INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8136, NULL, 1, 'Pantai Sanur', 'Bali', 'Jalan Hang Tuah, Denpasar Selatan, Denpasar, Bali', 'Pantai Sanur (bahasa Bali: ᬧᬲᬶᬄᬲᬦᬸᬃ, translit. Pasih Sanur), ejaan lama Sanoer, adalah salah satu pantai wisata yang ada di pulau Bali. Pantai ini terletak di timur Kotamadya Denpasar, tepatnya di kelurahan Sanur.', -8.6833333, 115.2666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20Pantai%20Sanur.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q1789991', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 27),
  (8137, NULL, 1, 'Pantai Lovina', 'Bali', 'Buleleng, Bali', 'Pantai Lovina atau Lovina adalah pesisir pantai yang terletak sekitar 9 km sebelah barat kota Singaraja. Daerah ini merupakan salah satu objek wisata yang ada di Bali Utara. Wisatawan banyak yang berkunjung ke sana, selain untuk melihat pantainya yang masih alami, juga untuk melihat aktivitas ikan lumba-lumba pada pagi hari yang banyak terdapat di pantai ini.', -8.1625028, 115.0256611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morning%20of%20Lovina%20Beach%20200507-6.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q1872519', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 22),
  (8138, NULL, 1, 'Pantai Senggigi', 'Lombok Barat', 'Senggigi, Lombok Barat, Nusa Tenggara Barat', 'Pantai Senggigi adalah salah satu tempat wisata pantai yang ada di sebelah barat Pulau Lombok, Provinsi Nusa Tenggara Barat, Indonesia. Pantai ini secara administratif berada di Desa Senggigi, Kecamatan Batu Layar, Kabupaten Lombok Barat.', -8.4997222, 116.0475, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/SenggigiHighSt1.JPG?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q1869598', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 12),
  (8139, NULL, 1, 'Medewi', 'Pekutatan', 'Pekutatan, Bali', 'Medewi adalah sebuah desa yang terletak di Kecamatan Pekutatan, Kabupaten Jembrana, Provinsi Bali, Indonesia.', -8.403, 114.8145, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balian%20Beach%20Sunset.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12497714', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 10),
  (8140, NULL, 1, 'Parangtritis', 'Parangtritis', 'Parangtritis, Bantul, Daerah Istimewa Yogyakarta', 'Pantai Parangtritis (bahasa Jawa: ꦥꦱꦶꦱꦶꦂ ꦥꦫꦁꦠꦿꦶꦠꦶꦱ꧀, translit. Pasisir Parangtritis) adalah tempat wisata yang terletak di Kalurahan Parangtritis, Kapanéwon Kretek, Kabupaten Bantul, Daerah Istimewa Yogyakarta. Jaraknya kurang lebih 29 km dari pusat kota.', -8.0166667, 110.35, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reflection%20of%20Parangtritis.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q105624140', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 9),
  (8141, NULL, 1, 'Pantai Pandawa', 'Badung', 'Kuta Selatan, Bali', 'Pantai Pandawa adalah salah satu tempat wisata di area Kecamatan Kuta Selatan, Kabupaten Badung, Bali. Pantai ini terletak di balik perbukitan dan sering disebut sebagai Pantai Rahasia (Secret Beach). Di sekitar pantai ini terdapat dua tebing yang sangat besar yang pada salah satu sisinya dipahat lima Patung Pandawa dan Kunti.', -8.845296, 115.186397, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pandawa%20Beach%2C%20Kuta%20Selatan%20-%20Bali.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746970', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 8),
  (8142, NULL, 1, 'Pantai Kuta', 'Kuta', 'Kuta, Bali', 'Pantai Kuta (bahasa Bali: Pasih Kuta, ᬓᭂᬘᬫᬢᬦ᭄ᬓᬸᬢ᭟) adalah salah satu pantai yang terletak di Kecamatan Kuta Selatan, Kabupaten Badung, Provinsi Bali, Indonesia. Pantai ini dikenal secara luas sebagai destinasi favorit bagi wisatawan mancanegara dan telah menjadi salah satu obyek wisata unggulan di Pulau Dewata sejak awal tahun 1970-an. Berhadapan langsung dengan Samudra Hindia, Pantai Kuta menawarkan panorama sunset yang sangat memukau dan menjadi kebalikan dari Pantai Sanur yang dikenal sebagai pantai sunrise.', -8.7208333, 115.1691667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Kuta%20sejuta%20cinta.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q7475907', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 7),
  (8143, NULL, 1, 'Pantai Padang', 'Padang', 'Jalan Samudra, Olo, Padang, Sumatera Barat', 'Pantai Padang atau populer dengan sebutan Taplau (singkatan dari tapi lauik, bahasa Minang yang artinya tepi laut) adalah sebuah pantai yang terletak di Kota Padang, Sumatera Barat. Pantai ini terletak pada kawasan padat perkotaan di Kecamatan Padang Barat, dan membentang dari daerah Purus hingga muara Batang Arau. Pantai ini berjarak kurang lebih 23 km dari Bandar Udara Internasional Minangkabau atau 30 menit perjalanan darat dengan mobil.', -0.9454722, 100.3513889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Quiet%20Water%20of%20Padang%20Beach%2C%20Bali.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746960', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 7),
  (8144, NULL, 1, 'Pantai Sembukan', 'Wonogiri', 'Wonogiri, Jawa Tengah', 'Pantai Sembukan (bahasa Jawa: ꦥꦱꦶꦱꦶꦂꦱꦼꦩ꧀ꦧꦸꦏꦤ꧀, translit. Pasisir Sembukan) adalah sebuah pantai di Desa Paranggupito, Kecamatan Paranggupito, Kabupaten Wonogiri, Jawa Tengah sekaligus menjadi salah satu tujuan wisata di Kabupaten Wonogiri. Pantai Sembukan juga merupakan salah satu objek wisata spiritual yang dilengkapi beberapa sarana ibadah antara lain masjid, paseban dan sanggar.', -8.2042, 110.8447, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Sembukan.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12502895', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 4),
  (8145, NULL, 1, 'Pantai Karangbolong', 'Indonesia', 'Cilacap, Kelurahan Cilacap Kecamatan Cilacap, Jawa Tengah', 'Pantai Karangbolong adalah sebuah pantai berpasir putih di pulau Nusakambangan di Kabupaten Cilacap, Jawa Tengah. Terletak di bagian paling timur pulau tersebut, pantai tersebut berada di dekat sebuah perbentengan Belanda kuno, yang juga dikenal sebagai Karang Bolong.', -7.76036, 109.042, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/West%20end%20of%20Karang%20Bolong%2C%20Nusakembangan%2C%20Cilacap%202015-03-21.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q20231077', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 4),
  (8146, NULL, 1, 'Pantai Balekambang', 'Jawa Barat', 'Jalan Batu Hiu, DUSUN PATROL DESA CIBENDA, Desa Ciliang, Jawa Barat', 'Pantai Balekambang adalah sebuah pantai di pesisir selatan yang terletak di tepi Samudra Indonesia secara administratif masuk wilayah Dusun Sumber Jambe, Desa Srigonco, Kecamatan Bantur, Kabupaten Malang, Jawa Timur dan merupakan salah satu wisata di Kabupaten Malang sejak 1985 hingga kini. Pantai ini berjarak sekitar 65 km dari pusat Kota Malang dan dapat ditempuh dalam waktu 2-3 jam. Daya tarik Balekambang adalah panorama alam, ombak yang tinggi, dan pasir pantai putih.', -7.6927778, 108.5372222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balekambang%20beach%2C%20Pura%20Amarta%20Jati%20in%20the%20middle%20of%20Ismoyo%20island.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q26737248', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 4),
  (8147, NULL, 1, 'Padang Padang Beach', 'Bali', 'Jalan Labuan Sait- Pecatu, Kuta Selatan, Bali', 'Padang Padang Beach adalah pantai di Bali.', -8.81114, 115.1012, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Padang%20Padang%20Beach%20Bali.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q125700900', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 4),
  (8148, NULL, 1, 'Pantai Amban', 'Amban', 'Jalan Petrus Kafiar Amban Pantai, Manokwari, Papua Barat', 'Pantai Amban adalah sebuah pantai di timur laut kepala Semenanjung Doberai, Provinsi Papua Barat, Indonesia. Pantai ini terletak 3 kilometer (1,9 mi) di sebelah utara desa Amban dan 7 kilometer (4,3 mi) di sebelah utara Manokwari. Dikelilingi hutan tropis dan rawa, pantai berpasir hitam ini merupakan tempat berselancar yang terkenal.', -0.8153889, 134.0793889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20amban.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q4741005', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8149, NULL, 1, 'Pantai Depok', 'Bantul', 'Parangtritis, Bantul, Daerah Istimewa Yogyakarta', 'Pantai Depok (bahasa Jawa: ꦥꦱꦶꦱꦶꦂꦝꦺꦥꦺꦴꦏ꧀, translit. Pasisir Dhépok) merupakan objek wisata pantai yang terletak di Kecamatan Kretek, Kabupaten Bantul, Daerah Istimewa Yogyakarta, sekitar tiga puluh kilometer di sebelah selatan Kota Yogyakarta. Pantai ini terkenal akan pasar ikannya yang ikannya merupakan hasil tangkapan nelayan Pantai Depok.', -8.0133611, 110.2893764, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Depok%20Beach.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12502834', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8150, NULL, 1, 'Pantai Widuri', 'Pemalang', 'Widuri, Pemalang, Jawa Tengah', 'Pantai Widuri adalah sebuah pantai yang terletak di Desa Widuri, Kabupaten Pemalang, Jawa Tengah.\nPantai Widuri adalah pantai yang terletak di desa Widuri maka itulah dinamakan Pantai Widuri dan masyarakat sekitar lebih mengenal dengan sebutan Cilincing. Desa Widuri terletak di kecamatan Pemalang, kabupaten Pemalang, Jawa tengah.', -6.8617241, 109.3778469, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Senja%20di%20Pantai%20Widuri.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12502913', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8151, NULL, 1, 'Pantai Clungup', 'Sitiarjo', 'Perumahan Rss, Kabupaten Malang, Jawa Timur', 'Pantai Clungup adalah sebuah pantai di pesisir selatan Pulau Jawa yang terletak di tepi Samudera Indonesia secara administratif berada di Desa Sitiarjo, Kecamatan Sumbermanjing Wetan, Kabupaten Malang, Jawa Timur.', -8.437536, 112.668603, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Clungup%20Indonesia.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746923', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8152, NULL, 1, 'Pantai Baron', 'Kemadang', 'Tanjungsari, Daerah Istimewa Yogyakarta', 'Pantai Baron (bahasa Jawa: ꦥꦱꦶꦱꦶꦂꦧꦫꦺꦴꦤ꧀, translit. Pasisir Baron) adalah salah satu objek wisata berupa pantai yang terletak di Kalurahan Kemadang, Kapanewon Tanjungsari, Kabupaten Gunungkidul. Lokasi Pantai Baron dapat ditempuh 40 km dari pusat kota Yogyakarta.', -8.129117, 110.549149, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baron%20Beach%20Gunung%20Kidul.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746920', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8153, NULL, 1, 'Pantai Menganti', 'Kebumen', 'Jalan Raya Ayah, Srati, Kebumen, Jawa Tengah', 'Pantai Menganti merupakan sebuah pantai yang berlokasi di Desa Karangduwur, Kecamatan Ayah, Kabupaten Kebumen, Jawa Tengah. Bentang alam pada Pantai Menganti terdiri dari perbukitan dan pasir putih. Sejak tahun 2011, Pantai Menganti menjadi tempat wisata dan selancar, sekaligus pelabuhan dan pelelangan ikan.', -7.7701944, 109.413, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Menganti%20dan%20Tebing.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19752364', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8154, NULL, 1, 'Pantai Glagah Indah', 'Indonesia', 'Glagah, Kulonprogo, Daerah Istimewa Yogyakarta', 'Pantai Glagah Indah adalah salah satu pantai yang menjadi objek wisata di provinsi Daerah Istimewa Yogyakarta dengan hamparan pasir yang berwarna hitam dan banyak mengandung pasir besi. Pantai Glagah Indah memiliki akses yang baik. Selain tidak jauh dari jalan provinsi, jalan menuju pantai dan jalan di sepanjang pantai Glagah sudah beraspal.', -7.91361, 110.06611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glagah%20Beach%20Kulon%20Progo.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q25080506', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8155, NULL, 1, 'Pantai Madale', 'Indonesia', 'Tegal Rejo, Sulawesi Tengah', 'Pantai Madale (bahasa Inggris: Madale Beach), adalah sebuah pantai yang terletak di Kabupaten Poso, Sulawesi Tengah, Indonesia, sekitar 5 kilometer (3,1 mi) timur laut dari kota Poso. Pantai ini dikelilingi oleh hutan tropis dan hutan mangrove, dan merupakan salah satu titik snorkeling yang terkenal. Rumah Katu Marine Park terletak disini.', -1.3544444, 120.8211111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Madale%20Beach%2C%20Poso%2C%202014.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q27148557', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8156, NULL, 1, 'Pantai Air Manis', 'Air Manis', 'Airmanis, Padang, Sumatera Barat', 'Pantai Air Manis (bahasa Minangkabau: Pantai Aia Manih) adalah pantai yang terletak kurang lebih 10 km ke selatan dari pusat Kota Padang. Lokasinya Berada di belakang Gunung Padang atau tepatnya di Kelurahan Air Manis, Kecamatan Padang Selatan, Kota Padang. Pantai ini merupakan salah satu tujuan wisata populer yang selalu ramai dikunjungi oleh masyarakat.', -0.9912745, 100.3606929, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20pantai%20air%20manis%20dari%20ketinggian.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q44041752', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8157, NULL, 1, 'Pantai Tanjung Aan', 'Indonesia', 'Pantaiaan, Lombok Tengah, Nusa Tenggara Barat', 'Pantai Tanjung Aan merupakan pantai berpasir putih yang terletak di Kawasan Ekonomi Khusus (KEK) Mandalika. Pantai Tanjung Aan berada di Desa Kuta, Kecamatan Pujut, Kabupaten Lombok Tengah, Provinsi Nusa Tenggara Barat.', -8.9095117, 116.328834, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BIRUNYA%20TANJUNG%20AAN.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q56392779', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8158, NULL, 1, 'Pantai Jumiang', 'Pademawu', 'Padelegan, Pamekasan, Jawa Timur', 'Pantai Jumiang (bahasa Madura: Pasèsèr Jhumèang) adalah salah satu pantai yang ada di Pulau Madura, letaknya ada di Desa Tanjung, Kecamatan Pademawu, Kabupaten Pamekasan, Provinsi Jawa Timur, Indonesia. Pantai Jumiang ini berhadapan langsung dengan Selat Madura, Pantai Jumiang menawarkan keindahan alam khas dengan penggabungan beberapa elemen-elemen unik dalam pantai tersebut. Pantai ini dikenal luas sebagai destinasi wisata dan tempat untuk melakukan penangkapan dan perdagangan ikan, Pantai Jumiang memiliki keindahan yang menawan disertai dengan hamparan pasir putih yang menghampar dengan tebing karang indah di sisi timurnya, dengan banyak macam spot foto yang menarik dan membuat pantai ini semakin terkenal, Pantai Jumiang ini juga menjadi tempat bagi nelayan nelayan lokal untuk memancing dan menangkap ikan sekaligus menjualnya kepada para masyarakat lokal atau bahkan mengimpornya keluar daerah.', -7.2327082, 113.5475737, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Jumiang%20Kabupaten%20Pamekasan%2004.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q139601150', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 3),
  (8159, NULL, 1, 'Pantai Jayanti', 'Indonesia', NULL, 'Pantai Jayanti adalah sebuah pantai yang terletak di Desa Cidamar, Kecamatan Cidaun, Kabupaten Cianjur, Jawa Barat. Pantai ini berdampingan dengan Cagar Alam Bojonglarang dan pelabuhan nelayan. Pantai ini masih alami, dengan ombak yang indah dan angin bertiup perlahan-lahan dan dapat menambah kenyamanan untuk berekreasi.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jayanti%20Beach%20Cianjur%20West%20Java%20Indonesia.JPG?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q10976659', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8160, NULL, 1, 'Pantai Batu Hiu', 'Indonesia', NULL, 'Pantai Batu Hiu merupakan salah satu tempat pariwisata yang berada di ibu kota Kabupaten Pangandaran. Batu hiu berjarak sekitar 14 km dari pangandaran sebagai objek wisata pilihan ketika Anda datang ke Pangandaran. Terletak di Desa Ciliang Kecamatan Parigi, kurang lebih 14 km dari Pangandaran ke arah selatan.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunset%20Batu%20Hiu.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q10981678', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8161, NULL, 1, 'Pantai Kejawanan', 'Indonesia', 'Lemahwungkuk, Cirebon, Jawa Barat', 'Pantai Kejawanan Cirebon adalah salah satu dari pantai yang berada di wilayah Kota Cirebon, Jawa Barat, Indonesia. Lokasi Pantai Kejawanan Cirebon dapat diakses oleh masyarakat umum. Pantai Kejawanan Cirebon dimanfaatkan sebagai pelabuhan, tempat pelelangan ikan dan wisata pantai.', -6.733613, 108.585791, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/%22%2Barya%2B%22%20pantai%20Kejawanan%20Cirebon%20-%20%EA%A6%8F%EA%A6%97%EA%A6%AE%EA%A6%A4%EA%A7%80%EA%A6%A4%EA%A6%A4%EA%A7%80%20-%202014%2001.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12502854', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8162, NULL, 1, 'Pantai Parai Tenggiri', 'Kepulauan Bangka Belitung', 'Bangka, Kepulauan Bangka Belitung', 'Pantai Parai Tenggiri adalah salah satu pantai yang terletak di Kecamatan Sungai Liat, Kabupaten Bangka, Kepulauan Bangka Belitung. Tepatnya berada di Desa Sinar Baru yang kira-kira berjarak 30 kilometer di sebelah utara kota Pangkalpinang. Pantai ini memiliki kontur tanah yang landai dengan ombak yang relatif kecil.', -1.804309, 106.128428, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Parai%20Tenggiri%20Bangka.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q12502880', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8163, NULL, 1, 'Pantai Serang', 'Blitar', 'Blitar Serang, Serang, Blitar, Jawa Timur', 'Pantai Serang merupakan sebuah pantai yang berada di Desa Serang, Kecamatan Panggungrejo, Kabupaten Blitar, Jawa Timur.\nPantai yang terletak kurang lebih 45 km sebelah tenggara Kota Blitar ini terdiri atas tiga kompleks pantai. Pantai utama merupakan tempat penyelenggaraan upacara larung sesaji setiap Tahun Baru Jawa, sedangkan pantai kedua dan ketiga yang berpasir putih terletak sebelah barat pantai utama dengan dibatasi perbukitan.', -8.330276, 112.221973, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/FT%20PANTAI%20SERANG%20BLITAR%20-%20panoramio.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q14917409', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8164, NULL, 1, 'Pantai Drini', 'Tanjungsari', 'Tanjungsari, Daerah Istimewa Yogyakarta', 'Pantai Drini adalah sebuah pantai yang menjadi objek wisata dan terletak di Desa Banjarejo, Kecamatan Tanjungsari, Gunungkidul, Yogyakarta. Indonesia. Letaknya di sebelah timur Pantai Baron dan berjarak sekitar 1 km ke arah timur Pantai Sepanjang akan tetapi, jarak sebenarnya yang harus ditempuh untuk sampai ke pantai ini sejauh 60 km atau sekitar 2-3 jam dari Kota Yogyakarta.', -8.1384283, 110.577506, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Drini%20Top%20View.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q18956305', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8165, NULL, 1, 'Pantai Lamaru', 'Kalimantan Timur', 'Balikpapan Timur, Balikpapan, Kalimantan Timur', 'Pantai Lamaru berada di wilayah Kota Balikpapan, provinsi Kalimantan Timur. Pantai ini merupakan objek wisata pantai yang terletak sekitar 5 km di sebelah timur dari Pantai Manggar Segara Sari, tepatnya di Jl. Mulawarman, Balikpapan Timur.', -1.1910832, 117.0067513, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Lamaru%20%2801%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q137803940', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8166, NULL, 1, 'Pantai Duta', 'Indonesia', 'Randutatah, Probolinggo, Jawa Timur', 'Pantai Duta adalah sebuah objek wisata pantai yang terletak di Desa Randutatah, Kecamatan Paiton, Kabupaten Probolinggo, Provinsi Jawa Timur, Indonesia. Pantai ini merupakan salah satu destinasi wisata pesisir yang cukup populer di wilayah timur Kabupaten Probolinggo, terutama saat akhir pekan dan hari libur.\nNama Pantai Duta berasal dari nama desa tempat pantai ini berada, yaitu Desa Randutatah.', -7.7040204, 113.4782957, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Duta%20Probolinggo.png?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q137868759', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8167, NULL, 1, 'Pantai Bentar', 'Gending', 'Gending, Jawa Timur', 'Pantai Bentar adalah destinasi wisata pantai yang terletak di Desa Curahsawo, Kecamatan Gending, Kabupaten Probolinggo, Provinsi Jawa Timur, Indonesia. Pantai ini dikenal sebagai salah satu objek wisata pesisir yang cukup populer di Kabupaten Probolinggo karena panorama alamnya, fasilitas wisata yang beragam, serta lokasinya yang strategis di jalur pantai utara Jawa (Pantura).\nPengelolaan kawasan wisata Pantai Bentar dilakukan oleh pemerintah desa bersama masyarakat setempat sebagai bagian dari pengembangan sektor pariwisata pesisir di Kabupaten Probolinggo.', -7.7794112, 113.2766803, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20wisata%20Pantai%20Bentar%20Probolinggo.png?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q137869022', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8168, NULL, 1, 'Pantai Goa China', 'Kabupaten Malang', 'Kabupaten Malang, Jawa Timur', 'Pantai Goa Cina adalah sebuah pantai di pesisir selatan yang terletak di Dusun Tumpak Awu, Desa Sitiarjo, Kecamatan Sumbermanjing Wetan, Kabupaten Malang, Jawa Timur. Nama asli dari pantai ini adalah Pantai Rowo Indah. Namun karena pernah terjadi peristiwa kematian seorang Tionghoa yang sedang bertapa di dalam goa yang ada di kawasan pantai ini, nama Rowo Indah diganti dengan Goa Cina karena lebih umum di masyarakat.', -8.4471565, 112.6537201, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Cina%20Beach.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746927', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8169, NULL, 1, 'Pantai Klayar', 'Pacitan', 'Pacitan, Jawa Timur', 'Pantai Klayar adalah sebuah pantai dengan pasir putih dan batu karang serta tebing-tebing batu yang mengelilingi. Pantai ini terletak di Pacitan, Jawa Timur dan berbatasan dengan Wonogiri, Jawa Tengah. Tepatnya berada di Desa Sendang, Kecamatan Donorojo, Kabupaten Pacitan, Provinsi Jawa Timur.', -8.2236944, 110.9474722, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klayar%20Beach%2C%20Pacitan%202009.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746934', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8170, NULL, 1, 'Pantai Ujung Pandaran', 'Indonesia', 'Ujung Pandaran, Kotawaringin Timur, Kalimantan Tengah', 'Pantai Ujung Pandaran adalah pantai yang terletak di Desa Ujung Pandaran, Kecamatan Teluk Sampit, Kabupaten Kotawaringin Timur, Provinsi Kalimantan Tengah. Letaknya berada di 80 km ke arah selatan dari pusat Kota Sampit.', -3.1652799, 113.0032404, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Camp%20Kobes%20Pantai%20Ujung%20Pandaran%20%2820230113%20154355%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19747018', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8171, NULL, 1, 'Pantai Trikora', 'Kepulauan Riau', 'Tanjung Ria, Jayapura, Papua', 'Pantai Trikora adalah salah satu pantai dengan pasir putih yang terletak di pulau Bintan, Kepulauan Riau, Indonesia. Pantai alami ini memiliki ombak yang landai dengan bebatuan-bebatuan indah di pantai. Sepanjang perjalanan menuju pantai Trikora, terdapat perkampungan nelayan yang berjajar rapi, beberapa resor-resor mewah, kawasan konservasi padang lamun, rumah makan seafood, hingga hutan mangrove.', -2.518788, 140.740378, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Trikora%201.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q20427037', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8172, NULL, 1, 'Pantai Botutonuo', 'Bone Bolango', 'Botutonuo, Bone Bolango, Gorontalo', 'Pantai Botutonuo adalah pantai yang berada di desa Botutonuo, Kabupaten Bone Bolango, Gorontalo. Letaknya di pesisir selatan Gorontalo menghadap ke Teluk Tomini. Pantai ini merupakan salah satu tujuan wisata utama bagi wisatawan lokal untuk mengisi liburan.', 0.4489444, 123.1256389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Botutonuo.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q25462884', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8173, NULL, 1, 'Pantai Nampu', 'Pacitan', 'Jalan Pantai Buyutan, Widoro, Pacitan, Jawa Timur', 'Pantai Nampu adalah sebuah objek wisata pantai yang terletak di pesisir bagian selatan Kabupaten Wonogiri, Jawa Tengah. Sebuah wisata pantai yang terletak di Dusun Gunturharjo, Kecamatan Paranggupito, Kabupaten Wonogiri ini menjadi salah satu tujuan destinasi wisata bagi wisatawan setempat maupun mancanegara. Dengan panorama pasir pantainya yang putih serta dihiasi dengan pandangan karang-karang yang indah membuat pantai ini menjadi salah satu objek wisata primadona di Wonogiri.', -8.2102, 110.9028, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Nampu.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q28724929', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8174, NULL, 1, 'Pantai Tanjung Kelayang', 'Belitung', 'Bangka, Kepulauan Bangka Belitung', 'Pantai Tanjung Kelayang adalah sebuah pantai yang terletak di Kepulauan Bangka Belitung. Lokasinya berada di Kecamatan Sijuk dan berjarak sekitar 27 kilometer dari Tanjung Pandan yang merupakan ibu kota Kabupaten Belitung.\nPantai ini memiliki puluhan batu granit raksasa, yang bentuknya sangat mirip dengan kepala burung garuda.', -1.80004, 106.121374, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kelayang%20beach%20Belitung%20March%202014%20%22%20-%20panoramio.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q31174026', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8175, NULL, 1, 'Pantai Pulau Merah', 'Indonesia', NULL, 'Pulau Merah atau Pulo Merah ( Red Island dalam Bahasa Inggris) adalah pariwisata di Indonesia wisata pantai yang terletak di Kecamatan Pesanggaran, Kabupaten Banyuwangi, Provinsi Jawa Timur. Di pantai ini terdapat sebuah bukit hijau kecil dengan tanah berwarna merah yang terletak di dekat bibir pantai. Bukit tersebut dapat dikunjungi dengan berjalan kaki saat air laut surut.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Merah.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q31174484', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8176, NULL, 1, 'Pantai Kukup', 'Tanjungsari', 'Tanjungsari, Daerah Istimewa Yogyakarta', 'Pantai Kukup (bahasa Jawa: ꦥꦱꦶꦱꦶꦂꦏꦸꦏꦸꦥ꧀, translit. Pasisir Kukup) adalah sebuah pantai di Desa Kemadang, Kecamatan Tanjungsari, Kabupaten Gunungkidul, Daerah Istimewa Yogyakarta, Indonesia. Pantai ini terletak di pesisir selatan Pulau Jawa dan menghadap langsung ke Samudra Hindia.', -8.1339167, 110.5548611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20di%20Pantai%20Kukup.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q98636702', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8177, NULL, 1, 'Pantai Kemala', 'Balikpapan', 'Balikpapan Kota, Balikpapan, Kalimantan Timur', 'Pantai Kemala berada di wilayah Kota Balikpapan, provinsi Kalimantan Timur. Pantai ini  terletak di pusat Kota Balikpapan, tepatnya di Jl. Jend.', -1.2810581, 116.8177196, NULL, 'Buka 24 jam', 'https://commons.wikimedia.org/wiki/Special:FilePath/2016-11-15%20Pantai%20Kemala%20Balikpapan.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q136458333', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8178, NULL, 1, 'Pantai Kenyamukan', 'Sangatta', 'Kenyamukan, Sangatta, Kalimantan Timur', 'Pantai Kenyamukan adalah salah satu pantai yang menjadi destinasi wisata di Kota Sangatta. Pantai Kenyamukan objek wisata bahari yang memikat di Kabupaten Kutai Timur Provinsi Kalimantan Timur.', 0.4870459, 117.6052057, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Kenyamukan%20%281%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q139859233', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8179, NULL, 1, 'Pantai Teluk Lingga', 'Sangatta', 'Sangatta, Kalimantan Timur', 'Pantai Teluk Lingga adalah nama Kelurahan di Kota Sangatta.Pantai ini dekat dengan pusat Kota Sangatta, lokasinya hanya berjarak lima kilometer dari kawasan Bukit Pelangi. Pantai ini hanya akan muncul pada sore hari atau lebih tepatnya pada pukul 15.30 Wita. Pantai Teluk Lingga memiliki nama lain yaitu Alien Mangrove Fish Santuary (AMFS).', 0.5036314, 117.619808, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Teluk%20Lingga%20%281%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q139859239', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8180, NULL, 1, 'Pantai Teluk Prancis', 'Singa Geweh', 'Sangatta, Kalimantan Timur', 'Pantai Teluk Prancis adalah kawasan objek wisata pantai yang berada di Kelurahan Singa Geweh, Kecamatan Sangatta Selatan, Kabupaten Kutai Timur, Provinsi Kalimantan Timur. Pantai ini dikenal dengan hamparan pasir putih dan lingkungan pesisir yang masih alami, serta kawasan mangrove yang dapat dijumpai dalam perjalanan menuju lokasi. Kawasan tersebut dimanfaatkan sebagai tempat rekreasi dengan berbagai kegiatan seperti menikmati pemandangan pantai, memancing, berenang, dan berkemah.', 0.3922808, 117.5678571, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Teluk%20Prancis%20%281%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q141175836', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (8181, NULL, 1, 'Pantai Pasir Panjang', 'Indonesia', 'Pasir Panjang, Singkawang Selatan, Singkawang, Kalimantan Barat', 'Pantai Pasir Panjang adalah objek wisata alam berupa pantai yang berpasir putih dan panjang yang terletak di Kecamatan Tujuh Belas, Kota Singkawang, Kalimantan Barat. Pantai ini membentang sepanjang 3 kilometer, sehingga dinamakan pantai Pasir Panjang. Pantai ini memiliki pasir putih yang cantik dan ombak yang tenang.', 0.8459483, 108.8796905, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pasir%20Panjang%20Beach%2C%20Singkawang%20City.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19730245', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8182, NULL, 1, 'Pantai Angsana', 'Tanah Bumbu', 'Tanah Bumbu, Kalimantan Selatan', 'Pantai Angsana adalah pariwisata pantai yang terletak di Kecamatan Angsana Tanah Bumbu, Kabupaten Tanah Bumbu, Kalimantan Selatan. Waktu perjalanan yang bisa ditempuh dengan waktu kurang lebih 5 jam perjalanan darat dari kota Banjarmasin. Tepatnya berada di belakang lokasi perkebunan kelapa sawit.', -3.771696, 115.587474, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/PantaiAngsanaPagiHari.jpeg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746906', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8183, NULL, 1, 'Pantai Ferdinand Waterpauw', 'Amban', 'Manokwari, Papua Barat', 'Pantai Ferdinand Waterpauw adalah salah satu destinasi wisata sekaligus sebagai venue voli pantai terbaik yang ada di kota Manokwari, Papua Barat. \nSelain itu, pantai ini digunakan juga sebagai tempat untuk ajang Kejuaraan Daerah maupun dalam ajang sirkuit nasional yang pertama kali di gelar di tanah papua. \nPantai ini dikerjakan hanya dalam waktu satu bulan dan mampu menampung hingga 530 orang penonton, dan juga dilengkapi fasilitas seperti pasir dengan kualitas terbaik dari pantai bakaro, penerangan, media center, dan ruang ganti sesuai standar internasional.', -0.8148551, 134.0831006, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Ferdinand%20Waterpauw.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q124714120', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8184, NULL, 1, 'Pantai Biru Kersik', 'Marang Kayu', 'Kersik, Kutai Kartanegara, Kalimantan Timur', 'Pantai Biru Kersik atau Pantai Biru Marangkayu berada di wilayah kabupaten Kutai Kartanegara, provinsi Kalimantan Timur. Pantai ini terletak di desa Kersik yang berjarak sekitar 10 km dari ibukota Kecamatan Marang Kayu dengan aksesibilitas yang cukup baik. Daya tarik dari pantai ini adalah pemandangan pantai yang indah.', -0.0624056, 117.4905328, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Biru%20Kersik%20Marang%20Kayu.JPG?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q136467533', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8185, NULL, 1, 'Pantai Sekerat', 'Kalimantan Timur', 'Sekerat, Kutai Timur, Kalimantan Timur', 'Pantai Sekerat: Pantai di Sekerat, Kutai Timur, Kalimantan Timur, Kalimantan Timur.', 0.7816541, 117.7899724, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Sekerat%20Bengalon.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q137803993', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8186, NULL, 1, 'Pantai Pagatan', 'Tanah Bumbu', 'Juku Eja, Tanah Bumbu, Kalimantan Selatan', 'Pantai Pagatan adalah destinasi wisata pantai yang terletak di Kecamatan Kusan Hilir, Kabupaten Tanah Bambu, Provinsi Kalimantan Selatan. Pantai Pagatan memiliki ombak yang tenang, sehingga cocok untuk berbagai aktivitas seperti berenang, bermain pasir, atau sekadar menikmati pemandangan matahari terbenam. Sekitar Pantai Pagatan, juga terdapat berbagai warung yang menjual makanan khas setempat, seperti ikan bakar dan hidangan laut segar.', -3.6125352, 115.9326749, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20siring%20pagatan%20-%20panoramio.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q19746964', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8187, NULL, 1, 'Pantai Akkarena', 'Tanjung Merdeka', 'Tamalate, Makassar, Sulawesi Selatan', 'Pantai Akkarena adalah pantai yang terletak di Kota Makassar, Sulawesi Selatan, Indonesia.Pantai Akkarena biasanya dijadikan pilihan sebagai tempat rekreasi bersama keluarga pada hari libur sebagai sarana bersantai, bermain, atau berolahraga. Akkarena dapat diartikan sebagai "tempat bermain". Pantai ini memiliki pasir yang berwarna hitam dan dikenal dengan matahari terbenamnya.', -5.1720025, 119.3886002, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Senja%20di%20Pantai%20Akkarena%2C%20Makassar%204.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q25459894', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8188, NULL, 1, 'Pantai Carolina', 'Bungus Selatan', 'Bungus Selatan, Padang, Sumatera Barat', 'Pantai Carolina adalah sebuah pantai yang terletak di Bungus Selatan, Bungus Teluk Kabung, Padang. Pantai ini berada sekitar 20 kilometer di sebelah selatan Kota Padang, Sumatera Barat, Indonesia. Lokasi ini dapat dicapai dari pusat kota Padang melalui jalur menuju Painan, Kabupaten Pesisir Selatan.', -1.0371649, 100.4082041, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Carolina.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q25464505', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8189, NULL, 1, 'Pantai Batu Karas', 'Batukaras', 'Cijulang Permai, Dusun Sanghiangkalang, Pangandaran, Jawa Barat', 'Pantai Batu Karas adalah salah satu objek wisata pantai yang ada di Kabupaten Pangandaran, tepatnya di Desa Batu Karas, Kecamatan Cijulang, Kabupaten Pangandaran, Provinsi Jawa Barat. Perjalanan menuju Pantai Batu Karas ini dapat ditempuh sekitar 30 menit dengan jarak 34 km dari Pantai Pangandaran. Sementara itu, apabila perjalanan dilakukan dari Jakarta akan menempuh sekitar 392 km ke arah tenggara, sedangkan apabila dari Bandung ke Batu Karas sekitar 197 km ke arah tenggara.', -7.73737, 108.4975978, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunrise%20Batu%20karas%20Pangandaran.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q25465265', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8190, NULL, 1, 'Pantai Sungai Suci', 'Indonesia', 'Bengkulu Tengah, Bengkulu', 'Pantai Sungai Suci adalah Objek wisata yang terletak di Desa Pasar Pedati, Kecamatan Pondok Kelapa, Kabupaten Bengkulu Tengah. yang kawasannya terbentang sepanjang 2Km, Objek wisata ini berjarak 15Km dari pusat Kota Bengkulu atau sekita 25Km dari Bandar Udara Fatmawati Soekarno.[1] Diarsipkan 2016-11-16 di Wayback Machine meskipun nama nya Pantai Sungai Suci Objek wisata ini tidak terdapat Sungai seperti namanya\nSelain menjadi tempat objek wisata Pantai Sungai Suci ini juga merupakan salah satu lokasi mencari batu akik [2], di Pantai Sungai Suci ini juga terdapat Pulau kecil juga yang bisa di seberangin dengan Jembatan gantung, yang terbuat dari tali tambang yang kuat dan dasar Jembatan terbuat dari potongan papan kayu yang tebal.', -3.719546, 102.235571, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20sungai%20suci.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q28725154', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8191, NULL, 1, 'Pantai Tirtamaya', 'Indonesia', NULL, 'Pantai Tirtamaya (aksara Sunda: ᮕᮔ᮪ᮒᮄ ᮒᮤᮁᮒᮙᮚ) adalah salah satu pantai yang berada di Kabupaten Indramayu, Provinsi Jawa Barat, pantai ini berada di Kecamatan Juntinyuat. Pantai ini sangat populer di wilayah Kabupaten Indramayu, untuk transportasi menuju pantai ini kita bisa menggunakan mobil, motor, dan kendaraan lainnya, untuk biaya masuk Pantai Tirtamaya tidak dikenakan biaya apapun, kecuali fasilitasnya.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tirtamaya.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q28725214', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8192, NULL, 1, 'Pantai Siuri', 'Indonesia', NULL, 'Pantai Siuri (bahasa Inggris: Siuri Beach), adalah sebuah pantai yang terletak di Kabupaten Poso, Sulawesi Tengah, Indonesia, di tepi Danau Poso. Pantai ini terletak 17 km dari kota Tentena. Di sini terdapat beberapa tempat penginapan, yang pada umumnya digunakan oleh wisatawan asing.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tentena%20Danau%20Poso%20Siuri%20Beach.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q31173115', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8193, NULL, 1, 'Pantai Liang', 'Maluku Tengah', 'Batudua, Maluku Tengah, Maluku', 'Pantai Liang merupakan pantai yang terletak di Negeri Liang, 40 km ke sebelah timur laut pusat Kota Ambon.\nPantai Liang atau yang mempunyai nama lain Pantai Hunimua memiliki hamparan pasir putih dipadukan dengan air yang cukup jernih berwarna kebiruan, yang membuatnya menjadi salah satu objek wisata di Maluku Tengah. Di sana, pengunjung dapat melakukan berbagai kegiatan atau rangkaian aktivitas karena ombak Pantai Liang cukup tenang.', -3.5058582, 128.3439679, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dermaga%20Desa%20Liang.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q45337232', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8194, NULL, 1, 'Pantai Nguyahan', 'Kanigoro', 'Jalan Pantai Gesing, Panggang, Daerah Istimewa Yogyakarta', 'Pantai Nguyahan adalah pantai berpasir putih yang terletak di Desa Kanigoro, Kecamatan Saptosari, Kabupaten Gunungkidul, Daerah Istimewa Yogyakarta, Indonesia. Pantai ini berada di sebelah barat Pantai Ngobaran dan dikenal karena keindahan panorama alamnya yang masih asri. Dahulu, lokasi Pantai Nguyahan berada di balik perbukitan, hingga kemudian masyarakat setempat membuka akses jalan untuk memudahkan pengunjung menuju pantai ini.', -8.1184767, 110.5030666, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20Pantai%20Nguyahan.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q65212356', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8195, NULL, 1, 'Pantai Wayob', 'Fakfak', 'Fakfak, Papua Barat', 'Pantai Wayob adalah salah satu pantai di Kabupaten Fakfak Papua Barat Indonesia. Letaknya di Pulau Panjang dan menjadi salah satu destinasi wisata pantai di Kota Fakfak. Pantai Wayob memiliki ekosistem yang terdiri dari ekosistem mangrove, lamun dan terumbu karang yang masih alami dengan kondisi sangat baik.', -2.9774537, 132.2231664, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sisi%20Lain%20Pantai%20Wayob%20di%20Pulau%20Panjang%20Fakfak%20%28doc.Aldi%20Bimantara%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q97455368', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8196, NULL, 1, 'Pantai Baru', 'Kotabaru', 'Pantai Baru, Kotabaru, Kalimantan Selatan', 'Pantai Baru (bahasa Jawa: ꦥꦱꦶꦱꦶꦂ ꦧꦫꦸ, translit. Pasisir Baru) adalah objek wisata pantai yang terletak di Dusun Ngentak, Desa Poncosari, Kecamatan Srandakan, Kabupaten Bantul, Daerah Istimewa Yogyakarta. Pantai ini terletak berdekatan dengan Pantai Pandansimo, Pantai Kuwaru, dan Pantai Goa Cemara.', -3.0898895, 116.1554672, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Baru.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q105653188', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8197, NULL, 1, 'Pantai Muara Mbaduk', 'Indonesia', 'Kandangan, Banyuwangi, Jawa Timur', 'Pantai Muara Mbaduk atau populer disebut Pantai Mumba (dulunya bernama Pandansari) adalah sebuah pantai yang terletak di Desa Sarongan, Kecamatan Pesanggaran, Banyuwangi, Jawa Timur. Pantai ini terletak di muara Sungai Buyuk, sungai yang melintasi Desa Sarongan dan Desa Kandangan atau di barat Pantai Rajegwesi. Pantai ini memiliki lanskap air sungai yang mengalir di muara yang dilatar belakangi perbukitan yang tersusun dari batu karang.', -8.5652778, 113.9588889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pos-tniau-sarongan-pesanggaran-banyuwangi.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q109435882', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8198, NULL, 1, 'Pantai Sungai Bakau', 'Indonesia', NULL, 'Pantai Muara Sungai Bakau atau hanya Pantai Sungai Bakau (alias Pantai sei bakau) adalah sebuah pantai yang terletak di Kabupaten Seruyan, Kalimantan Tengah, Indonesia.\nObjek wisata pantai ini mulai dibangun sejak terpilihnya bupati pertama Seruyan Darwan Ali, dan masih terus dikembangkan hingga saat ini.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sungai%20Bakau.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q112859539', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8199, NULL, 1, 'Pantai Indah Modisi', 'Modisi', 'Jalan Pantai, Modisi, Bolaang Mongondow Selatan, Sulawesi Utara', 'Pantai Indah Modisi adalah sebuah pantai dan tempat wisata yang terletak di Desa Modisi, Kabupaten Bolaang Mongondow Selatan, Sulawesi Utara. Jaraknya kurang lebih 50 km dari pusat Kabupaten Bolaang Mongondow Selatan. Pantai ini menjadi salah satu destinasi wisata terkenal di Sulawesi Utara dan telah menjadi ikon pariwisata di Sulawesi Utara.', 0.44848, 124.431639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Indah%20Modisi.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q115057357', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8200, NULL, 1, 'Pantai Kelingking', 'Bunga Mekar', 'Nusa Penida, Bali', 'Pantai Kelingking: Pantai di pulau Bali, Bunga Mekar.', -8.7503708, 115.4726151, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wonderfull%20Nusa%20Penida.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q116688420', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8201, NULL, 1, 'Pantai Tanjung Kolomboy', 'Indonesia', NULL, 'Pantai Tanjung Kolomboy adalah pantai yang terletak di antara Desa Mayayap, dan Desa Toiba, Bualemo, Kabupaten Banggai, Sulawesi Tengah.\nPantai Tanjung Kolomboy berjarak 37 km dari Desa Mayayap dan memiliki pantai berpasir putih dengan kekayaan hayati biota bawah laut. Daerah tersebut memiliki iklim tropis, dengan suhu rata-ratanya adalah 24 °C. Bulan terpanas adalah Oktober, yaitu pada suhu 26 °C, dan Maret adalah bulan terdingin, yaitu pada suhu 21 °C. Curah hujan rata-ratanya adalah 2,092 milimeter per tahun.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Beach%205%20%28209595709%29.jpeg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q121597045', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8202, NULL, 1, 'Pantai Tuing', 'Indonesia', 'Riau, Bangka, Kepulauan Bangka Belitung', 'Pantai Tuing atau dikenal dengan nama Pantai Tuing Jaya, Pantai Tuing Indah adalah sebuah objek wisata yang terletak di Desa Mapur, Pulau Bangka, Kepulauan Bangka Belitung. Objek wisata ini dibuka pertama pada tahun 2019, dilengkapi dengan fasilitas penginapan dan restoran. Saat ini Pantai Tuing berada dalam wilayah Kesatuan Pengelolaan Hutan Produksi (KPHP) Bubus Panca.', -1.6626919, 105.9865223, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Tuing%20Bangka%20Island.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q121597053', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
  (8203, NULL, 1, 'Pantai Suluban', 'Bali', 'Jalan Pantai Suluban, Kuta Selatan, Bali', 'Pantai Suluban adalah pantai di Bali.', -8.8163889, 115.0883333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jl.%20Pantai%20Suluban%2C%20Pecatu%2C%20Kuta%20Sel.%2C%20Kabupaten%20Badung%2C%20Bali%2080361%2C%20Indonesia%20-%20panoramio.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q26751679', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 1),
