  (8218, NULL, 1, 'Modisi Beach', 'Sulawesi Utara', 'Modisi Dua, Bolaang Mongondow Selatan, Sulawesi Utara', 'Modisi Beach adalah pantai di Sulawesi Utara.', 0.44718, 124.41866, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modisi%20Beach.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q114828145', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
