  (8220, NULL, 1, 'Crystal Bay Beach', 'Bali', 'Nusa Penida, Bali', 'Crystal Bay Beach adalah pantai di Bali.', -8.71526, 115.45904, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Still%20feeling%20a%20bit%20shaky%20on%20Crystal%20Bay%20Beach%20after%20my%20rip%20current%20encounter%20%2852461727167%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q123511638', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (8221, NULL, 1, 'Bingin Beach', 'Pecatu', 'Kuta Selatan, Bali', 'Bingin Beach adalah pantai di Pecatu.', -8.80566, 115.11307, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bingin%20Beach.PNG?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q124343204', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (8222, NULL, 1, 'Green Bowl Beach', 'Ungasan', 'Jalan Raya Bali Cliff, Kuta Selatan, Bali', 'Green Bowl Beach adalah pantai di Ungasan.', -8.8487221, 115.1709357, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Green%20Bowl%20Beach%20%2815238737765%29.jpg?width=800', '2026-11-04 09:37:20', '2026-11-24 23:32:50', 'wd:Q124344622', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (8223, NULL, 2, 'Gunung Kelud', 'Jawa Timur', 'Blitar, Jawa Timur', 'Gunung Kelud (dalam aksara jawa: ꦒꦸꦤꦸꦁꦏꦼꦭꦸꦠ꧀) adalah sebuah gunung berapi di Jawa Timur yang hingga sekarang tergolong aktif. Gunung ini berada di perbatasan antara Kabupaten Kediri, Kabupaten Blitar, dan Kabupaten Malang. Lokasinya kira-kira 45 km sebelah timur pusat Kota Kediri dan 35 km sebelah utara pusat Kota Blitar.', -7.9389217, 112.3052492, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kelud%20eruption%202014%20ash%20in%20Yogyakarta.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q513216', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 39),
  (8224, NULL, 2, 'Gunung Kelimutu', 'Nusa Tenggara Timur', 'Ende, Nusa Tenggara Timur', 'Gunung Kelimutu adalah gunung berapi yang terletak di Pulau Flores, Provinsi NTT, Indonesia. Lokasi gunung ini tepatnya di Desa Pemo, Kecamatan Kelimutu, Kabupaten Ende. Gunung ini memiliki tiga buah danau Diarsipkan 2017-03-04 di Wayback Machine kawah di puncaknya.', -8.77, 121.82, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kelimutu%202007-07-21.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q1738211', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 35),
  (8225, NULL, 2, 'Gunung Batur', 'Bali', 'Kintamani, Bali', 'Gunung Batur adalah sebuah gunung berapi kerucut aktif di Kecamatan Kintamani, Kabupaten Bangli, Bali, Indonesia. Sisi tenggara dari kaldera yang berukuran 10×13 km ini sebagian besar berisi danau kaldera. Baik kaldera yang lebih besar, dan kaldera yang lebih kecil 7,5 km dibentuk oleh runtuhnya ruang magma gunung , keruntuhan lebih besar pertama terjadi sekitar 29.300 tahun yang lalu, dan kaldera bagian dalam runtuh kedua kalinya sekitar 20.150 tahun yang lalu.', -8.2419444, 115.375, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Batur2.JPG?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q43876', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 31),
  (8226, NULL, 2, 'Gunung Dukono', 'Maluku Utara', 'Halmahera Utara, Maluku Utara', 'Gunung Dukono terletak di utara Pulau Halmahera. Gunung Dukono terdiri dari beberapa kawah berapi dengan aktivitas tinggi. Pada letusan pada tahun 1550, letusan lava mengisi selat di antara Pulau Halmahera dan lereng utara dari Gunung Mamuya.', 1.6991667, 127.8783333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mt%20Dukono.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2340739', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 24),
  (8227, NULL, 2, 'Gunung Muria', 'Jawa Tengah', 'Tempur, Jepara, Jawa Tengah', 'Gunung Muria adalah sebuah gunung bertipe stratovolcano, yang terletak di pantai utara Jawa Tengah, sekitar 66 kilometer di timur laut Kota Semarang. Gunung ini termasuk ke dalam wilayah Kota Jepara di sisi barat, wilayah Kota Kudus di sisi selatan, dan wilayah Kota Pati di sisi timur. Gunung ini memiliki ketinggian 1606 mdpl, tetapi sumber lain menyebutkan bahwa tingginya 1625 mdpl.', -6.6166667, 110.8833333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Muria.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q3217435', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8228, NULL, 2, 'Gunung Guntur', 'Jawa Barat', 'Leles, Garut, Jawa Barat', 'Gunung Guntur (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮌᮥᮔ᮪ᮒᮥᮁ) adalah gunung berapi kerucut aktif yang terdapat di Kelurahan Pananjung dan Desa Pasawahan, Tarogong Kaler, Kabupaten Garut, Jawa Barat, dan memiliki ketinggian 2.249 meter dpl.\nGunung Guntur berdekatan dengan gunung-gunung lainya yang mengelilingi kota Garut. Di sebelah selatan Gunung Guntur, ada Gunung Putri yang berhadapan dengan Gunung Cikuray dan Gunung Papandayan, kemudian di sebelah barat ada Gunung Masigit, Gunung Parupuyan, dan gunung lainnya.', -7.1433333, 107.8397222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Guntur.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2735753', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8229, NULL, 2, 'Gunung Talamau', 'Sumatera Barat', 'Simpang Empat, Sumatera Barat', 'Gunung Talamau adalah gunung tertinggi di Sumatera Barat yang terletak di Kabupaten Pasaman dan Kabupaten Pasaman Barat, berdampingan dengan Gunung Pasaman. Gunung ini memiliki ketinggian 2,920 meter dan termasuk dalam tipe gunung api tidak aktif.\nDi bawah puncak gunung pada ketinggian sekitar 2.750 m, terdapat 13 telaga.', 0.0791667, 99.9833333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Talakmau.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2740999', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 17),
  (8230, NULL, 2, 'Gunung Kie Besi', 'Indonesia', 'Tafasoho (matekente), Halmahera Selatan, Maluku Utara', 'Gunung Kie Besi atau Gunung Makian adalah sebuah gunung berapi stratovolcano yang terletak di Pulau Makian sebelah barat Pulau Halmahera, Indonesia. Gunung ini secara administratif berada di Kecamatan Pulau Makian, Kabupaten Halmahera Selatan, Provinsi Maluku Utara. Karakter letusan Gunung yang memiliki luas 113,12 km² ini umumnya bersifat eksposif, efusif serta freatomagmatik.', 0.3333333, 127.3666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Makian%20volcano.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q587915', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 16),
  (8231, NULL, 2, 'Gunung Sirung', 'Alor', 'Alor, Nusa Tenggara Timur', 'Gunung Sirung adalah gunung berapi aktif yang terletak di Pulau Pantar yang terletak di Kepulauan Alor yang berada di timur Provinsi Nusa Tenggara Timur. Lereng Gunung Sirung dapat dicapai dengan mudah dari desa di Kampung Kakamauta, Desa Mauta, Kecamatan Pantar Tengah, Kabupaten Alor. Dalam kawah Gunung Sirung terdapat sulfur di Danau kawah dan mengeluarkan sulfur dari lubang-lubang gunung.', -8.5166667, 124.1333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Sirung%20caldera.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q1322666', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8232, NULL, 2, 'Gunung Telomoyo', 'Semarang', 'Dalangan, Magelang, Jawa Tengah', 'Gunung Telomoyo (bahasa Jawa: Télåmåyå, Han.: ꦒꦸꦤꦸꦁꦠꦺꦭꦩꦪ) adalah gunung yang terletak di Desa Pandean, Kecamatan Ngablak, Kabupaten Magelang. Gunung ini memiliki ketinggian 1.894 mdpl dan merupakan gunung api yang berbentuk strato (kerucut) tetapi belum pernah tercatat meletus. Gunung Telomoyo dapat terlihat dari kota-daerah lain di sekitarnya, seperti Kota Salatiga, Kecamatan Ambarawa di Kabupaten Semarang dan Kecamatan Grabag di Kabupaten Magelang.', -7.37, 110.4, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Road%20to%20the%20summit%20of%20Mount%20Telomoyo.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q123157', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8233, NULL, 2, 'Gunung Wayang', 'Bandung', 'Kabupaten Bandung, Jawa Barat', 'Gunung Wayang merupakan gunung berapi kembar yang terdiri dari Gunung Wayang dan Gunung Windu. Terletak di sebelah timur kota Pangalengan di Kabupaten Bandung di Jawa Barat, Indonesia, sekitar 40 km sebelah selatan dari Kota Bandung. Daerah ini telah menjadi proyek panas bumi aktif.', -7.208, 107.63, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Gezicht%20op%20de%20Gunung%20Wayang%20en%20de%20Gunung%20Windu%20vanaf%20kina-%20en%20theeplantage%20Lodaja%20TMnr%2060016822.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2854575', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 14),
  (8234, NULL, 2, 'Bratan', 'Bali', 'Sukasada, Bali', 'Gunung Bratan adalah sebuah komplek gunung kaldera yang berada di Bali, Indonesia. Komplek ini memiliki luas sebesar 11 × 6 km.', -8.2833333, 115.1333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bratan.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2003801', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 14),
  (8235, NULL, 2, 'Gunung Ine Lika', 'Nusa Tenggara Timur', 'Wololika, Ngada, Nusa Tenggara Timur', 'Gunung Ine Like (Inielika) adalah gunung yang berada di Kabupaten Ngada, Pulau Flores, Nusa Tenggara Timur (NTT). Para penduduk di enam desa di sekitar gunung Ine Like mengungsi ketika gunung tersebut meletus pada 2001. Mereka mendiami lereng gunung, yaitu: Desa Ine Like, Wololika, Tarawaja, Piga, Tarawali, Naru.', -8.73, 120.98, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Flores%20Bajawa%20red%20lakes.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2352524', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8236, NULL, 2, 'Gunung Iliwerung', 'Nusa Tenggara Timur', 'Lerek, Lembata, Nusa Tenggara Timur', 'Gunung Iliwerung adalah gunung berapi yang terletak di bagian selatan dari Pulau Lembata, Kabupaten Lembata, Provinsi Nusa Tenggara Timur, Indonesia. Gunung Iliwerung merupakan kubah terbuka Gunung Ile Adowajo sebelum gunung besar dengan ketinggian lebih dari 1.000 Mdpl ini meletus hebat dan sebagian runtuh di sisi tenggaranya pada waktu yang tidak diketahui. Sisa-sisa puncak gunung ini berada di utara Gunung Ilewerung yang dikenal dengan Gunung Mauraja sedangkan Gunung Ile Adowajo hanya menjadi 300 Mdpl.', -8.5322222, 123.5733333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Iliwerung%20lava%20dome.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2483640', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13),
  (8237, NULL, 2, 'Iyang-Argapura', 'Indonesia', 'Probolinggo, Jawa Timur', 'Gunung Argapura (sering dieja Gunung Argopuro) adalah sebuah gunung berapi kompleks yang terdapat di Jawa Timur, Indonesia. Gunung Argapura mempunyai ketinggian setinggi 3.088 meter. Gunung Argapura merupakan bekas gunung berapi yang kini sudah tidak aktif lagi.', -7.97, 113.57, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Iyang-Argapura.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2549314', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13),
  (8238, NULL, 2, 'Poco Ranaka', 'Manggarai Timur', 'Rondo Woing, Manggarai Timur, Nusa Tenggara Timur', 'Gunung Ranakah atau Poco Ranakah adalah gunung berapi yang terletak di bagian tengah selatan pulau Flores, Indonesia. Kubah lava tertingginya, Gunung Poco Mandasawu adalah gunung tertinggi di pulau ini. Kubah lava baru yang diberi nama "Anak Ranakah" terbentuk di sana pada tahun 1987.', -8.63664, 120.53095, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anak%20Ranakah.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2901375', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13),
  (8239, NULL, 2, 'Sangeang Api', 'Nusa Tenggara Barat', 'Bima, Nusa Tenggara Barat', 'Gunung Sangeang Api atau Sangiang merupakan gunung berapi aktif di kompleks pulau Sangeang di Indonesia. Ini terdiri dari dua kerucut vulkanik, Doro Api 1.949 meter (6.394 kaki) dan Doro Mantoi 1.795 m (5.889 ft). Sangeang Api merupakan salah satu gunung berapi paling aktif di Kepulauan Sunda Kecil.', -8.18, 119.05, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%20-%20Sangeang%20Api.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2573663', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 12),
  (8240, NULL, 2, 'Gunung Kaba', 'Pematang Danau', 'Kepahiang, Bengkulu', 'Gunung Kaba (Rejang: [Têbo Kabêak] Galat: {{Lang}}: text has italic markup (bantuan)) adalah gunung berapi aktif yang terletak di Selupu Rejang, Kabupaten Rejang Lebong, Provinsi Bengkulu, Indonesia. Dari Kota Curup, gunung ini berada di sebelah tenggara dengan jarak sekitar 15 km.\nMulanya, Lokasi disekitar Gunung Kaba merupakan salah satu cagar alam untuk perlindungan bunga Rafflesia.', -3.52, 102.62, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Kaba.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q150081', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 12),
  (8241, NULL, 2, 'Gunung Kamojang', 'Jawa Barat', 'Mekarwangi, Kabupaten Bandung, Jawa Barat', 'Gunung Kamojang (dikenal luas dengan nama Kawah Kamojang) merupakan sumber panas bumi yang terletak di Jawa Barat, Indonesia. Dalam sejarahnya, dikenal sebagai bagian dari gunung berapi yang bernama Gunung Guntur, tetapi kawah ini dikelompokkan ke dalam gunung berapi aktif tersendiri karena aktivitas panas buminya.', -7.125, 107.8, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Badhuizen%20bij%20zwavelbaden%20in%20een%20oude%20kraterbodem%20van%20Kawah%20Kamodjang%20op%20de%20vulkaan%20Goentoer%20West-Java%20TMnr%2010007433.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2181214', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 11),
  (8242, NULL, 2, 'Gunung Pulosari', 'Banten', 'Mandalawangi, Banten', 'Gunung Pulosari adalah gunung berapi bertipe Stratovolcano yang berada di Kabupaten Pandeglang, Banten, Bagian Barat pulau Jawa Indonesia. Saat ini status gunung ini adalah gunung berapi yang mati karena tidak adanya aktivitas Letusan, tetapi masih terdapat aktivitas fumarol yang terjadi di dinding kaldera dengan kedalaman 300 meter.\nMenurut Sajarah Banten, sesampai di Banten Girang, Sunan Gunung Jati dan putranya, Hasanuddin, mengunjungi Gunung Pulosari yang saat itu merupakan tempat keramat bagi kerajaan.', -6.3416667, 105.9783333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung-pulosari-1.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q42118', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 11),
  (8243, NULL, 2, 'Gunung Butak', 'Malang', 'Jalur pendakian Gunung Butak via Panderman, Sukun, Kota Batu, Jawa Timur', 'Gunung Butak (bahasa Jawa: ꦒꦸꦤꦸꦁꦧꦸꦸꦛꦏ꧀, translit. Gunung Buthak) adalah sebuah gunung berapi kerucut yang terletak di perbatasan Kabupaten Malang dan Kabupaten Blitar dalam wilayah  Provinsi Jawa Timur, Indonesia. Gunung Butak merupakan bagian dari Pegunungan Kawi.', -7.92, 112.45, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kawi-Butak.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q126589', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 8),
  (8244, NULL, 2, 'Dataran Malang', 'Indonesia', 'Tajinan, Jawa Timur', 'Gunung Dataran Malang adalah kumpulan sembilan kerucut, maar, dan sumbat vulkanis. Dataran ini terletak di sekitar kota Malang, mulai dari tenggara sampai timur laut, di Jawa Timur, Indonesia. Beberapa kerucut vulkanis diduga merupakan kerucut parasit dari kompleks Kaldera Tengger.', -8.02, 112.68, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Olieverfschilderij%20voorstellende%20rivierlandschap%20bij%20Malang%20TMnr%20H-3279.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2786660', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 7),
  (8245, NULL, 2, 'Gunung Welirang', 'Jawa Timur', 'Pacet, Jawa Timur', 'Gunung Welirang (bahasa Jawa: ꦒꦸꦤꦸꦁꦮꦼꦭꦶꦫꦁ, "gunung belerang") adalah sebuah gunung berapi aktif tipe stratovolcano dengan ketinggian 3.156 mdpl. Secara administratif, gunung ini terletak di perbatasan Kota Batu, Kabupaten Pasuruan, dan Kabupaten Mojokerto, Jawa Timur. Gunung Welirang termasuk dalam kawasan Taman Hutan Raya Raden Soerjo dan sering dikaitkan dengan gunung tetangganya, Gunung Arjuno, sehingga kompleksnya dikenal sebagai Arjuno-Welirang.', -7.7325, 112.5747222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Gezicht%20op%20de%20vulkaan%20Welirang%20vanaf%20de%20Widodaren%20TMnr%2010023577.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q2011834', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 7),
  (8246, NULL, 2, 'Gunung Toba', 'Indonesia', 'Samosir, Sumatera Utara', 'Gunung Toba adalah gunung berapi supervulkan purba yang terletak di Provinsi Sumatera Utara. Gunung ini diperkirakan meletus terakhir sekitar 74.000 tahun lalu, yang membentuk kaldera berukuran besar yang diisi oleh air, yang saat ini dikenal sebagai Danau Toba. Toba merupakan satu-satunya supervulkan yang ada di Indonesia.', 2.616667, 98.816667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Toba%20zoom.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q17191410', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 4),
  (8247, NULL, 2, 'Gunung Ophir', 'Sumatera Barat', 'Pasaman, Sumatera Barat', 'Mount Ophir  (, terj. \'Gunung Ophir\'; disebut juga sebagai Gunong Passama dalam beberapa sumber) adalah sebuah gunung nyata yang berlokasi di dekat garis khatulistiwa yang mana sering kali disebutkan dalam naskah-naskah kuno yang bersejarah (utamanya sejak masa Solomon, atau dalam keimanan Islam dikenali sebagai Sulaiman). Lokasi dari Mount Ophir dulunya menjadi misteri dan perdebatan panjang oleh beberapa ahli karena minimnya sarana dan prasarana penelitian dan penelusuran pada zaman dahulu, tetapi dengan berkembangnya zaman berdasarkan para ahli yang kini dapat menelusuri data-data pada peta-peta kuno yang dikumpulkan dari seluruh belahan dunia, lokasi dari Mount Ophir yang kontroversial ini dapat dipastikan berlokasi di wilayah Sumatera Barat, yang secara detailnya yakni dekat dengan daerah Kabupaten Pasaman.', 0.0791667, 99.9833333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/1228%20of%20%27G%C3%A9ographie%20g%C3%A9n%C3%A9rale%3B%20physique%2C%20politique%20et%20%C3%A9conomique.%20...%20Avec%20...%20cartes%20...%20gravures%2C%20etc%27%20%2811112135594%29.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q113372328', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 4),
  (8248, NULL, 2, 'Kawi-Butak', 'Indonesia', 'Blitar, Jawa Timur', 'Kawi-Butak adalah gunung berapi di Indonesia.', -7.92, 112.45, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/RIMtButakMtKawi.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q11737565', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 3),
  (8249, NULL, 2, 'Barujari', 'Lombok Timur', 'Lombok Timur, Nusa Tenggara Barat', 'Barujari adalah gunung berapi di Lombok Timur.', -8.4112936, 116.4221044, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung-baru-jari.jpg?width=800', '2026-11-04 09:37:28', '2026-11-24 23:32:50', 'wd:Q109017289', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung berapi', 2),
  (8250, NULL, 2, 'Puncak Jaya', 'Mimika', 'Mimika, Papua Tengah', 'Puncak Jaya (bahasa Amungkal: Nemangkawi Ninggok) adalah puncak tertinggi yang menjadi bagian dari Pegunungan Barisan Sudirman yang terdapat di Kabupaten Mimika, Provinsi Papua Tengah, Indonesia. Puncak Jaya atau Piramida Carstensz mempunyai ketinggian 4.884 mdpl dan di sekitarnya terdapat gletser dengan nama yang sama yakni gletser Carstensz, satu-satunya gletser tropika di Indonesia, yang tersisa dan secara perlahan mulai menipis akibat pemanasan global.\nPuncak ini merupakan gunung tertinggi di Indonesia dan ke-7 tertinggi di Asia Tenggara.', -4.0833333, 137.1833333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncakjaya.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1045888', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 77),
  (8251, NULL, 2, 'Gunung Tambora', 'Bima', 'Bima, Nusa Tenggara Barat', 'Gunung Tambora atau Tomboro adalah stratovulkano aktif di Nusa Tenggara Barat, Indonesia. Terletak di Sumbawa di kawasan Kepulauan Nusa Tenggara, aktivitas vulkanis gunung ini merupakan hasil dari zona subduksi. Letusan tahun 1815 merupakan letusan terbesar dalam sejarah yang tercatat, memuntahkan hingga 150 kilometer kubik material vulkanis yang menjadikannya berskala VEI-7 pada Indeks Eksplosivitas Vulkanik.', -8.2452778, 117.9927778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Caldera%20Mt%20Tambora%20Sumbawa%20Indonesia.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q168714', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 73),
  (8252, NULL, 2, 'Gunung Agung', 'Karangasem', 'Bebandem, Bali', 'Gunung Agung (Aksara Bali: ᬕᬸᬦᬸᬂᬅᬕᬸᬂ) adalah gunung tertinggi di pulau Bali dengan ketinggian 3.142 mdpl. Gunung berapi ini terletak di Kecamatan Rendang, Kabupaten Karangasem, Bali, Indonesia. Pura Besakih, yang merupakan salah satu Pura terpenting di Bali, terletak di lereng gunung ini.', -8.3419444, 115.5077778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Agung%2C%20November%202017%20eruption%20-%2027%20Nov%202017%2003.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q158470', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 58),
  (8253, NULL, 2, 'Gunung Bromo', 'Jawa Timur', 'Pasuruan, Jawa Timur', 'Gunung Bromo atau dalam bahasa Tengger dieja "Brama", juga disebut Kaldera Tengger, adalah sebuah gunung berapi aktif di Jawa Timur, Indonesia. Gunung ini memiliki ketinggian 2.614 meter di atas permukaan laut dan berada dalam empat wilayah kabupaten, yakni Kabupaten Probolinggo, Kabupaten Pasuruan, Kabupaten Lumajang, dan Kabupaten Malang. Gunung Bromo terkenal sebagai objek wisata utama di Jawa Timur.', -7.9430556, 112.9538889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Bromo%20closeup%20on%20sunrise%202.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q679590', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 46),
  (8254, NULL, 2, 'Rinjani', 'Lombok Timur', 'Lombok Timur, Nusa Tenggara Barat', 'Gunung Rinjani (Sasak: ᬕᬸᬦ᭄ᬗᬸᬂ᭞ᬭᬶᬦ᭄ᬚᬦᬶ, translit. gunong rinjani) adalah gunung berapi stratovulkano aktif yang terletak di wilayah Lombok Utara, Nusa Tenggara Barat, di pulau Lombok, Indonesia. Gunung ini mencapai ketinggian 3.726 meter (12.224 ft), menjadikannya gunung berapi tertinggi kedua di Indonesia dan titik tertinggi di provinsi Nusa Tenggara Barat.', -8.4166667, 116.4666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Rinjani%20dari%20Jalur%20Sembalun.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q847323', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 46),
  (8257, NULL, 2, 'Gunung Marapi', 'Agam', 'Agam, Sumatera Barat', 'Gunung Marapi, juga dikenal sebagai Merapi atau Berapi (Gunuang Marapi dalam Bahasa Minang) dalam (Bahasa Jawi:  ڬونوواڠ ماراڤي), adalah gunung berapi yang terletak di Sumatera Barat, Indonesia. Gunung ini tergolong gunung yang paling aktif di sumatera. Terletak dalam kawasan administrasi Kabupaten Agam dan Kabupaten Tanah Datar, gunung berketinggian 2.891 mdpl ini dapat dilihat juga dari Kota Bukittinggi dan Kota Padang Panjang.', -0.3805556, 100.4733333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Marapi%20dalam%20sensasi%20Dua%20Warna%20%28cropped%29.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1960702', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 34),
  (8258, NULL, 2, 'Gunung Galunggung', 'Jawa Barat', 'Tasikmalaya, Jawa Barat', 'Gunung Galunggung (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮌᮜᮥᮀᮌᮥᮀ) merupakan gunung api dengan ketinggian 2.240 meter di atas permukaan laut, dengan puncak tertingginya yakni Puncak Beuti Canar yang memiliki ketinggian 2.240 Mdpl. Gunung ini terletak sekitar 17 km dari pusat kota Tasikmalaya, Jawa Barat. Untuk mencapai bibir kawah Gunung Galunggung, dibangun sebuah tangga yang memiliki 620 anak tangga.', -7.2567315, 108.0770588, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/GUNUNG%20GALUNGGUNG.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q911748', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 33),
  (8259, NULL, 2, 'Gunung Slamet', 'Jawa Tengah', 'Pemalang, Jawa Tengah', 'Gunung Slamet (bahasa Jawa: ꦒꦸꦤꦸꦁꦱ꧀ꦭꦩꦼꦠ꧀, translit. gunung slamet) adalah sebuah gunung berapi kerucut tipe A yang berada di Jawa Tengah, Indonesia, dan merupakan gunung tunggal yang terpisah dari pegunungan. Gunung Slamet memiliki ketinggian 3.432 mdpl dan terletak di antara 5 kabupaten, yaitu Kabupaten Banyumas, Kabupaten Purbalingga, Kabupaten Pemalang, Kabupaten Tegal dan Kabupaten Brebes.', -7.239, 109.22, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Slamet%20dari%20Kr%20Salam.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q580131', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 32),
  (8261, NULL, 2, 'Gunung Raung', 'Bondowoso', 'Bondowoso, Jawa Timur', 'Gunung Raung adalah gunung berapi kerucut yang terletak di ujung timur Pulau Jawa, Indonesia. Secara administratif, kawasan gunung ini termasuk dalam wilayah tiga kabupaten di wilayah Besuki, Jawa Timur, yaitu Banyuwangi, Bondowoso, dan Jember. Puncaknya sekitar 3.344 MDPL\nSecara geografis, lokasi gunung Ini berada di dalam kawasan kompleks Pegunungan Ijen dan menjadi puncak tertinggi dari gugusan pegunungan tersebut.', -8.125, 114.0416667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Raung.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2033748', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 31),
  (8262, NULL, 2, 'Gunung Merbabu', 'Jawa Tengah', 'Selo, Jawa Tengah', 'Gunung Merbabu (Hanacaraka: ꦒꦸꦤꦸꦁꦩꦼꦂꦧꦧꦸ) adalah gunung api yang bertipe Stratovulcano yang terletak secara geografis pada 7,5° LS dan 110,4° BT. Secara administratif gunung ini berada di wilayah Kabupaten Magelang di lereng sebelah barat dan Kabupaten Boyolali di lereng sebelah timur dan selatan, Kabupaten Semarang di lereng sebelah utara, Provinsi Jawa Tengah.\nGunung ini pernah meletus pada tahun 1560 dan 1797. Dilaporkan juga pada tahun 1570 pernah meletus, akan tetapi belum dilakukan konfirmasi dan penelitian lebih lanjut.', -7.455, 110.44, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20Merbabu%20dari%20Kota%20Salatiga%20%281%29.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q598893', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 30),
  (8263, NULL, 2, 'Gunung Dempo', 'Sumatera Selatan', 'Lahat, Sumatera Selatan', 'Gunung Dempo (Besemah : Dimpu) memiliki ketinggian (3.178 mdpl) terletak di provinsi Sumatera Selatan tepatnya di kota pegunungan yaitu Kota Pagaralam. Gunung Dempo terletak di kota Pagaralam, dengan jarak tempuh darat sekitar 7 jam dari Palembang, ibu kota provinsi Sumatera Selatan.\nSesuai dengan namanya, Kota Pagaralam dikelilingi oleh pegunungan Bukit Barisan dan yang tertinggi adalah Gunung Dempo.', -4.03, 103.13, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20dempo%20%28cropped%29.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1186618', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 29),
  (8264, NULL, 2, 'Puncak Mandala', 'Jayawijaya', 'Pegunungan Bintang, Papua Pegunungan', 'Puncak Mandala atau Aplim Apom adalah salah satu gunung di Papua Pegunungan, Indonesia. Dengan ketinggian 4.760 m, Puncak Mandala adalah gunung tertinggi ke-2 di Indonesia setelah Puncak Jaya. Puncak Mandala membentuk bagian Pegunungan Bintang bagian timur dan berada dekat perbatasan Papua Nugini.', -4.7086111, 140.2891667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Mandala%20from%20North%20West%20by%20Christian%20Stangl%20flickr.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1512836', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 29),
  (8265, NULL, 2, 'Gunung Gamalama', 'Maluku Utara', 'Ternate, Maluku Utara', 'Gunung Gamalama adalah sebuah Gunung berapi kerucut yang merupakan keseluruhan Pulau Ternate, Kepulauan Maluku, Indonesia. Pulau ini ada di pesisir barat Pulau Halmahera yang ada di bagian utara Kepulauan Maluku. Selama berabad-abad, Ternate adalah pusat benteng Portugis dan VOC Belanda untuk perdagangan rempah-rempah, yang telah mencatat aktivitas vulkanik Gunung Gamalama.', 0.8072222, 127.3338889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ternate%2C%20Maluku%20Islands%2C%20Indonesia%202.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1467910', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 27),
  (8266, NULL, 2, 'Gunung Lokon', 'Sulawesi Utara', 'Tomohon, Sulawesi Utara', 'Gunung Lokon adalah sebuah gunung berapi di Kota Tomohon, Provinsi Sulawesi Utara. Gunung ini memiliki ketinggian 1.580 m dari permukaan laut. Sesuai namanya, Gunung Lokon berarti yang tertua dan terbesar.', 1.3580556, 124.7919444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Lokon.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q265585', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 26),
  (8267, NULL, 2, 'Gunung Papandayan', 'Garut', 'Jalan Cikajang - Gunung Papandayan, Pamulihan, Garut, Jawa Barat', 'Gunung Papandayan adalah gunung api stratovolcano yang terletak di Kabupaten Garut, Jawa Barat, tepatnya di Kecamatan Cisurupan. Gunung dengan ketinggian 2.665 m di atas permukaan laut ini terletak sekitar 70 km sebelah tenggara Kota Bandung. Gunung Papandayan memiliki beberapa kawah yang terkenal, di antaranya Kawah Mas, Kawah Baru, Kawah Nangklak, dan Kawah Manuk.', -7.3289694, 107.7157028, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%20-%20papandayan%205.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1073134', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 26),
  (8268, NULL, 2, 'Gunung Tangkuban Perahu', 'Bandung Barat', 'Jalur Pendakian Puncak Upas via Trek 11 Sukawana, Cisarua, Jawa Barat', 'Gunung Tangkuban Parahu (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮒᮀᮊᮥᮘᮔ᮪ ᮕᮛᮠᮥ, Latin: Gunung Tangkuban Parahu) adalah salah satu gunung yang terletak di antara Kabupaten Subang dan Kabupaten Bandung Barat, Provinsi Jawa Barat, Indonesia. Sekitar 20 km ke arah utara Kota Bandung, dengan rimbun pohon pinus dan hamparan kebun teh di sekitarnya, Gunung Tangkuban Parahu mempunyai ketinggian setinggi 2.086 meter. Bentuk gunung ini adalah Stratovolcano dengan pusat erupsi yang berpindah dari timur ke barat.', -6.77, 107.6, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vulkaan%20Tangkuban%20Perahu.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1190569', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 25),
  (8269, NULL, 2, 'Gunung Soputan', 'Sulawesi Utara', 'Minahasa, Sulawesi Utara', 'Gunung Soputan adalah gunung berapi yang terletak di provinsi Sulawesi Utara, Indonesia. Gunung ini terbentuk pada masa Kuarterner di tepi selatan kaldera Tondano, dan merupakan salah satu gunung api teraktif di Sulawesi. Tercatat telah terjadi letusan yang cukup sering dalam rentang waktu beberapa tahun sekali.', 1.112, 124.736, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Soputan.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q781529', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 24),
  (8270, NULL, 2, 'Gunung Awu', 'Kepulauan Sangihe', 'Kendahe I, Sulawesi Utara', 'Gunung dengan ketinggian 1320 mdpl ini berada di Kabupaten Kepulauan Sangihe, Sulawesi Utara. Berdasarkan catatan sejarah gunung ini termasuk gunung api yang mempunyai masa istirahat yang panjang. Namun, setiap letusannya selalu tergolong besar.', 3.68128, 125.45387, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Awu%20Crater.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q791817', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 24),
  (8271, NULL, 2, 'Gunung Karangetang', 'Sulawesi Utara', 'Kepulauan Siau Tagulandang Biaro, Sulawesi Utara', 'Gunung Karangetang atau Api Siau adalah gunung berapi yang terletak di Pulau Siau, di lepas pantai utara Sulawesi Utara, Indonesia. Letak tepatnya di Kabupaten Kepulauan Siau Tagulandang Biaro. Gunung Karangetang adalah salah satu gunung berapi teraktif di Indonesia dengan letusan sebanyak lebih dari 40 kali sejak 1675 serta banyak letusan kecil yang tidak terdokumentasi pada catatan sejarah.', 2.7777778, 125.4075, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Karangetang.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1053413', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 24),
  (8272, NULL, 2, 'Gunung Gede', 'Bogor', 'Cianjur, Jawa Barat', 'Gunung Gede (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮌᮨᮓᮦ, Gunung Gedé, Gunung Gumuruh, bahasa Belanda: Blaauwberg) merupakan sebuah gunung berapi kerucut tipe A yang berada di bagian barat Pulau Jawa, Indonesia. Gunung ini berada di tiga wilayah kabupaten yaitu Kabupaten Cianjur, Kabupaten Sukabumi, dan Kabupaten Bogor, dengan ketinggian 1.000 - 2.962 mdpl, dan terletak pada garis lintang 106°51\' - 107°02\' BT dan 64°1\' - 65°1 LS. Terdapat tiga kawasan urban yang mengelilingi gunung ini yaitu Bogor, Cianjur, dan Sukabumi yang masing-masing terletak di barat laut, timur, dan selatan di mana sekitar 4 juta jiwa menghuni ketiga kawasan urban tersebut.\nGunung ini merupakan Gunung ketiga tertinggi di Jawa Barat setelah Gunung Ceremai dan Gunung Pangrango.', -6.7883333, 106.9816667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gede%20seen%20from%20Cilaku.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1145123', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 24),
  (8274, NULL, 2, 'Gunung Arjuno', 'Jawa Timur', 'Pasuruan, Jawa Timur', 'Gunung Arjuno (terkadang dieja Gunung Arjuna) adalah sebuah gunung berapi kerucut (istirahat) di Jawa Timur, Indonesia dengan ketinggian 3.339 m dpl. Gunung Arjuno secara administratif terletak di perbatasan Kota Batu, Kabupaten Malang, dan Kabupaten Pasuruan dan berada di bawah pengelolaan Taman Hutan Raya Raden Soerjo. Gunung Arjuno merupakan gunung tertinggi kedua di Jawa Timur setelah Gunung Semeru, serta menjadi yang tertinggi keempat di Pulau Jawa.', -7.765, 112.5897222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Arjuna.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q665399', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 23),
  (8275, NULL, 2, 'Puncak Trikora', 'Jayawijaya', 'Jayawijaya, Papua Pegunungan', 'Puncak Trikora atau Ettiakup merupakan sebuah gunung yang terdapat di Papua Pegunungan, Indonesia. Puncak Trikora mempunyai ketinggian setinggi 4,751 meter, menjadikannya gunung tertinggi ketiga di Indonesia setelah Puncak Jaya dan Puncak Mandala. Puncak Trikora mempunyai kawasan hutan Dipterokarp Bukit, hutan Dipterokarp Atas, hutan Montane, dan Hutan Ericaceous atau hutan gunung.', -4.35, 138.65, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Trikora%20from%20north.%20main%20summit%20%28center%20left%29%20and%20west%20ridge%20by%20Christian%20Stangl%20flickr.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1349622', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 22),
  (8276, NULL, 2, 'Gunung Talang', 'Sumatera Barat', 'Solok, Sumatera Barat', 'Gunung Talang (nama lainnya Salasi atau Sulasi) merupakan gunung berapi yang terletak terletak di kabupaten Solok, provinsi Sumatera Barat, Indonesia.\nGunung Talang berlokasi sekitar 9 km dari kota Arosuka ibu kota kabupaten Solok, dan sekitar 40 km sebelah timur kota Padang.\nGunung ini bertipe stratovolcano dengan ketinggian 2.597 m, merupakan salah satu dari gunung api aktif di Sumatera Barat, dan salah satu kawahnya menjadi sebuah danau yang disebut dengan Danau Talang.', -0.986, 100.6925, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Talang.JPG?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2155367', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 22),
  (8277, NULL, 2, 'Gunung Ceremai', 'Jawa Barat', 'Majalengka, Jawa Barat', 'Gunung Ceremai (sering kali secara salah kaprah dinamakan Ciremai, Latin: Gunung Ceremé) adalah gunung berapi kerucut yang secara administratif termasuk dalam wilayah dua kabupaten, yakni Kabupaten Kuningan dan Kabupaten Majalengka, Provinsi Jawa Barat. Posisi geografis puncaknya terletak pada kordinat 6° 53\' 30" LS dan 108° 24\' 00" BT, dengan ketinggian 3.078 meter di atas permukaan laut. Gunung Ceremai merupakan gunung tertinggi di Jawa Barat.', -6.8919444, 108.4, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Ciremai%20sfw2503.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q507179', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 21),
  (8278, NULL, 2, 'Gunung Sumbing Jawa Tengah', 'Temanggung', 'Temanggung, Jawa Tengah', 'Gunung Sumbing (bahasa Jawa: ꦒꦸꦤꦸꦁꦱꦸꦩ꧀ꦧꦶꦁ, translit. Gunung Sumbing) adalah gunung berapi kerucut yang terdapat di Jawa Tengah, Indonesia. Gunung Sumbing merupakan gunung tertinggi ketiga di Pulau Jawa setelah Gunung Semeru dan Gunung Slamet.', -7.385, 110.0725, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20sumbing.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1677690', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 21),
  (8279, NULL, 2, 'Gunung Lawu', 'Jawa Tengah', 'Karanganyar, Jawa Tengah', 'Gunung Lawu (Hanacaraka: ꦒꦸꦤꦸꦁꦭꦮꦸ) adalah sebuah gunung berapi aktif yang terletak di Pulau Jawa, tepatnya di perbatasan Jawa Tengah dan Jawa Timur, Indonesia. Gunung Lawu memiliki ketinggian sekitar 3.265 mdpl, ketinggian tersebut menjadikan Gunung Lawu masuk dalam 7 Summit of Java. Gunung Lawu terletak di antara tiga kabupaten, yaitu Karanganyar di Jawa Tengah, Ngawi, dan Magetan di Jawa Timur.', -7.627382, 111.1943158, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lawu.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q3219949', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 21),
  (8280, NULL, 2, 'Gunung Sumantri', 'Mimika', 'Puncak, Papua Tengah', 'Puncak Sumantri (atau juga ditulis sebagai Soemantri atau Soemantri Brodjonegoro) adalah sebuah puncak di bagian barat Barisan Sudirman (Papua). Ketinggian puncak ini mencapai 4.870 meter (15.978 ft).\nPuncak ini terletak sekitar 2 km di timur laut dari Piramida Carstensz (4,884 m), puncak tertinggi di Oseania.', -4.0619444, 137.185, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumantri%20%28center%29%20with%20Ngga%20Pulu%20%28right%29%20from%20Carstensz%20Summit%20by%20Christian%20Stangl%20flickr.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q7636960', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 21),
  (8281, NULL, 2, 'Gunung Binaia', 'Maluku', 'Maluku Tengah, Maluku', 'Gunung Binaia atau Binaiya atau Binaija adalah sebuah gunung yang terletak di Pulau Seram, Maluku di negara Indonesia. Gunung Binaiya merupakan gunung tertinggi di Provinsi Maluku dengan ketinggian 3.027 meter di atas permukaan laut (mdpl) masuk ke dalam wilayah Kabupaten Maluku Tengah. Provinsi Maluku.', -3.1733333, 129.455, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Seram%20en.png?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q863497', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 19),
  (8282, NULL, 2, 'Gunung Klabat', 'Minahasa Utara', 'Sulawesi Utara', 'Gunung Klabat merupakan gunung tertinggi di Provinsi Sulawesi Utara. Puncak ketinggiannya mencapai sekitar 1995 mdpl. Gunung ini oleh masyarakat Tonsea (Minahasa Utara) disebut juga Gunung Tamporok.', 1.4533333, 125.0308333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Klabat.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1193306', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 19),
  (8283, NULL, 2, 'Gunung Sindara', 'Temanggung', 'Kejajar, Jawa Tengah', 'Gunung Sindoro atau Gunung Sundoro (puncak ketinggian 3.153 mdpl) (bahasa Jawa: ꦒꦸꦤꦸꦁꦱꦸꦤ꧀ꦢꦫ, translit. Gunung Sundara) merupakan sebuah gunung stratovolcano aktif yang terletak di Jawa Tengah, Indonesia, dengan Temanggung sebagai kota terdekat. Gunung Sindoro terletak berdampingan dengan Gunung Sumbing.', -7.3011111, 109.9966667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sundoro.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2038462', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 19),
  (8284, NULL, 2, 'Gunung Seulawah Agam', 'Aceh', 'Aceh Besar, Aceh', 'Gunung Seulawah Agam adalah sebuah gunung berapi yang terletak di Kecamatan Seulimeum dan Kecamatan Lembah Seulawah, Kabupaten Aceh Besar, Provinsi Aceh.\nSelain dikenal sebagai Seulawah Agam, gunung yang memiliki tinggi 1726 mdpl ini memiliki nama-nama lain seperti, Solawa Agam, Solawaik Agam, Selawadjanten, dan Goldberg. Kawah Seulawah Agam dikenal sebagai Kawah Heutsz dan ada juga yang menyebut kawahnya sebagai Tanah Simpago\nGunung Seulawah Agam terbentuk akibat pertemuan lempeng Indo-Australia yang bergerak relatif ke utara, menujam di bawah Lempeng Kerak Benua Eurasia.', 5.448, 95.658, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Seulawaih%20Agam.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q29595', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8285, NULL, 2, 'Gunung Tandikat', 'Sumatera Barat', 'Tanah Datar, Sumatera Barat', 'Gunung Tandikat (Minang:Tandikek) atau Puncak Tri Arga (penyangga langit Minang) adalah gunung berapi aktif yang terletak di Dataran Tinggi Minangkabau. Letaknya 7,5 km dari kota Padang Panjang, Provinsi Sumatera Barat, Indonesia. Gunung ini membentang dari utara ke selatan.', -0.4325833, 100.3171361, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tandikat-Singgalang.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q40692', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8286, NULL, 2, 'Gunung Geureudong', 'Aceh', 'Bener Meriah, Aceh', 'Gunung Geureudong atau Bur ni Geureudong atau Bur ni Telong adalah gunung stratovolcano di Provinsi Aceh, Indonesia. Nama resmi untuk kompleks gunung berapi ini masih menjadi perdebatan, karena posisi Bur ni Geureudong dan Bur ni Telong yang berdekatan. Dua Kerucut vulkanik bernama Salah Nama dan Pepanji yang merupakan bukit sedimen.', 4.8105, 96.8169, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bur%20ni%20Telong.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q40981', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8287, NULL, 2, 'Gunung Baluran', 'Jawa Timur', 'Situbondo, Jawa Timur', 'Gunung Baluran adalah sebuah gunung di Jawa Timur, Indonesia. Gunung Baluran berketinggian 1.247 meter di atas permukaan laut. Gunung ini secara administratif termasuk dalam wilayah Kabupaten Situbondo.', -7.8463889, 114.3622222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20vulkaan%20Beloeran%20aan%20de%20Oostkust%20van%20Java%20vanuit%20zee%20TMnr%2010004116.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q571805', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8288, NULL, 2, 'Gunung Malabar', 'Bandung', 'Cinanggela, Kabupaten Bandung, Jawa Barat', 'Gunung Malabar (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮙᮜᮘᮁ) merupakan sebuah gunung api yang puncaknya berada di Pangalengan, Kabupaten Bandung, Jawa Barat. Kompleks Pegunungan Malabar merupakan rangkaian beberapa gunung, yaitu gunung Puntang dengan Puncak Mega-nya (2.222 m dpal), Gunung Haruman (2.141 m dpal) dan Gunung Malabar sendiri dengan puncaknya disebut dengan Puncak Besar 2,343 meter di atas permukaan laut.\nGunung Malabar mempunyai kawasan hutan Dipterokarp Bukit, hutan Dipterokarp Atas, hutan Montana, dan Hutan Ericaceous atau hutan gunung.', -7.13, 107.65, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Landschap%20met%20gezicht%20op%20de%20Goenoeng%20Malabar%20TMnr%2060011494.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q670643', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8289, NULL, 2, 'Gunung Ibu', 'Halmahera Utara', 'Sarau, Halmahera Barat, Maluku Utara', 'Gunung Ibu adalah gunung berapi kerucut yang terletak di barat laut Pulau Halmahera, Indonesia. Puncak gunung merupakan kawah vulkanik. Pusat kawah memiliki lebar 1 km dan kedalaman 400 m, Sementara bagian luar memiliki lebar 1.2 km.', 1.4833333, 127.6333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Ibu.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2573469', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 18),
  (8291, NULL, 2, 'Gunung Sorik Marapi', 'Sumatera Utara', 'Sinbanggor Julu, Mandailing Natal', 'Sorik Marapi (Surat Batak: ᯑᯬᯞᯬᯄ᯦᯲ ᯚᯬᯒᯪᯄ᯦᯲ ᯔᯒᯇᯪ, translit. Dolok Sorik Marapi) adalah sebuah gunung yang masuk dalam kawasan Taman Nasional Batang Gadis, secara administratif berada di Desa Sibanggor Julu, Kecamatan Puncak Sorik Marapi, Kabupaten Mandailing Natal, Sumatera Utara. Sorik Marapi merupakan gunung berapi aktif yang berketinggian 2.145 meter.', 0.686, 99.539, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sorikmarapi.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q29559', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8292, NULL, 2, 'Gunung Leuser', 'Aceh', 'Jalur Pendakian Gunung Leuser, Gayo Lues, Aceh', 'Puncak Leuser merupakan salah satu puncak dari tiga puncak utama pegunungan Leuser dengan ketinggiannya 3,119 m terletak di sebelah tenggara Aceh. Gunung Leuser terletak di dalam Taman Nasional Gunung Leuser yang mengambil nama gunung ini sebagai namanya.', 3.7975, 97.2191667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunrises%20-%20Mount%20Leuser%20National%20Park.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1909348', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8293, NULL, 2, 'Ngga Pulu', 'Mimika', 'Puncak, Papua Tengah', 'Ngga Pulu adalah sebuah puncak di sisi utara dari Gunung Carstensz di bagian barat dari Pulau Papua dengan ketinggian 4.862 meter (15.951 ft). Pengukuran trigonometri menunjukkan bahwa Ngga Pulu dulu adalah puncak tertinggi di Pulau Papua dan juga merupakan puncak tertinggi di Benua Australia-Papua. Ketinggian Ngga Pulu pada tahun 1936 adalah sekitar 4.907 m (16.099 ft), sehingga Ngga Pulu merupakan puncak tertinggi di antara Himalaya dan Andes.', -4.0572222, 137.1836111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Jaya%20icecap%201936.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1984246', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8294, NULL, 2, 'Gunung Penanggungan', 'Jawa Timur', 'Kedungudi, Mojokerto, Jawa Timur', 'Gunung Penanggungan atau yang dikenal juga dengan nama Gunung Pawitra memiliki ketinggian 1.653 mdpl. Penanggungan merupakan gunung berapi kerucut dalam kondisi istirahat yang berada di Jawa Timur, Indonesia. Posisinya berada di perbatasan dua kabupaten, yaitu Kabupaten Mojokerto (sisi barat) dan Kabupaten Pasuruan (sisi timur) dan berjarak kurang lebih 55 km sebelah selatan kota Surabaya.', -7.62, 112.63, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Penanggungan%20from%20Arjuno-Welirang%202018-12-30.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2171115', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8295, NULL, 2, 'Gunung Karang', 'Jawa Barat', 'Pandeglang, Banten', 'Gunung Karang adalah sebuah gunung berapi kerucut (Tipe B / istirahat) yang terletak di Kabupaten Pandeglang, Banten, Indonesia. Gunung ini masuk kedalam kelompok Stratovolcano yang memiliki potensi meletus pada masa mendatang. Gunung Karang memiliki ketinggian 1.778 meter di atas permukaan laut dengan puncaknya yang bernama Sumur Tujuh.', -6.2691667, 106.05, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20Gunung%20Karang%20TMnr%2060016534.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2344869', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 17),
  (8297, NULL, 2, 'Banua Wuhu', 'Mahengetang', 'Mahengetang, Sulawesi Utara', 'Banua Wuhu adalah gunung api bawah laut yang terletak di sebelah barat pulau Mahengetang, Kepulauan Sangihe, Indonesia. Gunung ini memiliki ketinggian 400 meter dari dasar laut dan puncaknya berada di kedalaman 5 meter di bawah permukaan air. Catatan sejarah menunjukkan bahwa beberapa pulau sementara terbentuk dan kemudian menghilang.', 3.1377778, 125.4905556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gelembung%20udara%20keluar%20dari%20dasar%20laut%20di%20Gunung%20Api%20Banua%20Wuhu.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q807010', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 16),
  (8298, NULL, 2, 'Colo', 'Sulawesi Tengah', 'Tojo Una-Una, Sulawesi Tengah', 'Gunung Colo adalah sebuah gunung berapi kerucut yang terletak di Pulau Una-Una, Provinsi Sulawesi Tengah, Indonesia. Gunung ini berada di di tengah Teluk Tomini, bagian utara Sulawesi. Secara administratif termasuk ke wilayah Kabupaten Tojo Una-Una.', -0.17, 121.608, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/A%20broad%20ash%20plume%20rises%20above%20Colo%20volcano%20on%20the%20island%20of%20Una-Una%20during%20the%20powerful%201983%20eruption.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1110232', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 16),
  (8299, NULL, 2, 'Gunung Tampomas', 'Sumedang', 'Sumedang, Jawa Barat', 'Tampomas (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮒᮙ᮪ᮕᮧᮙᮞ᮪) adalah sebuah gunung berapi andesit yang terletak di Jawa Barat, tepatnya di sebelah utara kawasan perkotaan Sumedang (6.77°S 107.95°E﻿ / -6.77; 107.95). Stratovolkano dengan ketinggian 1684 meter di atas permukaan laut ini memiliki aliran lava aktif di sisi timur lerengnya. Terdapat juga sumber air panas yang keluar di daerah sekitar kaki gunung.', -6.77, 107.95, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunungtampomas.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2020545', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 16),
  (8300, NULL, 2, 'Gunung Iya', 'Ende', 'Rukunlima, Ende, Nusa Tenggara Timur', 'Gunung Iya adalah gunung berapi kerucut yang terletak di bagian selatan Pulau Flores, Nusa Tenggara Timur, dan sebelah selatan dari Kota Ende yang berupa semenanjung kecil. Gunung Iya tergolong sebagai gunung berapi aktif yang terakhir kali meletus pada tahun 1969.', -8.897, 121.645, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Iya.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2236900', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 16),
  (8301, NULL, 2, 'Gunung Ebulobo', 'Pulau Flores', 'Woloede, Nagekeo, Nusa Tenggara Timur', 'Gunung Ebulobo, juga dikenal sebagai Emburombu atau Puncak Nage Keo, adalah gunung stratovolcano yang terletak bagian selatan dari Kabupaten Nagekeo di Pulau Flores Nusa Tenggara Timur, Indonesia.\nGunung Ebulobo menjulang di atas Kecamatan Boa Wae, yang terletak di bawah lereng barat laut gunung tersebut. Bentuk gunung simetris dengan ketinggian 2124 m, dengan bagian atas kubah lava berbentuk datar.', -8.82, 121.18, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ebulobo.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2382787', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 16),
  (8302, NULL, 2, 'Gunung Rajabasa', 'Kalianda', 'Kalianda, Lampung', 'Gunung Rajabasa (Abung: 𞜂𞜔𞜉𞜔𞜖𞜎𞜅𞜋𞜑) adalah gunung berapi dengan kerucut vulkanik yang terdapat di Selat Sunda di bagian tenggara dari Sumatra, terletak di Kabupaten Lampung Selatan, Provinsi Lampung. Gunung Rajabasa memiliki puncak kawah dengan lebar 500x700 meter dan bagian daratan berawa, serta gunung berapi yang diselimuti dengan berbagai vegetasi. Walaupun aktivitas fumarol terjadi di bagian kaki dan lereng gunung, terdapat kenaikan aktivitas yang dilaporkan terjadi pada April 1863 dan Mei 1892 serta tidak diketahui kapan terjadi erupsi.', -5.7833333, 105.625, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20rajabasa.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q42174', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8304, NULL, 2, 'Gunung Telaga Bodas', 'Jawa Barat', 'Pangatikan, Garut, Jawa Barat', 'Gunung Talaga Bodas (Bahasa Sunda, arti: "gunung telaga putih", Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮒᮜᮌ ᮘᮧᮓᮞ᮪, Latin: Gunung Talaga Bodas) adalah gunung stratovolcano yang terletak di bagian selatan Kabupaten Garut, Jawa Barat, Indonesia. Gunung ini terbentuk dari lava andesit dan piroklastik. Terdapat juga fumarol, kolam lumpur, dan mata air panas di sekitar danau kawah.', -7.208, 108.07, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Talagabodas.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q126717', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8305, NULL, 2, 'Gunung Wilis', 'Jawa Timur', 'Ponorogo, Jawa Timur', 'Gunung Wilis atau  Pegunungan Wilis adalah  gunung berapi Tipe B yang sudah lama tidak aktif dan terletak di Jawa Timur, Indonesia. Pegunungan Wilis merupakan gabungan dari banyak puncak gunung, yang salah satunya tertinggi yaitu Puncak Trogati dengan ketinggian 2.563 meter di atas permukaan laut (mdpl), Pegunungan Wilis termasuk dalam wilayah enam kabupaten yaitu Kabupaten Kediri, Kabupaten Tulungagung, Kabupaten Nganjuk, Kabupaten Madiun, Kabupaten Ponorogo, dan Kabupaten Trenggalek.\nPegunungan Wilis mempunyai kawasan hutan Dipterokarp Bukit, hutan Dipterokarp Atas, hutan Montane, dan hutan Ericaceous atau hutan gunung.', -7.808, 111.758, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wilis.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q956331', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8307, NULL, 2, 'Gunung Rantemario', 'Indonesia', 'Tana Toraja, Sulawesi Selatan', 'Gunung Latimojong adalah sebuah gunung di Sulawesi Selatan, Indonesia. Gunung Latimojong berada di tengah-tengah Sulawesi Selatan. Puncak gunung ini terletak di antara Kabupaten Enrekang dan Kabupaten Luwu.', -3.385, 120.0241667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Misty%20Morning%20Mount%20Latimojong.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1568730', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8308, NULL, 2, 'Singgalang', 'Sumatera Barat', 'Agam, Sumatera Barat', 'Gunung Singgalang merupakan sebuah gunung yang terdapat di provinsi Sumatera Barat, Indonesia dengan ketinggian 2,877 meter.\nDari bentuknya, gunung ini sangat mirip dengan Gunung Merbabu di Jawa Tengah. Gunung ini masih aktif tetapi tak lagi seaktif sebelum erupsi terakhir pada 1800 dan mempunyai telaga di puncaknya yang merupakan bekas kawah, Telaga ini dinamai Telaga Dewi.', -0.3913889, 100.3311111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Singgalang.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2188825', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8309, NULL, 2, 'Mount Ungaran', 'Semarang', 'Gunungsari, Kendal, Jawa Tengah', 'Gunung Ungaran (Hanacaraka: ꦒꦸꦤꦸꦁꦈꦔꦫꦤ꧀) adalah gunung berapi stratovolcano yang sudah terkikis habis, terletak di selatan Kota Semarang, Jawa Tengah, Indonesia. Tidak ada catatan sejarah tentang aktivitas gunung tersebut. Dua ladang fumarol aktif ditemukan di sisi selatan.', -7.18, 110.33, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ereveld%20Candi.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2746639', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8310, NULL, 2, 'Gunung Pangrango', 'Bogor', 'Sukabumi, Jawa Barat', 'Gunung Pangrango (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮕᮀᮛᮍᮧ) merupakan sebuah gunung berapi tidak aktif yang terdapat di bagian barat pulau Jawa, Indonesia yang merupakan bagian dari kawasan vulkanik Busur Sunda. Gunung Pangrango mempunyai ketinggian setinggi 3.026 mdpl. Puncaknya dinamakan Puncak Mandalawangi, dimana puncak ini merupakan titik pertemuan batas tiga kabupaten yaitu Kabupaten Bogor, Kabupaten Cianjur dan Kabupaten Sukabumi.', -6.7666667, 106.95, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pangrango%2C%20West%20Java.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q11222863', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 15),
  (8313, NULL, 2, 'Gunung Kembar', 'Aceh', 'Gayo Lues, Aceh', 'Gunung Kembar adalah sebuah gunung berapi Pleistosen yang terletak di bagian utara Pulau Sumatra, Indonesia. Gunung ini terdapat fumarol, yang bernama Gayolesten.', 3.85, 97.664, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumatra%20Topography.png?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q537391', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13),
  (8314, NULL, 2, 'Pegunungan Meratus', 'Indonesia', 'Kotabaru, Kalimantan Selatan', 'Meratus merupakan kawasan pegunungan yang berada di tenggara Pulau Kalimantan serta membelah Provinsi Kalimantan Selatan menjadi dua. Pegunungan ini membentang sepanjang ± 600 km² dari arah barat daya-timur laut dan membelok ke arah utara hingga perbatasan Provinsi Kalimantan Tengah dan Provinsi Kalimantan Timur. Titik tertinggi di rangkaian Pegunungan Meratus adalah Gunung Halau-halau yang memiliki ketinggian 1.901 Mdpl.', -2.75, 115.6666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meratus.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q937746', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 13),
  (8319, NULL, 2, 'Bukit Beriti Besar', 'Bengkulu', 'Lebong, Bengkulu', 'Belirang-Beriti, yang juga ditulis Belerang-Beriti, adalah kompleks gunung berapi yang berada di Dataran Semalako, yaitu bagian dari Bukit Barisan di barat daya Sumatra, Indonesia. Gunung ini terletak di Provinsi Sumatera Selatan. Kawah gunung memiliki lebar 1,2 km.', -3.2654417, 102.2648051, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Belirang-Beriti.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q815632', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 12),
  (8320, NULL, 2, 'Gunung Mutis', 'Nusa Tenggara Timur', 'Timor Tengah Selatan, Nusa Tenggara Timur', 'Gunung Mutis atau Nuaf Nefomasi adalah salah satu gunung yang terdapat di Pulau Timor. Dengan ketinggian 2.427 mdpl, ini adalah gunung tertinggi di wilayah Timor Barat dan juga Nusa Tenggara Timur, Indonesia. Secara administratif, puncak gunung berada di perbatasan Kabupaten Timor Tengah Utara dengan Kabupaten Timor Tengah Selatan, Provinsi Nusa Tenggara Timur.', -9.5261111, 124.2386111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Santalum%20album%20%28Chandan%29%20in%20Hyderabad%2C%20AP%20W%20IMG%200025.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q1165869', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 12),
  (8321, NULL, 2, 'Wurlali', 'Damer', 'Maluku Barat Daya, Maluku', 'Gunung Wurlali merupakan sebuah gunung berapi yang terdapat di bagian timur Pulau Damar, Maluku. Gunung ini memiliki ketinggian 868 meter di atas permukaan air laut. Secara administratif berada di wilayah Kecamatan Damer, Kabupaten Maluku Barat Daya, Provinsi Maluku.', -7.125, 128.675, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wurlali.jpg?width=800', '2026-11-04 09:38:03', '2026-11-24 23:32:50', 'wd:Q2025875', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 12),
  (8322, NULL, 3, 'Air Terjun Gitgit', 'Buleleng', '2, Sukasada, Bali', 'Air terjun Gitgit adalah air terjun yang terletak di kabupaten Buleleng, Bali. Air terjun ini terletak di Desa Gitgit, Kecamatan Sukasada, Buleleng yang berjarak 11 km ke arah selatan dari Singaraja. Air terjun ini mempunyai ketinggian 35 meter dan merupakan air terjun tertinggi di pulau Bali.', -8.1913, 115.1347, 20000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gitgit%20Waterfall%2C%20Campuhan%20area%2C%20Bali%2C%20Indonesia.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q37648', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 14),
  (8323, NULL, 3, 'Air Terjun Sipisopiso', 'Karo', 'Pangambatan, Kabupaten Karo, Sumatera Utara', 'Air Terjun Sipisopiso atau Sipiso-piso adalah sebuah air terjun yang berada di Desa Tongging, Kecamatan Merek, Kabupaten Karo, Provinsi Sumatera Utara, Indonesia. Air Terjun Sipisopiso memiliki ketinggian hingga 120 meter dan mengucur deras membentuk garis vertikal sempurna. Sehingga Air Terjun Sipisopiso masuk dalam air terjun tipe Plunge.', 2.9162, 98.5196, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sipiso-Piso%20Falls%20Front%20View.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q4420683', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 10),
  (8324, NULL, 3, 'Air terjun Madakaripura', 'Jawa Timur', 'Negororejo, Probolinggo, Jawa Timur', 'Air terjun Madakaripura-Indonesia adalah air terjun yang terletak di Kecamatan Lumbang, Kabupaten Probolinggo, Provinsi Jawa Timur. Air terjun setinggi 200 meter ini merupakan air terjun tertinggi di Pulau Jawa dan tertinggi kedua di Indonesia. Air terjun ini adalah salah satu air terjun di kawasan Taman Nasional Bromo Tengger Semeru tepatnya di lereng Gunung Bromo.', -7.8447222, 113.0175, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterfall%20Madakaripura%20B.JPG?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q4206976', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 7),
  (8325, NULL, 3, 'Curug Cipendok', 'Purwokerto', 'Purwokerto, Jawa Tengah', 'Curug Cipendok adalah air terjun dengan ketinggian 92 meter yang terletak di lereng Gunung Slamet. Curug Cipendok mempunyai daya tarik tersendiri, karena lingkungan masih betul-betul alami. Kesunyian juga masih sangat terasa, sebab belum banyak pelancong yang datang menikmati keindahan alamnya.', -7.339398, 109.134321, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Cipendok%2C%20Purwokerto%2C%202015-03-22.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q5196032', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 6),
  (8326, NULL, 3, 'air terjun Dago', 'Bandung', 'Cidadap, Kota Bandung, Jawa Barat', 'Taman Hutan Raya Ir. H. Djuanda (Tahura Djuanda) merupakan kawasan konservasi yang terpadu antara alam sekunder dengan hutan tanaman dengan jenis Pinus (Pinus merkusil) yang terletak di Sub-Daerah Aliran Sungai Cikapundung dan DAS Citarum yang membentang mulai dari Curug Dago, Dago Pakar sampai Curug Maribaya yang merupakan bagian dari kelompok hutan Gunung Pulosari.\nTahura Djuanda terletak di sebelah utara Kota Bandung berjarak kurang lebih 7 km dari pusat kota, secara geografis berada pada 1070 30’ BT dan 60 52’ LS, secara administrasi berada di wilayah Desa Ciburial, Kecamatan Cimenyan, Kabupaten Bandung dan sebagian masuk Desa Mekarwangi, Desa Cibodas, Desa Langensari, dan Desa Wangunharja, Kecamatan Lembang, Kabupaten Bandung Barat serta Kelurahan Dago, Kecamatan Coblong, Kota Bandung.', -6.8653249, 107.6181495, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Dago.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q2192810', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 5),
  (8327, NULL, 3, 'Air Terjun Tegenungan', 'Gianyar', 'Blahbatuh, Bali', 'Air terjun Tegenungan adalah air terjun yang terletak di Desa Kemenuh, Kecamatan Sukawati, Kabupaten Gianyar, berjarak 30 km dari Kota Denpasar. Air terjun ini memiliki ketinggian 15 meter. Meski tidak begitu tinggi, debit airnya sangat deras.', -8.575229, 115.290701, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tegenungan%20Waterfall%202017-08-18%20%282%29.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q25462922', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 5),
  (8328, NULL, 3, 'Air terjun Efrata', 'Sumatera Utara', 'Air Terjun Efrata Road, Sosor Dolok, Samosir, Sumatera Utara', 'Air terjun Efrata adalah sebuah air terjun yang terletak di Kecamatan Harian, provinsi Sumatera Utara, di bagian barat negara Indonesia (186 km dari pusat Kota Medan). Ketinggian air terjun ini sekitar 26 meter dan lebar kurang lebih 12 meter.\n\nKondisi lahan di sekitar objek wisata air terjun Efrata dikelilingi lahan pertanian, mengingat air terjun ini berada dekat desa.', 2.5368988, 98.6423665, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Efrata%20tampak%20dari%20bawah%20hingga%20atas%2006.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q129807124', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8329, NULL, 3, 'Grojogan Sewu', 'Karanganyar', 'Tawangmangu, Jawa Tengah', 'Grojogan Sewu merupakan air terjun yang berada di Provinsi Jawa Tengah.Terletak di Kecamatan Tawangmangu, Kabupaten Karanganyar, Jawa Tengah. Air terjun Grojogan Sewu terletak di lereng Gunung Lawu. Grojogan Sewu terletak sekitar 27 km di sebelah timur Kota Karanganyar.', -7.6605556, 111.1302778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/GrojoganSewu.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q5610142', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8330, NULL, 3, 'Curug Luhur', 'Jawa Barat', 'Mekarsari, Sukabumi, Jawa Barat', 'Curug Luhur adalah sebuah air terjun yang berada di daerah kecamatan Tenjolaya, Bogor. Tingginya 624 m. Curug yang mempunyai dua air terjun yang terletak di kaki Gunung Salak sekitar 70 km di selatan Jakarta.', -7.2325, 106.8166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Segarnya%20air%20di%20Curug%20Luhur.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q12479660', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8331, NULL, 3, 'Curug Cibeureum', 'Indonesia', 'Pangalengan, Jawa Barat', 'Curug Cibereum (aksara Sunda: ᮎᮥᮛᮥᮍ᮪ ᮎᮤᮘᮩᮛᮩᮙ᮪) adalah air terjun yang berada di Kabupaten Cianjur, Provinsi Jawa Barat. Di kawasan ini terdiri dari tiga air terjun yang saling berdekatan. Selain air terjun utama Curug Cibeureum, terdapat dua air terjun lain yang lebih kecil, yaitu Curug Cidendeng dan Curug Cikundul.', -7.1833333, 107.6166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/AIr%20Terjun%20Cibeureum.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q12479661', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8332, NULL, 3, 'Curug Maribaya', 'Jawa Barat', 'Langensari, Bandung Barat, Jawa Barat', 'Maribaya adalah kawasan wisata alam yang dulunya terkenal dengan pemandian air panasnya. Tapi saat ini yang paling dikenal adalah adanya curug / air terjun yang ada di beberapa tempat di lokasi ini.\nYang juga menarik adalah curug ini dipasang jembatan di atasnya.', -6.831872, 107.656639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maribaya%20Waterfall%202013%20%28008%29.JPG?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q15120101', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Pemandian air panas', 4),
  (8333, NULL, 3, 'Air Terjun Lembah Anai', 'Tanah Datar', 'Jalan Raya Padang Bukittinggi, Air Mancur, Tanah Datar, Sumatera Barat', 'Air Terjun Lembah Anai (dikenal pula Air Mancur, ejaan lama: Ajer Mantjoer) adalah sebuah air terjun yang terletak di jorong aie mancua nagari Singgalang, X Koto, Kabupaten Tanah Datar, Sumatera Barat. Air terjun setinggi sekira 35 meter ini berada tepat di tepi Jalan Raya Padang-Bukittinggi di kaki Gunung Tandikat. Air Terjun Lembah Anai merupakan bagian dari aliran Sungai Batang Lurah, anak Sungai Batang Anai yang berhulu di Gunung Singgalang di ketinggian 400 Mdpl.', -0.483561, 100.338569, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Suasana%20jalan%20di%20Air%20Terjun%20Lembah%20Anai.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q17997837', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8334, NULL, 3, 'Tumpak Sewu', 'Sidomulyo', 'Sidorenggo, Kabupaten Malang, Jawa Timur', 'Air Terjun Tumpak Sewu atau disebut juga Coban Sewu adalah air terjun yang terletak di perbatasan Kabupaten Lumajang dengan Kabupaten Malang, Provinsi Jawa Timur. Air terjun dengan ketinggian sekitar 120 meter memiliki visual yang menyerupai tirai sehingga termasuk dalam tipe air terjun tiered. Aliran Tumpak Sewu jatuh masuk kedalam sebuah lembah yang memanjang ke selatan yang berada di ketinggian sekitar 450-500 mdpl.', -8.230408, 112.916939, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Tumpak%20Sewu.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q26246069', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 4),
  (8335, NULL, 3, 'Air terjun Jumog', 'Ngargoyoso', 'Jalan Agro Amanah, Karang, Karanganyar, Jawa Tengah', 'Air Terjun Jumog adalah wisata alam yang terletak di Desa Berjo, Kecamatan Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah, serta merupakan tempat wisata yang berada di bawah pengelolaan Badan Usaha Milik Desa (BUMDes) Berjo.\nAir terjun ini berlokasi di 500 meter sebelah barat candi Hindu yang bernama Candi Sukuh. Ketinggiannya sekitar 30 meter, serta memiliki tiga cabang aliran, yaitu Klueng, Kusumajati, dan Jubleg.', -7.6309674, 111.1262805, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Jumog%202022%2002.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q6311009', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8336, NULL, 3, 'Curug Orok', 'Indonesia', 'Cikajang, Garut, Jawa Barat', 'Curug Orok merupakan jenis ODTW alam berupa air terjun yang terletak di desa Cikandang, kecamatan Cikajang, Kabupaten Garut, Provinsi Jawa Barat.', -7.386804, 107.736176, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Orok%2C%20Cikajang%2C%20Garut%2C%20Indonesia.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q12479667', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8337, NULL, 3, 'Air Terjun Coban Rondo', 'Jawa Timur', 'Kabupaten Malang, Jawa Timur', 'Air Terjun Coban Rondo merupakan air terjun yang terletak di Kecamatan Pujon, Kabupaten Malang, Jawa Timur. Air terjun ini mudah dijangkau oleh kendaraan umum. Akses yang paling mudah adalah dengan melalui jalan raya dari Malang ke Batu di sebelah timur atau dari Kediri ke Pare menuju Malang dari arah barat.', -7.8849611, 112.4773, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Coban%20Rondo.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q19725001', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8338, NULL, 3, 'Air Terjun Kapas Biru', 'Indonesia', 'Pronojiwo, Jawa Timur', 'Air Terjun Kapas Biru atau Coban Kapas Biru merupakan air terjun yang terletak di Kecamatan Pronojiwo, Kabupaten Lumajang, Provinsi Jawa Timur.Objek wisata ini dibuka untuk umum sejak tahun 2015 dengan menawarkan tempat yang luas untuk mendirikan tenda/camping serta keindahan air terjun. Belum diketahui pasti total ketinggian air terjun ini tetapi diperkirakan sekitar 100 meter. Air Terjun Kapas Biru ini bertingkat 2 dengan tingkat bawah setinggi 90 meter dan tingkat atas setinggi 10 meter dan diapit tebing yang airnya berasal dari sumber mata air di sekitar lereng Gunung Semeru.', -8.220167, 112.940333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keindahaan%20air%20terjuncdi%20lereng%20semeru.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q31173501', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8339, NULL, 3, 'Dengdeng waterfall', 'Indonesia', NULL, 'Dengdeng waterfall adalah air terjun di Indonesia.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dengdeng%20Waterfall%20%28Curug%20Dengdeng%29%20from%20Far%20Side%20View.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q30644929', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8340, NULL, 3, 'Air terjun Sikulikap', 'Sumatera Utara', NULL, 'Air Terjun Sikulikap adalah sebuah air terjun yang terletak di Kabupaten Karo, Sumatera Utara. Dikenal dengan keindahan alamnya yang memukau, air terjun ini memiliki ketinggian sekitar 40 meter dan dikelilingi hutan yang rimbun. Untuk mencapai lokasi ini, pengunjung perlu melakukan sedikit tracking, yang menjadikan perjalanan semakin menarik.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Sikulikap%2001.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q131354470', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 3),
  (8341, NULL, 3, 'Air Terjun Bajuin', 'Kalimantan Selatan', 'Sungai Bakar, Tanah Laut, Kalimantan Selatan', 'Air terjun Bajuin adalah tempat wisata alam yang berada di  Desa Sungai Bakar, Kecamatan Bajuin, Kabupaten Tanah Laut, Kalimantan Selatan. Air terjun Bajuin adalah termpat wisata populer di kurun waktu 1980 - 1995, tetapi meredup setelahnya. Hingga di 2019, dimulailah penataan lokasi wisata air terjun Bajuin dan dibuka kembali untuk umum pada 1 Juli 2020 dan berhasil mendapatkan kunjungan wisata sebanyak 2000 pengunjung selama 2 minggu dan kawasan ini pun berubah menjadi Bajuin Park.', -3.7699219, 114.8747206, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Bajuin.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q121330475', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8342, NULL, 3, 'Curug Bayan', 'Ketenger', 'Baturaden, Jawa Tengah', 'Curug Bayan adalah air terjun yang terletak di Desa Ketenger, Kecamatan Baturraden, Kabupaten Banyumas, Jawa Tengah. Curug ini terletak di kawasan lereng Gunung Slamet. Curug Bayan dikenal sebagai objek wisata alam dengan akses yang relatif mudah dibanding banyak air terjun lain di kawasan pegunungan.', -7.3246193, 109.2182515, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Bayan%20%282026%29%2001.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q121331132', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8343, NULL, 3, 'Curug Bengkawah', 'Pemalang', NULL, 'Curug Bengkawah adalah air terjun yang memiliki ketinggian + 450 m di atas permukaan laut,jenis tanah litosol serta mempunyai tipe iklim B dengan suhu antara 200-300 C serta mempunyai kelembapan 76% dengan curah hujan rata rata 2.000 mm/tahun', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20bengkawah.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q124359779', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8344, NULL, 3, 'Air Terjun Sarasah Bunta', 'Lima Puluh Kota', 'Tarantang, Lima Puluh Kota, Sumatera Barat', 'Air Terjun Sarasah Bunta: Air terjun di Sumatra Barat, Indonesia, Lima Puluh Kota.', -0.1074015, 100.6754629, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20terjun%20Sarasah%20Bunta.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q124750519', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8345, NULL, 3, 'Air Terjun Tumpang Dua', 'Kotabaru', 'Sebelimbingan, Kotabaru, Kalimantan Selatan', 'Air Terjun Tumpang Dua adalah sebuah air terjun yang berlokasi di Kabupaten Kotabaru, Provinsi Kalimantan Selatan, Indonesia. Air terjun ini dinamakan Tumpang Dua karena alirannya membentuk turunan seperti anak-anak tangga. Tidak seperti kebanyakan air terjun yang memiliki area tinggi, arus air di Air Terjun Tumpang Dua mengalir deras melewati area tanah yang landai.', -3.32463, 116.1836, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Tumpang%20Dua.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q132142770', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8346, NULL, 3, 'Air Terjun Sarasah Aia Luluih', 'Harau', NULL, 'Air Terjun Sarasah Aia Luluih: Objek wisata yang berada di Kabupaten Lima Puluh Kota, Sumatera Barat, Harau.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Sarasah%2011.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q137530926', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8347, NULL, 3, 'Air Terjun Coban Lanang', 'Malang', 'Lowokwaru, Kota Batu, Jawa Timur', 'Air Terjun Coban Lanang: Salah satu air terjun di Kabupaten Malang, Malang.', -7.8705399, 112.5515028, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Coban%20Lanang%20113445.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q138649671', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8348, NULL, 3, 'Air Terjun Jantur Inar', 'Temula', 'Sentalar, Kutai Barat, Kalimantan Timur', 'Air Terjun Jantur Inar adalah adalah wisata alam berupa air terjun yang berada di Kampung Temula, Kecamatan Nyuatan, Kabupaten Kutai Barat, Provinsi Kalimantan Timur. Jantur Inar memiliki ketinggian 30 meter dengan 200 anak tangga, selain itu air terjun ini mempertemukan keindahan eufoni visual dengan narasi tragedi kehidupan yang memilukan. Nama " Inar" di ambil dari studi stilistika, nama ini mengandung kekuatan personifikasi yang mendalam.', -0.2991536, 115.5479112, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Jantur%20Inar.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q141175710', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8349, NULL, 3, 'Air Terjun Monthel', 'Indonesia', 'Kandangmas, Kudus, Jawa Tengah', 'Air Terjun Monthel merupakan salah satu objek wisata yang berada di Kabupaten Kudus tepatnya di daerah Gunung Muria.', -6.738, 110.91, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monthel%20Waterfall.jpeg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q11255993', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8350, NULL, 3, 'Air Terjun Telun Berasap', 'Kerinci', 'Danau Gunung Tujuh Hike, Sungai Jernih, Kerinci, Jambi', 'Air Terjun Telun Berasap adalah salah satu dari begitu banyak air terjun yang terdapat di Kabupaten Kerinci, Jambi. Air terjun yang terletak di desa Telun Berasap ini memiliki ketinggian kurang lebih 50 Meter. Sumber dari air terjun ini adalah sungai-sungai yang berhulu disekitar Gunung Tujuh yang mengalir dari bibir Danau Gunung Tujuh.', -1.6888102, 101.3383811, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Telun%20Berasap.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q12471122', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8351, NULL, 3, 'Air Terjun Haratai', 'Kalimantan Selatan', 'Haratai, Hulu Sungai Selatan, Kalimantan Selatan', 'Air Terjun Haratai adalah air terjun yang terletak di Desa Haratai, Kecamatan Loksado, Kabupaten Hulu Sungai Selatan, Provinsi Kalimantan Selatan, bertingkat tiga dengan ketinggian masing-masing kurang lebih 13 meter. Di bawahnya terdapat telaga yang dapat digunakan untuk mandi atau sekadar berendam. Air terjun ini berada di deretan Pegunungan Meratus, di kawasan wisata Loksado.', -2.7753303, 115.5463766, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Haratai.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q19745512', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8352, NULL, 3, 'Air Terjun Banyumala', 'Wanagiri', 'Sukasada, Bali', 'Air Terjun Banyumala adalah sebuah air terjun yang terletak di Banjar Asah Panji, Desa Wanagiri, Kecamatan Sukasada, Kabupaten Buleleng, Bali. Air terjun Banyumala dibuka sebagai objek wisata pada bulan Juli 2015.', -8.217187, 115.101681, NULL, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Banyumala%20Waterfall.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q56392780', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8353, NULL, 3, 'Air Terjun Tiu Kelep', 'Lombok Utara', 'Senaru, Lombok Utara, Nusa Tenggara Barat', 'Air Terjun Tiu Kelep terletak di Desa Senaru, Kecamatan Bayan, Kabupaten Lombok Utara, Nusa Tenggara Barat. Air terjun setinggi 42 meter yang bertingkat-tingkat ini terletak pada kaki Gunung Rinjani dan berdekatan dengan Air Terjun Sendang Gile. Tiu Kelep dapat ditempuh dalam waktu sekitar 2.5 jam dari kota Mataram.', -8.3054944, 116.4081221, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiu%20Kelep.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q56392827', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8354, NULL, 3, 'Air Terjun Sekumpul', 'Buleleng', 'Sawan, Bali', 'Air Terjun Sekumpul adalah air terjun di Buleleng.', -8.1776, 115.182547, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Sekumpul.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q110660812', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8355, NULL, 3, 'Munduk Tutub Waterfall', 'Munduk', 'Banjar, Bali', 'Munduk Tutub Waterfall adalah air terjun di Munduk.', -8.253964, 115.079169, 20000, ' 07.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Munduk%20Tutub%20Waterfall%20SF0001.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q122203035', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8356, NULL, 3, 'Air Terjun Golden Valley', 'Munduk', 'Jalan Munduk, Banjar, Bali', 'Air Terjun Golden Valley adalah air terjun di Munduk.', -8.25432, 115.073584, NULL, ' 07.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20Valley%20Waterfall%20SF0001.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q122203119', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8357, NULL, 3, 'Banyu Wana Amertha Waterfall', 'Wanagiri', 'Sukasada, Bali', 'Banyu Wana Amertha Waterfall adalah air terjun di Wanagiri.', -8.2084534, 115.118431, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banyu%20Wana%20Amertha%20Waterfall%20SF0001.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q122947425', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8358, NULL, 3, 'Air Terjun Kembar Siapat', 'Batu Lepoq', 'Berau, Kalimantan Timur', 'Air Terjun Kembar Siapat adalah air terjun kembar yang indah dan masih alami, terletak di Desa Batu Lepoq, Kutai Timur, Kalimantan Timur. Estimasi waktu perjalan berkisar hingga 150 menit, dari desa Karangan Dalam, mengendarai kendaraan roda 4 menuju pintu masuk lokasi air terjun. Air terjun ini mempunyai dua tingkatan, masing-masing berada di kiri dan kanan hanya berjarak sekitar 30 meter.', 1.361934, 117.8786712, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Kembar%20Siapat%20%281%29.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q139989810', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 2),
  (8359, NULL, 3, 'Curug Anom', 'Jawa Barat', 'Kertawangi, Bandung Barat, Jawa Barat', 'Curug Anom adalah sebuah air terjun yang terletak di Desa Kertawangi, Cisarua, Bandung Barat, Jawa Barat. Air Terjun ini terletak di dalam kawasan wisata Natural Hill. Air terjun ini memiliki ketinggian sekitar 30 meter  dan dikelilingi pepohonan yang rindang.', -6.813178, 107.568904, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anom%20Waterfall%20Right%20Bottom%20View.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q125658184', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8360, NULL, 3, 'Air Terjun Alam Kandung', 'Tanen', 'Tanen, Tulungagung, Jawa Timur', 'Air Terjun Alam Kandung adalah air terjun yang terletak di Kabupaten Tulungagung, Jawa Timur. Air terjun ini memiliki tiga undak air terjun dengan air terjun utama setinggi sekitar 15 meter dan berada di kawasan hutan jati Alas Kandung. Nama lain dari air terjun ini adalah Grojokan Sewu\nAir Terjun Alam Kandung berada di aliran Sungai Kandung yang bersumber dari perbukitan karst selatan Jawa Timur.', -8.1695151, 112.0759166, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20terjun%20Alam%20Kandung.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q125658221', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8361, NULL, 3, 'Air Terjun Cipalasari', 'Jawa Barat', 'Cisarua, Jawa Barat', 'Curug Cipalasari adalah salah satu destinasi wisata alam berupa air terjun yang terletak di Desa Tugumukti, Kecamatan Cisarua, Kabupaten Bandung Barat, Jawa Barat, Indonesia, dengan ketinggian sekitar 80 meter. Air terjun ini menawarkan pemandangan yang asri dan udara yang sejuk, dikelilingi oleh hutan sekunder dan pepohonan hijau yang masih alami.', -6.7815972, 107.5600139, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Cipalasari%20Bottom%20View.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q130616363', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8362, NULL, 3, 'Air Terjun Cimanggu', 'Jawa Barat', 'Cimanggu, Bandung Barat, Jawa Barat', 'Curug Cimanggu adalah sebuah air terjun yang terletak di Kampung Cimanggu Landeuh, RW 11, Desa Cimanggu, Kecamatan Ngamprah, Kabupaten Bandung Barat, Jawa Barat, Indonesia. Air terjun ini merupakan bagian dari sungai Cimanggu yang menjadi anak sungai Citarum. Terletak di koordinat -6.822333, 107.511536, air terjun ini merupakan salah satu destinasi wisata alam tersembunyi yang menawarkan keindahan alam yang masih asri dan belum banyak terjamah oleh wisatawan.', -6.822333, 107.511536, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Cimanggu.jpg?width=800', '2026-11-04 09:38:15', '2026-11-24 23:32:50', 'wd:Q131314851', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8363, NULL, 3, 'Air Terjun Bugbrug', 'Indonesia', 'Cisarua, Jawa Barat', 'Curug Bugbrug adalah air terjun yang terletak di Desa Kertawangi, Kecamatan Cisarua, Kabupaten Bandung Barat, Provinsi Jawa Barat. Curug ini adalah air terjun yang terletak di lahan pertanian warga setempat. "Bugbrug" (ᮘᮥᮌ᮪ᮘᮢᮥᮌ᮪) berasal dari Bahasa Sunda yang berarti "bertumpuk banyak tapi tidak tersusun".', -6.7922202, 107.5801987, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Bugbrug.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q131912205', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8364, NULL, 3, 'Air terjun Coban Putri', 'Malang', 'Lowokwaru, Kota Batu, Jawa Timur', 'Coban Putri merupakan salah satu wisata air terjun yang terletak di Kota Batu, Jawa Timur. Ketinggian air terjun ini berkisar 15-20 meter dan berada di lembah Gunung Panderman. Keistimewaan dari air terjun ini terletak pada tebing bebatuan yang cukup terjal sehingga dapat membuat air yang jatuh menyebar secara indah.', -7.9119895, 112.5302516, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coban%20Putri%2C%20Batu%2C%20Malang.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q135977909', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8365, NULL, 3, 'Air Terjun Putuk Truno', 'Pasuruan', 'Jalan Putuk Truno, Prigen, Jawa Timur', 'Air Terjun Putuk Truno merupakan salah satu wisata air terjun di Pasuruan. Air terjun ini terletak di Jalan Putuk Truno, Kecamatan Prigen, Kabupaten Pasuruan, Provinsi Jawa Timur. Wisata ini berada di kaki Gunung Welirang dan Gunung Arjuno.', -7.687812, 112.635063, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Putuk%20Truno%20Waterfall.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q135977918', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8366, NULL, 3, 'Coban Sanusi', 'Tumpang', 'Duwet, Kabupaten Malang, Jawa Timur', 'Coban Sanusi: Merupakan salah satu Air Terjun yang ada di Tumpang, Kabupaten Malang, Jawa Timur, Indonesia, Tumpang.', -7.9912287, 112.8377924, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coban%20Sanusi%2C%20Tumpang%2C%20Kabupaten%20Malang.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q138313919', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8367, NULL, 3, 'Coban Srikandi', 'Tumpang', 'Duwet, Kabupaten Malang, Jawa Timur', 'Coban Srikandi: Merupakan salah satu Air Terjun yang ada di Tumpang, Kabupaten Malang, Jawa Timur, Indonesia, Tumpang.', -7.9895637, 112.8189455, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coban%20Srikandi%2C%20Tumpang%2C%20Kabupaten%20Malang.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q138313929', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8368, NULL, 3, 'Air terjun Sikarim', 'Jawa Tengah', 'Jalan Rake Panangkaran, Sembungan, Wonosobo, Jawa Tengah', 'Curug Sikarim adalah air terjun yang berada di Dataran Tinggi Dieng di antara Gunung Bisma dan Gunung Sikunir pada ketinggian 1.800 meter di atas permukaan air laut (Mdpl). Air terjun yang berasal dari limpahan Telaga Cebong tersebut mengalir menuruni tebing perbukitan setinggi hampir 90 meter dan jatuh ke Sungai Mlandi. Di kala debit air cukup besar, air terjun tersebut tak hanya menampakkan satu air terjun saja.', -7.24236, 109.90708, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Sikarim.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q12471133', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8369, NULL, 3, 'Air Terjun Sindaro', 'Kebumen', 'Lancar, Kebumen, Jawa Tengah', 'Air Terjun Sindaro atau Curug Sindoro adalah air terjun dengan ketinggian sekira 30 meter yang terletak di Cagar Alam Nasional Geologi Karangsambung. Air Terjun Sindaro mempunyai daya tarik tersendiri, karena lingkungan masih betul-betul alami. Kesunyian juga masih sangat terasa, sebab belum banyak pelancong yang datang menikmati keindahan alamnya sehingga bisa dikatakan masih tersembunyi.', -7.559185, 109.726471, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Sindaro%20Kebumen.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q25464464', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8370, NULL, 3, 'Air terjun Cigamea', 'Indonesia', 'Pamijahan, Jawa Barat', 'Air Terjun Cigamea atau Curug Cigamea merupakan air terjun yang terdapat di wilayah Gunung Bunder, Kecamatan Pamijahan, Kabupaten Bogor. Curug (bahasa sunda) berarti air terjun. Sedangkan Cigamea artinya adalah bergemuruh.', -6.6946825, 106.6863636, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Cigamea.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q109438976', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8371, NULL, 3, 'Air Terjun Sigerincing', 'Tuo', 'Dusun Tuo, Merangin, Jambi', 'Air Terjun Sigerincing adalah air terjun yang setinggi sekira kurang lebih 40-60 meter ini terletak di desa Dusun Tuo, kecamatan Lembah Masurai, kabupaten Merangin, Jambi. Air terjun ini merupakan bagian dari aliran sungai Batang Tembesi yang berhulu di Gunung Masurai.', -2.3783095, 101.9077543, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Sigerincing%20Merangin.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q109440988', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8372, NULL, 3, 'Air Terjun Nglirip', 'Jawa Timur', 'Singgahan, Jawa Timur', 'Air Terjun Nglirip adalah air terjun di Jawa Timur.', -6.9683333, 111.7941667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Air%20Terjun%20Nglirip.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q26739152', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8373, NULL, 3, 'Kanto lampo', 'Gianyar', 'Gianyar, Bali', 'Kanto lampo adalah air terjun di Gianyar.', -8.53234, 115.33298, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanto%20lampo.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q113010681', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8374, NULL, 3, 'Banyu Wana Waterfalls', 'Wanagiri', 'Sukasada, Bali', 'Banyu Wana Waterfalls adalah air terjun di Wanagiri.', -8.208996, 115.118366, 2000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Banyu%20Wana%20Amertha%20Waterfall%20SF0001.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q122202594', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
