  (8377, NULL, 3, 'Belong Waterfall', 'Munduk', 'Banjar, Bali', 'Belong Waterfall adalah air terjun di Munduk.', -8.259022, 115.067817, 20000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Belong%20Waterfall%20MRD%2002.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q132195807', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 1),
  (8378, NULL, 3, 'Air Terjun Benang Kelambu', 'Nusa Tenggara Barat', 'Pemotoh, Lombok Tengah, Nusa Tenggara Barat', 'Air Terjun Benang Kelambu: Salah satu air terjun di Nusa Tenggara Barat, Nusa Tenggara Barat.', -8.535994, 116.3430856, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lombok%20-%20Benang%20Kelambu%20Waterfall.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q135977542', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 0),
