  (8381, NULL, 3, 'Air Terjun Proklamator', 'Tanah Datar', 'Jalan Raya Padang Bukittinggi, Air Mancur, Tanah Datar, Sumatera Barat', 'Air Terjun Proklamator: Air terjun di Sumatera Barat, Indonesia, Tanah Datar.', -0.4813409, 100.3393426, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pesona%20Air%20Terjun%20Proklamator.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q135979780', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 0),
  (8382, NULL, 3, 'Curug Tilu Leuwi Opat', 'Bandung', 'Cisarua, Jawa Barat', 'Curug Tilu Leuwi Opat: Air terjun di Jawa Barat, Bandung.', -6.7906923, 107.5819927, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curug%20Aseupan.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q136435244', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 0),
