  (8384, NULL, 3, 'Tukad Cepung Waterfall', 'Bangli', 'Tembuku, Bali', 'Tukad Cepung Waterfall adalah air terjun di Bangli.', -8.44233, 115.3879, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tukad%20Cepung%20Waterfall%20%2852462237566%29.jpg?width=800', '2026-11-04 09:38:16', '2026-11-24 23:32:50', 'wd:Q124343186', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Air terjun', 0),
  (8385, NULL, 3, 'Danau Matano', 'Sulawesi Selatan', 'Nuha, Luwu Timur, Sulawesi Selatan', 'Danau Matano adalah sebuah danau tektonik dengan ukuran panjang 28 kilometer dan lebar 8 kilometer di Sulawesi Selatan, tepatnya berada di ujung timur provinsi Sulawesi Selatan, berbatasan dengan Sulawesi Tengah. Danau ini berada sekitar 50 km dari kota Malili (Ibu kota Kabupaten Luwu Timur).\nDanau ini memiliki kedalaman sejauh 625 meter (1.969 kaki).', -2.4714, 121.3298, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Matano%20Sunset.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q2417904', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 26),
  (8386, NULL, 3, 'Danau Poso', 'Sulawesi Tengah', 'Tolambo, Sulawesi Tengah', 'Danau Poso (bahasa Inggris: Poso Lake), merupakan sebuah danau yang terletak di Kabupaten Poso, Provinsi Sulawesi Tengah, Indonesia; dan merupakan danau terdalam ketiga di Indonesia. Danau ini memiliki panjang 32 km dan lebar 16 km.\nFestival Danau Poso diadakan di Tentena, kota di pinggir danau ini.', -1.97955, 120.6601, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20poso%20scene-sulawesi%20tengah-indonesia.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q29503', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 22),
  (8387, NULL, 3, 'Danau Maninjau', 'Sumatera Barat', 'Sungai Batang, Agam, Sumatera Barat', 'Danau Maninjau (berarti "pemandangan" atau "peninjauan" dalam bahasa Minangkabau) adalah sebuah danau kaldera di Tanjung Raya, Kabupaten Agam, Sumatera Barat, Indonesia. Danau ini terletak sekitar 140 kilometer (87 mi) sebelah utara Padang, ibu kota Sumatera Barat, 36 kilometer (22 mi) dari Bukittinggi, 27 kilometer (17 mi) dari Lubuk Basung, ibu kota Kabupaten Agam.', -0.3166667, 100.2, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/LakeManinjau1.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q177526', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 21),
  (8388, NULL, 3, 'Danau Towuti', 'Sulawesi Selatan', 'Luwu Timur, Sulawesi Selatan', 'Danau Towuti adalah sebuah danau yang terletak di Sulawesi Selatan, Indonesia. Secara administratif, danau ini terletak di Kecamatan Towuti, Kabupaten Luwu Timur, Provinsi Sulawesi Selatan. Danau ini memiliki lima pulau di tengah danau yang di antaranya yaitu Pulau Loeha, Pulau Bolong, dan Pulau Kembar.', -2.76258, 121.52232, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Towuti%20Danau%202019-09-09%20Sentinel%202%20SR.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q2516473', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 17),
  (8389, NULL, 3, 'Danau Singkarak', 'Sumatera Barat', 'Batu Taba, Tanah Datar, Sumatera Barat', 'Danau Singkarak adalah sebuah danau yang membentang di dua Kabupaten yang terdapat di Provinsi Sumatera Barat, Indonesia, yaitu Kabupaten Solok dan Kabupaten Tanah Datar.\nDanau ini memiliki luas 107,8 km² dan merupakan danau terluas ketiga di pulau Sumatra setelah Danau Ranau di Sumatera Selatan dengan Lampung dan Danau Toba di Sumatera Utara. Danau ini merupakan hulu dari sungai atau Batang Ombilin.', -0.6135, 100.5393, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Singkarak.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q2541128', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 17),
  (8390, NULL, 3, 'Danau Batur', 'Bali', '6, Kintamani, Bali', 'Danau Batur adalah danau kawah di Kintamani, Kabupaten Bangli di Bali, terletak sekitar 30 km (19 mi) di timur laut Ubud di Bali. Danau itu berada di dalam kaldera gunung berapi aktif, Gunung Batur, terletak di sepanjang, aktivitas vulkanis Cincin Api Pasifik.', -8.2569, 115.4088, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Batur%20%26%20Mount%20Abang%202013-11-10%20%2810849153196%29.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q13511216', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 17),
  (8391, NULL, 3, 'Situ Gintung', 'Tangerang Selatan', 'Ciputat Timur, Tangerang Selatan, Banten', 'Situ Gintung adalah danau kecil buatan yang terletak di Kecamatan Ciputat Timur, Kota Tangerang Selatan, Provinsi Banten. Lokasi danau ini berada di sebelah barat daya kota Jakarta. Situ Gintung mengalami penyusutan luas dari 31 hektare menjadi 21,4 hektare akibat pendangkalan dan urbanisasi.', -6.3053, 106.7622, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Gintung%202014.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q578708', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 16),
  (8392, NULL, 3, 'Danau Sentani', 'Papua', 'Yoboy, Jayapura, Papua', 'Danau Sentani adalah danau yang terletak di Pulau Papua, Indonesia. Danau Sentani berada di bawah lereng selatan Pegunungan Cycloop yang merupakan Cagar Alam Pegunungan Cycloop dengan luas mencapai 22.500 ha (225 km2). Danau ini terbentang antara Kabupaten Jayapura dan Kota Jayapura, Provinsi Papua, Indonesia.', -2.6122, 140.5172, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sentani%20Lake.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q59058', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 16),
  (8393, NULL, 3, 'Danau Tondano', 'Sulawesi Utara', 'Minahasa, Telap, Sulawesi Utara', 'Danau Tondano adalah danau terluas di Provinsi Sulawesi Utara, Indonesia. Danau ini diapit oleh Pegunungan Lembean, Gunung Kaweng, Bukit Tampusu, dan Gunung Masarang. Danau ini dilingkari dengan jalan provinsi dan menghubungkan Kota Tondano, Kecamatan Tondano Timur, Kecamatan Eris, Kecamatan Kakas, Kecamatan Remboken, dan Kecamatan Tondano Selatan.', 1.225, 124.9, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Tondano.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q1159279', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 15),
  (8394, NULL, 3, 'Danau Tamblingan', 'Banjar', 'Banjar, Bali', 'Danau Tamblingan (Aksara Bali: ᬤᬦᬸᬢ​ᬫ᭄​ᬩ᭄ᬮᬶᬗᬦ᭄, Danu Tamblingan) adalah sebuah danau yang terletak di lereng sebelah utara Gunung Lesung, kawasan Desa Munduk, Kecamatan Banjar, Kabupaten Buleleng, Bali. Danau ini merupakan satu dari tiga danau kembar yang terbentuk di dalam sebuah kaldera besar. Di sebelah timur berturut-turut terdapat Danau Buyan dan Danau Beratan.', -8.257056, 115.097003, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Tamblingan.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q17999895', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 14),
  (8395, NULL, 3, 'Danau Tempe', 'Sulawesi Selatan', 'Salomenraleng, Wajo, Sulawesi Selatan', 'Danau Tempe adalah danau tektonik yang membentang di tiga kabupaten di Sulawesi Selatan, di antaranya Wajo, Sidenreng Rappang, dan Soppeng. Danau ini dianggap sebagai danau purba karena terbentuknya danau ini bersamaan dengan terbentuknya daratan Sulawesi yang berada di atas lempeng benua Australia dan Asia. Luasnya sekitar 350 km2 dan menjadikannya sebagai danau terluas kedua di Sulawesi.', -4.1178, 119.9527, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sengkang%27s%20Floating%20Village%20scenery.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q3178248', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 13),
  (8396, NULL, 3, 'Ranu Kumbolo', 'Lumajang', 'Lumajang, Jawa Timur', 'Ranu Kumbolo (bahasa Indonesia: Danau Kumbolo) adalah sebuah danau kawah (maar) di Kecamatan Pasrujambe, Kabupaten Lumajang yang terletak di dalam Taman Nasional Bromo Tengger Semeru (TNBTS), Jawa Timur, Indonesia.  Danau ini merupakan bagian dari rute termudah pendakian yang berawal dari Ranu Pani menuju puncak Gunung Semeru.', -8.05, 112.9166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ranu%20Kumbolo.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q901605', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 12),
  (8397, NULL, 3, 'Segara Anak', 'Lombok Utara', 'Lombok Utara, Nusa Tenggara Barat', 'Segara Anak adalah danau yang ada di kawah Gunung Rinjani, tepatnya di daerah Desa Sembalun Lawang, Lombok Timur, Nusa Tenggara Barat, Indonesia. Nama Segara Anak memiliki arti "anak laut" dalam bahasa Sasak. Danau ini terletak pada ketinggian kurang lebih 2.000 mdpl.', -8.4042, 116.4004, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20rinjani.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q2173175', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 12),
  (8398, NULL, 3, 'Danau Ranau', 'Lampung', 'Desa Ujung, Lampung', 'Danau Ranau adalah danau terbesar kedua di Sumatra setelah Danau Toba. Danau ini terletak di perbatasan Kabupaten Ogan Komering Ulu Selatan Provinsi Sumatera Selatan dan Kabupaten Lampung Barat Provinsi Lampung. Danau ini tercipta dari gempa besar dan letusan vulkanik dari gunung berapi yang membuat cekungan besar.', -4.8674, 103.93226, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Ranau.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q3114099', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 11),
  (8399, NULL, 3, 'Danau Laut Tawar', 'Aceh Tengah', 'Telukone-one, Aceh Tengah, Aceh', 'Danau Lut Tawar adalah sebuah danau dan kawasan wisata yang terletak di Dataran Tinggi Gayo, Kabupaten Aceh Tengah, Aceh. Disisi barat danau ini terdapat sebuah kota kabupaten yaitu kota Takengon, yang juga merupakan ibu kota Kabupaten Aceh Tengah. Suku Gayo menyebut danau ini dengan sebutan Danau Lut Tawar.', 4.6112, 96.9267, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Laut%20Tawar.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q3124736', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 10),
  (8400, NULL, 3, 'Danau Gunung Tujuh', 'Gunung Tujuh', 'Kerinci, Jambi', 'Danau Gunung Tujuh merupakan danau yang terletak di desa Pelompek, kabupaten Kerinci, Jambi. Danau ini berada di kawasan Gunung Tujuh, sebuah gunung yang berada tepat di belakang Gunung Kerinci. Gunung Tujuh masih termasuk dalam wilayah Taman Nasional Kerinci Seblat yang merupakan Situs Warisan Dunia UNESCO.\nSeperti namanya, danau gunung tujuh dikelilingi tujuh puncak gunung di Jambi.', -1.7, 101.41667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tujuh1.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q3449734', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 9),
  (8401, NULL, 3, 'Danau Kawah Ijen', 'Banyuwangi', 'Bondowoso, Jawa Timur', 'Danau Kawah Ijen: Danau sulfur di Jawa Timur, Indonesia, Banyuwangi.', -8.0575, 114.2415, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kawah%20ijen%2C%20Pesona%20yang%20beracun.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q97241059', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 9),
  (8402, NULL, 3, 'Danau Linouw', 'Sulawesi Utara', 'Jalan Linow, Minahasa, Tomohon, Sulawesi Utara', 'Danau Linouw (atau Linow) adalah sebuah danau vulkanik yang terletak di kota Tomohon, Sulawesi Utara, Indonesia. Beberapa lubang hidrotermal memuntahkan gas panas dari tepi dan kedalaman danau. Komposisi kimiawi yang berubah dari danau berarti warnanya sering berubah warna, mulai dari merah, hijau tua, dan bahkan biru gelap.', 1.2708331, 124.8263889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danu%20Linow.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q1159276', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8403, NULL, 3, 'Rawa Pening', 'Semarang', 'Tuntang, Jawa Tengah', 'Danau Rawa Pening merupakan danau semi alam yang terletak di Kabupaten Semarang, Jawa Tengah, Indonesia. Membentang di empat kecamatan dalam wilayah Kabupaten Semarang yaitu Ambarawa, Bawen, Tuntang, dan Banyubiru. Danau ini berada di cekungan terendah yang dikelilingi oleh lereng Gunung Merbabu, Gunung Telomoyo, dan Gunung Ungaran, sekitar 40 kilometer ke arah selatan dari Kota Semarang.', -7.2833333, 110.4333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rawa%20Pening%20Central%20Java.jpg?width=800', '2026-11-04 09:38:50', '2026-11-24 23:32:50', 'wd:Q3140328', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8404, NULL, 3, 'Ranu Pani', 'Jawa Timur', 'Ranupane, Lumajang, Jawa Timur', 'Ranu Pani atau Ranupanuen adalah sebuah danau vulkanik di Desa Ranu Pani, Kecamatan Senduro, Kabupaten Lumajang, Jawa Timur. Ranu Pani adalah bagian dari Taman Nasional Bromo Tengger Semeru (TNBTS). Semula luas Ranu Pani berkisar satu juta hektare lebih, tetapi kini diperkirakan tinggal 0,75 hektare akibat laju sedimentasi yang cepat.', -8.0127778, 112.9461111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ranu%20Pani%2C%20semeru.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q3419038', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8405, NULL, 3, 'Danau Diatas', 'Solok', 'Simpang Tanjung Nan IV, Solok, Sumatera Barat', 'Danau Diatas adalah sebuah danau yang terletak di nagari Alahan Panjang, kecamatan Lembah Gumanti, kabupaten Solok, provinsi Sumatera Barat, Indonesia. Danau ini bersama-sama dengan Danau Dibawah, yang dikenal sebagai Danau Kembar.', -1.0781, 100.7543, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Diatas.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q3077365', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8406, NULL, 3, 'Situ Patenggang', 'Rancabali', 'Rancabali, Jawa Barat', 'Situ Patenggang atau Patengan adalah sebuah danau pegunungan yang terletak di kawasan taman wisata alam di Rancabali, Jawa Barat, Indonesia. Situ Patengan memiliki luas perairan sekitar 46,6 hektar (0,466 km²) dan berada di ketinggian kurang lebih 1.600 meter di atas permukaan laut.\nDanau ini menawarkan panorama alam pegunungan yang dikelilingi oleh perkebunan teh dan hutan tropis, menjadikannya salah satu destinasi ekowisata favorit di kawasan Bandung Selatan.', -7.1669444, 107.3580556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Junghuhn%20Telaga%20Patengan.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q5246981', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8407, NULL, 3, 'Danau Kerinci', 'Kerinci', 'Telago, Kerinci, Jambi', 'Danau Kerinci merupakan sebuah danau yang terletak di kabupaten Kerinci, provinsi Jambi, Indonesia. Danau ini memiliki luas wilayah 5.000 meter persegi dengan memiliki ketinggian 783 meter di atas permukaan laut. Danau yang terletak di kaki Gunung Rayo ini merupakan danau terbesar yang ada di kabupaten Kerinci, luasnya adalah 4.200 hektare.', -2.146, 101.4882, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meer%20van%20Kerintji%20bij%20Soengaipenoeh%2C%20KITLV%2015435.tiff?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480811', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 8),
  (8408, NULL, 3, 'Danau Dibawah', 'Sumatera Barat', 'Kampung Batu Dalam, Solok, Sumatera Barat', 'Danau Dibawah atau biasa juga disebut Danau Bawah adalah salah satu dari dua danau kembar di Kabupaten Solok, Sumatera Barat. Danau ini dipisahkan oleh sebuah bukit dengan kembarannya, Danau Diatas, dan berjarak sekitar 300 meter. Danau dengan luas 16,9 km2 ini memiliki panjang 5,62 kilometer dan lebar 3,00 kilometer.', -1.0105556, 100.7294444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Dibawah.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q3077052', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 7),
  (8409, NULL, 3, 'Situ Lembang', 'Jawa Barat', 'Bandung Barat, Jawa Barat', 'Situ Lembang (Aksara Sunda Baku: ᮞᮤᮒᮥ ᮜᮦᮙ᮪ᮘᮀ, Situ Lémbang) adalah sebuah danau yang terletak di Kabupaten Bandung Barat, Jawa Barat. Danau yang terletak ini berada di ketinggian 1574 m, dan memiliki luas sebesar 0,40 km2.\nSitu Lembang adalah danau yang dikelilingi pegunungan yang terletak di ketinggian dan dibangun oleh Belanda abad ke-20 tepatnya pada tahun 1912.', -6.7402778, 107.5766667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Geese%20in%20Situ%20Lembang.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q19728388', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 7),
  (8410, NULL, 3, 'Setu Babakan', 'Jakarta', 'Jalan Setu Babakan Timur, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Setu Babakan atau Situ Babakan adalah suatu cagar budaya yang terletak di Srengseng Sawah, Kecamatan Jagakarsa, Jakarta Selatan. Situ berarti \'danau\' dalam bahasa Sunda, sedangkan babakan berarti \'kampung baru\'. Penamaan ini disebabkan oleh fakta Situ Babakan diapit oleh tiga buah danau.', -6.341667, 106.823889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Setu%20Babakan.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q4262949', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 7),
  (8411, NULL, 3, 'Danau Bratan', 'Bali', 'Baturiti, Bali', 'Danau Bratan (aksara Bali: ᬤᬦᬸᬩ᭄ᬭᬢᬦ᭄) adalah sebuah danau yang terletak di kawasan Bedugul, Desa Candikuning, Kecamatan Baturiti, Kabupaten Tabanan, Bali. Danau yang terletak paling timur di antara dua danau lainnya yaitu Danau Tamblingan dan Danau Buyan, yang merupakan gugusan danau kembar di dalam sebuah kaldera besar, Danau Bratan terbilang cukup istimewa.\nBerada di jalur jalan provinsi yang menghubungkan Denpasar-Singaraja serta letaknya yang dekat dengan Kebun Raya Eka Karya menjadikan tempat ini menjadi salah satu andalan wisata pulau Bali.', -8.2722222, 115.1741667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ulun%20Danu%20Temple%2C%20Bali%3B%20June%202008.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480805', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 7),
  (8412, NULL, 3, 'Danau Lindu', 'Tomado', 'Tomado, Sulawesi Tengah', 'Danau Lindu merupakan danau yang terletak di Kecamatan Lindu, Kabupaten Sigi, Provinsi Sulawesi Tengah, Indonesia dan berada di dalam Taman Nasional Lore Lindu. Luasnya mencapai 34,88 km² dengan kedalaman maksimum 72,6 meter, kedalaman rata-rata 38 meter dan berada di ketinggian sekitar 1.000 meter di atas permukaan laut. Danau Lindu adalah danau terbesar ke delapan di Pulau Sulawesi dan kedua di Provinsi Sulawesi Tengah setelah Danau Poso.', -1.3187, 120.0809, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Lindu%20w%20bird%202007.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q3215011', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8413, NULL, 3, 'Waduk Saguling', 'Bandung Barat', 'Cangkorah, Bandung Barat, Jawa Barat', 'Waduk Saguling (aksara Sunda: ᮝᮓᮥᮊ᮪ ᮞᮍᮥᮜᮤᮀ) adalah sebuah waduk yang terletak di Kabupaten Bandung Barat, Provinsi Jawa Barat pada ketinggian 643 m di atas permukaan laut. Waduk ini adalah salah satu dari tiga waduk yang membendung aliran Sungai Citarum yang merupakan sungai terbesar di Jawa Barat. Dua waduk lainnya adalah Waduk Jatiluhur dan Waduk Cirata.', -6.9194444, 107.3816667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saguling%20Lake.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q2885450', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8414, NULL, 3, 'Danau Tambing', 'Poso', 'Sulawesi Tengah', 'Danau Tambing (bahasa Pamona: Rano Kalimpa\'a, Rano Tambing), adalah sebuah danau yang terletak di desa Sedoa, Lore Utara, Kabupaten Poso. Danau ini terletak pada ketinggian sekitar 1.700 meter dari permukaan laut. Danau Tambing merupakan salah satu bagian dari wilayah Taman Nasional Lore Lindu.', -1.3275, 120.3072, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Tambing%2C%20October%202016.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q27321535', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8415, NULL, 3, 'Danau Sidihoni', 'Samosir', 'Sabungan Nihuta, Samosir, Sumatera Utara', 'Danau Sidihoni (bahasa Batak Toba: Tao Sidihoni) adalah sebuah danau yang terletak di Kecamatan Ronggur Nihuta, Kabupaten Samosir, Sumatera Utara. Oleh karena berada di atas Pulau Samosir, Danau Sidihoni disebut sebagai "danau di atas danau" (di atas Danau Toba). Danau Sidihoni berjarak 8 kilometer dari Pangururan.', 2.6014833, 98.7447639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bagian%20sebelah%20kanan%20dari%20Danau%20Sidihoni.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q6477773', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8416, NULL, 3, 'Danau Aneuk Laot', 'Sabang', 'Sukakarya, Sabang, Aceh', 'Danau Aneuk Laot ("Danau Anak Laut" dalam bahasa Aceh) adalah sebuah danau yang terletak di tengah-tengah kota Sabang, Pulau Weh. Danau ini merupakan sumber mata air bagi penduduk Pulau Weh.\nSecara historis Danau Aneuk Laot merupakan danau yang berasal dari bekas kepundan gunung berapi yang telah mati, dan secara perlahan dan terus menerus kepundan ini terisi oleh air hujan sehingga membentuk sebuah ‘danau;’\nDanau ini tidak memiliki inlet dalam bentuk aliran sungai namun memiliki outlet dalam bentuk rembesan dan aliran air melalui celah atau rengkahan batuan dasar danau.', 5.86944, 95.32806, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Gezicht%20over%20het%20meer%20Aneuklaot%20en%20de%20Sabang-baai%20TMnr%2010018578.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480802', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8417, NULL, 3, 'Danau Limboto', 'Gorontalo', 'Buhu, Gorontalo, Gorontalo', 'Danau Limboto adalah sebuah danau yang terletak di Kecamatan Limboto, Kabupaten Gorontalo, Provinsi Gorontalo, Indonesia. Danau dengan luas 208 km² ini merupakan danau yang terbesar di Gorontalo. Secara administratif letak danau 30 persen di wilayah Kota Gorontalo dan 70 persen berada di Kabupaten Gorontalo.', 0.5847222, 122.9863889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menjaring%20asa.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480815', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 6),
  (8418, NULL, 3, 'Waduk Malahayu', 'Jawa Tengah', 'Melahayu, Brebes, Jawa Tengah', 'Waduk Malahayu adalah sebuah waduk yang dibangun di dekat perbatasan Jawa Tengah dan Jawa Barat, tepatnya di Kecamatan Banjarharjo, Kabupaten Brebes, Provinsi Jawa Tengah, Indonesia. Awalnya, waduk ini menggenangi sebagian wilayah Desa Malahayu, Desa Cipajang, dan Desa Penanggapan, tetapi karena pendangkalan, kini secara umum waduk ini hanya menggenangi sebagian wilayah Desa Malahayu, yang juga menjadi lokasi bendungan utamanya. Waduk Malahayu berjarak ± 6 km dari pusat Kecamatan Kecamatan Banjarharjo atau 17 km dari Kecamatan Tanjung.', -7.0363889, 108.8077778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waduk%20Malahayu.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q40445', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 5),
  (8419, NULL, 3, 'Situ Lengkong', 'Jawa Barat', 'Panjalu, Jawa Barat', 'Situ Lengkong, juga disebut Situ Lengkong Panjalu, (Aksara Sunda Baku: ᮞᮤᮒᮥ ᮜᮦᮀᮊᮧᮀ ᮕᮔ᮪ᮏᮜᮥ, Situ Léngkong Panjalu) adalah suatu danau (situ dalam bahasa Sunda) yang terletak di Kecamatan Panjalu, Kabupaten Ciamis, Jawa Barat, Indonesia. Luas permukaan danau ini adalah 58 hektar. Di tengah danau terdapat sebuah pulau yang bernama Pulau Nusa Gede.', -7.1275, 108.2725, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Het%20Pendjaloe%20meer.%20TMnr%2060002480.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12515553', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 5),
  (8420, NULL, 3, 'Rawa Jombor', 'Indonesia', '187, Krakitan, Klaten, Jawa Tengah', 'Rawa Jombor (bahasa Jawa: ꦫꦮꦗꦺꦴꦩ꧀ꦧꦺꦴꦂ, translit. Rawa Jombor) adalah sebuah waduk yang seluruh wilayahnya terletak di Desa Wisata Krakitan, Kecamatan Bayat, sekitar delapan kilometer ke arah tenggara dari pusat Kota Klaten, Jawa Tengah, Indonesia. Selain untuk mengairi lahan pertanian di sekitarnya, waduk ini juga dimanfaatkan sebagai objek pariwisata.', -7.74944, 110.62639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Jombor.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25080518', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 4),
  (8421, NULL, 3, 'Situ Buleud', 'Purwakarta', 'Purwakarta, Jawa Barat', 'Situ Buleud adalah danau yang berbentuk bulat seluas empat hektar yang terletak di Kelurahan Nagrikidul, Kabupaten Purwakarta yang dibangun pada tahun 1830–1831 atas prakarsa dari bupati RA Suriawinata.', -6.5569444, 107.4461111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Buleud%2003.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25165526', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 4),
  (8422, NULL, 3, 'Danau Tasikardi', 'Serang', 'Jalan Kenari, Kasemen, Kab Serang, Banten', 'Danau Tasikardi adalah suatu danau buatan di Desa Margasana, Kecamatan Kramatwatu, Kota Serang, Provinsi Banten, sekaligus menjadi salah satu cagar budaya peninggalan masa pemerintahan Sultan Maulana Yusuf yang ditetapkan secara resmi pada tahun 1998. Letaknya sekitar 10 km dari pusat kota Serang. Namanya berasal dari bahasa Sunda Kuno yang berarti \'danau buatan\'.', -6.0538889, 106.1433333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Tasikardi-5.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480830', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 4),
  (8423, NULL, 3, 'Situ Tonjong', 'Tajurhalang', 'Tajurhalang, Jawa Barat', 'Situ Tonjong adalah situ (danau kecil) terletak di Kecamatan Tajur Halang, Kabupaten Bogor, Jawa Barat. Letaknya di pinggir jalan raya Desa Tonjong, perbatasan antara Kecamatan Bojonggede dan Kecamatan Tajur Halang. Letak situ ini di wilayah kabupaten, sekitar 15 kilometer dari pusat Kota Bogor, Jawa Barat Lingkungannya cukup tenang dan pemandangannya menyejukkan karena dikelilingi pepohonan yang rindang.', -6.4936111, 106.7661111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20tonjong.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24828063', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8424, NULL, 3, 'Situ Kemang', 'Kemang', 'Kemang, Jawa Barat', 'Situ Kemang adalah situ (danau kecil) yang terletak di Kecamatan Kemang, Kabupaten Bogor, Jawa Barat. Letaknya tidak jauh dari jalan raya Parung-Bogor, dekat dengan Pusat Pendidikan dan Latihan Pegawai Kementerian Perhubungan Republik Indonesia. Berdasarkan data dari Balai Besar Wilayah Sungai Ciliwung Cisadane, luas Situ Kemang sekitar 29.44 Ha.', -6.4972222, 106.7472222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Kemang.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24895444', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8425, NULL, 3, 'Situ Cikaret', 'Jawa Barat', 'Cibinong, Jawa Barat', 'Situ cikaret adalah danau kecil (situ) yang terletak di Kecamatan Cibinong, Kabupaten Bogor, Provinsi Jawa Barat, Indonesia. Letaknya tidak jauh dari Rumah Sakit Umum Daerah(RSUD) Cibinong. Situ Cikaret berada di ketinggian 120 meter dpl.', -6.4688889, 106.8352778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20cikaret.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24989888', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8426, NULL, 3, 'Situ Cibinong', 'Cirimekar', 'Cibinong, Jawa Barat', 'Situ Cibinong (nama lain: Situ Citatah) merupakan situ (danau kecil) yang terdapat di Cirimekar, Cibinong, Bogor, Jawa Barat, Indonesia. Situ ini letaknya di pinggir jalan raya Mayor Oking akses Cibinong-Citeureup, dekat pasar tradisional Cibinong, kurang lebih 40 km dari Jakarta.\nSitu ini sebagaimana situ-situ lain di Kabupaten Bogor, berfungsi sebagai tempat penyimpanan (reservoir) air.', -6.4694444, 106.8569444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20cibinong.png?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25027163', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8427, NULL, 3, 'Situ Cikumpay', 'Purwakarta', 'Purwakarta, Jawa Barat', 'Situ Cikumpay: Struktur cagar budaya di Purwakarta, danau di Indonesia, Purwakarta.', -6.46972, 107.50639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Cikumpay.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25173945', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8428, NULL, 3, 'Danau Sipin', 'Jambi', 'Solok Sipin, Jambi, Jambi', 'Danau Sipin adalah salah satu danau yang ada di Kota Jambi. Danau Sipin merupakan sebuah fenomena alam yang menarik yang terbentuk berkat topologi unik sungai Batanghari. Fenomena ini terjadi ketika aliran sungai Batanghari mengalami perubahan bentuk yang disebut "ladam\' atau oxbow lake dalam terminologi topografi.', -1.5988889, 103.5797222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Sipin%202.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q31929115', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8429, NULL, 3, 'Danau Weekuri', 'Indonesia', 'Tambolaka, Nusa Tenggara Timur', 'Danau Weekuri adalah danau air asin yang terletak di Desa Kalena rongo, Kecamatan Kodi Utara, Kabupaten Sumba Barat Daya, Nusa Tenggara Timur. Danau Weekuri terletak sekitar 60 kilometer dari ibu kota kabupaten, Tambolaka.\nNama Weekuri berasal dari bahasa Sumba wee yang berarti air dan kuri yang berarti parutan atau percikan.', -9.49107, 118.96006, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Weekuri%20Lagoon.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q56392783', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8430, NULL, 3, 'Sanghyang Heuleut', 'Bandung Barat', 'Bandung Barat, Jawa Barat', 'Sanghyang Heuleut (aksara Sunda: ᮞᮀᮠᮡᮀ ᮠᮩᮜᮩᮒ᮪) tempat wisata di Rajamandala Kulon, Cipatat, Kabupaten Bandung Barat, Jawa Barat. Tempat ini berada di dalam kawasan PLTA Saguling. Sanghyang Heuleut berupa telaga kecil sedalam tiga meter yang airnya berasal dari Sungai Citarum.', -6.8764359, 107.3417601, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanghyang%20Heuleut%20Lake%20Is%20Hidden%20Paradise%20at%20West%20Java.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q65344278', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8431, NULL, 3, 'Danau Jempang', 'Kalimantan Timur', 'Pulau Lanting, Kutai Barat, Kalimantan Timur', 'Danau Jempang merupakan sebuah danau yang terletak di provinsi Kalimantan Timur, Indonesia, tepatnya di Kabupaten Kutai Barat. Danau ini memiliki luas wilayah 15.000 hektare dengan kedalaman 7-8 meter. Danau Jempang merupakan salah satu danau yang terbesar dari sekitar 76 danau yang tersebar di daerah aliran sungai Mahakam.', -0.4377778, 116.1913889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jempangbird.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480810', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8432, NULL, 3, 'Danau Cangkuang', 'Jawa Barat', 'Leles, Garut, Jawa Barat', 'Danau Cangkuang adalah sebuah danau yang terletak di wilayah Kecamatan Leles, Kabupaten Garut. Wilayah Danau Cangkuan terdiri dari perairan berbentuk sungai dan tiga pulau berukuran kecil. Pulau-pulau di Danau Cangkuang dihuni oleh penduduk Desa Cangkuang dan dikelola menjadi permukiman, pemakaman dan persawahan.', -7.1061111, 107.9213889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Cangkuang%2C%20Leles%2C%20Garut%2C%20Indonesia.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24989506', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 3),
  (8433, NULL, 3, 'Danau Anggi Gida', 'Pegunungan Arfak', 'Krobut / Kiwot, Pegunungan Arfak, Papua Barat', 'Danau Anggi Gida (dalam sumber lain: Danau Anggi Gita/Giti) adalah sebuah danau pegunungan di ketinggian sekitar 1900 mdpl dengan luas permukaan sekitar 2.500 ha (25 km2). Danau yang terletak di Kabupaten Pegunungan Arfak, Papua Barat ini berdekatan dengan Danau Anggi Giji yang di percaya para suku besar Arfak sebagai danau yang berpasangan. Kedua danau tersebut dipisahkan oleh punggung pegunungan Kobrey yang membentang sepanjang kurang lebih 6 km.', -1.3922222, 133.9652778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anggi%20Gida%20%C5%81%C4%85k%C4%99%2C%20Pegunungan%20Arfak%20Regency%2C%20West%20Papua.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24959467', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8434, NULL, 3, 'Situ Cisaat', 'Purwakarta', 'Purwakarta, Jawa Barat', 'Situ Cisaat: Struktur cagar budaya di Purwakarta, Purwakarta.', -6.45, 107.5333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Cisaat%2010.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24982558', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8435, NULL, 3, 'Danau Tahai', 'Palangka Raya', 'Tumbang Tahai, Palangka Raya, Kalimantan Tengah', 'Danau Tahai terletak di Desa Tahai, Kelurahan Tumbang Tahai, Kecamatan Bukit Batu, Kotamadya Palangka Raya, Provinsi Kalimantan Tengah. Danau ini terletak kurang lebih 30 km dari Kota Palangkaraya menuju ke daerah Sampit. Kata Tahai sendiri berasal dari bahasa Dayak yang berarti danau.', -2.026579, 113.7871831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tahai.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25459705', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8436, NULL, 3, 'Danau Kenali', 'Jambi', 'Buluran Kenali, Jambi, Jambi', 'Danau Teluk adalah salah satu danau yang ada di Kota Jambi. Topologi danau Teluk termasuk jenis perairan umum di daratan Indonesia. Dalam pengelolaannya, danau Teluk  termasuk kedalam wilayah Kawasan Pengelolaan Perikanan Perikanan Perairan Umum Daratan 438.', -1.5878133, 103.566351, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Kenali%20dan%20Liukan%20Sungai%20Batanghari%20dari%20Atas%20Pesawat.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q31928819', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8437, NULL, 3, 'Situ Salabenda', 'Parakanjaya', 'Kemang, Jawa Barat', 'Situ Salabenda adalah salah satu situ (danau kecil) yang terdapat di  Desa Parakan Jaya, Kecamatan Kemang, Kabupaten Kemang, Kabupaten Bogor, Jawa Barat. Terletak tidak jauh dari Jalan raya Parung-Bogor, Parakan Jaya, Semplak, Kemang, Kabupaten Bogor.\nSitu ini merupakan bagian dari situ-situ lain di Kemang (Situ Cilala, Situ Kemang, Situ Jampang Pulo) yang akan dikembangkan perikanan air tawar sebagai urat nadi minapolitan masyarakat Kecamatan Kemang.', -6.5229279, 106.7578911, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Salabenda.png?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q109442220', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8438, NULL, 3, 'Situ Jampang Pulo', 'Jampang', 'Kemang, Jawa Barat', 'Situ Jampang Pulo adalah situ (danau kecil) yang terletak di Desa Jampang, Kecamatan Kemang, Kabupaten Bogor, Jawa Barat. Situ Jampang Pulo kini disulap menjadi tempat pembudidayaan ikan hias. Berbagai kalangan dari pelajar, pemerintah, dan organisasi berdatangan mempelajari teknik pengembangan budi daya ikan hias di Desa Jampang.', -6.4709547, 106.7216628, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Danau%20Pulau%20Indah%20atau%20lebih%20dikenal%20Situ%20Jampang%20Pulo.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q109442843', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8439, NULL, 3, 'Danau Wanayasa', 'Indonesia', NULL, 'Danau Wanayasa terletak di Kecamatan Wanayasa, Kabupaten Purwakarta. Letaknya sekitar 23 km sebelah tenggara Kota Purwakarta. Penduduk setempat menyebutnya Situ Wanayasa (Dalam bahasa Sunda, situ berarti danau).', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20wanayasa%202011.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q12480836', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8440, NULL, 3, 'Danau Linting', 'Kabupaten Deli Serdang', 'Durian IV Mbelang, Kabupaten Deli Serdang, Sumatera Utara', 'Danau Linting adalah danau vulkanik yang terletak di Sinembah Tanjung Muda Hulu, Deli Serdang, Sumatera Utara, Indonesia. Danau ini dikenal karena warna airnya yang khas, yaitu biru kehijauan hingga toska, yang dipengaruhi kandungan belerang di dalamnya.', 3.229677, 98.725719, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Linting%2C%20North%20Sumatra%203.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q136409485', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 2),
  (8441, NULL, 3, 'Danau Kaos', 'Jambi', 'Kaos, Batang Hari, Jambi', 'Danau Kaos: Danau di Pemayung, Batang Hari, Jambi, Jambi.', -1.4775, 103.4058333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaos%20Lake.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24912091', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8442, NULL, 3, 'Danau Rambut Monte', 'Indonesia', 'Krisik, Blitar, Jawa Timur', 'Rambut Monte adalah sebuah tempat di Desa Krisik, Kecamatan Gandusari, Kabupaten Blitar, Jawa Timur. kurang lebih 30 km dari Kota Blitar. Candi yang terdapat di lokasi Rambut Monte ini merupakan tempat pemujaan bagi penganut agama Hindu pada zaman Kerajaan Majapahit.', -7.961861, 112.368444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situs%20Rambut%20Monte%20-%20panoramio.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25469623', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8443, NULL, 3, 'Danau Gunung', 'Indonesia', NULL, 'Danau Gunung (bahasa Sunda: Situ Gunung) adalah danau sisa maar yang terletak di Kec. Kadudampit, Kabupaten Sukabumi. Letak danau ini berada pada ketinggian 1.049 meter di atas permukaan laut.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menjala%20Ikan%20di%20Situ%20Gunung.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q109439290', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8444, NULL, 3, 'Danau Seran', 'Kalimantan Selatan', 'Palam, Banjarbaru, Kalimantan Selatan', 'Danau Seran adalah sebuah danau di Kota Banjarbaru, Provinsi Kalimantan Selatan. Danau ini merupakan kawasan bekas penambangan intan milik PT. Galuh Cempaka yang berlokasi di Kecamatan Landasan Ulin. Aktivitas penambangan di sini sudah tidak dilakukan lagi, tetapi lahan ini masih berstatus milik perusahaan penambangan hingga tahun 2034 mendatang.', -3.49048, 114.79036, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Seran%2C%20Banjarbaru%202.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q133867447', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8445, NULL, 3, 'Situ Cikamar', 'Purwakarta', 'Purwakarta, Jawa Barat', 'Situ Cikamar: Struktur cagar budaya di Purwakarta, Purwakarta.', -6.4478099, 107.5264711, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situ%20Cikamar%2005.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q134987130', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8446, NULL, 3, 'Danau Tamiyang', 'Kalimantan Selatan', NULL, 'Danau Tamiyang: Tempat wisata di Kalimantan Selatan, Kalimantan Selatan.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Tamiyang%2C%20Kabupaten%20Banjar%202.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q135911993', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8447, NULL, 3, 'Large Tolire Lake', 'Indonesia', 'Takome, Ternate, Maluku Utara', 'Large Tolire Lake adalah danau di Indonesia.', 0.83584, 127.3075, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Tolire.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q24829565', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8448, NULL, 3, 'Danau Agung', 'Jakarta', 'Jalan Danau Sunter Barat, Tanjung Priok, Jakarta Utara', 'Danau Agung adalah danau di Jakarta.', -6.1455556, 106.8816667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Sunter%20-%20panoramio.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q25068693', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8449, NULL, 3, 'Danau Ranamese', 'Manggarai Timur', 'Golo Loni, Manggarai Timur, Nusa Tenggara Timur', 'Danau Rana Mese atau Ranamese adalah sebuah danau vulkanik yang terletak di Desa Golo Loni, Kecamatan Ranamese, Kabupaten Manggarai Timur, Nusa Tenggara Timur (NTT), Indonesia. Danau ini berada dalam kawasan Taman Wisata Alam (TWA) Ruteng yang memiliki luas sekitar 32.245,6 hektar, menjadikannya salah satu TWA terluas di Indonesia. Danau Ranumese berada di  ketinggian sekitar 1.200 meter di atas permukaan laut (mdpl) dan dikelilingi oleh hutan hujan tropis yang lebat.', -8.63896, 120.56147, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bentang%20alam%20Danau%20Ranamese.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q138319267', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8450, NULL, 3, 'Danau Taman Hidup', 'Krucil', 'Jalur Pendakian Gn Argopuro via Bremi, Krucil, Jawa Timur', 'Danau Taman Hidup merupakan danau yang ada di jalur pendakian Gunung Argopuro. Lokasinya masuk wilayah Desa Kalianan, Kecamatan Krucil, Kabupaten Probolinggo. Danau ini terletak di ketinggian 1.980 mdpl.', -7.97806, 113.53415, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Taman%20Hidup.png?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q138319265', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 1),
  (8451, NULL, 3, 'Danau Laut Tinggal', 'Ujung Gading', 'Pasaman Barat, Sumatera Barat', 'Danau Laut Tinggal: Sisa kaldera dari Gunung Malintang purba, Ujung Gading.', 0.477455, 99.659966, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Laut%20Tinggal.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q135977947', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 0),
  (8452, NULL, 3, 'Danau Malawen', 'Kalimantan Tengah', 'Pamait, Barito Selatan, Kalimantan Tengah', 'Danau Malawen adalah danau di Kalimantan Tengah.', -1.6887666, 114.8794614, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Malawen.jpg?width=800', '2026-11-04 09:38:51', '2026-11-24 23:32:50', 'wd:Q137849180', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Danau', 0),
  (8453, NULL, 3, 'Taman Nasional Bogani Nani Wartabone', 'Gorontalo', 'Pangkusa, Bolaang Mongondow Selatan, Sulawesi Utara', 'Taman Nasional Bogani Nani Wartabone adalah salah satu taman nasional yang ada di Indonesia. Penetapannya secara resmi berlaku pada tahun 1991. Lahan yang ditempatinya  terletak di Semenanjung Utara, Sulawesi, perbatasan antara provinsi Gorontalo dengan Sulawesi Utara.', 0.5605556, 123.68, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Babirusa%20Mainunggu.jpg?width=800', '2026-11-04 09:38:55', '2026-11-24 23:32:50', 'wd:Q1426210', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Taman nasional', 17),
  (8454, NULL, 3, 'Taman Nasional Tesso Nilo', 'Riau', 'Pelalawan, Riau', 'Taman Nasional Tesso Nilo adalah sebuah taman nasional di Kabupaten Pelalawan, Riau, Indonesia. Di dalamnya terdapat sedikitnya 360 jenis flora, 107 jenis burung, 50 jenis ikan, 23 jenis mamalia, 18 jenis amfibi, 15 jenis reptil dan 3 jenis primata. Ekosistemnya termasuk hutan hujan tropika yang menjadi kawasan perlindungan gajah berjumlah 60-80 ekor gajah.', -0.166667, 101.75, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tesso%20Nilo%202009.jpg?width=800', '2026-11-04 09:38:55', '2026-11-24 23:32:50', 'wd:Q1651472', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Taman nasional', 17),
  (8455, NULL, 3, 'Taman Nasional Gunung Merbabu', 'Jawa Tengah', 'Selo, Jawa Tengah', 'Taman Nasional Gunung Merbabu (TNGMb) merupakan taman nasional yang mencakup kawasan hutan di Gunung Merbabu. Secara administratif, taman nasional ini termasuk ke dalam wilayah 3 (tiga) kabupaten yaitu Kabupaten Boyolali, Kabupaten Magelang, dan Kabupaten Semarang, provinsi Jawa Tengah. Secara geografis Taman Nasional Gunung Merbabu terletak antara 110º26’22” Bujur Timur dan 7º27’13” Lintang Selatan.', -7.5, 110.4, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20Merbabu%20dari%20Kota%20Salatiga%20%281%29.jpg?width=800', '2026-11-04 09:38:55', '2026-11-24 23:32:50', 'wd:Q2325342', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Taman nasional', 5),
  (8456, NULL, 3, 'Puncak Ratu', 'Pamekasan', 'Tebul Barat, Pamekasan, Jawa Timur', 'Puncak Ratu merupakan wisata alam yang terletak di desa Pamekasan, Kecamatan Pamekasan, Kabupaten Pamekasan, Pulau Madura, Jawa Timur dengan ketinggian 200-300 meter di atas permukaan laut. Dari puncaknya pengunjung dapat menyaksikan hamparan air laut Jawa di sebelah Utara, serta pegunungan dan perbukitan Madura yang membentang.', -7.0270651, 113.490283, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Ratu%2009%2020251122.jpg?width=800', '2026-11-04 09:38:55', '2026-11-24 23:32:50', 'wd:Q139601153', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Taman nasional', 3),
  (8457, NULL, 4, 'Liang Bua', 'Cibal', 'Jalan Ruteng-Reo, Cibal, Nusa Tenggara Timur', 'Liang Bua merupakan sebuah situs pemukiman di zaman prasejarah yang terletak di Kabupaten Manggarai, Provinsi Nusa Tenggara Timur. Menurut kebahasaan, kata liang memiliki arti "gua" dan bua berarti "sejuk"/"dingin", yang diambil dari bahasa Manggarai. Ukuran Liang Bua mencapai 50 meter untuk panjang, 40 meter untuk lebar, dan 25 meter untuk tinggi.', -8.5341667, 120.4602778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Homo%20floresiensis%20cave.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q1822737', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 16),
  (8458, NULL, 4, 'Goa Lawah', 'Klungkung', '1, Dawan, Bali', 'Pura Goa Lawah (bahasa Bali: ᭛ ᬧᬸᬭ ᬕᭀᬯ ᬮᬯᬄ ᭛) merupakan sebuah pura yang terletak di Desa Pesinggahan, Kecamatan Dawan, Kabupaten Klungkung, Bali, yang berjarak sekitar 40 km dari ibu kota Bali, Denpasar. Pura Goa Lawah dikenal masyarakat karena adanya sebuah gua pada bagian utama pura ini, yang didalamnya terdapat sekumpulan kelelawar.\nPura ini juga menjadi titik fokus Perang Kusamba, sebuah perang antara Tentara Kerajaan Hindia Belanda yang dipimpin oleh Mayor Jenderal Andreas Victor Michiels melawan rakyat Klungkung yang dipimpin oleh Dewa Agung Istri Kanya.', -8.5516, 115.4689, NULL, 'Sen–Min 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Lawah%20Bali53.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q4845403', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 15),
  (8459, NULL, 3, 'Goa Jatijajar', 'Jawa Tengah', 'Jalan Candirenggo Jatijajar, Jatijajar, Kebumen, Jawa Tengah', 'Gua Jatijajar adalah sebuah situs geologi yang terbentuk dari proses alamiah, yang terletak di Kabupaten Kebumen, Jawa Tengah. Gua yang keseluruhannya terbentuk dari kapur, ini memiliki panjang 250 meter, llebar rata-rata 15 meter, dan tinggi rata-rata 12 meter. Lokasi gua ini berada 50 meter di atas permukaan laut.', -7.6727778, 109.4283333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20jati%20jajar%20ayah%20kebumen.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q13148535', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 5),
  (8460, NULL, 3, 'Guo Inyiak Janun', 'Matua Hilia', 'Matua Hilia, Agam, Sumatera Barat', 'Gua Inyiak Janun adalah cerita rakyat yang berkembang karena ditemukan gua di Jorong Bukik Siriah, Nagari Matua Hilia, Kecamatan Matur, Kabupaten Agam, Sumatera Barat. Goa itu ditemukan karena banyak kelelawar putih terbang di dalam goa. Selain itu banyak pula burung layang-layang di sana.', -0.2656611, 100.305097, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Inyiak%20Lasun%20%286%29.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q57413557', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 4),
  (8461, NULL, 3, 'Gua Jomblang', 'Yogyakarta', 'Semanu, Daerah Istimewa Yogyakarta', 'Gua Jomblang merupakan gua vertikal yang bertipe collapse doline yang juga menjadi objek wisata di Kabupaten Gunungkidul, Daerah Istimewa Yogyakarta. Gua ini terbentuk akibat proses geologi amblasnya tanah beserta vegetasi yang ada di atasnya ke dasar bumi yang terjadi ribuan tahun lalu. Runtuhan ini membentuk sinkhole atau sumuran yang dalam bahasa Jawa dikenal dengan istilah luweng.', -8.0281028, 110.6379889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jomblang%20Cave%20-%20Indonesia%2004.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q20426957', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 4),
  (8462, NULL, 4, 'Leang Tedongnge', 'Indonesia', 'Majannang, Pangkajene dan Kepulauan, Sulawesi Selatan', 'Leang Tedongnge (Bugis & Makassar: ᨒᨙᨕ ᨈᨙᨉᨚᨂᨙ, translit. Léang Tédongngé, har. \'Gua Kerbau\') atau Gua Tedongnge adalah situs arkeologi berupa gua prasejarah yang terletak di kawasan Karst Maros-Pangkep, Taman Nasional Bantimurung Bulusaraung.', -4.9401, 119.6723, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leang%20Tedongnge%20cave%20mouth%20credit%20AA%20Oktaviana.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q105044544', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 3),
  (8463, NULL, 3, 'Gua Latea', 'Indonesia', 'Tentena, Sulawesi Tengah', 'Gua Latea (bahasa Inggris: Latea Cave), terletak di perbukitan Parere, di kelurahan Tentena, Pamona Puselemba, Kabupaten Poso, Sulawesi Tengah. Gua Latea merupakan gua alam berupa gua kapur yang usia genesisnya diperkirakan tidak kurang dari 30 juta tahun yang lalu. Gua Latea terletak ±800 meter dari jalan raya utama kota Tentena.', -1.7562667, 120.6569833, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Tengkorak%20Kampung%20Penggoli%2C%20Pamona%20Timur%2C%20Kabupaten%20Poso%2C%20Sulawesi%20Tengah.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q3117146', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 3),
  (8464, NULL, 3, 'Gua Batu Cermin', 'Labuan Bajo', 'Labuan Bajo, Nusa Tenggara Timur', 'Gua Batu Cermin adalah gua yang terdapat di bukit batu yang gelap di Labuan Bajo, Manggarai Barat, Nusa Tenggara Timur, Indonesia.\nLuas gua ini 19 hektar, dan tingginya sekitar 75 meter. Sinar matahari masuk ke gua melalui dinding-dinding gua, dan memantulkan cahayanya di dinding batu sehingga merefleksikan cahaya kecil ke areal lain dalam gua sehingga terlihat seperti cermin.', -8.479371, 119.8991904, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mirror%20Stone%20Cave%2C%20Flores%2C%20Indonesia%2C%2020250827%200933%203883.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q17255910', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 3),
  (8465, NULL, 3, 'Goa Tetes', 'Indonesia', 'Sidomulyo, Lumajang, Jawa Timur', 'Wisata Goa Tetes atau Air Terjun Goa Tetes-Indonesia merupakan pariwisata di Indonesia gabungan antara wisata air terjun dan goa yang menarik untuk dikunjungi. Sebenarnya Goa Tetes telah dibuka sebagai tempat wisata Lumajang lebih dulu jika dibandingkan dengan Air Terjun Tumpak Sewu. Hal ini dapat dibuktikan dengan adanya dua pintu masuk yang berbeda, padahal letak kedua tempat wisata ini saling bersebelahan (satu aliran sungai yang sama).', -8.2330211, 112.9185373, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20tetes.png?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q56391685', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 2),
  (8466, NULL, 3, 'Gua Togi Ndrawa', 'Saewe', 'Fadoro Lasara, Kota Gunungsitoli, Sumatera Utara', 'Tögi Ndrawa adalah sebuah gua yang terletak di Nias. Gua ini memiliki jejak peninggalan orang Nias sejak 12.000 tahun lalu. Letaknya berada di Desa Lolowonu Niko\'otano, Gunungsitoli.', 1.2944822, 97.5924259, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Togi%20Ndrawa.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q97307129', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 2),
  (8467, NULL, 3, 'Gua Liang Bangkai', 'Kalimantan Selatan', 'Dukuh Rejo, Tanah Bumbu, Kalimantan Selatan', 'Goa Liang bangkai adalah situs wisata yang berada di desa Dukuh Rejo, kecamatan Mantewe, kabupaten Tanah Bumbu, Kalimantan Selatan. Goa Liang bangkai merupakan kawasan perbukitan dan didominasi oleh batuan kapur ini menjadi dikenal setelah penemuan tulang belulang di dalam goa. Penamaan goa ini karena bau di dalam goa yang seperti bau bangkai akibat banyak kelelawar yang hidup di dalamnya.', -3.202396, 115.7972218, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Liang%20Bangkai.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q132194309', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 2),
  (8468, NULL, 3, 'Gua Limbuhang', 'Haliau', 'Jalan Haji M. Taher, Baru, Hulu Sungai Tengah, Kalimantan Selatan', 'Gua Limbuhang adalah objek wisata yang terletak di Desa Haliau, Kabupaten Hulu Sungai Tengah, Provinsi Kalimantan Selatan, Indonesia. Berjarak ± 20 km dari pusat Kabupaten Hulu Sungai Tengah, dengan waktu tempuh lebih kurang 1 jam. Gua ini berada di bawah bukit dengan ketinggian sekitar 50 meter dan menawarkan kesejukan yang berasal dari balik dinding batu, serta terdapat air telaga mini di bawahnya.', -2.6377043, 115.4280496, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Limbuhang%20Haliau%20005.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q141647167', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 2),
  (8469, NULL, 4, 'Gua Pawon', 'Bandung Barat', 'Jalan Orion, Gunungmasigit, Bandung Barat, Jawa Barat', 'Gua Pawon adalah sebuah gua alami dan situs purbakala yang terletak di Desa Gunung Masigit, Kecamatan Cipatat, Kabupaten Bandung Barat, atau sekitar 25 km arah barat Kota Bandung. Merupakan sebuah tempat yang penting bagi orang Sunda karena di sanalah tempat berkumpulnya sesepuh Sunda yang sekarang menduduki bagian barat pulau Jawa. Di sana pernah ditemukan kerangka manusia purba yang konon adalah nenek moyang orang Sunda (masih diteliti di balai Arkeolog Bandung).', -6.823602, 107.436292, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Pawon.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q12484537', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8470, NULL, 3, 'Gua Ngesong', 'Pulosari', 'Pulosari, Jombang, Jawa Timur', 'Gua Ngesong adalah sebuah gua yang berada di bukit antara Dusun Pulosari dan Sumbermulyo, Desa Pulosari, Kecamatan Bareng, Kabupaten Jombang.\nGua Ngesong berada di selatan Candi Rimbi ini ditemukan warga saat mencari rumput untuk kebutuhan makan hewan ternaknya.', -7.674641, 112.3493951, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Ngesong.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q97307794', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 1),
  (8471, NULL, 3, 'Gua Gong', 'Bomo', 'Bomo, Pacitan, Jawa Timur', 'Gua Gong terletak di Jl. Salam, Salam, Bomo, Punung, Kabupaten Pacitan, Jawa Timur  yang juga terkenal dengan julukan kota 1001 gua, dan satu yang terkenal disini adalah tempat wisata Gua Gong Pacitan.\nPacitan merupakan wilayah di Jawa Timur yang dikelilingi oleh pegunungan kapur, yang menjadikan tanah di daerah ini kering dan tidak subur.', -8.1644748, 110.9799579, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gua%20Gong.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q109441373', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 1),
  (8472, NULL, 3, 'Gua Batu Tunggal', 'Kalimantan Selatan', 'Tegal Rejo, Kotabaru, Kalimantan Selatan', 'Gua Batu Tunggal atau Gua Lowo adalah sebuah gua yang terletak di Kabupaten Kotabaru, Provinsi Kalimantan Selatan, Indonesia. Secara administratif, gua ini berlokasi di desa Tegalrejo, kecamatan Kelumpang Hilir. Gua ini diresmikan sebagai objek wisata di Kabupaten Kotabaru pada 23 Agustus 2020 oleh bupati Kotabaru saat itu, Sayed Jafar Al-Idrus.', -3.195716, 115.975714, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Lowo%20Kotabaru%20001.JPG?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q134053818', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 1),
  (8473, NULL, 3, 'Goa Ngarai Sianok', 'Bukik Apik Puhun', 'Kabun Pulasan, Bukittinggi, Sumatera Barat', 'Goa Ngarai Sianok: Wisata goa yang berada di Ngarai Sianok Kota Bukittinggi, Sumatera Barat, Bukik Apik Puhun.', -0.301094, 100.354897, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wisata%20Goa%20Ngarai%20Sianok%20BKT%2010.jpg?width=800', '2026-11-04 09:39:05', '2026-11-24 23:32:50', 'wd:Q141473281', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Gua', 1),
  (8474, NULL, 3, 'Pancuran Pitu', 'Lokawisata Baturraden', 'Baturaden, Jawa Tengah', 'Pancuran Pitu, atau Pancuran Tujuh merupakan salah satu lokawisata yang terletak dalam lingkungan Lokawisata Baturraden, Kabupaten Banyumas. Pancuran ini merupakan sumber air panas bumi yang terpancar langsung dari kaki Gunung Slamet yang keluar melalui tujuh pancuran. Dalam lokawisata Pancuran Tujuh terdapat Gua Sarabadak, tetapi saat ini gua tersebut telah ditutup karena longsor.', -7.30997, 109.218, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pancuran%20Tujuh%2C%20near%20Baturraden%2C%20Purwokerto%202015-03-23%2003.jpg?width=800', '2026-11-04 09:39:08', '2026-11-24 23:32:50', 'wd:Q12502468', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Pemandian air panas', 5),
  (8476, NULL, 3, 'Mata Air Panas Kalibacin', 'Indonesia', NULL, 'Mata Air Panas Kalibacin berada di sebelah selatan Kabupaten Banyumas. Tempat ini berupa sumber mata air panas yang mengandung belerang. Kalibacin terletak di Desa Tambaknegara, Kecamatan Rawalo.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalibacin%20purwokerto.jpg?width=800', '2026-11-04 09:39:08', '2026-11-24 23:32:50', 'wd:Q11245824', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Pemandian air panas', 2),
  (8477, NULL, 3, 'Pemandian Air Panas Banjar', 'Banjar', 'JI Air Panas Banjar, Banjar, Bali', 'Pemandian Air Panas Banjar: Mata air panas di Banjar, Banjar.', -8.210536, 114.967053, 10000, ' 08.30–17.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thermes%20d%27Air%20Panas%20Banjar.JPG?width=800', '2026-11-04 09:39:08', '2026-11-24 23:32:50', 'wd:Q122956574', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Pemandian air panas', 2),
  (8478, NULL, 3, 'The Full Hot Spring & Resort', 'Jawa Timur', 'Padusan, Mojokerto, Jawa Timur', 'The Full Hot Spring & Resort: Pemandian air panas di Kabupaten Mojokerto, Jawa Timur, Jawa Timur.', -7.683962, 112.549565, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Full%20Hot%20Spring%20%26%20Resort%20120129.jpg?width=800', '2026-11-04 09:39:08', '2026-11-24 23:32:50', 'wd:Q141746402', 'wikidata', 'Apr–Okt (musim kemarau), pagi hari', 'Pemandian air panas', 1),
  (8479, NULL, 4, 'Candi Prambanan', 'Jawa Tengah', 'Jalan Jogja - Solo, Bokoharjo, Sleman, Daerah Istimewa Yogyakarta', 'Candi Prambanan (bahasa Jawa: ꦕꦟ꧀ꦝꦶꦥꦿꦩ꧀ꦧꦤꦤ꧀, translit. Caṇḍi Prambanan) adalah bangunan candi bercorak agama Hindu terbesar di Indonesia yang dibangun pada abad ke-9 Masehi. Candi yang juga disebut sebagai Rara Jonggrang ini dipersembahkan untuk Trimurti, tiga dewa utama Hindu yaitu dewa Brahma sebagai dewa pencipta, dewa Wisnu sebagai dewa pemelihara, dan dewa Siwa sebagai dewa pemusnah.', -7.752, 110.49122, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prambanan%20Complex%201.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q47721', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 72),
  (8480, NULL, 4, 'Tanah Lot', 'Beraban', 'Jalan Enjung Pura, Kediri, Bali', 'Pura Tanah Lot (aksara Bali: ᬧᬸᬭᬢᬦᬄᬮᭀᬢ᭄) adalah salah satu Pura (Tempat Ibadah Umat Hindu) yang sangat disucikan di Bali, Indonesia. Nama Tanah Lot berasal dari kata "tanah" yang artinya tanah atau pulau dan "lot" atau lod yang artinya laut. Sehingga nama Tanah Lot dapat diartikan sebagai sebuah tanah atau pulau yang terletak di laut.', -8.6211389, 115.08675, 20000, '07.00–19.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bali%20-%20Pura%20Tanah%20Lot%2C%2020220827%201005%201141.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q515253', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 33),
  (8481, NULL, 4, 'Pura Besakih', 'Karangasem', 'Trail Besakih - Gunung Agung, Rendang, Bali', 'Pura Agung Besakih (aksara Bali: ᬧᬸᬭᬳᬕᬸᬂᬩᭂᬲᬓᬶᬄ) adalah sebuah Pura yang terletak di Kabupaten Karangasem, Bali. Besakih merupakan pura terbesar di Bali dan menjadi pura terpenting dan paling suci bagi umat Hindu Bali. Kawasan Suci Pura Agung Besakih adalah kawasan yang terdiri dari 26 (dua puluh enam) Pura, yaitu Pura Penataran Agung Besakih dan 25 (dua puluh lima) Pura Pakideh.', -8.3741, 115.45222, 5000, 'Sen–Min 07.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Besakih%20Sunrise%2001.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q829418', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 32),
  (8482, NULL, 4, 'Pura Luhur Uluwatu', 'Badung', 'Jalan Raya Uluwatu, Kuta Selatan, Bali', 'Pura Luhur Uluwatu (Aksara Bali: ᬧᬸᬭᬮᬸᬳᬸᬃᬉᬮᬸᬯᬢᬸ) atau Pura Uluwatu merupakan pura yang berada di wilayah Desa Adat Pecatu, Kecamatan Kuta Selatan, Kabupaten Badung.\nPura yang terletak di ujung barat daya pulau Bali di atas anjungan batu karang yang terjal dan tinggi serta menjorok ke laut ini merupakan Pura Sad Kayangan yang dipercaya oleh orang Hindu sebagai penyangga dari 9 mata angin. Pura ini pada mulanya digunakan menjadi tempat memuja seorang pendeta suci dari abad ke-11 bernama Empu Kuturan.', -8.82939, 115.084405, NULL, '09.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Uluwatu%20Temple.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q1381933', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 25),
  (8483, NULL, 4, 'Pura Ulun Danu Bratan', 'Tabanan', 'Baturiti, Bali', 'Pura Ulun Danu Bratan (ejaan tidak baku: Pura Ulun Danu Beratan, bahasa Bali: ᬧᬸᬭ ᬉᬮᬸᬦ᭄ ᬤᬦᬸ ᬩᭂᬭᬢ​ᬦ᭄᭟, translit. Pura Ulun Danu Bĕratan., disebut juga Bratan Pura) adalah sebuah pura dan candi air besar di Bali - candi utama air lainnya menjadi Pura Ulun Danu Batur. Kompleks pura ini terletak di tepi barat Danau Bratan di pegunungan dekat Bedugul, tepatnya di Desa Candikuning, Kecamatan Baturiti, Kabupaten Tabanan.', -8.27061, 115.16658, 3000, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brantan%20Bali%20Pura-Ulun-Danu-Bratan-01.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q2220851', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 22),
  (8484, NULL, 4, 'Pura Taman Ayun', 'Mengwi', 'Gang Nuri VI No.10, Mengwi, Bali', 'Pura Taman Ayun (Aksara Bali: ᬧᬸᬭᬢᬫᬦ᭄ᬅᬬᬸᬦ᭄) merupakan Pura Paibon/Pedarman Raja Mengwi untuk memuja roh leluhur dari raja-raja yang diwujudkan dengan dibangunnya sebuah gedong Paibon, serta dibangun pula meru-meru untuk pemujaan dan persembahyangan kepada para Dewa bagi masyarakat kerajaan Mengwi dalam memohon kesejahteraan. Pura Taman Ayun berlokasi di Kecamatan Mengwi, Badung, Bali, Indonesi. Taman ini beserta Pura Taman Ayun merupakan peninggalan bersejarah dari kerajaan Mengwi.', -8.5416083, 115.1726028, NULL, 'sunrise–sunset', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20taman%20ayun.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q1028566', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 20),
  (8486, NULL, 4, 'Pura Kehen', 'Bangli', 'Jalan Sriwijaya, Br. Pande, Bangli, Bali', 'Pura Kehen (bahasa Bali: ᬧᬸᬭ ᬓᬾᬏ​ᬦ᭄᭟, translit. Pura Kéhén) adalah sebuah pura Hindu yang berlokasi di Kelurahan Cempaga, Kecamatan Bangli, Kabupaten Bangli, Bali, Indonesia, sekitar 45 km dari pusat Kota Denpasar, 20 km dari Ubud dan 23 km dari Kintamani serta 3 km dari Desa Wisata Penglipuran. Pura ini disebut juga sebagai Pura Hyang Api di mana kehen dalam Bahasa Bali berarti api.', -8.441827, 115.359902, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Kehen%20temple%20complex%20in%20Bali.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q43389200', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 12),
  (8487, NULL, 4, 'Pura Luhur Batukaru', 'Tabanan', 'Pura Petali, Penebel, Bali', 'Pura Luhur Batukaru adalah pura atau tempat suci agama Hindu Bali sebagai tempat memuja Tuhan dalam manifestasinya sebagai Sang Hyang Mahadewa. Karena fungsinya untuk memuja Tuhan sebagai Dewa yang menumbuhkan tumbuh-tumbuhan dengan mempergunakan air secara benar, maka di Pura Luhur Batukaru ini disebut sebagai pemujaan Tuhan sebagai Ratu Hyang Tumuwuh—sebutan Tuhan sebagai yang menumbuhkan. Pura Luhur Batukaru terletak di Desa Wongaya Gede, Kecamatan Penebel, Kabupaten Tabanan.', -8.3725, 115.1027778, NULL, 'sunrise–sunset', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Luhur%20Batukaru%2C%20hindu%20temple%20Bali%20-%20panoramio.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q7260784', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 12),
  (8488, NULL, 4, 'Candi Cetho', 'Karanganyar', 'Gunung Lawu Via Candi Cetho, Gumeng, Karanganyar, Jawa Tengah', 'Candi Ceto (hanacaraka: ꦕꦼꦛ, ejaan bahasa Jawa latin: cethå) dibangun sekitar tahun 1451- 1470 pada zaman Kerajaan Majapahit ketika pengaruh Hindu di Jawa mulai pudar dan unsur Indonesia asli dari tradisi prasejarah mulai hidup lagi. Ciri khas seni arca pada masa itu dibuat berukuran besar tetapi pemahatannya lebih sederhana, contoh jelas adalah arca Bima yang ada di halaman pertama. Dari sisi arsitektur gaya bangunan masa itu menyerupai punden berundak yang berkembang di Gunung Penanggungan dan Gunung Arjuna, Jawa Timur.', -7.59554, 111.15731, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Ceto%20Terraces%2C%20Surakarta%201281.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q2735629', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 11),
  (8489, NULL, 4, 'Candi Kidal', 'Malang', 'Jalan Raya Kidal, Kidal, Kabupaten Malang, Jawa Timur', 'Candi Kidal, adalah salah satu candi warisan dari kerajaan Singasari. Candi ini dibangun sebagai bentuk penghormatan atas jasa besar Anusapati, Raja kedua dari Singhasari, yang memerintah selama 20 tahun (1227 - 1248). Menurut Pararaton Kematian Anusapati dibunuh oleh Panji Tohjaya sebagai bagian dari perebutan kekuasaan Singhasari, juga diyakini sebagai bagian dari kutukan Mpu Gandring.', -8.02577, 112.70909, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Kidal%20A.JPG?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q3029356', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 10),
  (8490, NULL, 4, 'Kuil Shri Mariamman, Medan', 'Sumatera Utara', 'Jalan Zainul Arifin, Medan Polonia, Kota Medan, Sumatera Utara', 'Kuil Shri Mariamman adalah kuil Hindu tertua di Petisah Tengah, Medan Petisah, Medan. Kuil ini dibangun pada tahun 1881 untuk memuja dewi Mariamman. Kuil ini terletak di kawasan yang dikenal sebagai Kampung Madras.', 3.5839167, 98.671, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Perhimpunan%20Shri%20Mariamman%20%28Mariamman%20Hindu%20Temple%29%2C%20Medan.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q12492840', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 10),
  (8491, NULL, 4, 'Pura Sakenan', 'Serangan', 'Tukad Punggawa, Serangan, Denpasar, Bali', 'Pura Sakenan adalah salah satu pura penting yang terletak di wilayah selatan Bali, berada di atas pantai di barat laut Pulau Serangan, yaitu sebuah pulau kecil yang berjarak sekitar 10 kilometer di selatan Denpasar. Pura ini masih memiliki hubungan dengan Buddha, yang melinggih Ida Bhatara Sakya Muni. Sebagaimana dengan pura-pura lain, setiap pengunjung yang hendak masuk ke tempat suci Pura Sakenan wajib mengenakan sarung dan sabuk kain khas Bali serta bagi yang wanita tidak sedang dalam masa menstruasi.', -8.725129, 115.2294, NULL, 'sunrise–sunset', 'https://commons.wikimedia.org/wiki/Special:FilePath/ID-bali-bangli-pura-kehen-04.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q19752612', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 8),
  (8492, NULL, 4, 'Pura Lempuyang Luhur', 'Abang', 'Temple Path Steps, Abang, Bali', 'Pura Lempuyang Luhur adalah pura ketujuh dan tertinggi di kompleks Pura Lempuyang di Gunung Lempuyang di Kabupaten Karangasem, Bali timur, Indonesia. Pura ini merupakan salah satu dari sembilan pura di kompleks Pura Sad Kahyangan atau Pura Kahyangan Sad Winayaka dan merupakan tempat ibadah paling suci di Bali.', -8.3914722, 115.6305556, NULL, 'Sen–Min 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bali%20Pura%20Lempuyang%20Luhur.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q48728528', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 8),
  (8493, NULL, 4, 'Candi Sambisari', 'Sleman', 'Jalan Masjid II, Purwomartani, Sleman, Daerah Istimewa Yogyakarta', 'Candi Sambisari (bahasa Jawa: ꦕꦤ꧀ꦝꦶꦱꦩ꧀ꦧꦶꦱꦫꦶ, translit. Candhi Sambisari) ditemukan secara kebetulan oleh seorang petani ketika mencangkul tanah pada tahun 1966. Ketika ditemukan keadaannya sudah tertimbun oleh pasir dan bebatuan lahar Gunung Merapi sedalam 6,5 m.', -7.76247, 110.44706, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sambisari%20Panorama%20%2829%20December%202013%29.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q3029610', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 8),
  (8494, NULL, 4, 'Pura Mangkunagaran', 'Indonesia', 'Jalan R.M. Said, Keprabon, Surakarta, Jawa Tengah', 'Pura Mangkunegaran (bahasa Jawa: ꦥꦸꦫꦩꦁꦏꦸꦤꦒꦫꦤ꧀, translit. Purå Mangkunagaran) adalah istana resmi Kadipaten Mangkunegaran dan tempat kediaman para Adipati Mangkunegaran yang bertahta sejak Mangkunegara I hingga Mangkunegara X yang saait ini bertahta. Bangunan ini berada di Surakarta.', -7.566325, 110.8229944, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mangkunegaran%20Palace%20Java362.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q16157895', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 6),
  (8495, NULL, 4, 'Pura Pulaki', 'Singaraja', 'Jalan Seririt-Gilimanuk, Gerokgak, Bali', 'Pura Pulaki adalah candi / pura di Singaraja.', -8.145668, 114.680338, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20hindouiste%20de%20Pura%20Pulaki%20-%20panoramio.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q48729986', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 5),
  (8496, NULL, 4, 'Pura Peti Tenget', 'Badung', 'Kerobokan Kelod, Kuta Utara, Bali', 'Pura Peti Tenget adalah candi / pura di Badung.', -8.68184, 115.15243, 50000, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Petitenget.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q56247112', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 3),
  (8497, NULL, 4, 'Pura Batu Bolong', 'Lombok Barat', 'Jalan Raya Meninting, Batulayar Barat, Lombok Barat, Nusa Tenggara Barat', 'Pura Batu Bolong adalah sebuah pura yang terletak di Kabupaten Lombok Barat, Provinsi Nusa Tenggara Barat, Indonesia.', -8.5093084, 116.0567816, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Batubolong%20Lombok%205.JPG?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q2575072', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 3),
  (8498, NULL, 4, 'Candi Gatotkaca', 'Banjarnegara', 'Dieng Kulon, Banjarnegara, Jawa Tengah', 'Candi Gatotkaca adalah salah satu candi Hindu yang berada di Dataran Tinggi Dieng, di wilayah Kabupaten Banjarnegara, Provinsi Jawa Tengah. Candi ini terletak di sebelah barat Kompleks Percandian Arjuna, di tepi jalan ke arah Candi Bima, di seberang Museum Dieng Kailasa. Nama Gatotkaca sendiri diberikan oleh penduduk dengan mengambil nama tokoh wayang dari cerita Mahabarata.', -7.208742, 109.905957, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Gatotkaca.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q11123778', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 3),
  (8499, NULL, 4, 'Candi Bangkal', 'Candiharjo', 'Jalan Raya Ngoro, Kembangsri, Mojokerto, Jawa Timur', 'Candi Bangkal adalah sebuah candi peninggalan Majapahit yang terletak di Dusun Bangkal, Desa Candiharjo, Kecamatan Ngoro, Kabupaten Mojokerto, Jawa Timur.\nAlas candi berbentuk segi empat. Pada kaki candi terdapat tangga menuju bilik candi.', -7.543056, 112.635556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tjandi%20Bangkal%20bij%20Modjokerto%2C%20KITLV%20162609.tiff?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q12478250', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 3),
  (8500, NULL, 4, 'Pura Kerti Bhuana', 'Way Lunik', 'Sinar Binglu, Bandar Lampung, Lampung', 'Pura Kahyangan Jagat Kerthi Bhuana merupakan pura yang berada di wilayah Kelurahan Way Lunik, Kecamatan Panjang, Bandar Lampung, tepatnya di Jalan Bypass Soekarno-Hatta KM 16.\n\nPura ini adalah pura pusat dan terbesar bagi umat Hindu yang ada di Provinsi Lampung.', -5.4477853, 105.3127651, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Kahyangan%20Jagat%20Kerthi%20Bhuana.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q25468551', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 2),
  (8501, NULL, 4, 'Pura Pegulingan', 'Gianyar', 'Jalan Raya Penelokan, Tampaksiring, Bali', 'Candi Pegulingan adalah sebuah candi yang terletak di Kabupaten Gianyar, Bali dengan jarak kurang lebih 48 km dari kota Denpasar atau 16 km dari kota Gianyar dan memiliki ketinggian 551 mdpl, berada di sebelah timur, tidak jauh dari lingkungan Pura Tirta Empul, Tampaksiring. Dari Balai Banjar Basangambu kita belok ke kiri dengan berjalan kaki melewati jalan setapak kira-kira ± 250 meter akan sampai di Pura Pegulingan.\nCandi Pegulingan terdapat di dalam kompleks pura Pegulingan.', -8.41498, 115.31777, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Agung%2C%20Pegulingan%20temple.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q66545466', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 2),
  (8502, NULL, 4, 'Pancoran Solas Taman Bali', 'Tamanbali', 'Tangga Menuju Pancoran Solas, Bangli, Bali', 'Pancoran Solas Taman Bali: Pura yang terletak di Taman Bali, Bangli, Tamanbali.', -8.5160329, 115.3569503, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/WIKITIRTA%20-%20PANCORAN%20SOLAS%2010.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q115721390', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 2),
  (8503, NULL, 4, 'Pura Agung Jagatnatha Kota Denpasar', 'Denpasar', 'Gang I, Dangin Puri, Denpasar, Bali', 'Pura Agung Jagatnatha Kota Denpasar adalah candi / pura di Denpasar.', -8.6566667, 115.2188889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Jagatnatha%20in%20Bali%3B%20David%20Stanley%3B%20November%202011.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q126048760', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 2),
  (8504, NULL, 4, 'Yeh Pulu', 'Blahbatuh', 'Jalan Raya Semebaung, Blahbatuh, Bali', 'Yeh Pulu adalah candi / pura di Indonesia.', -8.53166, 115.29304, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bedulu%20village%2C%20Yeh%20Pulu%20temple%2C%20Bali%2C%2020220824%201026%200617.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q114741272', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 1),
  (8505, NULL, 4, 'Pura Puseh Batuan', 'Gianyar', 'Sukawati, Bali', 'Pura Puseh Batuan adalah candi / pura di Gianyar.', -8.5822617, 115.2757394, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20batuan%20gianyar.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q140644996', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 1),
  (8506, NULL, 4, 'Pura Satria Dharma', 'Malang', 'Jalan Untung Suropati Selatan, Klojen, Kota Malang, Jawa Timur', 'Pura Satria Dharma: Kuil Hindu di Kec. Blimbing, Kota Malang, Indonesia, Malang.', -7.9807957, 112.6396074, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Satria%20Dharma%20%288%29.jpg?width=800', '2026-11-04 09:39:17', '2026-11-24 23:32:50', 'wd:Q138326675', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Candi / Pura', 0),
  (8507, NULL, 4, 'Museum Nasional Indonesia', 'Jakarta Pusat', 'Jalan Medan Merdeka Barat No.12, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Nasional Indonesia atau yang sering disebut dengan Museum Gajah adalah sebuah museum arkeologi, sejarah, etnografi, dan geografi yang berada di bawah naungan Museum dan Cagar Budaya,  Kementerian Kebudayaan Republik Indonesia dan terletak di Jalan Merdeka Barat 12, Jakarta Pusat. Museum ini merupakan museum pertama dan terbesar di Asia Tenggara.', -6.1761111, 106.8216667, 5000, 'Sel–Kam 09.00–18.00; Jum 08.30–11.00, 13.00–16.00; Sab–Min 08.30–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Front%20facade%20-%20National%20Museum%20Indonesia%2C%20Jakarta%20%282025%29%20-%20img%2007.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q1467125', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 33),
  (8508, NULL, 4, 'Monumen Nasional', 'Jakarta Pusat', 'Jalan Medan Merdeka Utara, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Monumen Nasional yang disingkat dengan Monas atau Tugu Monas adalah monumen peringatan setinggi 132 meter (433 kaki), terletak tepat di tengah Lapangan Medan Merdeka, Jakarta Pusat. Monas didirikan untuk mengenang perlawanan dan perjuangan rakyat Indonesia dalam merebut kemerdekaan dari pemerintahan kolonial Kerajaan Belanda. Pembangunan dimulai pada  17 Agustus 1961 di bawah perintah Presiden Soekarno dan diresmikan hingga dibuka untuk umum pada  12 Juli 1975 oleh Presiden Soeharto.', -6.1753889, 106.8271389, NULL, 'Sel–Min 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen%20Nasional%2C%20Jakarta%2C%20Indonesia.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q145151', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 32),
  (8509, NULL, 4, 'Museum Tsunami Aceh', 'Baiturrahman', 'Jalan Sultan Iskandar Muda, Baiturrahman, Banda Aceh, Aceh', 'Museum Tsunami Aceh (Aksara Jawoë: موسيوم سونامي اچيه) adalah sebuah museum di Banda Aceh yang dirancang sebagai monumen simbolis, untuk mengenang bencana gempa bumi dan tsunami Samudra Hindia 2004 sekaligus menjadi salah satu pusat pendidikan bencana dan tempat perlidungan atau evakuasi darurat andai tsunami terjadi lagi. Museum Tsunami mulai dibangun pada tahun 2008 menggunakan dana bantuan dari negara-negara donor yang dikoordinasikan oleh BRR. Proses pembangunan tersebut kemudian selesai pada akhir tahun yang sama, yaitu 2008. Museum ini diresmikan oleh Presiden Susilo Bambang Yudoyono pada tahun 2009 dan dibuka untuk publik pada tahun 2011.', 5.5477222, 95.3150833, 3000, ' 09.00:00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aceh%20Tsunami%20Museum%20site%20visit%3B%20February%202020%20%2825%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2218604', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 20),
  (8510, NULL, 4, 'Museum Bahari', 'Jakarta', 'Jalan Pasar Ikan, Penjaringan, Jakarta Utara', 'Museum Bahari adalah sebuah museum yang terletaka di Jalan Pasar Ikan Nomor 1 Sunda Kelapa, Jakarta Utara. Museum ini menyimpan koleksi yang berhubungan dengan kebaharian dan kenelayanan bangsa Indonesia dari Sabang hingga Merauke yang berlokasi di seberang Pelabuhan Sunda Kelapa. Museum Bahari merupakan salah satu dari delapan museum yang berada di bawah pengawasan dan pengelolaan dari Dinas Kebudayaan Provinsi Daerah Khusus Ibu kota Jakarta.', -6.1269833, 106.8083, 10000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Bahari%20Pintu%20Masuk.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2030607', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 15),
  (8511, NULL, 4, 'Museum Wayang', 'Jakarta', 'Jalan Pintu Besar Utara, Taman Sari, Jakarta Barat', 'Museum Wayang adalah sebuah museum yang berlokasi di Jalan Pintu Besar Utara Nomor 27, Jakarta Barat.', -6.1348725, 106.8124425, 2000, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Wayang%2C%20Jakarta%20%282025%29%20-%20img%2001.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2854954', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 13),
  (8512, NULL, 4, 'Museum Tekstil', 'Jakarta', 'Jalan Aipda Karel Satsuit Tubun, Palmerah, Jakarta Barat', 'Museum Tekstil merupakan museum yang diresmikan pada tanggal 28 Juni 1976 oleh Ibu Tien Suharto. Letak museum menempati gedung tua di Jalan K.S. Tubun / Kota Bambu Selatan No. 4 Kecamatan Palmerah, Jakarta Barat.', -6.18859, 106.80962, 5000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Musetextil.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2800358', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8513, NULL, 4, 'Museum Sonobudoyo', 'Yogyakarta', 'Jalan Pangurakan, Gondomanan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Sonobudoyo (bahasa Jawa: ꦩꦸꦱꦺꦪꦸꦩ꧀ꦱꦤꦧꦸꦢꦪ) adalah museum sejarah dan kebudayaan Jawa, termasuk bangunan arsitektur klasik Jawa. Museum ini menyimpan koleksi mengenai budaya dan sejarah Jawa yang dianggap paling lengkap setelah Museum Nasional Republik Indonesia di Jakarta. Selain keramik pada zaman Neolitik dan patung perunggu dari abad ke-8, museum ini juga menyimpan beberapa macam bentuk wayang kulit, berbagai senjata kuno (termasuk keris dan topeng Jawa).', -7.8023, 110.36394, 10000, ' 08.00–20.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sonobudoyo%20sep%202026.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4271636', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8514, NULL, 4, 'Museum Kereta Api Ambarawa', 'Semarang', 'Jalan Pemuda, Panjang, Kabupaten Semarang, Jawa Tengah', 'Museum Kereta Api Ambarawa (bahasa Inggris: Indonesian Railway Museum) adalah stasiun kereta api nonaktif yang dialihfungsikan menjadi museum perkeretaapian. Museum ini secara administratif terletak di Panjang, Ambarawa, Semarang. Museum yang terletak pada ketinggian +474,40 meter ini termasuk dalam Wilayah Penjagaan Aset Daerah Operasi IV Semarang serta dikelola oleh KAI Wisata bekerja sama dengan Pemerintah Provinsi Jawa Tengah.', -7.26542, 110.40126, 20000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stasiun%20Ambarawa%202.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q1311742', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8515, NULL, 4, 'Museum Puri Lukisan', 'Gianyar', 'Jalan Raya Ubud, Ubud, Bali', 'Museum Puri Lukisan (bernama lengkap Museum Puri Lukisan Ratna Wartha) adalah museum yang menjadi tempat dari berbagai koleksi kesenian budaya Bali berupa lukisan dan hasil ukiran kayu dari yang tradisional sampai yang modern. Museum ini merupakan museum seni tertua di Bali yang menyimpan koleksi sejak tahun 1930 hingga saat ini. Museum ini menyimpan koleksi kesenian berbagai budaya Bali, termasuk Ubud, Sanur, Batuan, Young Artist, dan sekolah Keliki.', -8.5050972, 115.2602778, NULL, 'Sen–Min 09.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Puri%20Lukisan%20Museum%20%2817032156926%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q7261229', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8516, NULL, 4, 'Museum Zoologi Bogor', 'Pabaton', 'Jalan Otto Iskandardinata No.9, Bogor Tengah, Bogor, Jawa Barat', 'Museum Zoologi Bogor (bahasa Sunda: ᮙᮥᮞᮤᮉᮙ᮪ ᮐᮧᮇᮜᮧᮌᮤ ᮘᮧᮌᮧᮁ, translit. Musieum Zoologi Bogor) adalah museum yang terletak di Bogor, memiliki koleksi yang berkaitan dengan dunia satwa seperti berbagai spesimen yang diawetkan maupun fosil hewan. Museum ini terbagi menjadi dua, salah satunya dibuka setiap hari untuk umum yang berisi ruang pameran terletak di Jalan Ir.', -6.60365, 106.79701, 16000, ' 07.30–16.00;  07.30–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Het%20Zo%C3%B7logisch%20Museum%20en%20laboratorium%20van%20%27s%20Lands%20Plantentuin%20te%20Buitenzorg%20West-Java%20TMnr%2010010799.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q16746897', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8517, NULL, 4, 'Museum Negeri Aceh', 'Banda Aceh', 'Jalan Sultan Alauddin Mahmudsyah, Baiturrahman, Banda Aceh, Aceh', 'Museum Aceh (Aksara Jawoë : موسياوم اچيه) adalah sebuah museum etnografi dari suku bangsa asli yang mendiami Tanah Aceh. Museum ini terletak di Banda Aceh, Provinsi Aceh, Indonesia. Didirikan pada tahun 1915 oleh pemerintah kolonial Belanda, museum ini berfungsi sebagai pusat pelestarian dan pameran berbagai koleksi sejarah, budaya, dan adat istiadat Aceh.', 5.548581, 95.320642, 2000, ' 08.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Aceh.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q8465860', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 11),
  (8518, NULL, 4, 'Istana Pagaruyung', 'Batusangkar', 'Jalan Sutan Alam Bagagarsyah, Pagaruyung, Tanah Datar, Sumatera Barat', 'Istano Basa Pagaruyung yang lebih terkenal dengan nama Istana Besar Kerajaan Pagaruyung adalah museum berupa replika istana Kerajaan Pagaruyung terletak di Nagari Pagaruyung, Kecamatan Tanjung Emas, Kabupaten Tanah Datar, Sumatera Barat. Istana ini berjarak lebih kurang 5 kilometer dari Batusangkar. Istana ini merupakan objek wisata budaya yang terkenal di Sumatera Barat.', -0.4713889, 100.6213889, 10000, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Pagaruyung%20%28Pagaruyung%20Palace%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12486845', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 11),
  (8519, NULL, 4, 'Museum Bank Indonesia', 'Jakarta Barat', 'Jalan Kali Besar Timur, Taman Sari, Jakarta Barat', 'Museum Bank Indonesia adalah sebuah museum sejarah dan budaya yang terletak di Kelurahan Pinangsia, Kecamatan Taman Sari, Kota Jakarta Barat, Indonesia. Pendirian Museum Bank Indonesia ditetapkan oleh Dewan Gubernur Bank Indonesia dengan tujuan untuk melestarikan gedung bersejarah milik Bank Indonesia di Kota Tua Jakarta sekaligus memperkenalkan peran Bank Indonesia dalam sejarah bangsa Indonesia.\nBangunan Museum Bank Indonesia pernah digunakan sebagai gedung Bank Indonesia Kota yang merupakan cagar budaya Indonesia peninggalan De Javasche Bank yang selesai dibangun pada tahun 1828.', -6.13733, 106.813, 5000, ' 08.00–15.30;  08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bank%20Indonesia%20Museum%20-%20Jakarta%20%282025%29%20-%20img%2002.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2521269', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 10),
  (8520, NULL, 4, 'Gedong Kirtya', 'Paket Agung', 'Jalan Veteran, Paket Agung, Buleleng, Bali', 'Gedong Kirtya disebut juga Museum Gedong Kirtya atau Perpustakaan Gedong Kirtya adalah perpustakaan lontar yang beralamat di Jalan Veteran, No. 20, Kelurahan Paket Agung, Kecamatan Buleleng, Kabupaten Buleleng, Provinsi Bali. Didirikan pada 2 Juni 1928 dan mulai dibuka untuk umum pada 14 September 1928 oleh orang-orang Belanda di Singaraja, Bali, untuk mengenang jasa Van der Tuuk.', -8.124837, 115.096198, 5000, ' 08.00–16.00; Jum 08.00–13.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedong%20Kirtya%20museum%20exhibition%2016.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q3100067', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 10),
  (8521, NULL, 4, 'Monumen Bajra Sandhi', 'Denpasar', 'Raya Puputan, Denpasar Timur, Denpasar, Bali', 'Monumen Bajra Sandhi atau Monumen Perjuangan Rakyat Bali (Aksara Bali: ᬫᭀᬦᬸᬫᬾᬦ᭄ᬩᬚ᭄ᬭᬲᬦ᭄​ᬟᬶ᭟​) merupakan monumen perjuangan rakyat Bali yang terletak di Kelurahan Panjer, Kota Denpasar, Bali. Dibangun di tanah seluas 13,8 hektare dengan luas gedung 4.900 m2. Monumen ini berada di sebelah selatan Kantor Gubernur Bali dan sebelah tenggara Kantor DPRD Bali, selain itu ada beberapa lapangan yaitu Niti Mandala di sebelah barat dan Puputan Renon di sebelah utara.', -8.6716667, 115.2338889, 2000, ' 08.30–17.00; Sab 9 AM–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen-Bajra-Sandhi.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4848938', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 10),
  (8522, NULL, 4, 'Museum Sri Baduga', 'Bandung', 'Jalan Peta No.185, Astanaanyar, Kota Bandung, Jawa Barat', 'Museum Sri Baduga merupakan sebuah museum yang terletak di Kota Bandung, Jawa Barat. Arsitektur museum ini dirancang menyerupai rumah panggung dengan suhunan panjang yang mencerminkan rumah khas Jawa Barat.', -6.93781, 107.604, 3000, ' 08.00–16.00;  08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sri%20Baduga%20Museum.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q3171723', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 9),
  (8523, NULL, 4, 'Museum Seni Neka', 'Gianyar', 'Ubud, Bali', 'Museum Seni Neka atau Neka Art Museum adalah sebuah museum seni lukis dan keris yang berlokasi di Ubud, provinsi Bali, Indonesia. Pembukaan Museum Seni Neka dimulai sejak 1976. Namun peresmiannya baru dilakukan pada 7 Juli 1982 oleh Daoed Joesoef selaku Menteri Pendidikan dan Kebudayaan.', -8.488988, 115.2536418, NULL, ' 9 AM–17.00; Min 12.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Foliage%20at%20the%20Neka%20Art%20Museum.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q924394', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 9),
  (8524, NULL, 4, 'Galeri Nasional Indonesia', 'Jakarta Pusat', 'Jalan Medan Merdeka Timur, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Galeri Nasional Indonesia (bahasa Inggris: National Gallery of Indonesia) adalah lembaga budaya negara yang berfungsi sebagai museum seni rupa modern dan kontemporer. Galeri ini memiliki gedung yang digunakan untuk pameran serta perhelatan seni rupa dari dalam dan luar negeri. Saat ini, Galeri Nasional Indonesia berada dalam naungan Museum dan Cagar Budaya, Kementerian Kebudayaan Republik Indonesia.', -6.1785255, 106.8327756, 0, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/National%20Gallery%20of%20Indonesia.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q6972830', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 9),
  (8525, NULL, 4, 'Museum Negeri Mpu Tantular', 'Indonesia', 'Jalan Kyai Haji Ali Mas\'ud, Sidokerto, Sidoarjo, Jawa Timur', 'Museum Negeri Mpu Tantular adalah sebuah museum negeri yang berlokasi di kecamatan Buduran, Sidoarjo, Jawa Timur. Awalnya, museum ini bernama Stedelijk Historisch Museum Soerabaia, didirikan oleh Godfried von Faber pada tahun 1933 dan diresmikan pada tanggal 25 Juli 1937. Saat ini, museum ini dikelola oleh Unit Pelaksana Teknis pada Departemen Kebudayaan dan Pariwisata.', -7.434, 112.7199167, 3000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/034%20Durga%20Mahesasuramardini%2C%20Mpu%20Tantular%20Museum%20%2826544597968%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499653', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8526, NULL, 4, 'Museum Pusat TNI AD "Dharma Wiratama"', 'Yogyakarta', 'Jalan Cik di Tiro, Gondokusuman, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Pusat TNI AD Dharma Wiratama (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦥꦸꦱꦠ꧀ꦠ꧀꧈ꦤ꧀꧈ꦆ꧈ꦄ꧈ꦢ꧀꧈ꦝꦂꦩꦮꦶꦫꦠꦩ, translit. Musiyum Pusat TNI AD Dharma Wiratama) adalah museum khusus yang memiliki koleksi tentang peran serta TNI AD dalam perjuangan Indonesia dalam mempertahankan kemerdekaan.', -7.78262, 110.37537, 0, ' 08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dharma%20Wiratama%20Museum%2004.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499663', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8527, NULL, 4, 'Istana Siak Sri Inderapura', 'Kampung Dalam', 'Jalan Kartini, Siak Sri Indrapura, Riau', 'Istana Siak Sri Indrapura (Jawi: ايستان سياق سري ايندراڤورا) atau Istana Asserayah Hasyimiah atau Istana Matahari Timur merupakan kediaman resmi Sultan Siak yang mulai dibangun pada tahun 1889, yaitu pada masa pemerintahan Sultan Syarif Hasyim. Istana ini merupakan peninggalan Kesultanan Siak Sri Indrapura yang selesai dibangun pada tahun 1893. Kini istana ini masuk wilayah administrasi pemerintahan Kabupaten Siak.', 0.79481, 102.048985, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Kerajaan%20Siak%20%282%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q41925', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 8),
  (8528, NULL, 4, 'Museum Ullen Sentalu', 'Yogyakarta', 'Taman Kaliurang, Hargobinangun, Sleman, Daerah Istimewa Yogyakarta', 'Museum Ullen Sentalu, (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦈꦭ꧀ꦭꦺꦤ꧀ꦱꦼꦤ꧀ꦠꦭꦸ, translit. Musiyum Ullèn Sentalu) terletak di Kecamatan Pakem (Kaliurang), Kabupaten Sleman, Daerah Istimewa Yogyakarta, adalah museum yang menampilkan budaya dan kehidupan para bangsawan Dinasti Mataram (Kasunanan Surakarta, Kesultanan Yogyakarta, Praja Mangkunegaran, dan Kadipaten Pakualaman) beserta koleksi bermacam-macam batik (baik gaya Yogyakarta maupun Surakarta).\nMuseum ini juga menampilkan koleksi patung-patung yang berbentuk tokoh-tokoh bangsawan zaman dahulu seperti tokoh raja-raja beserta permaisurinya dengan berbagai macam pakaian yang dikenakan, baik untuk acara formal maupun untuk keseharian.', -7.597973, 110.423174, 50000, ' 08.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Ullen%20Sentalu%20Spot%20Foto.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q3047067', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8529, NULL, 4, 'Museum Affandi', 'Yogyakarta', 'Jalan Laksda Adisucipto No.167, Catur Tunggal, Sleman, Daerah Istimewa Yogyakarta', 'Museum Affandi (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦄꦥ꦳꧀ꦥ꦳ꦤ꧀ꦢꦶ, translit. Musiyum Affandi) merupakan salah satu museum seni di Daerah Istimewa Yogyakarta, Indonesia. Museum yang berada di tepi Sungai Gajahwong ini menyimpan berbagai macam lukisan karya Affandi.', -7.7827, 110.3963, 50000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Barang%20koleksi%20berupa%20mobil%20dan%20sepeda%20onthel%20yang%20terpajang%20di%20dalam%20Galeri%20I%20Museum%20Affandi.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4688864', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8530, NULL, 4, 'Museum Indonesia', 'Jakarta Timur', 'Jalan Taman Mini Indonesia Indah, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Indonesia, adalah museum antropologi dan etnologi yang terletak di Taman Mini Indonesia Indah (TMII), Jakarta, Indonesia. Museum ini berkonsentrasi pada seni dan budaya berbagai suku bangsa yang menghuni Nusantara dan membentuk negara kesatuan Republik Indonesia. Museum ini bergaya arsitektur Bali dan dihiasi beraneka ukiran dan patung Bali yang sangat halus dan indah.', -6.3010573, 106.8914443, 15000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%20Museum%20Balinese%20Split%20Gate.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q1467232', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8531, NULL, 4, 'Museum Bank Mandiri', 'Jakarta', 'Jalan Asemka No.1, Taman Sari, Jakarta Barat', 'Museum Mandiri (atau Museum Bank Mandiri) adalah sebuah gedung dan museum sejarah yang terletak di Jl. Lapangan Stasiun No. 1, Jakarta Barat, DKI Jakarta dan dikelola oleh Bank Mandiri.', -6.13799, 106.81333, NULL, 'Sel–Min 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mandiri.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q1978377', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8532, NULL, 4, 'Museum Batik Pekalongan', 'Pekalongan', 'Jalan Jetayu No.1, Sampangan, Pekalongan, Jawa Tengah', 'Museum Batik Pekalongan adalah sebuah museum di Kota Pekalongan, Provinsi Jawa Tengah, Indonesia. Museum ini memiliki luas tanah dan bangunan 40 meter persegi dan memiliki 1149 koleksi batik, antara lain wayang beber dari kain batik yang berusia ratusan tahun dan alat tenun tradisional atau dikenal sebagai alat tenun bukan mesin. Museum Batik Pekalongan merupakan Unit Pelaksana Teknis Daerah (UPTD).', -6.8786168, 109.675473, 7000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Batik.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q7161016', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8533, NULL, 4, 'Museum Purna Bhakti Pertiwi', 'Jakarta', 'Gerbang 1 TMII, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Purna Bhakti Pertiwi (MPBP) didirikan oleh Yayasan Purna Bhakti Pertiwi atas prakarsa Tien Soeharto. Museum yang berada di Jalan Taman Mini I Jakarta ini, berisi koleksi benda-benda dan cendera mata berharga yang berhubungan dengan perjalanan pengabdian Presiden Republik Indonesia Ke-2 Soeharto.', -6.3003461, 106.8864414, NULL, 'Sab–Kam 09.00–16.00, Jum 09.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Purna%20Bhakti%20Pertiwi%20Museum%20Facade.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q7261332', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8534, NULL, 4, 'Museum Pers Nasional', 'Surakarta', 'Jalan Yosodipuro, Timuran, Surakarta, Jawa Tengah', 'Monumen Pers Nasional adalah museum khusus media massa (pers) nasional Indonesia yang terletak di Surakarta, Jawa Tengah. Koleksinya meliputi teknologi komunikasi dan teknologi reportase, seperti penerbangan, mesin tik, pemancar, telepon, dan kentongan besar. Museum ini didirikan pada 1978, setelah lebih dari 20 tahun diusulkan oleh Departemen Penerangan Indonesia.', -7.56502, 110.81805, NULL, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen%20Pers%20Nasional%2C%20Surakarta%20%28panorama%29.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q15287387', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8535, NULL, 4, 'Museum Geologi Bandung', 'Bandung', 'Jalan Diponegoro No.57, Cibeunying Kaler, Kota Bandung, Jawa Barat', 'Museum Geologi (bahasa Sunda: Musieum Géologi Bandung) didirikan pada tanggal 16 Mei 1929. Museum ini direnovasi dengan mendapat dana bantuan dari JICA  (Japan International Cooperation Agency). Setelah renovasi selesai, Museum Geologi dibuka kembali dan diresmikan oleh Wakil Presiden RI, Megawati Setiawati Soekarnoputri pada 23 Agustus 2000.', -6.9007, 107.6215, NULL, ' 9 AM–14.00;  9 AM–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Raflinoer32-Museum%20Geologi-Museum%20Geologi%20tampak%20depan.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q7475825', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8536, NULL, 4, 'Museum Adityawarman', 'Padang', 'Jalan Diponegoro No.10, Belakang Tangsi, Padang, Sumatera Barat', 'Museum Adityawarman adalah museum budaya yang terletak di Kota Padang, Sumatera Barat. Museum ini diresmikan pada 16 Maret 1977. Nama museum diambil dari nama besar salah seorang raja Malayapura pada abad ke-14, Adityawarman yang sezaman dengan Kerajaan Majapahit.', -0.95525, 100.3558333, 5000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Adityawarman%2020211213.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499632', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8537, NULL, 4, 'Museum Sumatera Utara', 'Sumatera Utara', 'Jalan H.M. Joni, Medan Kota, Kota Medan, Sumatera Utara', 'Museum Sumatera Utara atau yang lebih dikenal warga Sumut Museum Negeri Provinsi Sumatera Utara (disingkat Museum Negeri Provsu) ini terletak di Jln. H.M. Jhoni No. 51, Pasar merah, Medan.', 3.5681389, 98.6963056, 3000, ' 08.00–16.00;  08.30–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Negeri%20Sumatera%20Utara%20Medan.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499672', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8538, NULL, 4, 'Museum Perumusan Naskah Proklamasi', 'Jakarta', 'Jalan Imam Bonjol No.1, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Perumusan Naskah Proklamasi atau disingkat dengan Munasprok adalah gedung yang dibangun sebagai monumen peristiwa proses perumusan naskah proklamasi kemerdekaan di Indonesia. Lahan yang ditempati oleh Museum Perumusan Naskah Proklamasi seluas 3.914 m2 dengan bangunan seluas 1.138 m2. Bangunan yag dijadikan lokasi pendirian Museum Perumusan Naskah Proklamasi telah dibangun sejak tahun 1920.', -6.20036, 106.83115, NULL, 'Sel–Kam 08.00–16.00; Jum 08.00–11.30; Sab–Min 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Satriamandala%20Museum%20main%20building.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q15260362', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 8),
  (8539, NULL, 4, 'Museum Sasmita Loka', 'Jakarta', 'Jalan Lembang, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Sasmitaloka Jenderal Ahmad Yani atau Museum Ahmad Yani adalah salah satu museum pahlawan nasional yang terletak di jalan Lembang No. 58, Menteng, Jakarta Pusat. Museum ini dahulunya merupakan bekas rumah kediaman Jenderal Ahmad Yani, salah seorang Pahlawan Revolusi yang gugur dalam peristiwa Pemberontakan PKI yang dikenal dengan G.30 S/PKI tahun 1965.', -6.2045861, 106.8365667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/MuseumSasmitaLoka1.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2454010', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8540, NULL, 4, 'Candi Agung', 'Amuntai', 'Jalan Haji Kurdi Yusni, Amuntai, Kalimantan Selatan', 'Candi Agung adalah sebuah situs candi Hindu beratap yang terletak di Kelurahan Sungai Malang, kecamatan Amuntai Tengah, Kota Amuntai, Kalimantan Selatan. Di sekitar candi pernah ditemukan tiang kayu ulin dan pecahan genteng.\nCandi ini diperkirakan peninggalan Kerajaan Negara Dipa yang keberadaannya sezaman dengan Kerajaan Majapahit.', -2.414207, 115.248318, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Agung.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q2936250', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 7),
  (8541, NULL, 4, 'Benteng Pendem Cilacap', 'Cilacap', 'Jalan Karang, Cilacap, Kelurahan Cilacap Kecamatan Cilacap, Jawa Tengah', 'Benteng Pendem Cilacap (bahasa Belanda: Kustbatterij op de Landtong te Tjilatjap), merupakan benteng pertahanan peninggalan pemerintah Hindia Belanda yang terletak di tepi pantai Cilacap, Jawa Tengah. Benteng Pendem bersebelahan dengan objek wisata Teluk Penyu dan dibangun pada tahun 1861 dan selasai tahun 1879 dengan luas wilayah 10,5 ha. Benteng ini kemudian ditemukan dan mulai digali pemerintah Cilacap tahun 1986.', -7.74921, 109.017, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barracks%2C%20Benteng%20Pendem%2C%20Cilacap%202015-03-21.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4262369', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8542, NULL, 4, 'Pusat Dokumentasi dan Informasi Kebudayaan Minangkabau', 'Silaing Bawah', 'Jalan Sutan Syahrir, Padang Panjang Barat, Padang Panjang, Sumatera Barat', 'Pusat Dokumentasi dan Informasi Kebudayaan Minangkabau atau biasa disingkat PDIKM adalah salah satu museum di Sumatera Barat yang terletak di Kelurahan Silaing Bawah, Kecamatan Padang Panjang Barat, Kota Padang Panjang. Museum ini bersisikan berbagai macam informasi dan koleksi mengenai kebudayaan Minangkabau baik berupa dokumentasi audio maupun visual. Museum ini dapat diakses dari jalur utama Padang–Bukittinggi, berjarak sekitar lebih kurang dua kilometer dari pusat Kota Padang Panjang.', -0.470234, 100.378817, NULL, 'Kam 07.00–15.00;  07.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Gadang%20Minangkabau%20PDIKM%2C%20Padang%20Panjang.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q643129', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8543, NULL, 4, 'Museum Sasmitaloka Jenderal Besar DR. A.H. Nasution', 'Jakarta', 'Jalan Teuku Umar, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Abdul Haris Nasution atau tepatnya Museum Sasmitaloka Jenderal Besar DR. Abdul Haris Nasution adalah salah satu museum pahlawan nasional yang terletak di jalan Teuku Umar No. 40, Jakarta Pusat, DKI Jaya, Indonesia. Museum ini terbuka untuk umum dari hari Selasa hingga hari Minggu, dari pukul 08:00 hingga pukul 14:00 WIB. Setiap hari Senin dan setelah libur nasional museum ini ditutup untuk umum.', -6.19297, 106.83268, NULL, ' 08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/MuseumJendralAHNasution.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q1839448', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8544, NULL, 4, 'Museum Blanco Renaissance', 'Ubud', 'Jalan Raya Penestanan, Ubud, Bali', 'Museum Blanco Renaissance adalah sebuah museum yang berlokasi di Ubud, provinsi Bali, Indonesia. Museum ini berdiri dari keinginan Antonio Blanco, seorang pelukis untuk suatu hari nanti memiliki museum yang akhirnya mulai terwujud juga dan diberi nama The Blanco Renaissance Museum.', -8.5058, 115.2543, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Antonio%20Blanco%20le%20mus%C3%A9e.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4924960', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8545, NULL, 4, 'Benteng Marlborough', 'Bengkulu', 'Jalan Benteng, Kebun Keling, Bengkulu, Bengkulu', 'Benteng Marlborough (bahasa Inggris: Fort Marlborough), juga dikenal sebagai Malabero, adalah bekas benteng Perusahaan Hindia Timur yang terletak di Kota Bengkulu, Sumatra. Dibangun antara tahun 1713 dan 1719 oleh Perusahaan Hindia Timur di bawah kepemimpinan Gubernur Joseph Collett sebagai benteng pertahanan Keresidenan Perusahaan Hindia Timur di sana. Itu adalah salah satu benteng Inggris terkuat di wilayah timur, kedua setelah Benteng St.', -3.78748, 102.25099, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bengkulu%20City%20and%20Fort%20Marlborough.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q5471595', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8546, NULL, 4, 'Museum Pasifika', 'Kuta Selatan', '1 No.777, Benoa, Kuta Selatan, Bali', 'Museum Pasifika (Nusa Dua Bali) adalah museum seni di Komplek BTDC Area Blok P, Bali, Indonesia. yang menyajikan kebudayaan Asia dan Pasifik dan berbagai macam lukisan serta artefak budaya. Museum ini didirikan pada tahun 2006 oleh Moetaryanto P and Philippe Augier.', -8.8, 115.2306, 70000, 'Sen–Min 10.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pasifika.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q6940675', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8547, NULL, 4, 'Museum Kebangkitan Nasional', 'Jakarta Pusat', 'Jalan Abdulrahman Saleh Raya, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Kebangkitan Nasional adalah sebuah gedung yang dibangun sebagai monumen tempat lahir dan berkembangnya kesadaran nasional dan juga ditemukannya organisasi pergerakan modern pertama kali dengan nama Boedi Oetomo. Sebelum menjadi museum, bangunan ini dahulunya adalah sekolah kedokteran yang didirikan oleh Belanda dengan nama School tot Opleiding van Inlandsche Artsen (STOVIA). Dalam perjalanannya, gedung tersebut selalu beralih fungsi.', -6.1787259, 106.837968, NULL, ' 08.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Old%20Dutch%20building%20-%20panoramio.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q16726213', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8548, NULL, 4, 'Museum Satriamandala', 'Indonesia', 'Jalan Poncol Gang I, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Museum Satria Mandala adalah museum sejarah perjuangan Tentara Nasional Indonesia yang terletak di Jalan Gatot Subroto Kav. 14, Jakarta Selatan. Museum yang diresmikan pada tahun 1972 oleh mantan Presiden Indonesia, Soeharto sebelumnya dikenal sebagai Wisma Yaso, yang merupakan rumah dari salah satu istri mantan Presiden Indonesia, Soekarno, yaitu Ratna Sari Dewi Soekarno.', -6.2317, 106.81854, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20Satriamandala.01.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q7426467', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8549, NULL, 4, 'Museum Sumpah Pemuda', 'Jakarta', 'Jalan Kramat Raya, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Sumpah Pemuda adalah sebuah museum sejarah perjuangan kemerdekaan Republik Indonesia yang berada di Jalan Kramat Raya No. 106, Jakarta Pusat dan dikelola oleh Museum dan Cagar Budaya, Kementerian Kebudayaan Republik Indonesia. Museum ini didirikan berdasarkan SK Gubernur DKI Jakarta pada 1972 dan menjadi benda cagar budaya nasional.', -6.18416, 106.84328, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/MuseumSumpahPemuda.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499673', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 7),
  (8550, NULL, 4, 'Museum Angkut', 'Jawa Timur', 'Jalan Terusan Sultan Agung, Lowokwaru, Kota Batu, Jawa Timur', 'Museum Angkut merupakan museum transportasi dan tempat wisata modern yang terletak di Jl. Terusan Sultan Agung Atas No. 2, Kota Batu, Jawa Timur, sekitar 20 km dari Kota Malang.', -7.87906, 112.51986, 70000, ' 12.00–20.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20angkut.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q23001217', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8551, NULL, 4, 'Museum Huta Bolon Simanindo', 'Sumatera Utara', 'Jalan Raya Ambarita, Cinta Dame, Samosir, Sumatera Utara', 'Museum Huta Bolon Simanindo merupakan rumah tradisional Batak warisan dari Raja Sidauruk sejak tahun 1969. Museum ini terletak di Desa Simanindo, Kecamatan Simanindo, Kabupaten Samosir, Provinsi Sumatera Utara.', 2.7525, 98.7445, 10000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Bolon%20di%20Museum%20Huta%20Bolon%20Simanindo.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q24929048', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8552, NULL, 4, 'Museum Hakka Indonesia dan Taman Tionghoa', 'Jakarta Timur', 'Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Hakka Indonesia (Hanzi: 印尼客家博物館, bahasa Inggris: Indonesian Hakka Museum) adalah museum yang didirikan oleh Perhimpunan Hakka Indonesia Sejahtera yang berisikan informasi mengenai perjalanan sejarah Hakka di Indonesia. Museum ini berlokasi di komplek Taman Budaya Tionghoa, Taman Mini Indonesia Indah, Jakarta Timur, Jakarta, Indonesia.', -6.3053889, 106.904, NULL, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%20Hakka%20Museum.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q28129003', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8553, NULL, 4, 'Museum Monumen Yogya Kembali', 'Indonesia', 'Sinduadi, Sleman, Daerah Istimewa Yogyakarta', 'Museum Monumen Yogya Kembali (bahasa Jawa: ꦩꦺꦴꦤꦸꦩꦺꦤ꧀ꦪꦺꦴꦒꦾꦏꦼꦩ꧀ꦧꦭꦶ, translit. Monumèn Yogya Kembali) biasa dikenal sebagai Monumen Jogja Kembali disingkat Monjali adalah sebuah museum sejarah perjuangan kemerdekaan Indonesia yang ada di Daerah Istimewa Yogyakarta dan dikelola oleh Kementerian Pariwisata dan Ekonomi Kreatif. Museum yang berada di bagian utara kota ini banyak dikunjungi oleh para pelajar dalam acara darmawisata.', -7.749577, 110.369599, 10000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen%20Yogya%20Kembali.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q12499652', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 0),
  (8554, NULL, 4, 'Museum Lambung Mangkurat', 'Banjarbaru', 'Jalan Jenderal Achmad Yani, Komet, Banjarbaru, Kalimantan Selatan', 'Museum Lambung Mangkurat adalah museum Tipe A yang terletak di Jl. Jend. Ahmad Yani Km.', -3.4421177, 114.8381567, 3000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20lambung%20mangkurat%202023-12-08%206107.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q3582938', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8555, NULL, 4, 'Museum Taman Prasasti', 'Jakarta', 'Jalan Tanah Abang I, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Taman Prasasti atau Museum Prasasti adalah sebuah museum yang terletak di Jakarta, Indonesia. Museum ini dulunya merupakan pemakaman yang dibangun oleh pemerintah kolonial Belanda pada tahun 1795 sebagai tempat peristirahatan terakhir bagi para bangsawan Belanda. Beberapa tokoh penting yang dimakamkan di area pemakaman ini antara lain Olivia Mariamne Raffles – istri pertama Gubernur Jenderal Inggris Thomas Stamford Raffles – dan aktivis pemuda Indonesia Soe Hok Gie.', -6.1721921, 106.8189735, 5000, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tamanprasasti.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q4264481', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8556, NULL, 4, 'Museum Karmawibhangga', 'Jawa Tengah', 'Jalan Salaman - Mungkid, Borobudur, Jawa Tengah', 'Museum Karmawibhangga atau juga disebut Museum Borobudur, adalah sebuah museum arkeologi yang terletak di dalam kawasan Taman Wisata Candi Borobudur, Kabupaten Magelang, Provinsi Jawa Tengah, Indonesia. Museum ini menampilkan gambar relief Karmawibhangga yang terukir pada kaki tersembunyi Borobudur, beberapa blok batu Borobudur yang terlepas, serta temuan artefak arkeologi yang ditemukan di sekitar Borobudur dan yang berasal dari berbagai situs-situs purbakala di Jawa Tengah. Museum ini juga menampilkan struktur arsitektur Borobudur, serta dokumentasi proyek pemugaran besar-besaran antara tahun 1975 dan 1982 yang dibantu oleh UNESCO. Bangunan museum ini dibangun dengan gaya arsitektur tradisional Jawa, yaitu berupa rumah joglo lengkap dengan pendopo.', -7.6041906, 110.2046431, 0, ' 07.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Karmawibhangga%20Museum%20Pendopo%20of%20Borobudur.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q6372721', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8557, NULL, 4, 'Museum Mulawarman', 'Kutai Kartanegara', 'Jalan Pangeran Diponegoro No.26, Panji, Kutai Kartanegara, Kalimantan Timur', 'Museum Mulawarman adalah sebuah museum di kota Tenggarong, Kabupaten Kutai Kartanegara, Kalimantan Timur, Indonesia. Museum ini merupakan bekas istana dari Kesultanan Kutai Kartanegara yang dibangun oleh arsitek Belanda Holland Beton Mattscappy (HBM) pada 1935 tepat pada masa pemerintahan Sultan Aji Mohammad Parikesit dan rampung pada 1938. Museum ini diresmikan sebagai Museum Kutai pada 25 November 1971 oleh Gubernur Abdoel Wahab Sjahranie, lalu diserahterimakan kepada Departemen Pendidikan dan Kebudayaan tanggal 18 Februari 1976 dan berganti nama menjadi Museum Negeri Provinsi Kalimantan Timur "Mulawarman".', -0.41308, 116.9904, 5000, ' 08.30–16.30;  08.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mulawarman.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q6933766', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8558, NULL, 4, 'Museum dan Galeri Seni Rudana', 'Gianyar', 'Jalan Cok Rai Pudak, Ubud, Bali', 'Museum Rudana adalah sebuah museum seni yang berada di Ubud, Gianyar, Bali dan digunakan untuk memamerkan dan mempromosikan karya seni berupa lukisan dan patung karya seniman Bali.\nMuseum ini memamerkan karya seni dari I Gusti Nyoman Lempad (almarhum), Nyoman Gunarsa, Made Wianta,seniman Indonesia di luar Bali seperti Affandi (almarhum), Basuki Abdullah (almarhum), Srihadi Soedarsono, Sunaryo Sutono, maupun seniman asing yang tinggal di Bali seperti Antonio Blanco (almarhum), Arie Smit. Museum Rudana didirikan oleh Nyoman Rudana, seorang kolektor lukisan yang juga pemilik galeri seni Rudana Fine Art Gallery dan Genta Fine Art Gallery.', -8.5296389, 115.2712778, NULL, ' 09.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rudana%20in%20Ubud%2C%20Bali%2C%20Indonesia.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q6940689', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8559, NULL, 4, 'Museum Nasional Jogja', 'Yogyakarta', 'Jalan Profesor Dokter Ki Amri Yahya, Wirobrajan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Nasional Jogja, (bahasa Inggris: Jogja National Museum, JNM) adalah museum dan galeri seni kontemporer yang berdiri di bawah naungan Yayasan Yogyakarta Seni Nusantara (YSSN). Museum ini beralamat di Jalan Amri Yahya No. 1, Gampingan, Wirobrajan, Yogyakarta.', -7.8001561, 110.3534327, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ARTJOG%20di%20Jogja%20National%20Museum.jpg?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q16766372', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8560, NULL, 4, 'Museum Layang-layang Indonesia', 'Jakarta', 'Jalan Haji Kamang, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Museum Layang-Layang Indonesia adalah sebuah museum yang terletak di Jl. H. Kamang No. 38, Pondok Labu, Jakarta Selatan.', -6.3078, 106.79059, 25000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Layang-layang%20Panoramic.JPG?width=800', '2026-11-04 09:39:34', '2026-11-24 23:32:50', 'wd:Q17052315', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (8561, NULL, 4, 'Istana Bogor', 'Bogor', 'Jalan Insinyur Haji Djuanda, Bogor Tengah, Bogor, Jawa Barat', 'Istana Bogor (bahasa Inggris: Bogor Palace; bahasa Belanda: Het Paleis te Buitenzorg) adalah salah satu dari tujuh istana kepresidenan Indonesia yang terletak di Kota Bogor, Jawa Barat. Istana ini terkenal karena fitur arsitektur dan sejarahnya yang khas, serta kebun raya yang bersebelahan dengannya. Istana Bogor dibuka untuk umum pada tahun 1968 untuk rombongan wisata umum (bukan individu), dengan izin dari Penjabat Presiden Indonesia, Soeharto.', -6.597996, 106.79735, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Bogor.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q911762', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 17),
  (8562, NULL, 4, 'Istana Maimun', 'Medan', 'Jalan Brigjen Katamso, Medan Maimun, Kota Medan, Sumatera Utara', 'Istana Maimun atau Istana Maimoon adalah istana Kesultanan Deli yang merupakan salah satu ikon Kota Medan, Sumatera Utara. Istana ini terletak di Jalan Brigadir Jenderal Katamso, Aur, Medan Maimun.\nIstana Maimun didesain oleh arsitek Capt.', 3.5752, 98.68381, 5000, 'Sen–Min 08.00–17.00, Kam 08.00–12.00,14.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maimun%20Palace%20Medan%20Indonesia.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q1674833', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 14),
  (8563, NULL, 4, 'Istana Cipanas', 'Cianjur', 'Jalan Raya Puncak, Pacet, Cianjur, Jawa Barat', 'Istana Cipanas adalah salah satu dari tujuh istana kepresidenan Republik Indonesia. Istana ini terletak di Cipanas, Jawa Barat, Indonesia, dekat jalan raya yang menghubungkan Jakarta dan Bandung melalui Puncak. Terletak sekitar 103 kilometer (64 mi) dari Jakarta, atau sekitar 20 kilometer (12 mi) dari kota Cianjur.', -6.733569, 107.041077, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palace%20Cipanas.JPG?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12486833', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 14),
  (8564, NULL, 4, 'Istana Klungkung', 'Bali', 'Jalan Kenanga, Semarapura Kelod, Klungkung, Bali', 'Puri Agung Klungkung atau Puri Agung Semarajaya atau Puri Agung Semarapura adalah sebuah kompleks bangunan bersejarah yang terletak di Semarapura, ibu kota Kabupaten Klungkung, Bali, Indonesia. Istana atau puri ini diperkirakan mulai dibangun pada tahun 1686 sebagai istana kediaman raja Kerajaan Klungkung dari tahun 1700 - 1908. Pada gerbang utama (Pemedal Agung) istana bertuliskan sebuah candrasengkala berangka tahun saka 1622 (1700 M) yang diyakini sebagai tahun rampungnya istana ini.', -8.53564, 115.40298, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klungkung-Palace-1.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q1164385', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 13),
  (8566, NULL, 4, 'Istana Ubud', 'Ubud', 'Jalan Made Lebah, Ubud, Bali', 'Istana Ubud, secara resmi Puri Saren Agung, adalah kompleks bangunan bersejarah yang terletak di Ubud, Kabupaten Gianyar, Bali, Indonesia. Istana adalah tempat tinggal resmi keluarga bangsawan Ubud.', -8.5068, 115.2626, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Entrance%20Gate%2C%20Ubud%20Palace%2C%20Bali%201639.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q19646466', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 11),
  (8567, NULL, 4, 'Keraton Kasepuhan Cirebon', 'Cirebon', 'Jalan Kasepuhan No.43, Lemahwungkuk, Cirebon, Jawa Barat', 'Keraton Kasepuhan adalah keraton yang terletak di kelurahan Kesepuhan, Lemahwungkuk, Cirebon. Makna di setiap sudut arsitektur keraton ini pun terkenal paling bersejarah. Halaman depan keraton ini dikelilingi tembok bata merah dan terdapat pendopo di dalamnya.', -6.7262908, 108.5709169, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Symbol%20Keraton%20Kasepuhan.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q399336', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 9),
  (8568, NULL, 4, 'Keraton Kanoman', 'Cirebon', 'Jalan Kanoman No.40, Pekalipan, Cirebon, Jawa Barat', 'Keraton Kanoman adalah salah satu dari dua bangunan kesultanan Cirebon, setelah berdiri keraton Kanoman pada tahun 1678 M kesultanan Cirebon terdiri dari keraton Kasepuhan dan keraton Kanoman. Kebesaran Islam di Jawa bagian barat tidak lepas dari Cirebon. Sunan Gunung Jati adalah orang yang bertanggung jawab menyebarkan agama Islam di Jawa Barat, sehingga berbicara tentang Cirebon tidak akan lepas dari sosok Syarif Hidayatullah atau Sunan Gunung Jati.', -6.7262908, 108.5709169, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Kinderen%20voor%20de%20poort%20van%20de%20kraton%20Kanoman%20Cheribon%20TMnr%2060005192.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q643143', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 9),
  (8570, NULL, 4, 'Taman Mayura', 'Mayura', 'Kel. Cakranegara Timur, Mataram, Nusa Tenggara Barat', 'Taman Mayura dibangun oleh Anak Agung Gde Ngurah Karangasem pada 1866, berjarak 2 kilometer dari timur Mataram.\nSejarah keberadaan Taman Mayura, di mana taman ini sudah ada pada zaman Kerajaan Singasari pada abad ke-19. Taman Mayura adalah sebuah taman yang dibangun oleh raja sebagai kompleks istana raja.', -8.58668, 116.13317, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Tempelcomplex%20Majoera%20TMnr%2060012462.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q25300699', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 7),
  (8571, NULL, 4, 'Keraton Kacirebonan', 'Cirebon', 'Jalan Pulasaren No.49, Pekalipan, Cirebon, Jawa Barat', 'Keraton Kacirebonan adalah sebuah bangunan dahulu sebagai tempat para selir para raja dan sultan keraton kasepuhan yang berada di daerah Pulasaren (sekarang jalan Pulasaren, kecamatan Pekalipan, kota Cirebon). Keraton Kacirebonan dibangun pada sekitar tahun 1800-an. Bangunan kolonial ini banyak menyimpan benda-benda peninggalan sejarah seperti Keris, Wayang, perlengkapan Perang, Gamelan dan lain-lain.', -6.7252, 108.56536, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton-kacirebonan.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q643137', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 6),
  (8572, NULL, 4, 'Keraton Kasunanan Surakarta', 'Surakarta', 'Jalan Gondorasan, Baluwarti, Surakarta, Jawa Tengah', 'Keraton Surakarta Hadiningrat atau Keraton Surakarta (bahasa Jawa: ꦏꦣꦠꦺꦴꦤ꧀ꦱꦸꦫꦏꦂꦠꦲꦣꦶꦤꦶꦔꦿꦠ꧀, translit. Kadhaton Surakarta Hadiningrat) adalah Istana  milik Kerajaan Kasunanan Surakarta Hadiningrat  (Kagungan Dalem)yang terletak di Kota Surakarta. Keraton ini didirikan oleh Sri Susuhunan Pakubuwana II sekitar tahun 1743-1744 sebagai pengganti Keraton Kartasura yang porak-poranda akibat Geger Pecinan pada tahun 1743.', -7.57749, 110.82797, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kraton%20Solo.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q13095204', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 6),
  (8573, NULL, 4, 'Taman Narmada', 'Lombok Barat', 'Narmada, Nusa Tenggara Barat', 'Taman Narmada terletak di Desa Lembuak, Kecamatan Narmada, Kabupaten Lombok Barat atau sekitar 10 kilometer sebelah timur Kota Mataram, Provinsi Nusa Tenggara Barat, Indonesia. Taman yang luasnya sekitar 2 ha(hektar are) ini dibangun pada tahun 1727 oleh Raja Mataram Lombok, Anak Agung Ngurah Karang Asem, sebagai tempat upacara Pakelem yang diselenggarakan setiap purnama kelima tahun śaka (Oktober-November). Selain tempat upacara, Taman Narmada juga digunakan sebagai tempat peristirahatan keluarga raja pada saat musim kemarau.', -8.59544, 116.20452, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Narmada%20Water%20Palace.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q2207195', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 5),
  (8574, NULL, 4, 'Istana Sangkak Karojan', 'Kamang Baru', 'Nagari Air Amo, Sijunjung, Sumatera Barat', 'Rumah Gadang Sangkak Karojan adalah sebuah rumah gadang yang berada di Nagari Aie Amo, Kecamatan Kamang Baru, Sumatera Barat. Rumah Gadang ini termasuk kedalam benda cagar budaya.Bangunan Rumah Gadang ini berbentuk rumah panggung yang ditopang 20 tiang berdiameter rata-rata 16 cm. Tiang terbuat dari kayu Jua/Juar (nama Latin Senna siamea) dan tegak di atas batu sandi.', -0.7089553, 101.2427596, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Sangkak%20Karojan%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q124393630', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 3),
  (8575, NULL, 4, 'Istana Silinduang Bulan', 'Indonesia', 'Pagaruyung, Tanah Datar, Sumatera Barat', 'Istano Silinduang Bulan atau Istana Silindung Bulan merupakan istana yang terletak di Nagari Pagaruyung, Kecamatan Tanjung Emas, Kabupaten Tanah Datar, Sumatera Barat. Kini istana tersebut telah direnovasi setelah mengalami kebakaran pada tanggal 21 Maret 2010.', -0.466274, 100.615472, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istano%20Silinduang%20Bulan.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12486844', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 3),
  (8576, NULL, 4, 'Keraton Surosowan', 'Serang', 'Jalan Masjid Agung Banten, Kasemen, Serang, Banten', 'Keraton Surasowan adalah sebuah keraton dan sekaligus cagar budaya yang ada di di Kawasan Banten Lama, Kecamatan Kasemen, Kota Serang, Provinsi Banten. Keraton ini pertama dibangun sekitar tahun 1526 hingga tahun 1570 pada masa pemerintahan Maulana Hasanuddin, yang kemudian dikenal sebagai pendiri dari Kesultanan Banten. \nSejarah pembuatan keraton ini terkait dengan pemberian wilayah yang diberikan oleh Sunan Gunung Djati kepada anaknya, yakni Sultan Maulana Hasanuddin.', -6.035316, 106.157835, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Surosowan%20%283%29.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12491098', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 3),
  (8577, NULL, 4, 'Keraton Kaibon', 'Serang', 'Jalan Raya Banten, Kasemen, Serang, Banten', 'Keraton Kaibon adalah sebuah keraton peninggalan Kesultanan Banten yang terletak di Kota Serang, tepatnya berada di Kelurahan Kasunyatan, Kecamatan Kasemen, Kota Serang, Banten. Keraton ini dibangun kira-kira tahun 1815 dan dihancurkan oleh Belanda pada tahun 1832, sehingga menyisakan berupa pondasi, tembok-tembok bangunan dan gapura keraton. Pada tahun 1998 Keraton Kaibon secara resmi ditetapkan sebagai salah satu situs cagar budaya di Kota Serang.', -6.0428209, 106.1599678, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Kaibon-4.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12491096', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 3),
  (8578, NULL, 4, 'Istano Rajo Baloen', 'Koto Parik Gadang Diateh', 'Pakan Raba\'a Tengah, Sumatera Barat', 'Istana Rajo Balun merupakan bangunan istana yang masih lestari dan berdiri kokoh di Alam Surambi Sungai Pagu. Istana Rajo Balun terletak di Jorong Balun, Desa Pakan Rabaa, Kecamatan Muarolabuah, Kecamatan Koto Parik Gadang Diateh, Kabupaten Solok Selatan. Istana ini sangat mudah ditemukan karena letaknya dekat dengan tepi jalan raya.', -1.4075146, 100.9965812, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istano%20Rajo%20Baloen%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q83908689', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 3),
  (8579, NULL, 4, 'Istana Surya Negara Sanggau', 'Kalimantan Barat', 'Rambai, Ilir Kota, Kapuas, Kalimantan Barat', 'Istana Surya Negara adalah sebuah istana yang terletak di Jalan Pangeran Mas, Desa Tanjung Sekayam, Kecamatan Kapuas, Kabupaten Sanggau, Kalimantan Barat, Indonesia. Istana Surya Negara telah ditetapkan sebagai salah satu cagar budaya Indonesia. Benda-benda yang disimpan di dalam istana merupakan peninggalan Kerajaan Sanggau.', 0.1220921, 110.6029546, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Surya%20Negara%20Sanggau%2002.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q104636350', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8580, NULL, 4, 'Istana Mini', 'Banda', 'Jalan Kujali, Bandanaira, Maluku Tengah, Maluku', 'Istana Mini: Istana di Maluku Tengah, Maluku, Indonesia, Banda.', -4.52872, 129.90046, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Mini%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q106278587', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8581, NULL, 4, 'Istana Belitang', 'Kalimantan Barat', 'Belitang, Sekadau, Kalimantan Barat', 'Istana Belitang disebut juga Istana Kesenangan adalah sebuah Istana yang terletak di Desa Belitang Satu, Kecamatan Belitang, Kabupaten Sekadau, Kalimantan Barat. Istana merupakan bagian dari sejarah Kerajaan Sekadau di Kalimantan Barat, Indonesia. Kerajaan yang dikenal dengan nama Kerajaan Kusuma Negara Sekadau ini didirikan sekitar tahun 1550 dan berakhir pada tahun 1952 dengan penggabungannya dengan Negara Republik Indonesia Serikat (NKRI).', 0.1312521, 111.2495601, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Belitang%20Sekadau%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q131344302', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8582, NULL, 4, 'Istana Kerajaan Silat', 'Kalimantan Barat', 'Perigi, Kapuas Hulu, Kalimantan Barat', 'Kerajaan Silat adalah sebuah kerajaan Islam yang berlokasi di Kecamatan Silat Hilir, Kabupaten Kapuas Hulu, Kalimantan Barat. Kerajaan ini memiliki sejarah panjang yang dipengaruhi oleh berbagai unsur budaya dan peristiwa penting. Awalnya, kerajaan ini dikenal dengan nama Jempulin Panjang.', 0.339158, 111.7880491, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiang%20Bendera%20Istana%20Kerajaan%20Silat%2002.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q131344327', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8583, NULL, 4, 'Istana Karimata', 'Kalimantan Barat', 'Padang, Kayong Utara, Kalimantan Barat', 'Istana Karimata adalah sebuah Istana (ada yang menyebut rumah tua) yang terletak di Desa Padang, Kecamatan Kepulauan Karimata, Kabupaten Kayong Utara, Provinsi Kalimantan Barat. Istana ini berupa rumah panggung yang merupakan bekas rumah dari Tengku Dja\'far. Istana ini didirikan oleh penguasa Karimata dan pernah ditinggali raja bernama Tengku Abdul Jalil, bangsawan dari Kesultanan Siak.', -1.6386058, 108.9530768, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Karimata%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q131544954', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8584, NULL, 4, 'Istana Tuanku Bosa', 'Talu', 'Sungai Janiah Talu, Pasaman Barat, Sumatera Barat', 'Istana Tuanku Bosa: Istana di Pasaman Barat, Talu.', 0.2133405, 99.9904673, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Tuanku%20Bosa%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q136005902', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8585, NULL, 4, 'Istana Alwatzikoebillah', 'Kalimantan Barat', 'Sambas, Kalimantan Barat', 'Istana Alwatzikoebillah merupakan istana Kesultanan Sambas yang menjadi pusat pemerintahan di Sambas hingga berakhirnya kekuasaan kesultanan. Istana ini terletak di Desa Dalam Kaum, Kecamatan Sambas, Kabupaten Sambas, Provinsi Kalimantan Barat.', 1.3617228, 109.3130395, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Alwatzikoebillah%20Sambas.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12486832', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8586, NULL, 4, 'Kedaton Kutai Kartanegara', 'Tenggarong', 'Jalan Monumen Timur, Panji, Kutai Kartanegara, Kalimantan Timur', 'Kedaton Kutai Kartanegara adalah istana milik Sultan Kutai Kartanegara yang terletak di pusat kota Tenggarong, Kalimantan Timur, Indonesia. Istana ini selesai dibangun oleh Pemerintah Kabupaten Kutai Kartanegara pada tahun 2002 setelah dihidupkannya kembali Kesultanan Kutai Kartanegara ing Martapura.\nMeski telah resmi menjadi milik Sultan Kutai Kartanegara, istana baru ini lebih difungsikan sebagai kantor lembaga kesultanan serta sebagai tempat pelaksanaan acara seremonial oleh Sultan atau Kesultanan Kutai Kartanegara ing Martapura.', -0.4135645, 116.9888612, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kedaton%20Kutai%20Kartanegara%20%282%29.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q12490234', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8587, NULL, 4, 'Istana Amantubillah', 'Kalimantan Barat', 'Pulau Pedalaman, Mempawah, Kalimantan Barat', 'Amantubillah merupakan nama istana dari Kerajaan Mempawah, mempunyai arti, “Aku beriman kepada Allah”. Istana yang didominasi oleh wama hijau ini menempatkan tulisan “Mempawah Harus Maju, Malu dengan Adat" pada pintu gerbang istana. Kompleks Istana Amantubillah berdiri kukuh di Desa Pulau Pedalaman, Kecamatan Mempawah Timur, kabupaten mempawah, Provinsi Kalimantan Barat, Indonesia.', 0.3710955, 108.9589503, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Amantubillah%203.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q19745521', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8588, NULL, 4, 'Keraton Kadariah', 'Kalimantan Barat', 'Pontianak Timur, Pontianak, Kalimantan Barat', 'Istana Kadriah atau Keraton Kadriah adalah istana Kesultanan Pontianak yang dibangun pada dari tahun 1771 sampai 1778 masehi. Sayyid Syarif Abdurrahman Al-qadrie adalah sultan pertama yang mendiami istana tersebut. Istana ini berada di dekat pusat Kota Pontianak, Kalimantan Barat.', -0.0264718, 109.3500262, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Kadariah%2001.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q25459921', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
  (8589, NULL, 4, 'Istana Al Mukarramah', 'Kalimantan Barat', 'Pangeran Kuning, Sintang, Kalimantan Barat', 'Musem Dara Juanti merupakan museum yang menyimpan berbagai bukti sejarah perabadan daerah Sintang sekaligus sebagai bekas lokasi pusat pemerintahan Kerajaan Sintang, yakni Istana Al-Mukarramah. Museum yang juga bekas kompleks kerajaan Sintang hingga saat ini masih terawat baik dan menjadi tempat tinggal Sultan Sintang, Pangeran Ratu Sri Negara H.R.M. Ikhsan Perdana. Nama Dara Juanti diambil dari nama putri pendiri kerajaan Sintang, Demong Irawan, yang bernama Putri Dara Juanti.', 0.0821532, 111.4902296, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Al%20Mukarramah%20Kesultanan%20Sintang%2005.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q25470063', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 2),
