  (8608, NULL, 4, 'Istana Paku Negara Sanggau', 'Kalimantan Barat', 'Beringin, Kapuas, Kalimantan Barat', 'Istana Paku Negara Sanggau adalah istana / keraton di Kalimantan Barat.', 0.1200503, 110.5933192, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Paku%20Negara%20Sanggau%201.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q104636419', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 1),
  (8609, NULL, 4, 'Cakranegara palace', 'Indonesia', 'Kel. Cakranegara Timur, Mataram, Nusa Tenggara Barat', 'Cakranegara palace adalah istana / keraton di Indonesia.', -8.5881905, 116.1322001, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Het%20Mayura%20waterpaleis%20te%20Tjakranegara%20TMnr%2060017202.jpg?width=800', '2026-11-04 09:39:45', '2026-11-24 23:32:50', 'wd:Q122499151', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 1),
  (8610, NULL, 4, 'Candi Borobudur', 'Magelang', 'Desa Borobudur, Magelang, Jawa Tengah', 'Candi Borobudur (bahasa Jawa: ꦕꦟ꧀ꦝꦶꦧꦫꦧꦸꦝꦸꦂ, translit. Candhi Båråbudhur) adalah sebuah candi Buddha yang terletak di Borobudur, Magelang, Jawa Tengah, Indonesia. Candi ini terletak kurang lebih 100 km di sebelah barat daya Semarang, 86 km di sebelah barat Surakarta, dan 40 km di sebelah barat laut Yogyakarta.', -7.60793, 110.20384, 30000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Borobudur-Nothwest-view.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q42798', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 101),
  (8611, NULL, 4, 'Sangiran', 'Jawa Tengah', 'Jalan Barokah, Gondangrejo, Jawa Tengah', 'Sangiran adalah situs arkeologi di Jawa, Indonesia. Menurut laporan UNESCO (1995) "Sangiran diakui oleh para ilmuwan untuk menjadi salah satu situs yang paling penting di dunia untuk mempelajari fosil manusia, disejajarkan bersama situs Zhoukoudian (Cina), Willandra Lakes (Australia), Olduvai Gorge (Tanzania), dan Sterkfontein (Afrika Selatan), dan lebih baik dalam penemuan daripada yang lain."\nDaerah terdiri dari sekitar 56 km² (7 km x 8 km). Lokasi ini terletak di Jawa Tengah, sekitar 15 kilometer sebelah utara Surakarta di lembah Sungai Bengawan Solo.', -7.45, 110.85, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sangiran%2017-02.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q842328', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 41),
  (8612, NULL, 4, 'Goa Gajah', 'Gianyar', 'Jalan Raya Goa Gajah, Blahbatuh, Bali', 'Gua Gajah adalah gua buatan dari masa purbakala yang berfungsi sebagai tempat ibadah. Gua ini terletak di Desa Bedulu, Kecamatan Blahbatuh, Kabupaten Gianyar, Bali; berjarak kurang lebih 27 km dari Denpasar.', -8.523389, 115.286333, 50000, '08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Goa%20Gajah%20Front.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q2037360', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 27),
  (8613, NULL, 4, 'Situs Gunung Padang', 'Cianjur', 'Jalan Akses Gunung Padang, Cimenteng, Cianjur, Jawa Barat', 'Gunung Padang adalah situs arkeologi yang terletak di Karyamukti, Jawa Barat, Indonesia, 50 kilometer (31 mi) barat daya Cianjur. Terletak pada ketinggian 885 meter (2.904 ft) di atas permukaan laut, situs ini meliputi sebuah bukit—sebuah gunung berapi yang sudah tidak aktif—dalam serangkaian lima teras yang dibatasi oleh dinding penahan batu yang dapat diakses melalui 370 anak tangga andesit yang berurutan dengan ketinggian sekitar 95 meter (312 ft). Situs ini ditutupi oleh kolom-kolom batu heksagonal besar yang berasal dari gunung berapi.', -6.99385, 107.0560833, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Padang%20Site.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3120910', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 24),
  (8614, NULL, 4, 'Candi Trowulan', 'Mojokerto', 'Bejijong, Jawa Timur', 'Trowulan adalah situs arkeologi di Kecamatan Trowulan, Kabupaten Mojokerto, Jawa Timur, Indonesia. Situs ini mencakup area sekitar 100 kilometer persegi dan diyakini sebagai lokasi ibu kota Kerajaan Majapahit yang terkenal, yang dijelaskan oleh Mpu Prapanca dalam puisi Nagarakretagama abad ke-14 dan dalam sumber Tiongkok abad ke-15. Ketika menjadi ibu kota Kerajaan Majapahit, kota ini dikenal sebagai Majapahit atau Wilwatikta, yang menjadi asal nama kerajaan tersebut.', -7.55, 112.366667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bajang%20Ratu%20Gate%20Trowulan.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q962410', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 23),
  (8615, NULL, 4, 'Trinil', 'Ngawi', 'Jalan Raya Ngancar - Sonde, Ngancar, Ngawi', 'Trinil adalah situs paleoantropologi di Indonesia yang sedikit lebih kecil dari situs Sangiran. Tempat ini terletak di Desa Kawu, Kecamatan Kedunggalar, Ngawi kira-kira 13 km sebelum Kecamatan Ngawi dari arah kota Solo. Trinil merupakan kawasan di lembah Bengawan Solo yang menjadi hunian kehidupan purba, tepatnya zaman Pleistosen Tengah, sekitar satu juta tahun lalu.', -7.3743, 111.3578, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20most%20ancient%20skeletal%20remains%20of%20man%201.png?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q1318724', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 20),
  (8616, NULL, 4, 'Candi Kalasan', 'Sleman', 'Tirtomartani, Sleman, Daerah Istimewa Yogyakarta', 'Candi Kalasan atau Candi Kalibening (bahasa Jawa: ꦕꦟ꧀ꦝꦶꦏꦭꦱꦤ꧀, translit. Caṇḍi Kalasan) merupakan sebuah Bangunan Cagar Budaya yang dikategorikan sebagai candi umat Buddha. Candi ini terletak di Desa Tirtomartani, Kecamatan Kalasan, Kabupaten Sleman, Daerah Istimewa Yogyakarta, Indonesia.', -7.7673111, 110.4723361, 5000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalasan%20Temple%20from%20the%20north-east%2C%2023%20November%202013.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3517565', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 19),
  (8617, NULL, 4, 'Candi Sewu', 'Klaten', 'Bugisan, Klaten, Jawa Tengah', 'Candi Sewu (bahasa Jawa: ꦕꦤ꧀ꦝꦶꦱꦺꦮꦸ, translit. Candhi Sèwu) adalah candi Buddha yang dibangun pada abad ke-8 Masehi yang berjarak sekitar delapan ratus meter di sebelah utara Candi Prambanan. Candi Sewu merupakan kompleks candi Buddha terbesar kedua setelah Candi Borobudur di Jawa Tengah.', -7.74393, 110.49284, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Sewu%20viewed%20from%20the%20south%2C%2023%20November%202013.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q2936254', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 17),
  (8618, NULL, 4, 'Candi Penataran', 'Blitar', 'Jalan Insinyur Soekarno, Kedawung, Blitar, Jawa Timur', 'Candi Penataran atau nama aslinya adalah Candi Palah adalah sebuah gugusan candi bersifat keagamaan Hindu Siwaitis (pemuja keluarga Sri Siwa Mahadewa), yang terletak di Desa Penataran, Kecamatan Nglegok, Kabupaten Blitar, Jawa Timur. Candi termegah dan terluas di Jawa Timur ini terletak di lereng barat daya Gunung Kelud, di sebelah utara Blitar, pada ketinggian 450 meter di atas permukaan laut. Dari prasasti yang tersimpan di bagian candi diperkirakan candi ini dibangun pada masa Raja Srengga dari Kerajaan Kadiri sekitar tahun 1200 Masehi dan berlanjut digunakan sampai masa pemerintahan Wikramawardhana, Raja Kerajaan Majapahit sekitar tahun 1415.', -8.0161111, 112.2091667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Panataran%2034200113.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q2491478', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 16),
  (8620, NULL, 4, 'Candi Muara Takus', 'Riau', 'Jalan Simpang Muara Takus - Bandur Picak (Batas Kab. Rokan Hulu), Muara Takus, Kampar, Riau', 'Candi Muara Takus adalah sebuah situs candi Buddha yang terletak di desa Muara Takus, Kecamatan XIII Koto, Kabupaten Kampar, Riau, Indonesia. Situs ini berjarak kurang lebih 135 kilometer dari Kota Pekanbaru.\nSitus Candi Muara Takus dikelilingi oleh tembok berukuran 74 x 74 meter, yang terbuat dari batu putih dengan tinggi tembok ± 80 cm, di luar arealnya terdapat pula tembok tanah berukuran 1,5 x 1,5 kilometer, mengelilingi kompleks ini sampal ke pinggir Sungai Kampar Kanan.', 0.336016, 100.641951, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Muara%20Takus%20%281%29.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3101233', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 14),
  (8621, NULL, 4, 'Candi Gunung Kawi', 'Tampaksiring', 'Tampaksiring, Bali', 'Candi Gunung Kawi atau Candi Tebing Gunung Kawi adalah situs purbakala yang dilindungi di Bali. Terletak di Sungai Pakerisan, Dusun Penaka, Desa Tampaksiring, Kecamatan Tampaksiring, Kabupaten Gianyar, Provinsi Bali, Indonesia. Candi ini sangat unik karena biasanya candi berupa batuan utuh yang terbuat dari bata merah atau batu gunung, namun candi ini tidak seperti itu melainkan pahatan di dinding tebing batu padas ditepi sungai.', -8.423361, 115.312333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%20-%20Bali%20%2826781246023%29.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q2605109', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 14),
  (8622, NULL, 4, 'Candi Ratu Boko', 'Yogyakarta', 'Bokoharjo, Sleman, Daerah Istimewa Yogyakarta', 'Keraton Ratu Boko (bahasa Jawa: ꦏꦝꦠꦺꦴꦤ꧀ꦫꦠꦸꦧꦏ, translit. Kadhaton Ratu Baka) adalah situs purbakala yang merupakan kompleks sejumlah sisa bangunan yang berada kira-kira 3 km di sebelah selatan dari kompleks Candi Prambanan, 18 km sebelah timur Kota Yogyakarta atau 50 km barat daya Kota Surakarta, Jawa Tengah, lebih tepatnya di kalurahan Bokoharjo, kapanéwon Prambanan, kabupaten Sleman, Daerah Istimewa Yogyakarta. Situs Ratu Boko terletak di sebuah bukit pada ketinggian 196 meter dari permukaan laut.', -7.77, 110.4888889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Ratu%20Boko%204.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3111557', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 13),
  (8623, NULL, 4, 'Kompleks Candi Muaro Jambi', 'Muaro Jambi', 'Jalan Batanghari II - Zona Lima, Danau Lamo, Muaro Jambi, Jambi', 'Candi Muaro Jambi adalah sebuah kompleks percandian agama Hindu-Buddha terluas di Asia Tenggara, dengan luas 3981 hektar. yang kemungkinan besar merupakan peninggalan Kerajaan Sriwijaya dan Kerajaan Melayu. Kompleks percandian ini terletak di Kecamatan Maro Sebo, Kabupaten Muaro Jambi, Jambi, Indonesia, tepatnya di tepi Batang Hari, sekitar 26 kilometer arah timur Kota Jambi.', -1.4769444, 103.6341667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Gumpung%20Muarojambi.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q2725535', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 12),
  (8624, NULL, 4, 'Candi Badut', 'Malang', 'Jalan Esberg VE 5, Karangbesuki, Kota Malang, Jawa Timur', 'Candi Badut adalah sebuah candi yang terletak di kawasan Tidar, di bagian barat Kabupaten Malang. Secara administratif candi badut terletak di Desa Karangwidoro, Kecamatan Dau, Kabupaten Malang, Jawa Timur. \nLokasi candi ini berada di dekat Universitas Ma Chung, sekitar 15 menit berjalan kaki dari sana ke arah Timur.', -7.95776, 112.59857, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Badut.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3517536', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 10),
  (8625, NULL, 4, 'Percandian Batujaya', 'Indonesia', 'Karawang, Jawa Barat', 'Kompleks Percandian Batujaya adalah sebuah kompleks percandian Buddha kuno yang terletak di Kecamatan Batujaya dan Kecamatan Pakisjaya, Kabupaten Karawang, Provinsi Jawa Barat. Situs ini disebut percandian karena terdiri dari sekumpulan candi yang tersebar di beberapa titik. Candi-candi tersebut merupakan candi-candi tertua di Nusantara.', -6.05563, 107.15351, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Blandongan.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q19745571', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 8),
  (8627, NULL, 4, 'Candi Arjuna', 'Banjarnegara', 'Jalan Dieng, Dieng Kulon, Banjarnegara, Jawa Tengah', 'Candi Arjuna  (bahasa Jawa: ꦕꦤ꧀ꦢꦶꦄꦂꦗꦸꦤ, translit. Candi Arjuna) adalah sebuah bangunan candi Hindu yang terletak di Dataran Tinggi Dieng, Kabupaten Banjarnegara, Jawa Tengah, Indonesia.\n\nCandi Arjuna merupakan salah satu bangunan candi di Kompleks Percandian Arjuna, Dieng.', -7.2050892, 109.9068403, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Arjuna%20front%20view.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q11157349', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 7),
  (8628, NULL, 4, 'Candi Bojongmenje', 'Jawa Barat', 'Jalan Raya Cicalengka, Cihanjuang, Sumedang, Jawa Barat', 'Candi Bojongmenje (bahasa Sunda: ᮎᮔ᮪ᮓᮤ ᮘᮧᮏᮧᮀᮦᮙᮔ᮪ᮦᮏ, translit. Candi Bojongménjé) atau yang lebih dikenal dengan Situs Rancaekek, merupakan komplek purbakala yang diduga merupakan peninggalan masa pra-Islam di Jawa Barat yang terletak di Kampung Bojongmenje, Desa Cangkuang, Kecamatan Rancaekek, Bandung, Jawa Barat. Situs ini terletak di dekat kawasan industri sehingga keberadaannya terancam.', -6.96608, 107.802, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bojongmenje%201.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3517543', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 6),
  (8629, NULL, 4, 'Prasasti Plumpungan', 'Salatiga', 'Jalan Tol Semarang–Solo, Kauman Kidul, Salatiga, Jawa Tengah', 'Prasasti Plumpungan atau Prasasti Hampran adalah objek kepurbakalaan berupa batu bertulis yang berada di Dukuh Plumpungan, Kelurahan Kauman Kidul, Kecamatan Sidorejo, Kota Salatiga, Provinsi Jawa Tengah. Prasasti itu tertulis dalam batu besar berjenis andesit berukuran panjang 170 cm dan lebar 160 cm dengan garis lingkar 5 meter. Prasasti berangka tahun 750 Masehi (672 Syaka) ini dipercaya sebagai asal mula Kota Salatiga.', -7.3069444, 110.5127778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Salatiga%20%2812%29.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q4251759', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 5),
  (8630, NULL, 4, 'Candi Bima', 'Banjarnegara', 'Jalan Rake Sanjaya, Dieng, Wonosobo, Jawa Tengah', 'Candi Bima adalah salah satu peninggalan purbakala di kawasan Dataran Tinggi Dieng. Candi Bima memiliki bangunan yang tersusun dari pahatan batu kokoh.', -7.213889, 109.910556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Bima%20Dieng%20Plateau.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q11124187', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 5),
  (8631, NULL, 4, 'Leang Pettae', 'Taman Nasional Bantimurung Bulusaraung', 'Jalan Poros Leang Leang, RW 02, Maros, Sulawesi Selatan', 'Leang Pettae (Lontara Bugis: ᨒᨙᨕ ᨄᨛᨈᨕᨙ , transliterasi: Léang Pêttaé ) atau Gua Pettae (Lontara Indonesia: ᨁᨘᨕ ᨄᨛᨈᨕᨙ , transliterasi: Gua Pettae ) atau kadang ditulis Pattae adalah situs arkeologi dan berstatus cagar budaya di Kawasan Karst Maros-Pangkep, Taman Nasional Bantimurung-Bulusaraung, tepatnya di wilayah Kabupaten Maros. Di Leang Pettae inilah pertama kali ditemukan lukisan pada dinding gua di wilayah Kabupaten Maros. Sejak tahun 1980-an situs gua prasejarah ini telah dikembangkan menjadi tempat wisata Taman Prasejarah Leang-Leang dan menjadi salah satu tempat wisata yang menarik di Sulawesi Selatan.', -5.003056, 119.694444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hands%20in%20Pettakere%20Cave.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q3117263', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 5),
  (8632, NULL, 4, 'Candi Tanjung Medan', 'Pasaman', 'Patok Delapanbelas, Pasaman, Sumatera Barat', 'Candi Tanjung Medan adalah sebuah situs purbakala yang terletak di Dusun Tanjung Medan, Nagari Petok Kecamatan Panti, Kabupaten Pasaman, Sumatera Barat. Situs ini sudah lama diketahui keberadaannya oleh masyarakat sekitar, tetapi baru sekitar tahun 1990-an mulai pemugaran candi oleh pemerintah.', 0.2915268, 100.1013948, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Tanjung%20Medan%2012.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q12478284', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 4),
  (8633, NULL, 4, 'Keraton Plered', 'Bantul', 'Pleret, Daerah Istimewa Yogyakarta', 'Keraton Plered (bahasa Jawa: ꦏꦫꦠꦺꦴꦤ꧀ꦥ꧀ꦭꦺꦫꦺꦢ꧀, translit. karaton plèrèd) adalah bekas keraton dan ibu kota Kesunanan Mataram ketiga setelah Keraton Kotagede dan Keraton Karta. Dibangun pada 1644 oleh Sultan Agung sebagai ibu kota selanjutnya, pemindahannya baru terwujudkan pada 1646 oleh Amangkurat I. Status ibu kotanya berakhir pada 1677 ketika Plered diserbu oleh pasukan pemberontak pengikut Trunajaya, tetapi tetap lanjut digunakan sebagai keraton hingga 1680.', -7.863471, 110.411285, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20Kraton%27s%20van%20Pasar%20Gede%2C%20Kerta%20en%20Plered.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q7204619', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 3),
  (8634, NULL, 4, 'Situs Cibuaya', 'Indonesia', 'Pejaten, Jawa Barat', 'Situs Cibuaya berada di Dusun Pejaten, Desa Cibuaya, Kecamatan Cibuaya, Kabupaten Karawang, Jawa Barat yang berjarak kurang lebih 6 km dari garis pantai. Situs Cibuaya memiliki dua struktur bangunan, satu yang relatif masih terlihat dipermukaan tanah , terbuat dari bata dinamakan Lemah Duwur Lanang, berupa batur dua teras dan di puncaknya bertegah linggah semu.', -6.05028, 107.347, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vishnu%20Cibuaya%20Tarumanagara.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q12515569', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 3),
  (8635, NULL, 4, 'Kompleks Prasasti Adityawarman', 'Tanah Datar', 'Jalan Sutan Alam Bagagarsyah, Pagaruyung, Tanah Datar, Sumatera Barat', 'Kompleks Prasasti Adityawarman, juga dikenal sebagai Situs Prasasti Pagaruyung, adalah sebuah kompleks berisi kumpulan prasasti yang berasal dari sekitar masa pemerintahan Raja Adityawarman, yaitu pada periode Kerajaan Melayu Kuna pada abad ke-13 hingga ke-14 Masehi. Situs ini merupakan cagar budaya yang dikelola oleh Balai Pelestarian Cagar Budaya Provinsi Sumatera Barat, Riau, dan Riau Kepulauan berdasarkan Peraturan Menteri Kebudayaan dan Pariwisata Nomor PM.05/PW.007/MKP/2010. \nDi Kompleks Prasasti Adityawarman ini terdapat delapan prasasti utama, yaitu Prasasti Pagaruyung I, Prasasti Pagaruyung II, Prasasti Pagaruyung III, Prasasti Pagaruyung IV, Prasasti Pagaruyung V, Prasasti Pagaruyung VI, Prasasti Pagaruyung VII, dan Prasasti Pagaruyung VIII. Ada satu lagi yang juga disebut "Prasasti Pagaruyung", yaitu Prasasti Pagaruyung IX, namun lokasinya terpisah yaitu di Ruang Koleksi Balai Pelestarian Peninggalan Purbakala Batusangkar.', -0.4594069, 100.607786, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tungkup%20Prasasti%20Pagaruyung.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106281910', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 3),
  (8636, NULL, 4, 'Situs Bekas Kerajaan Daulat Parit Batu', 'Pasaman', 'Simpang Empat, Sumatera Barat', 'Benteng Parit Batu adalah salah satu situs Kerajaan Daulat Parit Batu yang terletak di Kabupaten Pasaman Barat. Lokasinya masuk dalam wilayah Jorong Bandarejo, Kenagarian Lingkuang Aua, Kecamatan Aur Limo. Benteng Parit Batu dibangun atas perintah Tuanku Daulat.', 0.0915384, 99.8307131, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situs%20Bekas%20Kerajaan%20Daulat%20Parit%20Batu%2003.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283010', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 3),
  (8638, NULL, 4, 'situs Beteng Boto Mulyo', 'Jember', 'Sidomekar, Jember, Jawa Timur', 'situs Beteng Boto Mulyo: Situs peninggalan sejarah Majapahit, Jember.', -8.2079448, 113.4613615, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beteng%20Boto%20Mulyo%205.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q139678929', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8639, NULL, 4, 'situs Duplang', 'Jember', 'Jalan Argopuro, Kamal, Jember, Jawa Timur', 'situs Duplang: Cagar budaya Megalitikum Jember, Jember.', -8.0884291, 113.7414561, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dolmen%20situs%20duplang%20Jember.png?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q139678958', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8640, NULL, 4, 'Situs arkeologi Padang Lawas', 'Indonesia', NULL, 'Situs arkeologi Padang Lawas merupakan kawasan kepurbakalaan yang terletak di Kabupaten Padang Lawas dan Kabupaten Padang Lawas Utara, Sumatera Utara, Indonesia. Mencakup daerah sekitar 1.500 km², situs arkeologi ini meliputi Kecamatan Barumun, Kecamatan Barumun Tengah, Kecamatan Sosopan, Kecamatan Padang Bolak, dan Kecamatan Padang Bolak Julu.\nDi sini ditemukan kompleks peninggalan candi Hindu-Buddha.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Bronzen%20boeddhabeeld%20TMnr%202960-140.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q7123230', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8641, NULL, 4, 'Situs Megalitik Batu Gajah', 'Tanggamus', 'Negeri Dolok, Simalungun, Sumatera Utara', 'Situs megalitik Batu Gajah adalah sebuah situs megalitik di kecamatan Pulau Panggung, Tanggamus, Provinsi Lampung. Namanya berasal dari salah satu batu yang terdapat di situs tersebut, dan berbentuk gajah.', 2.79328, 99.03378, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Megalitisch%20beeld%20in%20Batoegadjah%20TMnr%2060039779.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q12515580', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8642, NULL, 4, 'Umbul Pengging', 'Boyolali', 'Jentekan, Boyolali, Jawa Tengah', 'Umbul Pengging adalah sebuah kompleks pemandian peninggalan Kasunanan Surakarta terletak di Desa Dukuh, Kecamatan Banyudono, Kabupaten Boyolali, Provinsi Jawa Tengah, Indonesia. Pemandian ini dibangun oleh Raja Kasunanan Surakarta yaitu Sri Paduka Pakubuwono X.\nMenurut cerita masyarakat setempat, pada awalnya pemandian ini merupakan tempat bersantai raja dan keluarganya. Hal ini tampak dari bangunan tempat peristirahatan yang berada di dekat kolam pemandian ini.', -7.55328, 110.67555, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Umbul%20Pengging.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q20427710', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8643, NULL, 4, 'Yeh Pulu', 'Bedulu', 'Jalan Raya Semebaung, Blahbatuh, Bali', 'Yeh Pulu adalah situs purbakala yang berada di Desa Bedulu, Kecamatan Blahbatuh, Gianyar, Provinsi Bali. Situs ini berlokasi 500 meter dari arah tenggara Gua Gajah.\nYeh Pulu pertama kali ditemukan pada 1925 oleh Punggawa Ubud.', -8.531667, 115.293056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yeh%20Pulu.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q56391504', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8644, NULL, 4, 'Situs Gunung Susuru', 'Indonesia', 'Kertabumi, Ciamis, Jawa Barat', 'Situs Gunung Susuru: Situs arkeologi di Indonesia.', -7.3421031, 108.463669, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Pund%C3%A9n%20Situs%20Gunung%20Susuru.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q65344292', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8645, NULL, 4, 'Situs Pedati Gede', 'Cirebon', 'Pekalipan, Cirebon, Jawa Barat', 'Situs Pedati Gede Cirebon merupakan situs bersejarah di Kota Cirebon, tepatnya di Pekalangan Selatan, Cirebon serta sudah ada dari tahun 1371. Pedati ini merupakan artefak kendaraan yang masih terawat hingga saat ini. Berdasarkan penlitian kendaraan dibuat pada masa kepemimpinan Pangeran Walangsungsang 1445 - 1479, kendaraan ini biasanya digunakan sebagai alat transportasi untuk mengangkat material yang berasal dari alam sekitar sebagai bahan baku yang digerakkan oleh tenaga manusia ataupun hewan.', -6.7179708, 108.5614811, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situs%20Pedati%20Gede%20Pekalangan%2021.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283084', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8646, NULL, 4, 'Prasasti Ganggo Hilia', 'Bonjol', 'Nagari Ganggo Hilia, Pasaman, Sumatera Barat', 'Prasasti Ganggo Hilia adalah sebuah prasasti yang ditemukan di Jorong Pasar, Nagari Ganggo Hilia, Bonjol, Pasaman, Sumatera Barat. Prasasti ini ditemukan oleh tim survei Balai Arkeologi Medan pada September tahun 2004. Prasasti ini ditulis dalam bahasa Sansekerta dan aksara Jawa Kuno, dan berlokasi di dataran tinggi dengan ketinggian 232 mdpl, tidak jauh dari sungai Batang Bubus.', -0.015942, 100.2247695, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prasasti%20Ganggo%20Hilia%2001.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283095', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8647, NULL, 4, 'Situs Megalitik Pokekea', 'Indonesia', 'Sulawesi Tengah', 'Situs Megalitik Pokekea adalah situs arkeologi di Indonesia.', -1.6915306, 120.2132972, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/DSC04013-01.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q30627435', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 2),
  (8648, NULL, 4, 'Bulu Sipong', 'Sulawesi Selatan', 'Jalan Moncongbori Katubung, Mattoangin, Maros, Sulawesi Selatan', 'Bulu Sipong (Lontara: ᨅᨘᨒᨘ ᨔᨗᨄᨚ , transliterasi: Bulu Sipong ) adalah situs arkeologi dan berstatus cagar budaya di wilayah Kabupaten Maros, Sulawesi Selatan, Indonesia. Di situs ini ada tiga gua prasejarah terkenal, yaitu Leang Bulu Sipong I, Leang Bulu Sipong II, dan Leang Bulu Sipong III. Gua-gua ini terletak pada titik koordinat 04°58\'33" LS dan 119°36\'57" BT. Secara wilayah administratif, gua-gua ini terletak di wilayah Dusun Tangaparang, Desa Botolempangan, Kecamatan Bontoa, Kabupaten Maros. Di dalam Leang Bulu Sipong I terdapat lukisan telapak tangan dan perahu yang diatasnya terdapat lukisan manusia dengan berbagai aktivitas seperti mendayung dan memegang tombak dan didalam Leang Bulu Sipong II terdapat lukisan dinding gua berbentuk ikan dan telapak tangan, alat batu, dan cangkang mollusca.', -4.9758333, 119.6158333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lukisan%20tertua%20di%20dunia%20usia%20lebih%20dari%2040.000%20tahun.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q125585033', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8649, NULL, 4, 'benteng Pendem Cakru', 'Jember', 'Paseban, Jember, Jawa Timur', 'benteng Pendem Cakru: Cagar budaya berupa benteng pertahanan peninggalan Jepang, Jember.', -8.297474, 113.3324648, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situs%20benteng%20pendem%20cakru%201.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q139678979', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8650, NULL, 4, 'Peningki Lama', 'Kalimantan Utara', 'Jalan Padat Karya, Mamburungan Timur, Tarakan, Kalimantan Utara', 'Peningki Lama merupakan kawasan cagar budaya bersejarah peninggalan kolonial Belanda pada Perang Dunia II. Peningki Lama terletak di Kelurahan Mamburungan, Kecamatan Tarakan Timur, Kota Tarakan, Kalimantan Utara, Indonesia. Luas kawasan situs peningki Lama ini sekitar 6,1 ha. Situs ini dahulu sebagai basis utama pertahanan Belanda yang digunakan untuk mengawasi jalur masuk Tarakan (laut dan darat)  dari arah Selatan.', 3.2661848, 117.6170379, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Situs%20Peningki%20Lama.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q141833766', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8652, NULL, 4, 'Megalit Simawang', 'Tanah Datar', NULL, 'Situs Megalit Simawang adalah bangunan zaman megalit yang berada di Nagari Simawang, Kecamatan Rambatan, Kabupaten Tanah Datar, Sumatera Barat. Situs ini adalah kompleks pemakaman kuno yang diperkirakan muncul pada masa Islam sekitar abad ke XVIII. Wujud fisiknya berupa susunan batu-batu besar berjenis andesit dan berdiri di puncak bukit. Bagian kepala menhir lebih besar dari bagian kaki.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Megalit%20Simawang.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q65211267', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8653, NULL, 4, 'Leang Timpuseng', 'Maros', NULL, 'Leang Timpuseng atau Gua Timpuseng merupakan salah satu dari puluhan gua yang terdapat di perbukitan karst Maros. Terletak sekitar 400 m dari jalan poros Bantimurung-Leangleang, gua atau Leang (sebutan lokal) ini cukup mudah dijangkau dengan berjalan kaki melalui lahan persawahan. Lokasinya juga mudah ditemukan karena tampak jelas dari jalan poros.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lukisan%20Tangan%20di%20Leang-Leang%20Maros.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q97308228', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8654, NULL, 4, 'Situs Arca Padang Nunang', 'Rao Selatan', 'Jalan Rao - Rokan (Batas Riau), Nagari Lubuak Layang, Pasaman, Sumatera Barat', 'Situs Arca Padang Nunang: Situs arkeologi di Rao Selatan, Sumatra Barat, Indonesia, Rao Selatan.', 0.5528817, 100.0530455, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arca%20Padang%20Nunang%2012.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283004', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8655, NULL, 4, 'Situs Megalitik Purwakalih', 'Bogor', 'Jalan Lawang Gintung, Bogor Selatan, Bogor, Jawa Barat', 'Situs Megalitik Purwakalih: Situs arkeologi di Bogor, Jawa Barat, Indonesia, Bogor.', -6.62476, 106.80922, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Purwakalih%20site%203.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283081', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8656, NULL, 4, 'Situs Bleberan', 'Indonesia', NULL, 'Situs Bleberan merupakan situs tempat mengumpulkan (penampungan) objek-objek kepurbakalaan megalitik yang ditemukan di kawasan Playen, Gunungkidul, dan sekitarnya. Situs ini terletak di Dusun Bleberan, Desa Bleberan, Playen, Gunungkidul, tidak jauh dari jalan menuju objek wisata Air Terjun Sri Gethuk, menempati lahan seluas 1.146 meter persegi.\nDi situs penampungan ini terdapat objek cagar budaya berupa berbagai megalit, seperti menhir (ada pula yang berupa menhir arca) yang diletakkan berbaring, serta bagian-bagian kubur batu, tutup sarkofagus, serta batu kenong.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bleberan%20Site.JPG?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q17999585', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 1),
  (8657, NULL, 4, 'Situs dan Bangunan Candi Banyunibo', 'Sleman', 'Bokoharjo, Sleman, Daerah Istimewa Yogyakarta', 'Situs dan Bangunan Candi Banyunibo: Situs arkeologi di Sleman, D.I Yogyakarta, Indonesia, Sleman.', -7.77797, 110.49406, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banyunibo%20Temple%2C%202014-05-31%2001.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106309127', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 0);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (8658, NULL, 4, 'Situs Bukit Kerang Kawal Darat', 'Kepulauan Riau', NULL, 'Situs Bukit Kerang Kawal Darat: Situs arkeologi di Gunung Kijang, Kepulauan Riau, Indonesia, Kepulauan Riau.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Kerang%20Kawal%20Darat%20%28Tampak%20depan%29.jpg?width=800', '2026-11-04 09:39:57', '2026-11-24 23:32:50', 'wd:Q106283011', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Situs arkeologi', 0),
  (8659, NULL, 7, 'Masjid Istiqlal', 'Pasar Baru', 'Jalan Kyai Haji Hasyim Asyari, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Masjid Istiqlal (bahasa Arab: مسجد الاستقلال, "Masjid Kemerdekaan") adalah sebuah masjid nasional yang berada di Jakarta Pusat, Indonesia. Masjid ini menjadi masjid terbesar di Asia Tenggara dan masjid terbesar kedelapan di dunia dalam hal kapasitas jemaah. Dibangun untuk memperingati kemerdekaan Indonesia, masjid nasional Indonesia ini diberi nama "Istiqlal", kata bahasa Arab untuk "kemerdekaan".', -6.1697222, 106.8308333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20to%20the%20northeast%20from%20Monas.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q475379', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 42),
  (8660, NULL, 7, 'Masjid Raya Baiturrahman', 'Banda Aceh', 'Jalan Mohammad Jam, Baiturrahman, Banda Aceh, Aceh', 'Masjid Raya Baiturrahman Banda Aceh (bahasa Arab: مسجد بيت الرحمن في بندر آتشيه; bahasa Aceh: Meuseujid Raya Baiturrahman) atau yang lebih dikenal dengan Masjid Raya Baiturrahman (مسجد الجامع بيت الرحمن) atau Masjid Kesultanan Aceh (مسجد سلطنة آتشيه) adalah sebuah masjid bersejarah yang berada di Kota Banda Aceh, Provinsi Aceh, Indonesia. Masjid ini dibangun pada tahun 1879 dan merupakan simbol agama, budaya, semangat, kekuatan, perjuangan dan nasionalisme rakyat Aceh. Kemudian masjid ini adalah landmark Kota Banda Aceh sejak era Kesultanan Aceh dan Aceh saat ini.', 5.5536111, 95.3171944, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meuseujid%20Raya%20Bayturrahman.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q1548318', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 25),
  (8661, NULL, 7, 'Masjid Agung Demak', 'Demak', 'Jalan Kyai Singkil, Sorogenen, Demak, Jawa Tengah', 'Masjid Agung Demak (abjad Pegon: مَسْجِد اَڮَوڠ دَمَق) adalah salah satu kompleks masjid tertua yang berada di Kabupaten Demak, Provinsi Jawa Tengah, Indonesia. Masjid ini diyakini dibangun oleh Wali Sanga–penyebar agama Islam di Pulau Jawa–dengan sosok yang paling menonjol Sunan Kalijaga, pada masa penguasa Kesultanan Demak pertama, Raden Patah pada abad ke-15.\nDi dalam lokasi kompleks masjid ini, terdapat beberapa makam raja-raja Kesultanan Demak termasuk di antaranya adalah Raden Patah yang merupakan raja pertama Kesultanan Demak dan para abdinya.', -6.89473, 110.63739, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20demak.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q2393693', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 20),
  (8662, NULL, 7, 'Masjid Agung Jawa Tengah', 'Semarang', 'Jalan Jolotundo Gang V, Gayamsari, Kota Semarang, Jawa Tengah', 'Masjid Agung Jawa Tengah (bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦄꦒꦼꦁꦗꦮꦶꦩꦢꦾ, translit. Masjid Agêng Jawi Madya) adalah masjid yang terletak di Semarang, Jawa Tengah, Indonesia.\nMasjid ini mulai dibangun sejak tahun 2001 hingga selesai secara keseluruhan pada tahun 2006.', -6.9838889, 110.4458333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Jawa%20Tengah%20Indonesia.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q7476510', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 16),
  (8663, NULL, 7, 'Masjid Menara Kudus', 'Kota Kudus', 'Kauman, Kudus, Jawa Tengah', 'Masjid Menara Kudus (nama resmi: Masjid Al-Aqsa Manarat Qudus; ID masjid: 01.5.14.19.02.000001 bahasa Jawa: Hanacaraka: ꦩꦱ꧀ꦗꦶꦢ꧀ꦩꦼꦤꦫꦏꦸꦢꦸꦱ꧀ Pegon dan Arab standar: مسجد منارة قدوس) adalah masjid kuno yang dibangun oleh Sunan Kudus sejak tahun 1549 Masehi (956 Hijriah). Lokasi saat ini berada di Desa Kauman, Kecamatan Kota, Kabupaten Kudus, Jawa Tengah. Ada keunikan dari masjid ini karena memiliki menara yang serupa bangunan candi serta pola arsitektur yang memadukan konsep budaya Islam dengan budaya Hindu-Buddhis sehingga menunjukkan terjadinya proses akulturasi dalam pengislaman Jawa.', -6.80389, 110.832, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Menara%20Kudus%20Tampak%20Depan.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4022388', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 15),
  (8664, NULL, 7, 'Masjid Raya Sumatera Barat', 'Alai Parak Kopi', 'Jalan Khatib Sulaiman No.1, Rimbo Kaluang, Padang, Sumatera Barat', 'Masjid Raya Sumatera Barat atau Masjid Raya Syekh Ahmad Khatib Al Minangkabawi terletak di Jalan Chatib Sulaiman, Kota Padang, Sumatera Barat. Pembangunannya diawali peletakan batu pertama pada 21 Desember 2007 dan dinyatakan selesai pada 4 Januari 2019 dengan total biaya sekitar Rp330 miliar. Masjid ini didesain oleh Rizal Muslimin lewat proses sayembara yang diadakan pemerintah daerah pada 2006.', -0.924234, 100.362492, NULL, 'Buka 24 jam', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pendar%20cahaya%20ruang%20salat%20Masjid%20Raya%20Sumbar.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497335', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 14),
  (8665, NULL, 7, 'Masjid Bingkudu', 'Canduang Koto Laweh', 'Koto Tinggi, Agam, Sumatera Barat', 'Masjid Bingkudu (kadang dieja atau ditulis Masjid Bengkudu dan disebut juga dengan Masjid Jamik Bingkudu) adalah salah satu masjid tertua di Indonesia yang didirikan oleh kaum Padri di tengah kecamuk perang Padri di Sumatera Barat pada tahun 1823. Masjid dengan arsitektur khas Minangkabau ini terletak di Jorong Bingkudu, Nagari Canduang Koto Laweh, Kecamatan Canduang, Kabupaten Agam, Sumatera Barat. Saat mulai didirikan, bangunan masjid ini terbuat dari bahan kayu, mulai dari lantai, tiang, hingga dinding masjid.', -0.31159, 100.47388, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Bingkudu%202020%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q6684473', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 13),
  (8666, NULL, 7, 'Masjid Gedhe Kauman', 'Yogyakarta', 'Gang Monumen Syuhada, Gondomanan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Masjid Gedhe Kauman (bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦒꦼꦝꦺꦏꦲꦸꦩ꧀ꦩꦤ꧀), dikenal sebagai Masjid Agung Daerah Istimewa Yogyakarta, adalah masjid utama Kesultanan Yogyakarta dan Daerah Istimewa Yogyakarta yang terletak di sebelah barat kompleks Alun-alun Utara.', -7.8039461, 110.3625553, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jogja%20-%20Mesjid%20Gedhe%20Kauman%20Karaton%20Ngayogyakarta%20Hadiningrat%20%282025%29%20-%20img%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13095002', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 13),
  (8667, NULL, 7, 'Masjid Sultan Suriansyah', 'Banjarmasin', 'Jalan Kuin Utara, Banjarmasin Utara, Banjarmasin, Kalimantan Selatan', 'Masjid Sultan Suriansyah atau Masjid Kuin adalah sebuah masjid bersejarah di Kota Banjarmasin yang merupakan masjid tertua di Kalimantan Selatan. Masjid ini dibangun pada masa pemerintahan Sultan Suriansyah (1526-1550), Raja Banjar pertama yang memeluk agama Islam. Masjid Kuin merupakan salah satu dari tiga masjid tertua yang ada di kota Banjarmasin pada masa Mufti Jamaluddin (Mufti Banjarmasin), masjid yang lainnya adalah Masjid Besar (cikal bakal Masjid Jami Banjarmasin) dan Masjid Basirih.', -3.2943, 114.576, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Samping%20Masjid%20Suriansyah.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3393529', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8668, NULL, 7, 'Masjid Agung Nurul Iman', 'Belakang Tangsi', 'Jalan Tuanku Imam Bonjol, Belakangpondok, Padang, Sumatera Barat', 'Masjid Agung Nurul Iman, pernah dijuluki sebagai Masjid Presiden, terletak di pertigaan Jalan Imam Bonjol dan Jalan Muhammad Husni Thamrin, Kota Padang, Sumatera Barat. Masjid ini merupakan salah satu masjid terbesar di Kota Padang.\nMasjid Nurul Iman dibangun pada 1958 oleh negara sebagai bentuk permintaan maaf atas operasi penumpasan Pemerintahan Revolusioner Republik Indonesia (PRRI).', -0.954788, 100.36231, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Nurul%20Iman%202020.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4206428', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8669, NULL, 7, 'Masjid Rao-Rao', 'Rao Rao', 'Jalan Raya Batusangkar, Sungai Tarab, Tanah Datar, Sumatera Barat', 'Masjid Rao-Rao adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Rao-Rao, Kecamatan Sungai Tarab, Kabupaten Tanah Datar, Sumatera Barat. Masjid berarsitektur perpaduan Minangkabau dan Persia ini mulai dibangun pada tahun 1908 dengan atap berbahan ijuk sebelum akhirnya diganti menjadi seng.\nSejak berdirinya, masjid ini sempat mengalami kerusakan yang cukup berarti akibat gempa, seperti pada tahun 1926 dan terakhir 2009.', -0.37369, 100.55508, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Rao%20Rao%2C%20Tanah%20Datar%2C%20Sumatra%20Barat.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q6684240', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8670, NULL, 7, 'Masjid Dian Al-Mahri', 'Depok', 'Jalan Letnan Kolonel Haji Ali Bardha, Limo, Depok, Jawa Barat', 'Masjid Dian Al-Mahri (bahasa Arab: مسجد ديان المهري) atau yang lebih dikenal dengan Masjid Kubah Emas (bahasa Arab: مسجد القبة الذهبية) adalah sebuah kompleks masjid terbesar yang berlokasi di Jalan Meruyung Raya, Kelurahan Meruyung, Kecamatan Limo, Kota Depok, Provinsi Jawa Barat, Indonesia. Selain menjadi tempat ibadah umat Muslim sehari-hari, kompleks masjid ini juga menjadi kawasan wisata keluarga dan diminati banyak orang karena kubahnya yang terbuat dari emas. Karena luasnya wilayah dan aksesibilitas untuk umum, tempat ini sering menjadi tujuan liburan keluarga atau tempat beristirahat.', -6.384098, 106.772003, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menara%20Masjid%20Dian%20Al%20Mahri.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497288', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8671, NULL, 7, 'Masjid Raya Medan', 'Medan', 'Jalan Sipiso Piso, Medan Kota, Kota Medan, Sumatera Utara', 'Masjid Raya Al-Mashun (bahasa Arab: مسجد جامع المشون) atau yang lebih dikenal Masjid Raya Medan (abjad Jawi: مسجد رايا ميدان) (bahasa Arab: مسجد الجامع ميدان) adalah sebuah masjid yang berada di Kota Medan, Provinsi Sumatera Utara, Indonesia. Masjid ini dibangun pada tahun 1906 dan selesai pada tahun 1909. Pada awal pendiriannya, masjid ini merupakan bagian dari kompleks Istana Maimun.', 3.575111, 98.687321, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Great%20mosque%20in%20Medan.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497331', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8672, NULL, 7, 'Masjid Tuo Kayu Jao', 'Batang Barus', 'Solok, Sumatera Barat', 'Masjid Nurul Islam Koto Kayu Jao adalah salah satu masjid tertua di Indonesia yang terletak di Jorong Kayu Jao, Nagari Batang Barus, Kecamatan Gunung Talang, Kabupaten Solok, Sumatera Barat. Masjid ini diperkirakan merupakan peninggalan abad ke-17 dan menjadi masjid tertua di Kabupaten Solok.\nMasjid Tuo Kayu Jao juga merupakan salah satu cagar budaya di Sumatera Barat yang diawasi oleh Balai Pelestarian Peninggalan Purbakala.', -1.00418, 100.62884, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Tuo%20Kayu%20Jao%20%285%29.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q14917386', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8673, NULL, 7, 'Masjid Ampel', 'Surabaya', 'Jalan Gubah Kidul, Ampel, Surabaya, Jawa Timur', 'Masjid Agung Ampel adalah sebuah masjid kuno yang terletak di Desa Ampel, Kecamatan Semampir, Kota Surabaya, Provinsi Jawa Timur. Masjid ini didirikan pada tahun 1421 oleh Sunan Ampel yang di dekatnya terdapat Kompleks Pemakaman Sunan Ampel.', -7.23031, 112.743, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Poort%20bij%20de%20Ampel%20Moskee%20in%20de%20Arabische%20wijk%20van%20Soerabaja%20TMnr%2060037907.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4265576', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8674, NULL, 7, 'Masjid Agung Sang Cipta Rasa', 'Cirebon', 'Jalan Jagasatru, Lemahwungkuk, Cirebon, Jawa Barat', 'Masjid Agung Cirebon adalah sebuah masjid yang terletak di dalam kompleks Keraton Kasepuhan, Kota Cirebon, Jawa Barat. Masjid ini dibangun oleh Sunan Gunung Jati, dengan Sunan Kalijaga sebagai arsiteknya. Lokasi Masjid ini berada di bagian barat dari Alun-Alun Kota Cirebon.', -6.7255556, 108.57, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Sang%20Cipta%20Rasa%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q2791989', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8675, NULL, 7, 'Masjid Agung Banten', 'Serang', 'Jalan Masjid Agung Banten, Kasemen, Serang, Banten', 'Masjid Agung Banten (bahasa Arab:مسجد بنتن الكبير) (aksara Sunda: ᮙᮞ᮪ᮏᮤᮓ᮪ ᮃᮍᮥᮀ ᮘᮔ᮪ᮒᮨᮔ᮪)  adalah salah satu masjid tertua di Indonesia yang penuh dengan nilai sejarah. Masjid ini terletak di Banten Lama, Kelurahan Banten, Kecamatan Kasemen, Kota Serang, Provinsi Banten, Indonesia. Masjid ini adalah salah satu dari sedikit peninggalan yang tersisa dari bekas Kota Kuno Banten—pusat perdagangan paling makmur di Indonesia—setelah jatuhnya Kesultanan Demak pada pertengahan abad ke-16.', -6.03621, 106.15483, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20agung%20banten%20lama.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3384157', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 12),
  (8676, NULL, 7, 'Masjid At-Taqwa', 'Cirebon', 'Kejaksan, Cirebon, Jawa Barat', 'Masjid Raya At-Taqwa (Pegon Cirebonan: مسجد رايا التقوى) adalah sebuah masjid besar di Kota Cirebon, Jawa Barat yang didirikan pada tahun 1918 di suatu kampung yang bernama Kejaksan.\nMasjid ini semula bernama Tajug Agung., bangunannya sudah cukup lama dan tua, ruangannya terlalu kecil dan letaknya kurang menghadap kiblat, kemudian R.M. Arhatha, kepala Koordinator Urusan Agama Cirebon mempunyai gagasan untuk merenovasi Tajug Agung itu di tempat yang lama dengan mengambil nama Masjid At-Taqwa, karena sudah ada masjid agung yang terletak di kasepuhan yang sekarang menjadi Masjid Agung Sang Cipta Rasa. \nSeolah-olah pada waktu itu tidak dibenarkan dua nama yang sama pada dua masjid yang letaknya masih dalam satu kota, yaitu Tajug Agung dan Masjid Agung.', -6.71006, 108.558703, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taqwa.1.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3386650', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8677, NULL, 7, 'Masjid Baiturrahim Ulee Lheue', 'Ulee Lheue', 'Meuraxa, Banda Aceh, Aceh', 'Masjid Baiturrahim Ulee Lheue (bahasa Arab: مسجد بيت الرحيم اولو لهو) atau lebih dikenal dengan Masjid Ulee Lheue (bahasa Arab: مسجد اولو لهو) (bahasa Aceh: Meuseujid Bayturrahim Ulèe Lheue) adalah sebuah masjid bersejarah yang berada di Kota Banda Aceh, Provinsi Aceh, Indonesia. Masjid ini dibangun pada abad ke-17 dan merupakan peninggalan Kesultanan Aceh. Awalnya pada tahun 1873, masjid ini menjadi tempat relokasi sementara jemaah Masjid Baiturrahman Banda Aceh, yang dimana pada saat itu Masjid Baiturrahman Banda Aceh terbakar saat peristiwa pengusiran Pasukan Royal Belanda oleh masyarakat Aceh.', 5.555789, 95.284188, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meuseujid%20Bayturrahim%20Ul%C3%A8%C3%AB%20Lheu%C3%AB.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497282', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8678, NULL, 7, 'Masjid Cheng Ho Palembang', 'Palembang', 'Jalan Nusa Raya 2, Seberang Ulu I, Palembang, Sumatera Selatan', 'Masjid Raya Cheng Hoo Palembang atau lebih dikenal dengan Masjid Sriwijaya adalah sebuah masjid bernuansa Muslim Tionghoa yang berlokasi di Kompleks Jakabaring, Kota Palembang. Masjid ini didirikan atas prakarsa pengurus Persatuan Islam Tionghoa Indonesia dan serta tokoh masyarakat Tionghoa di sekitar Palembang.\nSelain itu, Masjid yang dibangun dengan perpaduan unsur Tiongkok, Melayu dan Nusantara.', -3.0244508, 104.7778827, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palembang%20Al%20Islam%20Muhammad%20Cheng%20Ho%20Mosque%20-%20Palembang%2C%20SS%20%2815%20Dec.%202021%29.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497285', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8679, NULL, 7, 'Masjid Wustho, Mangkunegaran', 'Surakarta', 'Jl. Sumatra 3, Ketelan, Surakarta, Jawa Tengah', 'Masjid Wustha Mangkunegaran (bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦮꦸꦱ꧀ꦛꦩꦁꦏꦸꦤꦒꦫꦤ꧀, translit. Masjid Wustha Mangkunagaran) adalah masjid tua yang terletak di Kota Surakarta. Karena menjadi "masjid negara" pada masa berdirinya Kadipaten Praja Mangkunegaran.', -7.565304, 110.821331, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Wustho%20MN%20sisi%20tenggara%20dengan%20minaret%20%28DSC%200822%29.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497343', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8680, NULL, 7, 'Masjid Al-Akbar', 'Surabaya', 'Jalan Masjid Agung Timur, Pagesangan, Surabaya, Jawa Timur', 'Masjid Nasional Al-Akbar Surabaya, juga dikenal sebagai Masjid Al-Akbar (bahasa Arab: المسجد الأكبر; bahasa Jawa: ꦩꦼꦱ꧀ꦗꦶꦢ꧀ꦄꦭ꧀ꦄꦏ꧀ꦧꦂ), atau Masjid  Agung Al Akbar Surabaya (bahasa Arab: مسجد الجامع الكبير الأكبر سورابايا) adalah sebuah masjid nasional yang berada di kota Surabaya, Provinsi Jawa Timur, Indonesia. Ini adalah masjid terbesar kedua di Indonesia setelah Masjid Istiqlal di Jakarta dalam hal kapasitas maksimum. Lokasi masjid ini berada di samping Jalan Tol Surabaya–Gempol, di kelurahan Pagesangan Kecamatan Jambangan, Surabaya Jawa Timur.', -7.336543, 112.715243, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menara%20Masjid%20Al-Akbar%20Surabaya.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13094984', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8681, NULL, 7, 'Masjid Agung Kraton Surakarta', 'Surakarta', 'Kauman, Surakarta, Jawa Tengah', 'Masjid Agung Kraton Surakarta (nama resmi: bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦄꦒꦼꦁꦏꦫꦠꦺꦴꦤ꧀ꦱꦸꦫꦏꦂꦠꦲꦢꦶꦤꦶꦔꦿꦠ꧀, translit. Masjid Agěng Karaton Suråkartå Hadiníngrat) pada masa pra-kemerdekaan adalah masjid agung milik kerajaan (Surakarta Hadiningrat) dan berfungsi selain sebagai tempat ibadah juga sebagai pusat syiar Islam bagi warga kerajaan.\nMasjid Agung dibangun oleh Sunan Pakubuwono III tahun 1763 dan selesai pada tahun 1768.', -7.574477, 110.826611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Mosque%20of%20Solo.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3386665', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8682, NULL, 7, 'Masjid Cut Mutiah', 'Jakarta Pusat', 'Jalan Cut Meutia, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Masjid Cut Meutia adalah masjid yang terletak di Jalan Cut Meutia Nomor 1, Jakarta Pusat, DKI Jakarta, Indonesia. Bangunan masjid ini merupakan salah satu peninggalan sejarah dari zaman penjajahan kolonial Belanda. Masjid ini memiliki keunikan tersendiri dan kemungkinan tidak terdapat di masjid-masjid lainnya.', -6.187285, 106.833358, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cut-Mutiah1.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4022393', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8683, NULL, 7, 'Masjid Pusaka Banua Lawas', 'Tabalong', 'Jalan 17 Mei, Banua Lawas, Tabalong, Kalimantan Selatan', 'Masjid Pusaka Banua Lawas adalah sebuah masjid tua yang terletak di desa Banua Lawas, kecamatan Banua Lawas, Kabupaten Tabalong, Kalimantan Selatan. Masjid ini juga sering disebut Masjid Pasar Arba karena pada hari rabu (arba), jumlah para pengunjung/peziarah lebih banyak dari hari-hari yang lain.\nDi masjid tertua di Kabupaten Tabalong yang dikeramatkan itu, selain menjadi tempat ibadah, juga menjadi tonggak atau bukti sejarah diterimanya Islam bagi suku Dayak Maanyan di Kabupaten Tabalong.', -2.3176205, 115.2754808, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Pusaka%20Banua%20Lawas.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4217263', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8684, NULL, 7, 'Masjid Mantingan', 'Mantingan', 'Jalan Sultan Hadlirin, Mantingan, Jepara, Jawa Tengah', 'Masjid Mantingan (bahasa Jawa: مَسْجِد ْْمَانْتِيْڠَان, ꦩꦱ꧀ꦗꦶꦢ꧀ꦩꦤ꧀ꦠꦶꦔꦤ꧀), juga dikenal dengan nama Masjid Astana Sultan Hadlirin, adalah salah satu masjid kuno di Indonesia yang terletak di Desa Mantingan, Kecamatan Tahunan, Kabupaten Jepara, Jawa Tengah. Jaraknya sekitar 5 km arah selatan dari Kecamatan Jepara. Secara keseluruhan, Masjid Mantingan merupakan sebuah kompleks yang terdiri dari masjid itu sendiri, permakaman, dan sebuah museum sederhana.', -6.6186472, 110.6771239, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Mantingan%20Jepara.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q4263071', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8685, NULL, 7, 'Masjid Tua Indrapuri', 'Indrapuri', 'Indrapuri, Aceh Besar, Aceh', 'Masjid Tua Indrapuri adalah sebuah bangunan bersejarah bekas Istana dan candi dari Kerajaan Lamuri sekitar abad ke-12 Masehi dan merupakan tempat pemujaan sebelum agama Islam masuk.\nSaat itu Kerajaan Lamuri berperang dengan pasukan bajak laut dari Tiongkok dan pada akhirnya perang dimenangkan oleh Kerajaan Lamuri atas bantuan Meurah Johan yaitu Pangeran dari Lingga, yang kemudian menjadikan Kerajaan Lamuri sebagai penganut Islam, tempat ini yang sebelumnya kuil diubah menjadi sebuah masjid. Bangunan masjid berdiri di atas tanah seluas 33.875 meter², terletak di ketinggian 4,8 meter di atas permukaan laut dan berada sekitar 150 meter dari tepi sungai Krueng Aceh.', 5.4154, 95.4466, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meuseujid%20Indra%20Puri.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q18343039', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8686, NULL, 7, 'Masjid Agung Malang', 'Malang', 'Gang Kauman 4, Klojen, Kota Malang, Jawa Timur', 'Masjid Agung Malang merupakan sebuah masjid yang terletak di Kota Malang. Masjid ini dibangun pada tahun 1890 dan selesai pada tahun 1903. Masjid ini berbentuk bujur sangkar berstruktur baja dengan atap tajug tumpang dua.', -7.9823846, 112.6296458, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Front%20Of%20Great%20Mosque%20Jami%20%27Malang.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q18347138', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8687, NULL, 7, 'Masjid Agung Nurul Islam', 'Kota Sawahlunto', 'Aurmulyo, Sawahlunto, Sumatera Barat', 'Masjid Agung Nurul Islam atau juga dikenal sebagai Masjid Agung Sawahlunto adalah salah satu masjid tertua di Indonesia yang terletak di Kelurahan Kubang Sirakuak Utara, Kecamatan Lembah Segar, Kota Sawahlunto, Sumatera Barat. Lokasinya berjarak sekitar 150 meter dari Museum Kereta Api Sawahlunto.\nMasjid yang dibangun pada masa penjajahan Belanda ini pada awalya merupakan bangunan pusat pembangkit listrik bertenaga uap.', -0.68605, 100.77775, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjidagung-nurulislam.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3386658', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8688, NULL, 7, 'Masjid Agung Al-Azhar', 'Jakarta Selatan', 'Jalan Raden Patah, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Masjid Agung Al-Azhar Jakarta (bahasa Arab: مسجد الأزهر جاكرتا) adalah sebuah masjid yang berada di Kebayoran Baru, Jakarta Selatan, DKI Jakarta. Masjid ini dimiliki oleh Yayasan Pesantren Islam Al-Azhar. Yayasan tersebut pada awalnya didirikan khusus untuk membangun masjid ini dan sekitarnya.', -6.23472, 106.79917, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Al-Azhar%202021.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q7384807', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 11),
  (8689, NULL, 7, 'Masjid Agung Manonjaya', 'Tasikmalaya', 'Jalan RTA Prawiraadiningrat, Cibeureum, Manonjaya, Jawa Barat', 'Masjid Agung Manonjaya adalah masjid yang terletak di Desa Manonjaya, Kecamatan Manonjaya, Kabupaten Tasikmalaya, Provinsi Jawa Barat. Bagian utara dan selatan masjid berbatasan dengan jalan raya. Sedangkan bagian timur berbatasan dengan Sekolah Dasar dan alun-alun.', -7.35111, 108.30694, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Manonjaya%20bagian%20samping.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497260', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8690, NULL, 7, 'Masjid Raya Andalas', 'Andalas', 'Jalan Raya Andalas, Andalas, Padang, Sumatera Barat', 'Masjid Raya Andalas (atau Andaleh dalam bahasa Minang) adalah masjid yang terletak di Jalan Andaleh Nomor 56, Kelurahan Andaleh, Kecamatan Padang Timur, Kota Padang, Sumatera Barat, Indonesia. Masjid berlantai dua ini berdiri di atas tanah seluas 1.200 meter persegi dengan warna hijau yang mendominasi dilengkapi menara di tenggara dan pintu gerbang di selatan.', -0.94047, 100.382, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Andalas.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497322', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8691, NULL, 7, 'Masjid Raya Bayur', 'Bayua', 'Bayua, Agam, Sumatera Barat', 'Masjid Raya Bayur terletak di Nagari Bayur, Kecamatan Tanjung Raya, Kabupaten Agam, Sumatera Barat, Indonesia. Letak masjid ini tidak begitu jauh dari jalan raya yang menghubungkan Lubuk Basung (Ibu kota kabupaten Agam) dengan Kota Bukittinggi.', -0.274873, 100.221439, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bayur%20Mosque.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497325', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8692, NULL, 7, 'Masjid Jamik Sultan Nata', 'Kalimantan Barat', 'Pangeran Kuning, Sintang, Kalimantan Barat', 'Masjid Jamik Sultan Nata adalah sebuah masjid bersejarah di Provinsi Kalimantan Barat, Indonesia, yang terletak di kompleks Istana Al Mukarrammah Sintang, tepatnya di Kampung Kapuas Kiri Hilir, Kabupaten Sintang. Pendirian masjid ini diprakarsai Pangeran Tunggal setelah naik tahta menggantikan Pangeran Agung (Sultan Sintang ke-17). Pada masa pemerintahannya, Islam berkembang sangat pesat.', 0.082496, 111.489674, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20JamiK%20Sultan%20Nata%20Sintang%201.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497304', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8693, NULL, 7, 'Masjid Raya Syekh Burhanuddin', 'Ulakan', 'Kampuang Gelapuang Ulakan, Padang Pariaman, Sumatera Barat', 'Masjid Raya Syekh Burhanuddin adalah salah satu masjid sekaligus cagar budaya di Sumatera Barat. Masjid ini terletak di Nagari Ulakan, Kecamatan Ulakan Tapakis, Kabupaten Padang Pariaman, Sumatera Barat.', -0.690146, 100.20203, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Syekh%20Burhanuddin%202020%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497334', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8694, NULL, 7, 'Masjid Sultan Ternate', 'Ternate', 'Gamalama, Ternate, Maluku Utara', 'Masjid Sultan Ternate adalah sebuah masjid yang terletak di kawasan Jalan Sultan Khairun, Kelurahan Soa Sio, Kecamatan Ternate Utara, Kota Ternate, Maluku Utara. Masjid ini menjadi bukti keberadaan Kesultanan Islam pertama di kawasan timur Nusantara ini. Kesultanan Ternate mulai menganut Islam sejak raja ke-18, yaitu Kolano Marhum yang bertahta sekitar 1465-1486 M. Pengganti Kolano Marhum adalah putranya, Zainal Abidin (1486-1500), yang kemudian mengganti gelar Kolano menjadi Sultan, menetapkan Islam sebagai agama resmi kerajaan, memberlakukan syariat Islam, serta membentuk lembaga kerajaan sesuai hukum Islam dengan melibatkan para ulama.', 0.798466, 127.385331, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid-ternate.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497340', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8695, NULL, 7, 'Masjid Tua Wapauwe', 'Kaitetu', 'Kaitetu, Maluku Tengah, Maluku', 'Masjid Tua Wapauwe adalah masjid tua bersejarah dan juga merupakan masjid tertua di Maluku. Masjid ini dibangun pada tahun 1414 M. Masjid Tua Wapauwe saat ini masih berdiri dam menjadi bukti sejarah penyebaran Islam di Maluku pada masa lampau.', -3.585226, 128.084243, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Tua%20Wapauwe%20Kaitetu.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497346', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8696, NULL, 7, 'Masjid Agung Palembang', 'Palembang', 'Jalan Jenderal Sudirman, Bukit Kecil, Palembang, Sumatera Selatan', 'Masjid Agung Sultan Mahmud Badaruddin I Jayo Wikramo (Jawi: مسجيد أڬوڠ سولطن محمود بدارودين ١ جايو ويكرامو)  adalah sebuah masjid paling besar di Kota Palembang, Sumatera Selatan. Masjid ini didirikan pada abad ke-18 oleh Sultan Mahmud Badaruddin I Jayo Wikramo. Saat ini, Masjid Agung Palembang telah menjadi Masjid regional di kawasan ASEAN. Masjid ini menempati kompleks seluas 15.400 meter persegi, di kawasan 19 Ilir, di mana merupakan salah satu Kampung Asli Melayu Palembang dan Arab yang telah lama didiami.', -2.98748, 104.75997, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Palembang.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q14917382', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8697, NULL, 7, 'Masjid Azizi', 'Langkat', 'Tanjung Pura', 'Masjid Azizi (bahasa Arab: مسجد عزيزي), secara resmi bernama Masjid Sultan Abdul Aziz (bahasa Arab: مسجد السلطان عبد العزيز) atau lebih dikenal dengan Masjid Kesultanan Langkat (bahasa Arab: مسجد لانجكات الملكي) adalah sebuah masjid bersejarah peninggalan Kesultanan Langkat yang berada di Kelurahan Tanjung Pura, Kecamatan Tanjung Pura, Kabupaten Langkat, Provinsi Sumatera Utara, Indonesia. Masjid ini awalnya dibangun pada tahun 1889, atas perintah Sultan Abdul Aziz, penguasa Kesultanan Langkat akhir abad ke-19. Arsitektur masjid ini menjadi inspirasi bagi arsitektur Masjid Zahir di Kedah, Malaysia.', 3.89145, 98.42392, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Azizi%20Mosque%20side.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q14917383', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8698, NULL, 7, 'Masjid Jami Pontianak', 'Pontianak', 'Pontianak Timur, Pontianak, Kalimantan Barat', 'Masjid Jami\' Pontianak atau dikenal juga dengan nama Masjid Sultan Syarif Abdurrahman adalah masjid tertua dan terbesar di Kota Pontianak, Provinsi Kalimantan Barat, Indonesia. Masjid ini merupakan satu dari dua bangunan yang menjadi pertanda berdirinya Kota Pontianak pada 1771 Masehi, selain Keraton Kadriyah.', -0.026738, 109.347678, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kesultanan%20Syarif%20Abdurrahman.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q14917384', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 10),
  (8699, NULL, 7, 'Masjid Merah Panjunan', 'Cirebon', 'Jalan Kolektoran, Lemahwungkuk, Cirebon, Jawa Barat', 'Masjid Merah Panjunan adalah sebuah masjid berarsitektur Arab-Tionghoa yang berada di Kota Cirebon, Jawa Barat. Masjid ini direnovasi dan dinamai ulang sesuai nama jalan tempat masjid ini dibangun yaitu Jalan Panjunan. Masjid Merah Panjunan ini telah dimasukkan sebagai benda cagar budaya.', -6.717479, 108.566065, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Merah%20Panjunan%2002.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q19728970', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8700, NULL, 7, 'Masjid Raya Ganting', 'Ganting Parak Gadang', 'Jalan Muhammad Husni Thamrin, Ranah Dalam 1, Padang, Sumatera Barat', 'Masjid Raya Ganting (atau ditulis dan dilafalkan Gantiang dalam bahasa Minang) adalah masjid peninggalan abad ke-19 yang terletak di Kampung Ganting, Kecamatan Padang Timur, Kota Padang, Sumatera Barat, Indonesia. Tercatat sebagai masjid tertua di Padang, cikal bakal masjid ini berawal dari sebuah surau di Seberang Padang, daerah permukiman awal dalam sejarah Padang. Arsitekturnya merepresentasikan akulturasi etnis-etnis yang ada di Padang dengan pengaruh Neoklasik dari Eropa yang dominan pada bagian fasad.', -0.9545, 100.36945, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Makam%20Syekh%20Bayang%2020220413%20173107.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3409262', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8701, NULL, 7, 'Masjid Saka Tunggal', 'Banyumas', 'Jalan Raya Pancasan, Windunegara, Banyumas, Jawa Tengah', 'Masjid Saka Tunggal Banyumas adalah sebuah masjid yang berada di Desa Cikakak, Kecamatan Wangon, Kabupaten Banyumas, Jawa Tengah atau sekitar 30 kilometer arah barat daya Purwokerto. Masjid ini dipercaya merupakan masjid tertua yang ada di Indonesia, bahkan masjid ini ada sebelum adanya Wali Sanga. Masjid ini dibangun pada tahun 1288 M (687 H) seperti yang tertulis pada Saka Guru (Tiang Utama) masjid ini.', -7.47387, 109.056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saka%20Tunggal%20Mosque%20%28exterior%2C%20HDR%29%2C%20Banyumas%20Regency%2C%202015-03-22.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q18347028', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8702, NULL, 7, 'Masjid Raya Sultan Riau', 'Tanjungpinang', 'Jalan Ahmadi, Penyengat, Tanjungpinang, Kepulauan Riau', 'Masjid Raya Sultan Riau atau disebut juga Masjid Sultan Riau merupakan salah satu masjid tua dan bersejarah di Indonesia yang berada di pulau Penyengat, Kota Tanjungpinang, provinsi Kepulauan Riau. Masjid ini merupakan salah satu masjid unik karena salah satu campuran bahan bangunan yang digunakan adalah putih telur. Masjid Sultan Riau ini sudah dijadikan situs cagar budaya oleh pemerintah Republik Indonesia.', 0.9294444, 104.4203889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20sultan%20Riau%20Penyengat.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q2690065', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8703, NULL, 7, 'Masjid Bayan Beleq', 'Lombok Utara', 'Bayan, Nusa Tenggara Barat', 'Masjid Bayan Beleq adalah sebuah masjid Tarekat Wetu Telu yang terletak di jalan Labuan lombok, desa Bayan, kecamatan Bayan, Kabupaten Lombok Utara, Nusa Tenggara Barat atau sekitar 80 km dari ibu kota provinsi NTB, yakni Mataram.', -8.26662, 116.42716, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bayan%20Beleq%20Mosque%2C%20Lombok%2C%20Indonesia.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497286', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8704, NULL, 7, 'Masjid Raya Kubang Putih', 'Kubang Putiah', 'Kubang Putiah, Agam, Sumatera Barat', 'Masjid Kubang Putih atau Masjid Raya Kubang Putih terletak di Nagari Kubang Putih, Kecamatan Banuhampu, Kabupaten Agam, Sumatera Barat. Masjid ini berdiri sejak 1810 memakai nama tempat berdirinya. Bangunannya tidak mengalami banyak perbaikan kecuali beberapa kali pengecetan ulang.', -0.33332, 100.4011, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kubang%20Agam.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q44033995', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8705, NULL, 7, 'Jakarta Islamic Centre', 'Jakarta Utara', 'Jalan Kramat Jaya, Koja, Jakarta Utara', 'Jakarta Islamic Centre (terj. har. \'Pusat Islam Jakarta\'), secara resmi bernama Pusat Pengkajian dan Pengembangan Islam Jakarta, adalah sebuah kompleks masjid serta lembaga pengkajian dan pengembangan Islam yang berada di kota Jakarta Utara, Provinsi Daerah Khusus Ibukota Jakarta, Indonesia. Awalnya masjid ini menempati lahan bekas kawasan rehabilitasi pelacuran terbesar di Asia Tenggara, yaitu Kramat Tunggak.', -6.122601, 106.917278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gerbang%20Jakarta%20Islamic%20Centre.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q48724457', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8706, NULL, 7, 'Masjid Raya Teluk Bayur', 'Teluk Bayur', 'Teluk Bayur, Padang, Sumatera Barat', 'Masjid Raya Teluk Bayur atau dulunya dikenal sebagai Surau Ateh adalah salah satu masjid tertua di Indonesia yang terletak di kawasan pelabuhan Teluk Bayur, Kecamatan Padang Selatan, Kota Padang, Sumatera Barat. Meski masjid yang sebelumnya hanya berupa surau ini tercatat telah berdiri sejak akhir abad ke-17, tetapi bangunan yang berdiri di lokasi sekarang baru dibangun pada masa penjajahan Belanda sekitar akhir abad ke-19.\nSaat ini, selain digunakan untuk aktivitas ibadah umat Islam, masjid satu lantai ini juga digunakan sebagai sarana pendidikan agama dan pesantren kilat bagi pelajar.', -0.995672, 100.369707, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Taluak%20Bayua.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q11018766', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8707, NULL, 7, 'Masjid Al-Osmani', 'Medan', 'Medan Labuhan, Kota Medan, Sumatera Utara', 'Masjid Al-Osmani (Aksara Jawi:مسجد العثماني) adalah sebuah masjid di Medan, Sumatera Utara. Masjid ini juga di kenal dengan sebutan Masjid Labuhan karena lokasinya yang berada di kecamatan Medan Labuhan. Masjid ini terletak di jalan K.L. Yos Sudarso Kel.', 3.732239, 98.676205, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Al-Osmani%20Mosque%2C%20Medan%2C%20Indonesia.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497269', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8708, NULL, 7, 'Masjid Raya Lima Kaum', 'Limo Kaum', 'Limo Kaum, Tanah Datar, Sumatera Barat', 'Masjid Raya Lima Kaum adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Lima Kaum, Kecamatan Lima Kaum, Kabupaten Tanah Datar, Sumatera Barat. Masjid ini diperkirakan berdiri pada tahun 1710. Lokasinya berada di pusat Nagari Lima Kaum, yakni di Balai Sariak, Jorong Tigo Tumpuak, sekitar 20 meter dari jalan arah Batusangkar menuju Padang.', -0.465606, 100.568022, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Lima%20Kaum.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497328', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8709, NULL, 7, 'Masjid Jamik Taluak Bukittinggi', 'Taluak Ampek Suku', 'Taluak IV Suku, Agam, Sumatera Barat', 'Masjid Jamik Taluak adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Taluak IV Suku, Kecamatan Banuhampu, Kabupaten Agam, Sumatera Barat. Letak masjid ini dekat dengan perbatasan Kota Bukittinggi, sehingga juga dikenal sebagai Masjid Jamik Taluak Bukittinggi.\nPembangunan masjid ini diprakarsai oleh Haji Abdul Majid pada tahun 1860, yang pada mulanya hanya terbuat dari kayu beratapkan ijuk.', -0.3278, 100.38818, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid-Taluak-Sumatra-Barat.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497306', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8710, NULL, 7, 'Masjid Muhammadan', 'Pasa Gadang', 'Jalan Pasar Batipuh, Pasa Gadang, Padang, Sumatera Barat', 'Masjid Muhammadan terletak di Kelurahan Pasa Gadang, Kecamatan Padang Selatan, Kota Padang, Sumatera Barat. Masjid ini merupakan peninggalan komunitas Muslim keturunan India di Padang dan kemungkinan berdiri pada abad ke-19. Lokasinya berada di Kota Tua Padang, yakni kawasan sehiliran Batang Arau di sekitar pelabuhan Muara.', -0.9614856, 100.3641762, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Muhammadan%20Agustus%202020.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497310', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8711, NULL, 7, 'Masjid Tuo Koto Nan Ampek', 'Padangtongah Balainanduo', 'Padangtangah Balain Nanduo, Payakumbuh, Sumatera Barat', 'Masjid Tuo Koto Nan Ampek atau juga disebut Masjid Gadang Balai Nan Duo adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Koto Nan Ampek atau kini secara administratif termasuk ke dalam wilayah Kelurahan Balai Nan Duo, Kecamatan Payakumbuh Barat, Kota Payakumbuh, Sumatera Barat. Masjid berarsitektur Minangkabau ini diperkirakan dibangun pada tahun 1840, yang pada mulanya beratapkan ijuk sebelum akhirnya diganti menjadi seng.\nSaat ini selain digunakan untuk aktivitas ibadah umat Islam, masjid satu lantai ini juga digunakan oleh masyarakat sekitar sebagai sarana pendidikan agama sekaligus tempat bermusyawarah.', -0.233117, 100.622558, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Tuo%20Koto%20Nan%20Ampek%202021%20landscape.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497342', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8712, NULL, 7, 'Masjid Agung Al-Falah', 'Jambi', 'Jalan Raden Pemuk, Beringin, Jambi, Jambi', 'Masjid Agung Al-Falah merupakan masjid terbesar di Kota Jambi, masjid ini juga dikenal sebagai Masjid Seribu Tiang, meskipun jumlah tiangnya hanya 232. Masjid ini dibangun pada tahun 1971 dan selesai pada tahun 1980, bangunannya memang hanya seperti sebuah pendopo terbuka dengan banyak tiang penyangga dan satu kubah besar di atasnya. Lokasi Masjid Agung ini berdiri, dulunya merupakan pusat Kesultanan Jambi, bekas istana Tanah Pilih dari Sultan Thaha Syaifuddin.', -1.5941944, 103.6085, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiang%20Teras%20Masjid%20Agung%20Al-Falah.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13094978', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8713, NULL, 7, 'Masjid Raya Bandung', 'Bandung', 'Jalan Alun-alun Timur No.1, Regol, Kota Bandung, Jawa Barat', 'Masjid Agung Bandung (Aksara Sunda: ᮙᮞ᮪ᮏᮤᮓ᮪ ᮛᮚ ᮘᮔ᮪ᮓᮥᮀ) adalah sebuah masjid raya yang berada di Kota Bandung, Jawa Barat. Status masjid ini adalah sebagai Masjid dibawah kepengurusan Nazhir Wakaf Keluarga Wiranatakusumah. Masjid ini pertama dibangun tahun 1810 dan sejak didirikannya telah mengalami 8 kali perombakan pada abad ke-19, kemudian 5 kali pada abad 20 sampai akhirnya direnovasi lagi pada tahun 2001 sampai peresmian Masjid Raya Bandung 4 Juni 2003 yang diresmikan oleh Gubernur Jawa Barat saat itu, H.R. Nuriana.', -6.921734, 107.606259, NULL, 'Sen–Sab 09.00–17.00; Min 09.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Bandung%20dan%20Alun-alun%20Bandung%20%28potrait%29.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13094993', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8714, NULL, 7, 'Masjid Tua Palopo', 'Palopo', 'Jalan Jenderal Ahmad Yani, Pontap, Palopo, Sulawesi Selatan', 'Masjid Jami Tua Palopo merupakan masjid peninggalan Kerajaan Luwu yang berlokasi di Kota Palopo, Sulawesi Selatan. Masjid ini didirikan oleh Raja Luwu yang bernama Datu Payung Luwu XVI Pati Pasaung Toampanangi Sultan Abdullah Matinroe pada tahun 1604 M. Masjid yang memiliki luas 15 m² ini diberi nama Jami, yang berarti (Penyatu) dalam bahasa Arab, dan Tua, karena usianya yang sudah tua. Sedangkan nama Palopo diambil dari kata dalam bahasa Bugis dan Luwu yang memiliki dua arti, yaitu: pertama, penganan yang terbuat dari campuran nasi ketan dan air gula; kedua, memasukkan pasak dalam lubang tiang bangunan.', -2.994113, 120.195301, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Tua%20Palopo.JPG?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13095009', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 9),
  (8715, NULL, 7, 'Masjid Jamik Sumenep', 'Kota Sumenep', 'Jalan Manikam, Sumenep, Jawa Timur', 'Masjid Agung Sumenep atau lebih dikenal dengan nama Masjid Jamik Sumenep adalah sebuah masjid yang berada di Kabupaten Sumenep, Jawa Timur. Berdiri menghadap Alun-Alun Sumenep dan menjadi simbol masuknya Islam di Kabupaten Sumenep.', -7.007985, 113.858763, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Moskee%20Madoera%20TMnr%2060022649.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3386677', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8716, NULL, 7, 'Masjid Raya Balai Gadang Mungo', 'Mungo', 'Andaleh, Lima Puluh Kota, Sumatera Barat', 'Masjid Raya Balai Gadang Mungo adalah salah satu masjid tertua di Indonesia yang terletak di Jorong Balai Gadang Bawah, Nagari Mungo, Kecamatan Luhak, Kabupaten Lima Puluh Kota, Sumatera Barat. Masjid yang mulai dibangun pada tahun 1914 ini tercatat sebagai masjid tertua di Nagari Mungo.\nDi kompleks masjid, terdapat makam Syekh Syahidan Syarbaini, seorang ulama Tarekat Naqsyabandiyah.', -0.233489, 100.699214, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Balai%20Gadang%20Mungo%202020%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q18435045', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8717, NULL, 7, 'Masjid Al-Markaz Al-Islami', 'Makassar', 'Jalan Al Markaz Al Islami, Bontoala, Makassar, Sulawesi Selatan', 'Masjid Al-Markaz Al-Islami merupakan sebuah masjid yang terletak di Makassar, Indonesia. Masjid ini dibangun pada tahun 1994 dan selesai pada tahun 1996. Saat ini berkembang menjadi pusat pengembangan ibadah agama Islam terbesar dan termegah di Sulawesi Selatan, terletak di Jalan Masjid Raya Makassar.', -5.1299887, 119.4263232, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Al-Markaz%20Al-Islami%20Makassar.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q3386529', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8718, NULL, 7, 'Masjid Raya Sabilal Muhtadin', 'Antasan Besar', 'Jalan Jenderal Sudirman, Banjarmasin Tengah, Banjarmasin, Kalimantan Selatan', 'Masjid Raya Sabilal Muhtadin  adalah sebuah masjid bersejarah yang berada di Jalan Jenderal Sudirman No. 1, Kelurahan Antasan Besar, Kecamatan Banjarmasin Tengah, Kota Banjarmasin, Provinsi Kalimantan Selatan, Indonesia. Masjid ini dibangun pada tahun 1974 dan diresmikan pada tahun 1981 sebagai penghormatan terhadap ulama besar Syekh Muhammad Arsyad al-Banjari, di mana nama masjid ini diambil dari nama kitabnya yang berjudul Sabilal Muhtadin lit-Tafaqquh fi Amrid-din (Jalan bagi Orang-Orang yang Mendapat Petunjuk untuk Mendalami Urusan-Urusan Agama), sebuah kitab fikih mazhab Syafii yang menjadi salah satu rujukan ulama di Nusantara.', -3.31901, 114.59125, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Sabilal%20Muhtadi%20depan.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q7396100', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8719, NULL, 7, 'Mesjid Agung Garut', 'Garut Kota', 'Jalan Jenderal Ahmad Yani, Garut Kota, Garut, Jawa Barat', 'Masjid Agung Garut (Aksara Sunda: ᮙᮞ᮪ᮏᮤᮓ᮪ ᮃᮌᮥᮀ ᮌᮛᮥᮒ᮪) terletak di Kelurahan Paminggir, Kecamatan Garut Kota, tepatnya di Jalan Jend. Ahmad Yani Garut, sebelah barat Alun-alun Garut. Menempati lahan yang luasnya 4.480 m2.', -7.2161389, 107.9008889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mesjid%20Agung%20Garut.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q10977168', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8720, NULL, 7, 'Masjid Islamic Center Samarinda', 'Samarinda', 'Jalan K.H. Fakhruddin, Sungai Kunjang, Samarinda, Kalimantan Timur', 'Masjid Islamic Center Samarinda (bahasa Indonesia: Masjid Pusat Islam Samarinda) (bahasa Arab: مسجد مركز ساماريندا الإسلامي) atau yang lebih dikenal dengan nama resminya Masjid Baitul Muttaqien (bahasa Arab: مسجد بيت المتقين) adalah masjid yang terletak di Teluk Lerong Ulu, Kota Samarinda, Provinsi Kalimantan Timur, Indonesia, yang merupakan salah satu masjid terbesar di Asia Tenggara. Masjid ini terletak di latar depan Sungai Mahakam, dan memiliki tujuh minaret dan satu kubah besar.\nMasjid ini memiliki luas bangunan 43.500 meter persegi, dengan luas bangunan pendukung 7.115 meter persegi, dan luas lantai basemen 10.235 meter persegi.', -0.5025278, 117.1199444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Islamic%20Centre%20Samarinda%20by%20bloesafir%20-%20panoramio.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497292', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8721, NULL, 7, 'Masjid Jamik Sungai Jambu', 'Sungai Jambu', 'Sungai Jambu, Tanah Datar, Sumatera Barat', 'Masjid Jami Sungai Jambu adalah salah satu masjid tertua di Indonesia yang terletak di Jorong Sungai Jambu, Nagari Sungai Jambu, Kecamatan Pariangan, Kabupaten Tanah Datar, Sumatera Barat. Masjid yang berada di kaki Gunung Marapi ini mulai dibangun pada tahun 1918, yang dalam perkembangannya telah mengalami sejumlah peningkatan baik dari segi fisik maupun pengelolaannya. Masjid ini sempat beberapa kali meraih peringkat pertama dalam penilaian masjid berwawasan lingkungan untuk tingkat provinsi yang dilakukan oleh Dewan Masjid Indonesia, seperti yang terakhir pada tahun 2012.', -0.439308, 100.514802, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jamik%20Sungai%20Jambu%202020%2001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497303', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8722, NULL, 7, 'Masjid Nurul Iman Koto Gadang', 'Koto Gadang', 'Jalan Mr. Mohammad Nazif, Koto Gadang, Agam, Sumatera Barat', 'Masjid Nurul Iman Koto Gadang atau Masjid Tapi Koto Gadang terletak di Nagari Koto Gadang, Kecamatan IV Koto, Kabupaten Agam, Sumatera Barat. Masjid ini merupakan masjid terbesar di Koto Gadang.\nSejak didirikan pertama kali pada tahun 1856, masjid ini telah mengalami perubahan bentuk dan beberapa kali perbaikan.', -0.318243, 100.357367, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Nurul%20Iman%20Koto%20Gadang%202020%2002.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q19746209', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8723, NULL, 7, 'Masjid Agung Baitul Makmur Meulaboh', 'Aceh', 'Seuneubok, Aceh Barat, Aceh', 'Masjid Agung Baitul Makmur adalah masjid terbesar dan termegah di kawasan pantai sebelah barat Kabupaten Aceh Barat. Masjid yang terletak di Drien Rampak, Kec. Johan Pahlawan ini memiliki arsitektur antara perpaduan Timur Tengah, Asia dan Aceh.', 4.158785, 96.124813, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Meulaboh.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497256', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8724, NULL, 7, 'Masjid Su\'ada', 'Kalimantan Selatan', NULL, 'Masjid As-Suada (bahasa Arab مسجد السعداء) atau yang lebih dikenal dengan Masjid As-Suada Baangkat (bahasa Arab: مسجد السعودة بانجكات) adalah sebuah masjid tua bersejarah yang berada di Kabupaten Hulu Sungai Selatan, Provinsi Kalimantan Selatan, Indonesia. Secara administratif mesjid ini terletak di desa Wasah Hilir, Kecamatan Simpur, Kabupaten Hulu Sungai Selatan.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Su%27ada%20Wasah%20Hilir%20001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497280', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8725, NULL, 7, 'Masjid Raya Koto Baru', 'Koto Baru', 'Jalan Raya Muara Labuh, Muara Labuh, Sumatera Barat', 'Masjid Raya Koto Baru adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Koto Baru, Kecamatan Sungai Pagu, Kabupaten Solok Selatan, Sumatera Barat.\nMasjid ini mulai dibangun pada tahun 1922 dengan arsitektur menyerupai Masjid Rao Rao yang terletak di Kabupaten Tanah Datar, yaitu berupa perpaduan antara arsitektur Minangkabau dengan Persia. Masjid ini sempat mengalami kerusakan cukup berarti akibat gempa dengan kerusakan terparah terjadi pada tahun 1926, yang pada saat itu masjid ini masih dalam tahap pengerjaan sehingga mengakibatkan pembangunannya baru dapat diselesaikan pada tahun 1933.', -1.481221, 101.059652, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Solok%20IMG20230211152108.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497326', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8726, NULL, 7, 'Masjid Nurul Huda', 'Durian I', 'Durian I, Sawahlunto, Sumatera Barat', 'Masjid Nurul Huda adalah salah satu masjid tertua di Indonesia yang terletak di Kecamatan Baringin, Kota Sawahlunto, Sumatera Barat. Masjid yang dibangun pada masa penjajahan Belanda ini memiliki bangunan berbentuk persegi panjang dengan sebuah menara yang menyatu dengan bangunan utama.\nSaat ini selain berfungsi sebagai tempat ibadah umat Islam, masjid berlantai dua ini juga digunakan sebagai sarana pendidikan agama bagi masyarakat sekitar.', -0.668504, 100.762293, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Nurul%20Huda%20di%20Pasar%20Baru%20Durian%2C%20Barangin%2C%20Sawahlunto.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q12497315', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8727, NULL, 7, 'Masjid Al Ihsaniyah', 'Jambi', 'Danau Teluk, Jambi, Jambi', 'Masjid Al Ihsaniyah atau yang lebih dikenal dengan nama Masjid Batu adalah masjid tertua di kota Jambi, provinsi Jambi. Masjid ini terletak di Seberang Kota Jambi, lebih tepatnya di kawasan Olak Kemang, kecamatan Danau Teluk.', -1.5852474, 103.6024016, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Moskee%20Djambi%20TMnr%2010016663.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q13094992', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8728, NULL, 7, 'Masjid Cheng Ho Surabaya', 'Surabaya', 'Jalan Telasih, Ketabang, Surabaya, Jawa Timur', 'Masjid Raya Cheng Ho Surabaya adalah sebuah Masjid bernuansa Muslim Tionghoa yang berlokasi di Jalan Gading, Ketabang, Kec. Genteng, Surabaya atau 1.000 m utara Gedung Balai Kota Surabaya. Masjid ini didirikan atas prakarsa para sesepuh, penasehat, pengurus PITI, dan pengurus Yayasan Haji Muhammad Cheng Ho Indonesia Jawa Timur serta tokoh masyarakat Tionghoa di Surabaya.', -7.2519444, 112.7466667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheng%20ho.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q14917385', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8729, NULL, 7, 'Masjid Jami Syekh Abdul Hamid Abulung', 'Kalimantan Selatan', 'Martapura, Kalimantan Selatan', 'Masjid Jami Syekh Abdul Hamid Abulung atau biasa disebut Masjid Datu Abulung adalah salah satu masjid tua di provinsi Kalimantan Selatan, Indonesia, yang berlokasi di desa Sungai Batang, kecamatan Martapura Barat, Kabupaten Banjar. Masjid ini dibangun oleh Raja Banjar, Sultan Tahmidullah II yang memerintah periode 1761-1801 sebagai bentuk penebusan dosa karena telah memerintahkan para algojo raja untuk mengeksekusi Datu Abulung, seorang ulama yang sempat dituding memiliki ajaran sesat.\nMasjid ini termasuk ke dalam salah satu cagar budaya yang berada di Kabupaten Banjar.', -3.4116, 114.8452, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Datu%20Abulung%20001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q16162803', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (8730, NULL, 7, 'Masjid Jami Kalipasir', 'Tangerang', 'Gang Masjid, Tangerang, Banten', 'Masjid Kali Pasir adalah masjid tertua di Kota Tangerang peninggalan Kerajaan Pajajaran. Masjid ini berada di sebelah timur bantaran Sungai Cisadane, tepatnya di tengah pemukiman warga Tionghoa kelurahan Sukasari. Bangunannya pun bercorak Tionghoa.', -6.1792222, 106.6288611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%20Kalipasir.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q16862806', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (8731, NULL, 7, 'Masjid Raya Darussalam Palangka Raya', 'Palangka Raya', 'Jalan G. Obos 9, Menteng, Palangka Raya, Kalimantan Tengah', 'Masjid Raya Darussalam Palangka Raya merupakan salah satu bangunan masjid termegah di provinsi Kalimantan Tengah. Masjid ini terletak di Jalan G. Obos no. 12, Kecamatan Jekan Raya, Kota Palangka Raya.', -2.230956, 113.890124, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Darussalam%20Palangka%20Raya%20003.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q113458530', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 0),
  (8732, NULL, 7, 'Masjid Jami Banjarmasin', 'Banjarmasin', 'Jalan Mesjid Jami, Banjarmasin Utara, Banjarmasin, Kalimantan Selatan', 'Masjid Jami Banjarmasin (aksara Jawi: مسجد جامع بنجرماسين) atau yang lebih dikenal dengan Masjid Jami Sungai Jingah (aksara Jawi: مسجد جامع ﺳﻮ ڠاﻱ‬ جيڠاه) adalah sebuah masjid bersejarah yang berada di Jalan Masjid Jami, Kelurahan Antasan Kecil Timur, Kecamatan Banjarmasin Utara, Kota Banjarmasin, Provinsi Kalimantan Selatan, Indonesia.\nMasjid ini berdekatan dengan Kompleks Makam Pangeran Antasari, di mana kompleks makam ini berada di daerah timur masjid, tepatnya di Jalan Malkon Temon. Selain itu, masjid ini juga berdekatan dengan makam salah satu ulama karismatik, yaitu K.H. Ahmad Zuhdiannor atau sering disapa Guru Zuhdi yang semasa hidupnya mengisi kegiatan keagaamaan di masjid ini, di mana makamnya berada di daerah barat masjid atau dikenal dengan daerah "Jalan Belakang Masjid Jami".', -3.3066667, 114.595, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%20Sungai%20Jingah%20Banjarmasin%20001.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q6684680', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 0),
  (8733, NULL, 7, 'Masjid Lama Gang Bengkok', 'Sumatera Utara', 'Jalan Mesjid, Medan Barat, Kota Medan, Sumatera Utara', 'Masjid Lama Gang Bengkok Medan merupakan sebuah masjid yang terletak di Kota Medan, Sumatera Utara, Indonesia. Masjid Lama Gang Bengkok ini tepatnya berada di Jalan Mesjid No. 62, Kelurahan Kesawan, Kecamatan Medan Barat, Kota Medan.', 3.5866474, 98.6779922, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Lama%20Gang%20Bengkok%20Medan%202021.jpg?width=800', '2026-11-04 09:40:51', '2026-11-24 23:32:50', 'wd:Q110706913', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (8734, NULL, 6, 'Taman Mini Indonesia Indah', 'Cipayung', 'Jalam Kramat Duri, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Taman Mini Indonesia Indah (disingkat TMII; sebelumnya Taman Mini "Indonesia Indah" dengan tanda kutip) merupakan suatu taman hiburan bertemakan kebudayaan Indonesia di Jakarta Timur, DKI Jakarta, yang memiliki area seluas kurang lebih 147 hektare atau 1,47 kilometer persegi. Taman ini merupakan rangkuman kebudayaan bangsa Indonesia, yang mencakup berbagai aspek kehidupan sehari-hari masyarakat provinsi Indonesia yang ditampilkan dalam anjungan daerah berarsitektur tradisional, serta menampilkan aneka busana, tarian, dan tradisi daerah.\nDi samping anjungan-anjungan daerah, di tengah-tengah TMII terdapat sebuah danau yang menggambarkan miniatur kepulauan Indonesia yang memiliki pertunjukkan air mancur menari dan atraksi drone bernama Tirta Cerita.', -6.301667, 106.896667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tongkonan%20-%20South%20Sulawesi%20Pavilion%20TMII%20%282025%29%20-%20img%2001.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q685790', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 18),
  (8735, NULL, 6, 'Trans Studio Bandung', 'Kota Bandung', 'Jalan Cibangkong Lor, Batununggal, Kota Bandung, Jawa Barat', 'Trans Studio Mall Bandung adalah sebuah pusat perbelanjaan, taman hiburan, dan hotel di Bandung, Jawa Barat, Indonesia. Trans Studio dibangun di atas lahan seluas 4,2 hektar ( 10 are ) yang menjadikan taman wahana pertama di wilayah Indonesia Barat dalam jaringan Trans Studio, dua tahun setelah diresmikannya Trans Studio Mall Makassar di wilayah Indonesia Timur. Trans Studio Bandung terdiri dari beberapa bagian termasuk pusat perbelanjaan yang disebut Trans Studio Mall (biasanya disebut TSM ), taman rekreasi yang disebut Trans Studio, hotel bintang 3 yang disebut ibis Bandung Trans Studio, dan hotel mewah bintang 5 yang disebut The Trans Luxury Hotel.', -6.9261861, 107.6362222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bandung%2C%20Bandung%20City%2C%20West%20Java%2C%20Indonesia%20-%20panoramio%20%282%29.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q4210050', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 6),
  (8736, NULL, 6, 'Jawa Timur Park', 'Batu', 'Jalan Kartika No.2, Lowokwaru, Kota Batu, Jawa Timur', 'Jawa Timur Park adalah sebuah tempat rekreasi dan taman belajar yang terdapat di Kota Batu, Jawa Timur. Objek wisata ini berada sekitar 20 km barat Kota Malang, dan kini menjadi salah satu icon wisata Jawa Timur. Objek wisata ini memiliki 36 wahana, di antaranya kolam renang raksasa (dengan latar belakang patung Ken Dedes, Ken Arok, dan Mpu Gandring), spinning coaster, dan drop zone.', -7.88412, 112.52491, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/East%20Java%20Park%2C%20Batu%2C%20Malang.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q19726842', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 6),
  (8737, NULL, 6, 'Trans Studio Cibubur', 'Depok', 'Jalan Transyogi, Harjamukti, Depok, Jawa Barat', 'Trans Studio Mall Cibubur adalah sebuah pusat perbelanjaan yang terletak di Depok, Jawa Barat. Didirikan pada tahun 2019, mal ini adalah cabang keempat mal milik Trans Shopping Mall Group yang dikelola melalui merek Trans Studio, menyusul Trans Studio Mall Makassar, Trans Studio Mall Bandung, dan Trans Studio Mall Bali. Trans Studio Mall Cibubur membentuk kawasan Transpark Cibubur yang juga mencakup apartemen dan taman bermain.', -6.375656, 106.901736, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trans%20Studio%20Cibubur.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q66048971', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 4),
  (8738, NULL, 6, 'Trans Studio Resort Makassar', 'Indonesia', 'Tamalate, Makassar, Sulawesi Selatan', 'Trans Studio Resort Makassar adalah taman hiburan di Indonesia.', -5.15968, 119.394, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/TransStudioShow.JPG?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q7833687', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 3),
  (8739, NULL, 6, 'Rumah Katu Marine Park', 'Indonesia', 'Tokorondo, Sulawesi Tengah', 'Rumah Katu Marine Park atau Taman Laut Rumah Katu, adalah sebuah taman air laut yang terletak di Kota Poso, Sulawesi Tengah, Indonesia. Taman ini terletak di Pantai Madale, sekitar 10 km dari pusat kota Poso.\nDi Rumah Katu Marine Park, permainan outbond seperti banana boat dan flying fox tersedia.', -1.3588889, 120.5505556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Katu%20Marine%20Park.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q27070226', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 3),
  (8740, NULL, 6, 'Batu Night Spectacular', 'Jawa Timur', 'Jalan Raya Oro-Oro Ombo, Lowokwaru, Kota Batu, Jawa Timur', 'Batu Night Spectacular (BNS) adalah sebuah lokawisata yang berada di Kota Batu, Jawa Timur. BNS hanya beroperasi pada malam hari. BNS menggabungkan konsep pusat perbelanjaan, permainan, olahraga, dan hiburan di dalamnya.', -7.896263, 112.534608, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batu%20Night%20Spectacular%20Main%20Entrance.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q28723978', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 2),
  (8741, NULL, 6, 'Obelix Village', 'Yogyakarta', 'Jalan Randon, Pandowoharjo, Sleman, Daerah Istimewa Yogyakarta', 'Obelix Village: Taman hiburan di Yogyakarta., Yogyakarta.', -7.687774, 110.373057, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obelix%20Village%20-%20Peternakan%20Bebek%208.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q134776097', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 1),
  (8742, NULL, 6, 'HeHa Sky View', 'Yogyakarta', 'No.2, Patuk, Daerah Istimewa Yogyakarta', 'HeHa Sky View: Taman hiburan di Yogyakarta., Yogyakarta.', -7.849029, 110.477909, NULL, 'Sen–Jum 10.00–21.00; Sab,Min 08.00–21.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/HeHa%20Sky%20View-30.jpg?width=800', '2026-11-04 09:40:56', '2026-11-24 23:32:50', 'wd:Q134776751', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Taman hiburan', 1),
  (8743, NULL, 6, 'Kebun Binatang Ragunan', 'Daerah Khusus Ibukota Jakarta', 'Jalan Anggrek, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Taman Margasatwa Ragunan atau juga disebut Kebun Binatang Ragunan adalah sebuah kebun binatang yang terletak di daerah Ragunan, Pasar Minggu, Jakarta Selatan,  Indonesia. Kebun binatang seluas 140 hektare ini didirikan pada tahun 1864. Di dalamnya terdapat berbagai koleksi yang terdiri dari 295 spesies dan 4040 spesimen.', -6.3115875, 106.8199182, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ragunan%20zoo%20Jakarta%20Indonesia.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q2713110', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 17),
  (8744, NULL, 6, 'Kebun Binatang Surabaya', 'Surabaya', 'Jalan Setail No.1, Darmo, Surabaya, Jawa Timur', 'Kebun Binatang Surabaya (Dialek Arekan: Kebon Binatang Suroboyo, disingkat KBS) adalah salah satu kebun binatang yang populer di Indonesia dan terletak di Surabaya. KBS merupakan kebun binatang yang pernah terlengkap se-Asia Tenggara, di dalamnya terdapat lebih dari 230 spesies satwa yang berbeda yang terdiri lebih dari 2179 ekor satwa. Termasuk di dalamnya satwa langka Indonesia maupun dunia terdiri dari Mamalia, Aves, Reptilia, dan Pisces.', -7.2958333, 112.7361111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Surabaya%20Zoo.JPG?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q4250220', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 10),
  (8745, NULL, 6, 'Taman Safari', 'Cisarua', 'Jalan Alternatif Gunung Mas, Cisarua, Jawa Barat', 'Taman Safari Indonesia adalah taman hiburan satwa yang terletak di Kabupaten Bogor, Jawa Barat, Kabupaten Pasuruan, Jawa Timur, Kabupaten Gianyar, Bali, dan Kota Surakarta, Jawa Tengah. Sebagai bagian dari organisasi yang sama, mereka dikenal sebagai Taman Safari I–II, Bali Safari & Marine Park, dan Solo Safari. Yang paling populer adalah Taman Safari I di lereng Gunung Gede–Pangrango, Kawasan Wisata Puncak, Kecamatan Cisarua, Kabupaten Bogor, Jawa Barat dan Bali Safari and Marine Park di Blahbatuh, Kabupaten Gianyar, Bali.', -6.7166667, 106.95, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Safari%20Indonesia.JPG?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q7680645', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 9),
  (8746, NULL, 6, 'Taman Safari Bali (Bali Safari)', 'Gianyar', 'Blahbatuh, Bali', 'Bali Safari & Marine Park (BSMP) merupakan tempat wisata keluarga berwawasan lingkungan yang terletak di Desa Serongga, Kec. Gianyar, Kabupaten Gianyar, Bali. Bali Safari and Marine Park ini dikelola oleh Taman Safari Group yang juga mengelola Taman Safari Indonesia 1 di Cisarua, Bogor, Jawa Barat dan Taman Safari Indonesia 2 di Prigen, Jawa Timur.', -8.581, 115.3441, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bali%20Safari%20%26%20Marine%20Park.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q4850846', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 5),
  (8747, NULL, 6, 'Batu Secret Zoo', 'Kota Batu', 'Jalan Raya Oro-Oro Ombo, Lowokwaru, Kota Batu, Jawa Timur', 'Batu Secret Zoo merupakan tempat wisata dan kebun binatang modern yang terletak di Kota Batu, Jawa Timur. Batu Secret Zoo yang berada di tanah seluas 14 hektare tersebut merupakan bagian dari Jatim Park 2, selain Pohon Inn dan Museum Satwa. Beberapa koleksi hewan dari berbagai habitat yang sebagian besar berasal dari Asia dan Afrika dapat ditemukan di kebun binatang ini, antara lain singa putih, kijang afrika, burung macau, dan bermacam-macam reptil.', -7.884, 112.525, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batu%20Secret%20Zoo%2C%20Batu-East%20Java%2C%20Indonesia%202.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q4251753', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 3),
  (8748, NULL, 6, 'Solo Safari', 'Surakarta', 'Jalan Ki Hadjar Dewantara No.109, Jebres, Surakarta, Jawa Tengah', 'Solo Safari (nama sebelumnya: Taman Satwa Taru Jurug Surakarta) adalah salah satu objek wisata di Kota Surakarta, Jawa Tengah yang dibangun pada tahun 1878. Di Solo Safari, terdapat berbagai spesies hewan dan tumbuhan. Dengan konsep wisata alam, jalan-jalan yang ada di dalam taman dikelilingi pohon-pohon besar dan rindang.', -7.5639563, 110.8586044, NULL, 'Setiap hari 09.00–16.30', NULL, '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q12490158', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 3),
  (8749, NULL, 6, 'Taman Margasatwa dan Budaya Kinantan', 'Sumatera Barat', 'Jalan Pemuda, Tembok, Bukittinggi, Sumatera Barat', 'Taman Margasatwa dan Budaya Kinantan atau lebih dikenal dengan nama Kebun Binatang Bukittinggi terletak di atas Bukit Cubadak Bungkuak, Bukittinggi, Sumatera Barat, Indonesia. Kebun binatang ini merupakan salah satu kebun binatang tertua yang ada di Indonesia dan satu-satunya di Sumatera Barat, dengan koleksi hewan terlengkap di Pulau Sumatra.\nDalam kompleks kebun binatang, terdapat Museum Rumah Adat Baanjuang dan Museum Zoologi.', -0.30022, 100.36955, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Margasatwa%20dan%20Budaya%20Kinantan-34.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q12518848', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 3),
  (8750, NULL, 6, 'Kebun Binatang Pematang Siantar', 'Pematang Siantar', 'Jalan Gunung Simanuk-Manuk, Siantar Barat, Kota Pematangsiantar', 'Taman Hewan Pematangsiantar (THPS) atau sebelumnya dikenal juga sebagai Kebun Binatang Siantar dan Kebun Binatang Pematangsiantar, adalah kebun binatang yang terletak di kota Pematangsiantar. Kebun binatang ini resmi dibuka untuk umum pada tanggal 27 November 1936 dengan luas areal sekitar 4.5 hektare. THPS berlokasi di Jalan Gunung Simanuk-Manuk Kota Pematangsiantar, Provinsi Sumatera Utara.', 2.9526171, 99.0588213, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Hewan%20Pematang%20Siantar%20%282%29.JPG?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q12490160', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 2),
  (8751, NULL, 6, 'Museum Zoologi', 'Teladan', 'Jalan Gunung Simanuk-Manuk, Siantar Barat, Kota Pematangsiantar', 'Museum Zoologi (dikenal juga sebagai Taman Hewan Pematang Siantar/THPS) adalah sebuah museum yang bertujuan untuk memajukan pengetahuan tentang keanekaragaman hayati, khususnya fauna, kepada masyarakat. Museum ini bertempat di Jl. Kapten Sitorus No.', 2.9525769, 99.0593792, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Hewan%20Pematang%20Siantar%20%282%29.JPG?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q136396469', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 1),
  (8752, NULL, 6, 'Taman Satwa Jhonlin Lestari', 'Indonesia', NULL, 'Taman Satwa Jhonlin Lestari adalah kawasan konservasi flora dan fauna yang difungsikan sebagai lembaga penangkaran satwa liar di Kabupaten Tanah Bumbu, Kalimantan Selatan. Kawasan ini berperan penting dalam pelestarian keanekaragaman hayati, baik melalui upaya penyelamatan satwa dilindungi maupun pengembangbiakan spesies tertentu. Selain itu, taman ini juga difungsikan sebagai pusat edukasi konservasi bagi masyarakat, lembaga pendidikan, dan pemangku kepentingan lingkungan di wilayah setempat.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burung%20Kakatua.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q136008629', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 1),
  (8753, NULL, 6, 'Medan Zoo', 'Sumatera Utara', 'Jalan Pintu Air IV, Medan Tuntungan, Kota Medan, Sumatera Utara', 'Medan Zoo adalah kebun binatang di Sumatera Utara.', 3.482323, 98.644674, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/LailanAmelia-13Mei2020.jpg?width=800', '2026-11-04 09:41:02', '2026-11-24 23:32:50', 'wd:Q136687552', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Kebun binatang', 1),
  (9170, NULL, 4, 'Bentara Budaya Jakarta', 'Jakarta', 'Jalan Palmerah Selatan, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Bentara Budaya Jakarta adalah sebuah lembaga kebudayaan yang berlokasi di Jalan Palmerah Selatan 17, Jakarta. Museum ini buka dari Senin hingga Jumat dari pukul 08.00 s/d 17.00 WIB. Sedangkan, hari besar/libur museum ini tutup. Untuk masuk ke dalam museum ini, tidak ada pemungutan biaya.', -6.2102, 106.7954, NULL, ' 8 AM–jam 5 sore', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bentara%20Budaya%20di%20Palmerah%20Jakarta.jpg?width=800', '2026-11-04 10:29:15', '2026-11-24 23:32:50', 'wd:Q17999302', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9179, NULL, 4, 'Museum Kretek', 'Jawa Tengah', 'Jalan Sentot Prawidorejo, Getas Pejaten, Kudus, Jawa Tengah', 'Museum Kretek (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦏꦿꦺꦠꦺꦏ꧀, translit. Musiyum Krètèk) adalah sebuah museum yang terletak di Kudus, Jawa Tengah, Indonesia.', -6.82655, 110.83865, 4000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20kretek%20-%20panoramio.jpg?width=800', '2026-11-04 10:29:15', '2026-11-24 23:32:50', 'wd:Q13095249', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9180, NULL, 4, 'Museum Semarajaya', 'Klungkung', 'Jalan Untung Surapati, Semarapura Kelod, Klungkung, Bali', 'Museum Semarajaya adalah museum sejarah yang terletak di Semarapura, Kabupaten Klungkung, Provinsi Bali, Indonesia. Peresmian Museum Semarajaya diadakan pada tanggal 28 April 1992 oleh Rudini selaku Menteri Dalam Negeri Republik Indonesia. Bangunan Museum Semarajaya menerapkan gabungan antara gaya arsitektur Belanda dan Bali.', -8.5355278, 115.4026667, 50000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/ID-bali-klungkung-mus-semarajaya.jpg?width=800', '2026-11-04 10:29:15', '2026-11-24 23:32:50', 'wd:Q14475767', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9352, NULL, 7, 'Masjid Agung Ats-Tsauroh Serang', 'Serang', 'Jalan Ki Fatoni, Serang, Banten', 'Masjid Agung Ats-Tsauroh Serang, atau juga dikenal dengan Masjid Agung Serang adalah sebuah kompleks masjid bersejarah yang berada di kota Serang, Banten, Indonesia. Masjid ini awalnya dibangun pada tahun 1870, atas perintah umat Muslim setempat, yang kemudian diresmikan pada tanggal 14 Februari 1872. Masjid ini lalu ditetapkan sebagai salah satu masjid tertua yang masih berdiri di Indonesia.', -6.1168, 106.157, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Mosque%20of%20Serang.jpg?width=800', '2026-11-04 10:29:48', '2026-11-24 23:32:50', 'wd:Q106644599', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (9353, NULL, 7, 'Masjid Jami Kampung Baru Inpak', 'Jakarta', 'Jalan Pekojan I, Tambora, Jakarta Barat', 'Masjid Jami Kampung Baru Inpak, juga dikenal sebagai Masjid Kampung Baru atau Masjid Bandengan adalah salah satu masjid tertua di Jakarta, Indonesia. Masjid ini terletak di Jalan Bandengan Selatan, Pekojan, Tambora, Jakarta, di dekat Masjid Al-Anshor. Ini adalah salah satu masjid yang dibangun oleh Muslim saudagar dari India, yang digunakan untuk bepergian dan tinggal di Batavia.', -6.136573, 106.802767, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Bandengan%20Atau%20Masjid%20Kampung%20Baru%20-%20panoramio.jpg?width=800', '2026-11-04 10:29:48', '2026-11-24 23:32:50', 'wd:Q38069209', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9354, NULL, 7, 'Masjid Keramat Banua Halat', 'Tapin', NULL, 'Masjid Al-Mukarramah atau juga dikenal sebagai Masjid Keramat Banua Halat adalah sebuah masjid bersejarah yang berlokasi di Provinsi Kalimantan Selatan, Indonesia. Secara administratif, masjid ini berada di desa Banua Halat Kiri, Kecamatan Tapin Utara, Kabupaten Tapin, masjid ini juga merupakan salah satu situs dari Taman Bumi Global UNESCO Meratus.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Keramat%20Banua%20Halat.jpg?width=800', '2026-11-04 10:29:48', '2026-11-24 23:32:50', 'wd:Q12497309', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9381, NULL, 1, 'Pantai Tanjung Tinggi', 'Belitung', 'Belitung, Kepulauan Bangka Belitung', 'Tanjung tinggi adalah pantai yang diapit oleh dua semenanjung, yaitu tanjung Kelayang dan tanjung Pendam. Nama tanjung tinggi diambil dari kata tanjung yang artinya semenanjung dan tinggi yang artinya pantai yang memiliki bebatuan yang tinggi. Pantai Tanjung Tinggi merupakan salah satu tempat wisata di pulau Belitung.', -2.551795, 107.713777, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Tanjung%20Tinggi%202026-07-18.jpeg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q19747015', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 2),
  (9382, NULL, 1, 'Thomas Beach', 'Pecatu', 'Jalan Labuan Sait- Pecatu, Kuta Selatan, Bali', 'Thomas Beach adalah pantai di Pecatu.', -8.812375, 115.0981241, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thomas%20beach%20%2848976502201%29.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q124344634', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9383, NULL, 1, 'Atuh Beach', 'Pejukutan', 'Nusa Penida, Bali', 'Atuh Beach adalah pantai di Pejukutan.', -8.7732, 115.62168, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Atuh%20Beach%2C%20Nusa%20Penida%20Bali.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q124346693', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9384, NULL, 1, 'Yeh Leh Beach', 'Jembrana', 'Jalan Raya Denpasar-Gilimanuk, Pekutatan, Bali', 'Yeh Leh Beach adalah pantai di Jembrana.', -8.4666546, 114.9150899, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yeh%20Leh%20Beach%20-%20Bali.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q124347585', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9385, NULL, 1, 'Nyang Nyang Beach', 'Pecatu', 'Kuta Selatan, Bali', 'Nyang Nyang Beach adalah pantai di Pecatu.', -8.83968, 115.09428, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jl.%20Batu%20Nunggalan%2C%20Pecatu%2C%20Kuta%20Sel.%2C%20Kabupaten%20Badung%2C%20Bali%2C%20Indonesia%20-%20panoramio%20%281%29.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q124394607', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9386, NULL, 1, 'Pandan Beach', 'Nusa Penida', 'Nusa Penida, Bali', 'Pandan Beach adalah pantai di Nusa Penida.', -8.71942, 115.45592, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Live%20is%20a%20beach%20%282728109671%29.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q125470006', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9387, NULL, 1, 'Muisne Beach', 'Muisne', 'Isidro Ayora, Muisne, Esmeraldas', 'Muisne Beach adalah pantai di Muisne.', 0.6036216, -80.0263546, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muisne%20Beach%20%282544677857%29.jpg?width=800', '2026-11-24 09:43:48', '2026-11-24 23:32:50', 'wd:Q125521648', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pantai', 0),
  (9399, NULL, 1, 'Pulau Komodo', 'Manggarai Barat', 'Kampung Komodo, Manggarai Barat, Nusa Tenggara Timur', 'Pulau Komodo adalah sebuah pulau yang terletak di Kepulauan Nusa Tenggara, berada di sebelah timur Pulau Sumbawa, yang dipisahkan oleh Selat Sape. Pulau Komodo dikenal sebagai habitat asli hewan komodo. Pulau ini dapat dicapai melalui Labuan Bajo dengan menggunakan kapal laut.', -8.576942, 119.451111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Komodo%20Island%20north%20aerial.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q107640', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 66),
  (9403, NULL, 1, 'Pulau Ambon', 'Maluku', NULL, 'Pulau Ambon merupakan pulau yang terletak di Kepulauan Maluku, di sebelah Pulau Seram dan sejajar dengan Kepulauan Lease. Ambon adalah pulau terpadat di Kepulauan Maluku dan di pulau inilah terdapat Kota Ambon, ibu kota Provinsi Maluku, sekaligus permukiman terbesar di kepulauan itu.', -3.6147194, 128.1658306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/USNS%20Mercy%20off%20the%20coast%20of%20Ambon%2C%20Indonesia.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q219608', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 62),
  (9408, NULL, 1, 'Pulau Ternate', 'Ternate', 'Ternate, Maluku Utara', 'Pulau Ternate: Pulau di Kota Ternate, Maluku Utara, Ternate.', 0.8094417, 127.3413889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ternate.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q333483', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 46),
  (9409, NULL, 1, 'Pulau Tidore', 'Tidore Kepulauan', 'Tidore Kepulauan, Maluku Utara', 'Pulau Tidore adalah sebuah pulau berukuran kecil yang berada dalam wilayah Kota Tidore Kepulauan, Provinsi Maluku Utara, Indonesia. Pembentukan pulau Tidore terjadi akibat aktivitas vulkanik dari gunung Kie Matubu. Penduduk asli di Pulau Tidore diperkirakan adalah orang Alifuru.', 0.686389, 127.410831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tidore%20Island%20Indonesia%20Daytime.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q12506955', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 45),
  (9411, NULL, 1, 'Pulau Nusapenida', 'Klungkung', NULL, 'Nusa Penida adalah sebuah pulau (nusa) bagian dari Kabupaten Klungkung, Bali, Indonesia yang terletak di sebelah tenggara Bali yang dipisahkan oleh Selat Badung. Di dekat pulau ini terdapat juga pulau-pulau kecil lainnya yaitu Nusa Ceningan dan Nusa Lembongan.', -8.7333333, 115.5333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kelingking%20Beach%20%28T-Rex%20Bay%29%20of%20Nusa%20Penida%2C%20Bali%20%282025%29%20-%20img%2011.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1520301', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 42),
  (9416, NULL, 1, 'Pulau Samosir', 'Samosir', 'Samosir, Sumatera Utara', 'Samosir (Surat Batak: ᯇᯮᯞᯬ ᯘᯔᯬᯘᯒᯪ᯲, translit. Pulo Samosir) adalah sebuah pulau vulkanik buatan pemerintah kolonial Belanda pada tahun 1906 setelah selesainya proyek Tano Ponggol. Samosir yang terletak di tengah-tengah Danau Toba di Kabupaten Samosir, Provinsi Sumatera Utara yang baru dimekarkan pada tahun 2003 dari bekas Kabupaten Toba Samosir.', 2.5833333, 98.8166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/HAMPARAN%20BUKIT%20DAN%20LUASNYA%20DANAU%20TOBA.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1369204', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 39),
  (9419, NULL, 1, 'Pulau Bawean', 'Gresik', 'Batusendi, Gresik, Jawa Timur', 'Bawean adalah pulau yang terletak di Laut Jawa, sekitar 135 kilometer sebelah utara Kota Gresik. Secara administratif, pulau ini termasuk ke dalam wilayah Kabupaten Gresik, Jawa Timur. Pasukan VOC menguasai pulau ini pada tahun 1743.', -5.7921028, 112.6540111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bawean1.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q812044', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 37),
  (9424, NULL, 1, 'Pulau Weh', 'Sabang', 'Sabang, Aceh', 'Pulau Weh (atau We) atau dikenal juga dengan Pulau Sabang adalah pulau vulkanik kecil yang terletak di barat laut Pulau Sumatra. Pulau ini pernah terhubung dengan Pulau Sumatra, tetapi kemudian terpisah oleh laut setelah meletusnya gunung berapi terakhir kali pada zaman Pleistosen. Pulau ini terletak di Laut Andaman.', 5.834853, 95.313267, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Weh%20Island.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1048813', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 35),
  (9428, NULL, 1, 'Pulau Rhun', 'Maluku Tengah', NULL, 'Pulau Rhun: Pulau di Kabupaten Maluku Tengah, Maluku, Maluku Tengah.', -4.558056, 129.681111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Run%20and%20Nailaka%20%28Banda%20Islands%29.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1072848', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 30),
  (9429, NULL, 1, 'Pulau Rinca', 'Nusa Tenggara Timur', 'Kampung Rinca, Manggarai Barat, Nusa Tenggara Timur', 'Pulau Rinca adalah sebuah pulau yang terletak di Kepulauan Nusa Tenggara. Pulau Rinca beserta Pulau Komodo dan Pulau Padar merupakan kawasan Taman Nasional Komodo yang dikelola oleh Pemerintah Pusat. Pulau Rinca berada di sebelah barat Pulau Flores, yang dipisahkan oleh Selat Molo.', -8.6966667, 119.6919417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rinca2.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1164773', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 30),
  (9432, NULL, 1, 'Pulau Enggano', 'Bengkulu Utara', 'Bengkulu Utara, Bengkulu', 'Pulau Enggano adalah salah satu pulau terluar Indonesia yang terletak di Samudra Hindia. Pulau ini termasuk dalam wilayah administratif Kabupaten Bengkulu Utara, Provinsi Bengkulu, dan merupakan bagian dari Kecamatan Enggano. Pulau Enggano berada di sebelah barat daya dari Kota Bengkulu dengan koordinat 05° 23′ 21″ LS, 102° 24′ 40″ BT. Berdasarkan data Badan Pusat Statistik tahun 2020, jumlah penduduk Enggano sebanyak 4.035 jiwa.', -5.4, 102.25, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumatra-Enggano.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1342338', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 29),
  (9433, NULL, 1, 'Pulau Sebatik', 'Nunukan', 'Nunukan, Kalimantan Utara', 'Pulau Sebatik adalah pulau yang berada di perbatasan antara Indonesia dan Malaysia. Secara administratif, pulau ini dikuasai oleh 2 negara, Sebatik bagian utara dikuasai oleh Kerajaan Malaysia, dan Sebatik bagian selatan dikuasai Republik Indonesia. \nPemisahan wilayah Sebatik Indonesia dengan Sebatik Malaysia menggunakan titik koordinat 4°10\' sesuai dengan perjanjian Konvensi London 1891, di mana semua wilayah Sebatik yang dikuasai oleh Belanda diambil oleh Indonesia, dan semua wilayah Sebatik yang di kuasai oleh Inggris diambil oleh Malaysia.', 4.143247, 117.787403, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sabah%20Tawau%20CowieBay%20Sebatik.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q737814', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 28),
  (9434, NULL, 1, 'Pulau Pantar', 'Alor', NULL, 'Pulau Pantar merupakan salah satu dari dua pulau utama di Kabupaten Alor, Provinsi Nusa Tenggara Timur, Indonesia. Pulau Pantar sendiri dibagi menjadi 6 kecamatan:\n\nKecamatan Pantar (Kabir)\nKecamatan Pantar Tengah (Muriabang)\nKecamatan Pantar Barat Laut (Marica / Wolu)\nKecamatan Pantar Barat (Baranusa)\nKecamatan Pantar Barat Daya (Puntaru)\nKecamatan Pantar Timur (Bakalang).\nPulau ini dibatasi oleh Laut Flores dan Laut Banda di sebelah utara, Selat Pantar di timur, Selat Ombai di selatan, serta Selat Alor di barat.', -8.421111, 124.133889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Tenggara%20Timur2.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q974980', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 28),
  (9436, NULL, 1, 'Pulau Batanta', 'Raja Ampat', 'Raja Ampat, Papua Barat Daya', 'Batanta merupakan salah satu dari empat pulau terbesar di kepulauan Raja Ampat di provinsi Papua Barat Daya . pulau ini memiliki total luas 453 km ² . Pulau-pulau utama lainnya di kepulauan ini adalah Salawati, Misool dan Waigeo.', -0.8598833, 130.66145, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batanta%20Island%2C%20ID%2C%20Sentinel-2.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q810729', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 27),
  (9437, NULL, 1, 'Pulau Sabu', 'Kupang', NULL, 'Sawu (Sabu; Savu) adalah nama sebuah pulau yang terletak di sebelah selatan perairan Laut Sawu di sebelah timur Pulau Sumba dan sebelah barat Pulau Rote. Secara administratif, pulau ini termasuk wilayah Kabupaten Sabu Raijua, Provinsi Nusa Tenggara Timur, Indonesia. Luasnya adalah 414 km².', -10.5422194, 121.8466667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Tenggara%20Timur2.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1469472', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 27),
  (9438, NULL, 1, 'Pulau Anak Krakatau', 'Lampung Selatan', NULL, 'Anak Krakatau adalah sebuah pulau vulkanik di Indonesia. Pada tanggal 29 Desember 1927, Anak Krakatau pertama kali muncul dari kaldera yang terbentuk akibat letusan eksplosif Krakatau pada tahun 1883 yang menghancurkan pulau Krakatau. Aktivitas letusan yang bersifat sporadis telah terjadi di lokasi tersebut sejak akhir abad ke-20.', -6.097919, 105.426364, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesia%2C%20Sunda%20Straits.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2205302', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 27),
  (9440, NULL, 1, 'Pulau Adonara', 'Flores Timur', 'Flores Timur, Nusa Tenggara Timur', 'Adonara adalah sebuah pulau yang terletak di Kepulauan Nusa Tenggara, yakni di sebelah timur Pulau Flores. Luas wilayahnya 509 km², dan titik tertingginya 1.676 m. Berdasarkan data Badan Pusat Statistik Kabupaten Flores Timur, populasi Adonara tercatat sekitar 119.000 jiwa dengan kepadatan sekitar 220 jiwa per kilometer persegi.', -8.333331, 123.166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Tenggara%20Timur2.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q366088', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 25),
  (9442, NULL, 1, 'Pulau Numfor', 'Biak Numfor', 'Biak Numfor, Papua', 'Pulau Numfor (ditulis juga: Numfoor, Noemfoor, Noemfoer) merupakan sebuah pulau yang berada di Kepulauan Biak dan terletak pada sebelah utara Pulau Papua. Secara administratif, Pulau Numfor termasuk wilayah Kabupaten Biak Numfor. Terletak di Teluk Cendrawasih yang berjarak 50 km sebelah barat Biak dan Supiori dan 70 km sebelah timur dari kota pelabuhan Manokwari.', -1.038256, 134.888575, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schouten%20Islands%20%28IN%29%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1632717', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 24),
  (9443, NULL, 1, 'Pulau Sipora', 'Kepulauan Mentawai', NULL, 'Sipora adalah pulau yang terletak di lepas pantai Sumatra di Indonesia. Pulau ini merupakan pulau terkecil dan paling berkembang dari empat pulau di Kepulauan Mentawai dengan luas hanya 845 km². Ibu kota Kabupaten Kepulauan Mentawai, Tua Pejat, terletak di Sipora.', -2.187219, 99.646111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mentawai%20Islands%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q761722', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9444, NULL, 1, 'Pulau Tarakan', 'Tarakan', 'Tarakan, Kalimantan Utara', 'Tarakan adalah pulau di Kalimantan Utara, Indonesia. Pulau berawa-rawa ini terletak di Laut Sulawesi, di lepas pantai timur laut Kalimantan. Pulau ini memiliki luas sebesar 657,33 km² di mana Kota Tarakan berada.', 3.362803, 117.597017, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tarakan%20Island%20Kalimantan%20.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q137796', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9445, NULL, 1, 'Pulau Solor', 'Flores Timur', 'Watobuku, Nusa Tenggara Timur', 'Pulau Solor adalah sebuah pulau yang terletak di Kepulauan Nusa Tenggara. Pulau ini terletak di sebelah timur dari Pulau Flores. Pulau ini dibatasi oleh Selat Lowotobi di barat, Selat Solor di utara, Selat Lamakera di timur, serta Laut Sawu di selatan.', -8.476389, 122.983889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20-%20Solor.PNG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1421494', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9447, NULL, 1, 'Pulau Pagai Utara', 'Kepulauan Mentawai', 'Sumatera Barat', 'Pagai Utara adalah salah satu pulau di Kepulauan Mentawai di lepas pantai barat Sumatra di Indonesia. Pulau ini berada di sebalah selatan Pulau Sipora dan di sebelah utara Pulau Pagai Selatan.\nKota Sikakap digunakan sebagai pusat operasi bantuan berkaitan dengan gempa bumi di Mentawai pada Oktober 2010.', -2.711389, 100.091942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mentawai%20Islands%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1578700', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9448, NULL, 1, 'Nusa Lembongan', 'Klungkung', 'Nusa Penida, Bali', 'Pulau Lembongan atau dalam bahasa Bali disebut "Nusè Lémbongan" adalah sebuah pulau kecil terletak yang berdekatan dengan Nusa Ceningan dan 2 km di sebelah barat laut Nusa Penida terletak di Selat Badung sebelah tenggara Pulau Bali. Pulau yang memiliki panjang 4,6 km dan lebar 1-1,5 km ini berada kira-kira 11 km di sebelah tenggara Bali. Secara administratif, pulau ini termasuk wilayah Kabupaten Klungkung, Provinsi Bali, Indonesia.', -8.6788889, 115.45, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Lembongan%20Dream%20Beach.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1970352', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9449, NULL, 1, 'Pulau Damar', 'Maluku Barat Daya', NULL, 'Pulau Damar adalah sebuah pulau yang terletak di bagian utara Kepulauan Barat Daya bagian dari provinsi Maluku, tepatnya di kecamatan Damer. Pulau ini terdapat tujuh desa yang terkonsentrasi di pesisir utara dan barat pulau. Topografi kawasan ini bergelombang di bagian tepi hingga bergunung rendah di bagian tengah.', -7.135, 128.613889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wurlali.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q19745747', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (9450, NULL, 1, 'Pulau Saparua', 'Maluku Tengah', 'Saparua, Maluku Tengah, Maluku', 'Saparua adalah salah satu pulau yang ada di Kepulauan Maluku. Bersama dengan Haruku, Nusalaut dan pulau-pulau kecil di sekitarnya, Saparua merupakan bagian dari Pulau-Pulau Lease, yang merupakan Gugus Pulau VII dalam konsep pembangunan ekonomi Maluku.', -3.554167, 128.666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ambon%20and%20Lease%20Islands%20%28Uliasers%29%20de.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1584814', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 22),
  (9451, NULL, 1, 'Pulau Selayar', 'Kepulauan Selayar', NULL, 'Pulau Selayar (Ejaan Van Ophuijsen: Saleijer) adalah nama sebuah pulau kecil di Indonesia, namun merupakan pulau terbesar yang berada di gugusan Kepulauan Selayar, perairan Laut Flores dan secara administratif masuk pada wilayah Kabupaten Kepulauan Selayar, Sulawesi Selatan, Indonesia. Secara astronomis, pulau ini terletak di titik koordinat 6°5′24.000″LS, 120°30′0.000″BT. Di pulau ini terdapat ibu kota Kabupaten Kepulauan Selayar, yaitu Kota Benteng dan beberapa Kecamatan, antara lain Kecamatan Benteng, Kecamatan Bontoharu, Kecamatan Bontomanai, Kecamatan Bontomatene, Kecamatan Bontosikuyu, dan Kecamatan Buki. Sarana transportasi dari luar yang paling dekat adalah Pelabuhan penyeberangan Pamatata yang terletak di Desa Pamatata, Kecamatan Bontomatene, Kabupaten Kepulauan Selayar.', -6.09, 120.5, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Selayar%2C%20fishing%20boat%20%286822982688%29.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2121185', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 22),
  (9452, NULL, 1, 'Pulau Ambalau', 'Buru Selatan', NULL, 'Pulau Ambelau adalah sebuah pulau vulkanik yang terletak di Laut Banda di kepulauan Maluku. Pulau ini terletak di Kecamatan Ambelau di Kabupaten Buru Selatan, Provinsi Maluku, Indonesia. Pusat administrasinya terletak Wailua, yang terletak di sebelah selatan pulau.', -3.8547194, 127.1930556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ambelau.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q19731126', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 22),
  (9453, NULL, 1, 'Pulau Sulabesi', 'Kepulauan Sula', NULL, 'Pulau Sulabesi (dikenal pula sebagai Pulau Sula Besi atau secara historis dinamai Pulau Sanana) adalah sebuah pulau utama di gugusan Kepulauan Sula, Provinsi Maluku Utara, Indonesia. Pulau ini membentang sepanjang 45 kilometer dari utara ke selatan dan terletak di sebelah selatan Pulau Mangole, dipisahkan oleh perairan Selat Mangoli.\nSecara administratif, Pulau Sulabesi terbagi ke dalam enam wilayah kecamatan dan merupakan pusat administrasi, perdagangan, serta kebudayaan terbesar di Kabupaten Kepulauan Sula, dengan ibu kota kabupaten yang berkedudukan di Sanana.', -2.2855556, 125.9663889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/UvA-BC%20300.115%20-%20Siboga%20-%20strand%20bij%20de%20kampong%20Sanana%20op%20het%20eiland%20Sulabesi.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q48767551', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 21),
  (9454, NULL, 1, 'Pulau Nusakambangan', 'Cilacap', 'Kampung Laut, Jawa Tengah', 'Nusakambangan adalah sebuah pulau di Cilacap yang lebih dikenal sebagai tempat terletaknya beberapa Lembaga Pemasyarakatan berkeamanan tinggi di Indonesia. Secara Geografis, pulau ini masuk dalam wilayah administratif Kabupaten Cilacap, tepatnya di Kecamatan Cilacap Selatan dan tercatat dalam daftar pulau terluar Indonesia. Sementara itu, secara pengelolaan pulau ini berada di bawah yuridiksi Kementerian Hukum (mulai 21 Oktober 2024).', -7.726619, 108.862403, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusakambangan%20map.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1782781', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 20),
  (9455, NULL, 1, 'Pulau Supiori', 'Supiori', NULL, 'Pulau Supiori adalah salah satu pulau di wilayah teluk Cenderawasih, provinsi Papua, Indonesia. Pulau ini terletak di barat laut Pulau Biak.\nPulau biak dan pulau Supiori dipisahkan oleh selat sorendiweri yang lebarnya kurang lebih 100 meter.', -0.728889, 135.568889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schouten%20Islands%20%28IN%29%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2084780', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 20),
  (9456, NULL, 1, 'Pulau Bunaken', 'Manado', 'Bunaken Kepulauan, Manado, Sulawesi Utara', 'Bunaken adalah sebuah pulau seluas 8,08 km² di Teluk Manado, yang terletak di utara pulau Sulawesi, Indonesia. Pulau ini merupakan bagian dari kota Manado, ibu kota provinsi Sulawesi Utara, Indonesia. Pulau Bunaken dapat ditempuh dengan kapal cepat (speed boat) atau kapal sewaan dengan perjalanan sekitar 30 menit dari pelabuhan kota Manado.', 1.622986, 124.765242, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bunaken2.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2144266', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 20),
  (9459, NULL, 1, 'Pulau Romang', 'Kepulauan Maluku', 'Jerusu, Maluku Barat Daya, Maluku', 'Romang adalah sebuah pulau di Kepulauan Barat Daya, Indonesia, yang terletak di 7.5833333°S 127.4333333°E﻿ / -7.5833333; 127.4333333, timur dari Pulau Wetar. Nama alternatif yang dipakai adalah Roma, Romonu dan Fataluku.', -7.580269, 127.399117, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Romang%20Island%20NASA.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q650971', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 19),
  (9460, NULL, 1, 'Pulau Kisar', 'Maluku Barat Daya', 'Oirata Timur, Maluku Barat Daya, Maluku', 'Pulau Kisar adalah salah satu pulau terluar wilayah Indonesia yang terletak di perairan Selat Wetar dan berbatas pada sebelah selatan dengan perairan ujung timur Pulau Timor yang masuk bagian negara Timor Leste. Pulau ini merupakan bagian dari wilayah administrasi pemerintah Kabupaten Maluku Barat Daya, provinsi Maluku. Secara biogeografi, pulau Kisar termasuk dalam kawasan Wallacea.', -8.0616667, 127.1858333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barat%20Daya%20Islands%20de.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1743695', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 19),
  (9461, NULL, 1, 'Pulau Kabaena', 'Sulawesi Tenggara', 'Bombana, Sulawesi Tenggara', 'Pulau Kabaena atau Tokotua adalah salah satu pulau di wilayah Kabupaten Bombana, Provinsi Sulawesi Tenggara, Indonesia. Untuk mencapai pulau ini harus ditempuh dengan jalur laut dari pelabuhan di Kasipute ke Dongkala, Kabaena Timur. Lama perjalanan yang ditempuh yaitu sekitar 2 jam dengan kapal jet atau sekitar 4 jam dengan kapal motor atau ferry .', -5.25, 121.9166667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buton%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q12506769', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 19),
  (9462, NULL, 1, 'Pulau Padar Besar', 'Manggarai Barat', NULL, 'Pulau Padar adalah pulau ketiga terbesar di kawasan Taman Nasional Komodo, Nusa Tenggara Timur (NTT) setelah Pulau Komodo dan Pulau Rinca. Pulau ini relatif lebih dekat ke Pulau Rinca daripada ke Pulau Komodo, yang dipisahkan oleh Selat Lintah. Di sekitar pulau ini terdapat pula tiga atau empat pulau kecil.', -8.6563889, 119.5719417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Padar%201.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1134717', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9463, NULL, 1, 'Pulau Karakelang', 'Kepulauan Talaud', 'Sulawesi Utara', 'Pulau Karakelang adalah pulau utama di Kepulauan Talaud yang berada di bagian timur dari laut Sulawesi, Indonesia. \nLuas wilayah pulau ini adalah 846 km2 (327 mil2) dengan kota terbesarnya adalah Melonguane di daerah pantai barat, yang merupakan pusat administrasi Kabupaten Kepulauan Talaud.', 4.306992, 126.806792, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/UvA-BC%20300.223%20-%20Siboga%20-%20Beo%20op%20het%20eiland%20Karakelang.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q687975', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9464, NULL, 1, 'Pulau Siau', 'Sulawesi Utara', 'Bumbiha, Kepulauan Siau Tagulandang Biaro, Sulawesi Utara', 'Pulau Siau merupakan pulau di Kabupaten Kepulauan Siau Tagulandang Biaro (SITARO), Provinsi Sulawesi Utara, Indonesia dengan letak geografis 02° 45\' 00\'\' LU dan 125° 23\' 59\'\' BT. Pulau ini memiliki gunung berapi yang masih aktif yaitu gunung karangetang. Ibu kota Kabupaten Kepulauan Siau Tagulandang Biaro yaitu Ondong Siau terdapat di pulau ini.', 2.7297472, 125.3828806, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Tamata%20%26%20Gunung%20Karangetang%20Kab.%20SITARO.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1670781', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9465, NULL, 1, 'Pulau Panaitan', 'Pandeglang', 'Pandeglang, Banten', 'Panaitan (Sunda: ᮕᮔᮄᮒᮔ᮪), adalah sebuah pulau yang terletak di Selat Sunda, dekat Ujung Kulon. Antara Pulau Panaitan dan Pulau Jawa dibatasi oleh Selat Panaitan. Secara administratif, pulau ini termasuk dalam wilayah Kabupaten Pandeglang, Banten.', -6.591267, 105.209033, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lovely%20Sunset%20Panaitan%20Island%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1861129', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9467, NULL, 1, 'Pulau Sangihe', 'Kepulauan Sangihe', 'Kepulauan Sangihe, Sulawesi Utara', 'Pulau Sangihe: Pulau di Kabupaten Kepulauan Sangihe, Sulawesi Utara, Kepulauan Sangihe.', 3.554753, 125.548894, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Jonge%20vrouwen%20van%20het%20eiland%20Sangihe%20bij%20Noord-Celebes%20TMnr%2010005697.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q3100064', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9468, NULL, 1, 'Nusa Ceningan', 'Klungkung', 'Nusa Penida, Bali', 'Nusa Ceningan adalah sebuah pulau kecil yang merupakan salah bagian satu pulau dari tiga gugusan kepulaun di Nusa Penida. Berdasarkan hasil pemetaan partisifatif yang pernah dilakukan oleh masyarakat bekerja beberapa lembaga LSM pada tahun 2000, luas pulau Ceningan adalah 300,6 Ha, yang terdiri dari 2 Dusun (sekarang banjar Dinas) yaitu Dusun Ceningan Kawan dan Dusun Ceningan Kangin, dengan jumlah penduduk 1523 jiwa dari 300 KK, yang tersebar di 6 Banjar Adat yaitu Banjar Adat Parangan tengah, Ambentiying, Ceningan Tengah, Anggrek, Batumelawang dan Gili Mekarnadi.\n\nSecara geografis, Ceningan merupakan Bagian dari Wilayah Desa Lembongan, Kecamatan Nusa Penida, Kabupaten Klungkung.', -8.7, 115.4513889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/NusaCeningan2009.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q3315165', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (9470, NULL, 1, 'Gili Trawangan', 'Lombok Utara', 'Tanjung, Nusa Tenggara Barat', 'Gili Trawangan adalah salah satu dari Tiga Gili yang ada di bagian barat laut Pulau Lombok, bersama dengan Gili Air dan Gili Meno atau yang juga disebut sebagai Pesona Tiga Gili \'Tramena\' (Trawangan, Meno, dan Air). Secara administrasi, Gili Trawangan berada di Kecamatan Pemenang, Kabupaten Lombok Utara, Nusa Tenggara Barat. Jumlah penduduk Gili Trawangan adalah 2.089 orang dengan jumlah laki-laki sebesar 1.085 dan jumlah perempuan sebesar 1.004.', -8.350886, 116.036389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gili%20Trawangan%20from%20Gili%20Meno.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1524363', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (9471, NULL, 1, 'Pulau Wawonii', 'Konawe', NULL, 'Wawonii adalah sebuah pulau di Laut Banda, Indonesia, tepatnya di Provinsi Sulawesi Tenggara. Wawonii sendiri merupakan Etnis atau suku yang berada di Sulawesi Tenggara. Pulau Wawonii luas 715 km².', -4.1138889, 123.1022194, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20wawonii%203.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2732929', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (9472, NULL, 1, 'Pulau Palue', 'Sikka', 'Nitung Lea, Sikka, Nusa Tenggara Timur', 'Pulau Palue adalah sebuah pulau vulkanik berukuran kecil yang terletak dalam wilayah Kabupaten Sikka, Provinsi Nusa Tenggara Timur, Indonesia. Wilayah Pulau Palue pernah dihuni oleh suku Naru sebelum akhirnya ditinggalkan.\nDi Pulau Palue terdapat sumber air panas yang digunakan untuk kebutuhan harian penduduk setelah dilakukan sublimasi.', -8.325, 121.711667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paluweh.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2735628', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (9473, NULL, 1, 'Pulau Kofiau', 'Raja Ampat', 'Awat, Raja Ampat, Papua Barat Daya', 'Pulau Kofiau adalah salah satu pulau yang ada di Kabupaten Raja Ampat, Provinsi Papua Barat Daya. Lahan seluas 16.676 Ha di Pulau Kofiau ditutupi oleh terumbu karang.', -1.182053, 129.848961, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karta%20ID%20RajaAmpat%20Isl.PNG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q24885179', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (9474, NULL, 1, 'Pulau Miangas', 'Kepulauan Talaud', 'Sulawesi Utara', 'Pulau Miangas adalah salah satu pulau terluar Indonesia yang terletak di paling utara wilayah Indonesia, sebagai tapal batas antara Indonesia dengan Filipina. Pulau ini termasuk ke dalam Desa Miangas, Kecamatan Miangas, Kabupaten Kepulauan Talaud, Provinsi Sulawesi Utara, Indonesia. Miangas adalah salah satu pulau yang tergabung dalam gugusan Kepulauan Nanusa yang berbatasan langsung dengan kawasan Filipina.', 5.5557861, 126.5852278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wolo%20Beach%2C%20Miangas%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q15253301', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (9475, NULL, 1, 'Pulau Gunungapi', 'Maluku', NULL, 'Gunung Api Banda adalah sebuah gunung berapi, sekaligus sebuah pulau yang terletak di Laut Banda. Pulau ini adalah salah satu pulau di Kepulauan Banda. Tingginya 656 meter dari permukaan laut.', -4.52, 129.88, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BandaVolcano.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q806237', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 16),
  (9476, NULL, 1, 'Pulau Lirang', 'Maluku Barat Daya', 'Ustutun, Maluku Barat Daya, Maluku', '8°3′50″S 125°44′0″E\n\nPulau Liran atau Lirang adalah pulau terluar Indonesia yang terletak di Selat Wetar dan berbatasan dengan Timor Leste. Pulau Liran ini merupakan bagian dari wilayah pemerintah kabupaten Maluku Barat Daya, Provinsi Maluku. Pulau ini berada di sebelah utara dari Timor Leste dengan koordinat 8° 3′ 50″ LS, 125° 44′ 0″ BT. Pada 2 Maret 2017, Presiden Joko Widodo menetapkan Pulau Liran sebagai salah satu dari 111 pulau-pulau kecil terluar.', -8.0161111, 125.7438889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Vuurtoren%20op%20het%20eiland%20Lyran%20TMnr%2010010409.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q939912', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 16),
  (9477, NULL, 1, 'Pulau Komolom', 'Merauke', NULL, 'Pulau Komolom atau Komoran adalah sebuah pulau di selatan Pulau Yos Sudarso yang jauh lebih besar dan berada di dekat pantai selatan pulau Papua di provinsi Papua Selatan, Indonesia. Luasnya adalah 695 km².Pulau datar sebagian besar ditutupi oleh vegetasi tropis dan memiliki banyak aliran air kecil yang mengalir melaluinya.\nKomoran memiliki 554 penduduk (sensus 2010) dan sangat jarang penduduknya sehingga kepadatan penduduknya hanya kurang dari 2 orang per km2.', -8.278178, 138.746172, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yos%20Sudarso%20SE%20txu-oclc-6552576-sc54-1.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1780682', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 16),
  (9478, NULL, 1, 'Pulau Neira', 'Maluku Tengah', NULL, 'Banda Neira (atau Banda Naira) adalah salah satu pulau di Kepulauan Banda yang berfungsi sebagai pusat administratif Kecamatan Banda, Kabupaten Maluku Tengah, Maluku. Secara administratif, wilayah ini terdiri dari 12 Negeri, meliputi Dwiwarna, Kampung Baru, Merdeka, Nusantara, Rajawali, Tanah Rata, Lonthoir, Walang, Katoro, Kumber, Selamon, Dender, Waer, dan Pulau Hatta. \nBerbeda dengan pulau lain di sekitarnya, Banda Neira memiliki topografi yang cenderung datar sehingga memungkinkan pembangunan kota kecil.', -4.5175, 129.9025, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banda%20Neira%201724.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2882109', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 16),
  (9479, NULL, 1, 'Pulau Ndana', 'Rote Ndao', 'Boa, Rote Ndao, Nusa Tenggara Timur', 'Lihat pula Pulau Pamana Besar, sebuah pulau di sebelah utara perairan Pulau Flores.\n\nPamana atau Dana, Dona dan Ndana adalah sebuah pulau terluar Indonesia yang terletak di sebelah barat daya Pulau Rote dan berlokasi cukup dekat dengan wilayah Australia. Secara administratif, pulau ini termasuk wilayah Kecamatan Rote Barat Daya, Kabupaten Rote Ndao, Provinsi Nusa Tenggara Timur, Indonesia.', -10.9822194, 122.8636111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rote%20Island%20de.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q5261510', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 16),
  (9481, NULL, 1, 'Pulau Nuhu Yuthu', 'Maluku Tenggara', NULL, 'Pulau Kei Besar (bahasa Kei: Nuhu Yuut atau Nusteen) adalah salah satu pulau di Kepulauan Kei, bagian dari gugusan Kepulauan Maluku, Indonesia. Luasnya mencapai 550 km (340 mil). Pulau besar lainnya di Kepulauan Kei adalah Pulau Kei Kecil (bahasa Kei: Nuhu Roa atau Nusyanat).', -5.6405556, 133.0177778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Prauw%20van%20Groot-Kei%20TMnr%2010010572.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1737894', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 15),
  (9482, NULL, 1, 'Pulau Galang', 'Batam', 'Batam, Kepulauan Riau', 'Pulau Galang adalah pulau di wilayah pemerintahan Kota Batam, provinsi Kepulauan Riau yang merupakan rangkaian pulau besar ketiga yang dihubungkan oleh enam buah jembatan Barelang. Pulau ini terkenal karena adanya tempat pengungsian Vietnam yang terjadi secara besar-besaran pada tahun 1979–1996 dan menjadi perhatian dari pihak Perserikatan Bangsa-Bangsa dan kalangan internasional. Kamp pengungsi Galang ini sekarang menjadi objek wisata dan sejarah kota Batam, karena jaraknya yang relatif dekat dengan pulau Batam (sekitar 7 km).', 0.747219, 104.231111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Galang%20Refugee%20Camp.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1491692', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 15),
  (9483, NULL, 1, 'Pulau Karimun', 'Karimun', 'Pasir Panjang, Karimun, Kepulauan Riau', 'Pulau Karimun: Pulau di Kabupaten Karimun, Kepulauan Riau, Karimun.', 1.0547333, 103.3577083, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Government%20office%20at%20Karimun.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q15222068', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 15),
  (9484, NULL, 1, 'Pulau Rempang', 'Batam', 'Batam, Kepulauan Riau', 'Pulau Rempang dengan luas kurang-lebih 165,83 km² adalah pulau di wilayah pemerintahan kota Batam, provinsi Kepulauan Riau yang merupakan rangkaian pulau besar kedua yang dihubungkan oleh enam buah jembatan Barelang. Pulau ini berada kira-kira 3 km di sebelah tenggara pulau Batam dan terhubung oleh jembatan Barelang ke-5 dengan pulau Galang di bagian selatan. Pada saat ini pulau Rempang banyak dikembangkan untuk wilayah pertanian dan perikanan Sembulang, selain juga mempunyai beberapa buah pantai yang bagus.', 0.869719, 104.153331, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jembatan%20Barelang%20Batam.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1754924', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9485, NULL, 1, 'Gili Air', 'Lombok Utara', 'Tanjung, Nusa Tenggara Barat', 'Gili Air merupakan salah satu dari tiga pulau gili terkenal di Lombok, yaitu Gili Trawangan, dan Gili Meno. Ketiga pulau ini terkenal dengan keindahan pantainya, maka tak heran apabila Gili Air menjadi salah satu destinasi wisata di Lombok.\nDari ketiga pulau gili yang telah disebutkan diatas, Gili Air merupakan pulau yang letaknya paling dekat dengan pulau Lombok.', -8.3575, 116.081389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gili%20Air%20seen%20from%20gili%20meno.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1490118', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9486, NULL, 1, 'Pulau Lembeh', 'Bitung', 'Bitung, Sulawesi Utara', 'Pulau Lembeh adalah sebuah pulau masuk wilayah administrasi Kota Bitung di Provinsi Sulawesi Utara, Indonesia. Pulau Lembeh saat ini secara administratif terbagi dua kecamatan yaitu Kecamatan Lembeh Utara dan Lembeh Selatan. Pulau ini terkenal karena menjadi lokasi penyelaman wisatawan asing di Sulawesi Utara selain Bunaken.', 1.421969, 125.231303, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lembeh%20Island%20view%20from%20Port%20of%20Bitung.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q3229302', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9487, NULL, 1, 'Pulau Batam', 'Batam', 'Kepulauan Riau', 'Pulau Batam adalah salah satu pulau yang terletak di provinsi Kepulauan Riau, Indonesia. Kota Batam terletak di atas pulau tersebut. Pulau Batam secara terkoneksi dengan Pulau Rempang dan Pulau Galang melalui jembatan Barelang.', 1.0875, 104.019719, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jodoh%20Nagoya%20-%20Panoramio%20109914890.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q4842953', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9488, NULL, 1, 'Pulau Menjangan', 'Buleleng', 'Gerokgak, Bali', 'Pulau Menjangan merupakan pulau kecil yang terletak di 5 mil barat laut pulau Bali dan merupakan bagian dari Taman Nasional Bali Barat. Pulau ini berada di wilayah Desa Sumberklampok, Kecamatan Gerokgak, Kabupaten Buleleng. Pulau ini dikenal sebagai tempat tujuan wisata snorkeling atau menyelam.', -8.095831, 114.515278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menjangan%20Island%20from%20the%20air.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1842938', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9489, NULL, 1, 'Pulau Selaru', 'Kepulauan Tanimbar', 'Fursuy, Kepulauan Tanimbar, Maluku', '8°11′02″S 130°57′43″E\n\nPulau Selaru adalah sebuah pulau yang terletak di Laut Timor dan berbatasan dengan negara Australia. Pulau Selaru ini merupakan bagian dari wilayah pemerintah Kabupaten Maluku Tenggara Barat, Provinsi Maluku. Pulau ini berada di sebelah selatan dari Pulau Yamdena.', -8.1838889, 130.9619417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Mangrovevegetatie%20te%20Seloe%20Tanimbar-eilanden%20TMnr%2010012649.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1884825', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9490, NULL, 1, 'Pulau Moyo', 'Sumbawa', 'Sebotok, Sumbawa, Nusa Tenggara Barat', 'Moyo adalah sebuah pulau yang terdapat 2,5 km di sebelah utara Pulau Sumbawa. Pulau ini memiliki luas 350 km2, ketinggian maksimum 671 meter, dan garis pantai 88 km. Secara administratif, pulau ini termasuk wilayah Kabupaten Sumbawa, Nusa Tenggara Barat, Indonesia.', -8.229578, 117.565064, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tambora%20volc.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1951280', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9491, NULL, 1, 'Pulau Singkep', 'Lingga', 'Lingga, Kepulauan Riau', 'Pulau Singkep adalah sebuah pulau di Kepulauan Lingga di Indonesia. Luasnya 757 kilometer persegi (292 sq mi). Pulau ini terpisah dari pantai timur Sumatra oleh Selat Berhala.', -0.491528, 104.411358, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Singkep%2038%20jago.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2093843', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 14),
  (9492, NULL, 1, 'Gili Meno', 'Lombok Utara', 'Tanjung, Nusa Tenggara Barat', 'Gili Meno adalah salah satu dari tiga pulau kecil, selain Gili Trawangan dan Gili Air, yang menjadi kawasan wisata bahari. Tempat ini dapat dicapai dari Kota Mataram sekitar 45 menit berkendaraan darat dengan perjalanan melewati Pantai Senggigi yang berlatarkan pemandangan pantai yang menakjubkan serta hutan lindung. Di sini terdapat taman burung yang mempunyai koleksi burung-burung langka dari Indonesia dan mancanegara.', -8.350556, 116.056942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gili%20Meno%20Island%2C%20Trees%2C%20Indonesia.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1524355', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9493, NULL, 1, 'Pulau Haruku', 'Maluku Tengah', 'Rohomoni, Maluku Tengah, Maluku', 'Pulau Haruku adalah sebuah pulau di Kepulauan Lease dalam wilayah Kecamatan Pulau Haruku, Kabupaten Maluku Tengah, Provinsi Maluku, Indonesia. Luas wilayah Pulau Haruku adalah 150 km2 dan terbagi menjadi 11 negeri. Pulau Haruku dihuni oleh dua komunitas masyarakat adat yaitu Uli Hatuhaha dan Uli Buang Besi.', -3.5680561, 128.48265, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ambon%20and%20Lease%20Islands%20%28Uliasers%29%20de.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1587817', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9494, NULL, 1, 'Pulau Sangiang', 'Serang', 'Kab Serang, Banten', 'Pulau Sangiang adalah sebuah pulau yang terletak di selatan Lampung berada di Selat Sunda, yakni antara pulau Sumatera dan pesisir utara Banten. Secara administratif, pulau ini masuk dalam wilayah Kabupaten Serang, Banten dan merupakan wilayah adat Lampung Cikoneng, terletak di titik kordinat antara 105′49′30″ - 105′52′ Bujur Timur 5′56′ - 5′58′50″ Lintang Selatan.\nJarak tempuhnya hanya membutuhkan waktu kurang lebih 45 menit dari Anyer, dengan menggunakan kapal atau perahu bermotor.', -5.9559, 105.8532833, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20sangiang.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2096402', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9495, NULL, 1, 'Gili Motang', 'Manggarai Barat', 'Golo Mori, Manggarai Barat, Nusa Tenggara Timur', 'Gili Motang adalah pulau kecil di Indonesia, yang merupakan bagian dari gugusan kepulauan di dalam Taman Nasional Komodo. Pulau ini memiliki luas sekitar 30 km². Pulau ini dihuni oleh sekitar seratus ekor biawak komodo (ora).', -8.807778, 119.786942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Komodo%20National%20Park%202000-07-20%20ASTER.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2275529', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9496, NULL, 1, 'Pulau Banda Besar', 'Maluku Tengah', 'Lautang, Maluku Tengah, Maluku', 'Lontor, juga dikenal sebagai Lonthor atau Lonthoir, atau secara lokal dikenal sebagai Banda Besar, adalah pulau di Kepulauan Banda, Indonesia. Pulau ini dikelola sebagai bagian dari kecamatan di dalam Kabupaten Maluku Tengah di Provinsi Maluku.', -4.555831, 129.909719, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bandaneira-0039.JPG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2658452', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9497, NULL, 1, 'Pulau Kayoa', 'Halmahera Selatan', 'Guruapin, Halmahera Selatan, Maluku Utara', 'Pulau Kayoa adalah salah satu pulau yang ada di Kabupaten Halmahera Selatan, Maluku Utara, Indonesia. Luas lahan daratan di Pulau Kayoa adalah 87 kilometer persegi. Sekitar sepertiga dari wilayah Pulau Kayoa merupakan ekosistem hutan bakau.', 0.0522194, 127.4352778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluku%20Islands%20en.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q3194411', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9498, NULL, 1, 'Pulau Mare', 'Tidore Kepulauan', 'Marekofo, Tidore Kepulauan, Maluku Utara', 'Pulau Mare adalah salah satu pulau yang ada di Kota Tidore Kepulauan, Provinsi Maluku Utara, Indonesia. Dalam sistem koordinat geografi, Pulau Mare terletak di titik koordinat 0o 34\' 26.603" Lintang Utara dan 127o 123\' 49.795" Bujur Timur.\nPulau Mare berada di bagian barat dari Kota Tidore Kepulauan.', 0.574056, 127.397164, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20on%20the%20Southern%20Coast%20of%20Pulau%20Tidore%2C%20The%20Moluccas%20%28Maluku%29%20%2815176607076%29.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q4176628', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 13),
  (9499, NULL, 1, 'Pulau Buano', 'Seram Bagian Barat', 'Serani, Seram Bagian Barat, Maluku', 'Pulau Buano atau Pulau Boano adalah sebuah pulau di sebelah selatan Laut Seram, Indonesia. Pulau ini terletak di sebelah timur laut dari Pulau Kelang dan di sebelah barat laut Pulau Seram. Pulau Buano secara administratif termasuk ke dalam daerah dua desa di Kecamatan Huamual Belakang, Kabupaten Seram Bagian Barat, Provinsi Maluku.', -2.9838889, 127.9169417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Boano%20ISS.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q887518', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9500, NULL, 1, 'Pulau Bengkalis', 'Bengkalis', NULL, 'Pulau Bengkalis adalah sebuah pulau di Provinsi Riau, juga merupakan pulau utama dari Kabupaten Bengkalis. Dimana pusat pemerintahan daerah Kabupaten Bengkalis berada. Pulau ini berbatasan dengan Selat Malaka di bagian timur, utara dan barat, dan Selat Bengkalis pada bagian selatannya.', 1.474769, 102.294639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lokasi%20Riau%20Kabupaten%20Bengkalis.svg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1136429', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9501, NULL, 1, 'Pulau Gag', 'Raja Ampat', NULL, 'Pulau Gag adalah sebuah pulau yang terletak di Kabupaten Raja Ampat, Provinsi Papua Barat Daya, Indonesia. Pulau ini berbatasan dengan Pulau Gebe, Provinsi Maluku Utara, di sebelah barat laut.', -0.443642, 129.879131, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karta%20ID%20RajaAmpat%20Isl.PNG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1491065', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9502, NULL, 1, 'Pulau Semau', 'Kupang', 'Bokonusan, Kupang, Nusa Tenggara Timur', 'Semau adalah sebuah pulau yang terletak di perairan sebelah barat Pulau Timor, yakni 20 km di sebelah barat Kota Kupang. Secara administratif, pulau ini terbagi dalam 2 kecamatan, yakni Semau dan Semau Selatan, Kabupaten Kupang, Provinsi Nusa Tenggara Timur, Indonesia.\nPenduduk asli P. Semau berasal dari suku Helong, yang dipercaya beberapa pihak sebagai penduduk asli wilayah Kupang.', -10.233331, 123.391667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Tenggara%20Timur2.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q1509983', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9504, NULL, 1, 'Pulau Yerui', 'Papua', NULL, 'Pulau Num adalah sebuah pulau berukuran kecil yang terletak di Kabupaten Kepulauan Yapen, Provinsi Papua, Indonesia. Lokasi Pulau Num termasuk dalam Kepulauan Yapen di perairan Teluk Cenderawasih yang berada di antara Pulau Yapen dan Pulau Numfor.', -1.5113889, 135.2152778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schouten%20Islands%20%28IN%29%20Topography.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q4116919', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9505, NULL, 1, 'Pulau Moti', 'Ternate', NULL, 'Moti adalah salah satu pulau yang ada di Kota Ternate, Maluku Utara, Indonesia. Moti juga tercatat sebagai salah satu Kecamatan di Kota Ternate yang diberi nama Kecamatan Pulau Moti.\nDalam sistem koordinat geografi, Pulau Moti berada di titik koordinat 0o 27\' 25.000" Lintang Utara dan 127o 24\' 39.000" Bujur Timur.', 0.456942, 127.410831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Moti.jpg?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q13149153', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (9506, NULL, 1, 'Pulau Kei Kecil', 'Maluku Tenggara', 'Maluku Tenggara, Maluku', 'Kei Kecil (Bahasa Kei: Nuhu Roa, atau Nusyanat) adalah salah satu pulau di Kepulauan Kei yang merupakan bagian dari Kepulauan Maluku, Indonesia. Luasnya 399 km2, dan sebagian wilayahnya termasuk dalam wilayah Kota Tual, kota utama di seluruh kepulauan ini yang terletak di Pulau Kei Dullah. Pulau utara lainnya dalam gugusan Kepulauan Kai adalah Kei Besar.', -5.750278, 132.728056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20Kai%20Kecil.PNG?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q685305', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 11),
  (9507, NULL, 1, 'Pulau Lautsa', 'Maluku Tengah', NULL, 'Nusalaut atau Nusalau adalah salah satu pulau yang ada di Kepulauan Maluku. Pulau ini sejak tahun 2011 merupakan kecamatan tersendiri, dengan ibu kota di negeri Ameth. Bersama Saparua, Haruku, dan pulau-pulau kecil di sekitarnya, Nusalaut merupakan bagian dari Kepulauan Lease, dengan Nusalaut sebagai pulau utama yang paling kecil.', -3.6733306, 128.7847194, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ambon%20and%20Lease%20Islands%20%28Uliasers%29%20de.png?width=800', '2026-11-24 09:44:08', '2026-11-24 23:32:50', 'wd:Q2008985', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 11),
  (9508, NULL, 1, 'Pulau Ndao', 'Rote Ndao', 'Ndao Nuse, Rote Ndao, Nusa Tenggara Timur', 'Pulau Ndao (ڤولاو نداءو) atau rai Dhao (nama lokal) adalah sebuah pulau kecil di sebelah barat Pulau Rote di Provinsi Nusa Tenggara Timur, Indonesia. Pulau Ndao adalah salah satu dari tujuh pulau di wilayah Sunda Kecil, yang disebut “busur luar”. Bersama dengan pulau kecil di timur laut, yang disebut Nuse, dan pulau lain yang tidak berpenghuni di bawahnya, yang disebut Do’o, pulau-pulau ini membentuk pemerintahan kecamatan.', -10.812219, 122.663889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ndao.PNG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2475573', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 11),
  (9509, NULL, 1, 'Pulau Raijua', 'Sabu Raijua', 'Bolua, Sabu Raijua, Nusa Tenggara Timur', 'Pulau Raijua adalah sebuah pulau yang terletak di Kecamatan Raijua, Kabupaten Sabu Raijua, Provinsi Nusa Tenggara Timur, Indonesia. Luas Pulau Raijua adalah 36 km2. Lokasi Pulau Raijua berada di sebelah barat daya Pulau Sawu.', -10.619442, 121.576942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Tenggara%20Timur2.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q19731173', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 11),
  (9510, NULL, 1, 'Pulau Sanghyang', 'Bima', NULL, 'Pulau Sanghyang: Pulau di Kabupaten Bima, Nusa Tenggara Barat, Bima.', -8.19857, 119.06663, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Sangeang%20Satellitenaufnahme.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1586632', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9511, NULL, 1, 'Pulau Kasiruta', 'Halmahera Selatan', 'Halmahera Selatan, Maluku Utara', 'Kasiruta merupakan nama sebuah pulau yang terdapat di Provinsi Maluku Utara. Letaknya di sebelah barat pulau Bacan.\nDesa penghasil batu bacan yang berurutan pertama kali dijumpai di pulau Kasiruta adalah Desa Doko dan terakhir Desa Palamea.', -0.388889, 127.194442, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20Kasiruta.PNG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1734975', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9512, NULL, 1, 'Pulau Unauna', 'Tojo Una-Una', 'Una Una, Tojo Una-Una, Sulawesi Tengah', 'Pulau Una-Una adalah salah satu pulau di wilayah Kabupaten Tojo Una-Una, provinsi Sulawesi Tengah, Indonesia. Pulau ini terletak di utara Pulau Togian.\nPulau ini populer di kalangan turis internasional untuk menyelam.', -0.171942, 121.609442, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Una-Una%20seen%20from%20the%20boat.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2492259', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9513, NULL, 1, 'Pulau Sempu', 'Malang', 'Kabupaten Malang, Jawa Timur', 'Pulau Sempu adalah sebuah pulau kecil yang terletak di sebelah selatan Pulau Jawa; secara administratif berada di Desa Tambakrejo, Kecamatan Sumbermanjing Wetan, Kabupaten Malang, Jawa Timur. Pulau yang ditumbuhi pepohonan tropis ini adalah cagar alam yang dikelola oleh Balai Besar Konservasi Sumber Daya Alam (BBKSDA) Jawa Timur di bawah KLHK RI. Secara resmi tempat ini ditetapkan sebagai cagar alam sejak 1928 pada masa pemerintahan Hindia Belanda, melalui SK Gubernur Jenderal (Besluit van den Gouverneur Generaal van Nederlandsch Indie) No. 69 dan No.', -8.444875, 112.698183, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Sempu.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3478479', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9514, NULL, 1, 'Pulau Manipa', 'Seram Bagian Barat', 'Hulane, Seram Bagian Barat, Maluku', 'Pulau Manipa adalah sebuah pulau di Kabupaten Seram Bagian Barat, Provinsi Maluku, Indonesia. Terletak 8 km lepas pantai barat Pulau Kelang di ujung barat Pulau Seram dan 25 km lepas pantai barat Buru. Termasuk pulau-pulau kecil yang berdekatan, mencakup area seluas 159,71 km2.', -3.3099028, 127.5762028, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9E%D1%81%D1%82%D1%80%D0%BE%D0%B2%20%D0%9C%D0%B0%D0%BD%D0%B8%D0%BF%D0%B0.svg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q115401971', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9515, NULL, 1, 'Pulau Runi', 'Raja Ampat', NULL, 'Pulau Runi: Pulau di Kabupaten Raja Ampat, Papua Barat Daya, Raja Ampat.', 0.377, 131.0483556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karta%20ID%20RajaAmpat%20Isl.PNG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q4117258', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9516, NULL, 1, 'Pulau Satonda', 'Dompu', 'Bima, Nusa Tenggara Barat', 'Pulau Satonda adalah sebuah pulau di Provinsi Nusa Tenggara Barat, Indonesia. Pulau ini terletak di lepas pantai utara Pulau Sumbawa. Pulau ini masuk dalam wilayah Kabupaten Dompu, 3 kilometer dari Selat Sanggar di Laut Flores dan secara administratif berada di wilayah Desa Nangamiro di Kecamatan Pekat.', -8.104267, 117.745958, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/SatondaGeneralView.JPG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q16856591', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9517, NULL, 1, 'Pulau Larat', 'Kepulauan Tanimbar', 'Keliobar, Kepulauan Tanimbar, Maluku', 'Pulau Larat adalah pulau terluar Indonesia yang terletak di Laut Aru dan berbatasan dengan negara Australia. Pulau Larat ini merupakan bagian dari wilayah pemerintah Kabupaten Kepulauan Tanimbar, provinsi Maluku. Pulau ini berada di sebelah timur laut dari Pulau Yamdena dengan 7° 14′26″ LS, 131° 58′49″ BT (batas bagian paling luarnya).', -7.137778, 131.850831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20Larat.PNG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q19731148', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 10),
  (9518, NULL, 1, 'Pulau Sebuku', 'Lampung Selatan', 'Lampung Selatan, Lampung', 'Pulau Sebuku adalah sebuah pulau di Selat Sunda. Pulau ini masuk ke dalam wilayah administratif Kabupaten Lampung Selatan, Provinsi Lampung. Luasnya 17.71 km persegi, menjadikannya salah satu pulau terbesar di Teluk Lampung.', -5.878719, 105.510658, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sebuku%20Island.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1075589', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9519, NULL, 1, 'Pulau Krakatau', 'Lampung Selatan', NULL, 'Pulau Rakata atau juga dikenal sebagai Pulau Krakatau Besar merupakan pulau yang terletak di Selat Sunda. Pulau ini merupakan sisa dari letusan besar gunung Krakatau pada tahun 1883. Pulau ini terletak di bagian selatan dari gugusan Kepulauan Krakatau, yang juga mencakup Pulau Anak Krakatau, Pulau Sertung, dan Pulau Panjang (Krakatau Kecil).', -6.1525, 105.444269, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rakata-1.JPG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1245622', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9520, NULL, 1, 'Pulau Letti', 'Maluku Barat Daya', NULL, 'Pulau Leti adalah pulau terluar Indonesia dengan luas 91,25 km2 terletak di Laut Timor dan berbatasan dengan negara Timor Leste. Pulau ini terletak pada titik koordinat 8°13′20″S 127°38′50″E. Pulau Leti merupakan bagian dari wilayah pemerintah kabupaten Maluku Barat Daya, provinsi Maluku. Hampir sebagian besar penduduk Pulau Leti beragama Kristen.', -8.194442, 127.6775, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leti%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1446634', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9521, NULL, 1, 'Pulau Matak', 'Kepulauan Anambas', 'Teluk Sunting, Kepulauan Anambas, Kepulauan Riau', 'Matak adalah sebuah pulau di Kepulauan Anambas, Indonesia. Pulau ini terletak di Laut Tiongkok Selatan di antara Semenanjung Malaysia dan Kalimantan. Pulau ini adalah markas perusahaan minyak, termasuk ConocoPhilips, Premier Oil dan Star Energy, dan dilayani oleh Bandara Matak (MWK/WIOM).', 3.316389, 106.266942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dermaga%20matak%20kecil%2C%20kabupaten%20kepulauan%20anambas%202014-01-26%2020-45.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2342740', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9522, NULL, 1, 'Pulau Peucang', 'Pandeglang', 'Pandeglang, Banten', 'Pulau Peucang (Sunda: Pulo Peucang) adalah pulau yang terdapat di  Kabupaten Pandeglang, Banten atau sebelah barat Taman Nasional Ujung Kulon.\n\nPulau ini bersama Pulau Panaitan dan Pulau Handeuleum termasuk dalam wilayah kawasan Taman Nasional Ujung Kulon sehingga tidak sedikit wisatawan yang berkunjung ke Taman Ujung Kulon, juga berkunjung ke pulau berpasir putih ini.\nKarena dalam wilayah Taman Nasional Ujung Kulon,Pulau Peucang juga diterima sebagai Situs Warisan Dunia UNESCO, bersama dengan Pulau Panaitan dan Pulau Handeuleum.', -6.740544, 105.257383, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesie%20-%20Pulau%20Peucang.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3156096', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (9523, NULL, 1, 'Pulau Wangiwangi', 'Wakatobi', 'Komala, Wakatobi, Sulawesi Tenggara', 'Pulau Wangiwangi atau juga masyarakat sekitar menyebutnya Wanci adalah sebuah pulau di Sulawesi Tenggara yang terkenal akan keindahan lautnya. Di bagian barat berbatasan dengan Pulau Kapota jaraknya cukup dekat sekitar 10 km. Pulau ini menjadi bagian dari Kepulauan Tukangbesi.', -5.3027, 123.5788, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wisata%20Goa%20Air%20Kontamale%2C%20Wanci%2C%20Pulau%20Wangi-Wangi.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3234911', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9524, NULL, 1, 'Pulau Manado Tua', 'Manado', 'Bunaken Kepulauan, Manado, Sulawesi Utara', 'Pulau Manado Tua adalah sebuah pulau yang berada di teluk Manado dan merupakan bagian dari Kecamatan Bunaken Kepulauan, kota Manado, Sulawesi Utara, Indonesia. \nPulau Manado Tua memiliki luas 89.065 ha dan garis pantai sepanjang 12.280 m dan merupakan pulau berbentuk gunung berstatus aktif. Puncak gunung memiliki ketinggian 655 m dan ditemukan tanda aktif gunung berapi di kedalaman 150 kaki.', 1.6351, 124.6948, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manado%20Sua.JPG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3285154', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9525, NULL, 1, 'Pulau Mursala', 'Tapanuli Tengah', NULL, 'Pulau Mursala merupakan salah satu pulau yang berada di Samudra Hindia. Pulau ini berada di sisi barat Pulau Sumatra.\nSecara administrasi, Pulau Mursala terletak di Tapanuli Tengah, Provinsi Sumatera Utara.', 1.6375, 98.525831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterfall%20from%20Mursala%20Island%20Flowing%20Directly%20to%20Sea.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3328260', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9526, NULL, 1, 'Pulau Nusabarong', 'Jember', NULL, 'Nusa Barung (atau Nusa Barong) adalah sebuah pulau kecil yang terletak di sebelah selatan Pulau Jawa. Pulau ini berada dalam wilayah Desa Puger Kulon, Kecamatan Puger, Kabupaten Jember, Jawa Timur. Pulau ini merupakan salah satu pulau terluar Indonesia yang terletak di Samudra Hindia dan berbatasan dengan negara Australia.', -8.4807556, 113.3345667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nusa%20Barong%20%28Landsat%29.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3346494', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9527, NULL, 1, 'Pulau Tinjil', 'Pandeglang', 'Pandeglang, Banten', 'Pulau Tinjil adalah sebuah pulau kecil yang terletak di Samudra Hindia. Secara administratif, pulau ini termasuk dalam wilayah Kabupaten Pandeglang, Banten.  Lokasinya berada di titik koordinat 6°57′44″LS, 105°47′0″BT.\nPulau Tinjil memiliki bentuk yang memanjang dari Timur Laut hingga ke Barat Daya dengan morfologi datar dan permukaan pada bagian timur hingga tengah dan semakin ke barat berubah menjadi kasar yang disertai dengan adanya bukit kecil.', -6.962211, 105.793217, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Mannen%20bij%20een%20hut%20op%20het%20strand%20van%20Trouwers-eiland%20%28Poelau%20Tindjil%29%20TMnr%2060044113.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3529193', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9528, NULL, 1, 'Pulau Pura', 'Alor', 'Pura Selatan, Alor, Nusa Tenggara Timur', 'Pura adalah sebuah pulau dalam Gugus Pulau Alor yang terletak di ujung timur Gugus Kepulauan Sunda Kecil. Pulau Pura adalah pulau terbesar di antara pulau-pulau kecil di perairan Selat Pantar yang memisahkan dua pulau utama, Pantar dan Alor. Pesisir utara dari pulau seluas 27,84 km2 ini merupakan kawasan perbukitan.', -8.298611, 124.346389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/10-103b%20Alor%20subdistricts%20relief%20colour.tif?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24847692', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 9),
  (9529, NULL, 1, 'Pulau Sertung', 'Lampung Selatan', 'Lampung Selatan, Lampung', 'Pulau Sertung adalah sebuah pulau yang terletak di Selat Sunda yang memisahkan antara Pulau Sumatra dengan Pulau Jawa. Pada zaman Hindia Belanda, pulau ini disebut "Pulau Verlaten" (bahasa Belanda untuk "tertinggal" atau "terbuang").\nPulau Sertung (6°05S\'., 105°23\' E.) berada sekitar 312 mil dari Pulau Rakata (Pulau Krakatau) dan merupakan bagian dari kepulauan Krakatau, bersama dengan Pulau Panjang, Pulau Anak Krakatau, dan Pulau Rakata.', -6.091469, 105.381758, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Zeegezicht%20met%20de%20S.S.%20Rumphius%20TMnr%2010027440.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q824896', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9530, NULL, 1, 'Pulau Sebesi', 'Lampung Selatan', 'Tejang Pulau Sebesi, Lampung Selatan, Lampung', 'Pulau Sebesi (Sebesi Island) adalah sebuah pulau yang secara administratif berada di wilayah Desa Tejang, Kecamatan Rajabasa, Kabupaten Lampung Selatan, Provinsi Lampung, Indonesia. Berbentuk gunung berapi dengan ketinggian 844m, secara geografis pulau ini terletak di Selat Sunda atau wilayah selatan perairan Lampung. Lebih tepatnya Pulau Sebesi berada di sebelah selatan dari Pulau Sebuku, sebelah timur Pulau Serdang dan Pulau Legundi, serta sebelah Timur Laut Gugusan Krakatau.', -5.946669, 105.487728, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piek%20van%20Sebesi%20in%20Straat%20Soenda.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1075601', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9531, NULL, 1, 'Pulau Raya', 'Aceh Jaya', 'Lhokkruet, Aceh Jaya, Aceh', 'Pulau Raya adalah pulau terluar Indonesia yang terletak di samudra Hindia dan berbatasan dengan negara India. Pulau Raya ini merupakan bagian dari wilayah pemerintah Kabupaten Aceh Jaya, provinsi Aceh. Pulau ini berada di sebelah barat dari Aceh dengan koordinat 4° 52′ 33″ LU, 95° 21′ 46″ BT. Dulu pulau tersebut sudah tidak di tempati, sehingga mengakibatkan Provinsi Aceh diporak-porandakan oleh guncangan air yang berasal dari pantai.', 4.87, 95.378889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Gezicht%20op%20Poeloraja%20TMnr%2060038954.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2280201', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9532, NULL, 1, 'Pulau Serua', 'Maluku Tengah', 'Maluku Tengah, Maluku', 'Pulau Serua: Pulau di Kabupaten Maluku Tengah, Maluku, Maluku Tengah.', -6.3106, 130.017092, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barat%20Daya%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3410731', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9533, NULL, 1, 'Pulau Sapudi', 'Sampang', 'Somber, Sumenep, Jawa Timur', 'Pulau Sapudi (Madura: Polo Sapodây, Polo Podây, Polo Sapodhi; Péghu: ڤَولَو ساڤَوداْي، ڤَولَو ڤَوداْي، ڤَولَو ساڤَودْي) adalah sebuah pulau yang terletak di antara gugusan pulau-pulau di sebelah timur dari Pulau Madura. Secara administratif, pulau ini termasuk kedalam wilayah Kabupaten Sumenep, Jawa Timur. Di antara gugusan pulau-pulau di sebelah timur Pulau Madura, Sapudi merupakan pulau terluas kedua setelah Pulau Kangean dan pulau dengan penduduk terbanyak.', -7.110989, 114.329844, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Visverkoop%20op%20het%20eiland%20Sapudi%20ten%20oosten%20van%20Madura%20TMnr%2010002730.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3473228', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9534, NULL, 1, 'Pulau Tagulandang', 'Sulawesi Utara', NULL, 'Pulau Tagulandang merupakan salah satu pulau di Kepulauan Sangihe, terletak di ujung utara Sulawesi, Indonesia. Pulau ini membentuk tiga kecamatan di Kabupaten Kepulauan Siau Tagulandang Biaro, Provinsi Sulawesi Utara. Terletak di antara Laut Sulawesi dan Laut Maluku, dan dipisahkan dari stratovolkano Gunung Ruang oleh saluran laut yang sempit.', 2.3458167, 125.4189472, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Hut%20langs%20een%20baai%20op%20Poelau%20Tahoelandang%20TMnr%2010018034.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3513864', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8),
  (9535, NULL, 1, 'Pulau Cubadak', 'Pesisir Selatan', 'Sungai Nyalo Mudiak Aia, Pesisir Selatan, Sumatera Barat', 'Pulau Cubadak terletak di kabupaten Pesisir Selatan, provinsi Sumatera Barat. Pulau ini  terletak di Kawasan Wisata Mandeh (Mande Resort), 40 kilometer di sebelah selatan Padang, dan 5 km dari pantai. Luasnya 40 km².', -1.216667, 100.388611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Pulau%20Cubadak%2012.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1142886', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9536, NULL, 1, 'Pulau Biawak', 'Indramayu', NULL, 'Pulau Biawak atau Pulau Rakit adalah sebuah pulau yang terletak di kepulauan Biawak, Laut Jawa di Kabupaten Indramayu Jawa Barat. Pulau Biawak terletak di sebelah utara semenanjung Inrdamayu sekitar 40 kilometer dari pantai utara Indramayu, dan secara administratif termasuk ke dalam wilayah kecamatan Indramayu, Kabupaten Indramayu.', -5.929722, 108.38, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biawak%202019-09-09%20Sentinel%202%20SR.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q4964668', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9537, NULL, 1, 'Pulau Moa', 'Maluku Barat Daya', 'Tounwawan, Maluku Barat Daya, Maluku', 'Pulau Moa merupakan pulau di Indonesia. Pulau ini terletak di provinsi Maluku. Pulau ini masuk ke dalam wilayah kabupaten Maluku Barat Daya.', -8.1830556, 127.9444417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leti%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1941313', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9538, NULL, 1, 'Pulau Salibabu', 'Kepulauan Talaud', 'Sulawesi Utara', 'Pulau Salibabu adalah sebuah pulau di Kepulauan Talaud yang termasuk dalam wilayah Kabupaten Kepulauan Talaud, Provinsi Sulawesi Utara, Indonesia. Nama Pulau Salibabu telah disebutkan dalam catatan sejarah berjudul Yingyai Shenglan yang ditulis oleh Ma Huan berdasarkan tiga pelayaran dalam ekspedisi pelayaran Cheng Ho yang diikutinya pada awal abad ke-15 M. Luas Pulau Salibabu adalah 99,36 km2. \nPulau Salibabu diperkirakan telah dihuni manusia sejak 30 ribu tahun lalu berdasarkan penemuan arkeologi di Gua Liang Sarru.', 3.922869, 126.686939, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Bos%20op%20de%20Gunung%20Ajambana%20TMnr%2010012526.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506910', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9539, NULL, 1, 'Pulau Marsela', 'Maluku Barat Daya', NULL, 'Pulau Marsela adalah pulau terluar Indonesia yang terletak di Laut Timor dan berbatasan dengan negara Timor Leste / Australia. Pulau Marsela ini merupakan bagian dari wilayah pemerintah kabupaten Maluku Barat Daya, provinsi Maluku. Pulau ini berada di sebelah timur dari negara Timor Leste dengan koordinat 8° 12′ 29″ LS, 129° 49′ 32″ BT. Pulau Marsela mempunyai Sumber daya Alam terbesar no.', -8.1441667, 129.8694417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Topographic%20map%20of%20Babar%20Islands-en.svg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q15119883', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9540, NULL, 1, 'Pulau Sibandang', 'Tapanuli Utara', 'Sibandang, Kabupaten Tapanuli Utara, Sumatera Utara', 'Pulau Sibandang (dikenal juga sebagai Pulau Pardopur atau Pulau Pardepur) adalah salah satu pulau alami di kawasan Danau Toba. Pulau ini berada di Muara, Tapanuli Utara, Sumatera Utara. Merupakan pulau terbesar kedua di kawasan Danau Toba setelah Pulau Samosir.', 2.36, 98.9, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Sibandang%2002.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24819323', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9541, NULL, 1, 'Pulau Kakaban', 'Berau', 'Berau, Kalimantan Timur', 'Pulau Kakaban mempunyai luas 774,2 hektar dan terletak di Kepulauan Derawan, Kecamatan Derawan, Kabupaten Berau, Kalimantan Timur. Pulau ini merupakan atol atau batu karang melingkar dan memiliki laguna, dan terdapat danau air payau di tengah pulau  dengan species ubur-ubur (jelly fish) yang tidak menyengat dan biota unik lainnya. Danau ini telah ditetapkan sebagai kawasan warisan dunia pada tahun 2004 oleh UNESCO. Objek ini dapat tempuh sekitar 45 menit dari pulau Derawan.', 2.144317, 118.536244, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stingless%20jellyfish.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q4115317', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 7),
  (9542, NULL, 1, 'Nusa Kode Besarsa', 'Manggarai Barat', NULL, 'Gili Dasami adalah pulau kecil di Indonesia, yang merupakan bagian dari gugusan kepulauan Sunda Kecil, yang bersama dengan kepulauan Sunda Besar membentuk kepulauan Sunda.\nPulau ini dihuni oleh spesies biawak komodo. Gili Dasami merupakan bagian dari Taman Nasional Komodo.', -8.8, 119.65, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Komodo%20National%20Park%202000-07-20%20ASTER.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2345996', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9543, NULL, 1, 'Pulau Kangean', 'Sumenep', NULL, 'Pulau Kangean (Kangean: [\'Kangayan\'] Galat: {{Lang}}: text has malformed markup (bantuan); Bugis: ᨀᨂᨐᨚ, translit. Kangayan; Makassar: 𑻠𑻢𑻬𑻨, translit. Kangayan) adalah nama salah satu pulau dan merupakan pulau utama dalam wilayah gugusan pulau-pulau yang terletak di bagian utara Laut Bali, sebelah baratlaut Nusa Tenggara, sekitar 120 km (75 mi) di utara Bali, yang dikenali secara kolektif sebagai kepulauan Kangean.', -6.870417, 115.362919, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kangean%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506779', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9544, NULL, 1, 'Pulau Maratua', 'Berau', 'Teluk Harapan, Berau, Kalimantan Timur', 'Pulau Maratua adalah salah satu pulau terluar Indonesia yang terletak di Kabupaten Berau, Provinsi Kalimantan Timur. Pulau ini merupakan salah satu paradise-island wilayah ini, dan merupakan pulau terluar Indonesia. \nSepanjang garis pantainya merupakan lokasi bertelurnya penyu hijau terbesar di Indonesia.', 2.190831, 118.607219, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Side%20view%20of%20Maratua%20Island.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506839', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9545, NULL, 1, 'Pulau Masalembu', 'Sampang', 'Masalima, Sumenep, Jawa Timur', 'Artikel ini mengenai Masalembu sebagai pulau. Lihat pula Kepulauan Masalembu dan Kecamatan Masalembu.\n\nMasalembu adalah pulau terbesar di Kepulauan Masalembu, yang terletak di Laut Jawa.', -5.559614, 114.427183, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau-masalembo.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506842', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9546, NULL, 1, 'Pulau Siompu', 'Buton', NULL, 'Pulau Siompu adalah salah satu pulau di wilayah Kabupaten Buton Selatan, provinsi Sulawesi Tenggara, Indonesia. Pulau ini terletak di selatan Pulau Tomia.\nRumah adat siompu bernama B\'ARUGA.\nPulau ini memiliki dua kecamatan yaitu Kecamatan Siompu dan Kecamatan Siompu Barat.', -5.6647194, 122.5180556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wamburumburu%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q19731189', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9547, NULL, 1, 'Pulau Teor', 'Seram Bagian Timur', 'Ker Ker, Seram Bagian Timur, Maluku', 'Pulau Teor: Pulau di Kabupaten Seram Bagian Timur, Maluku, Seram Bagian Timur.', -4.747219, 131.741111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tioor%20Island%20%28Landsat%29.JPG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2801102', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9548, NULL, 1, 'Pulau Biaro', 'Sulawesi Utara', 'Karungo, Kepulauan Siau Tagulandang Biaro, Sulawesi Utara', 'Pulau Biaro merupakan sebuah pulau di laut Sulawesi yang membentuk Kecamatan Biaro yang menjadi bagian dari Kabupaten Kepulauan Siau Tagulandang Biaro (Sitaro), terletak di ujung utara Pulau Sulawesi, Provinsi Sulawesi Utara, Indonesia. Kabupaten Kepulauan Sitaro dibentuk berdasarkan Undang-Undang Nomor 15 Tahun 2007 mulai tanggal 2 Januari 2007.\nPulau Biaro berjarak sekitar 90 kilometer dari pesisir Sulawesi Utara.', 2.1, 125.3666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Biaro.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2900864', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9549, NULL, 1, 'Pulau Deli', 'Pandeglang', 'Pandeglang, Banten', 'Pulau Deli adalah sebuah pulau kecil terletak di Samudra Hindia, di sebelah barat daya Pulau Jawa. Secara administratif, pulau ini termasuk dalam wilayah Provinsi Banten. Pulau ini terletak di titik koordinat 7°01′00″LS, 105°31′25″BT. dengan Titik Dasar (TD) 147 dengan Titik Referensi (TR) 147.', -7.006378, 105.545161, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemanfaatan%20Pulau%20Deli.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3593368', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9550, NULL, 1, 'Pulau Nunukan', 'Nunukan', 'Mansapa, Nunukan, Kalimantan Utara', 'Pulau Nunukan adalah sebuah pulau di sebelah timur laut Pulau Kalimantan. Pulau ini secara administratif merupakan bagian dari wilayah Kabupaten Nunukan, Provinsi Kalimantan Utara, Indonesia. Bagian utara pulau ini berbatasan langsung dengan negara bagian Sabah, Malaysia.', 4.063786, 117.664853, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Een%20maskerdans%20te%20Nunukan%20%28Borneo%29%20met%20Europese%20invloeden%20TMnr%2010003432.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q7069929', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9551, NULL, 1, 'Pulau Karimunjawa', 'Jepara', 'Legon Pinggir, Jepara, Jawa Tengah', 'Pulau Karimunjawa adalah salah satu pulau yang merupakan pulau terbesar dan pulau utama di Kepulauan Karimunjawa, Indonesia. Pulau ini secara administratif termasuk ke dalam daerah Kecamatan Karimunjawa, Kabupaten Jepara, Provinsi Jawa Tengah. Pulau ini terletak sekitar 90 km di sebelah utara Jepara.', -5.848847, 110.452125, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karimunjawa%20pulau%20pagi.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24894943', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 6),
  (9552, NULL, 1, 'Pulau Hatta', 'Maluku Tengah', 'Lama, Maluku Tengah, Maluku', 'Pulau Hatta: Pulau di Kabupaten Maluku Tengah, Maluku, Maluku Tengah.', -4.591667, 130.04, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banda%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2713351', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9553, NULL, 1, 'Pulau Mansinam', 'Manokwari', NULL, 'Pulau Mansinam adalah pulau  yang menjadi pariwisata religi umat Kristen Protestan di Papua. Pulau ini merupakan bagian dari wilayah Papua Barat. Letaknya sekitar 6 Kilometer dari Kota Manokwari.', -0.901825, 134.101675, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pekabaran%20Injil%20Mansinam.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2794039', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9554, NULL, 1, 'Pulau Simeulue Cut', 'Simeulue', NULL, 'Pulau Simeulue Cut adalah pulau terluar Indonesia yang terletak di Samudra Hindia di pesisir barat pulau Sumatra. Pulau ini merupakan bagian dari wilayah pemerintah Kabupaten Simeulue, Aceh.', 2.5341667, 95.9405556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dermaga%20Simeulue%20Cut.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q7585384', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9555, NULL, 1, 'Pulau Kembang', 'Barito Kuala', 'Tinggiran II Luar, Barito Kuala, Kalimantan Selatan', 'Pulau Kembang adalah sebuah delta yang terletak di tengah sungai Barito yang termasuk di dalam wilayah administratif kecamatan Alalak, Kabupaten Barito Kuala, provinsi Kalimantan Selatan. Pulau Kembang terletak di sebelah barat Kota Banjarmasin. Pulau Kembang ditetapkan sebagai hutan wisata berdasarkan SK. Menteri Pertanian No.', -3.3063889, 114.5608306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Warik%20pulau%20kambang.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506796', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9556, NULL, 1, 'Pulau Wetang', 'Maluku Barat Daya', NULL, 'Pulau Wetang: Pulau di Kabupaten Maluku Barat Daya, Maluku, Maluku Barat Daya.', -7.9075, 129.5408306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Topographic%20map%20of%20Babar%20Islands-en.svg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q14544396', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9557, NULL, 1, 'Pulau Teon', 'Maluku Tengah', 'Messa, Maluku Tengah, Maluku', 'Pulau Teon: Pulau di Kabupaten Maluku Tengah, Maluku, Maluku Tengah.', -6.9716667, 129.1430556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Damar%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q15060339', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9558, NULL, 1, 'Pulau Fani', 'Raja Ampat', 'Raja Ampat, Papua Barat Daya', 'Pulau Fani adalah pulau terluar Indonesia yang terletak di Samudra Pasifik dan berbatasan dengan negara Palau. Pulau Fani ini merupakan bagian dari wilayah pemerintah Kabupaten Raja Ampat, provinsi Papua Barat Daya.', 1.063633, 131.264892, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Asia%20Islands%2C%20Indonesia%2C%20Sentinel-2.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q18691551', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9559, NULL, 1, 'Pulau Gam', 'Raja Ampat', 'Sawinggrai, Raja Ampat, Papua Barat Daya', 'Pulau Gam: Pulau di Kabupaten Raja Ampat, Papua Barat Daya, Raja Ampat.', -0.45, 130.6, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boat%20and%20corals%20near%20Pulau%20Gam%2C%20Raja%20Ampat.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q20190842', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9560, NULL, 1, 'Pulau Bras', 'Supiori', 'Supiori, Papua', 'Pulau Bras adalah pulau terluar Indonesia yang terletak di Samudra Pasifik dan berbatasan dengan negara Palau. Pulau Bras ini merupakan bagian dari wilayah pemerintah Kabupaten Supiori, provinsi Papua. Pulau ini berada di sebelah utara dari Kota Manokwari dengan koordinat 0° 55′57″ LU, 134° 20′30″ BT.\nPulau Bras merupakan gugusan dari Kepulauan Mapia yang berbatasan dengan Republik Palau.', 0.916667, 134.3325, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stamps%20of%20Indonesia%2C%20104-08.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3084981', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9561, NULL, 1, 'Pulau Pini', 'Nias Selatan', 'Lambak, Nias Selatan', 'Pulau Pini adalah sebuah pulau di Kepulauan Batu di Kabupaten Nias Selatan, Sumatera Utara, Indonesia. Pulau ini terletak di bagian timur kepulauan, antara Pulau Tanahmasa dan pesisir barat Pulau Sumatra sekitar 90 km ke arah tenggara dari Telukdalam. Pada tahun 2018, pulau ini dihuni oleh 945 jiwa yang tersebar di lima desa yang termasuk ke dalam Kecamatan Pulau-Pulau Batu Timur.', 0.128889, 98.700556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pini%202019-02-25%20Landsat%208%20T1%20SR.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q3388727', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9562, NULL, 1, 'Pulau Menui', 'Morowali', 'Buranga, Morowali, Sulawesi Tengah', 'Pulau Menui atau Pulau Manui adalah sebuah pulau yang terletak di lepas pantai timur Pulau Sulawesi, Indonesia, di perairan Laut Banda. Pulau ini secara administratif terletak di Kecamatan Menui Kepulauan, Kabupaten Morowali, Provinsi Sulawesi Tengah. Ibu kota Kecamatan Menui Kepulauan yaitu Ulunambo terletak di pulau ini.', -3.594442, 123.112219, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menui%202019-09-14%20Sentinel%202%20SR.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24879652', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9563, NULL, 1, 'Pulau Lepar', 'Bangka Selatan', 'Penutuk, Bangka Selatan, Kepulauan Bangka Belitung', 'Pulau Lepar adalah sebuah pulau yang terletak di lepas pantai tenggara Pulau Bangka. Secara administrasi pemerintahan, pulau ini merupakan bagian dari Kabupaten Bangka Selatan di Provinsi Kepulauan Bangka Belitung, dan merupakan pulau terbesar ketiga di provinsi tersebut setelah Pulau Bangka dan Belitung, dengan luas 169 km2. Pulau Lepar terletak di Selat Gaspar yang memisahkan kedua pulau tersebut.', -2.955831, 106.810278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lepar%20Island%20Location.svg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24880743', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9564, NULL, 1, 'Pulau Pongok', 'Bangka Selatan', NULL, 'Pulau Pongok, kadang dikenal sebagai Pulau Liat, adalah sebuah pulau yang merupakan bagian dari Kecamatan Kepulauan Pongok di Kabupaten Bangka Selatan, Provinsi Kepulauan Bangka Belitung. Pulau ini mencakup lebih dari 95% luas kecamatan dan sebagian besar penduduknya, dengan luas 48,3 km2. Pulau ini merupakan pulau ke-5 terbesar di provinsi tersebut, jauh lebih kecil daripada Pulau Bangka dan Belitung di samping Pulau Lepar dan Mendanau.', -2.8644417, 107.0569417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%2C%20Island%20of%20Pulo%20Leat%2C%20showing%20the%20Sinking%20of%20the%20Alceste%20in%201817.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24880806', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9565, NULL, 1, 'Pulau Bukabuka', 'Tojo Una-Una', 'Tojo Una-Una, Sulawesi Tengah', 'Pulau Bukabuka: Pulau di Kabupaten Tojo Una Una, Sulawesi Tengah, Tojo Una-Una.', -0.745831, 121.763056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukabukaislandreconnectislandresort.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24992554', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9566, NULL, 1, 'Pulau Talimago', 'Maluku Utara', NULL, 'Pulau Talimago adalah sebuah pulau kecil yang berada pada gugusan kepulauan Halmahera dan secara administratif termasuk dalam wilayah Kabupaten Halmahera Selatan, Provinsi Maluku Utara, Indonesia. Pulau ini letaknya di timur laut pulau Muari dan barat daya pulau Taneti, jaraknya kurang lebih 110 kilometer dari Kota Ternate.\nPulau Talimago tidak dihuni manusia, hanya burung yang cukup banyak bersarang di pulau ini.', -0.16077, 127.18773, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Talimago3.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q26759723', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9567, NULL, 1, 'Pulau Batu Tara', 'Lembata', NULL, 'Pulau Komba adalah pulau vulkanis terpencil yang terletak di Laut Flores, Indonesia. Pulau ini secara administratif merupakan bagian dari Kab. Lembata, Nusa Tenggara Timur.', -7.7916667, 123.5913889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batutara.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q30228047', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 5),
  (9568, NULL, 1, 'Pulau Lakor', 'Maluku Barat Daya', 'Werwawan, Maluku Barat Daya, Maluku', 'Pulau Lakor: Pulau di Kabupaten Maluku Barat Daya, Maluku, Maluku Barat Daya.', -8.246942, 128.156667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leti%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q1523442', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9569, NULL, 1, 'Pulau Manuoko', 'Seram Bagian Timur', 'Amersekaru, Seram Bagian Timur, Maluku', 'Pulau Manuoko: Pulau di Kabupaten Seram Bagian Timur, Maluku, Seram Bagian Timur.', -4.1211111, 131.3383306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluku%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q2245223', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
