  (9571, NULL, 1, 'Pulau Gorom', 'Seram Bagian Timur', 'Bas, Seram Bagian Timur, Maluku', 'Pulau Gorom: Pulau di Kabupaten Seram Bagian Timur, Maluku, Seram Bagian Timur.', -4.006667, 131.412778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluku%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q11905047', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9572, NULL, 1, 'Pulau Maitara', 'Tidore Kepulauan', 'Maitara, Tidore Kepulauan, Maluku Utara', 'Pulau Maitara adalah sebuah pulau yang berada di Maluku Utara Indonesia. Pulau Maitara ini letaknya hanya 30 menit jika menggunakan speed boat dari pulau Ternate. Pulau Maitara adalah pulau kecil di antara Tidore dan Ternate.', 0.7322189, 127.3711111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Maitara.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506831', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9573, NULL, 1, 'Pulau Manggudu', 'Sumba Timur', NULL, 'Pulau Mangudu atau Manggudu adalah pulau terluar Indonesia yang terletak di Samudra Hindia dan berbatasan dengan negara Australia. Pulau Mangudu ini merupakan bagian dari wilayah pemerintah kabupaten Sumba Timur, provinsi Nusa Tenggara Timur. Pulau ini berada di sebelah selatan dari pulau Sumba dengan koordinat 10° 20′ 8″ LS, 120° 5′ 56″ BT. Pulau Mangudu berbatasan dengan Pulau Sumba di sebelah utara, Samudera Hindia di sebelah barat dan selatan, dan dengan Pulau Salura di sebelah timur.', -10.3302778, 120.1175, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karte%20Pulau%20Sumba.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506837', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9574, NULL, 1, 'Nus Yatas', 'Maluku Barat Daya', 'Maluku Barat Daya, Maluku', 'Nus Yatas: Pulau di Kabupaten Maluku Barat Daya, Maluku, Maluku Barat Daya.', -7.5194639, 127.287825, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Romang%20Island%20NASA.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q15058157', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9575, NULL, 1, 'Pulau Nila', 'Maluku Tengah', 'Bumey, Maluku Tengah, Maluku', 'Pulau Nila: Pulau di Kabupaten Maluku Tengah, Maluku, Maluku Tengah.', -6.739719, 129.511389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barat%20Daya%20Islands%20de.png?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q15122888', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9576, NULL, 1, 'Pulau Marore', 'Kepulauan Sangihe', 'Sulawesi Utara', 'Pulau Marore adalah pulau terluar Indonesia yang terletak di Laut Sulawesi dan berbatasan dengan negara Filipina. Pulau Marore ini merupakan bagian dari wilayah pemerintah Kabupaten Kepulauan Sangihe, provinsi Sulawesi Utara.', 4.735711, 125.484606, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelangi%20Pelabuhan%20Marore.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q19731155', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9577, NULL, 1, 'Pulau Nongsa', 'Kepulauan Riau', NULL, 'Pulau Nongsa adalah salah satu pulau terluar Indonesia yang terletak di perbatasan Indonesia dengan Singapura. Wilayah Pulau Nongsa merupakan bagian dari Kota Batam, Provinsi Kepulauan Riau. Pulau Nongsa berdekatan dengan bagian utara dari Pelabuhan Nongsa di Pulau Batam.', 1.2042, 104.07793, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nongsa%20island%20Indonesia.JPG?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q19731162', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9578, NULL, 1, 'Pulau Mansuar', 'Raja Ampat', 'Kurkapa, Raja Ampat, Papua Barat Daya', 'Pulau Mansuar adalah pulau yang berada di distrik Misool Selatan, kabupaten Raja Ampat, Papua Barat Daya. Menuju pulau Mansuar bisa menggunakan transportasi speedboat dari kota Waisai dengan waktu tempuh sekitar 30 menit.', -0.585906, 130.602389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mansuar%20Island%2C%20ID%2C%20Sentinel-2.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q20191035', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9579, NULL, 1, 'Pulau Lage Peley', 'Raja Ampat', 'Raja Ampat, Papua Barat Daya', 'Pulau Lage Peley: Pulau di Kabupaten Raja Ampat, Papua Barat Daya, Raja Ampat.', 0.1775056, 130.0184028, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Wayag%20%2869211407%29.jpeg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q23304706', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9580, NULL, 1, 'Pulau Suwangi', 'Tanah Bumbu', 'Kotabaru, Kalimantan Selatan', 'Pulau Suwangi merupakan salah satu pulau yang terletak di selat pulau laut dan termasuk kategori pulau berpenghuni. Pulau ini termasuk dalam wilayah administratif Kelurahan Batulicin, Kecamatan Batulicin, Kabupaten Tanah Bumbu, Provinsi Kalimantan Selatan.\nMayoritas penduduk bersuku bugis yang sudah tinggal secara turun temurun hingga sekarang di keturunan kelima.', -3.439719, 116.028056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Sewangi%20Tanah%20Bumbu.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24830503', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9581, NULL, 1, 'Pulau Serasan', 'Natuna', 'Tanjung Setelung, Natuna, Kepulauan Riau', 'Pulau Serasan: Pulau di Kabupaten Natuna, Kepulauan Riau, Natuna.', 2.5125, 109.059167, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Scenery%20at%20Serasan%20Harbor%2C%20Natuna%20Islands%2C%20Riau%20Islands%20Province%2C%20Indonesia.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24837993', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9582, NULL, 1, 'Pulau Pua', 'Seram Bagian Barat', 'Pua, Seram Bagian Barat, Maluku', 'Pulau Pua adalah sebuah pulau di sebelah selatan Laut Seram, Indonesia. Pulau Pua secara administratif termasuk ke dalam daerah Desa Buano Utara, Kecamatan Huamual Belakang, Kabupaten Seram Bagian Barat, Provinsi Maluku. Pulau ini terletak di sebelah barat laut dari Pulau Seram.', -2.941111, 127.899719, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pua%20pulau%20ISS%202002-12-01.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24847615', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9583, NULL, 1, 'Pulau Ende', 'Ende', 'Rorurangga, Ende, Nusa Tenggara Timur', 'Pulau Ende adalah sebuah Kecamatan di Kabupaten Ende Lio, Nusa Tenggara Timur, Indonesia. Tempat ini dapat dicapai dari kota Ende dengan kapal.\nDusun Pedarae adalah sebuah dusun di desa Rendoraterua tempat ditemukan reruntuhan sebuah benteng Portugis yang dibangun pada abad ke-16.', -8.8888889, 121.5219444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ende%20Island%20%2826133372205%29.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24977488', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9584, NULL, 1, 'Pulau Bonerate', 'Kepulauan Selayar', 'Pasimarannu, Kepulauan Selayar, Sulawesi Selatan', 'Pulau Bonerate adalah salah satu pulau yang berada di gugusan Kepulauan Selayar dan secara administratif masuk pada wilayah Desa Bonerate, Kecamatan Pasimarannu, Kabupaten Kepulauan Selayar, Sulawesi Selatan, Indonesia.', -7.357144, 121.113092, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Nasional%20Takabonerate.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24997194', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
  (9585, NULL, 1, 'Pulau Tulas', 'Samosir', 'Siboro, Sumatera Utara', 'Pulau Tulas merupakan salah satu pulau yang berada di tengah Danau Toba, Indonesia.', 2.643611, 98.645278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Tulas%2003.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q26732140', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 4),
