  (9592, NULL, 1, 'Pulau Kadidiri', 'Sulawesi Tengah', 'Tojo Una-Una, Sulawesi Tengah', 'Pulau Kadidiri adalah sebuah pulau yang masuk dalam kawasan Taman Nasional Kepulauan Togean, yang terletak di Teluk Tomini, Sulawesi Tengah. Pantai pasir putih yang sangat bersih dan laut yang sangat jernih dengan biota lautnya yang berjumlah lebih dari 200 macam merupakan daya tarik bagi turis-turis asing. Pulau ini terbentuk dari gugusan pulau karang dengan pasir putih yang indah dan air laut yang jernih dan sejuk.', -0.3591, 121.8468, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kadidiri%2C%20morning%20view%20%286972093459%29.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506772', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 3),
  (9593, NULL, 1, 'Pulau Padamarang', 'Kolaka', 'Kolaka, Sulawesi Tenggara', 'Pulau Padamarang adalah salah satu pulau terbesar di kabupaten Kolaka. pulau ini terletak di wilayah Kabupaten Kolaka, provinsi Sulawesi Tenggara, Indonesia.', -4.131203, 121.417778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelabuhan%20bersandar%20Padamarang.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506861', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 3),
  (9594, NULL, 1, 'Pulau Pasi', 'Kepulauan Selayar', 'Kahu-Kahu, Kepulauan Selayar, Sulawesi Selatan', 'Pulau Pasi adalah sebuah pulau kecil yang berada sebelah barat Pulau Selayar di gugusan Kepulauan Selayar, perairan Laut Flores dan secara administratif masuk pada wilayah sebagian Desa Bontoborusu dan sebagian Desa Kahu-Kahu di Kecamatan Bontoharu, Kabupaten Kepulauan Selayar, Sulawesi Selatan, Indonesia. Secara astronomis, pulau ini terletak di titik koordinat 6°10′12.000″LS, 120°24′36.000″BT. Pulau ini berada tepat di sebelah Barat Pulau Selayar dengan jarak ± 1 mil dari Kecamatan Benteng, ibu kota Kabupaten Kepulauan Selayar atau sekitar 15 menit perjalanan melalui jalur laut. Pulau Pasi berseberangan dengan Pulau Gusung (terletak di bagian utara pulau Pasi) dan hanya dipisahkan oleh selat kecil yang dinamai Tarrusang.', -6.17, 120.41, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantai%20Liang%20Kareta%2C%20Pulau%20Pasi%2C%20Selayar%20Island%20%2815177756451%29.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506878', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 3),
  (9595, NULL, 1, 'Pulau Rusa', 'Alor', 'Alor, Nusa Tenggara Timur', 'Rusa adalah sebuah pulau kecil yang terletak di perairan sebelah barat Pulau Pantar. Secara administratif, pulau ini termasuk wilayah Kabupaten Alor, Provinsi Nusa Tenggara Timur, Indonesia.', -8.3886111, 123.8230556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/10-103b%20Alor%20subdistricts%20relief%20colour.tif?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q12506903', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 3),
