  (9604, NULL, 1, 'Pulau Angso Duo', 'Pariaman Tengah', 'Pariaman, Sumatera Barat', 'Angso Duo adalah pulau kecil yang menjadi tujuan wisata di Kota Pariaman, Sumatera Barat. Pulau dengan luas 5,13 hektar ini terdiri dari hamparan pasir putih dan karang, serta pantainya tergolong landai. Dalam sejarahnya, kepemilikan pulau ini diwariskan oleh Kaum Rumah Gadang Pauh dari Raja Pagaruyung.', -0.6333333, 100.0986111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Angso%20Duo%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q97216009', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 3),
