  (9620, NULL, 1, 'Pulau Talise', 'Minahasa Utara', 'Talise, Sulawesi Utara', 'Pulau Talisei adalah sebuah pulau yang terletak di Kecamatan Likupang Barat, Kabupaten Minahasa Utara, Sulawesi Utara, Indonesia. Lokasi Pulau Talisei berjarak sekitar 60 km dari Kota Manado.', 1.843564, 125.075169, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Talisei%20dan%20Pulau%20Kinabuhutan.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24830634', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 2),
  (9621, NULL, 1, 'Pulau Marasende', 'Pangkajene dan Kepulauan', 'Pangkajene dan Kepulauan, Sulawesi Selatan', 'Marasende adalah nama sebuah pulau kecil berpenghuni yang berada di gugusan Kepulauan Kalukalukuang, perairan Selat Makassar dan secara administratif masuk pada wilayah Desa Marasende, Kecamatan Liukang Kalmas, Kabupaten Pangkajene dan Kepulauan, Sulawesi Selatan, Indonesia. Pulau Marasende memiliki wilayah seluas 1.916.810,2295700 m2. Secara astronomis, pulau ini terletak di titik koordinat 5°7′33.96″LS, 118°8′52.8″BT.\nPulau Marasende merupakan satu-satunya pulau yang termasuk dalam wilayah administratif Desa Marasende.', -5.123056, 118.148889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Marasende.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24879699', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 2),
