  (9623, NULL, 1, 'Pulau Bahuluang', 'Kepulauan Selayar', 'Bahuluang, Kepulauan Selayar, Sulawesi Selatan', 'Pulau Bahuluang (Ejaan Van Ophuijsen: Baoeloewang) adalah sebuah pulau kecil yang berada sebelah barat daya Pulau Selayar di gugusan Kepulauan Selayar, perairan Laut Flores dan secara administratif masuk pada wilayah Desa Bahuluang, Kecamatan Bontosikuyu, Kabupaten Kepulauan Selayar, Sulawesi Selatan, Indonesia. Secara astronomis, pulau yang memiliki pasir putih ini terletak di titik koordinat 6°28′49.449″LS, 120°25′39.645″BT. Jumlah penduduk di pulau ini adalah sekitar 326 jiwa pada tahun 2022 dan sebagian besar penduduk bermata pencaharian sebagai nelayan. Penghuni pertama pulau ini berasal dari suku Seram, Provinsi Maluku.', -6.480403, 120.427678, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20on%20a%20Small%20Island%20off%20the%20South-west%20Coast%20of%20Selayar%2C%20South%20Sulawesi%20%2815164521086%29.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q25016438', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 2),
  (9624, NULL, 1, 'Pulau Lapang', 'Alor', 'Blang Merang, Alor, Nusa Tenggara Timur', 'Pulau Lapang: Pulau di Kabupaten Alor, Nusa Tenggara Timur, Alor.', -8.225, 124.032219, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/10-103b%20Alor%20subdistricts%20relief%20colour.tif?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q15057361', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 2),
