  (9628, NULL, 1, 'Pulau Pam Iba', 'Raja Ampat', 'Saukabu, Raja Ampat, Papua Barat Daya', 'Pulau Pam Iba: Pulau di Kabupaten Raja Ampat, Papua Barat Daya, Raja Ampat.', -0.6539139, 130.2944361, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fam%20Island%2C%20ID%2C%20Sentinel-2.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q20190832', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9629, NULL, 1, 'Pulau Pelambak Besar', 'Aceh Singkil', NULL, 'Pulau Pelambak Besar: Pulau di Kabupaten Aceh Singkil, Aceh, Aceh Singkil.', 2.1747194, 97.4355556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Palambak%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24819298', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9630, NULL, 1, 'Pulau Sikandang', 'Aceh Singkil', 'Aceh Singkil, Aceh', 'Pulau Sikandang: Pulau di Kabupaten Aceh Singkil, Aceh, Aceh Singkil.', 2.300831, 97.310831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20banyak-sikandang.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q24821354', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9631, NULL, 1, 'Pulau Tengah', 'Riau', 'Siak, Riau', 'Pulau Tengah: Pulau di Riau, Riau.', 0.65464, 102.2073, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Pulau%20Besar%20Taman%20Nasional%20Zamrud.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q26758218', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9632, NULL, 1, 'Pulau Besar', 'Riau', 'Siak, Riau', 'Pulau Besar: Pulau di Danau Pulau Besar, Indonesia, Riau.', 0.65929, 102.2132, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danau%20Pulau%20Besar%20Taman%20Nasional%20Zamrud.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q26758219', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9633, NULL, 1, 'Pulau Beor', 'Indonesia', NULL, 'Pulau Beor adalah pulau di Indonesia.', -5.5718315, 132.5887654, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Topographic%20map%20of%20the%20Kai%20Islands-en.svg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q18616650', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 1),
  (9634, NULL, 1, 'Pulau Babi', 'Balikpapan', 'Kalimantan Timur', 'Pulau Babi: Pulau di kota Balikpapan, Kalimantan Timur, Indonesia, Balikpapan.', -1.280013, 116.808969, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulau%20Babi%20Balikpapan%20Kalimantan%20Timur.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q125503937', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 0),
  (9635, NULL, 1, 'Mios Kedwa', 'Raja Ampat', 'Raja Ampat, Papua Barat Daya', 'Mios Kedwa: Pulau di Kabupaten Raja Ampat, Papua Barat Daya, Raja Ampat.', -0.5675611, 130.2743944, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mios%20Kedwa%2C%20Miot%20Mangkintut%20Mkuni%2C%20Koruwoi%20Iba%2C%20and%20Koruwoi%20Munde%20Islands%20from%20Piaynemo%20Island%2C%20Papua%20Barat%2C%20ID.jpg?width=800', '2026-11-24 09:44:09', '2026-11-24 23:32:50', 'wd:Q115421871', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 0),
  (9636, NULL, 2, 'Gunung Kendang', 'Garut', 'Garut, Jawa Barat', 'Gunung Kendang adalah gunung berapi stratovolcano yang terletak di perbatasan kecamatan Kertasari, Kab. Bandung dan kecamatan Pasirwangi, Kab. Garut, Jawa Barat, Indonesia.', -7.23, 107.72, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20Gunung%20Karang%20TMnr%2060016534.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q675072', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 11),
  (9637, NULL, 2, 'Kelam', 'Kalimantan Barat', 'Sintang, Kalimantan Barat', 'Gunung Kelam adalah kubah granit yang terletak di Kalimantan Barat. Gunung ini memiliki tanaman endemik kantong semar dari spesies Nepenthes clipeata. Gunung Kelam membentang dari barat ke timur dengan ketinggian 1.002 mdpl merupakan sebongkah batu raksasa (monolit).', 0.0758, 111.6525, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Kelam%20Sintang.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q1092252', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 11),
  (9638, NULL, 2, 'Gunung Sago', 'Sumatera Barat', 'Tanah Datar, Sumatera Barat', 'Gunung Sago adalah sebuah Gunung yang terletak di perbatasan daerah kecamatan Lareh Sago Halaban, Luhak, Situjuh Lima Nagari, kabupaten Lima Puluh Kota dan Lintau Buo Utara, kabupaten Tanah Datar, provinsi Sumatera Barat, Indonesia. Gunung Sago adalah gunung berapi yang sudah tidak aktif, meskipun dulu sempat menjadi salah satu gunung aktif. Gunung Sago jika dilihat dari udara akan tampak memiliki kaldera besar yang dinamakan Kaldera Tingga.', -0.3269444, 100.6705556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Sago.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q5770007', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 11),
  (9639, NULL, 2, 'Gunung Argapura', 'Jawa Timur', 'Probolinggo, Jawa Timur', 'Gunung Argapura (sering dieja Gunung Argopuro) adalah sebuah gunung berapi kompleks yang terdapat di Jawa Timur, Indonesia. Gunung Argapura mempunyai ketinggian setinggi 3.088 meter. Gunung Argapura merupakan bekas gunung berapi yang kini sudah tidak aktif lagi.', -7.9645, 113.5665, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20vulkaan%20Argopuro%20TMnr%2020017909.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q2860906', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 10),
  (9640, NULL, 2, 'Gunung Puet Sague', 'Aceh', 'Pidie, Aceh', 'Gunung Peuet Sagoë adalah sebuah gunung berapi yang terletak di wilayah Geumpang, Kabupaten Pidie, Provinsi Aceh, Indonesia. Gunung ini menjulang tinggi dengan empat buah puncak.\nGunung ini memiliki ketinggian 2780 di atas permukaan laut dengan posisi geografis berada pada 4 0 - 55 1/2 0 Lintang Selatan dan 96 0 - 20 0 Bujur Timur.', 4.914, 96.329, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peuet%20Sague.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q3958173', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 10),
  (9641, NULL, 2, 'Gunung Suoh', 'Lampung', 'Jalan Lintas Sanggi Sukabumi Suoh, Dusun Sidorejo, Desa Sukamarga, Lampung', 'Gunung Suoh atau Gunung Suwoh adalah gunung yang memiliki kaldera dengan lebar 16x8km yang terdapat di bagian selatan  Lampung, Sumatra, Indonesia. Penurunan terjadi akibat aktivitas tektonik. Tercatat memiliki maar dan kubah lava.', -5.25, 104.27, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/DJI%200847%20kawah%20nirwana%20Suoh%20TNBBS.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q4178018', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 10),
  (9642, NULL, 2, 'Gunung Jailolo', 'Maluku Utara', 'Idamdehe Gamsungi, Halmahera Barat, Maluku Utara', 'Gunung Jailolo adalah sebuah gunung berapi yang terletak di Kabupaten Halmahera Barat, Provinsi Maluku Utara. Berdasarkan data PVMBG melalui webnya MAGMA Indonesia, gunung Jailolo tidak termasuk dalam gunung api Tipe A, B, maupun C. Di sebelah barat kerucut Gunung Jailolo atau juga disebut Kerucut Bobanehene terdapat sebuah kaldera yang merupakan sisa Gunung Jailolo tua yang sekarang dikenal dengan Kaldera Idamdehe. Lumpur panas dilaporkan dari Gunung Jailolo sesaat sebelum tahun 1883, tetapi tidak ada letusan yang diketahui selama waktu tersebut.', 1.0817, 127.4267, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jailolo.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q4180889', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 10),
  (9643, NULL, 2, 'Gunung Tujuh', 'Jambi', 'Dharmasraya, Sumatera Barat', 'Gunung Tujuh: Gunung di Indonesia, Jambi.', -1.6770639, 101.4274472, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tujuh1.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q825329', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 9),
  (9644, NULL, 2, 'Gunung Tondano', 'Sulawesi Utara', 'Minahasa, Parepei, Sulawesi Utara', 'Gunung Tondano adalah gunung yang terletak di Kota Tondano Sulawesi Utara Indonesia yang memiliki kawah dengan lebar 20 x 30 km yang terbentuk oleh letusan besar pada kala akhir Miosen atau awal Pliosen. Kerucut vulkanik, aliran obsidian, dan area geothermal diketahui terjadi di kaldera. Danau Tondano terletak di tepi timur kaldera.', 1.23, 124.83, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Tondano%20view%20from%20Bukit%20Kasih.JPG?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q2933735', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 9),
  (9645, NULL, 2, 'Gunung Abang', 'Bangli', 'Rendang, Bali', 'Gunung Abang  adalah sebuah gunung dengan ketinggian 2,151 m yang terletak di wilayah kabupaten Bangli, kecamatan Kintamani (di Desa Abangsongan), pulau Bali, Indonesia. Gunung Abang merupakan puncak ketiga tertinggi di pulau Bali setelah Gunung Agung dan Gunung Batukaru. Gunung ini merupakan tempat menarik bagi pelancong pendakian gunung yang aman untuk didaki, karena gunung berapi ini tidak aktif.', -8.2802, 115.4295, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Batur%20%26%20Mount%20Abang%202013-11-10%20%2810849153196%29.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q25017813', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 9),
  (9646, NULL, 2, 'Gunung Tarakan', 'Halmahera Utara', 'Seki, Halmahera Utara, Maluku Utara', 'Gunung api Tarakan terletak di kepulauan Halmahera, Indonesia, didekat Teluk Galela sebelah timur laut Gunung Api Dukono. Tarakan terdiri dari dua kerucut besar, bernama Tarakan Lamo (Tarakan besar) dan Tarakan Itji (Tarakan kecil).', 1.83, 127.83, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ternate%20Island.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q6924047', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 9),
  (9647, NULL, 2, 'Gunung Arfak', 'Papua Barat', 'Manokwari, Papua Barat', 'Gunung Arfak adalah titik tertinggi di provinsi Papua Barat. Gunung ini terletak di timur laut Semenanjung Doberai dan merupakan puncak tertinggi dari Pegunungan Arfak. Lanskap Kota Manokwari dapat terlihat dari puncak gunung ini.', -1.1563889, 133.9797222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pegunungan%20Arfak%20from%20the%20Pond%20of%20Rendani.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q7160827', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 9),
  (9648, NULL, 2, 'Pegunungan Sewu', 'Wonogiri', 'Karangwuni, Wonogiri, Jawa Tengah', 'Pegunungan Sewu atau Pegunungan Kidul adalah nama untuk deretan pegunungan yang terbentang memanjang di sepanjang pantai selatan Gunungkidul (Daerah Istimewa Yogyakarta), Wonogiri (Jawa Tengah), hingga Tulungagung (Jawa Timur) di wilayah selatan Pulau Jawa. Deretan pegunungan Sewu terbentuk karena pengangkatan dasar laut ribuan tahun silam. Batuan kapur menjadi ciri khas pegunungan ini.', -8.0438889, 110.7761111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Sewu.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q12504054', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 8),
  (9649, NULL, 2, 'Gunung Sumbing Jambi', 'Jambi', 'Merangin, Jambi', 'Gunung Sumbing adalah gunung berapi stratovolcano yang terletak di Kecamatan Jangkat, Kabupaten Merangin, Provinsi Jambi, Indonesia. Gunung berapi ini memiliki puncak yang terdapat kawah vulkanik dan danau kawah dengan lebar 180 meter.', -2.414, 101.728, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Sumbing%202013-09-18%20%2815854172378%29.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q1087196', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 8),
  (9650, NULL, 2, 'Puncak Jaya Wijaya', 'Mimika', 'Mimika, Papua Tengah', 'Puncak Jaya Wijaya: Gunung di Indonesia, Mimika.', -4.0833333, 137.2894444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Jaya%20icecap%201972.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q2940435', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 7),
  (9651, NULL, 2, 'Gunung Manglayang', 'Jawa Barat', 'Jalur Pendakian Gunung Manglayang via Batu Kuda, Cileunyi, Jawa Barat', 'Gunung Manglayang (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮙᮍᮣᮚᮀ) adalah sebuah gunung berapi kerucut non-aktif yang terletak di antara Kabupaten Bandung dan Kabupaten Sumedang, Jawa Barat, Indonesia dan memiliki ketinggian sekitar 1818 mdpl. Pemandangannya cukup indah, tetapi gunung ini relatif tidak terlalu tinggi, sehingga kurang dikenal oleh pendaki-pendaki gunung pada umumnya.\nDalam rangkaian Zona Bandung yang beranggotakan gunung-gunung peninggalan Gunung Sunda Purba yaitu Burangrang – Tangkuban Perahu – Palasari – Bukit Tunggul – Manglayang, gunung ini merupakan gunung yang terletak paling timur.', -6.8761111, 107.7436111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mont%20Manglayang.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q19728822', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 7),
  (9652, NULL, 2, 'Gunung Parang', 'Purwakarta', 'Purwakarta, Jawa Barat', 'Gunung Parang adalah gunung yang terletak di Kec. Salopa, Kab. Tasikmalaya dan Jayasari, Kab.', -6.5913889, 107.3466667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Parang.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q6922655', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 7),
  (9653, NULL, 2, 'Gunung Parahu', 'Jawa Tengah', 'Pranten, Batang, Jawa Tengah', 'Gunung Prau salah satu gunung di Dataran Tinggi Dieng, Jawa Tengah, Indonesia memiliki ketinggian puncak 2.590 mdpl dan terletak pada koordinat 7°11′13″S 109°55′22″E. Gunung ini merupakan tapal batas empat kabupaten di Jawa Tengah, yaitu Kabupaten Batang, Kabupaten Kendal, Kabupaten Temanggung dan Kabupaten Wonosobo.\nPuncak dari Gunung Prau merupakan padang rumput luas yang memanjang dari barat ke timur. Bukit-bukit dan sabana dengan sedikit pepohonan dapat dijumpai pada puncaknya.', -7.1869444, 109.9227778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Parahu%20in%20the%20Dieng%20Plateau.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q11215860', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9654, NULL, 2, 'Tanggamus', 'Lampung', 'Campang, Tanggamus, Lampung', 'Gunung Tanggamus (Abung: 𞜂𞜔𞜉𞜔𞜖𞜇𞜖𞜂𞜌𞜔𞜑𞜜) adalah sebuah gunung yang terletak di Kecamatan Kota Agung, Kabupaten Tanggamus, Provinsi Lampung, Indonesia. Gunung Tanggamus berada di sebelah timur laut dari Kota Agung dengan jarak sekitar 10 km. Gunung Tanggamus adalah gunung tertinggi kedua di Provinsi Lampung, setelah Gunung Pesagi.', -5.427, 104.675, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Tanggamus.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q11224465', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9655, NULL, 2, 'Gunung Masurai', 'Jambi', 'Merangin, Jambi', 'Gunung Masurai adalah gunung di pulau Sumatra, Indonesia. Gunung tak aktif ini secara administatif terletak dalam tiga wilayah kecamatan di kabupaten Merangin, Jambi, yakni kecamatan Lembah Masurai, Jangkat dan Sungai Tenang. Gunung Masurai diperuntukan sebagai kawasan hutan konservasi, yakni kawasan Taman Nasional Kerinci Seblat.', -2.5025302, 101.8580832, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mt%20Masurai%20%28201293087%29.jpeg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q12484774', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9656, NULL, 2, 'Gunung Perkison', 'Aceh', 'Aceh Tenggara, Aceh', 'Gunung Perkison adalah sebuah gunung yang terdapat di Kabupaten Aceh Tenggara, Provinsi Aceh, Indonesia. Jarak dari kota Kutacane, ibu kota Kabupaten Aceh Tenggara, sekitar 30 km ke arah barat laut.', 3.62225, 97.8583333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Gunung%20Perkison.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q47467', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9657, NULL, 2, 'Gunung Panderman', 'Jawa Timur', 'Lowokwaru, Kota Batu, Jawa Timur', 'Gunung Panderman adalah sebuah gunung di Kota Batu, Jawa Timur, Indonesia, dengan puncak Basundara yang berketinggian 2.045 mdpl.', -7.9041667, 112.4966667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mt.%20Panderman.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q12484805', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9658, NULL, 2, 'Gunung Todoko-Ranu', 'Maluku Utara', 'Halmahera Barat, Maluku Utara', 'Gunung Todoko-Ranu adalah kompleks kaldera kembar di Pulau Halmahera, Indonesia. Kaldera Todoko berisi lava dan memiliki lebar 2 km yang terletak di selatan kaldera Ranu yang memiliki Kerucut vulkanik sahu dengan lebar 2,8 km. Di utara kaldera Ranu terdapat danau kaldera.', 1.25, 127.47, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Todoko-Rano.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q4180752', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9659, NULL, 2, 'Lokon-Empung', 'Tomohon', 'Tomohon, Sulawesi Utara', 'Lokon-Empung: Gunung di Indonesia.', 1.358, 124.791, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tompaluan130910.JPG?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q6668748', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 6),
  (9660, NULL, 2, 'Gunung Kemul', 'Indonesia', 'Malinau, Kalimantan Utara', 'Gunung Kemul (alias Kemoel, Kemal, Kongkemul, Kong Kemul) adalah gunung di Kalimantan Timur. Di Gunung Kemul terdapat spesies lokal, yaitu spesies pitcher plant Nepenthes fusca dan Nepenthes mollis.', 1.8602778, 116.1763889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Kongkemul.png?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q1093279', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 5),
  (9661, NULL, 2, 'Gunung Ranai', 'Kepulauan Riau', 'Ranai, Kepulauan Riau', 'Gunung Ranai adalah gunung yang terletak di Pulau Bunguran, Kabupaten Natuna, Provinsi Kepulauan Riau, Indonesia.\nGunung Ranai merupakan gunung dataran rendah, sebab ketinggiannya berkisar antara 300—1.035 meter di atas permukaan laut (mdpl). Meskipun demikian, para pelancong yang mendaki gunung ini akan menemukan fenomena menarik, yaitu gradasi jenis-jenis tanaman dari hutan dataran rendah hingga hutan dataran atas.', 3.9608, 108.3433, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Ranai%20in%20Natuna.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q11220511', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 5),
  (9662, NULL, 2, 'Gunung Andong', 'Jawa Tengah', 'Prajeksari, Magelang, Jawa Tengah', 'Gunung Andong adalah sebuah gunung tipe perisai yang terletak di Ngawi Selatan, Provinsi Jawa Tengah, Indonesia. Gunung ini memiliki ketinggian 1.726 meter di atas permukaan laut dan dikenal sebagai destinasi pendakian populer, terutama bagi pendaki pemula karena jalurnya yang relatif pendek dan menanjak secara stabil.', -7.52852, 110.18365, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pagi%20Di%20Puncak%20Gunung%20Andong.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q12484663', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 5),
  (9663, NULL, 2, 'Gunung Sanggabuana', 'Indonesia', 'Tanjungsari, Jawa Barat', 'Gunung Sanggabuana (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮞᮀᮌᮘᮥᮃᮔ) adalah gunung yang terdapat dalam wilayah Kabupaten Karawang dan Kabupaten Bogor. Secara administratif, gunung ini berada di Kecamatan Tegalwaru, Karawang dan Tanjungsari, Jonggol.\nSaat ini, kawasan pegunungan Sanggabuana sedang dalam proses menjadi kawasan konservasi berupa taman nasional.', -6.59083, 107.22056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanggabuana%20Pacet%202022%2000.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24843709', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 4),
  (9664, NULL, 2, 'Pegunungan Fakfak', 'Indonesia', 'Fakfak, Papua Barat', 'Pegunungan Fakfak: Gunung di Indonesia.', -2.8328, 132.3332, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BirdsHeadPeninsula%20Topo.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24965778', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 4),
  (9665, NULL, 2, 'Gunung Sipiso-piso', 'Sumatera Utara', 'Negeri Tongging, Kabupaten Karo, Sumatera Utara', 'Gunung Sipiso - piso atau kerap juga disebut dengan nama Gunung Tanduk banua adalah salah satu gunung di Indonesia. Gunung ini terletak di Provinsi Sumatera Utara, di bagian barat negara tersebut, berjarak 1.400 km arah barat laut Jakarta (ibu kota negara Indonesia). Gunung Sipiso - piso terletak 1.940 meter di atas permukaan laut, atau 497 meter di atas ketinggian rata-rata daerah sekitarnya .', 2.9258333, 98.5347222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Sipiso%20piso%20tampak%20keseluruhan%20hingga%20puncak.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q26732088', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 4),
  (9666, NULL, 2, 'Merapi (Ijen)', 'Bondowoso', 'Banyuwangi, Jawa Timur', 'Merapi (Ijen): Gunung di Indonesia, Bondowoso.', -8.0627, 114.262, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ijen%20Merapi%20Kawah%20Ijen.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q3306249', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9667, NULL, 2, 'Gunung Halau-halau', 'Kalimantan Selatan', 'Hulu Sungai Tengah, Kalimantan Selatan', 'Gunung Halau-Halau, yang juga dikenal sebagai Gunung Besar, adalah sebuah gunung yang terletak di perbatasan tiga kabupaten di Provinsi Kalimantan Selatan, Indonesia, yaitu Kabupaten Hulu Sungai Tengah, Kabupaten Hulu Sungai Selatan, dan Kabupaten Tanah Bumbu.', -2.709895, 115.625761, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20halau-halau.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q10949069', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9668, NULL, 2, 'Gunung Gajah', 'Pemalang', 'Gongseng, Pemalang, Jawa Tengah', 'Gunung Gajah adalah sebuah gunung di Pemalang Jawa Tengah, yang secara administrasi terletak di Desa Gongseng, Kecamatan Randudongkal, Kabupaten Pemalang. Gunung ini tidak termasuk gunung aktif, melainkan berbentuk bukit batu besar yang menjulang serta ditumbuhi bermacam tanaman di atasnya. Pada puncak gunung ini terdapat goa kecil yang bernama Gua Lawa.', -7.0007373, 109.2989162, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pesona%20gunung%20gajah%20pemalang.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q12484702', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9669, NULL, 2, 'Puncak Lawang', 'Agam', 'Agam, Sumatera Barat', 'Puncak Lawang adalah salah satu objek wisata alam yang terletak di dataran tinggi di Nagari Lawang, Kecamatan Matur, Kabupaten Agam, Sumatera Barat. Keindahan Puncak Lawang ditandai dengan birunya alam Danau Maninjau serta rindangnya pohon pinus dan udara yang sejuk. Keindahan danaunya dapat dilihat dari ketinggian 1.210 mdpl di puncak tertinggi, yaitu Nagari Lawang.', -0.2636503, 100.2429594, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Lawang.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q19747274', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9670, NULL, 2, 'Gunung Bukit Raya', 'Indonesia', 'Serawai, Sintang, Kalimantan Barat', 'Gunung Bukit Raya  adalah sebuah gunung yang terletak di Kabupaten Katingan, Provinsi Kalimantan Tengah. Gunung ini adalah gunung tertinggi di Kalimantan yang masuk dalam wilayah Indonesia. Kawasan sekitar Bukit Raya menjadi cagar alam, dan bersama-sama dengan Cagar Alam Bukit Baka di Kalimantan Barat merupakan Taman Nasional Bukit Baka-Bukit Raya.', -0.483333, 112.6, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Bukit%20Raya.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q19942574', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9671, NULL, 2, 'Gunung Endut', 'Lebakgedong', 'Lebakgedong, Banten', 'Gunung Endut adalah sebuah gunung di Kabupaten Lebak, Provinsi Banten, Indonesia. Gunung Endut merupakan salah satu gunung tertinggi di Provinsi Banten dengan memiliki ketinggian mencapai 1.207 Mdpl. Gunung Endut secara administratif termasuk ke Kecamatan Cipanas, Kecamatan Lebakgedong, Kecamatan Muncang dan Kecamatan Sobang dan termasuk ke dalam kawasan Taman Nasional Gunung Halimun Salak (TNGHS).', -6.6204, 106.3623, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Endut%20dilihat%20dari%20Harumsari.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24965616', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9672, NULL, 2, 'Gunung Cakrabuana', 'Garut', 'Garut, Jawa Barat', 'Gunung Cakrabuana (Aksara Sunda Baku: ᮌᮥᮔᮥᮀ ᮎᮊᮢᮘᮥᮝᮔ, Latin: Gunung Cakrabuwana) adalah gunung di Jawa Barat dengan ketinggian 1721 mdpl dan koordinat 7°2\'7"S 108°7\'51"E. Menjadi tapal batas antara 3 kabupaten yaitu Kabupaten Garut, Kabupaten Tasikmalaya, dan Kabupaten Majalengka.', -7.0422, 108.1392, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/KITLV%20A686%20-%20Vlakte%20rond%20Malangbong%20bij%20Garoet%2C%20op%20de%20achtergrond%20de%20Tjakraboewana%2C%20KITLV%2081157.tiff?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24989451', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9673, NULL, 2, 'Gunung Bayangkaki', 'Jawa Timur', 'Sawo, Jawa Timur', 'Gunung Bayangkaki adalah nama salah satu gunung yang ada di wilayah Kabupaten Ponorogo. Tepatnya Gunung Bayangkaki terletak di Kecamatan Sawoo, Kabupaten Ponorogo. Gunung ini membatasi wilayah Ponorogo dan Trenggalek.', -7.9469444, 111.6019444, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Bayang%20Kaki%20Sebelum%20Bendungan%20Bendo%20Dibangun%20%282015%29.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q25255108', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 3),
  (9674, NULL, 2, 'Table Mountain', 'Indonesia', 'Sandaun', 'Table Mountain: Gunung di Indonesia.', -4.5569444, 141.1311111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manokwari.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q7673144', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9675, NULL, 2, 'Mount Tamata', 'Sulawesi Utara', 'Bahu, Kepulauan Siau Tagulandang Biaro, Sulawesi Utara', 'Mount Tamata: Gunung di Indonesia, Sulawesi Utara.', 2.7188, 125.38, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Tamata.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24830658', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9676, NULL, 2, 'Gunung Penanjakan', 'Probolinggo', 'Pasuruan, Jawa Timur', 'Gunung Penanjakan atau bisa juga disebut Pananjakan adalah salah satu gunung yang terdapat di Taman Nasional Bromo Tengger Semeru, Pasuruan, Jawa Timur, Indonesia. Gunung Penanjakan lebih diidentikan dengan sebutan Penanjakan 1 yang biasa dijadikan sebagai lokasi pandang untuk melihat Gunung Bromo, karena ketinggiannya di atas Gunung Bromo yang hanya memiliki ketinggian 2329 mdpl. Dari Gunung Penanjakan dapat terlihat lautan pasir luas beserta Gunung Bromo di tengahnya, lalu juga terlihat Gunung Batok, Gunung Kursi dan Gunung Semeru.', -7.8993214, 112.9492285, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Penanjakan%20%28Bromo-Tengger-Semeru%29%20at%20sunrise.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q24847226', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9677, NULL, 2, 'Pasir Pangonan', 'Jawa Barat', 'Sumedang, Jawa Barat', 'Pasir Pangonan: Gunung di Indonesia, Jawa Barat.', -6.8388889, 107.8041667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Pangonan%2C%20Dieng%2029092016.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q25161404', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9678, NULL, 2, 'Gunung Pengsong', 'Nusa Tenggara Barat', 'Kuranji, Lombok Barat, Nusa Tenggara Barat', 'Gunung Pengsong adalah sebuah bukit yang terletak di desa Kuranji,  Labuapi, Kabupaten Lombok Barat.', -8.6427778, 116.0875, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Pengsong1.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q25287267', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9679, NULL, 2, 'Gunung Batu Jonggol', 'Indonesia', NULL, 'Gunung Batu merupakan sebuah gunung yang terdapat di Desa Sukaharja, Sukamakmur, Bogor, Jawa Barat, Indonesia. Gunung Batu Ini mempunyai ketinggian setinggi 875 Mdpl atau sekitar 2.871 kaki. Banyak Orang mengenal Gunung ini dengan sebutan Gunung Batu Jonggol meski secara Administratif Gunung ini masuk dalam kecamatan Sukamakmur lebih tepatnya di Desa Sukaharja, Sukamakmur, Kabupaten Bogor.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Batu%20-%20Sukamakmur.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q25466302', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9680, NULL, 2, 'Gunung Taliut', 'Kalimantan Selatan', 'Tanah Bumbu, Kalimantan Selatan', 'Gunung Taliut adalah sebuah gunung dan kawasan karst yang menjadi objek wisata alam di Desa Teluk Kepayang, Kecamatan Teluk Kepayang, Kabupaten Tanah Bumbu, Provinsi Kalimantan Selatan, Indonesia.', -3.4034904, 115.6433838, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Taliut.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q132205267', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9681, NULL, 2, 'Gunung Birah', 'Kalimantan Selatan', 'Kandangan Lama, Tanah Laut, Kalimantan Selatan', 'Bukit Birah (Gunung Birah) adalah bukit yang terletak di Desa Kandangan lama, Kecamatan Panyipatan, Kabupaten Tanah Laut, Kalimantan Selatan. Luas kawasan Bukit Birah adalah 1.589,02 ha dengan puncak tertingginya adalah 367 mdpl.\nBukit Birah memiliki sejarah yang berkaitan dengan perjuangan penduduk melawan penjajah dimana tempat ini menjadi lokasi keluar masuk warga.', -4.0406636, 114.6737192, 20000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Birah%2C%20Tanah%20Laut.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q135978381', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9682, NULL, 2, 'Gunung Bisma', 'Jawa Tengah', 'Sikunang, Wonosobo, Jawa Tengah', 'Gunung Bismo atau Gunung Bisma adalah sebuah gunung yang berada di Kabupaten Wonosobo, Provinsi Jawa Tengah. Gunung Bisma masih berada di Pegunungan Komplek Gunung Api Dieng. Secara Administrasi, Gunung Bisma terletak di Kabupaten Wonosobo.', -7.238525, 109.890884, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Bisma.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q28724780', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9683, NULL, 2, 'Bukit Kabut', 'Jambi', 'Kerinci, Jambi', 'Bukit Kabut: Bukit di Indonesia, Jambi.', -1.9161111, 101.4833333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kerinciku.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q32546646', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 2),
  (9684, NULL, 2, 'Gunung Pantai Cermin', 'Indonesia', NULL, 'Gunung Pantai Cermin,Salah satu gunung di Sumatera Barat dalam kawasan bukit barisan,Lokasinya di perbatasan Kabupaten Solok dengan Kabupaten Pesisir Selatan.Gunung ini belum banyak di daki orang,karena belum banyak yang mengetahuinya.Jalur pendakiannya dari Jorong Koto Tinggi, Nagari Surian, Kecamatan Pantai Cermin, Kabupaten Solok.\nGunung Pantai Cermin bukanlah tujuan populer bagi para pejalan kaki, dan mungkin karena ini jalan setapaknya bersih dari sampah, ada tanaman Kantong Semar yang tumbuh tanpa gangguan di punggung bukit yang lebih tinggi, dan setidaknya satu dari sedikit Harimau Sumatera di bagian ini pula mengintai mangsanya di lereng gunung yang lebih rendah. Ada sangat sedikit pemandangan yang layak karena hutannya yang lebat, tetapi karena jalurnya sangat terdefinisi dengan baik, ini membuat tamasya yang bagus jika Anda sudah melakukan puncak Sumatera Barat yang lebih populer.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantaicermin%20019.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q121592855', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9685, NULL, 2, 'Bunder', 'Bogor', 'Gunung Bunder 2, Pamijahan, Jawa Barat', 'Bunder: Gunung di kaki Gunung Salak, Jawa Barat, Indonesia, Bogor.', -6.6810278, 106.6850528, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Bunder%20vegetation%20and%20road.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q125767106', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
