  (9687, NULL, 2, 'Gunung Gadung', 'Jawa Timur', 'Andongrejo, Jember, Jawa Timur', 'Gunung Gadung: Gunung di Indonesia, Jawa Timur.', -8.4, 113.7716667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Franz%20Wilhelm%20Junghuhn%20-%20Gunung%20Gamping%20-%20Tafel.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q26742274', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
