  (9689, NULL, 2, 'Gunung Lojeh', 'Jawa Timur', 'Sukokidul, Trenggalek, Jawa Timur', 'Gunung Lojeh: Gunung di Indonesia, Jawa Timur.', -8.0561111, 111.5711111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Lojeh%2C%20Sokokidul%20-%20panoramio.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q26743995', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9690, NULL, 2, 'Gunung Bintan', 'Bintan', 'Bintan, Kepulauan Riau', 'Gunung Bintan merupakan salah satu gunung yang lebih menyerupai bentuk bukit terletak di Pulau Bintan, Kepulauan Riau. Gunung Bintan ini memiliki ketinggian hanya sekitar 400 m di atas permukaan laut, hal itu merupakan alasan mengapa Gunung Bintan ini terlihat seperti bukit. Gunung Bintan menjadi tempat wisata yang cocok bagi mereka yang penyuka gunung, hutan dan olahraga di alam terbuka.', 1.0718784, 104.4566372, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Bintan%20yang%20tidak%20aktif%20lagi.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q97307795', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9691, NULL, 2, 'Gunung Kulabu', 'Pasaman', 'Pasaman, Sumatera Barat', 'Gunung Kulabu adalah sebuah Gunung yang terletak di perbatasan Sumatera Barat dan sumatera Utara tepatnya di Kabupaten Pasaman, Provinsi Sumatera Barat, dan Kabupaten Mandailing Natal, Sumatera Utara, Indonesia yang memiliki ketinggian 2179 meter, atau setara dengan 7149 kaki.  Dataran tinggi berbentuk Gunung yang bernama Gunung Kulabu ini masih belum tereksplor secara luas, karena minimnya aktivitas pendakian ke sana. Padahal sebenarnya keindahan alam yang disajikan oleh Gunung Kulabu tidak kalah indahnya dari gunung-gunung lain di dunia.', 0.466667, 99.9, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunung%20Kulabu%20Sumatera.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q97308106', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9692, NULL, 2, 'Pahwuwi', 'Indonesia', 'Batu Merah, Maluku Barat Daya, Maluku', 'Pahwuwi adalah gunung di Indonesia.', -7.1000409, 128.5992622, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Damar%20Islands%20de.png?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q15058343', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9693, NULL, 2, 'Mount Ranti', 'Indonesia', NULL, 'Mount Ranti adalah gunung di Indonesia.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ijen%2C%20Mount%20Ranti%2C%20East%20Java%2C%20Indonesia%2C%2020220821%200645%209780.jpg?width=800', '2026-11-24 09:44:36', '2026-11-24 23:32:50', 'wd:Q115282759', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Gunung', 1),
  (9694, NULL, 2, 'Bukit Bego', 'Bantul', 'Jalan Imogiri - Dlingo, Imogiri, Daerah Istimewa Yogyakarta', 'Bukit Bego (bahasa Jawa: ꦥꦸꦤ꧀ꦛꦸꦏ꧀ꦧꦺꦒꦺꦴ, translit. Punthuk Bégo) atau Bukit Kedung Buweng adalah destinasi wisata berupa bukit sisa proyek penggalian tanah yang terletak di Jalan Imogiri–Dlingo, Dusun Kedung Buweng, Kalurahan Wukirsari, Kapanewon Imogiri, Kabupaten Bantul, Provinsi Daerah Istimewa Yogyakarta. Bukit tersebut menjadi populer di Kabupaten Bantul karena sering dikunjungi oleh para muda-mudi pecinta fotografi dan pesepeda untuk berfoto dan beristirahat.', -7.9257878, 110.4030391, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Bego%20%281%29.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q105653198', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 4),
  (9695, NULL, 2, 'Gunung Padang', 'Padang', 'Padang, Sumatera Barat', 'Gunung Padang atau Bukit Sitti Nurbaya adalah bukit kecil dengan ketinggian puncak sekitar 80 mdpl yang terletak di muara Batang Arau dan termasuk dalam wilayah Kecamatan Padang Selatan, Kota Padang, Sumatera Barat. Masyarakat Kota Padang menamainya Gunung Padang karena bukit ini bisa dikatakan tempat tertinggi di sekitar pusat Kota Padang. \nDi Gunung Padang  terdapat Taman Siti Nurbaya dan peninggalan sejarah pendudukan Jepang.', -0.9650278, 100.3489167, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Padang%20dan%20Gunung%20Padang%20Nov%202019.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q12687295', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 3),
  (9696, NULL, 2, 'Bukit Tangkiling', 'Tangkiling', 'Palangka Raya, Kalimantan Tengah', 'Bukit Tangkiling adalah sebuah bukit yang memiliki tinggi 197 meter di atas permukaan laut. Bukit ini juga merupakan salah satu tujuan destinasi pariwisata alam yang ada di Kota Palangka Raya. Bukit ini berada di Kelurahan Banturung, Kecamatan Bukit Batu, Kota Palangka Raya, Provinsi Kalimantan Tengah, Indonesia.', -1.9881028, 113.7504103, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Tangkiling%20dari%20Jalan%20Tjilik%20Riwut%20km%2033%20%2820260117%20103810%29.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q98974293', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 3),
  (9697, NULL, 2, 'Bukit Holbung', 'Sumatera Utara', 'Hariara Pohan, Samosir, Sumatera Utara', 'Bukit Holbung (Bahasa Batak: Dolok Holbung; Surat Batak: ᯑᯬᯞᯬᯂ᯲ ᯂᯬᯞ᯲ᯅᯮᯰ) adalah salah satu tempat wisata di Danau Toba yang terletak perbukitan di Desa Holbung, Kecamatan Sitiotio, Kabupaten Samosir, Sumatera Utara.\nRangkaian perbukitan Bukit Holbung ini sudah ada sejak 200 tahun yang lalu.', 2.5299856, 98.6946109, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Holbung-2.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q109439283', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 3),
  (9698, NULL, 2, 'Bukit Gajah Bobok', 'Sumatera Utara', 'Tongging, Kabupaten Karo, Sumatera Utara', 'Bukit Gajah Bobok adalah salah satu bukit yang terletak di Pangambaten, Merek, Karo provinsi Sumatera Utara. Bukit ini memiliki ketinggian sekitar 1.200 meter di atas permukaan laut. Di sekitarnya terdapar hamparan sabana yang hijau; tetapi ketika musim panas tiba, areanya didominasi dengan hamparan rumput dengan warna kuning keemasan.', 2.8990516, 98.508302, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukut%20paling%20Tinggi%20di%20gajah%20Bobok%20Bagian%20Kaki.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q128898966', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 3),
  (9699, NULL, 2, 'Panorama Puncak Batudindiang', 'Tabek Patah', 'Tanjuang Alam, Tanah Datar, Sumatera Barat', 'Panorama Puncak Batudindiang: Objek wisata yang berada di Kabupaten Tanah Datar, Sumatera Barat, Tabek Patah.', -0.3437866, 100.5062359, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batu%20Badindiang%2014.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q137438992', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9700, NULL, 2, 'Bukit Kerang', 'Aceh Tamiang', 'Cintaraja, Aceh Tamiang, Aceh', 'Bukit Remis Pangkalan atau juga dikenal dengan nama Situs Bukit Kerang Pangkalan adalah sebuah situs masa prasejarah berburu dan mengumpulkan makanan yang berlokasi di Kabupaten Aceh Tamiang, Provinsi Aceh. Situs ini terbentang lebih dari 300 km dari wilayah Kabupaten Batu Bara, Sumatera Utara hingga Lhokseumawe.  \nPeninggalan yang terdapat di bukit tersebut adalah kjokkenmoddinger atau sejenis kerang atau remis.', 4.3913624, 98.180189, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Kerang%20in%20Aceh%20Tamiang%2C%20Aceh.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q4986910', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9701, NULL, 2, 'Bukit Jaka Tua', 'Karimunjawa', 'Kemloko, Jepara, Jawa Tengah', 'Bukit Joko Tuo adalah bukit yang terletak di Karimunjawa. Untuk menuju Bukit Joko Tuo, pengunjung dapat menggunakan sepeda motor atau mobil, dapat pula dengan berjalan kaki sekitar 20 menit dari dermaga.', -5.8746111, 110.4373278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Batu%20huruf%20di%20Bukit%20Joko%20Tuo.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q19745600', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9702, NULL, 2, 'Puncak Gagoan', 'Paninggahan', 'Paninggahan, Solok, Sumatera Barat', 'Puncak Gagoan: Wisata yang ada di Kabupaten Solok, Paninggahan.', -0.674141, 100.508924, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puncak%20Gagoan%2022.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q97214446', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9703, NULL, 2, 'Bukit Mamake', 'Kotabaru', 'Jalan Bukit Mamake SJA Hills, Kotabaru, Kalimantan Selatan', 'Bukit Mamake adalah sebuah bukit yang berlokasi di Kabupaten Kotabaru, Provinsi Kalimantan Selatan, Indonesia. Bukit ini menjadi tujuan wisata andalan di Kabupaten Kotabaru karena menawarkan pemandangan keindahan laut dan perbukitan dalam satu tempat. Selain menampilkan pemandangan ibu kota Kabupaten Kotabaru dari ketinggian, pengunjung juga dapat menikmati pemandangan Gunung Sebatung, gunung tertinggi di Pulau Laut Kotabaru.', -3.24324, 116.26043, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Mamake%20SJA%20Hill%20002.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q132142772', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9704, NULL, 2, 'Bukit Timah', 'Kalimantan Selatan', 'Jalan Raya Pelaihari - Batakan, Tanjung Dewa, Tanah Laut, Kalimantan Selatan', 'Bukit Timah adalah bukit kecil di Desa Tanjung Dewa, Kecamatan Panyipatan, Kabupaten Tanah Laut, Kalimantan Selatan, Indonesia. Bukit yang telah dikembangkan sebagai destinasi wisata alam sederhana ini terletak sekitar 45 kilometer dari Pelaihari, ibu kota kabupaten, dan berjarak dekat dengan Pantai Batakan, menjadikannya titik singgah yang praktis bagi pengunjung pantai yang ingin menikmati pemandangan lebih luas.', -4.0659826, 114.641182, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukit%20Timah%20Batakan%20002.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q133893391', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9705, NULL, 2, 'Bukit Aua Sarumpun', 'Tanah Datar', 'Aur Serumpun MTB, Pasia Jaya, Tanah Datar, Sumatera Barat', 'Bukit Aua Sarumpun: Bukit di tepi Danau Singkarak, Tanah Datar.', -0.54267, 100.54342, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aua%20Sarumpun%2009.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q135988874', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9706, NULL, 2, 'Bukik Bulek Taram', 'Indonesia', 'Taram, Lima Puluh Kota, Sumatera Barat', 'Bukik Bulek Taram terletak di Nagari Taram, Kecamatan Harau, Kabupaten Lima Puluh Kota, Sumatera Barat, Indonesia. Lokasinya berjarak 11,5 kilometer dari Kota Payakumbuh. Dinamakan Bukik Bulek karena bentuk bukit ini yang menonjol berbentuk lonjong dan berdiri sendiri di kawasan rawa-rawa yang datar.', -0.21265, 100.69925, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bukik%20Bulek%20IMG%204240.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q79006951', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 2),
  (9707, NULL, 2, 'Bukit Sikunir', 'Jawa Tengah', 'Sembungan, Wonosobo, Jawa Tengah', 'Bukit Sikunir: Bukit di Wonosobo Indonesia, Jawa Tengah.', -7.2391303, 109.9242895, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunrise%20Silhouette%20over%20Sikunir%20Hill.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q25151663', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 1),
  (9708, NULL, 2, 'Budug Asu', 'Malang', 'Kabupaten Malang, Jawa Timur', 'Budug Asu: Bukit di Kabupaten Malang, Jawa Timur, Malang.', -7.8062067, 112.6192034, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/250525%20Papan%20penanda%201422%20mpdl%20Pendakian%20Budug%20Asu.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q134572826', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 1),
  (9709, NULL, 2, 'Bukit Sibeabea', 'Sumatera Utara', 'Janji Martahan, Samosir, Sumatera Utara', 'Bukit Sibeabea adalah bukit di Sumatera Utara.', 2.550241, 98.671705, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pemandangan%20Dari%20Bukit%20Sibea%20Bea.jpg?width=800', '2026-11-24 09:44:52', '2026-11-24 23:32:50', 'wd:Q136734940', 'wikidata', 'Apr–Okt (musim kemarau), mulai dini hari', 'Bukit', 1),
  (9710, NULL, 4, 'Museum Rekor Dunia Indonesia', 'Jawa Tengah', 'Jalan Jenderal Anton Sujarwo, Banyumanik, Kota Semarang, Jawa Tengah', 'Museum Rekor Indonesia atau MURI adalah sebuah museum yang terletak di Semarang, Jawa Tengah, Indonesia yang didirikan pada 27 Januari 1990 oleh Jaya Suprana. Di dalam Museum Rekor Indonesia terdapat sekitar 8.448 rekor hingga Mei 2018.', -7.0691667, 110.4111111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20muri%20021.png?width=800', '2026-11-24 09:47:57', '2026-11-24 23:32:50', 'wd:Q2469088', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9711, NULL, 4, 'Museum Kapal Samudraraksa', 'Borobudur', 'Jalan Salaman - Mungkid, Borobudur, Jawa Tengah', 'Museum Samudra Raksa atau Museum Kapal Samudraraksa adalah museum bahari yang terletak dalam Taman Wisata Candi Borobudur. Lokasi Museum Samudra Raksa masuk dalam wilayah Kecamatan Borobudur, Kabupaten Magelang. Museum ini menampilkan jalur perdagangan bahari antara Indonesia purba, Madagaskar, dan pesisir Afrika Timur, yang mahsyur dijuluki "Jalur Kayumanis".', -7.6047222, 110.2033333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kapal%20Samudraraksa.jpg?width=800', '2026-11-24 09:47:57', '2026-11-24 23:32:50', 'wd:Q7410684', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9712, NULL, 4, 'Museum Trowulan', 'Candi Trowulan', 'Trowulan, Jawa Timur', 'Pusat Informasi Majapahit (PIM) atau yang lebih dikenal dengan Museum Trowulan adalah museum arkeologi yang terletak di Trowulan, Mojokerto, Jawa Timur, Indonesia. Museum ini dibangun untuk menyimpan berbagai artefak dan temuan arkeologi yang ditemukan di sekitar Trowulan. Tempat ini adalah salah satu lokasi bersejarah terpenting di Indonesia yang berkaitan dengan sejarah kerajaan Majapahit.', -7.56, 112.3808333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/032%20Artefacts%2C%20Museum%20Mojopahit%20%2840386063522%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q7846697', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9713, NULL, 4, 'Gedung Joang \'45', 'Jakarta', 'Jalan Gang Tembok, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Gedung Joang \'45 atau Museum Joang 45 adalah salah satu museum yang berada di Jakarta. Museum ini awalnya dikelola oleh Unit Pengelola Museum Kesejarahan Jakarta, dan selanjutnya untuk  saat ini pengelolaannya dilaksanakan oleh Dinas Kebudayaan Provinsi DKI Jakarta. Museum ini terletak di Jalan Menteng Raya 31, Kelurahan Kebon Sirih, Kecamatan Menteng, Jakarta Pusat.', -6.18587, 106.83655, 5000, ' 08.00–16.00; Jum 08.00–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Joang%2045.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q11042914', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9714, NULL, 4, 'Museum Pusat TNI AU Dirgantara Mandala', 'Yogyakarta', 'Jalan Lettu Tpt Sapardal, Banguntapan, Daerah Istimewa Yogyakarta', 'Museum Pusat TNI AU "Dirgantara Mandala" atau Museum Pesawat Terbang adalah museum gagasan TNI Angkatan Udara dan berisikan benda-benda koleksi sejarah, di mana sebagian besar berupa pesawat terbang yang pernah mengabdikan diri di lingkungan TNI AU. Museum ini berlokasi kurang lebih 6 kilometer arah timur dari pusat Kota Yogyakarta, yaitu di kompleks Pangkalan Udara Adi Sutjipto, Kec. Banguntapan, Kabupaten Bantul, Daerah Istimewa Yogyakarta. Sebelumnya, museum ini berada berada di Jalan Tanah Abang Bukit, Jakarta.', -7.790362, 110.417379, 8500, ' 08.30–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ruang%20Pamer%20Museum%20Pusat%20TNI%20AU%20Dirgantara%20Mandala.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q13095241', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 6),
  (9715, NULL, 4, 'Museum Kereta Api Sawahlunto', 'Lembah Segar', 'Jalan Saka Ombilin, Saringan, Sawahlunto, Sumatera Barat', 'Museum Kereta Api Sawahlunto (bahasa Inggris: Sawahlunto Rail and Train Museum atau Stasiun Sawahlunto Biofarma sebagai pemegang hak penamaan) adalah Stasiun kereta api kelas II yang juga menjadi museum sejarah perkeretaapian. Museum ini secara administratif terletak di Pasar, Lembah Segar, Sawahlunto. Museum ini termasuk dalam Divisi Regional II Sumatera Barat dan dikelola oleh Unit Pusat Pelestarian dan Desain Arsitektur PT KAI bekerja sama dengan Pemerintah Kota Sawahlunto.', -0.6829139, 100.7769461, 3000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kereta%20Api%20Sawahlunto%202018.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q3140705', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9716, NULL, 4, 'Museum "Waja Sampai Kaputing"', 'Kalimantan Selatan', 'Jalan Museum Perjuangan, Banjarmasin Utara, Banjarmasin, Kalimantan Selatan', 'Museum Waja Sampai Kaputing atau Museum Wasaka adalah sebuah museum perjuangan rakyat Kalimantan Selatan. Arti dari Waja Sampai Kaputing sendiri yaitu "perjuangan yang tidak berhenti hingga tetes darah penghabisan", di mana kalimat ini merupakan motto perjuangan rakyat Kalimantan Selatan.\nMuseum ini terletak di Kompleks H. Andir, Kampung Kenanga Ulu, Kelurahan Sungai Jingah, Kecamatan Banjarmasin Utara, Kota Banjarmasin.', -3.30362, 114.60907, 0, 'Jum 09.00–11.00;  09.00–12.30;  09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Waja%20Sampai%20Kaputing.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q3606131', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9717, NULL, 4, 'Museum Rumah Kelahiran Buya Hamka', 'Agam', 'Batu Panjang, Agam, Sumatera Barat', 'Museum Rumah Kelahiran Buya Hamka adalah museum yang terletak di sekitar tepian Danau Maninjau, tepatnya di Jl. H. Oedin Rahmani,Nagari Sungai Batang, Kecamatan Tanjung Raya, Kabupaten Agam, Sumatera Barat. Museum ini mulai dibangun pada tahun 2000 dan diresmikan pada tahun 2001 oleh Gubernur Sumatera Barat waktu itu, Zainal Bakar.', -0.3557778, 100.2182778, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rumah%20Kelahiran%20Buya%20Hamka.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q4205496', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9718, NULL, 4, 'Museum Balanga', 'Kalimantan Tengah', 'Jalan Tjilik Riwut No.Km 2.5, Palangka, Palangka Raya, Kalimantan Tengah', 'Museum Balanga adalah sebuah museum yang berlokasi di Kota Palangka Raya, Provinsi Kalimantan Tengah. Museum ini digunakan sebagai media pembelajaran tentang budaya dan sumber daya alam di lingkungan hidup Suku Dayak. Gedung museum merupakan bekas Gedung Monumen Dewan Nasional yang bernama Balanga.', -2.19499, 113.90219, NULL, ' 07.30–15.00;  08.00–12.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Balanga%20Palangka%20Raya.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q4216835', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9719, NULL, 4, 'Keraton Sumenep', 'Sumenep', 'Jalan Dokter Soetomo, Sumenep, Jawa Timur', 'Keraton Sumenep adalah tempat kediaman resmi para Adipati/Raja-Raja selain sebagai tempat untuk menjalankan roda pemerintahan. Kerajaan Sumenep sendiri bisa dibilang sifatnya sebagai kerajaan (setingkat Kadipaten) kala itu, sebab sebelum wilayah Sumenep dikuasai VOC wilayah Sumenep sendiri masih kerabat dari Kertanegara dan Raden Wijaya seduluran kepada kerajaan-kerajaan besar seperti (Singhasari, pada tahun 1269 dan Majapahit pada tahun 1293 pada saat itu.\nKeraton Sumenep sejatinya banyak jumlahnya, selain sebagai kediaman resmi adipati/raja yang berkuasa saat itu, karaton juga difungsikan sebagai tempat untuk mengatur segala urusan pemerintahan kerajaan.', -7.0079153, 113.8628123, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Labhang%20Mesem.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q6436409', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9720, NULL, 4, 'Lokananta', 'Jawa Tengah', 'Jalan Jenderal Achmad Yani, Kerten, Surakarta, Jawa Tengah', 'Lokananta adalah bagian dari Perum Percetakan Negara Republik Indonesia yang bergerak di bidang multimedia. Sebelumnya, Lokananta merupakan bekas badan usaha milik negara Indonesia yang bergerak di bidang perekaman musik. yang didirikan pada tahun 1956.', -7.5578484, 110.7967977, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lokananta%20Studio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12495102', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9721, NULL, 4, 'Museum Radya Pustaka', 'Jawa Tengah', 'Jalan Brigadir Jenderal Slamet Riyadi, Timuran, Surakarta, Jawa Tengah', 'Museum Radya Pustaka (bahasa Jawa: ꦩꦸꦱꦾꦶꦪꦸꦩ꧀ꦫꦢꦾꦥꦸꦱ꧀ꦠꦏ, translit. Musyium Radya Pustaka) adalah sebuah museum yang terletak di Surakarta, Jawa Tengah, Indonesia.', -7.568031, 110.8145, 0, ' 09.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Radyapustaka-Surakarta01.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499664', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9722, NULL, 4, 'Museum Batak, Balige', 'Sumatera Utara', 'Hinalangbagasan, Kabupaten Toba', 'Museum Batak adalah museum budaya yang bertempat di Kompleks T. B. Silalahi Center di Jl. Pagar Batu No. 88 (eks.', 2.33344, 99.04837, 10000, ' 08.00–18.00;  08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Batak%2C%20Balige.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499671', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (9723, NULL, 4, 'Museum Siwa Lima', 'Nusaniwe', 'Nusaniwe, Ambon, Maluku', 'Museum Siwalima atau Museum Negeri Provinsi Maluku Siwalima Ambon terletak di kawasan Taman Makmur, desa Amahusu, kecamatan Nusaniwe, kota Ambon, propinsi Maluku. Museum ini didirikan tanggal 8 November 1973 dan diresmikan tanggal 26 Maret 1977. Lokasi bangunan ini berada di atas bukit yang menghadap ke Teluk Ambon yang membuatnya semakin eksotis.', -3.7135, 128.15309, 4000, ' 08.00–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Siwalima%202026%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499669', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9724, NULL, 4, 'Museum Tri Daya Eka Dharma', 'Sumatera Barat', 'Jalan Panorama, Panorama, Bukittinggi, Sumatera Barat', 'Museum Tridaya Eka Dharma adalah salah satu museum yang ada di Sumatera Barat yang terletak di kota Bukittinggi, tepatnya di jalan Panorama No. 22, kelurahan Kayu Kubu, kecamatan Guguk Panjang, Bukittinggi. Museum ini diresmikan oleh Mohammad Hatta pada tanggal 16 Agustus 1973.', -0.3071389, 100.3661389, NULL, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tri%20Daya%20Eka%20Dharma%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499676', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9725, NULL, 4, 'Museum Kereta Api Bondowoso', 'Bondowoso', 'Jalan Imam Bonjol, Mandaluki, Bondowoso, Jawa Timur', 'Museum Kereta Api Bondowoso (bahasa Inggris: Bondowoso Rail and Train Museum) adalah stasiun kereta api nonaktif yang sekarang dialihfungsikan sebagai museum sejarah perkeretaapian. Museum ini secara administratif terletak di Kademangan, Bondowoso, Bondowoso; termasuk dalam Wilayah Penjagaan Aset IX Jember pada ketinggian +253 m. Museum ini sekarang dikelola oleh Unit Pusat Pelestarian dan Desain Arsitektur PT KAI bekerja sama dengan Pemerintah Kabupaten Bondowoso.', -7.91695, 113.82948, 0, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stasiun%20Bondowoso%202019.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12516227', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9726, NULL, 4, 'Museum Tani Jawa Indonesia', 'Bantul', 'Jalan Imogiri Siluk Panggang, Kebonagung, Imogiri, Daerah Istimewa Yogyakarta', 'Museum Tani Jawa Indonesia merupakan museum kecil yang terletak di desa wisata Candran, di Kebon Agung, Kabupaten Bantul , Daerah Istimewa Yogyakarta. Museum Tani Jawa Indonesia ini berdiri pada tahun 2005, dipelopori oleh Kristya Bintara yang pada saat itu menjabat sebagai Lurah di Desa Kebonagung pada tahun 1988. Museum ini dulunya ditempati sebagai rumah joglo milik Subandi, Dukuh Kanten.', -7.9244722, 110.3714722, NULL, ' 08.00–14.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Tani%20Jawa%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q13095247', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9727, NULL, 4, 'Museum BRI Purwokerto', 'Jawa Tengah', 'Jalan RA. Wiriatmaja, Kedungwuluh, Banyumas, Jawa Tengah', 'Museum Bank Rakyat Indonesia (Museum BRI) adalah sebuah museum yang terletak di Purwokerto, Kabupaten Banyumas, Provinsi Jawa Tengah, Indonesia. Tujuan didirikannya Museum BRI ialah sebagai bentuk penghormatan kepada para pendiri Bank Rakyat Indonesia (BRI) dan sebagai sarana pelestarian benda peninggalan hasil kegiatan operasional BRI. Koleksi Museum BRI meliputi benda-benda yang berkaitan dengan perkembangan bank di Indonesia sejak masa penjajahan Belanda, pendudukan Jepang, kemerdekaan Indonesia dan masa kini. Kunjungan ke Museum BRI dapat dilakukan setiap hari Minggu hingga Kamis secara gratis.', -7.4237346, 109.2257644, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bank%20BRI%20Museum%20Purwokerto.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q13148980', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9728, NULL, 4, 'Museum Benteng Heritage', 'Banten', 'Jalan Cikepu, Tangerang, Banten', 'Museum Benteng Heritage adalah museum peranakan Tionghoa pertama dan satu-satunya di Indonesia. Museum ini merupakan hasil restorasi sebuah bangunan berarsitektur tradisional Tionghoa. Museum Benteng Heritage merupakan salah satu bangunan tertua di Kota Tangerang yang menjadi cikal bakal pusat Kota Tangerang yang dulunya disebut Kota Benteng.', -6.1786869, 106.6296684, 10000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balkon%20Lantai%20Dua%20Sisi%20Kiri%20Benteng%20Heritage.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q16862716', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9729, NULL, 4, 'Museum Sultan Mahmud Badaruddin II', 'Sumatera Selatan', 'Jalan Dokter AK. Gani No.19, Bukit Kecil, Palembang, Sumatera Selatan', 'Museum Sultan Mahmud Badaruddin II adalah museum di kota Palembang, Sumatera Selatan, Indonesia. Museum ini didirikan di bekas bangunan rumah residen kolonial Sumatera Selatan abad ke-19. Bangunan ini juga menjadi gedung dinas pariwisata Palembang.', -2.99026, 104.7611, NULL, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sultan%20Mahmud%20Badaruddin%20II%20Museum%2C%20Palembang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q48988740', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9730, NULL, 4, 'House of Sampoerna', 'Surabaya', 'Jalan Sampoerna No.6, Pabean Cantian, Surabaya, Jawa Timur', 'House of Sampoerna adalah sebuah museum tembakau dan markas besar Sampoerna yang terletak di Surabaya. Gaya arsitektur dari bangunan utamanya yang dipengaruhi oleh gaya kolonial Belanda dibangun pada 1862 dan sekarang menjadi situs sejarah. Sebelumnya dipakai sebagai panti asuhan yang diurus oleh Belanda, tempat tersebut dibeli pada 1932 oleh Liem Seeng Tee‚ pendiri Sampoerna‚ dengan tujuan dipakai sebagai fasilitas produksi rokok besar pertama Sampoerna.', -7.2308056, 112.73425, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/House%20of%20Sampoerna%20Mei%202015.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q60674533', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9731, NULL, 4, 'De Tjolomadoe', 'Jawa Tengah', 'Jalan Adi Sucipto, Colomadu, Jawa Tengah', 'De Tjolomadoe adalah bekas pabrik gula yang terletak di Jalan Adi Sucipto No. 1 Malangjiwan, Colomadu, Karanganyar, Jawa Tengah, Indonesia. Pabrik gula ini dialihfungsikan menjadi museum, pusat konvensi, dan kawasan komersial.', -7.53438, 110.74992, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20Colomadu%20suikerfabriek%20in%20Malangjiwan%20in%20de%20omgeving%20van%20Soerakarta%20TMnr%2060005243.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q81199133', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 5),
  (9732, NULL, 4, 'Situs Purbakala Cipari', 'Cigugur', 'Kuningan, Jawa Barat', 'Situs Purbakala Cipari merupakan situs peninggalan megalitik di Kabupaten Kuningan. Situs ini diduga sebagai sebuah situs desa permukiman purbakala dengan karakateristik peninggalan bangunan megalitik, seperti kubur batu dan menhir.', -6.9620583, 108.4692306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Situs%20Cipari%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q3485423', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9733, NULL, 4, 'Museum Mandala Wangsit Siliwangi', 'Bandung', 'Jalan Lembong No.38, Sumur Bandung, Kota Bandung, Jawa Barat', 'Museum Wangsit Mandala Siliwangi adalah sebuah museum yang berada di Kota Bandung, Jawa Barat. Siliwangi merupakan nama komando daerah militer TNI-AD di Jawa Barat dan Banten yang namanya diambil dari raja dari Kerajaan Sunda yang beribu kota di Pakuan Pajajaran yang kekuasaannya konon tak terbatas, juga arif dan bijaksana serta wibawa dalam menjalankan roda pemerintahan. \nSedangkan arti Mandala Wangsit merupakan sebuah tempat untuk menyimpan amanat, petuah atau nasihat dari pejuang masa lalu kepada generasi penerus melalu benda-benda yang ditinggalkannya.', -6.91714, 107.61128, NULL, 'Sab 08.00–12.00;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mandala%20Wangsit%20Siliwangi.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q3658066', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9734, NULL, 4, 'Museum Kebudayaan dan Kemajuan Asmat', 'Agats', 'Agats, Papua Selatan', 'Museum Kebudayaan dan Kemajuan Asmat adalah sebuah museum yang terletak di distrik Agats, Kabupaten Asmat, Provinsi Papua Selatan, Indonesia. Museum ini didirikan oleh para misionaris OSC Frank Trenkenschuh, OSC dan Mgr. Alphonse Sowada, OSC pada tahun 1969 sebagai jalan untuk mempertahankan kebudayaan-kebudayaan Asmat serta memberikan kontribusi ekonomi bagi orang-orang Asmat.', -5.5405295, 138.1341535, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Asmat%20%2848280683281%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q4807420', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9735, NULL, 4, 'Museum Provinsi Kalimantan Barat', 'Pontianak', 'Jalan Ahmad Yani, Pontianak Selatan, Pontianak, Kalimantan Barat', 'Museum Provinsi Kalimantan Barat adalah sebuah museum yang berlokasi di Jalan Jenderal Ahmad Yani, Kota Pontianak, Kalimantan Barat, Indonesia. Museum ini menyimpan berbagai benda-benda bernilai historis yang ada di Provinsi Kalimantan Barat salah satunya peninggalan-peninggalan sejarah dari peradaban beberapa jenis suku bangsa yang ada di Kalimantan Barat, yaitu: Suku Melayu, Suku Dayak, dan Suku Tionghoa. Jam kunjungan museum ini yaitu pada hari Selasa-Minggu 08.00-14.00, Jumat 08.00-11.00 dan 12.30-14.00.', -0.0483611, 109.3430833, 2000, 'Jum 13.00–11.00; Jum 08.00–11.00; Jum 13.00–15.00; Jum 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20samping%20Museum%20Nasional%20Kalimantan%20Barat.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q6940672', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9736, NULL, 4, 'Museum Konferensi Asia Afrika', 'Bandung', 'Jalan Asia Afrika No.65, Sumur Bandung, Kota Bandung, Jawa Barat', 'Museum Konferensi Asia Afrika adalah salah satu museum yang berada di Kota Bandung. Museum  ini didirikan  pada  24  April  1980. Pada tanggal 18-24 April 1955, delegasi dari dua puluh sembilan negara menghadiri Konferensi Asia Afrika di Bandung, Indonesia.', -6.9212134, 107.6073265, 0, 'Jum 14.00–16.00;  08.00–16.00;  09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Musium%20KAA.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q10972781', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9737, NULL, 4, 'Museum Pos Indonesia', 'Bandung', 'Jalan Cilaki No.73, Bandung Wetan, Kota Bandung, Jawa Barat', 'Museum Pos Indonesia (Aksara Sunda Baku: ᮙᮥᮞᮤᮉᮙ᮪ ᮕᮧᮞ᮪, Musieum Pos) merupakan museum yang ada di sebelah kanan Gedung Kantor Pusat PT Pos Indonesia di Jalan Cilaki 73. Bangunannya ada di sebelah timur Gedung Sate.', -6.9020426, 107.6197712, 0, ' 9 AM–15.00; Sab 9 AM–13.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kantor%20Pusat%20Pos%20Indonesia.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q10986546', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9738, NULL, 4, 'Museum Dewantara Kirti Griya', 'Yogyakarta', 'Jalan Taman Siswa No.31, Mergangsan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Tamansiswa Dewantara Kirti Griya (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦢꦺꦮꦤ꧀ꦠꦫꦏꦶꦂꦠꦶꦒꦿꦶꦪ) merupakan museum peninggalan dari tokoh pendidikan Indonesia yaitu Ki Hadjar Dewantara yang berupa rumah dan pendapa. Selain itu, museum juga menampilkan koleksi dan peninggalan barang-barang yang dipakai oleh Ki Hadjar Dewantara beserta keluarga.', -7.80506, 110.37819, 5000, ' 08.00–13.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pendapa%20tamansiswa.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499637', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9739, NULL, 4, 'Museum Pusaka Nias', 'Sumatera Utara', 'Jalan Kakatua, Iraonogeba, Kota Gunungsitoli', 'Museum Pusaka Nias adalah sebuah museum di Jl. Yos Sudarso No. 134-A. Saombö, Gunungsitoli, Sumatera Utara yang didirikan untuk melestarikan budaya Nias.', 1.2984162, 97.6087372, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Objects%20of%20the%20Nias%20Heritage%20Museum%2C%20Gunungsitoli%20City%3B%20September%202024%20%2805%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499662', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9740, NULL, 4, 'Museum Wayang Sendang Mas', 'Sudagaran', 'Jalan Gadean, Banyumas, Jawa Tengah', 'Museum Wayang Sendang Mas (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦮꦪꦁꦱꦼꦤ꧀ꦝꦁꦩꦱ꧀, translit. Musiyum Wayang Sendhang Mas) atau Museum Wayang Banyumas adalah sebuah museum yang terletak di kompleks pusat pemerintahan lama Kabupaten Banyumas, Jawa Tengah. Koleksi utama di dalam Museum Wayang Sendang Mas adalah wayang Gagrag Banyumasan,terutama tokoh Bawor yang hanya ada dalam wayang Banyumasan.', -7.51459, 109.29422, 1000, 'Sab 07.00–13.00; Min 08.00–13.00;  07.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Wayang%20Banyumas%20%282026%29%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499684', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9741, NULL, 4, 'Monumen Kapal Selam', 'Surabaya', 'Jalan Pemuda No.39, Embong Kaliasin, Surabaya, Jawa Timur', 'Monumen Kapal Selam, atau disingkat Monkasel, adalah sebuah museum kapal selam yang terdapat di Embong Kaliasin, Genteng, Surabaya. Terletak di pusat kota yaitu di Jalan Pemuda No. 39, tepat di sebelah Plaza Surabaya, dan terdapat pintu akses untuk mengakses mal dari dalam monumen.', -7.26552, 112.75027, 15000, ' 08.00–21.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Submarine%20Monument%20Surabaya%202.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729370', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9742, NULL, 4, 'Museum Manusia Purba Sangiran', 'Jawa Tengah', 'Jalan Barokah, Gondangrejo, Jawa Tengah', 'Museum Manusia Purba Sangiran atau Museum Sangiran adalah museum arkeologi yang terletak di dua kabupaten, yaitu Sragen dan Karanganyar. Memiliki lima klaster, empat di antaranya terletak di Kabupaten Sragen, sedangkan satu klaster terletak di Kabupaten Karanganyar. \nSaat ini, lima klaster museum di kawasan Museum Manusia Purba Sangiran dikelola oleh Museum dan Cagar Budaya, Kementerian Kebudayaan Republik Indonesia.', -7.45331, 110.83435, 8000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20manusia%20purba%20sangiran.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729521', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9743, NULL, 4, 'Museum Bank Indonesia Padang', 'Berok Nipah', 'Jalan Nipah No.66, Batang Arau, Padang, Sumatera Barat', 'Museum Bank Indonesia Padang (sebelumnya De Javasche Bank Padang) adalah bangunan berarsitektur kolonial peninggalan pemerintah Hindia Belanda bekas Bank Indonesia (BI) yang terletak di Jalan Batang Arau, Kecamatan Padang Barat, Kota Padang, Sumatera Barat. Bangunan ini dibangun pada 31 Maret 1921 dan diresmikan pada 12 Januari 1925 sebagai kantor cabang De Javasche Bank sebelum diambil alih oleh BI pada 1 Juli 1953. \nBangunan ini merupakan kantor kedua  De Javasche Bank Padang, menggantikan kantor lama yang dibangun pada 1865.', -0.96449, 100.35827, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Kantoor%20van%20de%20Javasche%20Bank%20en%20het%20monument%20voor%20W.H.%20de%20Greve%20TMnr%2010015479.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19745831', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9744, NULL, 4, 'Museum PDRI', 'Koto Tinggi', 'Baruah Gunuang, Lima Puluh Kota, Sumatera Barat', 'Museum Nasional PDRI (atau Museum Bela Negara) adalah museum nasional yang menampilkan kronik dan peninggalan sejarah perjuangan Pemerintahan Darurat Republik Indonesia (PDRI), penyelenggara pemerintahan Republik Indonesia ketika ibu kota Indonesia jatuh ke tangan Belanda pada Agresi Militer Belanda Kedua. Museum ini berada di area seluas 20 hektare di salah satu kawasan yang pernah menjadi basis PDRI, yaitu di Jorong Aie Angek, Nagari Koto Tinggi, Kecamatan Gunung Omeh, Kabupaten Lima Puluh Kota, Sumatera Barat.', -0.0212027, 100.3693226, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20PDRI%20Sumbar%2032.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19746312', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9745, NULL, 4, 'Museum Sadurengas', 'Paser', 'Jalan Sultan Ibrahim Khaliluddin, Pasir Belengkong, Paser, Kalimantan Timur', 'Museum Sadurengas adalah sebuah museum di Kabupaten Paser yang secara khusus mengoleksi benda peninggalan Kesultanan Paser. Lokasi museum berada di Desa Paser Belengkong, Kecamatan Paser Belengkong, Kabupaten Paser, Kalimantan Timur. Di sekitar lokasi museum terdapat masjid peninggalan Kesultanan Paser dan pemakaman dari para Sultan Paser.', -1.94808, 116.211, 10000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sadurengas%20171224001.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19899331', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9746, NULL, 4, 'Museum Bank Indonesia Surabaya', 'Surabaya', 'Jalan Kasuari, Krembangan Selatan, Surabaya, Jawa Timur', 'Cagar Budaya Bank Indonesia terletak di Surabaya, Indonesia. Cagar Budaya ini secara khusus didirikan oleh Bank Indonesia dan dibuka pada tanggal 27 Januari 2012 setelah direstorasikan. Cagar Budaya yang menempati gedung ini dikenal sebagai De Javasche Bank (sekarang: Bank Indonesia) sebagai Bank sentral Hindia Belanda yang bermarkas di Batavia.', -7.2353333, 112.7368056, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Bank%20Indonesia%20Surabaya.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q25460071', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9747, NULL, 4, 'Museum Brawijaya Malang', 'Jawa Timur', 'Jalan Retawu No.25A, Klojen, Kota Malang, Jawa Timur', 'Museum Brawijaya adalah sebuah museum militer yang berada di Malang, Jawa Timur. Museum Brawijaya merupakan museum perjuangan yang dibangun atas prakarsa Brigjen TNI (Purn) Soerachman ketika menjabat sebagai Pangdam VIII Brawijaya pada periode 1959–1962. Pembangunan museum dimulai pada tahun 1967 dan kemudian diresmikan pada 4 Mei 1968 oleh Kolonel (Purn) Dr.', -7.972094, 112.621147, 3000, ' 08.00–14.30;  08.00–13.00; Jum 08.00–11.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Brawijaya%20Malang%20with%20Statue%20of%20Sudirman.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q25578630', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9748, NULL, 4, 'Museum Balaputra Dewa', 'Sumatera Selatan', 'Jalan Srijaya, Alang-Alang Lebar, Palembang, Sumatera Selatan', 'Museum Balaputra Dewa (atau Museum Negeri Sumatera Selatan) adalah sebuah museum etnografi di Kota Palembang, Sumatera Selatan, Indonesia. Museum ini menampilkan sejarah dan kebudayaan Sumatera Selatan. Museum ini mulai dibangun pada 1978 dan diresmikan pada 5 November 1984.', -2.95096, 104.73069, 2000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Limas%20of%20IDR%2010000%20banknote.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q48728288', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9749, NULL, 4, 'Museum Uang Sumatra', 'Medan', 'Medan Maimun, Kota Medan, Sumatera Utara', 'Museum Uang Sumatera adalah museum uang pertama yang ada di Sumatra yang diresmikan pada tanggal 2 Mei 2017 oleh Gubernur Sumatera Utara. Museum ini awalnya terletak di lantai 2 Gedung Juang 45 Sumatera Utara. Kini museum ini beralih lokasi di Kantor Bupati Aceh Jaya, Aceh.', 3.5819, 98.68236, NULL, ' 09.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Uang%20Sumatera.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q64681279', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9750, NULL, 4, 'Museum Kapuas Raya', 'Sintang', 'Sintang - Putussibau, Sintang, Kalimantan Barat', 'Museum Kapuas Raya adalah museum yang terletak di Jalan Sintang – Putussibau km 14, Kelurahan Tanjung Puri, Kecamatan Sintang, Sintang, Kalimantan Barat.\nMuseum Kapuas Raya dimiliki oleh Pemerintah Kabupaten Sintang dan dikelola oleh Dinas Pendidikan dan Kebudayaan Kabupaten Sintang. Museum ini menerima pengunjung setiap hari Senin hingga Jumat dari pukul 08.00-14.00 WIB.Museum ini terletak tak jauh dari Galeri Motor Bandong.', 0.08316, 111.57699, 0, ' 08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kapuas%20Raya%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q84709327', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9751, NULL, 4, 'Museum Daerah Kabupaten Sambas', 'Sambas', 'Sambas To Serabek Car Ferry, Lorong, Sambas, Kalimantan Barat', 'Museum Daerah Kabupaten Sambas adalah museum yang terletak di Jalan Siapat, Desa Lorong, Kecamatan Sambas, Kabupaten Sambas, Kalimantan Barat. Museum ini khusus mengoleksi berbagai macam benda-benda peninggalan Kesultanan Sambas. Pemilik museum adalah pemerintah Kabupaten Sambas, sebagai pengelolanya adalah Dinas Pendidikan dan Kebudayaan Kabupaten Sambas.', 1.36487, 109.29708, 0, ' 07.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Daerah%20Sambas%201.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940199', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 4),
  (9752, NULL, 4, 'Museum Gunungapi Merapi', 'Sleman', 'Hargobinangun, Sleman, Daerah Istimewa Yogyakarta', 'Museum Gunungapi Merapi (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦒꦸꦤꦸꦁꦩꦼꦫꦥꦶ, translit. Musiyum Gunung Merapi) merupakan museum geologi yang terletak di Hargobinangun, Pakem, Sleman, Daerah Istimewa Yogyakarta, Indonesia; tepatnya sekitar lima kilometer di sebelah selatan kawasan objek wisata Kaliurang. Museum ini diresmikan pada tanggal 1 Oktober 2009 oleh Menteri Energi dan Sumber Daya Mineral (ESDM), Purnomo Yusgiantoro.', -7.6159272, 110.4243329, 5000, ' 08.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Gunungapi%20Merapi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q1958032', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9753, NULL, 4, 'Erasmus Huis', 'Daerah Khusus Ibukota Jakarta', 'Jalan Denpasar Raya, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Erasmus Huis adalah pusat kebudayaan Belanda di Jakarta, Indonesia. Terutama karena acara musik, akustik ruangan yang bermutu dan letaknya yang cukup strategis, Erasmus Huis berhasil membangun reputasi sebagai pusat kebudayaan yang aktif dan berjalan dengan baik. Namun, acara Erasmus Huis tidak hanya berfokus pada musik saja.', -6.2343611, 106.8287222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Perpustakaan%20Erasmus%20Huis.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q2558851', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9754, NULL, 4, 'Keraton Sumedang Larang', 'Jawa Barat', 'Sukajaya, Sumedang, Jawa Barat', 'Keraton Sumedang Larang adalah sebuah keraton yang dibangun di bekas kediaman raja Kusumadinata II atau juga dikenal sebagai Prabu Geusan Ulun yang berada di Jl. Prabu Geusan Ulun No. 40, Kabupaten Sumedang, Jawa Barat, Indonesia.', -6.8609741, 107.920822, 3000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Makuta%20Binokasih.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q4262432', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9755, NULL, 4, 'Museum Gudang Ransoem', 'Sumatera Barat', 'Tanahlapang, Sawahlunto, Sumatera Barat', 'Museum Goedang Ransoem adalah salah satu museum di Indonesia yang terletak di Jalan Abdul Rahman Hakim, Kelurahan Air Dingin, Kecamatan Lembah Segar, Kota Sawahlunto, Sumatera Barat. Museum ini berada sekitar 94 kilometer atau dua jam perjalanan dengan kendaraan dari Kota Padang.\nMuseum Goedang Ransum menempati sebuah kompleks bangunan bekas dapur umum para pekerja tambang batu bara dan pasien Rumah Sakit Umum Daerah Sawahlunto yang ketika itu berjumlah ribuan.', -0.6787778, 100.7810278, 2000, ' 09.00–17.00;  08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Gudang%20Ransoem%202015.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499638', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9756, NULL, 4, 'Museum Kailasa', 'Jawa Tengah', 'Jalan Inspeksi Pipa Geothermal, Dieng Kulon, Banjarnegara, Jawa Tengah', 'Museum Kailasa merupakan sebuah museum di Dataran Tinggi Dieng, Jawa Tengah. Museum yang memiliki 4 bangunan utama ini memiliki koleksi  arekologis, benda-benda cagar budaya, artefak, flora dan fauna serta film mengenai Dieng. Koleksi yang dapat dilihat pada museum ini di antaranya memuat sejarah letusan Gunung Prahu Tua, sumber batu andesit yang digunakan untuk pembangunan candi, dan sistem kepercayaan masyarakat Dieng.', -7.2082219, 109.9053681, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Dieng%20Kailasa.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499636', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9757, NULL, 4, 'Museum Kayu Tuah Himba', 'Kalimantan Timur', 'Jalan Anggana, Maluhu, Kutai Kartanegara, Kalimantan Timur', 'Museum Kayu Tuah Himba adalah museum yang terletak di Kawasan Waduk Panji Sukarame, Kutai Kartanegara, Kalimantan Timur. Museum ini dibangun dengan bangunan kayu panggung yang berukuran 20 x 20 m². Pembangunan museum dilatarbelakangi oleh dengan adanya pembukaan objek wisata berupa buaya yang telah diawetkan sebagai koleksi museum.Per 2023, tarif tiket masuk yang dikenakan bagi pengunjung dewasa adalah Rp.5000.', -0.40569, 116.97131, 3000, 'Jum 09.00:00–11.00; Sab 09.00:00–16.00; Min 09.00:00–12.00;  09.00:00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kayu%20Tuah%20Himba.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499641', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9758, NULL, 4, 'Museum Perjuangan Yogyakarta', 'Kota Yogyakarta', 'Jalan Kolonel Sugiono, Mergangsan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Perjuangan Yogyakarta (bahasa Jawa: ꧋ꦩꦸꦱꦾꦶꦪꦸꦩ꧀ꦦꦼꦂꦗꦸꦮꦔꦤ꧀ꦔꦪꦺꦴꦒꦾꦏꦂꦠ꧉, translit. Musiyum Perjuwangan Ngayogyakarta) adalah museum yang memiliki koleksi mengenai perjuangan bangsa Indonesia. Museum ini terletak kurang lebih 2 kilometer dari pusat Kota Yogyakarta.', -7.8164582, 110.3718637, NULL, 'Sen–Jum 07.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Perjuangan%20Yogyakarta.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499660', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9759, NULL, 4, 'Museum Tembi', 'Bantul', 'Jalan Tembi - Sudimoro, Sewon, Daerah Istimewa Yogyakarta', 'Museum Tembi Rumah Budaya adalah museum yang menyimpan benda-benda warisan budaya Jawa. Museum yang diresmikan pada 21 Oktober 1999 bermula dari Lembaga Studi Jawa yang pindah ke dusun Tembi, Timbulharjo, Sewon, Bantul, Yogyakarta pada 6 September 1995.', -7.869894, 110.3561531, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alat%20Musik%20Museum%20Tembi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499675', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9760, NULL, 4, 'Museum Wayang Kekayon', 'Yogyakarta', 'Jalan Wonosari, Banguntapan, Daerah Istimewa Yogyakarta', 'Museum Wayang Kekayon (carakan: ꦩꦸꦱꦶꦪꦸꦩ꧀​ꦮꦪꦁ​​ꦏꦺꦏꦪꦺꦴꦤ꧀) adalah sebuah museum wayang yang berada di luar Kota Yogyakart, tepatnya di Jl. Jogja-Wonosari Km.7 No.277, kurang lebih 1 km dari Jl. Majapahit (Ring Road Timur) secara adiministratif berada di Kalanagan, Kalurahan Batutetno, Kapanewon Banguntapan, Kabupaten Bantul, Daerah Istimewa Yogyakarta.', -7.8153785, 110.4131046, 20000, ' 09.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wayang%20Klithik%20Museum%20Wayang%20Kekayon.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499678', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9761, NULL, 4, 'Museum Sasmitaloka Panglima Besar Jenderal Sudirman', 'Yogyakarta', 'Jalan Bintaran Wetan, Pakualaman, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Sasmitaloka Panglima Besar (Pangsar) Jenderal Sudirman (bahasa Jawa: Hanacaraka, ꦩꦸꦱꦩ꧀ꦱꦱ꧀ꦩꦶꦠꦭꦺꦴꦏꦥꦔ꧀ꦭꦶꦩꦧꦼꦱꦂꦗꦼꦤ꧀ꦢꦼꦫꦭ꧀ꦱꦸꦢꦶꦂꦩꦤ꧀) adalah museum sejarah dengan koleksi mengenai perjuangan Jenderal Sudirman. Kata sasmita berasal dari bahasa Jawa, yang berarti "pengingat", "mengenang", sedangkan loka berarti "tempat". "Sasmitaloka Panglima Besar Jenderal Sudirman" artinya merupakan tempat untuk mengenang pengabdian, pengorbanan dan perjuangan Panglima Besar Jenderal Sudirman.', -7.8024267, 110.3754886, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sasmitaloka%20Panglima%20Besar%20Jenderal%20Soedirman.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q13095242', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9762, NULL, 4, 'Rumah Pengasingan Bung Karno', 'Indonesia', 'Anggut Atas, Bengkulu, Bengkulu', 'Rumah Pengasingan Bung Karno merupakan tempat Soekarno menjalani hukuman pengasingan sebagai tahanan politik. Soekarno diasingkan ke Ende, Flores pada 14 Januari 1934. Ia diasingkan di sana selama empat tahun (1934-1938).', -3.7992447, 102.2612888, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Pengasingan%20Bung%20Karno%20di%20Kota%20Bengkulu.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q16878966', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9763, NULL, 4, 'Museum Kayu Sampit', 'Kalimantan Tengah', 'Yos Sudarso No.1, Sampit, Kalimantan Tengah', 'Museum Kayu Sampit adalah museum yang berlokasi di kota Sampit, Kabupaten Kotawaringin Timur, Provinsi Kalimantan Tengah, Indonesia. Museum ini dibangun pada tahun 2003 dan diresmikan pada 6 Oktober 2004 oleh Bupati Kotawaringin Timut. Museum ini dinamakan Museum Kayu karena kota Sampit pernah berjaya di bidang perkayuan.', -2.5384224, 112.9587967, 0, 'Jum 13.00–11.00; Jum 08.00–11.00; Jum 13.00–16.00; Jum 08.00–16.00;  13.00–12.00;  08.00–12.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kayu%20Sampit%20001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729524', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9764, NULL, 4, 'Gedung Juang Tambun', 'Bekasi', 'Jalan Hasanuddin, Kompas, Tambun, Jawa Barat', 'Gedung Juang Tambun adalah sebuah situs sejarah yang terletak di Kecamatan Tambun Selatan, Kabupaten Bekasi, Jawa Barat, Indonesia. Saat ini Gedung Juang Tambun difungsikan sebagai Museum Bekasi yang dikelola oleh Pemerintah Kabupaten Bekasi.', -6.2592573, 107.0546198, 0, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Juang%2045%20Tambun.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q20426935', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9765, NULL, 4, 'Museum Makam Sultan Suriansyah', 'Indonesia', 'Jalan Kuin Utara, Banjarmasin Utara, Banjarmasin, Kalimantan Selatan', 'Museum Makam Sultan Suriansyah merupakan salah satu museum yang terdapat di Kota Banjarmasin, Provinsi Kalimantan Selatan. Bangunan museum ini merupakan bagian dari komplek pemakaman Sultan Suriansyah beserta sang ratu. Makam beserta dengan bagunan museum tersebut saat ini menjadi objek wisata religi yang dapat dikunjungi oleh masyarakat umum.', -3.293139, 114.572639, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Halaman%20Depan%20Museum%20Makam%20Sultan%20Suriansyah.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q134441160', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9766, NULL, 4, 'Museum Galeri Melaka', 'Pinangsia', 'Taman Fatahillah, Taman Sari, Jakarta Barat', 'Museum Galeri Melaka: Galeri di Jakarta, Pinangsia.', -6.1341819, 106.8132511, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Melaka%20Gallery.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q20715999', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9767, NULL, 4, 'Museum Tuanku Imam Bonjol', 'Bonjol', 'Bonjol, Sumatera Barat', 'Museum Tuanku Imam Bonjol adalah museum yang dibangun berisikan peninggalan sejarah terutama alat-alat serta barang yang digunakan pahlawan nasional Tuanku Imam Bonjol. Museum ini dibangun di areal seluas lebih kurang 2 hektar dengan luas bangunan 42 x 16.50 meter persegi, terletak di Jalan Lintas Sumatra, tepatnya di Kecamatan Bonjol, Kabupaten Pasaman, Sumatera Barat.', 0.0013889, 100.2211667, NULL, 'Jum 08.00–17.00;  08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Tuanku%20Imam%20Bonjol%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q59347826', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9768, NULL, 4, 'Rumah Kelahiran Bung Hatta', 'Campago Ipuh', 'Jalan Soekarno Hatta No.37, Tanjung Alam, Bukittinggi, Sumatera Barat', 'Rumah Kelahiran Bung Hatta adalah rumah yang dibangun sebagai upaya mengenang dan memperoleh gambaran tempat Bung Hatta dilahirkan dan menghabiskan masa kecilnya sampai berusia 11 tahun. Pendidikan formal Bung Hatta dimulai di Europese Lageree School (ELS) Bukittinggi. Selanjutnya Bung Hatta melanjutkan pendidikan menengahnya di Meer Uitgebred Lager Onderwijs (MULO) atau sekolah menengah di kota Padang.', -0.30078, 100.37311, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mohammad%20Hatta%20Birth%20Place%20and%20Museum%2C%20Bukittinggi%2C%20West%20Sumatra%202017-02-13%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q61363073', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9769, NULL, 4, 'Rumah Kelahiran Tan Malaka', 'Pandam Gadang', 'Kurai, Lima Puluh Kota, Sumatera Barat', 'Rumah Kelahiran Tan Malaka adalah sebuah rumah tempat Tan Malaka menghabiskan masa kecilnya, sebelum akhirnya hijrah ke Bukittinggi dan melanglang buana ke berbagai negara. Rumah ini adalah sebuah rumah tua yang berlokasi di pelosok Pandam Gadang, Gunuang Omeh, Kabupaten Lima Puluh Kota, Sumatera Barat. Bangunannya bergaya arsitektur tradisional Minangkabau dan tampakmenyendiri dari permukiman penduduk lainnya.', -0.0871389, 100.4190833, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Kelahiran%20Tan%20Malaka.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q61363089', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9770, NULL, 4, 'Museum Kota Bandung', 'Bandung', 'Jalan Aceh No.47, Sumur Bandung, Kota Bandung, Jawa Barat', 'Museum Kota Bandung adalah sebuah museum yang terletak di Jalan Aceh No. 47, Kota Bandung, Provinsi Jawa Barat. Lokasi Museum Kota Bandung berada di seberang Gedung Bandung Planning Gallery ini diresmikan oleh wali kota Bandung Oded M. Danial pada tanggal 31 Oktober 2018.', -6.90965, 107.60943, NULL, 'Sel–Min 10.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Luar%20Museum%20Kota%20Bandung%20%28Desember%202024%29%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65212192', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9771, NULL, 4, 'Rumah Pengasingan Bung Hatta', 'Maluku Tengah', 'Jalan Dr. Rehatta, Kampung Baru, Maluku Tengah, Maluku', 'Rumah Pengasingan Bung Hatta merupakan tempat Mohammad Hatta menjalani hukuman pengasingan sebagai tahanan politik selama 6 tahun (1936–1942) di Banda Naira, kini di Kabupaten Maluku Tengah, Maluku. Ia bersama dengan tokoh nasional lain bernama Sutan Sjahrir juga diasingkan dekat rumah pengasingan Bung Hatta yang sekarang dikenal sebagai Rumah Pengasingan Bung Sjahrir mulai Februari - Maret Tahun 1942.\nPada 2008, Kementerian Pendidikan dan Kebudayaan menetapkan bangunan Rumah Pengasingan Bung Hatta sebagai cagar budaya dari provinsi Maluku dengan SK Menteri Nomor PM.31/PW.007/MKP/2008.', -4.5274, 129.8998, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Pengasingan%20Bung%20Hatta%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65213908', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9772, NULL, 4, 'Rumah Gadang Mande Rubiah', 'Lunang', 'Lunang, Pesisir Selatan, Sumatera Barat', 'Museum Mande Rubiah adalah museum umum yang didirikan oleh Muskala Kanwil P&K Provinsi Sumatera Barat  pada 8 Maret 1980. Museum ini lebih sering disebut dengan nama Rumah Gadang Mande Rubiah. Pemilik rumah Gadang ini memiliki hubungan dengan Kerajaan Pagaruyung dan diperkirakan sudah ada sejak abad ke-14.', -2.25238, 101.12648, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Gadang%20Mande%20Rubiah%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65251767', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9773, NULL, 4, 'Museum Rumah Kelahiran Bagindo Aziz Chan', 'Sumatera Barat', 'Jalan Thamrin, Belakangpondok, Padang, Sumatera Barat', 'Museum Rumah Kelahiran Bagindo Aziz Chan adalah museum yang terletak di  Kelurahan Alang Laweh, Kecamatan Padang Selatan, Kota Padang, Provinsi Sumatera Barat. Museum ini merupakan replika dari bangunan aslinya yang didirikan untuk mengenang jasa pahlawan nasional Bagindo Aziz Chan. Setelah mengalami beberapa kali renovasi sejak tahun 2017 akhirnya museum ini resmikan oleh pada tanggal 18 Juli 2019.', -0.9559167, 100.3642778, 0, 'Sel–Jum 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Kelahiran%20Bagindo%20Azizchan.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q71661156', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9774, NULL, 4, 'Museum Karo Lingga', 'Sumatera Utara', 'Lingga, Kabupaten Karo, Sumatera Utara', 'Museum Karo Lingga adalah museum yang terletak di Jl. Kotacane No. 180 Kabanjahe yaitu 5 km di sebelah barat Kabanjahe, sekitar 1 km sebelum lokasi Perkampungan tradisional Lingga, Kecamatan Simpang Empat, Kabupaten Karo, Sumatera Utara.', 3.1181111, 98.4752778, NULL, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Karo%20Lingga.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q72284358', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9775, NULL, 4, 'Museum Multatuli', 'Banten', 'Jalan Abdi Negara, Rangkasbitung, Banten', 'Museum Multatuli adalah museum umum yang menempati bekas Kawedanaan Rangkasbitung (Patih wedana\'swoning te Rangkasbetoeng). Bangunan berlanggam Indies ini dirancang oleh Pemerintah Hindia Belanda pada tahun 1913 dalam Verslag over de burgerlijke openbare werken in Nederlandsch-Indië over het jaar 1914 dan mulai diresmikan penggunaannya pada tahun 1923. Kepemilikan Museum Multatuli dipegang oleh Pemerintah Kabupaten Lebak dan pengelolaannya diserahkan kepada Dinas Kebudayaan dan Pariwisata Kabupaten Lebak.', -6.3606369, 106.2472236, 2000, ' 09.00–15.00;  08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20multatuli%20rangkasbitung%20lebak.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97195136', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9776, NULL, 4, 'Museum Barli', 'Bandung', 'Jalan Prof. Dr. Ir. Sutami No.91, Sukasari, Kota Bandung, Jawa Barat', 'Museum Barli adalah sebuah museum yang terletak di Jl. Prof. Dr.', -6.8780044, 107.5875885, NULL, ' 9 AM–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Museum%20Barli%202023-03-18.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97241063', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9777, NULL, 4, 'Museum Perjuangan Rakyat Jambi', 'Jambi', 'Jalan Sultan Agung No.12, Beringin, Jambi, Jambi', 'Museum Perjuangan Rakyat Jambi merupakan salah satu museum di Indonesia yang terletak di Kota Jambi, Provinsi Jambi.', -1.59632, 103.60688, 100000, 'Sen–Min 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Perjuangan%20Rakyat%20Jambi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97241081', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9778, NULL, 4, 'Museum Menara Gentala Arasy', 'Arab Melayu', 'Pelayangan, Jambi, Jambi', 'Museum Menara Gentala Arasy adalah museum yang menggambarkan perkembangan Islam di Provinsi Jambi. Museum sekaligus Jembatan Pedestrian Gentala Arasy diresmikan pada tanggal 28 Maret 2015 oleh Wakil Presiden Indonesia, H. Jusuf Kalla. Museum ini juga melambangkan Jambi Seberang sebagai pusat pendidikan Islam.', -1.58425, 103.61409, NULL, ' 07.30–16.00;  07.30–13.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gntl%20Arsy.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97306880', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9779, NULL, 4, 'Museum Padepokan Sumber Karahayon', 'Yogyakarta', 'Jalan Samas, Banguntapan, Daerah Istimewa Yogyakarta', 'Museum Padepokan Sumber Karahayon atau Museum Sumber Karahayon (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦥꦣꦺꦥꦺꦴꦏ꧀ꦏꦤ꧀ꦱꦸꦩ꧀ꦧꦼꦂꦏꦫꦲꦪꦺꦴꦤ꧀, translit. Musiyum Padhépokan Sumber Karahayon) adalah museum yang terletak di Padukuhan Tegal, Kalurahan Jambidan, Kapanéwon Banguntapan, Kabupaten Bantul, Yogyakarta. Museum tersebut didirikan oleh Ki Wiryodikarso atau Mbah Pleret dan awalnya dikenal sebagai Padepokan Sumber Karahayon.', -7.8595917, 110.4089327, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koleksi%20Museum%20Padepokan%20Sumber%20Karahayon%20%281%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97308863', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9780, NULL, 4, 'Museum Lewu Hante', 'Kalimantan Tengah', 'Jalan Tamiang Layang - Pasar Panas, Taniran, Barito Timur, Kalimantan Tengah', 'Museum Lewu Hante adalah sebuah museum yang terletak di Kabupaten Barito Timur, Provinsi Kalimantan Tengah, Indonesia. Museum ini berbentuk Rumah Betang, rumah adat Dayak Kalimantan Tengah. Dalam bahasa Dayak Maanyan, "Lewu Hante" yang berarti rumah betang atau rumah besar.', -2.198926, 115.2403898, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Lewu%20Hante%20002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108920199', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9781, NULL, 4, 'Museum Subkoss Garuda Sriwijaya', 'Sumatera Selatan', 'Jalan Garuda Merah, Lubuklinggau Barat II, Lubuklinggau, Sumatera Selatan', 'Museum Subkoss Garuda Sriwijaya merupakan museum khusus yang didirikan sebagai pusat informasi mengenai sejarah Kota Lubuk Linggau pada masa revolusi fisik 1945–1949. Pada masa tersebut, Lubuk Linggau merupakan pusat komando Tentara Nasional Indonesia tertinggi di Sumatera bagian Selatan. Sebelum mendirikan Museum SUBKOSS (Sub Komandemen Sumatera Selatan, terlebih dahulu mendirikan Monumen Perjuangan SUBKOSS dimulai tahun 1986 atas prakarsa dari Gubernur Sumatera Selatan, yaitu Sainan Sagiman, dan monumen ini kemudian diresmikan pada 13 Februari 1987.', -3.2957, 102.86055, 5000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen%20Perjuangan%20Subkoss%20Garuda%20Sriwijaya.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940291', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9782, NULL, 4, 'Rumah Budaya Banda', 'Banda', 'Jalan Geraja Tua, Bandanaira, Maluku Tengah, Maluku', 'Rumah Budaya Banda Neira adalah sebuah museum di Banda Neira yang khusus mengoleksi benda-benda yang berkaitan dengan sejarah, kesenian dan budaya di Banda Neira. Bangunan yang digunakan oleh Rumah Budaya Banda Neira berukuran sekitar 30 × 20 meter dan bergaya arsitektur Eropa abad ke-17 M. Rumah Budaya Banda Neira mengoleksi benda yang beragam macam seperti senjata dan uang. Selain itu, Rumah Budaya Banda Neira mengoleksi antara lain tempat tidur, kain batik Lasem, miniatur kora-kora, lonceng gereja dan lukisan pembantaian tokoh terkemuka di Banda Neira oleh Jan Pieterszoon Coen.', -4.5256437, 129.8974649, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Budaya%20Banda%202026%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109354656', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9783, NULL, 4, 'Museum Nyah Lasem', 'Lasem', 'Karangturi, Rembang, Jawa Tengah', 'Museum Nyah Lasem atau Museum Guest House and Creative Space Nyah Lasem adalah museum khusus yang terletak di Gang Karangturi V No. 2, Desa Karangturi, Lasem, Kabupaten Rembang. Museum ini didirikan dengan tujuan untuk mengingat kembali kehidupan para nyonya dan perempuan-perempuan yang pernah tinggal di rumah-rumah kuno Lasem.', -6.7008, 111.44672, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Nyah%20Lasem%20%28Beranda%20Depan%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433494', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9784, NULL, 4, 'Museum Misi Muntilan Pusat Animasi Misioner', 'Jawa Tengah', 'Jalan Kartini, Muntilan, Jawa Tengah', 'Museum Misi Muntilan Pusat Animasi Misioner adalah museum yang terletak di Jalan Kartini 3, Muntilan, Magelang, Jawa Tengah. Museum ini didirikan khusus untuk menjelaskan sejarah tentang gereja Keuskupan Agung Semarang. Pembangunan museum dimulai sejak 23 Juli 1998.', -7.5818213, 110.2929744, NULL, 'Sab 08.00–12.00;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Misi%20Muntilan%20%285%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109437465', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9785, NULL, 4, 'Museum Kesultanan Bulungan', 'Tanjung Palas Tengah', 'Jalan Kasimuddin, Tanjung Palas, Kalimantan Utara', 'Museum Kesultanan Bulungan adalah sebuah museum bersejarah yang berada di Kabupaten Bulungan, Provinsi Kalimantan Utara. Museum Kesultanan Bulungan menempati bangunan yang sebelumnya bangunan Istana Kesultanan Bulungan. Bangunan Museum Kesultanan Bulungan saat ini merupakan bangunan istana yang dibangun kembali oleh Pemerintah Kabupaten Bulungan.', 2.8320501, 117.3572414, 15000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kesultanan%20Bulungan.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109441121', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9786, NULL, 4, 'Wahanarata', 'Indonesia', 'Jalan Rotowijayan, Kraton, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Wahanarata (bahasa Jawa: ꦏꦒꦸꦁꦔꦤ꧀ꦢꦊꦩ꧀ꦮꦲꦤꦫꦠ, translit. Kagungan Dalem Wahanarata), dikenal pula sebagai Museum Kereta Keraton, adalah museum yang terletak di sebelah barat area Keraton Ngayogyakarta Hadiningrat, tepatnya di Jalan Rotowijayan, di sebelah utara kantor Kemantren Kraton. Museum ini merupakan bagian dari Museum Keraton Yogyakarta, selain Museum Lukisan, Museum Sri Sultan Hamengkubuwana IX, dan Museum Batik.', -7.8054872, 110.3628299, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kareta%20Karaton.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109483663', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9787, NULL, 4, 'Museum Mini Sisa Hartaku', 'Sleman', 'Kepuhharjo, Sleman, Daerah Istimewa Yogyakarta', 'Museum Mini Sisa Hartaku (bahasa Inggris: The House of Memory; bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦩꦶꦤꦶ꧇​ꦱꦶꦱꦲꦂꦠꦏꦸ) adalah sebuah museum yang menyimpan sisa-sisa letusan Gunung Merapi tahun 2010 dan merupakan bangunan rumah milik seorang warga dan hanya berjarak tujuh kilometer dari puncak Gunung Merapi.. Museum ini terletak di Dusun Petung, Kepuharjo, Cangkringan, Sleman, Yogyakarta. Di dalam museum ini terdapat berbagai koleksi, seperti kerangka hewan-hewan ternak korban letusan hingga peralatan rumah tangga yang telah rusak akibat terkena erupsi merapi.', -7.6004659, 110.4495059, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mini%20Sisa%20Hartaku%20%281%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109483914', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9788, NULL, 4, 'Museum Bumi Ageung Cikidang Kabupaten Cianjur', 'Cianjur', 'Jalan Cicih Wiarsih, Cianjur, Jawa Barat', 'Bumi Ageung Cikidang merupakan salah satu bangunan bersejarah milik Bupati Cianjur ke-10 Raden Aria Adipati Prawiradiredja II, yang berlokasi di Jln. Moch Ali, Kelurahan Solokpandan, Kecamatan Cianjur, Kabupaten Cianjur, Jawa Barat. Nama Bumi Ageung Cikidang berasal dari bahasa Sunda, bumi ageung yang berarti rumah besar, sedangkan cikidang merujuk pada nama kawasan tersebut yang diambil dari kata kidang (kijang).', -6.822459, 107.1431078, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bumi%20Ageung%20Cikidang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q115786991', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9789, NULL, 4, 'Museum Kota Lama', 'Purwodinatan', 'Jalan MT. Haryono, Semarang Tengah, Kota Semarang, Jawa Tengah', 'Museum Kota Lama adalah sebuah museum yang terletak di Jalan Cenderawasih No 1 A, Purwodinatan, Kecamatan Semarang Tengah, Kota Semarang, Jawa Tengah. Museum ini menampilkan sejarah Kota Semarang.', -6.969459, 110.4307724, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Museum%20Kota%20Lama%20Semarang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q134539489', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9790, NULL, 4, 'Museum Galunggung', 'Tasikmalaya', 'Sukamulih, Tasikmalaya, Jawa Barat', 'Museum Galunggung adalah salah satu museum yang terletak di kaki Gunung Galunggung, serta berlokasi di dalam Wisata Alam Batu Mahpar, Kabupaten Tasikmalaya, Provinsi Jawa Barat yang didirikan dengan tujuan untuk melestarikan budaya dan sejarah di wilayah tersebut.', -7.3029259, 108.0659199, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dokumentasi%20Gedung%20Museum%20Galunggung.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q140048531', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 3),
  (9791, NULL, 4, 'Museum Sang Nila Utama', 'Pekanbaru', 'Jalan Jenderal Sudirman, Marpoyan Damai, Pekanbaru, Riau', 'Museum Sang Nila Utama merupakan sebuah museum daerah yang berlokasi di Pekanbaru, Riau. Museum ini mengumpulkan dan menyimpan warisan-warisan yang berhubungan dengan budaya Melayu Riau seperti pakaian adat pernikahan, permainan tradisional, alat musik, artefak dan lainnya. Lokasinya berada di Jalan Jenderal Sudirman, Pekanbaru dan berada dalam satu kompleks kantor Dinas Kebudayaan Provinsi Riau.', 0.49423, 101.454, 100000, ' 07.00–19.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sang%20Nila%20Utama.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q6940682', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9792, NULL, 4, 'Museum Asmat', 'Jakarta', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Asmat adalah museum etnografi suku Asmat yang berada di komplek Taman Mini Indonesia Indah (TMII), Jakarta Timur. Pendirian museum dilatarbelakangi ketertarikan orang-orang asing terhadap kekhasan seni ukir Asmat. Keinginan tersebut ditanggapi baik Ibu Tien Soeharto, yang kemudian memprakarsai pendirian Museum Asmat dan meresmikannya pada tanggal 20 April 1986.', -6.3057084, 106.8936812, 10000, ' 08.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Asmat%2C%20Taman%20Mini%20Indonesia%20Indah%20%2801%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499630', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9793, NULL, 4, 'Museum Batik Danar Hadi', 'Surakarta', 'Jalan Brigadir Jenderal Slamet Riyadi, Timuran, Surakarta, Jawa Tengah', 'House of Danar Hadi (disingkat HDH) (bahasa Jawa: ꦩꦸꦱꦾꦶꦪꦸꦩ꧀ꦧꦛꦶꦏ꧀ꦢꦤꦂꦲꦝꦶ, translit. Musyium Bathik Danar Hadhi) adalah sebuah kompleks wisata heritage terpadu tentang batik yang terletak di kota Solo di Jawa Tengah. HDH didirikan oleh perusahaan batik asal Solo PT Batik Danar Hadi pada tahun 2008 dan mengkhususkan Batik beserta aspek-aspek budayanya sebagai objek wisata utamanya.', -7.568432, 110.816908, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aksara%20Jawa%20037.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499633', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9794, NULL, 4, 'Museum La Galigo', 'Sulawesi Selatan', 'Jalan Ujung Pandang No.2, Ujung Pandang, Makassar, Sulawesi Selatan', 'Museum La Galigo adalah sebuah museum provinsi Sulawesi Selatan yang terletak di Jl. Ujung Pandang No. 2, Kota Makassar, Sulawesi Selatan, Indonesia.', -5.1342808, 119.405726, 5000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20La%20Galigo%2C%20Makassar.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499645', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9795, NULL, 4, 'Museum Sandi', 'Yogyakarta', 'Jalan Faridan Muridan Noto, Gondokusuman, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Sandi adalah Unit Pelaksana Teknis di lingkungan Badan Siber dan Sandi Negara (BSSN). Museum Sandi berlokasi di Kotabaru, Kecamatan Gondokusuman, Yogyakarta. Museum Sandi mendukung pelaksanaan tugas dan fungsi Badan Siber dan Sandi Negara (BSSN) dalam meningkatkan budaya keamanan informasi melalui edukasi kepada masyarakat sekaligus melestarikan, nilai-nilai sejarah perjuangan insan persandian sebagai bagian integral perjuangan kemerdekaan Indonesia.', -7.78432, 110.37122, 0, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sandi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499666', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9796, NULL, 4, 'Museum Transportasi', 'Jakarta', 'Jalan Taman Mini, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Transportasi adalah museum khusus yang terletak di dalam kompleks Taman Mini Indonesia Indah (TMII). Museum ini awalnya hanya akan memamerkan koleksi perkeretaapian. Namun, seiring berkembangnya waktu terdapat pengubahan rencana.', -6.30466, 106.89891, 5000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Transportasi%20TMII%20-%20panoramio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499674', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9797, NULL, 4, 'Taman purbakala Pugung Raharjo', 'Lampung Timur', 'Mengandung Sari, Lampung Timur, Lampung', 'Taman Purbakala Pugung Raharjo adalah situs arkeologi yang terletak di Desa Pugung Raharjo, Kabupaten Lampung Timur, Provinsi Lampung. Situs ini pertama kali ditemukan pada 1957.\nTinggalan-tinggalan arkeologis di situs ini mencakup berbagai periode sejarah, mulai dari masa prasejarah, masa klasik (Hindu–Buddha), hingga masa Islam.', -5.2820429, 105.5610183, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pugung%20Raharjo%20Pyramid%202.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12518872', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9798, NULL, 4, 'Museum Kartini', 'Jepara', 'Jawa Tengah', 'Museum Kartini adalah museum yang terletak di utara alun-alun Jepara, Jawa Tengah. Museum ini termasuk museum umum sekaligus objek wisata sejarah maupun edukasi yang dikelola oleh Dinas Pariwisata dan Kebudayaan Kabupaten Jepara. Tujuan utama didirikannya museum ini adalah untuk mengabadikan jasa-jasa perjuangan Kartini.', -6.1411508, 110.7773036, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/R.A.%20Kartini%20Museum%20Jepara.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q14917395', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9799, NULL, 4, 'Asi mbojo', 'Bima', 'Jalan Sultan Ibrahim, Kelurahan Paruga, Bima, Nusa Tenggara Barat', 'Museum Asi Mbojo adalah bangungan istana Kesultanan Bima. Asi Mbojo dalam dalam bahasa Bima berarti istana orang Bima. Bangunan bergaya Eropa ini mulai dibangun pada 1927 dan selesai pada 1929, namun terdapat versi lain yang menyebutkan dibangun pada 1930 M pada masa Sultan Muhammad Salahudin.', -8.4539, 118.7272, NULL, 'Sen–Min 08.00–20.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Asi%20Mbojo%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q16168623', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9800, NULL, 4, 'Rahmat International Wildlife Museum & Gallery', 'Sumatera Utara', 'Gang Langgar, Medan Baru, Kota Medan, Sumatera Utara', 'Rahmat International Wildlife Museum and Gallery adalah museum yang diilhami oleh Dr. H Rahmatsyah yang memiliki kecintaan pada alam dan niatnya mencegah kepunahan hewan langka. Museum ini terletak di Kelurahan Petisah Hulu, Medan Baru, Kota Medan.', 3.5792575, 98.6677323, 40000, ' 09.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Primate%20Taxidermy%2C%20Rahmat%20International%20Wildlife%20Museum%20and%20Gallery.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q18393164', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9801, NULL, 4, 'Museum Pleret', 'Bantul', 'Jalan Jejeran - Pleret, Pleret, Bantul, Daerah Istimewa Yogyakarta', 'Museum Pleret adalah salah satu museum yang berada di Jl.Raya Pleret, Kedaton, Kecamatan Pleret Kabupaten Bantul. Museum Sejarah Purbakala Pleret yang berada di Dusun Kedaton ini menyimpan benda cagar budaya yang sebelumnya ditemukan di sekitar Kabupaten Bantul. Terdapat sekitar 50 an benda benda peninggalan sejarah masa lampau mulai dari arca, stupa, dan lain lain.', -7.86829, 110.40524, 0, ' 08.00–16.00; Jum 08.00–14.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pleret.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q20426944', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9802, NULL, 4, 'Museum Flora dan Fauna Tarakan', 'Pamusian', 'Sebengkok, Tarakan, Kalimantan Utara', 'Museum Flora dan Fauna Tarakan atau Museum Flora dan Fauna Roemah Boendar Kota Tarakan adalah sebuah museum yang pernah beroperasi di Kota Tarakan, Provinsi Kalimantan Utara, Indonesia. Museum ini pernah memamerkan berbagai macam flora dan fauna endemik baik dari Pulau Tarakan maupun dari daerah lain di Kalimantan Utara. Museum ini berlokasi di kelurahan Pamusian, Kota Tarakan.', 3.3132975, 117.5946028, 0, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Flora%20dan%20Fauna%20Kota%20Tarakan.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q25459827', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9803, NULL, 4, 'Museum Samparaja', 'Nusa Tenggara Barat', 'Jalan Gajah Mada, Kelurahan Pane, Bima, Nusa Tenggara Barat', 'Museum Samparaja adalah museum khusus yang didedikasikan untuk sejarah lokal. Museum Samparaja terletak di Jalan Gajah Mada, Monggonao, Mpunda, Bima, Nusa Tenggara Barat. Pendiri sekaligus pengurus Museum Samparaja adalah Hj.', -8.4554574, 118.7402169, 15000, ' 08.00–14.00; Jum 08.00–11.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Samaparaja%2C%20Bima.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940691', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9804, NULL, 4, 'Museum Tanah dan Pertanian', 'Bogor', 'Jalan Pedati, Bogor Tengah, Bogor, Jawa Barat', 'Museum Tanah dan Pertanian merupakan museum yang menyajikan informasi tentang segala sesuatu yang berkaitan dengan tanah. Museum Tanah telah berdiri sejak 29 September 1988, museum ini menempati gedung Laboratorium Voor Agrogeologie en Grond Onderzoek atau Laboratorium Penelitian Agrogeologi dan Tanah, yang didirikan pada zaman Pemerintahan Belanda sekitar tahun 1900.\nMuseum sempat mengalami penutupan beberapa tahun sampai kemudian Kementerian Pertanian memutuskan untuk melakukan renovasi gedung tersebut untuk dimanfaatkan sebagai museum.', -6.603208, 106.7981917, NULL, ' 9 AM–jam 4 sore', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Tanah%20dan%20Pertanian.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940811', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9805, NULL, 4, 'Museum Nasional Sejarah Alam Indonesia', 'Jawa Barat', 'Jalan Kantor Batu, Bogor Tengah, Bogor, Jawa Barat', 'Museum Nasional Sejarah Alam Indonesia (MUNASAIN), dulunya bernama Museum Etnobotani Indonesia, adalah sebuah museum di Kota Bogor yang menyimpat koleksi dan penjelasan sejarah alam Indonesia terkait hubungan berbagai sumber daya hayati dengan etnografi di wilayah Indonesia.', -6.5988649, 106.793942, NULL, ' 08.00–16.00;  07.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Nasional%20Sejarah%20Alam%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940814', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9806, NULL, 4, 'Museum Kepresidenan Republik Indonesia Balai Kirti', 'Bogor', 'Jalan Insinyur Haji Djuanda, Bogor Tengah, Bogor, Jawa Barat', 'Museum Kepresidenan Republik Indonesia Balai Kirti adalah sebuah museum yang berada di dalam Kompleks Istana Kepresidenan Bogor, Jalan Ir. Juanda Nomor 1, Kota Bogor, Jawa Barat, Indonesia. Museum ini dibangun khusus untuk menampilkan kisah sejarah pemerintahan para presiden Indonesia.', -6.5982318, 106.7943045, NULL, ' 9 AM–15.00;  9 AM–13.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kepredisenan%20RI%20Balai%20Kirti.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940812', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9807, NULL, 4, 'Museum Rahmah El Yunusiyah', 'Pasar Usang', 'Padang Panjang Barat, Padang Panjang, Sumatera Barat', 'Museum Rahmah El Yunusiyah adalah museum khusus yang menyimpan memoar dan peninggalan Rahmah El Yunusiyah, seorang ulama, pejuang kemerdekaan, dan pendidik yang mendirikan perguruan Diniyyah Puteri. Museum ini terletak di Jalan Abdul Hamid Hakim, Kelurahan Pasar Usang, Kota Padang Panjang, Sumatera Barat, Indonesia.\nMuseum ini diresmikan pembukannya pada 26 Agustus 2019 oleh Direktur Jenderal Kebudayaan Kementerian Pendidikan dan Kebudayaan RI Hilmar Farid.', -0.4611873, 100.3983176, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rahmah%20El%20Yunusiyah%20oleh%20Denas.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108948917', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9808, NULL, 4, 'Museum Dewan Perwakilan Rakyat Republik Indonesia', 'Jakarta', 'Jalan Tentara Pelajar, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Dewan Perwakilan Rakyat Republik Indonesia atau Museum DPR RI adalah museum khusus yang menampilkan koleksi serta informasi mengenai sejarah lembaga parlemen di Indonesia sejak masa Hindia Belanda (dengan nama Volksraad atau Dewan Rakyat) hingga berdiri dengan nama DPR RI. Museum DPR RI terletak di dalam Kompleks MPR/DPR/DPD tepatnya di Lantai 2 Gedung Nusantara.', -6.2102027, 106.7997735, 0, 'Jum 08.00–15.30;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/MuseumDPRRI.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108958446', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9809, NULL, 4, 'Museum Gedung Sate', 'Bandung', 'Jalan Diponegoro No.22, Bandung Wetan, Kota Bandung, Jawa Barat', 'Museum Gedung Sate adalah sebuah museum yang berada di Jalan Diponegoro Nomor 22, Kota Bandung. Alamat lengkapnya masuk dalam wilayah Kelurahan Citarum, Kecamatan Bandung Wetan. Museum ini dibangun khusus untuk menjelaskan tentang sejarah Gedung Sate.', -6.9022262, 107.6192292, NULL, ' 09.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Gedung%20Sate.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108991304', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9810, NULL, 4, 'Museum Perbendaharaan', 'Bandung', 'Jalan Diponegoro No.45B, Cibeunying Kaler, Kota Bandung, Jawa Barat', 'Museum Perbendaharaan adalah museum yang berada di dalam kompleks Kantor Wilayah Direktorat Jenderal Perbendaharaan, Kementerian Keuangan Republik Indonesia. Pembangunan Museum Perbendaharaan berlangsung selama satu tahun dan diselesaikan pada tanggal 21 November 2015. Peresmian dan pembukaan untuk umum atas Museum Perbendaharan diadakan pada tanggal 26 September 2017.', -6.9012741, 107.6167514, 0, 'Sen 9 AM–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Museum%20Perbendaharaan%202023-03-18.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109001170', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9811, NULL, 4, 'Batak Museum', 'Simanindo', NULL, 'Batak Museum atau yang bisa disebut Museum Batak Tomok adalah museum yang memamerkan koleksi terkait dengan kehidupan masyarakat Toba di masa lampau. Museum ini terletak di Desa Tomok, Kecamatan Simanindo, Kabupaten Samosir, Sumatera Utara. Di bangun pada tahun 2005, dengan arsitektur bangunan khas Batak yang disebut Rumah Bolon.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Batak%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109312226', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9812, NULL, 4, 'museum Huruf Jember', 'Jember', 'Jalan Bengawan Solo, Jember, Jawa Timur', 'Museum Huruf Jember adalah museum khusus yang memberikan informasi tentang aksara dan dialektik dari beragam masyarakat di Nusantara. Gagasan pendirian museum ini dicetuskan oleh Ade Sidiq Permana dan Erik Wijayanto. \nMuseum ini awalnya adalah rumah pribadi Erik.', -8.1679823, 113.7070474, 5000, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Suasana%20museum%20huruf%20estetik.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433129', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9813, NULL, 4, 'Museum BNI 1946', 'Jakarta', 'Jalan Lada No.1, Taman Sari, Jakarta Barat', 'Museum BNI 1946 adalah sebuah museum yang berada di area Kota Tua Jakarta, tepatnya di Jalan Lada Nomor 1, Kota Tua Jakarta, Kelurahan Pinangsia, Kecamatan Taman Sari, Kota Administrasi Jakarta Barat, Provinsi Daerah Khusus Ibukota Jakarta. Tujuan pembangunan Museum BNI 1946 adalah sebagai museum khusus yang memberikan pengetahuan sejarah mengenai Bank Negara Indonesia.', -6.1345725, 106.8149376, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BNI%20Kota%20-%20panoramio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433478', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9814, NULL, 4, 'Museum Surabaya', 'Surabaya', 'Jalan Tunjungan No.1-3, Genteng, Surabaya, Jawa Timur', 'Museum Surabaya adalah sebuah museum yang terletak di Kota Surabaya. Alamat museum di Jalan Tunjungan Nomor 1-3, Kelurahan Genteng, Kecamatan Genteng. Museum ini berada di dalam gedung ex.SIOLA. Museum Surabaya berisi koleksi benda-benda bersejarah tentang Kota Surabaya.', -7.2563056, 112.7376389, 0, ' 09.00–20.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Foto%20Museum%20Surabaya%20Siola.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433481', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9815, NULL, 4, 'Museum Pendidikan Nasional Universitas Pendidikan Indonesia', 'Bandung', 'Jalan Dr. Setiabudi, Sukasari, Kota Bandung, Jawa Barat', 'Museum Pendidikan Nasional Universitas Pendidikan Indonesia atau yang biasa disingkat Mupenas, adalah sebuah museum yang berada di bawah naungan Unversitas Pendidikan Indonesia. Terletak di area universitas yang beralamat di\nFungsi khusus museum ini untuk memberikan informasi mengenai sejarah dan perkembangan pendidikan di Indonesia. Museum ini juga menghadirkan informasi mengenai pendirian dan perkembangan Universitas Pendidikan Indonesia.', -6.8597099, 107.5942154, NULL, ' 08.00–15.00; Jum 08.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Museum%20Pendidikan%20Nasional%20UPI%202023-03-20.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433484', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9816, NULL, 4, 'Rumah Topeng dan Wayang Setia Darma', 'Ubud', 'Jalan Tegal Bingin, Ubud, Bali', 'Rumah Topeng dan Wayang Setia Darma adalah sebuah museum yang terletak di Jalan Tegal Bingin Mas, Ubud, Banjar Tengkulak Tengah, Desa Kemenuh, Sukawati, Gianyar, Bali. Museum ini khusus mengoleksi topeng dan wayang dari berbagai wilayah di Indonesia dan juga mancanegara. Pendiri museum ini adalah seorang pengusaha dan pecinta budaya bernama Hadi Sunyoto, beliau dibantu oleh mendiang A. Prayitno seorang pemerhati seni budaya.', -8.5338203, 115.2805198, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/001%20First%20House%2C%20Setia%20Darma%20Mask%20and%20Puppet%20House%2C%20Ubud%2C%20Bali%2C%20photograph%20by%20Anandajoti%20Bhikkhu.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433513', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9817, NULL, 4, 'Makam Giri Sapto', 'Yogyakarta', 'Jalan Wukirsari, Wukirsari, Imogiri, Daerah Istimewa Yogyakarta', 'Taman Makam Seniman dan Budayawan Giri Sapto adalah sebuah kompleks makam para seniman dan budayawan yang terletak di Bukit Gajah, Desa Giri Rejo, Kecamatan Imogiri, Kabupaten Bantul, Daerah Istimewa Yogyakarta (DIY).\nMakam ini mulai dibangun oleh seniman lukis Saptohoedojo pada tahun 1988 dan berada tidak jauh dari Makam Raja-Raja Mataram. \nLuas makam sekitar 5 hektare dan desainnya berjenjang mengikuti bentuk bukit.', -7.9198932, 110.3920899, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Makam%20Seniman%20dan%20Budayawan%20Giri%20Sapto%20Imogiri.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q115863395', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9818, NULL, 4, 'Museum Kota Subang', 'Subang', 'Jalan Dewi Sartika, Pasirkareumbi, Subang, Jawa Barat', 'Museum Kabupaten Subang merupakan museum yang berada di Kabupaten Subang, Jawa Barat. Bangunan museum ini berdiri di Gedung WIsma Karya Jalan Ade Irma Suryani nomor 2. Museum ini merupakan museum satu-satunya di wilayah Subang.', -6.5707731, 107.7594672, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kabupaten%20Subang%20-%2012.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q115864208', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9819, NULL, 4, 'Museum Nyoman Gunarsa', 'Klungkung', 'Jalan Raya Banda No.1, Banjarangkan, Bali', 'Museum Seni Lukis Bali Klasik adalah sebuah museum yang didirikan oleh pelukis di Bali sebagai bentuk sumbangan bagi tempat kelahirannya. Museum serupa juga didirikan sebelumnya di Yogyakarta pada tahun 1987. Terdapat berbagai keunikan yang mendasari pendirian Museum Seni Lukis Klasik Bali salah satunya adalah lokasi museum yang dianggap angker karena diapit di sebelah kanan dan sebelah kirinya oleh kuburan atau setra Banda dan setra Umesalakan sedangkan di depannya terdapat pertigaan agung.', -8.551926, 115.3868708, NULL, '09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gunarsa-cious.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65212194', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9820, NULL, 4, 'Museum Polri', 'Jakarta', 'Jalan Pattimura, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Museum Polri adalah museum yang memperlihatkan perjalanan panjang Kepolisian Negara Republik Indonesia kepada masyarakat, di dalam tugasnya sebagai pelindung serta penjaga ketertiban di dalam masyarakat, dan juga sebagai kekuatan perang dalam mempertahankan kemerdekaan Indonesia.\nMuseum ini diresmikan pada tanggal 29 Juni 2009, dan mulai dibuka untuk umum pada 1 Juli 2009. Pendirian museum didorong keinginan Jenderal Polisi Bambang Hendraso.', -6.2393, 106.8027, NULL, 'Sen–Min 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20polri%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729526', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9821, NULL, 4, 'Museum Purbakala Muara Kaman', 'Kalimantan Timur', 'Jalan Mulawarman, Muara Kaman Ilir, Kutai Kartanegara, Kalimantan Timur', 'Museum Purbakala Muara Kaman atau Museum Kutai Mulawarman Ing Martadipura adalah sebuah museum yang terletak di Kecamatan Muara Kaman, Kabupaten Kutai Kartanegara, Kalimantan Timur. Museum ini adalah museum ketiga yang didirikan oleh Pemerintah Kabupaten Kutai Kartanegara setelah Museum Mulawarman dan Museum Kayu Tuah Himba yang berada di Kota Tenggarong.', -0.1469302, 116.7258979, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Purbakala%20Muara%20Kaman.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729528', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9822, NULL, 4, 'Siola', 'Surabaya', 'Jalan Tunjungan, Genteng, Surabaya, Jawa Timur', 'Gedung Siola (sebelumnya dinamakan White Laidlaw) adalah sebuah gedung bersejarah di Kota Surabaya, Provinsi Jawa Timur, Indonesia. Gedung ini sebelumnya pernah digunakan oleh para pejuang Indonesia untuk meredam serangan oleh pasukan Sekutu yang datang dari utara kota. Akibatnya, Pertempuran sengit membuat pejuang meluluh lantahkan gedung ini.', -7.25875, 112.7387778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tunjungan%20Siola%20di%202022%20%28infobox%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19734246', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (9823, NULL, 4, 'Museum Mandala Bhakti', 'Jawa Tengah', 'Jalan MGR. Sugiopranoto, Semarang Selatan, Kota Semarang, Jawa Tengah', 'Museum Mandala Bhakti (bahasa Jawa: ꦩꦸꦱꦶꦪꦸꦩ꧀ꦩꦤ꧀ꦢꦭꦨꦏ꧀ꦠꦶ, translit. Musiyum Mandala Bhakti) adalah sebuah museum bertema perjuangan yang berlokasi di Kota Semarang. Alamat Museum Mandala Bhakti di Jalan Sugiyopranoto No.', -6.9845206, 110.4093092, NULL, ' 08.00–15.00; Sab 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mandala%20Bhakti%20met%20op%20de%20voorgrond%20het%20monument%20Tugu%20Muda%20aan%20de%20Taman%20Tugu%20Muda%20te%20Semarang%2C%20KITLV%20D13345.tiff?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19746470', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9824, NULL, 4, 'Museum Agung Bung Karno', 'Denpasar', 'Raya Puputan, Denpasar Timur, Denpasar, Bali', 'Museum Agung Bung Karno adalah museum yang menyimpan peninggalan bersejarah yang berhubungan dengan Soekarno—presiden pertama Indonesia. Museum ini terletak di Jalan Raya Puputan 80, Dangin Puri Klod, Denpasar, Bali. Letak tepatnya berada di sisi barat pusat kota Denpasar, tak jauh dari Puputan Renon.', -8.672314, 115.225437, 10000, ' 9 AM–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Agung%20Bung%20Karno.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q23808507', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9825, NULL, 4, 'Kadato Kie', 'Indonesia', 'Soa, Ternate, Maluku Utara', 'Kadato Kie (Istana Kie), juga disebut Kedaton Tidore, adalah istana tempat bersemayamnya sultan dari Kesultanan Tidore. Istana ini terletak di Kelurahan Soasio, Kecamatan Tidore, Kota Tidore Kepulauan. Awal mulanya setelah konflik dengan Portugis dan Spanyol, Sultan Syaifuddin atau Kaicil Golofino memindahkan ibukota ke Limau Timore, dibangunlah sebuah kedaton dengan nama Kadato Ijo yang kemudian dikenal dengan nama Fola Ijo, ini karena bangunan diwarnai hijau.', 0.8003884, 127.3649821, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kadato%20Kie.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q28725532', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9826, NULL, 4, 'Museum Musik Indonesia (MMI)', 'Jawa Timur', 'Lowokwaru, Kota Malang, Jawa Timur', 'Museum Musik Indonesia (MMI) merupakan satu-satunya museum seni musik di Indonesia, berada di Kota Malang, Jawa Timur. Tiap-tiap aspek kehidupan memiliki sejarahnya sendiri yang patut dikenang. Demikian pula dengan perkembangan musik yang tiap-tiap zamannya memiliki masa keemasannya.', -7.9402408, 112.6208274, 5000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Kesenian%20Gajayana%20-%20Museum%20Musik%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q56412803', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9827, NULL, 4, 'Museum Balla Lompoa', 'Sulawesi Selatan', 'Jalan K.H. Wahid Hasyim No.39, Somba Opu, Sungguminasa, Sulawesi Selatan', 'Museum Ballaʼ Lompoa atau Ballaʼ Lompoa ri Sungguminasa adalah sebuah museum yang terletak di Jalan Wahid Hasyim, Kelurahan Sungguminasa. Museum ini didirikan pada tanggal 11 Desember 1973. Ballaʼ Lompoa merupakan arsitek rumah etnis Makassar dapat diartikan rumah besar dalam bahasa Makassar atau istana bagi raja-raja dari Kerajaan Gowa.', -5.2066181, 119.4527762, 2000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/MuseumBallaLompoa.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203916', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9828, NULL, 4, 'Museum Buntu Kalando', 'Sulawesi Selatan', 'Sangalla, Sulawesi Selatan', 'Museum Buntu Kalando merupakan salah satu museum yang berada di Tana Toraja, Sulawesi Selatan, tepatnya terletak di atas Bukit Sanggala. Dulunya, museum ini merupakan bekas istana yang memiliki gaya bangunan berbentuk klasik tradisional. Terdapat sembilan  buah lumbung padi di depan museum yang melambangkan ciri istana atau rumah adat Toraja.', -3.0855983, 119.9127326, 5000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Buntu%20Kalando%2003.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203923', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9829, NULL, 4, 'Museum Gereja Batak Karo Protestan', 'Sumatera Utara', 'Durin Serugun, Kabupaten Deli Serdang, Sumatera Utara', 'Museum Gereja Batak Karo Protestan (disingkat Museum GBKP) adalah museum yang terletak di kompleks Taman Jubelium 100 Tahun GBKP di Bandar Baru, Sibolangit, Kabupaten Deli Serdang, Sumatera Utara. Museum GBKP didirikan sebagai bagian dari perayaan Jubileum 100 tahun Gereja Batak Karo Protestan (GBKP) untuk melestarikan warisan dan dokumen sejarah masuk dan berkembangnya Kekristenan di tengah masyarakat Batak Karo.\nPeletakan batu pertama museum ini dilaksanakan pada tanggal 30 Juli 1990, kemudian diresmikan pada tanggal 11 Agustus 2007 oleh Gubernur Sumatera Utara Rudolf Pardede.', 3.2811333, 98.5546917, 2000, ' 09.00–16.00;  13.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Batak%20Karo%20Protestan%20tampak%20samping.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203930', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9830, NULL, 4, 'Museum Kota Makassar', 'Sulawesi Selatan', 'Jalan Balai Kota, Ujung Pandang, Makassar, Sulawesi Selatan', 'Museum Kota Makassar berada di provinsi Sulawesi Selatan yang didirikan oleh/atas ide wali kota Makassar Drs. HB. Amiruddin Maula, S.H., M.Si pada masa awal-awal menjabat. Museum beralamat di Jl.', -5.13462, 119.40854, 5000, ' 9 AM–15.00;  9 AM–13.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kota%20Makassar.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203944', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9831, NULL, 4, 'Museum Perundingan Linggajati', 'Jawa Barat', 'Jalan Ciremai, Linggajati, Kuningan, Jawa Barat', 'Museum Perundingan Linggajati adalah sebuah museum yang terletak di Desa Linggajati, Kecamatan Cilimus, Kabupaten Kuningan, Jawa Barat. Museum ini didirikan untuk memperingati peristiwa bersejarah Perundingan Linggajati yang terjadi pada tahun 1946-1947 antara pihak Indonesia dan Belanda.', -6.8812543, 108.4747908, NULL, ' 08.00–17.00;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Perundingan%20Linggarjati%2C%20Kuningan001.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203972', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9832, NULL, 4, 'Museum Simalungun', 'Pematang Siantar', 'Jalan Jenderal Sudirman, Siantar Barat, Kota Pematangsiantar', 'Museum Simalungun adalah sebuah museum daerah yang berada di Jalan Sudirman Nomor 20, Kelurahan Proklamasi, Kecamatan Siantar Barat, Kota Pematangsiantar, Provinsi Sumatera Utara.\nMuseum ini mulai dibangun pada bulan April tahun 1939 dan selesai dibangun pada bulan Desember pada tahun yang sama. Pembangunan museum bertujuan untuk melestarikan budaya Batak Simalungun seperti benda-benda cagar budaya yang bernilai sejarah.', 2.954288, 99.061083, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20bolon%20simalungun.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203990', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9833, NULL, 4, 'Museum Tebing Tinggi', 'Sumatera Utara', 'Jalan Gereja, Tebing Tinggi Kota, Kota Tebing Tinggi, Sumatera Utara', 'Museum Kota Tebing Tinggi terletak di Jalan Kotamadya, Kota Tebing Tinggi, Provinsi Sumatera Utara. Objek wisata edukasi ini selain berfungsi sebagai sarana pembelajaran bagi para pelajar dan masyarakat, tetapi juga untuk melestarikan peninggalan bersejarah yang terdapat di Kota Tebing Tinggi.', 3.3286944, 99.1629444, 5000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Plang%20nama%20Museum%20Kota%20Tebing%20Tinggi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q86587413', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9834, NULL, 4, 'Museum Geopark Batur', 'Bangli', 'Jalan Raya Penelokan, Kintamani, Bali', 'Museum Geopark Batur adalah museum yang menyajikan informasi taman bumi nasional dan mancanegara. Letaknya di Jalan Raya Pengelokan, Kintamani, Bangli, Bali. Peresmiannya dilakukan pada tanggal 10 Mei 2017.', -8.2834848, 115.3650607, 0, ' 08.00–16.00;  08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Geopark%20Batur%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q95376573', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9835, NULL, 4, 'Museum Bahari Bintan', 'Kepulauan Riau', 'Jalan Wisata Bahari, Teluk Bakau, Bintan, Kepulauan Riau', 'Museum Bahari Bintan adalah museum khusus yang terletak di Kabupaten Bintan. Peresmian Museum Bahari Bintan diadakan pada tahun 2006. Keunikan Museum Bahari Bintan adalah desain arsitektur bangunannya yang berbentuk perahu Kajang.', 1.02435, 104.65294, NULL, ' 08.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Bahari%20Bintan%20%28Tampak%20kanan%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97195068', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9836, NULL, 4, 'Museum Ne\' Gandeng', 'Sulawesi Selatan', 'Jalan Poros Rantepao - Sa\'dan - Batas Kab. Luwu, Pangli, Toraja Utara, Sulawesi Selatan', 'Museum Ne\' Gandeng atau Museum Rambu Solo Ne Gandengadalah museum yang terletak di Lembang Palangi, Kecamatan Balusu, Kabupaten Toraja Utara, Provinsi Sulawesi Selatan. Nama Museum Ne\' Gandeng berasal dari nama salah satu tokoh masyarakat Toraja yang bernama Ne\' Gandeng. Museum Ne\' Gandeng terdiri dari beberapa bangunan yang menerapkan gaya arsitektur Tongkonan.', -2.9287364, 119.9490063, 5000, ' 07.00–21.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Ne%60Gandeng%20Toraja%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97195150', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9837, NULL, 4, 'Museum Pahlawan Nasional Jamin Gintings', 'Sumatera Utara', 'Jalan Museum Ginting Suka, Suka Mbayak, Kabupaten Karo, Sumatera Utara', 'Museum Pahlawan Nasional Letjen Jamin Gintings (dikenal sebagai Museum Letjen Jamin Gintings) adalah museum khusus yang diresmikan pada tanggal 17 September 2013. Peresmian museum ini dilakukan oleh Menteri Pertahanan Indonesia, Purnomo Yusgiantoro. Museum Pahlawan Nasional Jamin Gintings dibangun untuk mengenang seorang tokoh Pahlawan Nasional Indonesia yaitu Jamin Gintings.', 3.06115, 98.5206, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pahlawan%20Nasional%20Jamin%20Ginting.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97198871', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9838, NULL, 4, 'Museum Karst dan Budaya', 'Sulawesi Selatan', 'Pangkajene, Sulawesi Selatan', 'Museum Karst dan Budaya Bungoro adalah museum wisata unggulan sebagai kawasan konservasi dan destinasi yang terletak di Pangkajene Kepulauan, tepatnya berada di halaman Rumah jabatan Bupati Pangkep, Jl Andi Burhanuddin, Tumampua, Kecamatan Pangkajene, Kabupaten Pangkajene Kepulauan, Sulawesi Selatan.\nMuseum ini diresmikan pada tanggal 5 April 2005 oleh Menteri Negara Lingkungan Hidup Republik Indonesia Ir. Rachmat Witoelar dan kemudian ditetapkan sebagai Museum Koleksi Karst dan Budaya pada 22 Nopember 2008 oleh Bupati Pangkep, Syafrduin Nur.', -4.8358478, 119.5466786, 0, ' 07.30–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Karst%20dan%20Budaya%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97222527', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9839, NULL, 4, 'Museum La Pawawoi', 'Sulawesi Selatan', 'Jalan Sungai Citarum No.9, Watampone, Sulawesi Selatan', 'Museum La Pawawoi merupakan bangunan bekas Istana Andi Mappanyukki Sultan Ibrahim Raja Bone ke XXXII. Bangunan ini berdiri di lahan 600 m² dengan luas 150 m² yang terletak di Jl. K.H. Thamrin No.9 Watampone, Kecamatan Tenete Rianttang, Kabupaten Bone, Sulawesi Selatan. Museum ini didirikan sejak 5 Januari 1971 oleh Bupati Bone, H. Suaib.', -4.5373923, 120.3289189, NULL, ' 08.00–12.00;  08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20La%20Pawawoi%2007.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97238386', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9840, NULL, 4, 'Museum Sonyine Malige', 'Tidore Kepulauan', 'Royal Port, Soadara, Tidore Kepulauan, Maluku Utara', 'Museum Sonyine Malige adalah museum yang menyimpan koleksi benda berharga milik sultan dan para bangsawan dari Kesultanan Tidore. Pembangunan museum berasal dari hibah masyarakat Tidore. Museum Sonyine Malige diresmikan oleh Direktorat Jenderal Kebudayaan Indonesia, yaitu Haryati Soebadio pada tahun 1982.', 0.6501207, 127.443615, NULL, ' 9 AM–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sonyine%20Malige%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97238393', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9841, NULL, 4, 'Museum Bikon Blewut', 'Sikka', 'Jalan Sikka 7, Nangalimang, Sikka, Nusa Tenggara Timur', 'Museum Bikon Blewut adalah museum yang terletak di atas perbukitan desa Takaplager, Kecamatan Nita, Kabupaten Sikka, Nusa Tenggara Timur yang didirikan oleh Pater Dr. Theodor Verhoeven dan berada di dalam kompleks Seminari Tinggi St. Paulus Ledalero.', -8.6662809, 122.1843556, NULL, ' 07.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Bikon%20Blewut.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97242585', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9842, NULL, 4, 'Museum Pusaka Karo', 'Sumatera Utara', 'Jalan Perwira, Berastagi, Sumatera Utara', 'Museum Pusaka Karo adalah salah satu museum yang ada di Kabupaten Karo berada di Jl. Perwira no 1 kelurahan Gundaling 1, kecamatan Berastagi, Sumatera Utara, Indonesia yang menyimpan koleksi barang-barang pusaka masyarakat Karo. Museum ini didirikan oleh misionaris Kapusin Belanda bernama oleh Pastor Leo atau Leonardus Egidius Joosten .', 3.19492, 98.50822, 8000, 'Min 13.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pusaka%20Karo%20%28Berastagi%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97306884', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9843, NULL, 4, 'History of Sundaland Museum', 'Karawang', 'Karawang, Jawa Barat', 'Museum History of Sundaland merupakan museum kebudayaan lokal Indonesia yang mengangkat kisah tentang peradaban Tanah Sunda sejak zaman purbakala hingga era modern. Di Museum History of Sundaland terdapat 17 Zona yang berkisah tentang peradaban Tanah Sunda hingga kehidupan di kerajaan Hindu-Buddha sampai Kerajaan Islam.\nSeperti namanya, Museum History of Sundaland berkisah tentang peradaban sejarah Tanah Pasundan.', -6.3267783, 107.2945556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kunjungan%20Atalia%20Ridwan%20Kamil%20di%20Museum%20History%20of%20Sundaland.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108651654', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9844, NULL, 4, 'Museum Matan', 'Ketapang', 'Sutera, Sukadana, Kalimantan Barat', 'Museum Matan atau Museum Gusti Saunan adalah museum umum yang didirikan di bekas keraton Kesultanan Matan Ketapang yang berada di jalan Pangeran Kesumajaya, desa Mulia Kerta, Benua Kayong, Ketapang, Kalimantan Barat. \nSelain disebut sebagai museum, bangunan yang berupa istana ini juga disebut Keraton Kerajaan Matan Tanjungpura dan dulunya disebut Keraton Mulia Kerta oleh warga.', -1.2406439, 109.9488484, NULL, ' 09.00–17.00; Jum 14.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Kerajaan%20Matan%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108919984', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9845, NULL, 4, 'Museum Mansinam', 'Manokwari Timur', 'Manokwari, Papua Barat', 'Museum Mansinam atau dikenal juga dengan Museum Pekabaran Injil adalah museum tematik pertama di Papua Barat yang terletak di Pulau Mansinam, Distrik Manokwari Selatan, Kabupaten Manokwari. \nMuseum ini didirikan pada tahun 2014 oleh pemerintah Kabupaten Manokwari dan diresmikan oleh Presiden Republik Indonesia ke-6 Susilo Bambang Yudhoyono. Museum Mansinam didirikan untuk mengenang sejarah masuknya agama Kristen di Tanah Papua.', -0.891557, 134.0918263, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pekabaran%20Injil%20Mansinam.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108920816', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9846, NULL, 4, 'Museum Noken', 'Heram', 'Waena, Jayapura, Papua', 'Museum Noken adalah museum yang menyimpan kerajinan tangan khas Papua berupa sebuah tas tradisional yang disebut Noken. Museum ini didirikan dengan tujuan melestarikan berbagai koleksi Noken asli Papua yang telah ditetapkan oleh UNESCO menjadi salah satu warisan dunia  Museum ini terletak di Waena, Abepura, Jayapura dan diresmikan pada tahun 2013. Pembangunan museum ini menggunakan dana dari APBN yang dianggarkan oleh Direktorat Jenderal (Ditjen) Kebudayaan, Kementrian Pendidikan dan Kebudayaan.', -2.5958829, 140.6316911, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Noken%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108921059', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9847, NULL, 4, 'Museum Karaeng Pattingalloang', 'Sulawesi Selatan', 'Jalan Abdul Kadir, Tamalate, Makassar, Sulawesi Selatan', 'Museum Karaeng Pattingalloang adalah museum khusus yang dibangun untuk mengenang riwayat hidup Karaeng Pattingalloang. Museum ini mulai dibangun sejak tahun 1989 dan selesai pada tahun 1995. Letak museum berada di sekitar Benteng Somba Opu, Barombong, Gowa.', -5.1908685, 119.4041735, NULL, ' 08.00–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fasad%20Museum%20Karaeng%20Pattingalloang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940229', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9848, NULL, 4, 'Museum Singhasari', 'Malang', 'Jalan Tumapel No.Singhasari Residence, Krajan, Desa Klampok, Kecamatan Singosari, Kabupaten Malang, Jawa Timur, Tuboro, Kota Malang, Jawa Timur', 'Museum Singhasari adalah sebuah museum yang terletak di dalam Perumahan Singhasari Residence, Krajan, Desa Klampok, Kecamatan Singosari, Kabupaten Malang, Provinsi Jawa Timur. Status museum ini ialah museum khusus. Fungsi khususnya yaitu mengoleksi benda-benda arkeologi dan etnografi.', -7.88125, 112.64135, 0, ' 08.00–21.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Singhasari.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940612', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9849, NULL, 4, 'Museum Pong Tiku', 'Sulawesi Selatan', 'Jalan Landorundun, Karassik, Rantepao, Sulawesi Selatan', 'Museum Pong Tiku atau Museum Toraja Utara dalah museum umum yang menyediakan koleksi yang berkaitan tentang masyarakat suku Toraja yang berada di Rantepao, Toraja Utara, Sulawesi Selatan. Penamaan museum ini berasal dari nama tokoh pejuang kemerdekaan Toraja, Pong Tiku.\nMuseum Pong Tiku beralamat di Jalan Landorundun, Rantepao, Toraja Utara, Sulawesi Selatan.', -2.9700189, 119.8977348, 5000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pong%20Tiku%20Toraja%20Utara%2033.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940618', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9850, NULL, 4, 'Museum Mpu Purwa', 'Jawa Timur', 'Jalan Soekarno-Hatta No.Perumahan Griya Santa No. 210, Lowokwaru, Kota Malang, Jawa Timur', 'Museum Mpu Purwa adalah museum yang mengoleksi benda-benda purbakala yang ada di Indonesia, khususnya Pulau Jawa. Koleksinya meliputi patung, arca, candi dan prasasti dari berbagai kerajaan di Jawa. Benda-benda tersebut dahulu digunakan dalam berbagai aktivitas kerajaan dan menghilang bersama dengan keruntuhan kerajaannya.', -7.94019, 112.62078, 0, ' 08.00–16.00;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mpu%20Purwa.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940676', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9851, NULL, 4, 'Museum Tambang Batubara Ombilin', 'Kota Sawahlunto', 'Jalan Saka Ombilin, Saringan, Sawahlunto, Sumatera Barat', 'Museum Tambang Batubara Ombilin adalah sebuah museum yang terletak di Kota Sawahlunto, Sumatera Barat, Indonesia. Museum ini beralamat di Jalan M. Yamin, Kelurahan Pasar, Kecamatan Lembah Segar, tepatnya berapada di kawasan pusat kota yang dahulu menjadi area inti tambang batubara Ombilin. Museum ini didirikan untuk melestarikan sejarah pertambangan batubara di kawasan Ombiiln, yang merupakan dalah satu tambang batubara tertua di Indonesia.', -0.6798889, 100.7775556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Tambang%20Batu%20Bara%20Ombilin.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q71662616', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9852, NULL, 4, 'Museum Deli Serdang', 'Sumatera Utara', 'Jalan Raya Medan-Tebing Tinggi, Petapahan, Lubuk Pakam, Sumatera Utara', 'Museum Daerah Deli Serdang atau Museum Deli Serdang adalah museum sejarah dan budaya yang terletak di lokasi kompleks perkantoran pemerintahan, yaitu di Tanjung Garbus I, Lubuk Pakam, Deli Serdang.', 3.55184, 98.8665393, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Landmark%20Museum%20Deli%20Serdang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q72282879', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9853, NULL, 4, 'Museum Pendidikan Indonesia', 'Sleman', 'Jalan Colombo, Catur Tunggal, Sleman, Daerah Istimewa Yogyakarta', 'Museum Pendidikan Indonesia atau MPI didirikan sebagai dedikasi bagi Universitas Negeri Yogyakarta (UNY). Melalui museum ini disampaikan bahwa kejayaan bangsa ini merupakan hasil dari harmonisasi antara tujuan perjuangan dan semangat untuk menuntut ilmu.\nMuseum Pendidikan Indonesia dibangun sebagai bentuk penghargaan bagi para perintis, tokoh, dan pejuang pendidikan nasional.', -7.7744648, 110.3851762, NULL, 'Sen–Jum 08.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pendidikan%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97307324', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9854, NULL, 4, 'Museum Popa Eyato', 'Tamalate', 'Kota Timur, Gorontalo, Gorontalo', 'Museum Popa Eyato merupakan satu-satunya museum yang menyimpan berbagai peninggalan sejarah di Provinsi Gorontalo. Mulai dari foto-foto peninggalan masa penjajahan, berbagai alat rumah tangga kuno, berbagai jenis senjata tajam, seperti tombak, parang dan badik, hingga bendera merah putih yang pertama yang dikibarkan, saat upacara kemerdekaan Gorontalo 23 Januari 1942.\nNama Museum Popa Eyato yang diambil dari dua nama raja berpengaruh yang pernah memimpin kerajaan yang ada di Gorontalo.', 0.5363279, 123.0786709, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Provinsi%20Gorontalo.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97307462', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9855, NULL, 4, 'Museum Batiwakkal', 'Gunung Tabur', 'Jalan Manunggal, Tanjung Redeb, Kalimantan Timur', 'Museum Batiwakkal adalah sebuah museum yang berada di Kabupaten Berau, Provinsi Kalimantan Timur. Museum yang terletak di kecamatan Gunung Tabur ini dibangun pada tahun 1990 dan dibuka untuk umum pada tahun 1992. Museum ini juga merupakan renovasi ulang dari bentuk asli Keraton Gunung Tabur.', 2.16013, 117.492, 2000, 'Sab 08.30–13.00;  08.30–16.00; Min 08.30–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Batiwakkal.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97308159', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9856, NULL, 4, 'Museum Batara Guru', 'Sulawesi Selatan', 'Jalan Andi Djemma No.1, Pontap, Palopo, Sulawesi Selatan', 'Museum Batara Guru adalah sebuah museum yang mengoleksi warisan budaya Kerajaan Luwu dan berlokasi di Jl. Andi Jemma No.1, Kelurahan Batupasi, Kecamatan Wara Utara, Kabupaten Luwu, Palopo, Provinsi Sulawesi Selatan. Museum Batara Guru merupakan museum yang didirikan dengan tujuan melestarikan warisan budaya dan sejarah Kerajaan Luwu.', -2.9773301, 120.1960226, NULL, 'Jum 08.00–13.00; Min 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Batara%20Guru%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97374356', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9857, NULL, 4, 'Museum Rumah Sakit Mata Dr. Yap', 'Yogyakarta', 'Jalan Cik di Tiro, Gondokusuman, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Rumah Sakit Mata Dr. Yap atau Museum Dr. Yap Prawirohusodo merupakan museum yang didirikan untuk mengenang pendiri Rumah Sakit Mata Dr.', -7.7807154, 110.3750467, NULL, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rumah%20Sakit%20Mata%20Dr.%20Yap%201.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97374410', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9858, NULL, 4, 'Museum Pedir', 'Bandar Baru', 'Blang Glong, Pidie Jaya, Aceh', 'Pedir Museum atau Museum Manuskrip Lueng Putu adalah sebuah museum yang terletak di Blang Glong, Pidie Jaya dan memiliki cabang di Punge Blang Cut, Banda Aceh . Museum ini didirikan oleh Masykur Syarifuddin pada tanggal 6 Juni 2015. Museum ini mengkoleksi berbagai benda-benda kuno peninggalan peradaban di Aceh seperti manuskrip, mata uang, senjata, keramik dan berbagai artefak lainnya.', 5.2582674, 96.0716335, 10000, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pedir%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97374869', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9859, NULL, 4, 'Indonesian Islamic Art Museum', 'Lamongan', 'Jalan Raya Daendels, Tunggul, Lamongan, Jawa Timur', 'Indonesian Islamic Art Museum atau Museum Islam adalah museum sejarah Islam Indonesia dan dunia yang berlokasi di Jl. Raya Paciran, Lamongan, Jawa Timur. Museum ini dibuka pada 28 Desember 2016.', -6.866825, 112.361589, 20000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Indonesian%20Islamic%20Art%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q99439928', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9860, NULL, 4, 'History of Java Museum', 'Bantul', 'Jalan Parangtritis, Sewon, Daerah Istimewa Yogyakarta', 'History of Java Museum (dalam bahasa Indonesia: Museum Sejarah Jawa) beroperasi pada akhir Desember 2018. History of Java Museum merupakan ikon wisata sejarah dan budaya berlokasi di Jalan Parangtritis KM 5.5, Kecamatan Sewon, Kabupaten Bantul, DIY.\nHistory of Java Museum menceritakan tentang Peradaban Tanah Jawa dan dibangun dengan design gedung yang unik, sangat inspiratif, dan penuh nilai filosofis.\nDesign bangunan History of Java Museum menggambarkan simbol gunungan dalam cerita pewayangan.', -7.8438889, 110.36225, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/History%20of%20Java%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q99450344', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9861, NULL, 4, 'Monumen Pancasila Sakti', 'Jakarta Timur', 'Jalan Langgar II, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Monumen Pancasila Sakti dibangun atas gagasan Presiden ke-2 Indonesia, Soeharto. Monumen ini merupakan museum khusus yang berada di bawah kepemilikan TNI dan dikelola oleh Pusat Sejarah TNI. Monumen ini dibangun di atas tanah seluas 14,6 hektar dengan tujuan untuk mengingat perjuangan para Pahlawan Revolusi yang berjuang mempertahankan ideologi negara Republik Indonesia, Pancasila dari ancaman ideologi komunis.\nKetujuh pahlawan revolusi tersebut adalah:\n\nPanglima Angkatan Darat Letnan Jenderal TNI (Jenderal TNI (Anumerta)) Ahmad Yani,\nMayor Jenderal TNI (Letnan Jenderal TNI (Anumerta)) R. Suprapto\nMayor Jenderal TNI (Letnan Jenderal TNI (Anumerta)) M.T. Haryono\nMayor Jenderal TNI (Letnan Jenderal TNI (Anumerta)) Siswondo Parman\nBrigadir Jenderal TNI (Mayor Jenderal TNI (Anumerta)) DI Panjaitan\nBrigadir Jenderal TNI (Mayor Jenderal TNI (Anumerta)) Sutoyo Siswomiharjo\nLetnan Satu (Kapten CZI (Anumerta)) Pierre Tendean, Ajudan Jenderal TNI A.H. Nasution\nSelain ketujuh pahlawan revolusi tersebut terdapat 2 pahlawan revolusi lainnya:\n\nBrigadir Jenderal TNI Anumerta Katamso Darmokusumo\nKolonel Infanteri Sugiyono Mangunwiyoto\nKedua pahlawan revolusi tersebut diperingati di Monumen Pahlawan Pancasila Yogyakarta.', -6.29027, 106.90816, 2500, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumen%20Pancasila%20Sakti.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q106278628', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9862, NULL, 4, 'Museum Daerah Kabupaten Maros', 'Sulawesi Selatan', 'Jalan H.M. Kasim, Raya, Maros, Sulawesi Selatan', 'Museum Daerah Kabupaten Maros (Lontara Indonesia: ᨆᨘᨔᨙᨕᨘ ᨉᨕᨙᨑ ᨀᨅᨘᨄᨈᨙ ᨆᨑᨚ , transliterasi: Museum Daerah Kabupaten Maros ; Lontara Bugis: ᨆᨘᨔᨙᨕᨘ ᨉᨕᨙᨑ ᨀᨅᨘᨄᨈᨙ ᨆᨑᨘ , transliterasi: Muséung Daéra Kabupaténg Maru\' ; Lontara Makassar : ᨆᨘᨔᨙᨕᨘ ᨉᨕᨙᨑ ᨀᨅᨘᨄᨈᨙ ᨆᨑᨘᨔᨘ , transliterasi: Muséung Daéra Kabupaténg Marusu\' ) adalah sebuah museum eks bangunan masa kolonial Hindia Belanda yang terletak di Jalan Ahmad Yani No. 01, Kelurahan Turikale, Kecamatan Turikale, Kabupaten Maros, Provinsi Sulawesi Selatan, Indonesia. Lebih tepatnya museum ini berhadapan dengan markas Polres Maros.', -5.00613, 119.57469, 0, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Daerah%20Kabupaten%20Maros%2004.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q106279483', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9863, NULL, 4, 'Museum Nene Mallomo', 'Sidenreng Rappang', 'Jalan Usman Isa, Pangkajene, Sulawesi Selatan', 'Museum Nene Mallomo merupakan museum daerah yang terdapat di Jl. Wolter Monginsidi No. 17, Kabupaten Sidenreng Rappang, Provinsi Sulawesi Selatan, Indonesia dan diresmikan pada 4 Oktober 2018 yang berdasarkan SK Pendirian Bupati H.Dollah Mando.', -3.9278754, 119.8010015, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Daerah%20Nene%20Mallomo%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q121139921', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9864, NULL, 4, 'Museum Kayuh Baimbai', 'Kalimantan Selatan', 'Banjarmasin Selatan, Banjarmasin, Kalimantan Selatan', 'Museum Kayuh Baimbai adalah sebuah museum yang terletak di Kota Banjarmasin. Pembangunan Museum Kayu Baimbai pada tahun 2022. Museum Kayuh Baimbai diresmikan pada 8 Maret 2023.', -3.3287591, 114.5928537, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kota%20Banjarmasin.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q123113785', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9865, NULL, 4, 'Museum Indo’ Ta’dung', 'Toraja Utara', 'Jalan Poros Tedong Bonga - Buntao - Batas Kab. Luwu, Karassik, Toraja Utara, Sulawesi Selatan', 'Museum Indo’ Ta’dung adalah museum khusus yang dirintis sejak tahun 1964 dan berada di dalam Kompleks wisata Kete Kesu, Pantanakan Lolo, Kecamatan Kesu’, Kabupaten Toraja Utara, Sulawesi Selatan.\nNama museum dipilih dari seorang yang dihormati, pedagang dan kolektor barang antik, Indo’ Ta’dung yang meninggal tanpa anak sehingga keluarga Ne’ Duma memutuskan membangun museum untuk menyimpan koleksi beliau. Saat ini museum dimiliki oleh Keluarga besar Indo’ Ta’dung dan Sarungallo dan dikelola oleh ahli waris Indo’ Ta’dung.', -2.995095, 119.91069, 0, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Indo%20Tadung%20Toraja%20Utara%2003.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q126181398', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9866, NULL, 4, 'Museum Kota Samarinda', 'Samarinda', 'Jalan Taman Samarendah, Samarinda Kota, Samarinda, Kalimantan Timur', 'Museum Kota Samarinda atau dikenal juga dengan Museum Samarendah adalah museum yang berlokasi di Jalan Bhayangkara, kelurahan Bugis, Kecamatan Samarinda Kota, Kota Samarinda, Kalimantan Timur. \nMuseum ini merupakan museum pertama di Kota Samarinda dan saat ini, museum dikelola oleh Dinas Pendidikan dan Kebudayaan Kota Samarinda.', -0.496046, 117.1445787, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Samarinda.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q126190922', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9867, NULL, 4, 'Museum Pusat TNI Angkatan Laut Jalesveva Jayamahe', 'Jawa Timur', 'Jalan Raya Hang Tuah, Ujung, Surabaya, Jawa Timur', 'Museum Pusat TNI Angkatan Laut (AL) Jalesveva Jayamahe Surabaya adalah museum militer yang berlokasi di Jalan Raya Hang Tuah No.1 Surabaya, Jawa Timur. Museum ini resmi dibuka untuk masyarakat umum pada 20 Januari 2024. Museum ini berisi koleksi senjata dan alat perang armada TNI Angkatan Laut Indonesia.', -7.2216103, 112.7401828, 0, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Replika%20KRI%20REM-331%20Muspusal.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q127104044', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9868, NULL, 4, 'Museum Batik Indonesia', 'Jakarta Timur', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Batik Indonesia adalah salah satu museum di Taman Mini Indonesia Indah, Kota Jakarta Timur, Provinsi Daerah Khusus Ibukota Jakarta, Indonesia. Gagasan pendirian Museum Batik Indonesia disampaikan oleh Yayasan Batik Indonesia pada tahun 2014 dan ditindaklanjuti dengan pengadaan sayembara desain arsitektur pada tahun 2015. Museum Batik Indonesia mulai dibangun pada tahun 2016 dan diselesaikan pembangunannya pada tahun 2019.', -6.3053972, 106.8957076, 0, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20batik%20indonesia.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q127110413', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9869, NULL, 4, 'Museum Pagatan', 'Kalimantan Selatan', 'Jalan 7 Februari, Kota Pagatan, Tanah Bumbu, Kalimantan Selatan', 'Museum Pagatan atau Museum Tanah Bumbu adalah sebuah museum yang berlokasi di Kabupaten Tanah Bumbu, Provinsi Kalimantan Selatan. Museum ini diresmikan penggunaannya oleh bupati Tanah Bumbu saat itu, Zairullah Azhar, pada 16 Februari 2022. Museum ini direncanakan akan memajang benda-benda bersejarah yang masih tersebar di beberapa tokoh di Tanah Bumbu.', -3.6084987, 115.933551, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pagatan.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q133847825', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9870, NULL, 4, 'Museum Ganesya', 'Jawa Timur', 'Banjararum, Kabupaten Malang, Jawa Timur', 'Museum Ganesya adalah sebuah museum yang ada di bawah nauangan Hawai Group Malang. Museum ini dikenal juga sebagai museum Gelar Indonesia Budaya. Museum ini berlokasi di Jl.', -7.9230713, 112.6570818, 30, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tanda%20Peresmian%20Museum%20Ganesya%20%28Gelar%20Indonesia%20Budaya%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q133968437', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9871, NULL, 4, 'Museum Colliq Pujie', 'Barru', 'Jalan Sultan Hasanuddin, Barru, Sulawesi Selatan', 'Museum Colliq Pujie adalah museum yang berlokasi di Kabupaten Barru, Sulawesi Selatan. Lokasi tepatnya berada di Alun-Alun Colliq Pujie di Kota Barru. Penamaan Colliq Pujie ini berasal dari tokoh sejarah yang menjadi ikon Kota Barru.', -4.4141431, 119.6195151, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Colliq%20Pujie%20Barru%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136328239', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9872, NULL, 4, 'Museum Rumah Kelahiran Ilyas Jacob', 'Puluik-Puluik Selatan', 'Jalur Bayang - Alahan Panjang (Alpa), Puluik-Puluik Selatan, Pesisir Selatan, Sumatera Barat', 'Museum Rumah Kelahiran Ilyas Jacob: Museum di Pesisir Selatan, Puluik-Puluik Selatan.', -1.2034323, 100.5755294, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rumah%20Kelahiran%20Ilyas%20Jacob%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136358285', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9873, NULL, 4, 'Museum dan Galeri Arsip Statis Kota Padang', 'Sumatera Barat', 'kampungjawa, Padang, Sumatera Barat', 'Museum dan Galeri Arsip Statis Kota Padang adalah museum yang menyimpan dokumen dan arsip penting yang merekam perjalanan panjang Kota Padang dari masa kolonialisme hingga era kemerdekaan. Museum ini berlokasi di Lantai II Gedung Balai Kota Padang lama, Jalan M. Yamin no. 70, Kampung Jao, Kecamatan Padang Barat, Sumatera Barat.', -0.9478655, 100.3597983, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Staatsblad%20di%20Kota%20Padang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136391015', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9874, NULL, 4, 'Rumah Budaya Banda Neira', 'Banda', 'Jalan Geraja Tua, Bandanaira, Maluku Tengah, Maluku', 'Rumah Budaya Banda Neira: Bangunan di Banda Neira, Banda.', -4.5256704, 129.8973885, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Budaya%20Banda%202026%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q140528516', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9875, NULL, 4, 'Museum Keris Nusantara', 'Jawa Tengah', 'Jalan Bhayangkara, Sriwedari, Surakarta, Jawa Tengah', 'Museum Keris Nusantara merupakan sebuah museum yang dibangun oleh Direktorat Jenderal Kebudayaan, Kementerian Pendidikan dan Kebudayaan melalui Direktorat Pelestarian Cagar Budaya dan Permuseuman sejak 2013 lalu diresmikan oleh Presiden Republik Indonesia, Joko Widodo pada tanggal 9 Agustus 2017. Museum Keris berada di Jl. Bhayangkara No.2 tepatnya di lokasi eks gedung Rumah Sakit Jiwa Mangunjayan, dan direncanakan akan menyatu dengan ruang terbuka hijau (RTH) di kawasan Stadion R Maladi Sriwedari.', -7.56881, 110.81085, 7500, ' 09.00–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museumkerisnusantara%202.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q61356674', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9876, NULL, 4, 'Museum Perkebunan Indonesia', 'Medan', 'Jalan Brigjen Katamso, Medan Maimun, Kota Medan, Sumatera Utara', 'Museum Perkebunan Indonesia adalah sebuah museum yang didirikan sebagai pusat informasi dan pendidikan tentang perkebunan yang ada di Indonesia. Museum ini berlokasi di Jalan Brigjen Katamso No. 53 Kota Medan, Sumatera Utara.', 3.5561111, 98.6888611, NULL, ' 08.30–16.00; Sen 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Koleksi%20Museum%20Perkebunan%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q61364111', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9877, NULL, 4, 'Museum Rumah Adat Baanjuang', 'Bukittinggi', 'Jalan Minangkabau, Kampuang Cino, Bukittinggi, Sumatera Barat', 'Museum Rumah Adat Baanjuang adalah museum umum yang didirikan oleh seorang berkebangsaan Belanda bernama Modelar Countrolleur pada tanggal 1 Juli 1935. Bangunan museum berbentuk rumah gadang dan di halamannya terdapat rangkiang, lumbung padi khas Minangkabau. Sebagian besar bangunan masih terbuat dari bahan bangunan tradisional.', -0.3006667, 100.3695556, 10000, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rumah%20Baanjuang%20Bukittinggi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q71531197', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9878, NULL, 4, 'Rumah Puisi Taufiq Ismail', 'Padang Panjang', 'Jalan Padang Panjang - Bukittinggi, Koto Baru, Tanah Datar, Sumatera Barat', 'Rumah Puisi Taufiq Ismail adalah sebuah rumah baca yang menyimpan ribuan buku karya sastrawan legendaris Indonesia, Taufiq Ismail. Rumah ini adalah warisan kesenian yang ditinggalkan oleh Taufiq Ismail yang dibangun pada 19 Desember 2008 di Jalan Raya Padang Panjang - Bukittinggi Km. 6, Aie Angek, Kecamatan X Koto, Kabupaten Tanah Datar, Provinsi Sumatera Barat.', -0.4132778, 100.4062778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Puisi%20Taufiq%20Ismail.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q71554944', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9879, NULL, 4, 'Monumen Puputan Klungkung', 'Semarapura', '6, Semarapura Kangin, Klungkung, Bali', 'Monumen Puputan Klungkung adalah museum di Semarapura.', -8.53487, 115.40346, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID-bali-klungkung-monument.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q121218344', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9880, NULL, 4, 'Museum Cokelat Monggo', 'Indonesia', 'Jalan Tugu Gentong, Kasihan, Daerah Istimewa Yogyakarta', 'Museum Cokelat Monggo, dikenal juga sebagai Museum dan Pabrik Cokelat Monggo, merupakan museum khusus yang berfokus pada koleksi dan edukasi yang berkaitan dengan cokelat. Museum ini terletak di Jl. Tugu Gentong, Sribitan, Bangunjiwo, Kasihan, Bantul, Daerah Istimewa Yogyakarta.', -7.8406901, 110.2978182, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20%26%20Pabrik%20Cokelat%20Monggo%20%282%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136500171', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 2),
  (9881, NULL, 4, 'Rumah Fatmawati', 'Ratu Samban', 'Jalan Fatmawati, Penurunan, Bengkulu, Bengkulu', 'Rumah Fatmawati adalah salah satu tempat bersejarah yang berada di Bengkulu, tepatnya berada di Jalan Fatmawati, Kelurahan Penurunan, Kecamatan Ratu Samban. Rumah Fatmawati atau tempat kediaman Fatmawati istri ke-3 Soekarno ini ditetapkan Pemerintah Daerah Bengkulu menjadi aset sejarah. Rumah tersebut dilengkapi berbagai ornamen asli, rumah itu berukuran 92 meter persegi dan dibangun ulang sesuai konstruksi aslinya, yaitu berbentuk panggung dan terbuat dari kayu.', -3.7950177, 102.2650477, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Fatmawati.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108934500', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9882, NULL, 4, 'Museum Sriwijaya', 'Sumatera Selatan', 'Jalan Kadir TKR, Gandus, Palembang, Sumatera Selatan', 'Museum Sriwijaya adalah museum umum yang didirikan sebagai pusat informasi mengenai peninggalan-peninggalan serta peradaban dari Kerajaan Sriwijaya. Jenis koleksi yang dipamerkan terdiri dari benda-benda arkeologi, keramologi, dan numismatika. Koleksi yang umum dipamerkan meliputi beragama arca, stupa, hingga kapal yang berukuran 8,2 meter.', -2.99026, 104.7611, 2000, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Taman%20Purbakala%20Kerajaan%20Sriwijaya%20-%20Museum%20Sriwijaya.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940615', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9883, NULL, 4, 'Museum Situs Lubang Tambang Mbah Soero', 'Lembah Segar', 'Saringan, Sawahlunto, Sumatera Barat', 'Museum Situs Lubang Tambang Mbah Soero adalah museum khusus yang terdiri dari Galeri Kotak Info dan Lubang Tambang Mbah Soero yang terletak di Jl. Muhammad Yazid,Tangsi Bau, kelurahan Tanah Lapang, Lembah Segar, Kota Sawahlunto, Sumatera Barat, Indonesia. Museum ini merupakan bekas tempat penumpukan batu bara yang digali dari Lubang Tambang Mbah Soero.', -0.6786816, 100.7791308, 10000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lubang%20Tambang%20Mbah%20Soero%20by%20Mugikun.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12495371', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9884, NULL, 4, 'Museum Keraton Surakarta', 'Surakarta', 'Jalan Mloyokusuman, Baluwarti, Surakarta, Jawa Tengah', 'Museum Keraton Surakarta Hadiningrat atau Museum Keraton Solo adalah museum khusus yang mengoleksi benda-benda budaya peninggalan Karaton Kasunanan Surakarta Hadiningrat. Museum Keraton terbagi menjadi dua bangunan utama di bagian barat dan timur. Kedua bangunan memiliki ruangan-ruangan yang memuat hasil kriya Karaton Surakarta.', -7.5779003, 110.8267612, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Kasunanan%20Surakarta%20Hadiningrat.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499643', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9885, NULL, 4, 'Museum Masjid Agung Demak', 'Demak', 'Jalan Kyai Singkil, Sorogenen, Demak, Jawa Tengah', 'Museum Masjid Agung Demak adalah sebuah museum yang terletak di Jl. Sultan Patah No. 57  dalam kompleks Masjid Agung Demak dalam lingkungan alun-alun kota Demak.', -6.89424, 110.63774, 0, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Demak.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499650', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9886, NULL, 4, 'Museum Penerangan', 'Daerah Khusus Ibukota Jakarta', 'Jalan Taman Mini, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Penerangan adalah museum khusus yang terletak di kompleks Taman Mini Indonesia Indah (TMII), dan dikelola oleh Kementerian Komunikasi dan Digital RI. Didirikan atas prakarsa Tien Soeharto dan diresmikan oleh Presiden Soeharto pada 20 April 1993, museum ini didirikan dengan tujuan untuk mengenang jasa-jasa para petugas penerangan dari era pra kemerdekaan hingga kini.\nBangunan museum ini berbentuk bintang bersudut lima yang menggambarkan Pancasila dan lima unsur media penerangan. Di muka museum terdapat Tugu Api Tak Kunjung Padam, lambang kementerian terdahulu Departemen Penerangan RI yang melambangkan semangat petugas penerangan.', -6.299318, 106.8934026, NULL, 'Sab–Kam 09.00–16.00, Jum 09.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Penerangan%20TMII%20-%20panoramio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499658', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9887, NULL, 4, 'Museum Olahraga Nasional', 'Indonesia', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Olahraga adalah bekas museum yang berisi tentang segala macam olahraga yang berada di kawasan Taman Mini Indonesia Indah (TMII), Jakarta Timur. Museum ini dulu dikenal karena bentuk bangunannya yang sangat unik, yakni berbentuk bola sepak menghadap ke arah Teater Keong Emas. Pernah berdiri di atas tanah 1,5 hektare dengan luas bangunan 3.000 m², museum ini bertujuan memberikan pemahaman masyarakat mengenai pentingnya olahraga bagi kesehatan jasmani dan rohani.', -6.3042879, 106.8890364, 5000, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Olahraga%20TMII%20-%20panoramio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499657', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9888, NULL, 4, 'Museum Sulawesi Tengah', 'Sulawesi Tengah', 'Jalan Kemiri, Balaroa, Kecamatan Ulujadi, Sulawesi Tengah', 'Museum Sulawesi Tengah terletak di Jalan Kemiri No. 23, Kelurahan Kamonji, Kecamatan Palu Barat, Kota Palu, Provinsi Sulawesi Tengah, Indonesia. Museum Sulawesi Tengah dibangun di atas tanah seluas 18.330 m2.', -0.90241, 119.85387, 3000, ' 07.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Barkcloth%20dress%20of%20Lore%20Bada%2C%20Central%20Sulawesi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499670', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9889, NULL, 4, 'Museum Satwa', 'Jawa Timur', 'Jalan Raya Oro-Oro Ombo, Lowokwaru, Kota Batu, Jawa Timur', 'Museum Satwa adalah sebuah museum yang terletak di Kota Batu, Jawa Timur. Keberadaan Museum Satwa menjadi salah satu ikon pariwisata Jawa Timur yang terletak di bagian barat Kota Batu dan termasuk dalam kawasan Jatim Park 2. Museum Satwa menampilkan tiruan dari satwa-satwa dan fosil-fosil dinosaurus.', -7.8887337, 112.5295573, 84000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Satwa%20Jatim%20Park%202%202017-09-18.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12499668', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9890, NULL, 4, 'Rumah Budaya Fadli Zon', 'Tanah Datar', NULL, 'Rumah Budaya Fadli Zon adalah sebuah ruang kebudayaan, tempat dialog dan bertutur rasa beragam budaya Nusantara.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Budaya%20Fadli%20Zon.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q12509032', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9891, NULL, 4, 'Museum Diponegoro', 'Yogyakarta', 'Jalan Diponegoro, Kauman, Kota Magelang, Jawa Tengah', 'Museum Diponegoro: Museum di Indonesia, Yogyakarta.', -7.4748434, 110.2149716, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gate%20of%20Monumen%20Pangeran%20Diponegoro%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q13095246', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9892, NULL, 4, 'Museum Karst Indonesia', 'Jawa Tengah', '242, Pracimantoro, Jawa Tengah', 'Museum Karst adalah museum yang berisi koleksi informasi dan contoh batuan kapur (Karst), terletak di Desa Gebangharjo, Kecamatan Pracimantoro, Wonogiri. Museum tersebut merupakan museum karst terbesar dan terunik di Indonesia, bahkan di Asia Tenggara.\nMuseum Karst menjadi tempat wisata edukasi dan rekreasi.', -8.0412, 110.78318, 0, ' 08.30–15.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Karst%20-%20panoramio%20%281%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19729523', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9893, NULL, 4, 'Museum di Tengah Kebun', 'Jakarta', 'Jalan Kemang Timur XIII, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Museum di Tengah Kebun adalah sebuah museum penyimpanan ± 4.000 koleksi seni dan sejarah Indonesia dan luar negeri yang berlokasi di Jl. Kemang Timur 66, Kec. Mampang Prapatan, Jakarta Selatan.', -6.2963281, 106.7950309, 0, ' 09.30–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20kebun%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19746455', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9894, NULL, 4, 'Museum Telekomunikasi', 'Jakarta', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Telekomunikasi (disingkat Mustel) adalah bekas museum tentang telekomunikasi di Indonesia yang terletak di kawasan Taman Mini Indonesia Indah (TMII), Jakarta Timur. Museum ini dibongkar pada tahun 2022, dan letaknya dahulu berdampingan dengan Museum Olahraga (juga dibongkar di tahun yang sama) dan Museum Bayt al-Quran di dekat pintu utama.\nCiri khas museum ini adalah atap kubah warna biru dengan keberadaan di depannya sebuah Monumen Sumpah Palapa Maha Patih Gajah Mada yang berdiri tegak sambil mengacungkan keris.', -6.3027767, 106.8906528, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Patih%20Gajah%20Mada.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19746492', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9895, NULL, 4, 'Museum Timor Timur', 'Jakarta', 'Jalan Bambu Kuning Utara, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Timor Timur adalah bagian dari Taman Mini Indonesia Indah, terletak di sebelah utara Istana Anak-Anak Indonesia, menghadap ke selatan arah Museum Prangko Indonesia. Semula Museum Timor Timur adalah Anjungan Daerah Timor-Timur yang dibangun tahun 1979 dan diresmikan 20 April 1980 oleh Presiden Soeharto.\nSetelah Provinsi Timor Timur berpisah dengan Indonesia dan membentuk negara sendiri, Anjungan Daerah Timor-Timur dikelola oleh pengelola Taman Mini Indonesia Indah sebagai sebuah monumen.', -6.3032587, 106.9014576, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20of%20East%20Timor.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q19752254', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9896, NULL, 4, 'Museum House of Sampoerna', 'Surabaya', 'Jalan Dapuan I, Pabean Cantian, Surabaya, Jawa Timur', 'Museum House of Sampoerna: Museum di Indonesia, Surabaya.', -7.2305831, 112.7349961, 0, ' 09.00–19.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/House%20of%20Sampoerna%20Mei%202015.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q25581169', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9897, NULL, 4, 'Museum Maritim Indonesia', 'Jakarta', 'Jalan Pelabuhan Raya, Tanjung Priok, Jakarta Utara', 'Museum Maritim Indonesia adalah museum yang terletak di Jl. Pasoso No. 1, Pelabuhan Tanjung Priok, Jakarta Utara, DKI Jakarta, Indonesia.', -6.1075275, 106.8833969, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Maritim%20Indonesia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q56391591', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9898, NULL, 4, 'Museum Istana Kepresidenan Yogyakarta', 'Yogyakarta', 'Jalan Reksobayan, Gondomanan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Museum Istana Kepresidenan Yogyakarta adalah sebuah museum yang terletak di Jalan Ahmad Yani, Ngupasan, Gondomanan, Kota Yogyakarta. Museum ini berada di ujung selatan kawasan pariwisata terkenal Malioboro dan di seberang Museum Benteng Vredeburg. Penduduk lokal menyebut museum ini dengan nama Gedung Agung.', -7.800094, 110.36395, NULL, ' 08.30–15.00;  13.00–15.00;  08.30–12.00;  13.00–12.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Agung.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q56391615', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9899, NULL, 4, 'Studio Pemugaran Manjusrigrha', 'Indonesia', 'Bokoharjo, Sleman, Daerah Istimewa Yogyakarta', 'Studio Pemugaran Manjusrigrha (kadang juga disebut Museum Pemugaran Candi Sewu) adalah sebuah bangunan di dalam kompleks Candi Sewu yang digunakan untuk memperkenalkan sejarah proses pemugaran Candi Sewu. Studio ini memiliki ruang audio-visual yang dapat digunakan pengunjung untuk menonton film dokumenter terkait pemugaran Candi Sewu. Museum berada di sebelah utara Candi Sewu.', -7.7426989, 110.4929348, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Studio%20Pemugaran%20Manjusrighra.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109563873', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9900, NULL, 4, 'Museum Anatomi Tubuh', 'Indonesia', 'Lowokwaru, Kota Batu, Jawa Timur', 'The Bagong Adventure Museum Tubuh adalah sebuah museum yang beralamat di Jalan Kartika Nomor 2, Kompleks Jatim Park I, Kota Batu, Jawa Timur, Indonesia. Fungsi khusus museum ini sebagai museum tematik yang memberikan penjelasan tentang anatomi manusia. Letak museum ini di dalam Jatim Park Group dan berfungsi sebagai salah satu wahana.', -7.8834202, 112.5250371, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20tubuh%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q121138541', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9901, NULL, 4, 'Rumah Perundingan PDRI di Padang Japang', 'Lima Puluh Kota', 'VII Koto Talago, Lima Puluh Kota, Sumatera Barat', 'Rumah Perundingan PDRI di Padang Japang: Rumah Perundingan PDRI di Padang Japang yang sekarang sudah menjadi Museum di Nagari VII Koto Talago, Kecamatan Guguak, Kabupaten Lima Puluh Kota, Sumatera Barat., Lima Puluh Kota.', -0.1123305, 100.5365515, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Perundingan%20PDRI%20Padang%20Japang%202023%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q124251826', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9902, NULL, 4, 'Museum Kota Juang Bireuen', 'Bireuen', 'Baro, Bireuen, Aceh', 'Museum Kota Juang Bireuen adalah museum yang terletak di jalan di Gampong Baro, Kota Juang,  Bireuen. Museum ini menampilkan koleksi  sejarah para tokoh Bireuen, Aceh dan Indonesia serta sejarah saat Soekarno menetap di wilayah ini.', 5.2080784, 96.6993855, 15000, ' 09.00:00–12.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kota%20Juang%20Bireuen%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q126126047', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9903, NULL, 4, 'Museum Song Terus', 'Pacitan', 'Wareng, Pacitan, Jawa Timur', 'Museum Song Terus adalah sebuah museum prasejarah yang terletak di Dusun Weru, Desa Wareng, Kecamatan Punung, Kabupaten Pacitan, Jawa Timur. Lokasi Museum Song Terus terletak di Kawasan Cagar Budaya Gunung Sewu. Posisinya berseberangan dengan Situs Song Terus di sisi timur lautnya.', -8.1251389, 110.9880833, 15000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20song%20terus.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q126167518', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9904, NULL, 4, 'Museum Khazanah Melayu Haji Subhan Nur', 'Sambas', 'Lorong, Sambas, Kalimantan Barat', 'Museum Khazanah Melayu Haji Subhan Nur: Museum di Sambas, Kalimantan Barat, Sambas.', 1.3653824, 109.2933001, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Khazahah%20Melayu%20Haji%20Subhan%20Nur.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q127327272', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9905, NULL, 4, 'Kampung Budaya Ngabang', 'Kalimantan Barat', 'Amboyo Inti, Ngabang, Kalimantan Barat', 'Kampung Budaya Ngabang: Kampung Budaya di Ngabang, Kabupaten Landak, Kalimantan Barat, Kalimantan Barat.', 0.3848622, 109.9314856, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kampung%20Budaya%20Ngabang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q130335920', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9906, NULL, 4, 'Museum Poesaka Ningrat Kesultanan Sintang', 'Sintang', 'Pangeran Kuning, Sintang, Kalimantan Barat', 'Museum Poesaka Ningrat Kesultanan Sintang: Museum di Sintang Kalimantan Barat, Sintang.', 0.0832929, 111.491808, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Al%20Mukarramah%20Kesultanan%20Sintang%2004.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q131324002', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9907, NULL, 4, 'Museum Jenderal M Jusuf', 'Makassar', 'Jalan Rajawali, Mariso, Makassar, Sulawesi Selatan', 'Museum Jenderal M. Jusuf adalah museum yang berada di Makassar, Sulawesi Selatan. Museum ini diresmikan pada 17 Agustus 2022 oleh Pangdam XIV/ Hasanuddin Mayjen TNI Andi Muhammad Bau Sawa Mappanyukki. Museum ini didirikan dengan tujuan untuk mengenang dan mengabadikan riwayat hidup Jenderal M Jusuf, mulai dari masa kecil hingga berkarier di dunia militer.', -5.1503267, 119.4099667, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Jendral%20M.%20Jusuf.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q131757594', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9908, NULL, 4, 'Museum Fansuri', 'Sumatera Utara', 'Jago Jago, Kecamatan Badiri', 'Museum Fansuri Situs Bongal merupakan museum yang terletak di desa Jago-Jago, Kecamatan Badiri, Kabupaten Tapanuli Tengah, Provinsi Sumatera Utara. Koleksi museum ini berasal dari situs Bongal.', 1.605163, 98.823496, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Foto%20Museum%20Fansuri%20Situs%20Bongal.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q132214035', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9909, NULL, 4, 'Museum Sanggar Apapuhang', 'Tabukan Utara', 'Tola, Kepulauan Sangihe, Sulawesi Utara', 'Museum Sanggar Apapuhang adalah sebuah museum yang terletak di Desa Lenganeng, Tabukan Utara, Kabupaten Kepulauan Sangihe, Sulawesi Utara. Museum ini sebelumnya berfungsi sebagai sanggar seni dan budaya lalu bertransformasi menjadi museum untuk menyimpan dan melestarikan warisan budaya suku Sangihe.\nDidirikan pertama kali pada tahun 2010 dan diresmikan kembali pada Desember 2022, museum ini menyimpan koleksi duplikat benda budaya Sangihe yang kaya, serta menjadi pusat edukasi dan apresiasi terhadap sejarah dan tradisi lokal.', 3.6388553, 125.5133797, NULL, ' 00.01–23.59; Min 09.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ansambel%20Musik%20Lide%20dari%20kepulauan%20Sangihe%203.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136304771', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9910, NULL, 4, 'Museum Mini Kerajaan Siguntur', 'Siguntur', 'Suikabau, Dharmasraya, Sumatera Barat', 'Museum Mini Kerajaan Siguntur: Museum di Dharmasraya, Siguntur.', -0.9543367, 101.5671245, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Mini%20Kerajaan%20Siguntur%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136358257', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9911, NULL, 4, 'Museum Pranidha Ranajaya Ghanavara', 'Indonesia', 'Jalan Letnan Jenderal MT Haryono, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Pranidha Ranajaya Ghanavara merupakan museum anti narkotika pertama di Indonesia. Pranidha Ranajaya Ghanavara memiliki arti yaitu tempat yang mewakili wajah BNN atas kemenangan-kemenangan dalam mengentas narkotika. Museum Pranidha Ranajaya Ghanavara berlokasi di Lantai 3 Gedung Pradavi Rajistha Gataroga, BNN RI. Museum tersebut didirikan agar masyarakat dapat belajar mengetahui bahaya dan cara menanggulangi narkoba di Indonesia.', -6.2459712, 106.8710085, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BNN%20LRT%20sisi%20Selatan%20depan%20institusi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q136379341', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9912, NULL, 4, 'Oemah Batik Lasem', 'Karangturi', 'Jalan Pamotan-Lasem, Pancur, Jawa Tengah', 'Oemah Batik Lasem (juga dikenal sebagai Oemah Batik Tiga Negeri atau Rumah Merah Heritage Lasem, Museum Batik Tiga Negeri Lasem) adalah sebuah showroom, museum, dan ruang budaya batik tradisional yang terletak di Lasem, Kabupaten Rembang, Jawa Tengah, Indonesia. Tempat ini menjadi salah satu pusat penting dalam pelestarian dan promosi batik Lasem, khususnya Batik Tiga Negeri, serta menjadi ruang interaksi antara pengunjung dan warisan budaya batik pesisir Jawa.', -6.7000981, 111.4465381, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Patung%20Orang%20Membatik%20di%20Oemah%20Batik%20Lasem.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q142162772', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9913, NULL, 4, 'Yayasan Amai Setia', 'Koto Gadang', 'Jalan Mr. Mohammad Nazif, Koto Gadang, Agam, Sumatera Barat', 'Yayasan Amai Setia merupakan yayasan yang mengelola kerajinan di Koto Gadang, Kecamatan IV Koto, Agam, Sumatera Barat. Yayasan ini didirikan oleh Roehana Koeddoes bersama dua orang temannya, Rekni Putri dan Hadisah pada 11 Februari 1911 dengan nama Kerajinan Amai Setia.\nPada awalnya, Kerajinan Amai Setia merupakan sekolah keterampilan yang ditujukan untuk perempuan.', -0.3134222, 100.3548835, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kerajinan%20Amai%20Setia.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q61355371', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9914, NULL, 4, 'Museum Kendil Kemilau Emas', 'Kuok', 'Pulau Jambu, Kampar, Riau', 'Museum Kandil Kemilau Emas adalah sebuah museum yang terletak di Desa Wisata Pulau Belimbing, Kecamatan Kuok, Kabupaten Kampar. Museum ini berbentuk rumah Adat Lima Koto Kampar atau yang lebih dikenal dengan sebutan Rumah Lontiok. Museum ini berasal dari beberapa kata yaitu kandil yang berarti lampu, kemilau yang berarti cahaya dan emas yang berarti megah atau indah.', 0.3419383, 100.9577283, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Lontiak%20Kandil%20Kemilau%20Emas%20%285%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203941', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9915, NULL, 4, 'Museum Simettengpola Saoraja Mallangga', 'Sulawesi Selatan', 'Jalan Jenderal Ahmad Yani No.25, Padduppa, Wajo, Sulawesi Selatan', 'Museum Simettengpola Saoraja Mallangga adalah sebuah museum yang berada di Kabupaten Wajo, Sulawesi Selatan, tepatnya di Jl Ahmad Yani No  25 Kelurahan Perdupa, Kecamatan Tempe. Museum ini didirikan pada tahun 1990, yang merupakan inisiatif Pemerintah Kabupaten Wajo atas persetujuan dan kerjasama dengan ahli waris. Museum ini menempati bekas istana atau kediaman Datu Raureng Bettempol Ke-27.', -4.1367671, 120.0332123, 0, ' 08.00–17.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Simettengpola%20Saoraja%20Mallangga%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65203993', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9916, NULL, 4, 'Gedung Joang \'45 Sumatra Barat', 'Belakang Tangsi', 'Jalan Samudra, Berok Nipah, Padang, Sumatera Barat', 'Gedung Joang \'45 Sumatera Barat adalah bangunan cagar budaya yang terletak di Jalan Samudera, Kota Padang, Sumatera Barat, Indonesia. Gedung ini berfungsi sebagai museum dan perpustakaan di bawah pengelolaan Dewan Harian Daerah ’45 Sumatera Barat. Bangunannya didirikan pada 1909, yang pada masa kolonial Belanda berfungsi sebagai Kantor Perwakilan Dagang Jerman.', -0.9579595, 100.3537051, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedung%20Joang%20%2745%20Sumatra%20Barat%2020211108.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q65211729', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9917, NULL, 4, 'Museum RRI Bukittinggi', 'Bukittinggi', 'Jalan Dr. A. Rivai, Tembok, Bukittinggi, Sumatera Barat', 'Museum Radio Republik Indonesia Bukittinggi (Museum RRI Bukittinggi) adalah sebuah museum yang terletak di Jalan Abdul Rivai No. 22, Kayu Kubu, Kota Bukittinggi, Provinsi Sumatera Barat. Bangunan Museum RRI Bukittingi telah didirikan sejak tanggal 14 Januari 1946.', -0.3000556, 100.3665556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Radio%20Republik%20Indonesia%20%28RRI%29%20Bukittinggi%203.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q71534204', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9918, NULL, 4, 'Museum Sultan Sulaiman Badrul Alamsyah', 'Kepulauan Riau', 'Jalan Mawar, Tanjungpinang Kota, Tanjungpinang, Kepulauan Riau', 'Museum Sultan Sulaiman Badrul Alamsyah adalah museum yang terletak di Kota Tanjungpinang, Kepulauan Riau, Indonesia. Museum ini diresmikan pada 31 Januari 2009 oleh Wali Kota Tanjungpinang Suryatati Abdul Manan. Museum ini berada di bawah pengelolaan Dinas Kebudayaan dan Pariwisata Kota Tanjungpinang.', 0.9295441, 104.4439765, NULL, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museumtanjungpinang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q86585018', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9919, NULL, 4, 'Museum Rumah Bolon Adat Pematang Purba', 'Sumatera Utara', 'Simalungun, Sumatera Utara', 'Museum Rumah Bolon Adat Pematang Purba adalah sebuah museum yang juga merupakan Istana Raja Pematang Purba yang didirikan pada masa pemerintahan Tuan Rahalim, raja ke-12 Kerajaan Purba pada tahun 1864. Museum Rumah Bolon Adat Pematang Purba ini berlokasi di Pematang Purba, Kecamatan Simalungun, Kelurahan Pematang Purba, Kabupaten Simalungun, Propinsi Sumatera Utara. Museum ini ditetapkan sebagai objek wisata oleh Bupati Simalungun pada tahun 1961.', 2.9162865, 98.7154382, 500, ' 07.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Bolon%20at%20Pematang%20Purba.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q86587935', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9920, NULL, 4, 'Museum Negeri Provinsi Banten', 'Banten', 'Serang, Banten', 'Museum Negeri Provinsi Banten adalah museum yang terletak di kompleks Masjid Agung Banten, terletak percis di depan Keraton Surosowan, Kecamatan Kasemen Kota Serang. Museum Negeri Banten baru saja pindah sejak September 2023 ke Banten Islamic Center di kawasan Banten Lama. Sebelumnya Museum Negeri berada di Gedung Negara eks Pendopo Gubernur Alun-alun Barat Kota Serang yang didirikan pada 26 Januari 1821.', -6.1157048, 106.1503599, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Negeri%20Banten%202025-07-15.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97195162', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9921, NULL, 4, 'Rumah Budaya Sumba', 'Nusa Tenggara Timur', 'Jalan Kalembu Nga\'a Bangga, Tambolaka, Nusa Tenggara Timur', 'Rumah Budaya Sumba adalah museum khusus yang digunakan untuk memperkenalkan sejarah dan budaya Sumba. Fungsi Rumah Budaya Sumba adalah sebagai museum sekaligus tempat wisata, penelitian, dan pertemuan, serta pusat pembelajaran kebudayaan Sumba. Rumah Budaya Sumba mengoleksi berbagai macam peninggalan kelompok etnik daerah Sumba yang berasal dari masa prasejarah hingga masa kini.', -9.433109, 119.2147737, NULL, ' 00.00–23.59', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumba%2C%20its%20traditional%20house%2C%20and%20its%20people.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97195716', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9922, NULL, 4, 'Museum Kota Langsa', 'Langsa', 'Jalan Raya Medan Banda Aceh, Langsa Kota, Langsa, Aceh', 'Museum Kota Langsa adalah museum umum yang berada di Jl. Ahmad Yani, Kota Langsa, Indonesia. Gedung Museum Kota Langs telah didirikan sejak tahun 1910.', 4.4712327, 97.9675827, 3000, ' 08.30–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Langsa%20Bale%20Juang.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97198850', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (9923, NULL, 4, 'Museum dan Monumen Pendaratan Pesawat Ampibi Catalina', 'Indonesia', 'Jalan Gorontalo 6, Gorontalo, Gorontalo', 'Museum Pendaratan Pesawat Ampfibi Catalina atau yang lebih dikenal dengan sebutan Museum Pendaratan Pesawat Amfibi Soekarno merupakan wisata sejarah yang berada di Desa Iiuta, Kecamatan Batuda\'a, Kabupaten Gorontalo.\nMuseum Pendaratan Pesawat Ampfibi Catalina dapat dikunjungi setiap hari oleh masyarakat umum secara gratis. Selain mempelajari koleksi bersejarah di museum ini, pengunjung juga dapat menikmati panorama Danau Limboto.', 0.5586297, 122.9955929, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pendaratan%20Pesawat%20Amfibi%20di%20Iluta%2C%20Gorontalo.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97222540', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9924, NULL, 4, 'Museum Tosan Aji', 'Purworejo', 'Jalan Mayjen Sutoyo No.10, Purworejo, Jawa Tengah', 'Museum Tosan Aji adalah museum yang didirikan atas prakarsa Menteri Dalam Negeri Soepardjo Rustam dan diresmikan pada 13 April 1987 oleh Gubernur Jawa Tengah, Ismail. Museum ini terletak di Jalan Setiabudi No. 1 Kabupaten Purworejo, Jawa Tengah, tetapi dipindahkan ke Gedung Pengadilan Negeri Kabupaten Purworejo yang terletak di Jalan Mayjend Sutoyo No.', -7.71086, 110.01, 1000, ' 08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Inbound5362715310648609663.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97241097', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9925, NULL, 4, 'Museum Sabang', 'Sabang', 'Jalan Oentoeng Suropati, Sukakarya, Sabang, Aceh', 'Museum Sabang adalah museum khusus yang terletak di Jl. O. Surapati, Kuta Ateuh, Pulau Rondo, Sabang, Provinsi Aceh. Museum ini didirikan pada tahun 2013 atas gagasan dari pimpinan Badan Pengusahaan Kawasan Perdagangan Bebas dan Pelabuhan Bebas Sabang.', 5.8942775, 95.3173158, NULL, ' 08.00–15.30;  08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20De%20baai%20van%20Sabang%20Noord-Sumatra.%20TMnr%2060007529.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97306885', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9926, NULL, 4, 'Museum Penataran', 'Blitar', 'Jalan Insinyur Soekarno, Kedawung, Blitar, Jawa Timur', 'Museum Penataran merupakan museum yang terdapat di Kabupaten Blitar. Museum ini dulunya bernama Museum Blitar berubah nama menjadi "Museum Penataran". Museum ini diresmikan pada tahun 1997 menjadi pusat pendidikan, penelitian, dan pariwisata budaya.', -8.0122108, 112.2080016, 3000, ' 07.30–13.00;  07.30–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Penataran%20Blitar.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97307646', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9927, NULL, 4, 'Museum Memorial Kedaton Sultan Ternate', 'Maluku Utara', 'Makasar Timur, Ternate, Maluku Utara', 'Museum Memorial Kedaton Sultan Ternate merupakan museum yang dibangun oleh Sultan Muhammad Ali pada 24 November 1813. Museum ini dikelola oleh Kementerian Pendidikan dan Kebudayaan Indonesia sejak tahun 1981, tetapi masih digunakan sebagai kediaman keturunan sultan dan bangsawan dari Kesultanan Ternate. Setelah pemugaran pada 1982, museum ini diresmikan oleh  Menteri Pendidikan dan Kebudayaan, Daoed Joesoef.', 0.80054, 127.38405, 0, ' 08.00–14.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Het%20Museum%20Kedaton%20voormalige%20paleis%20van%20de%20sultan%20van%20Ternate%20TMnr%2010016840.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q97307644', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9928, NULL, 4, 'Rumah PDRI Sumpur Kudus', 'Sumpur Kudus', 'Sumpur Kudus Selatan, Sijunjung, Sumatera Barat', 'Rumah PDRI Sumpur Kudus: Rumah di Sumpur Kudus, Sumatra Barat, Indonesia, Sumpur Kudus.', -0.4480907, 100.9073096, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rumah%20Penginapan%20Ketua%20PDRI%20Sumpur%20Kudus%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q106279611', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9929, NULL, 4, 'Museum Keraton Sumenep', 'Sumenep', 'Jalan Dokter Soetomo, Sumenep, Jawa Timur', 'Museum Keraton Sumenep adalah sebuah museum umum yang beralamat di Jalan Dr. Sutomo Nomor 6, Lingkungan Delama, Pajagalan, Kota sumenep, Kabupaten Sumenep, Jawa Timur. Museum Keraton Sumenep pada awalnya merupakan pusat pemerintahan pada masa Gusti Ayu Tirtonegoro R. Rasmana & Kanjeng Tumenggung Ario Tirtonegoro (Bindara Saod) yang dibangun tahun 1750 hingga 1762.', -7.00828, 113.86235, 3000, ' 07.00–16.00;  08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Musium%20sumenep%20-%20panoramio.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940621', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9930, NULL, 4, 'Museum Trinil', 'Ngawi', 'Jalan Raya Ngancar - Sonde, Ngancar, Ngawi', 'Museum Trinil adalah museum khusus yang mengoleksi beragam jenis fosil manusia purba dan hewan purba. Perintisan museum dilakukan oleh Wirodiharjo sejak 1967.\nPendirian Museum Trinil berhasil dicanangkan pada 1980 dan 1981 oleh Pemerintah Provinsi Jawa Timur.', -7.37434, 111.35758, 1000, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Patung%20Gajah%20di%20Museum%20Trinil%2C%20Ngawi.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940625', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9931, NULL, 4, 'Museum Airlangga', 'Mojoroto', 'Jalan Lingkar Maskumambang, Pojok, Kota Kediri, Jawa Timur', 'Museum Airlangga atau sering disebut Museum Erlangga adalah sebuah museum yang terletak di Kota Kediri. Nama tersebut digunakan untuk mengenang jasa serta masa kejayaan Raja Airlangga. Museum Airlangga menyimpan berbagai situs bersejarah yang menggambarkan kehidupan dan peradaban masyarakat Kediri serta wilayah sekitarnya.', -7.80725, 111.97389, 4000, 'Min 08.00–15.00;  09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20airlangga%2001.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940633', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9932, NULL, 4, 'Museum Mandala Pembebasan Irian Barat', 'Sulawesi Selatan', 'Jalan Amanagapa, Ujung Pandang, Makassar, Sulawesi Selatan', 'Museum Monumen Mandala Pembebasan Irian Barat adalah sebuah museum yang terletak di Jalan Jenderal Sudirman Nomor 2, Kelurahan Baru, Kecamatan Ujung Pandang, Kota Makassar, Provinsi Sulawesi Selatan, Indonesia. Status museum ini adalah museum khusus yang mengoleksi diorama, tiruan pakaian dan ruang kerja Komando Mandala.\nMuseum terletak di samping Balai Besar Jenderal M Yusuf dan berhadapan dengan Rumah Sakit Militer Pelamonia.', -5.1374612, 119.4136141, 5000, ' 08.00–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bagian%20Depan%20Bawah%20Monumen%20Mandala.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940636', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9933, NULL, 4, 'Museum Kata Andrea Hirata', 'Kepulauan Bangka Belitung', 'Jalan Negeri 1, Gantung, Kepulauan Bangka Belitung', 'Museum Kata Andrea Hirata adalah museum khusus yang koleksinya menampilkan karya sastra dan lukisan yang dibuat dan dimiliki oleh Andrea Hirata. Peresmian Museum Kata Andrea Hirata diadakan pada bulan November 2012. Museum Kata Andrea Hirata merupakan museum sastra pertama dan satu-satunya di Indonesia.', -2.9674, 108.1641, 50000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Kata%20Andrea%20Hirata.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108940790', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9934, NULL, 4, 'Museum BPK RI', 'Jawa Tengah', 'Jalan Kaliangkrik - Magelang, Magelang, Kota Magelang, Jawa Tengah', 'Museum Badan Pemeriksa Keuangan Republik Indonesia atau Museum BPK RI adalah sebuah museum yang terletak di Jalan Diponegoro Nomor 1, Kota Magelang, Jawa Tengah. Pendirian museum ini khusus untuk menjadi tempat rujukan publik mengenai sejarah pembentukan Badan Pemeriksa Keuangan Republik Indonesia. Lokasi museum tepat berada di titik koordinat 7°28’27.1” LS dan 110°12’51.7” BT. Museum BPK RI dapat dikunjungi melalui beberapa rute yaitu Bandar Udara Adi Sutjipto (49,1 km), Stasiun Tugu (44,7 km), atau Stasiun Lempuyangan (46,5 km).', -7.47429, 110.21413, 0, ' 09.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Badan%20Pemeriksa%20Keuangan%20RI.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q108950505', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9935, NULL, 4, 'Museum Sepakat Segenap', 'Indonesia', 'Gang Sekolah, Percut Sei Tuan, Sumatera Utara', 'Museum Sepakat Segenap adalah sebuah museum yang terletak di Jalan Raya Babussalam, Kotacane, Kecamatan Babussalam, Kabupaten Aceh Tenggara, Provinsi Daerah Istimewa Aceh. Museum ini diselenggarakan oleh Pemerintah Daerah Tingkat II Aceh Tenggara dan dibuka untuk umum tanpa dipungut biaya masuk. Museum ini dibangun seluas 864 meter persegi di atas lahan seluas 5.000 meter persegi dengan mengusung gaya arsitektur tradisional dan dilengkapi dengan berbagai fasilitas pendukung seperti ruang pameran tetap, ruang pameran temporer, auditorium, dan ruang administrasi.', 3.6217585, 98.7821426, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Sepakat%20Segenep.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109279071', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9936, NULL, 4, 'Museum Si Pahit Lidah', 'Sumatera Selatan', 'Ogan Komering Ulu, Sumatera Selatan', 'Museum Si Pahit Lidah adalah sebuah museum arkeologi pertama di Sumatera Selatan. Di dalam museum, terdapat koleksi arkeologi berupa artefak. Artefak ini diperoleh melalui penggalian di sekitar Gua Putri dan Gua Harimau.', -4.0680384, 103.9262064, NULL, ' 08.00–15.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20si%20pahit%20lidah%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109314041', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9937, NULL, 4, 'Museum Rempah-rempah', 'Pulau Ternate', 'Jalan Pahlawan Revolusi, Makassar Timur, Ternate, Maluku Utara', 'Museum Rempah adalah sebuah museum yang dibangun di Jl. Pahlawan Revolusi, kawasan Benteng Orange Ternate, Maluku Utara. Museum ini dikelola sepenuhnya oleh Dinas Kebudayaan dan Pariwisata Kota Ternate.', 0.7943383, 127.3869347, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Rempah%20di%20Fort%20Oranje.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109354933', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9938, NULL, 4, 'Museum Katedral', 'Jakarta', 'Jalan Lapangan Banteng Utara, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Museum Katedral adalah museum khusus yang berada di bagian balkon dalam Gereja Katedral Jakarta. Gagasan pendirian museum dicetuskan oleh pastor bernama Rudolphus Kurris. Pada tahun 1988, Gereja Katedral Jakarta mengalami pemugaran secara menyeluruh dan balkon yang sebelumnya dimanfaatkan untuk paduan suara diubah menjadi museum.', -6.168761, 106.834342, NULL, 'Min 12.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Katedral%20Jakarta%20%282024%29%2001.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109405131', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9939, NULL, 4, 'Museum Graha Widya Patra', 'Jakarta', 'Jalan Laksmana Raya, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Museum Minyak, dan Gas Bumi “Graha Widya Patra” (Gawitra) terletak di bagian timur Taman Mini Indonesia Indah berdekatan dengan Taman Burung, dan Museum Listrik dan Energi Baru. Museum Gawitra dibangun untuk memperingati 100 tahun pengusahaan migas di Indonesia. Museum ini diresmikan 20 April 1989 oleh Presiden RI yang kedua, Soeharto.', -6.3019901, 106.9057158, 15000, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Louisiana%20State%20Oil%20and%20Gas%20Museum%2C%20Oil%20City%2C%20LA%20IMG%205210.JPG?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109405160', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9940, NULL, 4, 'Museum Pusaka Keraton Kasepuhan', 'Jawa Barat', 'Jalan Kasepuhan, Lemahwungkuk, Cirebon, Jawa Barat', 'Museum Pusaka Keraton Kasepuhan adalah sebuah museum yang terletak di Jalan Kasepuhan Nomor 43, Kasepuhan, Lemahwungkuk, Cirebon, Jawa Barat. Fungsi khusus dari museum ini untuk memberikan informasi sejarah dari Keraton Kasepuhan di Cirebon. Koleksinya meliputi benda-benda pusaka peninggalan pemimpin Keraton Kasepuhan sejak masa lalu.', -6.7263285, 108.5688174, NULL, ' 08.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cirebon%20Keraton%20Kasepuhan.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433485', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9941, NULL, 4, 'Museum Gedung Pusaka Keraton Kanoman', 'Jawa Barat', 'Jalan Astana Garibi, Pekalipan, Cirebon, Jawa Barat', 'Museum Gedung Pusaka Keraton Kanoman adalah museum yang terletak di dalam Kompleks Kesultanan Kanoman Cirebon, Jalan Merdeka Nomor 28, Kelurahan Lemahwungkuk, Kota Cirebon, Jawa Barat. Museum Gedung Pusaka Keraton Kanoman adalah museum khusus yang digunakan sebagai tempat penyimpanan pusaka yang dimiliki Keraton Kanoman. Peresmian sekaligus pembukaan museum untuk masyarakat umum diadakan pada tahun 1997 oleh Sultan Kanoman.', -6.7228007, 108.5659239, NULL, ' 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keraton%20Kanoman%20Cirebon.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109433510', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9942, NULL, 4, 'Museum Ciputra Artpreneur', 'Jakarta', 'Jalan Profesor Doktor Satrio, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Museum Ciputra Artpreneur adalah museum khusus yang menyimpan koleksi pribadi dari Ciputra. Gedung museum berada dalam satu kawasan dengan pusat perbelanjaan, perkantoran, dan kawasan seni. Koleksi museum terdiri dari lukisan-lukisan dan sketsa-sketsa karya Hendra Gunawan.', -6.2240134, 106.8233321, 15000, ' 12.00–18.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ciputra%20Artpreneur%20Museum.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109434571', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9943, NULL, 4, 'Puspa IPTEK Sundial', 'Jawa Barat', 'Jalan Layang Kota Baru Parahyangan, Kota Baru Parahyangan, Bandung Barat, Jawa Barat', 'Puspa IPTEK Sundial adalah sebuah pusat peragaan ilmu dan teknologi di Kota Baru Parahyangan, Kecamatan Padalarang, Kabupaten Bandung Barat, Provinsi Jawa Barat. Ikon penanda Puspa IPTEK Sundial adalah jam matahari. Nama museum ini merupakan sebuah akronim.', -6.851963, 107.4940107, NULL, ' 08.30–16.30', 'https://commons.wikimedia.org/wiki/Special:FilePath/Science%20Center%2C%20Puspa%20Iptek%2C%20Kota%20Baru%20Parahyangan%20-%20panoramio%20%281%29.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109434806', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9944, NULL, 4, 'Pusat Informasi Geopark Nasional Merangin', 'Merangin', 'Air Batu, Merangin, Jambi', 'Pusat Informasi Geopark Merangin atau Museum Geopark Merangin adalah museum mengenai Geopark Merangin-Jambi yang terletak di kabupaten Merangin, provinsi Jambi. Jenis koleksi yang disimpan meliputi benda biologi, geologi, arkeologi, dan numismatika. Benda biologi terdiri dari fosil-fosil flora dan fauna.', -2.1785903, 102.1109277, NULL, 'Jum 08.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Geopark-merangin%201.png?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109434808', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9945, NULL, 4, 'Museum Taman Purbakala Cipari', 'Jawa Barat', 'Kuningan, Jawa Barat', 'Museum Taman Purbakala Cipari adalah museum khusus yang berada dalam Situs Purbakala Cipari di Kabupaten Kuningan. Koleksi museum sebagian besar berupa artefak yang terbuat dari batu. Museum ini juga mengoleksi benda peninggalan peradaban manusia zaman batu seperti peti kubur, kapak batu, gelang batu dan tembikar.', -6.9627463, 108.4668922, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Situs%20Cipari%2002.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109437047', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9946, NULL, 4, 'Museum Pangeran Cakrabuana', 'Cirebon', 'Tukmudal, Cirebon, Jawa Barat', 'Museum Pangeran Cakrabuwana adalah museum khusus yang mengoleksi benda budaya dan kesenian di Cirebon. Pembangunan museum dilakukan pada tahun 2014 oleh Pemerintah Kabupaten Cirebon. Peresmiannya dilakukan oleh Bupati Cirebon pada tanggal 2 April 2014.', -6.7625649, 108.4729901, NULL, ' 07.00–http.//www.wikidata.org/.well-known/genid/66472e134132395b7fe06cbc8b49fd5f', 'https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20Pangeran%20Cakrabuana.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109437061', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9947, NULL, 4, 'Museum Potehi Gudo Jombang', 'Jombang', 'Jalan Raya Gudo, Gudo, Jawa Timur', 'Museum Potehi Gudo Jombang adalah sebuah museum yang berada di dalam Klenteng Hong San Kiong di Desa Gudo, Kecamatan Gudo, Kabupaten Jombang, Jawa Timur. Status museum ini adalah museum khusus yang hanya mengoleksi wayang potehi. Pendiri museum adalah ketua Yayasan Klenteng Hong San Kiong yang bernama Toni Harsono.', -7.6275606, 112.1910796, 0, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/01%20Wayang%20Potehi%20Museum%20Ganesya.jpg?width=800', '2026-11-24 09:47:58', '2026-11-24 23:32:50', 'wd:Q109437463', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Museum', 1),
  (9948, NULL, 4, 'Istana Latifah', 'Siak', 'Jalan Kartini, Siak Sri Indrapura, Riau', 'Istana Latifah: Cagar budaya di Siak, Siak.', 0.7952033, 102.0487696, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Latifah%20%282%29.jpg?width=800', '2026-11-24 09:48:05', '2026-11-24 23:32:50', 'wd:Q124250595', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 0),
  (9949, NULL, 4, 'Istana Gunung Sahilan', 'Kampar', 'Sahilan Darussalam, Kampar, Riau', 'Istana Gunung Sahilan: Cagar budaya di Kampar, Kampar.', 0.0882884, 101.2867488, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Kerajaan%20Gunung%20Sahilan%20%283%29.jpg?width=800', '2026-11-24 09:48:05', '2026-11-24 23:32:50', 'wd:Q124250599', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 0),
  (9950, NULL, 4, 'Istana Kesultanan Kampa', 'Kampar', 'Koto Perambahan, Kampar, Riau', 'Istana Kesultanan Kampa: Cagar budaya di Kampar, Kampar.', 0.356914, 101.2094296, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Istana%20Kampa%20%282%29.jpg?width=800', '2026-11-24 09:48:05', '2026-11-24 23:32:50', 'wd:Q124250636', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Istana / Keraton', 0),
  (9951, NULL, 4, 'Benteng Rotterdam', 'Makassar', 'Jalan Wage Rudolf Supratman, Ujung Pandang, Makassar, Sulawesi Selatan', 'Benteng Rotterdam atau Benteng Ujung Pandang adalah benteng peninggalan Kesultanan Gowa yang terletak di pesisir barat Kota Makassar, Sulawesi Selatan.\nBenteng ini awalnya dibangun pada tahun 1545 oleh Raja Gowa ke-9, Daeng Matanre Karaeng Manguntungi Tumaparisi Kallona. Nama awal benteng ini adalah Benteng Ujung Pandang.', -5.13439, 119.40575, NULL, ' 09.00–16.00', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Rotterdam%2C%20Makassar%2C%20Indonesia%20-%2020100227-02.jpg?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q29771', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 16),
  (9952, NULL, 4, 'Benteng Belgica', 'Maluku Tengah', 'Jalan Geraja Tua, Bandanaira, Maluku Tengah, Maluku', 'Benteng Belgica adalah benteng peninggalan Belanda abad ke-17, yang berada di Kecamatan Banda, Kabupaten Maluku Tengah, Maluku. Benteng ini dibangun untuk pertahanan VOC dari serangan rakyat Banda yang menentang monopoli perdagangan pala saat itu.', -4.52662, 129.89869, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Belgica%20%2848250814991%29.jpg?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q4982061', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 15),
  (9953, NULL, 4, 'Benteng Tolukko', 'Ternate', 'Jalan Pemuda, Salero, Ternate, Maluku Utara', 'Benteng Tolukko adalah benteng peninggalan Portugis yang berada di Kelurahan Sangaji, Kecamatan Ternate Utara, Kota Ternate, Maluku Utara, Indonesia. Benteng Tolukko dibangun pada tahun 1522. Benteng ini dibangun Portugis untuk mencoba mengusir Belanda dari pulau Benteng ini diambil alih oleh Belanda pada tahun 1612 dan direnovasi oleh Pieter Both.', 0.8138856, 127.3880932, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Tolukko%20op%20Ternate%2C%20KITLV%20178142.tiff?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q1955002', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 10),
  (9954, NULL, 4, 'Benteng Amsterdam', 'Hila', 'Kaitetu, Maluku Tengah, Maluku', 'Benteng Amsterdam adalah sebuah benteng peninggalan Belanda yang letaknya di perbatasan antara begeri Hila dan negeri Kaitetu, kecamatan Leihitu, Kabupaten Maluku Tengah, sekitar 42 km dari Kota Ambon. Letak benteng ini tepat di samping pantai negeri Hila dan negeri Kaitetu. Benteng Amsterdam adalah bangunan kedua yang didirikan oleh Belanda setelah Casteel Vanveere di negeri Seith hancur.', -3.58256, 128.0832, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Amsterdam%202026%2001.jpg?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q2651405', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 9),
  (9955, NULL, 4, 'Benteng De Kock', 'Guguak Panjang', 'Jalan Yos Sudarso, Kampuang Cino, Bukittinggi, Sumatera Barat', 'Benteng de Kock (bahasa Belanda: Fort de Kock) adalah benteng peninggalan Belanda pada abad ke-19 yang didirikan di atas bukit di Bukittinggi, Sumatera Barat, Indonesia. Di sekitar benteng, permukiman baru tumbuh, yang akhirnya berkembang menjadi Kota Bukittinggi, kota terbesar kedua di Sumatera Barat. Meskipun sisa-sisa gundukan tanah dan beberapa meriam masih bisa dilihat, bangunan asli di atas benteng telah dihancurkan.', -0.30067, 100.36764, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Memorial%20Fort%20de%20Kock.jpg?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q47779', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 8),
  (9956, NULL, 4, 'Benteng Oranje', 'Ternate', 'Jalan Pahlawan Revolusi, Makassar Timur, Ternate, Maluku Utara', 'Benteng Oranje adalah benteng yang dulunya ditinggali Bangsa Portugis dan Belanda, sebagai penanda kekuasaan bangsa tersebut untuk menguasai cengkeh dan hasil alam lainnya dari Ternate. Di sekitar kawasan Benteng Oranje terdapat permukiman yang secara historis dihuni oleh komunitas pedagang dari Tiongkok, Arab, Melayu, dan Makassar. Di dalam benteng terdapat bangunan dengan langgam arsitektur Indis, sedangkan kawasan di luar benteng pada awalnya memiliki ruang terbuka dengan vegetasi.', 0.792878, 127.387, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Oranje%2C%20Ternate%2010.jpg?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q1954949', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 7),
  (9957, NULL, 4, 'Benteng Otanaha', 'Gorontalo', 'Lekobalo, Gorontalo, Gorontalo', 'Benteng Otanaha terletak di atas perbukitan Kelurahan Dembe I, Kecamatan Kota Barat, Kota Gorontalo. Benteng ini merupakan salah satu cagar budaya di Provinsi Gorontalo.\nBenteng ini dapat dicapai melalui empat tempat persinggahan dan 348 anak tangga menuju puncak.', 0.54888, 123.00815, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Otanaha%20Fortress.JPG?width=800', '2026-11-24 09:48:26', '2026-11-24 23:32:50', 'wd:Q277210', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9958, NULL, 4, 'Benteng Kalamata', 'Ternate', 'Falajawa 2, Ternate, Maluku Utara', 'Benteng Kalamata adalah benteng yang dibangun oleh Portugis pada tahun 1540. Benteng Kalamata disebut juga Benteng Kayu Merah. Disebut Benteng Kayu Merah karena berada kelurahan Kayu Merah, Kota Ternate Selatan.', 0.7625, 127.37296, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Kalamata%20%28Kalamata%20Fort%29%20in%20Ternate%2C%20The%20Moluccas%20%28Maluku%29%20%2815012708550%29.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q2320942', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9959, NULL, 4, 'Benteng Van Der Wijck', 'Gombong', 'Jalan Secata, Gombong, Jawa Tengah', 'Benteng Van Der Wijck adalah benteng pertahanan Hindia Belanda yang dibangun sekitar tahun 1820 atau permulaan abad ke 19. Benteng ini terletak di kota Gombong, sekitar 17,35 km sebelah barat dari Ibukota kabupaten Kebumen, Jawa Tengah, 8,72 km Barat Kota Karanganyar, atau 96,92 km dari Yogyakarta.\nNama benteng Van Der Wijck ini diambil dari nama salah satu Gubernur Jenderal Hindia Belanda Carel Herman Aart Van der Wijck yang bertugas di Jawa pada masa itu  yakni sekitar tahun 1893-1899.', -7.59932, 109.51759, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20van%20der%20Wijck%20-%20Entrance.JPG?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q2382589', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9960, NULL, 4, 'Benteng Duurstede', 'Saparua', 'Saparua, Maluku Tengah, Maluku', 'Benteng Duurstede adalah suatu benteng Belanda abad ke-17 yang berlokasi di Saparua, Maluku, Indonesia. Benteng ini awalnya melindungi Desa Saparoea. Panduan navigasi dari tahun 1878 menyatakan: "terdapat pelabuhan yang bagus di dekat benteng ini di musim angin barat sekitar 12 fathom." Benteng ini terbuka untuk umum dan telah banyak dipulihkan.', -3.57504, 128.65924, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Duurstede%20dari%20Atas.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q2433724', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9961, NULL, 4, 'Benteng Nassau', 'Ternate', 'Jalan Dr. Rehatta, Bandanaira, Maluku Tengah, Maluku', 'Benteng Nassau adalah benteng Belanda pertama yang dibangun di Pulau Neira, Kepulauan Banda, Maluku. Benteng ini selesai dibangun pada tahun 1609, tujuannya adalah untuk mengontrol perdagangan pala, yang pada saat itu hanya tumbuh di Kepulauan Banda.\nPortugis sebelumnya telah berusaha untuk membangun sebuah benteng di lokasi ini pada tahun 1529, tetapi setelah membangun fondasi, mereka meninggalkan pekerjaan karena adanya resistansi dari penduduk setempat.', -4.52813, 129.89756, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Nassau%201646.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q16773101', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9962, NULL, 4, 'Benteng Kastela', 'Ternate', 'Jalan Kh. Ahmad Dahlan Kelurahan Sasa, Kecamatan Ternate Selatan, Jambula, Ternate, Maluku Utara', 'Benteng Kastela adalah sebuah reruntuhan benteng yang terletak di pesisir barat daya Ternate. Benteng ini terkenal sebagai benteng kolonial pertama yang dibangun di Kepulauan Maluku, Indonesia. Dibangun oleh Portugis pada tahun 1522, benteng ini juga disebut dalam bahasa yang berbeda seperti São João Batista (Bahasa Portugis), Ciudad del Rosario (Bahasa Spanyol) atau Gammalamma (Bahasa Ternate dan Belanda).', 0.76126, 127.312, 0, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ruins%20of%20Kastella%2C%20Ternate.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q17052192', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 6),
  (9963, NULL, 4, 'Benteng Van der Capellen', 'Batusangkar', 'Jalan Pasar Papan, Diponegoro, Batusangkar, Sumatera Barat', 'Benteng Van der Capellen adalah benteng peninggalan Belanda yang berdiri di Batusangkar, Sumatera Barat, Indonesia. Fort Van der Capellen juga nama lama Batusangkar. diambil dari nama seorang jenderal belanda yaitu Godert Alexander Gerard Philip baron van der Capellen.', -0.45588, 100.59393, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Van%20Der%20Capellen%202017.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q12475821', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 5),
  (9964, NULL, 4, 'Benteng Middelburg', 'Ambon', 'Passo, Ambon, Maluku', 'Benteng Middelburg terletak di Negeri Passo, Kecamatan Baguala, Kota Ambon, Maluku. Benteng ini berada di kawasan permukiman dan berjarak sekitar 50 meter dari Gereja Menara Iman Jemaat Negeri Passo. Benteng Middelburg disebut dibangun oleh Portugis sekitar tahun 1524 karena posisi Negeri Passo yang strategis.', -3.6310446, 128.2531977, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Middelburg%20%28Ambon%29%2001.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q140398243', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 4),
  (9965, NULL, 4, 'Benteng Frederik Hendrik', 'Indonesia', 'Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Benteng Prins Frederik, adalah sebuah fortifikasi yang dibangun pada tahun 1837 oleh pemerintah Belanda di Batavia (kini Jakarta), Hindia Belanda (kini Indonesia). Benteng ini terletak di Taman Wilhelmina, yang kemudian dihancurkan sekitar tahun 1961 dan digantikan oleh Masjid Istiqlal.\nMasyarakat setempat biasa menyebut benteng ini sebagai Gedung Tanah.', -6.170422, 106.831162, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20%27Citadel%20%27Prins%20Hendrik%27%20te%20Weltevreden%27%20TMnr%2010002113.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q12475807', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 4),
  (9966, NULL, 4, 'Benteng Tabanio', 'Tanah Laut', 'Tanggul, DUSUN VI, DESA TABANIO, Tanah Laut, Kalimantan Selatan', 'Benteng Tabanio (bahasa Inggris: Fort Tabanio) adalah bekas benteng historis sebagai pusat pertahanan militer Belanda yang terletak di Distrik Tabanio (sekarang Desa Tabanio), Kabupaten Tanah Laut, Kalimantan Selatan.', -3.75847, 114.611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Denah%20Fort%20Tabanio.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q51696483', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9967, NULL, 4, 'Benteng Tatas', 'Indonesia', 'Jalan Letnan Jenderal R. Suprapto, Banjarmasin Tengah, Banjarmasin, Kalimantan Selatan', 'Benteng Tatas (bahasa Inggris: Fort Tatas) adalah bekas benteng historis sebagai pusat pertahanan militer Belanda di Kalimantan. Situs Benteng ini terletak di pusat kota banjarmasin, sekarang menjadi lahan Masjid Raya Sabilal Muhtadin.', -3.31911, 114.59, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Het%20bezoek%20van%20de%20Gouverneur-Generaal%20mr.%20Dirk%20Fock%20aan%20Bandjermasin%20tijdens%20zijn%20rondreis%20door%20de%20Zuider-%20en%20Oosterafdeling%20van%20Borneo%201924-04-00%20TMnr%2060013434.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q56388332', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9968, NULL, 4, 'Benteng Indrapatra', 'Aceh', 'Jalan Kerapu, Gampongbaro, Aceh Besar, Aceh', 'Benteng Indra Patra (bahasa Aceh: Kuta Indra Patra, Aksara Jawoë :كوتا ايندرا ڤترا) adalah sebuah benteng bersejarah di Aceh yang telah digunakan sejak era Hindu hingga era Islam. Benteng ini terletak di Kabupaten Aceh Besar, Aceh. Benteng ini pada awalnya digunakan sebagai bangunan pertahanan dari penyerangan musuh ke dalam wilayah Aceh yang saat itu masih merupakan Kerajaan Lamuri.', 5.63433, 95.4713, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Inside%20of%20Indrapatra%20Fortress.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q56486827', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9969, NULL, 4, 'Benteng Bukit Tajadi', 'Bonjol', 'Nagari Ganggo Hilia, Pasaman, Sumatera Barat', 'Benteng Bukit Tajadi atau kadang salah dieja Bukit Tak Jadi adalah bekas benteng pertahanan Kaum Padri yang terletak di Jorong Pasar, Nagari Ganggo Hilia, Kecamatan Bonjol, Kabupaten Pasaman, Sumatera Barat, Indonesia. Saat meletusnya Perang Padri, benteng ini menjadi pusat komando pasukan Padri. Area benteng meliputi bukit berbentuk persegi panjang yang memiliki kemiringan hampir tegak lurus ke atas.', -0.016971, 100.2264942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Bukit%20Tajadi%202020.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q65209596', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9970, NULL, 4, 'Benteng Pulau Cingkuk', 'Pesisir Selatan', 'Painan, Sumatera Barat', 'Benteng Pulau Cingkuk adalah benteng yang terletak di Pulau Cingkuk, Dusun Cerocok, Desa Painan Selatan, Kecamatan IV Jurai, Kabupaten Pesisir Selatan, Provinsi Sumatera Barat.  Balai Pelestarian Cagar Budaya Sumatera Barat telah mendaftarkan Benteng Pulau Cingkuk sebagai cagar budaya Indonesia pada Kementerian Pendidikan dan Kebudayaan. Benten Pulau Cingkuk telah ditetapkan sebagai salah satu cagar budaya Indonesia pada tanggal 17 Oktober 2011.', -1.35438, 100.55892, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Pulau%20Cingkuk%2002.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q106280173', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9971, NULL, 4, 'Benteng Fuerza Nueva', 'Ternate', NULL, 'Benteng Fuerza Nueva merupakan benteng peninggalan Spanyol di Ternate. Asal usul nama “Fuerza Nueva” diartikan sebagai “kekuatan Nueva” diartikan sebagai “kekuatan baru” dari serapan bahasa Spanyol. Menurut Dr.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Fuerza%20Nueva.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q141642505', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9972, NULL, 4, 'Benteng Tore', 'Tidore', NULL, 'Benteng Torre yang terletak di Kota Tidore Kepulauan, Provinsi Maluku Utara, tepatnya berada di Kelurahan Soasio, Kecamatan Tidore Pulau merupakan peninggalan bangsa Portugis pada abad ke 18 sebagai lokasi pertahanan kota tidore dari penyerangan spanyol pada saat itu, Benteng Torre saat ini sudah menjadi salah satu kawasan destinasi wisata di Kota Tidore kepulauan setelah adanya pengembangan dari balai cagar budaya provinsi Maluku Utara, meskipun belum dikelola secara baik oleh pemerintah Kota Tidore sebagai potensi penunjang pendapatan daerah (PAD), Benteng Tore banyak dikunjungi para wisatawan domestik dan mancanegara.\nBenteng Torre yang bangunanya berjarak 100 meter dari Kadaton Kesultanan Tidore dibangun tepatnya pada tahun 1578 yang dipimpin langsung oleh Panglima Portugis Sancho de Vasconcelos setelah mendapat izin dari Sultan Tidore saat itu yang dijabat Gapi Baguna atau dikenal dengan Sirajun Arifin, nama benteng "Tore" sendiri diambil dari salah satu nama petinggi pejabat Portugis di kala itu bernama Hernando de la Torre.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Torre%20di%20Tidore.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q141642714', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 3),
  (9973, NULL, 4, 'Benteng Nieuw Zeelandia', 'Maluku Tengah', 'Haruku, Maluku Tengah, Maluku', 'Benteng Nieuw Zeelandia: Benteng di Maluku, Indonesia, Maluku Tengah.', -3.60277, 128.417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Nieuw%20Zeelandia%2001.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q104534008', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 2),
  (9974, NULL, 4, 'Benteng Fort Concordia', 'Kota Raja', 'Jalan Pahlawan, Kec. Kota Lama, Kupang, Nusa Tenggara Timur', 'Benteng Fort Concordia adalah benteng di Kota Raja.', -10.162773, 123.574766, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/AMH-4677-NA%20View%20of%20Fort%20Concordia%20at%20Coupan.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q10283788', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 2),
  (9975, NULL, 4, 'Benteng Baluwerti Keraton Yogyakarta', 'Yogyakarta', NULL, 'Benteng Baluwerti (bahasa Jawa: ꦧꦺꦠꦺꦁꦧꦭꦸꦮꦂꦠꦶ, translit. Bètèng Baluwarti) merupakan sebuah dinding yang mengelilingi kawasan Keraton Ngayogyakarta Hadiningrat. Dinding ini didirikan atas prakarsa Hamengkubuwana II ketika masih menjadi putra mahkota pada tahun 1785–1787.', -7.8137278, 110.3629074, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jokteng%20Lor%20Wetan.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q17999304', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 2),
  (9976, NULL, 4, 'Benteng Vredeburg', 'Yogyakarta', 'Jalan Margo Mulyo, Gondomanan, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Benteng Vredeburg: Benteng di yogyakarta, Yogyakarta.', -7.800436, 110.365686, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort%20Vredeburg%2C%20Yogyakarta%2C%20Indonesia.JPG?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q120306261', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 1),
  (9977, NULL, 4, 'Fort De Verwachting', 'Sanana', 'Sanana, Maluku Utara', 'Fort De Verwachting adalah benteng di Sanana.', -2.055306, 125.97996, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Op%20het%20Fort%20te%20Sanana%20Soela-eilanden.%20TMnr%2060008337.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q2648495', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 1),
  (9978, NULL, 4, 'Benteng Bernaveld Amasing', 'Indonesia', NULL, 'Benteng Bernaveld Amasing: Bangunan peninggalan Belanda di Pulau Bacan.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benteng%20Barnaveld%20Bacan.jpg?width=800', '2026-11-24 09:48:27', '2026-11-24 23:32:50', 'wd:Q56197906', 'wikidata', 'Pagi hari, hari kerja (lebih sepi)', 'Benteng', 0),
  (9979, NULL, 7, 'Masjid Luar Batang', 'Jakarta', 'Jalan Gedong Panjang, Penjaringan, Jakarta Utara', 'Masjid Jami Keramat Luar Batang atau juga populer dengan sebutan Masjid Luar Batang adalah sebuah bangunan ibadah bersejarah yang berada di daerah Penjaringan, Jakarta Utara. Di masjid ini terdapat makam seorang ulama bernama Habib Husein bin Abubakar bin Abdillah Alaydrus atau lebih dikenal dengan \'Habib Husein\'. Dia merupakan seorang Arab Hadramaut yang hijrah ke tanah Jawa melalui Pelabuhan Sunda Kelapa pada 1736.', -6.1238, 106.80646, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Moskee%20Luar%20Batang%20%28Batavia%29%20TMnr%2060046455.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q13094999', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 8),
  (9980, NULL, 7, 'Masjid Jamik Air Tiris', 'Kampar', 'Tanjung Berulak, Kampar, Riau', 'Masjid Jami Air Tiris adalah salah satu masjid tertua di kabupaten Kampar, provinsi Riau, indonesia.', 0.3731726, 101.0939378, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jamik%20Air%20Tiris%20Minang.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497294', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9981, NULL, 7, 'Masjid Raya Makassar', 'Makassar', 'Jalan Jenderal M. Yusuf, Bontoala, Makassar, Sulawesi Selatan', 'Masjid Raya Makassar (Makassar: ᨆᨔᨗᨁᨗ ᨒᨚᨄᨚᨓ ᨆᨀᨔᨑ) merupakan sebuah masjid yang terletak di Makassar, Indonesia. Masjid ini dibangun pada tahun 1948 dan selesai pada tahun 1949. Masjid ini mengalami renovasi dari tahun 1999 hingga tahun 2005.', -5.1305556, 119.4197222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Makassar.JPG?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497329', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9982, NULL, 7, 'Masjid Katangka', 'Indonesia', 'Jalan Syech Yusuf, Rappocini, Makassar, Sulawesi Selatan', 'Masjid Al-Hilal atau Masjid Katangka adalah salah satu masjid tertua di provinsi Sulawesi Selatan, Indonesia. Dinamakan Masjid Katangka karena berlokasi di kelurahan Katangka, kecamatan Somba Opu, Kabupaten Gowa. Selain itu, masjid ini disebut Katangka, karena bahan baku dasar dari masjid tersebut diyakini diambil dari pohon Katangka.', -5.1907013, 119.451227, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Tua%20Al-Hilal%20Katangka.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q13094989', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9983, NULL, 7, 'Masjid Kasunyatan', 'Serang', 'Jalan Raya Banten, Kasemen, Serang, Banten', 'Masjid Kasunyatan adalah masjid yang terletak di Desa Kasunyatan, Kecamatan Kasemen, Kota Serang. Luas lahannya adalah 2544 m2. Kompleks masjid ini dikelilingi oleh tembok keliling yang mempunyai tiga buah gapura di bagian barat, selatan, dan timur.', -6.050932, 106.157169, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kasunyatan-1.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q13199811', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9984, NULL, 7, 'Masjid Angke', 'Tambora', 'Jalan Pangeran Tubagus Angke - Gang Masjid I, Tambora, Jakarta Barat', 'Masjid Angke, atau yang kini dikenal sebagai Masjid Al-Anwar, adalah salah satu masjid tertua di DKI Jakarta. Masjid yang terletak di Kelurahan Angke, Kecamatan Tambora, Jakarta Barat ini diyakini dibangun oleh sekelompok orang Bali di Batavia pada tahun 1761.', -6.14337, 106.796, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Moskee%20te%20Angke%20bij%20Batavia%20TMnr%2060048715.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q19646040', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 7),
  (9985, NULL, 7, 'Masjid Jami Sungai Banar', 'Kalimantan Selatan', 'Jalan Dr. Kyai Haji Idham Chalid, Cempaka, Hulu Sungai Utara, Kalimantan Selatan', 'Masjid Jami Sungai Banar adalah salah satu masjid tua di Kalimantan Selatan yang terletak di tepi Sungai Negara, sekitar 3 km dari Amuntai, Kabupaten Hulu Sungai Utara, tepatnya di desa Jarang Kuantan, kecamatan Amuntai Selatan.', -2.439747, 115.2413631, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%20Sungai%20Banar%20006.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497300', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9986, NULL, 7, 'Masjid Kauman Semarang', 'Semarang', 'Jalan Suromenggalan, Semarang Tengah, Kota Semarang, Jawa Tengah', 'Masjid Agung Semarang atau biasa disebut Masjid Kauman Semarang (bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦑꦲꦸꦩ꧀ꦩꦤ꧀ꦯꦼꦩꦫꦁ) adalah sebuah masjid tertua di Semarang, Jawa Tengah, memiliki sejarah yang panjang dan erat kaitannya dengan sejarah berdirinya kota Semarang. Masjid yang kini telah menjadi cagar budaya dan harus dilindungi menjadi kebanggaan warga Semarang karena bangunannya yang khas, mencaerminkan jatidiri masyarakat pesisir yang lugas tetapi bersahaja. Seperti halnya pada masjid-masjid kuno di pulau Jawa, Masjid Agung Semarang berada di pusat kota (alun-alun) dan berdekatan dengan pusat pemerintahan (kanjengan) dan penjara, serta tak berjarak jauh dari pusat perdagangan (pasar Johar), merupakan ciri khas dari tata ruang kota pada zaman dahulu.', -6.97248, 110.42261, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kauman%20Semarang.png?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q3386723', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9987, NULL, 7, 'Masjid Taqwa Muhammadiyah', 'Belakang Tangsi', 'Jalan M. Yamin, Belakang Tangsi, Padang, Sumatera Barat', 'Masjid Taqwa Muhammadiyah adalah salah satu masjid di Indonesia yang terletak di pusat Kota Padang, Sumatera Barat. Berada di kawasan Pasar Raya Padang, masjid yang pertama dibangun pada 1961 berupa bangunan berlantai dua ditandai dengan kubah. Namun, pada 6 Januari 1975, masjid pertama mengalami kerusakan berat setelah kubah runtuh.', -0.951829, 100.360005, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Muhammadiyah%20Padang%202019%20%282%29.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q10994410', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9988, NULL, 7, 'Masjid Agung Al-Karomah', 'Banjar', 'Ahmad Yani, Martapura, Kalimantan Selatan', 'Masjid Agung Al Karomah adalah masjid agung yang terletak di Martapura, Kabupaten Banjar, Kalimantan Selatan dan merupakan masjid terbesar di Kalimantan Selatan. Masjid ini juga merupakan tengara tanah dari Martapura karena mudah diakses dari seluruh kota di Kalimantan Selatan dan terletak di Jalan Ahmad Yani yang merupakan jalan utama (jalan nasional) antar kota, terutama dari Kalimantan Timur (arah utara) ke Kota Banjarmasin.', -3.4049172, 114.8484061, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Al-Karomah.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497252', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9989, NULL, 7, 'Masjid Raya Akbar At-Taqwa', 'Bengkulu', 'Anggut Atas, Bengkulu, Bengkulu', 'Masjid Raya Akbar At-Taqwa merupakan sebuah masjid yang terletak di Bengkulu, Indonesia. Masjid ini dibangun pada tahun 1988 dan selesai pada tahun 1989. Kemiripan masjid ini dengan model bangunan istana era kolonial terlihat dari taman yang cukup luas dengan gaya penataan layaknya taman di halaman istana kepresidenan atau alun-alun kecil di halaman keraton.', -3.8, 102.2588889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q18455520', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9990, NULL, 7, 'SMA Tri Ratna', 'Jakarta Selatan', 'Jalan Raden Saleh Raya, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Masjid Jami\' Al-Makmur adalah sebuah Masjid bersejarah yang terletak di Jl. Raden Saleh Raya No. 30, Cikini, Menteng, Jakarta Pusat.', -6.1912, 106.8428, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE%20TROPENMUSEUM%20Moskee%20in%20Batavia%20TMnr%2010014927.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q20716718', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9991, NULL, 7, 'Masjid Terapung Al-Aminah', 'Hanura', 'Pesawaran, Lampung', 'Masjid Terapung Al-Aminah adalah masjid yang terletak di 300 meter dari bibir pantai Sari Ringgung, Kecamatan Teluk Pandan, Kabupaten Pesawaran, Provinsi Lampung. Masjid ini mengapung ditopang oleh beberapa pelampung dan dijangkar supaya tidak hanyut. Masjid ini awalnya difungsikan sebagai fasilitas ibadah bagi nelayan yang masih berada di laut.', -5.556379, 105.2547802, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Terapung%20Al-Aminah.JPG?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q25461108', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9992, NULL, 7, 'Masjid Al Imtizaj', 'Bandung', 'Jalan ABC, Sumur Bandung, Kota Bandung, Jawa Barat', 'Masjid Al-Imtizaj adalah salah satu masjid yang bernuansa oriental dan arsitektur bercorak negeri tirai bambu yang berada di Kota Bandung. Letak masjid ini lebih tepatnya berada di Jalan Banceuy nomor 8, Kota Bandung, Jawa Barat.', -6.9194444, 107.6078611, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Al-Imtizaj%202.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q61446775', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9993, NULL, 7, 'Masjid Al-Hakim', 'Berok Nipah', 'Jalan Samudra, Berok Nipah, Padang, Sumatera Barat', 'Masjid Al-Hakim Padang adalah sebuah masjid bergaya Taj Mahal di tepi Pantai Padang, Kota Padang, Sumatera Barat, Indonesia. Masjid ini mulai dibangun pada awal 2017. Biaya pembangunannya berasal dari seorang donatur, sementara lahannya disediakan oleh Pemerintah Kota Padang seiring penataan Pantai Padang yang dilakukan sejak 2014.', -0.960518, 100.353282, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Al%20Hakim%20oleh%20Denas.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q87056773', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 6),
  (9994, NULL, 7, 'Masjid Agung Sunda Kelapa', 'Jakarta', 'Jalan Taman Sunda Kelapa, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Masjid Agung Sunda Kelapa adalah masjid yang terletak di Jalan Taman Sunda Kelapa Nomor 16, Menteng, Jakarta Pusat, DKI Jakarta, Indonesia. Masjid ini dibuka setiap hari.', -6.2015233, 106.832956, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Sunda%20Kelapa%2C%20Jakarta%20%282010%29.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497266', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (9995, NULL, 7, 'Masjid Jami Keraton Sambas', 'Kalimantan Barat', 'Tebing Batu, Sambas, Kalimantan Barat', 'Masjid Jami Keraton Sambas adalah masjid yang berada di komplek keraton Kesultanan Sambas, Kota Sambas, Kalimantan Barat. Masjid yang resminya bernama Masjid Sultan Muhammad Syafi\'oeddin II ini tercatat sebagai masjid tertua di Kalimantan Barat.', 1.325678, 109.2256583, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%27%20Sultan%20Muhammad%20Shafiuddin%20II%20Sambas.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497298', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (9996, NULL, 7, 'Masjid Jami Tuhfaturroghibin', 'Banjarmasin', 'Jalan Alalak Tengah, Banjarmasin Utara, Banjarmasin, Kalimantan Selatan', 'Masjid Jami\' Tuhfaturroghibin atau lebih populer dengan nama Masjid Kanas adalah sebuah masjid bersejarah yang berlokasi di kawasan Alalak Tengah, Banjarmasin, Kalimantan Selatan. Masjid menjadi khas karena terdapat hiasan buah nenas. Lantaran berarsitektur Timur Tengah campur Banjar, sekilas masjid ini mirip Masjid Jami Sungai Jingah.', -3.268618, 114.570143, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%20Tuhfaturroghibin.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497302', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (9997, NULL, 7, 'Masjid Muhammadiyah Kelayan', 'Banjarmasin', 'Jalan Kelayan B, Banjarmasin Selatan, Banjarmasin, Kalimantan Selatan', 'Masjid Muhammadiyah Kelayan adalah sebuah masjid yang dimiliki oleh Persyarikatan Muhammadiyah, yang terletak di Jalan Kelayan B,  Kelurahan Kelayan Barat, Banjarmasin Selatan, Kota Banjarmasin, Provinsi Kalimantan Selatan.\nMasjid ini terletak di tepi Sungai Kelayan. Bagian depan menghadap ke Jalan Kelayan B, sedangkan bagian belakang berada tepat di tepi Sungai Kelayan.', -3.3296599, 114.5960761, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Muhammadiyah%20Kelayan.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497311', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (9998, NULL, 7, 'Masjid Sa’adah', 'Gurun', 'Gurun, Tanah Datar, Sumatera Barat', 'Masjid Saadah atau Masjid As-Saadah adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Gurun, Kecamatan Sungai Tarab, Kabupaten Tanah Datar, Sumatera Barat. Masjid yang mulai dipergunakan pada tahun 1917 ini dibangun pada tahun 1910 dengan arsitektur yang sedikit menyerupai Masjid Rao Rao di Nagari Rao Rao, Sungai Tarab.\nSaat ini, selain digunakan untuk aktivitas ibadah umat Islam, masjid ini juga digunakan sebagai sarana pendidikan agama bagi masyarakat sekitar.', -0.442399, 100.557931, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Saadah%202020%2002.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497333', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (9999, NULL, 7, 'Masjid Shiratal Mustaqiem', 'Samarinda', 'Pangeran Bendahara, Samarinda Seberang, Samarinda, Kalimantan Timur', 'Masjid Shiratal Mustaqiem adalah masjid tertua di Kota Samarinda, Provinsi Kalimantan Timur, Indonesia, tepatnya di Kelurahan Mesjid, Kecamatan Samarinda Seberang. Masjid yang dibangun pada tahun 1881 ini pernah menjadi pemenang ke-2 dalam festival masjid-masjid bersejarah di Indonesia pada tahun 2003.', -0.5155556, 117.1522222, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Shiratal%20Mustaqiem%20%282%29.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497337', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10000, NULL, 7, 'Masjid Riadhusshalihin', 'Kalimantan Selatan', 'Jalan Haji Damanhuri, Barabai, Kalimantan Selatan', 'Masjid Agung Riadhusshalihin (bahasa Arab: مسجد الجامع رياض شليهين)  adalah sebuah masjid bersejarah di Barabai, Kabupaten Hulu Sungai Tengah, Provinsi Kalimantan Selatan, Indonesia. Masjid ini dibangun pada tahun 1962; sekaligus menjadi salah satu tempat wisata religi dan wisata terpenting di Barabai.\nMasjid ini dibangun berdasarkan niat baik dari Jenderal Amirmachmud.', -2.5818936, 115.3826375, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Riadhusshalihin%20001.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q17997786', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10001, NULL, 7, 'Masjid Syuhada', 'Yogyakarta', 'Jalan Nyoman Oka, Gondokusuman, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Masjid Syuhada atau Masjid Agung Kota Yogyakarta adalah sebuah bangunan masjid bersejarah di daerah Kotabaru, Gondokusuman, Kota Yogyakarta. Bangunan masjid tersebut bernama "syuhada" yang bermakna penghargaan kepada para pejuang yang gugur semasa Revolusi Nasional Indonesia. Masjid tersebut merupakan salah satu masjid yang menyimpan nilai sejarah, terutama berkaitan dengan perjuangan kemerdekaan Indonesia.', -7.786269, 110.369236, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Syuhada.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q18396842', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10002, NULL, 7, 'Masjid Kampus UGM', 'Sleman', 'Jalan Tevesia, Catur Tunggal, Sleman, Daerah Istimewa Yogyakarta', 'Masjid Kampus Universitas Gadjah Mada (atau disingkat Maskam UGM) adalah sebuah masjid kampus milik Universitas Gadjah Mada yang terletak di Kabupaten Sleman, Daerah Istimewa Yogyakarta.  Masjid ini terletak di Jalan Olahraga, Bulaksumur, Caturtunggal, Depok, Sleman.', -7.773351, 110.380016, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kampus%20Universitas%20Gadjah%20Mada%202026%20oleh%20Denas.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q19728968', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10003, NULL, 7, 'Masjid An-Nawier', 'Jakarta', 'Jalan Pekojan, Tambora, Jakarta Barat', 'Masjid An-Nawier, Masjid An-Nawir, atau juga dikenal sebagai Masjid Pekojan di Jakarta, adalah salah satu masjid tertua di Kota Jakarta. Masjid yang terletak di Jl. Pekojan no 79, Pekojan, Tambora, Jakarta Barat, ini dibangun pada tahun 1760 oleh Sayid Abdullah bin Husein Alaydrus.', -6.141518, 106.804522, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%20Annawier%20Pekojan.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q38251541', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10004, NULL, 7, 'Masjid Raya Al Az\'hom', 'Tangerang', 'Tangerang, Banten', 'Masjid Raya Al-A\'zhom (bahasa Arab: مسجد الجامع الأزهم) adalah sebuah kompleks masjid yang terletak di Kota Tangerang, Banten, Indonesia. Sebagai salah satu masjid besar berdasarkan kapasitas jemaah, Masjid Raya Al-A\'zhom menjadi salah satu ikon keagamaan dan arsitektural di wilayah Tangerang.', -6.1698428, 106.6390134, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Azhom%202.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q107862469', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10005, NULL, 7, 'Masjid Agung Ar Raudhah', 'Pulang Pisau', 'Pulang Pisau, Kalimantan Tengah', 'Masjid Agung Ar Raudhah adalah masjid terluas di wilayah Kabupaten Pulang Pisau, Kalimantan Tengah. Masjid ini terletak di Jalan Pembangunan Rei II Arah Pelindo, Desa Mantaren I, Kecamatan Kahayan Hilir, Kabupaten Pulang Pisau. Masjid ini merupakan salah satu ikon dari Kabupaten Pulang Pisau dan rencananya dijadikan sebagai pusat keagamaan Islam di kabupaten tersebut.', -2.7691667, 114.2655556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Ar%20Raudhah%20Pulang%20Pisau.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q116949697', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 5),
  (10006, NULL, 7, 'Masjid Agung Syuhada Pelaihari', 'Kalimantan Selatan', 'Jalan Almanar, Pelaihari, Kalimantan Selatan', 'Masjid Agung Syuhada adalah sebuah masjid besar dan tertua di Kabupaten Tanah Laut, Kalimantan Selatan, Indonesia, dan menjadi kebanggaan masyarakat Pelaihari.', -3.7992886, 114.7643678, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Syuhada%20Pelaihari.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q3384149', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10007, NULL, 7, 'Masjid Sholihin', 'Surakarta', NULL, 'Masjid Sholihin (bahasa Jawa: ꦩꦱ꧀ꦗꦶꦢ꧀ꦱꦭꦶꦏꦶꦤ꧀, translit. Masjid Salikin) adalah sebuah masjid di Kota Surakarta. Masjid ini didirikan pada tahun 1954 dan terletak di Jalan Gajah Mada 97,Punggawan,Banjarsari,Kota Surakarta,Jawa Tengah.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Sholihin%20Surakarta.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q4264860', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10008, NULL, 7, 'Masjid Djami Keraton Landak', 'Landak', 'Raja, Ngabang, Kalimantan Barat', 'Masjid Djami Keraton Landak adalah sebuah masjid bersejarah di Provinsi Kalimantan Barat, Indonesia, yang berlokasi di kompleks Keraton Landak yang terletak di Ngabang, Kabupaten Landak. Kompleks keraton milik Kerajaan Landak ini terdiri dari tiga bagian yang saling melengkapi, yakni istana kerajaan, masjid, serta makam raja dan para kerabatnya. Terletak di utara istana, Masjid Djami\' Keraton Landak masih terawat dengan baik sampai sekarang.', 0.39738, 109.95594, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Djami%20Keraton%20Landak%203.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497289', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10009, NULL, 7, 'Masjid Jami Aji Amir Hasanuddin', 'Tenggarong', NULL, 'Masjid Jami\' Adji Amir Hasanoeddin (EYD: Masjid Jami Aji Amir Hasanuddin) adalah sebuah masjid bersejarah di kota Tenggarong, Kabupaten Kutai Kartanegara, Provinsi Kalimantan Timur.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Jami%27%20Adji%20Amir%20Hasanoeddin%20%282%29.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497296', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10010, NULL, 7, 'Masjid Raya Al-Karim', 'Koto Kaciak', 'Jalan Ambalad, Duo Koto, Agam, Sumatera Barat', 'Masjid Raya Al-Karim atau Masjid Raya Koto Kaciak adalah sebuah masjid yang terletak di Nagari Koto Kaciak, Kecamatan Tanjung Raya, Kabupaten Agam, Sumatera Barat, Indonesia.', -0.246072, 100.167412, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Al-Karim%20Koto%20Kaciak%202020.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497319', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10011, NULL, 7, 'Masjid Nurul Yaqin Aie Bangih', 'Aia Bangih', 'Nagari Air Bangis, Pasaman Barat, Sumatera Barat', 'Masjid Nurul Yaqin adalah salah satu masjid tertua di Indonesia yang terletak di Nagari Aia Bangih, yang kini secara administratif masuk ke dalam wilayah Kecamatan Sei Beremas, Kabupaten Pasaman Barat, Sumatera Barat. Masjid ini tercatat sebagai masjid tertua di Kabupaten Pasaman Barat.\nDibangun atas prakarsa H. Abdul Azis sekitar tahun 1860, keberadaan Masjid Nurul Yaqin turut berperan dalam penyebaran Islam di Nagari Air Bangis dan menjadi cikal bakal bagi perkembangan masjid-masjid lainnya di Air Bangis.', 0.198906, 99.380509, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Nurul%20Yaqin.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12497316', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10012, NULL, 7, 'Surau Baitul Jalil', 'Aur Tajungkang Tangah Sawah', 'Kampuang Cino, Bukittinggi, Sumatera Barat', 'Surau Baitul Jalil atau dulu bernama Surau Balingka terletak di pusat Kota Bukittinggi, Sumatera Barat, Indonesia. Masjid ini diresmikan pada 17 Agustus 2004 dan memiliki kapasitas 250 orang jamaah. Berada di salah satu sisi Janjang 40, tata letak bangunannya dirancang menyesuaikan kontur.', -0.3019297, 100.3707742, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Surau%20Baitul%20Jalil%20oleh%20Denas.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q12518126', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10013, NULL, 7, 'Masjid Agung Natuna', 'Natuna', '55, Ranai, Kepulauan Riau', 'Masjid Agung Natuna merupakan sebuah masjid yang terletak di Kabupaten Natuna, Indonesia. Masjid ini dibangun pada tahun 2007 dan selesai pada tahun 2009. Masjid ini merupakan bagian dari kompleks Gerbang Utaraku, kawasan yang dipersiapkan sebagai pusat pemerintahan dan bisnis Natuna di wilayah Ranai yang menjadi ibu kota Kabupaten Natuna, tidak hanya itu, masjid juga menjadi titik pusat kawasan tersebut.', 3.952708, 108.3833326, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Natuna.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q13094983', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10014, NULL, 7, 'Masjid Agung Wolio', 'Bau Bau', NULL, 'Masjid Al-Muqarrabin Syafyi Shaful Mu\'min atau lebih dikenal dengan Masjid Agung Wolio adalah sebuah masjid bersejarah yang berlokasi di Kota Baubau, Pulau Buton, Sulawesi Tenggara.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Keraton%20Buton.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q13094985', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10015, NULL, 7, 'Masjid Kiai Gede', 'Kotawaringin Barat', 'Kotawaringin Hulu, Kotawaringin Barat, Kalimantan Tengah', 'Masjid Kiai Gede adalah sebuah masjid yang terletak di desa Kotawaringin Hulu, kecamatan Kotawaringin Lama, Kabupaten Kotawaringin Barat, provinsi Kalimantan Tengah. Masjid ini merupakan bagian dari sejarah perkembangan Islam di Kotawaringin yang dilakukan oleh seorang ulama dari Pulau Jawa bernama Kiai Gede. Pembangunan Masjid Kiai Gede dilakukan pada masa pemerintahan Raja Kerajaan Kotawaringin, Dipati Antakesuma.', -2.48591, 111.44434, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Kyai%20Gede%20001.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q16187809', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10016, NULL, 7, 'Masjid Agung Baiturrahman Banyuwangi', 'Banyuwangi', NULL, 'Masjid Baiturrahman Banyuwangi (bahasa Arab: مسجد بيت الرحمن بانيوانجي) atau yang lebih dikenal Masjid Agung Baiturrahman (bahasa Arab: مسجد الجامع بيت الرحمن) adalah sebuah masjid yang berada di Banyuwangi, Kabupaten Banyuwangi, Provinsi Jawa Timur, Indonesia. Latar belakang berdirinya masjid ini dimulai sejak tanggal 7 Desember 1773, hal ini berdasarkan data pada surat wakaf yang berupa denah gambar arsitektur masjid dari keluarga besar Raden Tumenggung Wiraguna I—Bupati pertama Banyuwangi. Masjid ini sejak awal pembangunan setidaknya mengalami beberapa renovasi, yakni pada tahun 1844, 1971, 1990, dan tahun 2005.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Baiturrahman%20Banyuwangi.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q18519829', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10017, NULL, 7, 'Masjid Agung Purbalingga', 'Purbalingga', 'Gunung Sumbul, Purbalingga, Jawa Tengah', 'Masjid Agung Purbalingga adalah sebuah masjid yang berada di Purbalingga Jawa Tengah. Masjid ini diresmikan oleh Gubernur Jawa Tengah dan dipugar oleh Bupati Purbalingga, Drs. Triyono Budi Sasongko, MSi.', -7.3891077, 109.3625454, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Agung%20Purbalingga.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q19746205', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10018, NULL, 7, 'Surau Lubuk Bauk', 'Batipuah Baruah', '5, Batipuah Baruah, Tanah Datar, Sumatera Barat', 'Surau Lubuk Bauk atau kadang keliru disebut sebagai Masjid Lubuk Bauk terletak di Jorong Lubuk Bauk, Nagari Batipuh Baruh, Kabupaten Tanah Datar, Sumatera Barat. Surau ini didirikan pada 1896 memakai nama tempat berdirinya dan rampung pada 1901.\nSebagaimana umumnya surau di Minangkabau, keberadaan surau ini dikhususkan sebagai pusat pendidikan non-formal setempat.', -0.4771738, 100.456558, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Surau%20Lubuk%20Bauk%202020%2004.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q56390743', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10019, NULL, 7, 'Masjid Raya Kuraitaji', 'Pariaman', 'Jalan Samaun Bakri, Sikabu, Pariaman, Sumatera Barat', 'Masjid Kurai Taji adalah salah satu masjid tertua di Indonesia yang terletak di Desa Batang Tajongkek Kanagarian Kurai Taji atau kini secara administratif termasuk ke dalam wilayah Kota Pariaman, Sumatera Barat. Masjid ini dibangun secara bersama oleh masyarakat Nagari Kurai Taji pada tahun 1900-an dengan turut melibatkan pemuka masyarakat setempat, di antaranya Labai Nan Putiah dan Tuanku Abdurrahman. Seperti kebanyakan masjid-masjid tua di Nusantara, masjid ini juga memiliki bedug berukuran besar atau disebut tabuah gadang dalam bahasa Minang.', -0.635371, 100.168622, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Masjid%20Raya%20Kuraitaji%202020%2001.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q79388202', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10020, NULL, 7, 'Masjid 99 Kubah', 'Makassar', 'Lego-Lego, Mariso, Makassar, Sulawesi Selatan', 'Masjid 99 Kubah (bahasa Arab: مسجد القبة ٩٩) atau yang lebih dikenal dengan Masjid 99 Asmaulhusna (bahasa Arab: مسجد اسماء الحسنى) adalah sebuah masjid artistik dan menjadi ikon yang berada di Kota Makassar, Provinsi Sulawesi Selatan, Indonesia. Masjid dibangun pada tahun 2017 dan diresmikan pada tahun 2023. Masjid 99 Kubah berlokasi di kawasan Center Point of Indonesia (CPI) Tanjung Bunga.', -5.143781, 119.404041, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Makassar%202022%20Bennylin%2073.jpg?width=800', '2026-11-24 09:49:48', '2026-11-24 23:32:50', 'wd:Q116827711', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Masjid', 4),
  (10021, NULL, 7, 'Katedral Jakarta', 'Jakarta', 'Jalan Lapangan Banteng Utara, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Gereja Katedral Jakarta, atau bernama resmi Gereja Katedral Santa Perawan Maria Diangkat ke Surga (bahasa Belanda: De Kerk van Onze Lieve Vrouwe ten Hemelopneming; bahasa Inggris: The Church of Our Lady of the Assumption) adalah sebuah gereja katedral Katolik yang terletak di Jakarta Pusat, Jakarta, ibu kota Indonesia. Gedung gereja ini diresmikan pada 1901 dan dibangun dengan arsitektur neo-gotik dari Eropa, yakni arsitektur yang sangat lazim digunakan untuk membangun gedung gereja beberapa abad yang lalu.\nGereja yang sekarang ini dirancang dan dimulai oleh Pastor Antonius Dijkmans dan peletakan batu pertamanya dilakukan oleh Pro-vikaris, Carolus Wenneker.', -6.1692528, 106.8331194, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20Jakarta%20-%20exterior%20%282025%29%20-%20img%2001.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q55519', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 15),
  (10022, NULL, 7, 'Gereja Sion Jakarta', 'Jakarta Barat', 'Jalan Pangeran Jayakarta, Taman Sari, Jakarta Barat', 'Gereja Protestan di Indonesia bagian Barat Jemaat Sion DKI Jakarta, sering disingkat GPIB Jemaat Sion DKI Jakarta atau Gereja Sion, adalah sebuah gereja Kristen Protestan di Pinangsia, Taman Sari, Jakarta Barat. Bangunan gereja ini telah berdiri sejak abad ke-17 dan merupakan gedung tertua di Jakarta yang masih digunakan sesuai dengan fungsi awalnya. Gereja ini juga diyakini sebagai gereja Protestan tertua di Asia yang masih aktif digunakan hingga kini.', -6.1383, 106.8178, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20GPIB%20Sion%20Jakarta%20%282025%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q2306448', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 9);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (10023, NULL, 7, 'Graha Maria Annai Velangkanni', 'Medan', 'Gang Pertama, Medan Tuntungan, Kota Medan, Sumatera Utara', 'Graha Maria Annai Velangkanni adalah gereja Katolik bergaya India-Mughal yang dibuka pada tahun 2005 di Kota Medan, Sumatera Utara, Indonesia. Peresmian bangunan dilakukan oleh Gubernur Sumatera Utara Rudolf Pardede. Konsekrasi bangunan dan altar dilakukan oleh Uskup Agung Medan Mgr.', 3.548065, 98.608646, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/GrahaMaria.JPG?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q4349197', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 9),
  (10024, NULL, 7, 'Gereja Blenduk', 'Semarang', 'Jalan Nuri, Semarang Utara, Kota Semarang, Jawa Tengah', 'GPIB Immanuel Semarang, lebih dikenal sebagai Gereja Blenduk, adalah sebuah gereja Protestan di Semarang, Jawa Tengah. Dibangun pada tahun 1753, gereja ini merupakan gereja tertua di provinsi ini.', -6.9681333, 110.4274944, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja-blenduk.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q4350177', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 9),
  (10025, NULL, 7, 'Gereja Katedral Semarang', 'Semarang', 'Jalan Dokter Sutomo, Semarang Selatan, Kota Semarang, Jawa Tengah', 'Gereja Katedral Semarang (nama resminya "Gereja Katedral Santa Perawan Maria Ratu Rosario Suci") (bahasa Jawa: ꦒꦿꦺꦗꦏꦠꦼꦢꦿꦭ꧀ꦱꦼꦩꦫꦁ, translit. Gréja Katedral Semarang) adalah sebuah gereja katedral Katolik yang berada di Jl. Pandanaran No.', -6.9855028, 110.4099167, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Randusari%20interior.JPG?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q4204290', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 8),
  (10026, NULL, 7, 'Gereja Ganjuran', 'Bantul', 'Gang Ganjuran, Bambang lipuro, Daerah Istimewa Yogyakarta', 'Gereja Hati Kudus Yesus adalah sebuah gereja paroki Katolik yang terletak di Ganjuran, Bantul, Daerah Istimewa Yogyakarta, Indonesia. Gereja ini juga dikenal dengan nama Gereja Ganjuran, berdasarkan tempat letaknya. Gereja ini merupakan gereja tertua di Bantul.', -7.9265806, 110.3189944, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ganjuran%20Church%20exterior%20front%20%283%29.JPG?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q4350166', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 6),
  (10027, NULL, 7, 'Gereja Santo Servatius, Kampung Sawah', 'Bekasi', 'Jalan Raya Kampung Sawah, Pondok Melati, Bekasi, Jawa Barat', 'Gereja Santo Servatius, Kampung Sawah adalah sebuah gereja paroki Katolik yang sebagian besar beranggotakan warga Katolik Betawi di wilayah Kampung Sawah, Bekasi, Jawa Barat. Budaya Betawi masih ditunjukkan oleh para anggota gereja tersebut melalui penggunaan bahasa dan kosakata Betawi yang merupakan turunan dari bahasa Melayu. Di Kampung Sawah sendiri budaya Betawi tetap bertahan sekalipun beberapa bagian di antaranya telah punah.', -6.3227634, 106.9377094, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Gereja%20Santo%20Servatius%20Kampung%20Sawah%20%282026%29%2006.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q10972677', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 6),
  (10028, NULL, 7, 'Gereja Santo Yusuf Semarang', 'Semarang', 'Jalan Ronggowarsito, Semarang Utara, Kota Semarang, Jawa Tengah', 'Gereja Santo Yusuf atau Gereja Santo Yosef, juga dikenal sebagai Gereja Gedangan adalah gereja Katolik pertama di kota Semarang. Secara administratif, gereja ini merupakan bagian dari Paroki Santo Yusuf di Keuskupan Agung Semarang.\nGereja ini dirancang oleh arsitek Belanda, W.I. van Bakel dan dibangun pada tahun 1870 hingga 1875 dengan biaya 110.000 gulden untuk memenuhi kebutuhan pertumbuhan penduduk Katolik Semarang.', -6.96596, 110.431, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Exterior%2C%20Gedangan%20Church%2C%202014-06-18.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16900556', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 6),
  (10029, NULL, 7, 'Graha Bethany Nginden', 'Surabaya', 'Jalan Nginden Intan Timur I No.29, Ngiden Jangkungan, Surabaya, Jawa Timur', 'Graha Bethany Nginden biasa disebut sebagai Bethany Church of God (dalam bahasa Inggris) dengan mottonya yang sangat familiar yaitu Successful BETHANY Families adalah sebuah megachurch evangelis yang berafiliasi dengan Gereja Bethany Indonesia yang kemudian beralih kepada Gereja Suara Kebenaran Injil \nGereja Suara Kebenaran Injil ini dipimpin oleh Pdt. Dr. Erastus Sabdono yang berpusat di Mal Artha Gading, Jakarta.', -7.307, 112.7725, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bethany%20Nginden%20Building.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q27860378', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 4),
  (10030, NULL, 7, 'Katedral Kristus Raja, Ende', 'Ende', 'Jalan Kathedral, Ende, Nusa Tenggara Timur', 'Gereja Katedral Ende, secara resmi bernama Gereja Katedral Kristus Raja, adalah sebuah gereja katedral Katolik yang terletak di kota Ende, Nusa Tenggara Timur. Gereja ini terletak di bagian selatan dari pulau Flores.', -8.8452791, 121.645911, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ende%20catholic%20cathedral%20%28Indonesia%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q28797627', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 4),
  (10031, NULL, 7, 'Gereja Kristen Jawa Pakem Kertodadi', 'Pakembinangun', 'Jalan Kaliurang, Pakembinangun, Sleman, Daerah Istimewa Yogyakarta', 'Gereja Kristen Jawa (GKJ) Pakem Kertodadi (bahasa Jawa: ꦒꦿꦺꦗꦏꦿꦶꦱ꧀ꦠꦼꦤ꧀ꦗꦮꦥꦏꦼꦩ꧀ꦏꦼꦂꦠꦢꦢꦶ, translit. Gréja Kristen Jawa Pakem Kertadadi) adalah salah satu gereja di bawah naungan sinode Gereja Kristen Jawa, yang terletak di Jalan Kaliurang km. 18,5, Padukuhan Kertodadi, Kalurahan Pakembinangun, Kapanewon Pakem, Kabupaten Sleman, Provinsi Daerah Istimewa Yogyakarta.', -7.6536762, 110.4232012, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Kristen%20Jawa%20Pakem%20Kertodadi.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q134347105', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 4),
  (10032, NULL, 7, 'Gereja Katolik Kelahiran Santa Perawan Maria', 'Jawa Timur', 'Jalan Kepanjen, Krembangan Selatan, Surabaya, Jawa Timur', 'Gereja Kelahiran Santa Perawan Maria adalah sebuah gereja paroki Katolik dan merupakan salah satu gereja tertua yang terletak di kota Surabaya, Jawa Timur, Indonesia. Berlokasi di Jalan Kepanjen, Surabaya, bangunan religius ini berdampingan dengan gedung SMA Katolik Frateran Surabaya.', -7.242204, 112.736615, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20the%20Birth%20of%20Our%20Lady%2C%20Surabaya%2C%202025%20%2802%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483951', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 4),
  (10033, NULL, 7, 'Gereja Kristen Pasundan', 'Bandung', 'Jalan Kebon Jati No.108, Andir, Kota Bandung, Jawa Barat', 'Gereja Kristen Pasundan (bahasa Sunda: ᮌᮛᮦᮏ ᮊᮛᮦᮞ᮪ᮒᮨᮔ᮪ ᮕᮞᮥᮔ᮪ᮓᮔ᮪, translit. Garéja Karésten Pasundan, bahasa Inggris: Pasundan Christian Church) yang biasa dikenal dengan GKP adalah sebuah gereja yang tumbuh dan berkembang di daerah Pulau Jawa bagian barat, yaitu DKI Jakarta, Jawa Barat dan Banten.  Gereja ini resmi berdiri pada tanggal 14 November 1934 dengan Rad Ageng (Majelis Besar) pertama, yang diketuai oleh Penginjil J. Iken dari Nederlandse Zendelings Vereeniging (NZV) dari Belanda, penulis D. Abednego, dan bendahara Tan Goan Tjong.', -6.9136364, 107.5986658, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Kristen%20Pasundan%202.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16178058', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 4),
  (10034, NULL, 7, 'Gereja Santo Fransiskus Xaverius', 'Kuta', NULL, 'Gereja Katolik St. Fransiskus Xaverius adalah sebuah gereja Katolik dari Paroki Kuta yang berlokasi di Kota Kuta, Bali dan dekat dengan Bandar Udara Ngurah Rai. Bagi turis mancanegara yang singgah di Kuta, gereja ini juga menyelenggarakan misa berbahasa Inggris.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Francis%20Xavier%20Church%20Kuta%2C%20Bali.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19725933', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10035, NULL, 7, 'Gereja Santa Perawan Maria Ratu, Blok Q', 'Jakarta', 'Jalan Suryo Raya, Jakarta Selatan, Daerah Khusus Ibukota Jakarta', 'Gereja Santa Perawan Maria Ratu Paroki Blok Q, disingkat sebagai Gereja SPMR Blok Q, atau yang juga dikenal sebagai Gereja Santa adalah gereja paroki Katolik yang terletak di Jakarta, Indonesia. Wilayah parokinya mencakup Kebayoran Baru, Jakarta Selatan, dan Pasar Santa, yang menjadi nama dari gereja ini. Gereja ini berada dalam reksa pastoral tarekat Serikat Yesus (S.J).', -6.238404, 106.814513, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Dalam%20Gereja%20Santa%20Okt%2024%20%282%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q47004349', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10036, NULL, 7, 'GPIB Tamansari Salatiga', 'Salatiga', 'Jalan Jenderal Sudirman, Salatiga, Jawa Tengah', 'Gereja Protestan Indonesia Bagian Barat (GPIB) Tamansari Salatiga (bahasa Jawa: ꦒꦿꦺꦗꦠꦩꦤ꧀ꦱꦫꦶꦱꦭꦠꦶꦒ, translit. Gréja Tamansari Salatiga) adalah gereja tertua di Salatiga ini dibangun pada tahun 1823 untuk tempat ibadah keluarga besar Batalyon A II Bg yang bermarkas di Jl. Ahmad Yani sekarang.', -7.3252733, 110.5054554, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/GPIB%20Tamansari%20Salatiga.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q97240690', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10037, NULL, 7, 'Gereja Katholik Bukittinggi', 'Bukittinggi', 'Jalan Padang Panjang - Bukittinggi, Panorama, Bukittinggi, Sumatera Barat', 'Gereja Santo Petrus Claver yang bernama resmi Gereja Paroki Santo Petrus Claver, Bukittinggi adalah sebuah gereja paroki Katolik yang terletak di Kota Bukittinggi, Sumatera Barat, Indonesia. Gereja ini didedikasikan kepada Santo Petrus Claver. Gereja ini berada di bawah naungan yurisdiksi Keuskupan Padang.', -0.31015, 100.37168, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katholik%20Bukittinggi%202019.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q106279355', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10038, NULL, 7, 'Gereja Kristen Jawa Tengah Utara Salatiga', 'Indonesia', NULL, 'Gereja Kristen Jawa Tengah Utara (GKJTU) Salatiga adalah bangunan gereja di bawah naungan sinode Gereja Kristen Jawa Tengah Utara yang terletak di Jalan Letjend Sukowati No. 74a, Kelurahan Kalicacing, Kecamatan Sidomukti, Kota Salatiga, Provinsi Jawa Tengah.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Kristen%20Jawa%20Tengah%20Utara%20Salatiga.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q106900515', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10039, NULL, 7, 'Gereja Pentakosta Isa Almasih Indonesia Efata Salatiga', 'Jawa Tengah', NULL, 'Gereja Pentakosta Isa Almasih Indonesia (GPIAI) Efata Salatiga adalah gereja di bawah naungan sinode gereja Kristen aliran Pentakosta yang terletak di Jalan Brigjen Sudiarto No. 1a, Kelurahan Mangunsari, Kecamatan Sidomukti, Kota Salatiga, Provinsi Jawa Tengah. Gereja ini, awalnya merupakan bagian dari Gereja Isa Almasih, tetapi kemudian memisahkan diri pada 9 Mei 1985.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Pentakosta%20Isa%20Almasih%20Indonesia%20Efata%20Salatiga.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q106900525', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10040, NULL, 7, 'Gereja Yesus Sejati Salatiga', 'Salatiga', NULL, 'Gereja Yesus Sejati Salatiga (bahasa Jawa: ꦒꦿꦺꦗꦪꦺꦱꦸꦱ꧀ꦱꦗꦠꦶꦱꦭꦠꦶꦒ, translit. Gréja Yésus Sajati Salatiga) adalah bangunan gereja Kristen non-denominasi (mandiri) yang berada di Jalan Diponegoro No. 11, Kelurahan Salatiga, Kecamatan Sidorejo, Kota Salatiga, Provinsi Jawa Tengah.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Yesus%20Sejati%20Salatiga.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q106900532', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10041, NULL, 7, 'Gereja Bethel Bandung', 'Bandung', 'Jalan Perintis Kemerdekaan, Sumur Bandung, Kota Bandung, Jawa Barat', 'GPIB Bethel Bandung (secara resmi Gereja Protestan di Indonesia Bagian Barat Jemaat Bethel Bandung) adalah gereja Protestan yang berlokasi di Jalan Wastukancana No. 1, Kota Bandung, Jawa Barat. Gereja ini merupakan salah satu gereja Protestan tertua di Kota Bandung dan termasuk bangunan cagar budaya yang dirancang oleh arsitek Belanda Charles Prosper Wolff Schoemaker.', -6.913635, 107.6086978, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Bethel%20Bandung.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q123679619', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10042, NULL, 7, 'Gereja Katolik Santo Yoseph Medari', 'Indonesia', 'Triharjo, Sleman, Daerah Istimewa Yogyakarta', 'Gereja Santo Yoseph yang bernama resmi Gereja Paroki Santo Yoseph, Medari adalah sebuah gereja paroki Katolik yang terletak di Kabupaten Sleman, Daerah Istimewa Yogyakarta, Indonesia. Gereja ini didedikasikan kepada Santo Yoseph. Gereja ini berada di bawah naungan yurisdiksi Keuskupan Agung Semarang.', -7.6888806, 110.3433694, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Front%20Facade%20of%20St.%20Joseph%20Church%20Medari.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q134308216', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10043, NULL, 7, 'Gereja Santo Yusuf, Yos Sudarso', 'Cirebon', 'Jalan Yos Sudarso, Lemahwungkuk, Cirebon, Jawa Barat', 'Gereja Santo Yusuf adalah sebuah gereja paroki Katolik yang berlokasi di Jalan Yos Sudarso, Kota Cirebon, Jawa Barat, Indonesia. Gereja ini merupakan pusat dari Paroki Santo Yusuf Cirebon, atau disebut juga sebagai Paroki Yos Sudarso, yang menjadi bagian dalam Dekanat Priangan pada Keuskupan Bandung. Gereja ini dinamai menurut Yusuf, ayah Yesus Kristus.', -6.7214335, 108.5721064, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katolik%20Santo%20Yusuf%20Cirebon%20tampak%20depan.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q134499909', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10044, NULL, 7, 'Gereja Santo Petrus dan Paulus, Klepu', 'Indonesia', 'Jalan Godean, Sendangmulyo, Minggir, Daerah Istimewa Yogyakarta', 'Gereja Santo Petrus dan Paulus yang bernama resmi Gereja Paroki Santo Petrus dan Paulus, Klepu adalah sebuah gereja paroki Katolik yang terletak di Kabupaten Sleman, Daerah Istimewa Yogyakarta, Indonesia. Gereja ini didedikasikan kepada Santo Petrus dan Paulus. Gereja ini berada di bawah naungan yurisdiksi Keuskupan Agung Semarang.', -7.7560596, 110.242785, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santo%20Petrus%20dan%20Paulus%2C%20Klepu%20%282%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q134499990', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10045, NULL, 7, 'Gereja Immanuel Hila', 'Hila', 'Hila, Maluku Tengah, Maluku', 'Gereja Tua Immanuel Hila merupakan salah satu bangunan bersejarah tertua di Provinsi Maluku yang terletak di Negeri Hila, Kecamatan Leihitu, Kabupaten Maluku Tengah. Bangunan ini menjadi bukti penting dalam sejarah perkembangan agama Kristen di Indonesia bagian timur serta menjadi saksi perjalanan panjang interaksi budaya dan agama di Kepulauan Maluku.', -3.5832321, 128.0839533, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Tua%20Immanuel%20Hila%2001.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q140191432', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10046, NULL, 7, 'Gereja Katolik Santo Antonius Surakarta', 'Surakarta', 'Jalan MGR. Sugiyopranoto, Kampung Baru, Surakarta, Jawa Tengah', 'Gereja Katolik Santo Antonius Surakarta (atau yang lebih dikenal dengan nama Gereja Katolik Santo Antonius Purbayan (Hanacaraka: ꦒꦿꦺꦗꦏꦠꦸꦭꦶꦏ꧀ꦱꦤ꧀ꦠꦺꦴꦄꦤ꧀ꦠꦺꦴꦤꦶꦪꦸꦱ꧀ꦥꦸꦂꦧꦪꦤ꧀, Gréja Katulik Santo Antonius Purbayan) adalah sebuah gereja paroki Katolik yang terletak di Kota Solo, Jawa Tengah. Gereja ini berdiri pada bulan November 1916. Tanggal 13 Juni dipilih menjadi Hari Jadi/Ulang tahun Gereja Katolik Santo Antonius Purbayan, karena pada tanggal tersebut merupakan hari peringatan Santo Pelindung Gereja yaitu Santo Antonius dari Padua.', -7.5686613, 110.8298129, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santo%20Antonius%20Purbayan%20Solo%20by%20Bennylin%2003.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483952', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10047, NULL, 7, 'Gereja Santa Maria de Fatima, Toasebio', 'Jakarta', 'Jalan Kemenangan III, Taman Sari, Jakarta Barat', 'Gereja Katolik Santa Maria de Fatima (bahasa Tionghoa: 草埔法蒂瑪聖母堂) adalah sebuah gereja paroki Katolik yang terletak di Glodok, Taman Sari, Jakarta, Indonesia. Gedung ini dibangun dengan arsitektur Tiongkok pada awal abad ke 19. Gereja ini beralamat di Jalan Kemenangan III (Toosebiostraat) Nomor 47, Glodok, Taman Sari, Jakarta Barat.', -6.1438002, 106.8117792, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santa%20Maria%20de%20Fatima%20-%20Paroki%20Toasebio.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q13641781', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10048, NULL, 7, 'Gereja Kristen Luwuk Banggai', 'Indonesia', NULL, 'Gereja Kristen di Luwuk Banggai (disingkat GKLB) adalah suatu organisasi gereja Kristen Protestan di Indonesia yang terdiri dari lebih kurang 12 gereja-gereja mandiri dari tubuh Indische Kerk/Gereja Protestan Indonesia. GKLB saat ini fokus melayani umat di pulau Sulawesi khususnya di tanah Banggai.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Infografis%20GPI.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q15223783', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10049, NULL, 7, 'Gereja Protestan Indonesia di Donggala', 'Indonesia', NULL, 'Gereja Protestan Indonesia di Donggala (disingkat GPID) adalah sebuah kelompok gereja Protestan di Indonesia yang berpusat di pulau Sulawesi bagian tengah. GPID yang terbentuk pada 4 April 1965 ini merupakan gereja anggota Gereja Protestan di Indonesia (GPI) yang berdiri sendiri. Pada awalnya, anggota jemaatnya berasal dari warga Gereja Masehi Injili di Minahasa (GMIM) yang datang ke Sulawesi Tengah sejak tahun 1909, dan kemudian berkembang sebagai hasil penginjilan yang dilakukan oleh GMIM. Dengan demikian jemaat GPID tersebar di Kabupaten Donggala, Parigi Moutong, Poso, Sigi dan kota Palu sebagai kedudukan kantor Sinode.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Logo%20Gereja%20Protestan%20Indonesia%20Donggala.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16178202', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10050, NULL, 7, 'Gereja Toraja Mamasa', 'Makassar', 'Jalan Kesadaran Raya, Panakkukang, Makassar, Sulawesi Selatan', 'Gereja Toraja Mamasa (disingkat GTM) atau dalam Bahasa Inggris disebut The Toraja Mamasa Church adalah kelompok gereja Kristen Protestan di Indonesia yang beraliran Calvinis/Reformed dahulunya bernama Gereja Kristen Toraja Mamasa (GKTM) dan merupakan jenis lembaga gereja terbesar di Provinsi Sulawesi Barat yang berpusat di Jl. Demmatande No.17, Kelurahan Mamasa, Kecamatan Mamasa, Kabupaten Mamasa, Provinsi Sulawesi Barat (sebelumnya Kabupaten ini pernah menjadi bagian dari Provinsi Sulawesi Selatan, pada waktu itu masih tergabung dengan Polewali sebagai Kabupaten Polewali Mamasa, baru pada tahun 2002 Mamasa menjadi kabupaten tersendiri) Gereja Toraja Mamasa terdaftar sebagai anggota Persekutuan Gereja-Gereja di Indonesia pada tanggal 25 Mei 1950 pada nomor urut 11.', -5.1423807, 119.466892, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Toraja%20house.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16178257', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10051, NULL, 7, 'Gereja Paulus', 'Jakarta', 'Jalan Imam Bonjol, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Gereja Paulus Jakarta atau yang dikenal juga dengan GPIB Jemaat Paulus Jakarta adalah sebuah bangunan gereja yang berada di wilayah Menteng, Jakarta (tepatnya Jalan Taman Sunda Kelapa nomor 12), Indonesia. Gereja ini bernaung dalam GPIB (Gereja Protestan di Indonesia bagian Barat) dengan sistem Presbiterial Sinodal.', -6.20056, 106.831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/GPIB%20Paulus%20Jakarta%20%28November%202026%29%2003.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19325482', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 3),
  (10052, NULL, 7, 'Paroki Maria Ratu Semesta Alam, Sungai Durian', 'Indonesia', NULL, 'Paroki Maria Ratu Semesta Alam Sungai Durian merupakan sebuah paroki dari Gereja Katolik di Keuskupan Sintang yang berpusat di daerah Sungai Durian (Sei Durian) - Kelurahan Kapuas Kanan Hulu, di Kota Sintang - Kalimantan Barat. Paroki Sungai Durian, atau Paroki Sei Durian, merupakan pemekaran dari Paroki Kristus Raja, Katedral Sintang sejak tahun 1979; sama seperti Paroki Katedral Sintang, pusat Paroki Sungai Durian juga terletak di Kota Sintang.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Paroki%20Maria%20Ratu%20Semesta%20Alam.png?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19730342', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10053, NULL, 7, 'Gereja Santa Sesilia, Pontianak Tenggara', 'Bangkabelitung Darat', 'Pontianak Tenggara, Pontianak, Kalimantan Barat', 'Gereja Santa Sesilia adalah sebuah gereja paroki Katolik yang berlokasi di Kompleks Persekolahan Gembala Baik, Kecamatan Pontianak Tenggara, Kota Pontianak, Kalimantan Barat, Indonesia. Kompleks tersebut terletak di perbatasan dengan Kabupaten Kubu Raya. Gereja ini berada di bawah pengelolaan Keuskupan Agung Pontianak.', -0.0704354, 109.3597068, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Luar%20Gereja%20Santa%20Sesilia%20Pontianak%20%282026%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19730350', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10054, NULL, 7, 'Paroki Santa Perawan Maria Yang Terkandung Tanpa Noda, Kelayan', 'Banjarmasin Selatan', 'Banjarmasin Selatan, Banjarmasin, Kalimantan Selatan', 'Gereja Santa Perawan Maria Yang Terkandung Tanpa Noda - Paroki Kelayan merupakan Paroki Gereja Katolik Roma di Keuskupan Banjarmasin; terletak di Kelurahan Kelayan Barat, Kecamatan Banjarmasin Selatan, Kota Banjarmasin, Kalimantan Selatan. Pada 5 November 1939, Mgr. J. Kusters, Prefek Apostolik Banjarmasin memberkati gereja di Kelayan, dan tanggal 11 November 1939 Paroki Kelayan didirikan dengan batas antar kedua Paroki di Banjarmasin (dengan Paroki Katedral Keluarga Kudus) adalah Sungai Martapura.', -3.3317435, 114.5920939, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santa%20Perawan%20Maria%20Yang%20Terkandung%20Tanpa%20Noda%20Banjarmasin%20001.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19730349', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10055, NULL, 7, 'Gereja Trinitas, Cengkareng', 'Cengkareng Barat', 'Jalan Bambu Kuning 9, Cengkareng, Jakarta Barat', 'Gereja Trinitas adalah sebuah gereja paroki Katolik yang berlokasi di Cengkareng Barat, Jakarta Barat, Jakarta. Gereja ini berada di bawah pengelolaan Keuskupan Agung Jakarta. Secara parokial, Gereja ini merupakan Paroki Cengkareng.', -6.1470367, 106.7250578, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Dalam%20Gereja%20Trinitas%202024%20%281%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19730369', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10056, NULL, 7, 'Gereja Santa Maria Ratu, Gumbrih', 'Indonesia', NULL, 'Paroki Santa Maria Ratu Gumbrih adalah sebuah paroki dari Gereja Katolik Roma di Keuskupan Denpasar; berpusat di Desa Gumbrih - Kecamatan Pekutatan, di Kabupaten Jembrana - Bali. Paroki Gumbrih merupakan salah satu paroki perintis di Bali Barat yang dipelopori oleh Pastor Simon Buis SVD, yang dijuluki \'Ida Pedanda Lingsir\' --yaitu orang tua yang penuh wibawa, sekitar tahun 1930-an. Beberapa keluarga Katolik dari Gumbrih merupakan bagian dari eksodus yang dilakukan Pastor Buis pada 15 September 1940, bersama dengan beberapa keluarga dari Paroki Tuka, ke ujung barat Pulau Bali dan membuka desa di tengah hutan yang kini terkenal sebagai Desa Palasari—pusat Paroki Palasari.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katolik%20Santa%20Maria%20Ratu%2C%20Desa%20Gumbrih%2C%20Jembrana.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19745851', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10057, NULL, 7, 'Gereja Keluarga Kudus, Kota Baru', 'Akcaya', 'Jalan Sutan Syahrir, Pontianak Kota, Pontianak, Kalimantan Barat', 'Gereja Keluarga Kudus adalah sebuah gereja paroki Katolik yang berlokasi di Kelurahan Akcaya, Kecamatan Pontianak Selatan, Kota Pontianak, Kalimantan Barat, Indonesia. Gereja ini terletak persis di perbatasan dengan Kecamatan Pontianak Kota. Gereja ini berada di bawah pengelolaan Keuskupan Agung Pontianak.', -0.043183, 109.3243301, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Gereja%20Keluarga%20Kudus%20Kota%20Baru%20%282026%29%2002.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19746055', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10058, NULL, 7, 'Paroki Santo Matius, Kuala Kapuas', 'Kalimantan Tengah', 'Jalan Kapten Pierre Tendean, Selat Hilir, Kapuas, Kalimantan Tengah', 'Paroki Santo Matius Kuala Kapuas adalah paroki dari Gereja Katolik Roma di Keuskupan Palangka Raya. Pusat paroki terletak di tepi Sungai Kapuas di Kelurahan Selat Hilir - Kecamatan Selat, di Kota Kuala Kapuas - Kalimantan Tengah. Paroki Kuala Kapuas sudah menjadi stasi tetap sejak tahun 1952 di bawah Vikariat Apostolik Banjarmasin (saat itu Keuskupan Palangka Raya belum berdiri); pada 26 September 1975 gereja (gedung) baru, yang digunakan saat ini, diberkati dan kemudian menyusul pembangunan pastoran baru pada tahun 1982.', -3.0201893, 114.3855966, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katolik%20Santo%20Matius%20Kuala%20Kapuas.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19746083', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10059, NULL, 7, 'Paroki Maria Bunda Segala Bangsa, Nusa Dua', 'Indonesia', NULL, 'Paroki Maria Bunda Segala Bangsa Nusa Dua merupakan sebuah paroki dari Gereja Katolik Roma di Keuskupan Denpasar; berpusat di Nusa Dua, di Kelurahan Benoa, Kecamatan Kuta Selatan, Kabupaten Badung provinsi Bali. Pada awalnya Paroki Nusa Dua adalah stasi dari Paroki Santo Fransiskus Xaverius, Kuta sejak tahun 1992. Wilayahnya meliputi Kecamatan Kuta Selatan - Kabupaten Badung.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuta%20Bali%20Indonesia%20Catholic-Church-Maria-Bunda-Segala-Bangsa-02.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19746766', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10060, NULL, 7, 'Gereja Gembala Baik, Seng Hie', 'Benuamelayu Laut', 'Pontianak Selatan, Pontianak, Kalimantan Barat', 'Gereja Gembala Baik, Seng Hie adalah sebuah gereja Katolik yang berlokasi di Kota Pontianak, Kalimantan Barat, Indonesia. Gereja ini berada di bawah pengelolaan Keuskupan Agung Pontianak. Secara parokial, Gereja Gembala Baik Seng Hie merupakan pusat dari Paroki Seng Hie.', -0.0279747, 109.3451699, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Perspektif%20Gereja%20Gembala%20Baik%20Seng%20Hie%20%282026%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19747216', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10061, NULL, 7, 'GPM Nolloth', 'Nolloth', 'Nolloth, Maluku Tengah, Maluku', 'Gereja Protestan Maluku Nolloth atau GPM Nolloth ialah sebuah pastori jemaat dari Gereja Protestan Maluku yang melayani dan mengabari injil di negeri/desa Nolloth, Saparua, Maluku Tengah, Indonesia.', -3.4957697, 128.6950658, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Tua%20Nolloth%2001.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483177', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10062, NULL, 7, 'Gereja Bunda Tujuh Kedukaan, Pandu', 'Bandung', 'Jalan Pandu, Cicendo, Kota Bandung, Jawa Barat', 'Paroki Bunda Tujuh Kedukaan adalah sebuah Paroki Gereja Katolik di bawah Keuskupan Bandung. Paroki Bunda Tujuh Kedukaan terletak di Jalan Pandu No. 4, Bandung, sehingga sering disebut juga Paroki Pandu.', -6.9055257, 107.5934125, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Outside%20view%20of%20Pandu%20Church%20in%20Bandung%2C%202024.png?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483950', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10063, NULL, 7, 'Gereja Santa Theresia, Menteng', 'Daerah Khusus Ibukota Jakarta', 'Jalan Gereja Theresia, Jakarta Pusat, Daerah Khusus Ibukota Jakarta', 'Gereja Santa Theresia adalah sebuah gereja paroki Katolik yang berlokasi di Jakarta Pusat, Indonesia. Gereja ini merupakan pusat Paroki Menteng dalam Keuskupan Agung Jakarta. Gereja Santa Theresia dinamai menurut Santa Theresia dari Kanak-kanak Yesus, yang dikenal sebagai salah seorang Pujangga Gereja.', -6.188929, 106.82549, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santa%20Theresia%2C%20Maret%202024.png?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483998', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10064, NULL, 7, 'Gereja Santo Yakobus, Kelapa Gading', 'Jakarta', 'Jalan Pulau Ringgit, Kelapa Gading, Jakarta Utara', 'Gereja Santo Yakobus adalah sebuah gereja paroki Katolik yang berlokasi di Kelapa Gading, Jakarta Utara, Indonesia. Gereja ini merupakan pusat dari Paroki Kelapa Gading dalam pengelolaan Keuskupan Agung Jakarta. Gereja ini dinamai menurut Santo Yakobus, salah seorang dari dua belas rasul Yesus.', -6.15742, 106.8936247, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santo%20Yakobus%20Jakarta%2C%202024.png?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12483999', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10065, NULL, 7, 'Gereja Zebaoth', 'Bogor', 'Jalan Insinyur Haji Djuanda, Bogor Tengah, Bogor, Jawa Barat', 'GPIB Zebaoth Bogor atau Gereja Zebaoth adalah salah satu gereja Protestan yang berada di Kota Bogor, Jawa Barat. Gereja Zebaoth dikenal juga dengan nama "Gereja Ayam" karena di bagian ujung atas gereja terdapat logo ayam. Gereja ini didirikan pada tahun 1920 oleh Gubernur Jenderal Hindia Belanda ke-61, J.P. Graaf van Limburg Stirum.', -6.59832, 106.79438, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zebaoth%20100609-2801%20bo.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12484006', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10066, NULL, 7, 'Paroki Santo Fransiskus dari Asisi, Saribudolok', 'Indonesia', NULL, 'Paroki Santo Fransiskus dari Assisi, Saribudolok adalah paroki di bawah Keuskupan Agung Medan terletak di Saribu Dolok, Silimakuta, Simalungun.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katolik%20Santo%20Pio%20Purba%20Hinalang%20%28Kec.%20Purba%2C%20Simalungun%29%2002.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12503263', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10067, NULL, 7, 'Paroki Santo Yosef, Balige', 'Indonesia', NULL, 'Paroki Santo Yosef, Balige adalah salah satu wilayah administrasi Gereja Katolik Roma di bawah naungan Keuskupan Agung Medan melalui Vikariat Episkopal Dolok Sanggul. Paroki Santo Yosef, Balige meliputi 28 stasi Gereja Katolik yang tersebar di Kabupaten Toba, Sumatera Utara. Gereja induk Paroki Santo Yosef, Balige terletak di desa Pardede Onan, Balige, Toba.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Katolik%20St.%20Yosef%20%28Kec.%20Balige%2C%20Toba%20Samosir%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12503274', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10068, NULL, 7, 'Gereja Santo Yakobus, Klodran', 'Bantul', 'Bantul, Daerah Istimewa Yogyakarta', 'Paroki Santo Yakobus Bantul adalah suatu paroki dari Gereja Katolik Roma yang berada di bawah Keuskupan Agung Semarang. Pusat Paroki terletak di kota Bantul, yang terletak dalam wilayah Provinsi Daerah Istimewa Yogyakarta.', -7.8802639, 110.3365437, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santo%20Yakobus%2C%20Klodran%20%284%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q12503273', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10069, NULL, 7, 'Gereja Huria Kristen Indonesia Protestan', 'Indonesia', NULL, 'Huria Kristen Indonesia Protestan (disingkat HKIP) adalah sebuah kelompok Gereja Kristen Protestan di Indonesia. Sekitar tahun 1992 Gereja HKIP memisahkan diri dari HKI. Sekarang gereja ini berkantor pusat di Jl. Pisang, Gg.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/HKIP%20Pniel%20Pulo%20Siborna.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16181616', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10070, NULL, 7, 'Gereja Santo Andreas Kim Tae-gon', 'Indonesia', 'Jalan Pelangi Raya, Kelapa Gading, Jakarta Utara', 'Gereja Santo Andreas Kim Tae-gon (ditulis juga Gereja Santo Andreas Kim Tae-gŏn) adalah sebuah gereja paroki Katolik yang terletak di Jalan Puspa Gading dalam kawasan Kelapa Gading, Jakarta. Paroki ini merupakan pemekaran dari Paroki Kelapa Gading. Nama Gereja ini berasal dari nama Santo Andreas Kim Tae-gon yang berasal dari Korea Selatan.', -6.173749, 106.9159645, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pintu%20Gerbang%20Gereja%20Santo%20Andreas%20Kim%20Tae-gon%20%282025%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q16187829', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10071, NULL, 7, 'Gereja Stella Maris, Siantan', 'Indonesia', 'Gusti Situt Mahmud, Pontianak Utara, Pontianak, Kalimantan Barat', 'Gereja Stella Maris, Siantan adalah sebuah gereja paroki Katolik yang berlokasi di Kelurahan Siantan Tengah, Kecamatan Pontianak Utara, Kota Pontianak, Kalimantan Barat, Indonesia. Gereja ini berada di bawah pengelolaan Keuskupan Agung Pontianak. Secara parokial, Gereja Stella Maris merupakan pusat Paroki Siantan.', -0.0179443, 109.3454484, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Depan%20Gereja%20Stella%20Maris%20Siantan%20%282026%29%2002.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19747952', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10072, NULL, 7, 'Gereja Santo Lukas, Temindung', 'Samarinda', NULL, 'Paroki Santo Lukas Temindung adalah paroki yang terletak di bagian utara kota Samarinda, berada dalam Keuskupan Agung Samarinda. Merupakan paroki kedua terbesar di kota Samarinda setelah Paroki Katedral Samarinda yang melayani umat di bagian tengah kota Samarinda.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santo%20Lukas%2C%20Temindung.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q19748908', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10073, NULL, 7, 'Gereja Santa Catharina, Taman Mini Indonesia Indah', 'Indonesia', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Gereja Santa Catharina adalah sebuah gereja stasi Katolik yang terletak dalam kawasan Taman Mini Indonesia Indah, Jakarta, Indonesia. Letaknya bersampingan dengan Masjid Pangeran Diponegoro dan Gereja Protestan Haleluya, Gereja Santa Catharina dibangun tahun 1973 dan diresmikan tahun 1975 dengan luas bangunan 1.030 m2 di atas lahan seluas 2.860 m2.\nSecara pastoral, gereja ini termasuk bagian dari reksa parokial Paroki Lubang Buaya dalam wilayah administratif Dekanat Bekasi, Keuskupan Agung Jakarta.', -6.3033713, 106.8928185, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20Santa%20Catharina%20TMII.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25463725', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10074, NULL, 7, 'Gereja Kristen Haleluya', 'Jakarta', 'Jalan Mabes Hankam, Jakarta Timur, Daerah Khusus Ibukota Jakarta', 'Gereja Kristen Protestan Haleluya adalah sebuah gereja Kristen Protestan yang terletak di kawasan Taman Mini Indonesia Indah, Jakarta Timur, DKI Jakarta, Indonesia. Gereja ini terletak di antara bangunan Gereja Katholik Santa Chatarina dan Pura Hindu Dharma serta berhadapan dengan anjungan DKI. Gereja ini dibangun tahun 1973 dan diresmikan tahun 1975. Bangunan utama meliputi ruang pastori, ruang ganti, ruang sound, dan ruang paling besar untuk jemaat.', -6.3034023, 106.8933315, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haleluya%20Protestant%20Church%20-%20TMII%20%282025%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25463730', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10075, NULL, 7, 'Paroki Keluarga Kudus Banteng', 'Sinduharjo', 'Jalan Kaliurang, Ngaglik, Daerah Istimewa Yogyakarta', 'Paroki Keluarga Kudus Banteng merupakan sebuah paroki yang terdapat di Sleman, DI Yogyakarta. Bangunan Gereja Keluarga Kudus Banteng berada dalam satu komplek dengan Wisma Nasaret yang ditinggali para imam MSF (Missionarii a Sacra Familia) dan pemakaman "Sasana Golgota".\nKeunikan paroki ini adalah memiliki bangunan aula utama yang terbuka pada kedua sisinya.', -7.7414937, 110.3910963, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Holy%20Family%20Church%2C%20Banteng%2C%20Indonesia%20%286%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25464375', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10076, NULL, 7, 'Gereja Santa Maria Assumpta, Pakem', 'Pakembinangun', 'Jalan Kaliurang, Pakembinangun, Sleman, Daerah Istimewa Yogyakarta', 'Paroki Santa Maria Assumpta Pakem merupakan Gereja Katolik yang berada di bawah naungan Keuskupan Agung Semarang dan berlokasi di Pakem, Sleman, DI Yogyakarta. Gedung gereja ini dibangun oleh Romo C. Rommens, SJ dengan dukungan umat pada tahun 1956 dan direnovasi pada tahun 2010 serta diberkati pada tanggal 1 Mei 2011 oleh Uskup Agung Semarang pada saat itu, yaitu Mgr. Johannes Pujasumarta.', -7.6675673, 110.4175967, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Mary%20Assumpta%20Pakem%20Church.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25464372', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10077, NULL, 7, 'Gereja Santo Alfonsus Maria de Liguori, Nandan', 'Indonesia', 'Sinduadi, Sleman, Daerah Istimewa Yogyakarta', 'Gereja Santo Alfonsus Maria de Liguori atau Paroki Nandan adalah salah satu paroki yang berada di bawah Keuskupan Agung Semarang. Paroki ini terletak di Sinduadi, Mlati, Sleman, DI Yogyakarta.', -7.7544733, 110.3685317, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Alfonsus%20Nandan%2C%20Yogya%20%281%29.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25464451', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10078, NULL, 7, 'Gereja Huria Kristen Batak Protestan', 'Yogyakarta', NULL, 'Gereja Huria Kristen Batak Protestan Resort Yogyakarta (HKBP Yogyakarta) merupakan sebuah gereja bersejarah di bawah naungan Huria Kristen Batak Protestan Distrik XVIII Jabartengdiy yang berlokasi di Kotabaru, Yogyakarta. Resort ini berdiri pada 7 April 1946, dengan menggunakan bangunan gereja resort HKBP ini menggunakan bangunan kuno gereja Kristen Gereformeerd peninggalan zaman Belanda.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gereja%20HKBP%20Yogyakarta.jpeg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25464453', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10079, NULL, 7, 'Gereja Belanda', 'Indonesia', 'Jalan Kali Besar Timur 5, Taman Sari, Jakarta Barat', 'Gereja Belanda (bahasa Belanda: De Hollandsche Kerk) adalah sebuah gereja tua yang terletak di Heerenstraat (sekarang Jalan Pintu Besar Utara). Gereja yang memiliki nama Kruiskerk ini sudah tiada karena hancur dihantam gempa hebat tahun 1808. Sebagai gantinya, Pemerintah Hindia Belanda menggunakan lahan bekas gereja tersebut untuk dibangunkan sebuah bangunan dengan gaya Neo-Reinaissance yang diperuntukkan sebagai gudang milik perusahaan Geo Wehry & Co.', -6.135, 106.8123, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/De-Kruis-Kerk-op-Batavia-1682.jpg?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25464871', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10080, NULL, 7, 'Gereja Santo Laurentius, Sukajadi', 'Gegerkalong', 'Jalan Sukajadi, Sukasari, Kota Bandung, Jawa Barat', 'Gereja Santo Laurentius adalah sebuah gereja paroki Katolik yang terletak di Kelurahan Gegerkalong, Kota Bandung, Jawa Barat. Gereja ini berada dalam naungan Keuskupan Bandung dan didedikasikan kepada Santo Laurentius. Gereja ini berada dalam reksa pastoral para imam Ordo Salib Suci.', -6.8758311, 107.5960457, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tampak%20Luar%20Gereja%20Santo%20Laurentius%20Bandung%202024%20%282%29.png?width=800', '2026-11-24 09:50:06', '2026-11-24 23:32:50', 'wd:Q25466688', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Gereja', 2),
  (10081, NULL, 7, 'Candi Sukuh', 'Karanganyar', 'Gunung Lawu Via Tahura, Berjo, Karanganyar, Jawa Tengah', 'Candi Sukuh  diperkirakan dibangun pada masa akhir Kerajaan Majapahit, yaitu abad ke-15, pada masa pemerintahan Ratu Suhita (1429–1446). Situs Candi Sukuh pertama kali ditemukan oleh Johnson pada tahun 1815 di bawah masa kepemimpinan Jenderal Raffles. Laporan Johnson mengenai penemuan candi yang terletak di lereng barat Gunung Lawu ini selanjutnya dimuat dalam buku The History of Java karangan Thomas S. Raffles.', -7.6274, 111.13118, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Sukuh%202007.JPG?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q3101506', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 19),
  (10082, NULL, 7, 'Pura Ulun Danu Batur', 'Kintamani', 'Jalan Raya Penelokan, Kintamani, Bali', 'Pura Ulun Danu Batur (juga dikenal sebagai "Pura Batur" atau "Pura Ulun Danu") adalah Pura yang terletak di pulau Bali, Indonesia . Sebagai salah satu Pura Kahyangan Jagat, Pura Ulun Danu Batur adalah salah satu dari pura terpenting di Bali yang bertindak sebagai pemelihara harmoni dan stabilitas seluruh pulau. Pura Ulun Danu Batur mewakili arah Utara dan didedikasikan untuk dewa Wisnu dan dewi lokal Dewi Danu, dewi Danau Batur, danau terbesar di Bali.', -8.2544444, 115.3361111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/PuraUDBaturNewShrinesDetail.JPG?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q2390081', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 16),
  (10083, NULL, 7, 'Candi Gedong Songo', 'Semarang', 'Sumowono, Jawa Tengah', 'Candi Gedong Songo (bahasa Jawa: ꦕꦤ꧀ꦝꦶꦒꦼꦝꦺꦴꦁꦱꦔ, translit. Candhi Gedhong Sanga)  diperkirakan oleh para ahli dibuat semasa dengan Candi Dieng yang dibuat pada kurun waktu abad ke 7 sampai 9 Masehi pada masa Dinasti Sanjaya dari Kerajaan Mataram Lama. Nama Gedongsongo diberikan oleh penduduk setempat yang berasal dari bahasa Jawa, "Gedong" berarti rumah atau bangunan, "Songo" berarti sembilan.', -7.2084722, 110.3418889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gedong%20songo.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q2574009', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 12),
  (10084, NULL, 7, 'Kompleks Candi Dieng', 'Indonesia', 'Dieng Kulon, Banjarnegara, Jawa Tengah', 'Kumpulan candi Hindu beraliran Syiwa ini diperkirakan dibangun antara akhir abad ke-7 sampai abad ke-8 dan terletak di Dataran Tinggi Dieng, Kabupaten Banjarnegara, Jawa Tengah. Merupakan salah satu kompleks candi tertua milik Etnis Jawa. Sampai saat ini belum ditemukan informasi tertulis tentang sejarah Candi Dieng, tetapi para ahli memperkirakan bahwa kumpulan candi ini dibangun atas perintah raja- raja dari Wangsa Sanjaya dari Kerajaan Medang.', -7.2, 109.9, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Complex%20of%20Candi%20Arjuna.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q17002130', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 9),
  (10085, NULL, 7, 'Candi Jago', 'Malang', 'Jalan Raya Tumpang, Tumpang, Jawa Timur', 'Menurut kitab Negarakertagama pupuh 41:4 dan Pararaton, nama Candi Jago sebenarnya berasal dari kata "Jajaghu", yang didirikan pada masa Kerajaan Singhasari pada abad ke-13 sebagai penghormatan bagi Raja ketiga Singhasari, Wisnuwardhana. Jajaghu, yang artinya adalah \'keagungan\', merupakan istilah yang digunakan untuk menyebut tempat suci. Candi ini berlokasi di Dusun Jago, Desa Tumpang, Kecamatan Tumpang, Kabupaten Malang, Jawa Timur atau sekitar 22 km dari Kota Malang, pada koordinat 8°0′20.81″S 112°45′50.82″E. Candi ini berjarak sekitar 25 km dari Pura Bhuvana Kertha.', -8.00579, 112.76405, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Jago%2C%20001%20General%20View%20from%20West%20%2840385409172%29.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q12091291', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 8),
  (10086, NULL, 7, 'Candi Pendem', 'Magelang', 'Jalan Raya Boyolali-Magelang, Krogowanan, Magelang, Jawa Tengah', 'Candi Pendem adalah salah satu jenis candi kategori agama Hindu yang terletak di dusun Candi Pos, Desa Sengi, Kecamatan Dukun, Kabupaten Magelang, provinsi Jawa Tengah, Indonesia.', -7.52569, 110.35196, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pendem%20Temple%2C%202014-06-21.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q129157', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 3),
  (10087, NULL, 7, 'Petirtaan Belahan', 'Gempol', 'Penanggungan via Kunjorowesi, Pasuruan, Jawa Timur', 'Petirtaan Belahan, dikenal juga sebagai Candi Belahan atau Sumber Tetek (Jawa: Sumber Payudara), adalah petirtaan bersejarah yang terletak di sisi timur Gunung Penanggungan, tepatnya di Dusun Belahanjowo, Desa Wonosunyo, Kecamatan Gempol, Kabupaten Pasuruan. Usianya sekitar satu milenium (10 abad), dibangun pada masa Kerajaan Medang periode Jawa Timur awal.\nPemandian ini berbentuk kolam empat persegi yang mendapat pasokan air dari sungai kecil yang berada di sisi selatan Dinding sebelah barat dan selatan mengepras lereng tebing dan dibentuk relung-relung yang diberi jaladwara, tempat air memancur.', -7.607426, 112.6516, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/041%20Fountain%20Figures%2C%20Candi%20Belahan%20%2825543837107%29.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q3517537', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 3),
  (10088, NULL, 7, 'Pura Luhur Ponten', 'Indonesia', 'Probolinggo, Jawa Timur', 'Pura Luhur Poten atau disebut juga Sanggar Agung Poten adalah sebuah pura yang terletak di bawah Gunung Bromo, lokasinya masuk wilayah Desa Ngadisari, Kecamatan Sukapura, Kabupaten Probolinggo. Pura ini adalah tempat persembahyangan umat Hindu Tengger. Pura ini dianggap sebagai satu-satunya bangunan yang dibangun di atas padang pasir Bromo.', -7.9333333, 112.9541667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bromo-s6-14-2a.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q56414767', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 3),
  (10089, NULL, 7, 'Candi Puntadewa', 'Jawa Tengah', 'Jalan Dieng, Dieng Kulon, Banjarnegara, Jawa Tengah', 'Candi Puntadewa adalah salah satu candi Hindu yang terletak dalam Kompleks Candi Arjuna, Dataran Tinggi Dieng, Kabupaten Banjarnegara. Bentuk Candi Puntadewa tidak lebar tetapi meninggi. Pembangunan Candi Puntadewa diperkirakan pada masa penyatuan Wangsa Sanjaya dengan Wangsa Syailendra.', -7.2053802, 109.9069181, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Puntadeva%2C%20Java%201155.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q134738619', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 3),
  (10090, NULL, 7, 'Vihara Dhammasoka Banjarmasin', 'Kalimantan Selatan', 'Gang Vihara, Banjarmasin Tengah, Banjarmasin, Kalimantan Selatan', 'Vihara Dhammasoka merupakan tempat ibadah umat Buddha Theravada terbesar yang ada di Banjarmasin. Vihara ini terletak di kawasan Kampung Pacinan Laut, Kelurahan Gadang, kecamatan Banjarmasin Tengah, Banjarmasin.\nAwal mulanya vihara ini hanyalah kecil saja dan didirikan pada tahun 1960-an dan 1970-an.', -3.3163912, 114.5943278, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vihara%20Dhammasoka.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q19744921', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10091, NULL, 7, 'Vihara Dharmayana Kuta', 'Bali', NULL, 'Vihara Dharmayana Kuta (Kongco Kuta atau Kongco Leng Gwan Kuta) adalah salah satu dari sembilan tempat ibadah Tridharma yang memuja Tan Hu Cin Jin sebagai Shing Bing utama. Klenteng ini terletak dekat dengan Pantai Kuta dan Bandara Internasional Ngurah Rai sehingga berada di lokasi padat lalu lintas. Sebagaimana kebanyakan klenteng lain di Bali, tempat ibadah ini tidak hanya dikunjungi oleh Tionghoa-Indonesia tetapi juga penduduk Bali asli yang beragama Buddha dan Hindu, terutama karena Kongco yang dipuja memiliki hubungan erat dengan Kerajaan Mengwi.', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vihara%20Dharmayana%20Kuta%201.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q25465170', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10092, NULL, 7, 'Kong Fuk Miau', 'Muntok', 'Muntok, Kepulauan Bangka Belitung', 'Kong Fuk Miau (Hanzi: 廣福廟, Romanisasi Hakka: Kóng-fuk-meu/Kóng-fuk-miau, pinyin: Guang Fu Miao）adalah sebuah kelenteng bercorak Taois-Konfusianis yang terletak di Kampung Tanjung, Mentok, Kabupaten Bangka Barat, Kepulauan Bangka Belitung.\nKong Fuk Miau berawal dari sebuah kuil yang didirikan sekitar tahun 1800 oleh gabungan imigran Tionghoa asal Provinsi Guangdong dan Fujian yang kemudian menamai tempat ibadah itu menjadi "Kuil Orang Guangdong dan Fujian". Kuil Kong Fuk Miau dijadikan sebagai bangunan bersejarah yang dilindungi (cagar budaya) Kota Mentok.', -2.0668404, 105.161466, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20Temple%20and%20Mosque.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q31172957', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10093, NULL, 7, 'Pura Ulun Danu Tamblingan', 'Munduk', 'Jalan Munduk, Banjar, Bali', 'Pura Ulun Danu Tamblingan adalah klenteng / kuil di Munduk.', -8.263722, 115.091237, 20000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Ulun%20Danu%20Tamblingan%20SF0001.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q122386929', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10094, NULL, 7, 'Pura Segara Ulun Danu Batur', 'Batur Tengah', 'Kintamani, Bali', 'Pura Segara Ulun Danu Batur adalah klenteng / kuil di Batur Tengah.', -8.269106, 115.386217, 10000, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Segara%20Ulun%20Danu%20Batur%20SF0001.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q124401706', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10095, NULL, 7, 'Pura Pasar Agung Batur', 'Kintamani', 'Jalur Daki Batur, Kintamani, Bali', 'Pura Pasar Agung Batur adalah klenteng / kuil di Kintamani.', -8.245631, 115.378232, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Construction%20of%20Pura%20Pasar%20Agung%20Batur%201.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q124652397', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10096, NULL, 7, 'Pura Blanjong', 'Sanur', 'Jalan Belanjong, Denpasar Selatan, Denpasar, Bali', 'Pura Blanjong adalah klenteng / kuil di Sanur.', -8.705909, 115.25414, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blanjong%20temple%20Bali-03.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q124808061', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 2),
  (10097, NULL, 7, 'Candi Awang Maombiak', 'Siguntur', 'Suikabau, Dharmasraya, Sumatera Barat', 'Candi Awang Maombiak: Candi di Dharmasraya, Siguntur.', -0.9674724, 101.5483947, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Candi%20Awang%20Maombiak%2001.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q134932851', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 1),
  (10098, NULL, 7, 'Pura Mandhara Giri Semeru Agung', 'Lumajang', 'Jalan Raya Karanganom - Senduro, Senduro, Lumajang, Jawa Timur', 'Pura Mandhara Giri Semeru Agung adalah klenteng / kuil di Lumajang.', -8.0908333, 113.0883333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gapura%20Pura%20Madhara%20Giri%20Semeru%20Agung.jpg?width=800', '2026-11-24 09:50:17', '2026-11-24 23:32:50', 'wd:Q102442389', 'wikidata', 'Di luar jam ibadah, pagi atau sore', 'Klenteng / Kuil', 1),
  (10099, NULL, 1, 'Pulau Bali', 'Bali', NULL, 'Pulau Bali adalah salah satu pulau di Indonesia yang berada dalam gugusan Kepulauan Nusa Tenggara. Ibu Kota sekaligus pusat pemerintahan utama Provinsi Bali berada di pulau Bali yaitu Kota Denpasar dengan jumlah penduduk mencapai 670.210 jiwa pada tahun 2024 dengan\nKepadatan penduduk 124 jiwa/km2. Pada 2023 jumlah penduduk pulau Bali adalah 4.275.894 jiwa.', -8.3563889, 115.0719417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pura%20Taman%20Ayun%20terletak%20di%20Mengwi%2C%20Bali.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q4648', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 102),
  (10100, NULL, 1, 'Pulau Lombok', 'Nusa Tenggara Barat', NULL, 'Pulau Lombok (jumlah penduduk pada awal tahun 2025: 4.057.386 jiwa) adalah sebuah pulau di gugusan Kepulauan Nusa Tenggara yang terpisahkan oleh Selat Lombok dari Bali di sebelah barat dan Selat Alas di sebelah timur dari Sumbawa. Pulau ini kurang lebih berbentuk bulat dengan semacam "ekor" di sisi barat daya yang panjangnya kurang lebih 70 km. Luas pulau ini mencapai 4.738,65 km² menempatkannya pada peringkat 108 dari daftar pulau berdasarkan luasnya di dunia.', -8.6312194, 116.3175556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lombok%20Island%20and%20Mount%20Rinjani%20under%20clouds%2C%20Gili%20Islands%2C%20Indonesia.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q7564', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 82),
  (10101, NULL, 1, 'Pulau Flores', 'Nusa Tenggara Timur', NULL, 'Flores adalah sebuah pulau yang berada di wilayah administrasi Provinsi Nusa Tenggara Timur, Indonesia. dan bagian dari gugusan kepulauan Sunda Kecil. Kata Flores berasal dari bahasa Portugis "cabo de flores" yang berarti \'tanjung bunga\'.', -8.715, 121.4955556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bajawa.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q148440', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 80),
  (10102, NULL, 1, 'Pulau Sumbawa', 'Nusa Tenggara Barat', NULL, 'Pulau Sumbawa adalah sebuah pulau yang terletak di provinsi Nusa Tenggara Barat, Indonesia. Pulau ini dibatasi oleh Selat Alas di sebelah barat (memisahkan dengan Pulau Lombok), Selat Sape di sebelah timur (memisahkan dengan Pulau Komodo), Samudra Hindia di sebelah selatan, serta Laut Flores di sebelah utara. Kota terbesarnya adalah Bima, yang berada di bagian timur pulau ini.', -8.8168278, 117.9514778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumbawa%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q186367', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 69),
  (10103, NULL, 1, 'Pulau Sumba', 'Nusa Tenggara Timur', NULL, 'Sumba adalah sebuah pulau di Provinsi Nusa Tenggara Timur, Indonesia. Luas wilayahnya 10.710 km², dan titik tertingginya Gunung Wanggameti (1.225 m). Sumba berbatasan dengan Sumbawa di sebelah barat laut, Flores di timur laut, Timor di timur, dan Australia di selatan dan tenggara.', -9.7283306, 120.0011111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waingapu.JPG?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q206368', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 63),
  (10104, NULL, 1, 'Pulau Bangka', 'Kepulauan Bangka Belitung', NULL, 'Pulau Bangka,Jawi: ڤولو بڠكـ , Belanda: Banka, adalah sebuah pulau yang terletak di sebelah timur Sumatra, Indonesia dan termasuk dalam wilayah Provinsi Kepulauan Bangka Belitung. Populasinya pada 2004 berjumlah 789.809 jiwa. Luas pulau Bangka ialah 11.693.54 km².', -2.25, 106, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Perahu%20Nelayan%20di%20Bangka.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q188428', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 56),
  (10105, NULL, 1, 'Pulau Nias', 'Sumatera Utara', 'Sumatera Utara', 'Pulau Nias (bahasa Nias: Tanö Niha) adalah sebutan untuk pulau dan kepulauan yang terletak di sebelah barat Pulau Sumatra, Indonesia, dan secara administratif berada dalam wilayah Provinsi Sumatera Utara. Pulau ini merupakan pulau terbesar di antara gugusan pulau di pantai barat Sumatra, dihuni oleh suku Nias (Ono Niha). Daerah ini memiliki objek wisata seperti selancar, rumah tradisional, penyelaman, hombo batu (lompat batu).', 1.0679306, 97.6009306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nias%20Indonesien.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q505707', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 56),
  (10106, NULL, 1, 'Pulau Belitung', 'Kepulauan Bangka Belitung', 'Kepulauan Bangka Belitung', 'Pulau Belitung, atau Belitong (bahasa setempat, diambil dari nama sejenis siput laut), dulunya dikenal sebagai Billiton adalah sebuah pulau di lepas pantai timur Sumatra, Indonesia, diapit oleh Selat Gaspar dan Selat Karimata. Pulau ini terkenal dengan lada putih (Piper sp.) yang dalam bahasa setempat disebut sahang, dan bahan tambang tipe galian-C seperti timah putih (Stannuum), pasir kuarsa, tanah liat putih (kaolin), dan granit. Serta akhir-akhir ini menjadi tujuan wisata alam alternatif.', -2.8561111, 107.9163889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tanjung%20Tinggi%20Beach.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q334771', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 47),
  (10107, NULL, 1, 'Pulau Kolepom', 'Merauke', NULL, 'Pulau Kolepom (disebut juga Pulau Dolok atau Pulau Yos Sudarso) adalah sebuah pulau yang termasuk dalam wilayah Kabupaten Merauke, Provinsi Papua Selatan. Pulau ini dipisahkan oleh Selat Muli yang sempit dari pulau utama Nugini. Nama pulau ini berasal dari seorang pahlawan Trikora, Yos Sudarso, dan juga dikenal dengan nama Pulau Kimaam.', -7.895831, 138.364167, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yos%20Sudarso%20NASA%20138.38068E%207.82292S.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q329452', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 45),
  (10108, NULL, 1, 'Pulau Buton', 'Sulawesi Tenggara', 'Sulawesi Tenggara', 'Buton adalah sebuah pulau di Sulawesi Tenggara. Pulau ini dikenal sebagai satu-satunya tempat di Indonesia yang memiliki cebakan aspal alami. Kandungan aspal alam di pulau ini mencapai 663 juta ton.', -5.0138889, 122.8883306, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buton%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1018014', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 40),
  (10109, NULL, 1, 'Pulau Morotai', 'Halmahera Utara', 'Pulau Morotai, Maluku Utara', 'Pulau Morotai adalah sebuah pulau di Kabupaten Pulau Morotai, Maluku Utara, Indonesia. Pada abad ke-15 M, pulau Morotai merupakan bagian dari kekuasaan Kesultanan Ternate. Pulau Morotai memiliki sebuah varietas tanaman domestik yaitu kelapa bido yang telah ditetapkan sebagai varietas unggulan di Indonesia oleh Menteri Pertanian Indonesia pada tahun 2017.', 2.3191667, 128.4666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morotai%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q19146', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 39),
  (10110, NULL, 1, 'Pulau Bintan', 'Bintan', NULL, 'Artikel ini mengenai Pulau Bintan. Lihat pula Kabupaten Bintan.\n\nPulau Bintan adalah pulau di provinsi Kepulauan Riau, di mana terdapat Kota Tanjungpinang, Ibu kota Provinsi Kepulauan Riau.', 1.083331, 104.490831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sumpat%2C%20Bintan.JPG?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q774859', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 39),
  (10111, NULL, 1, 'Pulau Siberut', 'Kepulauan Mentawai', 'Sumatera Barat', 'Siberut adalah pulau terbesar dan paling utara dari Kepulauan Mentawai, terletak 150 kilometer sebelah barat Sumatra di Samudra Hindia. Sebagai bagian dari Indonesia, pulau ini menjadi rumah terpenting bagi Suku Mentawai. Paro barat pulau ini telah ditetapkan menjadi Taman Nasional Siberut pada 1993.', -1.340556, 98.916389, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Siberut%20island%20river.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q826041', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 39),
  (10112, NULL, 1, 'Pulau Rote', 'Kupang', NULL, 'Pulau Rote, juga disebut Pulau Roti (ڤولاو روتي), adalah sebuah pulau dalam kepulauan Rote di Provinsi Nusa Tenggara Timur, Indonesia. Kepulauan Rote merupakan wilayah paling selatan Indonesia. Pulau ini terkenal dengan kekhasan budidaya lontar, wisata alam pantai, alat musik sasando, topi adat Ti’i Langga, daging se\'i, jagung bose, gula hela, susu goreng, serta lagu Bolelebo juga berasal dari daerah ini.', -10.743611, 123.118331, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rote%20%28Island%29%20123.05527E%2010.71620S.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q686196', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 38),
  (10113, NULL, 1, 'Pulau Wetar', 'Maluku Barat Daya', 'Maluku Barat Daya, Maluku', 'Pulau Wetar adalah pulau terluar Indonesia yang terletak di Laut Banda dan berbatasan dengan Timor Leste. Secara administratif, pulau Wetar bagian dari wilayah pemerintah Kabupaten Maluku Barat Daya,  Provinsi Maluku. Pulau ini berada di sebelah utara dari Timor Leste dengan koordinat 7° 56′ 50″ LS, 126° 28′ 10″ BT. Pulau Wetar termasuk dalam kawasan biogeografi Wallacea \nDi tengah pulau terdapat sebuah danau yang bernama Danau Tihu, sebenarnya ada potensi wisata yang bisa dikembangkan di pulau tersebut.', -7.805278, 126.266111, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barat%20Daya%20Islands%20en.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q615657', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 37),
  (10114, NULL, 1, 'Pulau Yapen', 'Papua', NULL, 'Pulau Yapen yang sekaligus Kabupaten Kepulauan Yapen adalah salah satu pulau di wilayah Kabupaten Kepulauan Yapen provinsi Papua, Indonesia. Pulau ini terletak di selatan Pulau Biak dan di utara Kabupaten Waropen.', -1.757219, 136.156942, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schouten%20Islands%20%28IN%29%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1323436', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 36),
  (10115, NULL, 1, 'Pulau Biak', 'Biak Numfor', 'Biak Numfor, Papua', 'Biak adalah pulau utama di Kepulauan Biak yang terletak di Teluk Cenderawasih dekat pantai utara Papua, sebuah provinsi di Indonesia, dan berada tepat di sebelah barat laut Pulau Papua. Biak memiliki banyak atol, terumbu karang, dan koral. Dalam literatur lama, pulau ini juga disebut Pulau Mysore.', -0.945033, 135.936142, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schouten%20Islands%20%28IN%29%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q855314', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 35),
  (10116, NULL, 1, 'Pulau Alor', 'Alor', 'Alor, Nusa Tenggara Timur', 'Alor adalah sebuah pulau yang terletak di ujung timur Kepulauan Nusa Tenggara. Luas wilayahnya 2.119 km², dan titik tertingginya 1.839 m. Pulau ini dibatasi oleh Laut Flores dan Laut Banda di sebelah utara, Selat Ombai di selatan (memisahkan dengan Pulau Timor), serta Selat Pantar di barat (memisahkan dengan Pulau Pantar.', -8.276667, 124.739442, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/10-103b%20Alor%20subdistricts%20relief%20colour.tif?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1130641', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 35),
  (10117, NULL, 1, 'Pulau Waigeo', 'Raja Ampat', NULL, 'Pulau Waigeo adalah pulau yang berada di Papua Barat Daya di bagian timur Indonesia. Pulau ini dikenal juga dengan nama Amberi atau Waigiu. Pulau Waigeo adalah pulau terbesar dari empat pulau utama dari Kepulauan Raja Ampat.', -0.171617, 130.953731, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waigeo%20view-2.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1323418', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 35),
  (10118, NULL, 1, 'Pulau Simeulue', 'Simeulue', NULL, 'Pulau Simeulue atau Simalur merupakan pulau yang berada di barat Sumatra. Berada kurang lebih 150 km dari lepas pantai barat Aceh, juga merupakan pulau pemerintahan Kabupaten Simeulue di tengah Samudra Hindia. Posisi geografisnya terisolasi dari daratan utama, hiruk-pikuk konflik di Aceh daratan tidak pernah berimbas di kawasan ini, bahkan tidak ada pergerakan GAM di kawasan kepulauan ini.', 2.611667, 96.095831, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Busung-Gusong%20Bay-Simeulue-Indonesia-8-Apr-2005.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q3809449', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 34),
  (10119, NULL, 1, 'Pulau Misool', 'Raja Ampat', NULL, 'Pulau Misool adalah salah satu dari empat pulau besar di Kepulauan Raja Ampat di Papua Barat Daya, Indonesia. Luas wilayahnya 2.034 km². Titik tertinggi adalah 535 m dan kota utama adalah Waigama dan memiliki kordinat 1 ° 53\'41 "S 130 ° 5\'1" E. Pulau Misool berada di distrik Misool, Kabupaten Raja Ampat, provinsi Papua Barat Daya.', -1.8695139, 130.1380889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fafanlap%20Village.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1326456', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 32),
  (10120, NULL, 1, 'Pulau Muna', 'Sulawesi Tenggara', 'Muna, Sulawesi Tenggara', 'Pulau Muna adalah sebuah pulau yang terletak di jazirah ujung pulau Sulawesi bagian Tenggara Sulawesi Tenggara dengan luas ±100.000 km2. Pulau ini terletak pada selatan garis khatulistiwa pada garis lintang 4º06 - 5.15° LS dan garis Bujur 120.00° – 123.24° BT. Daratan pulau umumnya merupakan dataran rendah dengan ketinggian rata-rata kurang dari 100 meter di atas permukaan laut.\n\nPulau Muna pada umumnya beriklim tropis dengan suhu rata-rata antara 25°C–27°C. Musim hujan terjadi antara bulan Nopember dan mulai Maret, di mana pada bulan tersebut angin bertiup dari Benua Asia dan Samudera Pasifik mengandung banyak uap air yang menyebabkan terjadinya hujan di wilayah Indonesia, sedangkan musim kemarau terjadi antara bulan Mei dan bulan Oktober, pada bulan ini angin bertiup dari Benua Australia yang sifatnya kering dan sedikit mengandung uap air.', -4.9902778, 122.5219417, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buton%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q428076', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 30),
  (10121, NULL, 1, 'Pulau Salawati', 'Papua Barat', 'Raja Ampat, Papua Barat Daya', 'Salawati adalah salah satu dari empat pulau utama di Kepulauan Raja Ampat di Provinsi Papua Barat Daya, Indonesia. Pulau ini memiliki luas 1.623 km². Pulau-pulau utama lain dari kepulauan Raja Ampat adalah Misool, Batanta, dan Waigeo.', -1.0966583, 130.9022472, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salawati%20Island%2C%20ID.%20Sentinel-2.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q975927', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 30),
  (10122, NULL, 1, 'Pulau Yamdena', 'Kepulauan Tanimbar', NULL, 'Yamdena adalah pulau terbesar di Kepulauan Tanimbar, Indonesia. Bahasa Yamdena dipertuturkan di pulau ini. Di pesisir timur pulau ini terdapat berbagai bukit berhutan lebat.', -7.507778, 131.493331, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20Yamdena.PNG?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q431318', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 29);
INSERT INTO destinations (`id`, `owner_id`, `category_id`, `name`, `location`, `address`, `description`, `latitude`, `longitude`, `price`, `open_hours`, `cover_image`, `created_at`, `updated_at`, `external_id`, `source`, `best_time`, `highlights`, `popularity`) VALUES
  (10123, NULL, 1, 'Pulau Lembata', 'Lembata', 'Lembata, Nusa Tenggara Timur', 'Lomblen, kadang juga disebut Kawela atau Lembata, adalah sebuah pulau yang terletak di Kepulauan Nusa Tenggara, yakni di antara Pulau Adonara dengan Pulau Pantar. Pulau ini dibatasi oleh Laut Flores di utara, Selat Alor di barat, Laut Sawu di selatan, serta Selat Lamakera di barat.\nSecara astronomis Lomblen terletak pada posisi 8°10\' - 8°11\' LS dan 123°12\' - 123°57\' BT. Pulau Lomblen merupakan pulau utama yang membentuk Kabupaten Lembata, Provinsi Nusa Tenggara Timur, Indonesia.', -8.4047194, 123.5347194, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lembata%20island%2C%20Indonesia.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q771493', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 27),
  (10124, NULL, 1, 'Pulau Obimayor', 'Halmahera Selatan', NULL, 'Pulau Obi atau bisa disebut juga Pulau Obira, merupakan pulau terbesar yang terletak di gugusan Kepulauan Obi. Pulau Obi dikelilingi oleh banyak pulau-pulau kecil, di antaranya Pulau Obilatu, Pulau Bisa, Pulau Gata-gata, Pulau Latu, Pulau Woka, dan Pulau Tomini.\nPulau Obi dibatasi oleh Laut Maluku di sebelah barat, Laut Seram di sebelah selatan, dan Selat Obi di sebelah utara dan di sebelah Timur.', -1.5338889, 127.7791667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obi%20Islands%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q2774516', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 26),
  (10125, NULL, 1, 'Pulau Peling', 'Banggai Kepulauan', NULL, 'Pulau Peleng adalah salah satu pulau di wilayah Kabupaten Banggai Kepulauan, provinsi Sulawesi Tengah, Indonesia. Pulau ini terletak di utara pulau Bangkurung dan Banggai. Di pulau ini terdapat hewan khas, seperti Kuskus Beruang, Kuskus Banggai, dan Tarsius pulau peleng.', -1.5808306, 123.1727778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banggai%20Islands%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1578714', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 25),
  (10126, NULL, 1, 'Pulau Mangoli', 'Kepulauan Sula', NULL, 'Templat:Infobox pulau\nPulau Mangole (dikenal luas oleh masyarakat setempat sebagai Pulau Mangoli) adalah sebuah pulau utama yang terletak di gugusan Kepulauan Sula, Provinsi Maluku Utara, Indonesia. Dengan luas daratan mencapai sekitar 1.228,5 kilometer persegi dan membentang sepanjang 110 kilometer dari barat ke timur, Pulau Mangole merupakan pulau terluas di wilayah Kabupaten Kepulauan Sula, melampaui luas daratan tetangganya di sebelah selatan, Pulau Sulabesi.', -1.8583306, 125.7666667, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sula%20Islands%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1529054', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 23),
  (10127, NULL, 1, 'Pulau Bacan', 'Halmahera Selatan', 'Halmahera Selatan, Maluku Utara', 'Pulau Bacan adalah sebuah pulau yang terdapat di Kepulauan Maluku tepatnya di sebelah barat daya Pulau Halmahera, Indonesia. Secara administratif Pulau Bacan masuk ke dalam wilayah Kabupaten Halmahera Selatan, provinsi Maluku Utara mencakup 7 kecamatan di kabupaten tersebut. Di pulau Bacan inilah, Labuha, ibu kota Kabupaten Halmahera Selatan berada.', -0.5980556, 127.5302778, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/ID%20Bacan.PNG?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q13405341', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 20),
  (10128, NULL, 1, 'Pulau Bunguran', 'Natuna', NULL, 'Pulau Bunguran atau Pulau Natuna Besar (terkadang juga hanya disebut sebagai Pulau Natuna saja) atau Pulau Bunguran Besar adalah sebuah pulau yang merupakan pulau terbesar dan pulau utama di Kepulauan Natuna, Indonesia. Pulau ini secara administratif terletak di Kabupaten Natuna, Provinsi Kepulauan Riau. Pusat pemerintahan Kabupaten Natuna di Ranai terletak di bagian timur pulau ini.', 3.911389, 108.2425, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Ranai%20in%20Natuna.jpg?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q267725', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 19),
  (10129, NULL, 1, 'Pulau Terangan', 'Kepulauan Aru', NULL, 'Pulau Trangan atau Terangan adalah sebuah pulau di Indonesia. Pulau ini terletak di provinsi Maluku. Adapun wilayahnya masuk ke dalam wilayah kabupaten Kepulauan Aru.', -6.5825, 134.2938889, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluku%20Islands%20en.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q2573656', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 18),
  (10130, NULL, 1, 'Pulau Wokam', 'Kepulauan Aru', 'Kepulauan Aru, Maluku', 'Pulau Wokam adalah sebuah pulau di Indonesia. Pulau ini terletak di provinsi Maluku. Pulau ini masuk ke dalam wilayah kabupaten Kepulauan Aru.', -5.8196778, 134.4945694, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluku%20Islands%20en.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q517126', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 17),
  (10131, NULL, 1, 'Pulau Banggai', 'Banggai Kepulauan', 'Malino Padas, Banggai Laut, Sulawesi Tengah', 'Pulau Banggai adalah salah satu pulau di wilayah Kabupaten Banggai Laut, provinsi Sulawesi Tengah, Indonesia. Pulau ini terletak di tenggara Pulau Peleng, di utara pulat Salue Besar dan di timur laut pulau Labobo.\nPulau Banggai secara administratif terletak di Kabupaten Banggai Laut, Sulawesi Tengah.', -1.6172194, 123.5480556, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banggai%20Islands%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q1075618', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 15),
  (10132, NULL, 1, 'Pulau Taliabu', 'Kepulauan Sula', 'Pulau Taliabu, Maluku Utara', 'Pulau Taliabu adalah sebuah pulau di Provinsi Maluku Utara. Pulau ini merupakan pulau utama di Kabupaten Pulau Taliabu yang dimekarkan dari Kabupaten Kepulauan Sula pada tahun 2012.', -1.8333333, 124.8333333, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sula%20Islands%20Topography.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q27868248', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 12),
  (10133, NULL, 1, 'Pulau Bangka', 'Minahasa Utara', 'Ehe, Sulawesi Utara', 'Pulau Bangka adalah sebuah pulau kecil yang terletak tepat di ujung timur laut Sulawesi, Indonesia. Pulau Bangka dikenal dengan pantai indah yang belum terjamah serta wisata menyelam nan eksotik. Pulau Bangka termasuk dalam wilayah administrasi kecamatan Likupang Timur, Kabupaten Minahasa Utara, Provinsi Sulawesi Utara.', 1.792967, 125.150419, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/BangkaIsland%20Sulawesi%20S2%202022.png?width=800', '2026-11-24 10:07:00', '2026-11-24 23:32:50', 'wd:Q18356444', 'wikidata', 'Apr–Okt (musim kemarau), pagi atau sore', 'Pulau', 8);
